// The on-disk format is little-endian; the bulk Float64 copy reads platform order.
const PLATFORM_LITTLE_ENDIAN = new Uint8Array(new Uint32Array([1]).buffer)[0] === 1;
const vectorTextDecoder = new TextDecoder("utf-8", { fatal: true });
const SQL_DOMAIN_PREFIX_BYTES = new TextEncoder().encode("\u0000minnow-domain:");
const NULL_STRING_VECTOR_CODE = 0xffffffff;
/** Unspellable SQL identifier used as the scalar locator for a declared composite primary key. */
const COMPOSITE_KEY_COLUMN_NAME = "\u0000minnow_primary_key";
const ENUM_TYPE_PREFIX = "\u0000minnow_enum_type:";
const SEQUENCE_PREFIX = "\u0000minnow_sequence:";
/**
 * Candidate rows the point-read fast path will verify per statement before conceding that the
 * shape is not selective enough and handing the scan back to the vectorized executor.
 */
const MAX_POINT_READ_CANDIDATES = 1_024;
/** A keyed replay decoding more blocks than this leaves the read to the ordinary path. */
const MAX_POINT_READ_DELTA_BLOCKS = 256;
/** Delta-chunk tail length past which a search schedules a fold-by-rebuild of the base. */
const FTS_FOLD_DELTA_CHUNKS = 16;
/** Candidate lists wider than this scan their blocks instead of probing for exact rows. */
const SECONDARY_INDEX_ROW_SELECTION_CAP = 4096;
/** Candidate results at most this wide are pooled across snapshots by (column, version, terms). */
const MAX_POOLED_FTS_CANDIDATE_ROW_IDS = 65_536;
/** Persistent rebuild failure cannot let an accelerator append one durable delta per commit. */
const FTS_HARD_DELTA_CHUNKS = 64;
const DEFAULT_COMPACTION_TARGET_BLOCK_BYTES = 2 * 1024 * 1024;
/**
 * Ordinary writes use the same physical target as compaction. Row count remains an upper bound,
 * while this byte target keeps wide string columns from turning one nominal row group into a
 * tens-of-megabytes allocation. A single row may exceed the target, but never the format's hard
 * physical-column limit.
 */
const DEFAULT_WRITE_TARGET_BLOCK_BYTES = DEFAULT_COMPACTION_TARGET_BLOCK_BYTES;
const DEFAULT_COMPACTION_MEMORY_BUDGET_BYTES = 32 * 1024 * 1024;
const DEFAULT_COMPACTION_MINIMUM_LEVEL_ZERO_SEGMENTS = 2;
const DEFAULT_COMPACTION_MAXIMUM_LEVEL_ZERO_SEGMENTS = 64;
const DEFAULT_COMPACTION_MAXIMUM_LEVEL_ZERO_STORED_BYTES = 64 * 1024 * 1024;
/**
 * Rows a keyed fold aims to keep in one level-one partition. A fold rewrites only the
 * partitions its deltas touch, so this bounds how much one touched key costs to absorb; the
 * table's partition count, and with it the per-query block count, grows as rows divided by it.
 */
const DEFAULT_COMPACTION_PARTITION_ROWS = 16_384;
const DEFAULT_LEVEL_TWO_MAX_WRITE_AMPLIFICATION = 16;
const MAX_COMPACTION_TARGET_BLOCK_BYTES = 64 * 1024 * 1024;
const MAX_BLOCK_ENVELOPE_BYTES = 1024;
const INTERNAL_READ_LEASE_TTL_MS = 60_000;
/** Live proof windows kept resident; a sweep uses one, concurrent sets a few. */
const LIVE_PROOF_CONTEXT_LIMIT = 4;
/** Distinct table-name sets whose catalog state stays resident; entries are tiny (records only). */
const CATALOG_STATE_CACHE_LIMIT = 64;
/** Blocks fetched per round trip when a streamed scan window needs more data. */
const STREAMED_SCAN_LOOKAHEAD_BLOCKS = 8;
/** Visible segments per table at which a scan or a commit schedules a compaction step. */
const AUTO_COMPACT_SCAN_SEGMENTS = 48;
/** Visible delete/update segments at which a scan or a commit schedules a compaction step. */
const AUTO_COMPACT_DELTA_SEGMENTS = 32;
/** Commits to one table between auto-compaction checks on the write path. */
const AUTO_COMPACT_COMMIT_CHECK_INTERVAL = 8;
/** Quiet time after a write burst before checking its final, sub-interval tail. */
const AUTO_COMPACT_IDLE_CHECK_MS = 25;
/** Commits between background collection passes; each prunes the manifests they wrote. */
const AUTO_COLLECT_COMMIT_INTERVAL = 64;
/**
 * Manifest versions background collection leaves readable behind the current one, and how
 * old one may be before it is collected regardless. A version is kept only while both hold: the
 * count serves a reader that names a version it was just handed, the age keeps a burst of
 * commits from pinning everything it superseded until the next burst — an idle tab reclaims
 * within a minute.
 */
const AUTO_COLLECT_RETAINED_VERSIONS = 64;
const AUTO_COLLECT_RETAINED_VERSION_MS = 60_000;
/** A commit this long after the last collection pass starts one, whatever the commit count. */
const AUTO_COLLECT_QUIET_MS = 60_000;
/** Candidates one background collection step examines before yielding to the event loop. */
const AUTO_COLLECT_STEP_ITEMS = 64;
/** Passes one background collection run makes before handing the rest to the next trigger. */
const AUTO_COLLECT_MAX_PASSES = 32;
/** Durable discovery pages one public collection step may advance before yielding. */
const GARBAGE_COLLECTION_DISCOVERY_PAGES_PER_STEP = 5;
/** Persisted compaction records inspected by one quiet maintenance run. */
const AUTO_COMPACTION_RECONCILE_RECORDS = 8;
/** Finished job records of each kind a background run leaves for inspection. */
const AUTO_COLLECT_RETAINED_JOB_RECORDS = 8;
const MAINTENANCE_JOB_PAGE_SIZE = 64;
const CATALOG_SEGMENT_READ_CONCURRENCY = 8;
/** Nested SQL savepoints and their total cloned transaction state are both hard bounded. */
export const MAX_TRANSACTION_SAVEPOINTS = 64;
export const MAX_TRANSACTION_SAVEPOINT_BYTES = 8 * 1024 * 1024;
/** Outstanding simple writes retained by one database instance before callers must await. */
export const MAX_DATABASE_PENDING_WRITES = 64;
/** Concurrent direct reads retained by one database instance. Reads still execute in parallel. */
export const MAX_DATABASE_ACTIVE_READS = 256;
/** Commits tolerated while collection fails before foreground writes assist and backpressure. */
const AUTO_COLLECT_MAX_DEBT_COMMITS = 4_096;
/** Failed background passes retry without another write, with bounded exponential backoff. */
const AUTO_COLLECT_RETRY_MIN_MS = 1_000;
const AUTO_COLLECT_RETRY_MAX_MS = 60_000;
/** Output blocks one background compaction step writes before yielding to the event loop. */
const AUTO_COMPACT_STEP_BLOCKS = 4;
/**
 * Level-zero segments one background fold may absorb. A fold rewrites every partition its
 * deltas touch, and a partition touched by several deltas is rewritten once, so absorbing
 * everything pending in one pass costs one rewrite of those partitions where the default would
 * cost several; the stored-bytes ceiling still bounds the pass.
 */
const AUTO_COMPACT_MAX_LEVEL_ZERO_SEGMENTS = 256;
/**
 * Level-zero segments past which a write drives one fold step before its own commit. The
 * background fold takes one bounded step per commit under a writer that never pauses, so a
 * writer whose every statement adds a segment outruns any fold that costs more steps than the
 * segments it retires. Past two folds' worth of backlog the writer lends the fold its own turn:
 * a statement is delayed by one step, where the absolute ceiling would refuse it.
 */
const AUTO_COMPACT_BACKPRESSURE_LEVEL_ZERO_SEGMENTS = 2 * AUTO_COMPACT_MAX_LEVEL_ZERO_SEGMENTS;
/** A failed background fold waits this long before the next attempt, doubling per failure. */
const AUTO_COMPACT_RETRY_MIN_MS = 250;
const AUTO_COMPACT_RETRY_MAX_MS = 60_000;
/** Manifest races a complete fold may lose to writers already in flight before it is abandoned. */
const MAX_COMPACTION_PUBLICATION_CONFLICTS = 64;

/** Why a table's next background fold waits: a segment count it must reach, and a timer. */
interface AutoCompactionBackoff {
  readonly minimumSegments: number;
  readonly failures: number;
  /** Set while the time part of the backoff is still running; its firing re-checks the table. */
  readonly retryTimer: ReturnType<typeof setTimeout> | undefined;
}
/** Modeled retained bytes for one cached block description (header metadata, no payload). */
const ZONE_DESCRIPTION_CACHE_BYTES = 160;

/** Overlay logical order for a write scope's staged segments: after all committed data. */
const STAGED_OVERLAY_ORDER_BASE = 2 ** 52;

/**
 * Internal restart signal: a commit conflict invalidated staged trigger derivations — their
 * bodies and OLD/NEW images were read at the superseded snapshot, so a rebase would republish
 * stale values. The statement re-runs whole instead, re-reading everything fresh.
 */
class StaleTriggerDerivationsError extends Error {
  constructor(readonly conflict: WriteConflictError) {
    super("Trigger derivations were computed at a superseded snapshot");
  }
}
/** Distinct SQL statements whose optimized plans stay cached; plans are a few KB each. */
const PLAN_CACHE_LIMIT = 512;

/**
 * Below this ratio, gzip is not paying for itself: it costs the write a full compression pass
 * and every read a decompression pass, to save almost nothing. Measured on 129,000-row blocks,
 * the shapes worth compressing land far above it — the weakest, random UUID text, still reaches
 * 1.8x — while a column of unstructured doubles reaches 1.07x for 16ms a block.
 */
const GZIP_WORTHWHILE_RATIO = 1.2;

/**
 * How many blocks a column may be written raw before gzip is tried again. A column's shape is
 * usually stable across its blocks, which is what makes one observation worth reusing; this
 * bounds how long a wrong observation can persist if the data changes underneath it.
 */
const GZIP_REPROBE_BLOCKS = 32;
/** Failed per-column probes retained in one database session. */
const GZIP_VERDICT_CACHE_LIMIT = 256;

/**
 * Below this many logical bytes a block is written raw: the compression pass on the write and
 * the decompression pass on every read would cost more than the bytes they save, and a point
 * update's or delete's one-row block is the common case — it used to pay a CompressionStream
 * round trip to shrink a few dozen bytes.
 */
const GZIP_MINIMUM_INPUT_BYTES = 4 * 1024;
/** Bounds concurrent compression work without serializing independent column blocks. */
const WRITE_ENCODE_CONCURRENCY = 6;
/** Posting rows accumulated by an index builder before one bounded sorted flush. */
const FTS_BUILD_POSTING_WINDOW = 16_384;

/**
 * Holds at most one storage-sized block batch. Before encoding the next block, callers provide
 * its conservative stored-size bound; if it would cross the batch limit the existing bytes are
 * durably staged first. Staged blocks remain invisible until the segment and transaction commit,
 * and an exception later in validation or a trigger aborts the journal normally.
 */
class BoundedWriteBlockStager {
  readonly #pending: BlockWrite[] = [];
  #pendingBytes = 0;
  #earlyStageMs = 0;

  constructor(private readonly transaction: DatabaseTransaction) {}

  get earlyStageMs(): number {
    return this.#earlyStageMs;
  }

  async prepare(maximumNextBytes: number): Promise<void> {
    await this.prepareBatch(1, maximumNextBytes);
  }

  async prepareBatch(nextBlockCount: number, maximumNextBytes: number): Promise<void> {
    if (
      this.#pending.length > 0 &&
      (this.#pending.length + nextBlockCount > MAX_TRANSACTION_STAGE_BLOCKS ||
        this.#pendingBytes + maximumNextBytes > MAX_TRANSACTION_STAGE_BYTES)
    ) {
      await this.#flush();
    }
  }

  add(block: BlockWrite): void {
    if (
      this.#pending.length >= MAX_TRANSACTION_STAGE_BLOCKS ||
      this.#pendingBytes + block.bytes.byteLength > MAX_TRANSACTION_STAGE_BYTES
    ) {
      throw new Error("Write block accumulator crossed its prepared storage bound");
    }
    this.#pending.push(block);
    this.#pendingBytes += block.bytes.byteLength;
  }

  pendingBlocks(): readonly BlockWrite[] {
    return this.#pending;
  }

  async stageWithSegments(segments: readonly SegmentRecord[]): Promise<void> {
    await this.transaction.stageArtifacts(this.#pending, segments);
    this.#pending.length = 0;
    this.#pendingBytes = 0;
  }

  async #flush(): Promise<void> {
    const started = performance.now();
    await this.transaction.stageBlocks(this.#pending);
    this.#earlyStageMs += performance.now() - started;
    this.#pending.length = 0;
    this.#pendingBytes = 0;
  }
}

type PhysicalCompactionRewritePlan = RechunkCompactionRewritePlan | MergeCompactionRewritePlan;

interface PhysicalCompactionSourceRange {
  readonly blockId: string;
  readonly outputRowStart: number;
  readonly sourceRowStart: number;
  readonly rowCount: number;
  readonly sourceBlockRowCount: number;
  readonly storedBytes: number;
  readonly encodedBytes: number;
  readonly checksum: number;
}

interface PhysicalCompactionSourceColumn {
  readonly columnId: string;
  readonly type: SimpleDataType;
  readonly sourceRanges: readonly PhysicalCompactionSourceRange[];
}

/** What a grouped compaction read needs of a source block: its ID and the plan's two sizes. */
interface CompactionSourceBlockRef {
  readonly blockId: string;
  readonly storedBytes: number;
  readonly encodedBytes: number;
}

interface PhysicalCompactionLayout {
  readonly targetBlockBytes: number;
  readonly outputCompression: Compression;
  readonly totalRows: number;
  readonly columns: readonly PhysicalCompactionSourceColumn[];
  readonly outputs: readonly RechunkCompactionOutputWindow[];
}

interface MergeResolvedSource {
  readonly blockId: string;
  readonly sourceRowIndex: number;
}

/** A table's part of a live proof window: see `#liveProofContext`. */
interface LiveProofTable {
  readonly table: TableRecord;
  /** Segments whose transaction committed inside the window, in store order. */
  readonly windowSegments: readonly SegmentRecord[];
  /** The committed versions those segments account for. */
  readonly coveredVersions: ReadonlySet<number>;
}

/** What every live proof over one commit window shares: see `#liveProofContext`. */
interface LiveProofContext {
  readonly after: number | null;
  readonly until: number;
  /** Versions in (after, until] that recorded a change to each table. */
  readonly changedVersions: ReadonlyMap<string, ReadonlySet<number>>;
  readonly tables: Map<string, Promise<LiveProofTable | undefined>>;
}

interface SegmentVisibilityCatalog {
  readonly transactions: ReadonlyMap<string, { readonly committedVersion: number | null }>;
  readonly segmentsByTable: ReadonlyMap<string, readonly SegmentRecord[]>;
  /** One staged writer exposed as a synthetic post-snapshot commit inside a transaction scope. */
  readonly overlayTransactionId?: string;
}

/** Exact current-layout counters retained between local commits for cheap maintenance checks. */
interface AutoCompactionHint {
  readonly version: number | null;
  readonly visible: number;
  readonly levelZero: number;
  readonly deltas: number;
}

interface ZonePredicate {
  readonly column: TableColumnRecord;
  readonly operator: ComparisonOperator | "IN";
  /** The compared literal; for IN, the smallest list member. */
  readonly value: number;
  /** IN only: every distinct member, ascending, so a block test is one binary search. */
  readonly members?: Float64Array;
}

interface SecondaryIndexPredicate {
  readonly columns: readonly TableColumnRecord[];
  readonly indexId: string;
  readonly index: SecondaryIndexRecord;
  /** Exact members for equality/IN, or one lexicographic range. */
  readonly queries: readonly FtsPostingQuery[];
  /** IN unions its aligned posting lists; a comparison reads the only list. */
  readonly union: boolean;
}

interface SelectedAppendSegment {
  readonly segment: SegmentRecord;
  readonly blockIndexes: readonly number[];
  readonly rowCounts: readonly number[];
}

export interface ColumnDefinition {
  name: string;
  type: SimpleDataType;
  /** SQL integer-domain guard; ordinary API number columns remain finite Float64 values. */
  integer?: true;
  /** PostgreSQL logical domain over the primitive storage type. */
  sqlDomain?: SqlDomain;
  nullable?: boolean;
  /** Fills omitted or SQL DEFAULT slots at insert time; never applied at read time. */
  defaultValue?: ColumnDefault;
  /** Stored expression over sibling columns; callers cannot assign this column. */
  generatedValue?: ColumnGenerated;
  /** String columns only: the closed set of values writes must draw from. */
  enumValues?: readonly string[];
  /** What rows written before this column existed read as, instead of NULL. */
  backfill?: boolean | number | string | Date;
}

function normalizedColumnBackfill(
  column: Pick<ColumnDefinition, "name" | "type" | "integer" | "sqlDomain" | "enumValues">,
  value: boolean | number | string | Date,
): boolean | number | string | Date {
  if (column.sqlDomain !== undefined) {
    const normalized = normalizeSqlDomainValue(column.sqlDomain, value);
    if (normalized === null) throw new TypeError(`Backfill cannot be NULL: ${column.name}`);
    return normalized;
  }
  const valid =
    column.type === "datetime"
      ? value instanceof Date && Number.isFinite(dateMilliseconds(value))
      : column.type === "number"
        ? typeof value === "number" &&
          Number.isFinite(value) &&
          (column.integer !== true || Number.isSafeInteger(value))
        : typeof value === column.type;
  if (!valid) throw new TypeError(`Backfill does not fit column: ${column.name}`);
  if (
    column.enumValues !== undefined &&
    typeof value === "string" &&
    !column.enumValues.includes(value)
  ) {
    throw new TypeError(`Backfill must be one of the enum values: ${column.name}`);
  }
  return value;
}

export interface MigrateOptions {
  /**
   * Allows steps that destroy data — dropping a column or a table. Off by default: a migration
   * runs when an application opens, with nobody to review it.
   */
  readonly allowDestructive?: boolean;
  /**
   * Treats the schema as the whole database, so a table it created and no longer declares is
   * dropped. Off by default: an application may migrate feature by feature, and each call
   * declaring only its own tables must not mean "drop the others". Needs `allowDestructive`
   * as well, since dropping a table destroys its rows.
   */
  readonly schemaOwnsDatabase?: boolean;
}

export interface MigrateResult {
  createdTables: string[];
  alteredTables: string[];
  droppedTables: string[];
  replacedViews: string[];
  droppedViews: string[];
  steps: MigrationStep[];
}

/** Reports the durable before-to-declaration delta, including work completed before a retry. */
function migrationResult(steps: readonly MigrationStep[]): MigrateResult {
  const createdTables: string[] = [];
  const alteredTables = new Set<string>();
  const droppedTables: string[] = [];
  const replacedViews: string[] = [];
  const droppedViews: string[] = [];
  for (const step of steps) {
    if (step.kind === "create-table") createdTables.push(step.table.name);
    else if (step.kind === "drop-table") droppedTables.push(step.tableName);
    else if (step.kind === "replace-view") replacedViews.push(step.view.name);
    else if (step.kind === "drop-view") droppedViews.push(step.viewName);
    else alteredTables.add(step.tableName);
  }
  return {
    createdTables,
    alteredTables: [...alteredTables],
    droppedTables,
    replacedViews,
    droppedViews,
    steps: [...steps],
  };
}

export interface CreateTableInput {
  name: string;
  columns: readonly ColumnDefinition[];
  /** Row conditions every written row must satisfy (E141-06); each is a boolean SQL expression. */
  checks?: ReadonlyArray<{ name: string; sql: string }>;
  /** Marks the table as created from a schema, which lets a later migration drop it. */
  managed?: boolean;
  /** References to a parent PRIMARY/unique row-addressing key. */
  foreignKeys?: readonly ForeignKeyDefinition[];
  uniqueKey?: string;
  /** PostgreSQL composite PRIMARY KEY, backed by a hidden canonical tuple locator. */
  compositePrimaryKey?: readonly string[];
  /** Independently enforced PostgreSQL UNIQUE constraints. */
  uniqueConstraints?: readonly UniqueConstraintDefinition[];
}

export type { BatchRow, BatchValue, ColumnarBatch, InsertBatchInput } from "./batch.js";

export interface InsertBatchResult {
  tableName: string;
  segmentId: string;
  rowCount: number;
  blockCount: number;
  storedBytes: number;
  version: number;
  metrics: WriteMetrics;
  /**
   * Full written vectors, input row order, for every column where the engine filled at least
   * one default or generated slot. Absent when the batch was written exactly as provided.
   */
  generatedColumns?: Record<string, BatchValue[]>;
}

export interface UpsertBatchResult extends Omit<InsertBatchResult, "segmentId"> {
  segmentId: string | null;
  /** Input rows considered by the statement, including conflicts rejected by `conflictWhere`. */
  requestedRowCount: number;
  insertedRowCount: number;
  updatedRowCount: number;
  /** Input rows rejected by `conflictWhere`; always 0 without it. */
  skippedRowCount: number;
}

export interface UpsertConflictWhere {
  /** Column of the existing conflicting row to test. */
  column: string;
  operator: ComparisonOperator;
  value: BatchValue;
}

export interface UpsertOptions {
  /** SQL `ON CONFLICT DO UPDATE ... WHERE` semantics over the existing target row. */
  conflictWhere?: UpsertConflictWhere;
}

export interface UpdateBatchInput {
  /** Stable ordinary arrays; do not mutate or expose changing accessors until the write settles. */
  keys: readonly BatchValue[];
  /** Stable ordinary arrays; do not mutate or expose changing accessors until the write settles. */
  changes: Readonly<Record<string, readonly BatchValue[]>>;
}

/** `UpdateBatchInput` as the typed overload hands it on; see `ColumnarBatchLike`. */
interface UpdateBatchInputLike {
  readonly keys: readonly BatchValue[];
  readonly changes: Readonly<Record<string, readonly BatchValue[] | undefined>>;
}

function compactUpdateBatchInput(input: UpdateBatchInputLike): UpdateBatchInput {
  return Object.values(input.changes).includes(undefined)
    ? { keys: input.keys, changes: definedVectors(input.changes) }
    : (input as UpdateBatchInput);
}

export interface UpdateBatchResult {
  tableName: string;
  segmentId: string;
  requestedRowCount: number;
  updatedRowCount: number;
  changedColumns: string[];
  blockCount: number;
  storedBytes: number;
  version: number;
  metrics: WriteMetrics;
  /** Recomputed generated-column vectors in input key order. */
  generatedColumns?: Record<string, BatchValue[]>;
}

export interface WriteMetrics {
  logicalBytes: number;
  storedBytes: number;
  writeAmplification: number;
  /** Encoding the batch into blocks. */
  encodeMs: number;
  /**
   * Staging the blocks and segments as a step of its own: trigger-derived rows, and stores
   * without a single-shot commit. On a store that commits a simple write in one storage
   * transaction the staging happens inside the commit, this is 0, and `commitMs` covers both.
   */
  stageMs: number;
  /** Committing — including the staging, on the single-shot path — and any rebase retries. */
  commitMs: number;
  totalMs: number;
  retries: number;
  rowsPerSecond: number;
}

export interface ReadTableOptions {
  version?: number;
  columns?: readonly string[];
}

/**
 * The scope handed to `snapshot()`: queries pinned to one manifest version, consistent with
 * each other for the lifetime of the callback.
 */
export interface SnapshotSession {
  /** The pinned manifest version; null only on a database with no commits yet. */
  readonly version: number | null;
  query(sql: string, options?: QueryOptions): Promise<QueryResult>;
}

/** Lifetime buffer pool counters; see MinnowDatabase.bufferPoolStats(). */
export interface BufferPoolStats {
  limitBytes: number;
  usedBytes: number;
  entries: number;
  hits: number;
  misses: number;
  evictions: number;
}

/** One staged mutation inside a write scope; the commit version arrives on the scope. */
export interface StagedWriteResult {
  tableName: string;
  segmentId: string | null;
  rowCount: number;
  /** Values filled by defaults or auto-increment while the rows were staged. */
  generatedColumns?: Record<string, QueryValue[]>;
}

export interface StagedUpsertResult extends StagedWriteResult {
  /** Input rows rejected by `conflictWhere`; always 0 without it. */
  skippedRowCount: number;
}

/**
 * The scope handed to `write()`: every mutation stages into one transaction and publishes
 * as one commit — all of it or none of it, in every tab. Reads observe the pre-scope snapshot
 * plus everything the scope has staged, so later statements (and trigger bodies) see earlier
 * ones; AFTER triggers fire per staged operation exactly as they do for standalone writes.
 *
 * A mutation that fails after registering part of its work ends the scope: the registration
 * cannot be undone in place, so later statements and the commit both reject even if the caller
 * caught the original error. A mutation that fails validation before registering anything
 * leaves the scope usable.
 */
export interface WriteSession<TSchema extends AnySchema = UntypedSchema> {
  /**
   * Read-your-writes: the query observes the pre-scope snapshot PLUS everything this scope
   * has staged so far, ordered after all committed data — without publishing anything.
   */
  query(sql: string, options?: QueryOptions): Promise<QueryResult>;
  /** Runs a SELECT, INSERT, UPDATE, or DELETE inside this write scope. */
  execute(sql: string, params?: readonly QueryValue[]): Promise<ExecuteResult>;
  insertBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchInsertInput<TSchema, TName>,
  ): Promise<StagedWriteResult>;
  upsertBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchInsertInput<TSchema, TName>,
    options?: BatchUpsertOptions<TSchema, TName>,
  ): Promise<StagedUpsertResult>;
  updateBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchUpdateInput<TSchema, TName>,
  ): Promise<StagedWriteResult>;
  deleteBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchDeleteInput<TSchema, TName>,
  ): Promise<StagedWriteResult>;
}

/** What one statement's execution cost, reported by the engine that ran it. */
export interface QueryExecutionStats {
  /**
   * Peak modeled execution memory for this statement, in bytes: the documented vector,
   * row-index, group/result payload, and ordering buffers, which is the same model
   * `executionMemoryBudgetBytes` bounds. Boxed snapshot preparation, JavaScript container
   * overhead, and allocator overhead are outside it. Not reported for a memo hit — nothing ran.
   */
  readonly peakMemoryBytes: number;
}

export interface MaintenanceStatus {
  readonly autoCollectionEnabled: boolean;
  readonly collectionRunning: boolean;
  readonly collectionRequested: boolean;
  /** Commits since collection last proved there was no immediately reclaimable work. */
  readonly pendingCommitDebt: number;
  readonly consecutiveFailures: number;
  /** In-memory posting-tail retry markers; bounded and cleared with their catalog owner. */
  readonly postingDeltaTailMarkers: number;
  /** SQL text caches retain only inputs below the fixed cacheability ceiling. */
  readonly retainedPlanEntries: number;
  readonly retainedStatementEntries: number;
  readonly lastStartedAt: Date | null;
  readonly lastCompletedAt: Date | null;
  readonly nextRetryAt: Date | null;
  readonly lastError: { readonly name: string; readonly message: string; readonly at: Date } | null;
}

export interface QueryOptions {
  /**
   * Stops a read between bounded execution or storage batches. An abort never returns a partial
   * result and releases any reader lease and temporary spill owner before the promise rejects.
   */
  readonly signal?: AbortSignal;
  /**
   * Called once with what this execution cost, before the result is returned. Additive and
   * optional: the engine can report its own memory because it reserves before it allocates,
   * which is not something the storage layer or a caller could measure from outside.
   */
  readonly onStats?: (stats: QueryExecutionStats) => void;
  /**
   * false makes this statement compute its results instead of reusing any it has cached: the
   * probe-validated result memo, cached block results, and the columnar forms of derived and
   * windowed sources are all bypassed (the default true serves provably-fresh cached results
   * from each). Block and vector caches stay warm — those cache storage reads, not results.
   *
   * Useful for benchmarking execution itself, and for callers that re-run one statement in a
   * tight loop over changing external state. Note that replaying one statement over unchanging
   * data with the default on measures cache lookups, not query execution.
   */
  memoize?: boolean;
  readonly version?: number;
  /**
   * Values for the statement's `?`/`$n` placeholders, in order. Required exactly when the
   * statement has placeholders; the compiled plan is cached on the SQL text and re-bound per
   * execution, so parameterized queries skip re-parsing.
   */
  readonly params?: readonly QueryValue[];
  /**
   * Budget for the documented modeled vector, row-index, group/result payload, and ordering buffers.
   * Boxed snapshot preparation, JavaScript container overhead, returned-result lifetime, and browser
   * allocator overhead are not included in this Phase 7B-B model.
   */
  readonly executionMemoryBudgetBytes?: number;
  /** Forces durable temp pages; with an explicit budget, spill otherwise retries only after exhaustion. */
  readonly spillToStorage?: boolean;
  /** Maximum rows encoded in each merged spill page. */
  readonly spillPageRows?: number;
}

/**
 * Engine controls honored by `execute()`. A SELECT runs through the query pipeline with all of
 * them; every other statement checks `signal` before it starts running, so an already-aborted
 * execute never mutates anything. Mutations are not stopped mid-statement — a write either
 * publishes completely or fails — and only SELECT executions report stats.
 */
export type ExecuteOptions = Pick<
  QueryOptions,
  "signal" | "onStats" | "memoize" | "executionMemoryBudgetBytes"
>;

export interface QueryCursorOptions extends QueryOptions {
  /** Maximum rows in one yielded result batch. Defaults to the vector scan batch size. */
  readonly batchRows?: number;
}

export interface DeleteBatchInput {
  /** Stable ordinary array; do not mutate or expose changing accessors until the write settles. */
  keys: readonly BatchValue[];
}

export interface DeleteBatchResult {
  tableName: string;
  segmentId: string | null;
  requestedKeyCount: number;
  deletedRowCount: number;
  blockCount: number;
  storedBytes: number;
  version: number | null;
  metrics: WriteMetrics;
}

export interface CompactTableOptions {
  /** Minimum L0 segments promoted; one also permits a direct L0 -> L2 promotion. */
  minimumLevel0Segments?: number;
  /** Target maximum L0 segments promoted by one job. Equal-order groups remain indivisible. */
  maxLevel0Segments?: number;
  /** Target maximum stored L0 bytes promoted by one job. The L1 anchor is excluded. */
  maxLevel0StoredBytes?: number;
  /**
   * Target maximum rows per level-one partition a keyed fold publishes. A fold rewrites only
   * the partitions its deltas touch, so smaller partitions make folds cheaper and scans read
   * more blocks. Ignored by keyless tables and by L2 promotion.
   */
  partitionRows?: number;
  /** Number of immutable output blocks processed before yielding and checkpointing. */
  maxBlocksPerStep?: number;
  /** Output level. L2 is the append-only row-range partition policy. */
  targetLevel?: number;
  /** Hard L2 output-byte limit as a multiple of newly promoted L0 stored bytes. */
  maxWriteAmplification?: number;
  /** Estimated uncompressed physical bytes per output column block. */
  targetBlockBytes?: number;
  /** Compression used for rewritten output blocks. */
  outputCompression?: Compression;
  /** Upper bound for accounted JavaScript-owned executor buffers. */
  memoryBudgetBytes?: number;
}

export interface CompactTableStepOptions extends CompactTableOptions {
  maxBlocks?: number;
}

export type CompactionSkipReason =
  | "below-segment-threshold"
  | "contains-mutation-segments"
  | "keys-outside-selected-sources"
  | "non-contiguous-row-ids"
  | "unsupported-level-layout"
  | "write-amplification-budget";

export interface CompactTableResult {
  jobId?: string;
  tableName: string;
  compacted: boolean;
  skipReason?: CompactionSkipReason;
  sourceSegmentCount: number;
  sourceBlockCount: number;
  outputSegmentId: string | null;
  /** Every published output segment; a keyed fold publishes one per partition it wrote. */
  outputSegmentIds?: string[];
  outputBlockCount: number;
  rowCount: number;
  sourceStoredBytes: number;
  outputStoredBytes: number;
  level0SourceStoredBytes?: number;
  anchorSourceStoredBytes?: number;
  compactionWriteAmplification?: number;
  outputPartitionOrdinal?: number;
  maxWriteAmplification?: number;
  maximumOutputStoredBytes?: number;
  plannedOutputStoredBytesUpperBound?: number;
  /** Stored bytes cancelled or aborted attempts at these sources already wrote. */
  priorAttemptOutputStoredBytes?: number;
  /** This attempt's output plus every prior failed attempt's, sharing one lifetime ceiling. */
  lifetimeOutputStoredBytes?: number;
  outputLogicalBytes?: number;
  targetBlockBytes?: number;
  outputCompression?: Compression;
  memoryBudgetBytes?: number;
  minimumMemoryBytes?: number;
  peakWorkingBytes?: number;
  supersededBlockCount: number;
  physicallyReclaimedBytes: 0;
  version: number | null;
  metrics: WriteMetrics | null;
}

export interface CompactionJobProgress {
  jobId: string | null;
  tableName: string;
  state: CompactionJobState | "skipped";
  processedRows: number;
  sourceSegmentCount: number;
  sourceBlockCount: number;
  outputBlockCount: number;
  level0SourceStoredBytes?: number;
  anchorSourceStoredBytes?: number;
  outputPartitionOrdinal?: number;
  maxWriteAmplification?: number;
  maximumOutputStoredBytes?: number;
  plannedOutputStoredBytesUpperBound?: number;
  memoryBudgetBytes?: number;
  minimumMemoryBytes?: number;
  peakWorkingBytes?: number;
  result: CompactTableResult | null;
}

export interface CancelCompactionJobResult {
  jobId: string;
  state: "cancelled" | "published" | "aborted";
  publishedVersion: number | null;
}

export interface CollectGarbageOptions {
  /** Maximum candidates examined and checkpointed by each durable reclamation step. */
  maxItemsPerStep?: number;
  /** Maximum block, segment, and transaction candidates copied into one durable planning record. */
  maxPlanningItems?: number;
  /**
   * Manifest versions below the current one to leave unpruned, newest first, so a reader that
   * names a recent version — `query({ version })`, `readTable(name, version)` — still finds it.
   * Defaults to 0: an explicit call reclaims everything no lease or job pins. Background
   * collection keeps 64.
   */
  retainRecentVersions?: number;
}

export interface CollectGarbageStepOptions {
  /** Maximum candidates examined and checkpointed by this durable reclamation step. */
  maxItems?: number;
  /** Maximum block, segment, and transaction candidates copied into a newly planned job. */
  maxPlanningItems?: number;
  /** See `CollectGarbageOptions.retainRecentVersions`; applies when this step plans a job. */
  retainRecentVersions?: number;
}

export const MAX_GARBAGE_COLLECTION_RETAIN_RECENT_VERSIONS = 1_024;

export interface GarbageCollectionResult {
  jobId: string;
  prunedManifestCount: number;
  alreadyPrunedManifestCount: number;
  retainedManifestCount: number;
  missingManifestCount: number;
  reclaimedSegmentCount: number;
  retainedSegmentCount: number;
  missingSegmentCount: number;
  reclaimedBlockCount: number;
  retainedBlockCount: number;
  missingBlockCount: number;
  reclaimedTransactionCount: number;
  retainedTransactionCount: number;
  missingTransactionCount: number;
  physicallyReclaimedBytes: number;
}

export interface GarbageCollectionProgress {
  jobId: string;
  state: GarbageCollectionJobState;
  examinedManifestCount: number;
  examinedSegmentCount: number;
  examinedBlockCount: number;
  examinedTransactionCount: number;
  result: GarbageCollectionResult | null;
}

export interface TableDefinition {
  name: string;
  columns: ColumnDefinition[];
  uniqueKey?: string;
}

export type DatabaseRow = Record<string, Exclude<BatchValue, null> | null>;

export {
  CompactionBacklogError,
  CompactionJobCancelledError,
  CompactionMemoryBudgetError,
  CompactionWriteAmplificationError,
  MaintenanceBacklogError,
  MissingKeyError,
  SqlCompileError,
  UnknownTableError,
  TableInUseError,
  UniqueConstraintError,
  VisibleSegmentCursorStaleError,
};

export interface MinnowDatabaseOptions<TSchema extends AnySchema = UntypedSchema> {
  /**
   * The schema this database is declared against. It types every batch method by table name —
   * rows, keys, update changes, `conflictWhere`, `readTable` results — and is what a bare
   * `migrate()` applies. Without it the batch API addresses tables by plain string, as SQL does.
   */
  schema?: TSchema;
  /**
   * Block codec for newly written blocks; defaults to "gzip", which is also what compaction
   * rewrites to, so a table's blocks are encoded the same way however they got there.
   *
   * Measured over 200k rows on IndexedDB, gzip against raw: about half the stored bytes
   * (4.9 MiB vs 10.0 MiB) and a *faster* cold scan (13.3 ms vs 17.9 ms) — reading half the
   * bytes out of IndexedDB more than pays for decompressing them — at the cost of roughly
   * 2.2x on bulk ingest (413 ms vs 184 ms). Warm scans are identical either way, because the
   * buffer pool caches decoded blocks. Choose "raw" when ingest throughput matters more than
   * storage quota; the browser usually makes the opposite trade worth it.
   */
  compression?: Compression;
  /**
   * Target maximum uncompressed bytes in a newly written column block. `rowsPerBlock` remains a
   * second ceiling. A single value may exceed this target when it still fits the format's 64 MiB
   * hard limit. Defaults to 2 MiB, matching compaction output.
   */
  targetBlockBytes?: number;
  rowsPerBlock?: number;
  maxCommitRetries?: number;
  now?: () => Date;
  createId?: () => string;
  /** Durable spill-owner lease lifetime; renewed while a spilling query runs. */
  spillOwnerLeaseMs?: number;
  /** Durable active-writer deadline; renewed every third while the writer is live. */
  transactionOwnerLeaseMs?: number;
  /**
   * How long a statement-level transaction (`BEGIN` … `COMMIT`) may sit untouched before it
   * rolls itself back; 30 seconds by default. A scope nobody ever closes would otherwise hold
   * its staged blocks and transaction record against the collector forever.
   */
  transactionIdleTimeoutMs?: number;
  /**
   * Retained bytes for the block buffer pool: decoded physical blocks, their vectorized
   * per-block column forms, zone-map block descriptions, and derived/subquery block
   * results. Every entry is keyed by an immutable identity (a block id, or an exact
   * visible-segment-id fingerprint), so a cached entry can never serve stale data;
   * superseded entries simply stop being referenced and age out of the byte-bounded
   * LRU. 0 disables the pool. Defaults to 64 MiB.
   */
  bufferPoolBytes?: number;
  /**
   * Default modeled execution-memory budget for every query, including mutation selection,
   * triggers, subqueries, and read-your-writes scopes. Eligible sorts and groups spill
   * automatically. Defaults to 64 MiB; `null` explicitly restores unbounded mode.
   */
  executionMemoryBudgetBytes?: number | null;
  /**
   * Visible-row threshold at which a full-text MATCH on an unindexed append-only column
   * schedules a background index build (fire-and-forget; correctness never waits on it).
   * Defaults to 4096.
   */
  ftsAutoIndexRows?: number;
  /**
   * Background compaction: when a scan or a run of commits finds a table fragmented past 48
   * visible segments or carrying 32 delete/update deltas, a fold is planned and driven to
   * publication in small yielding steps, and re-planned while the table stays due — the same
   * self-maintenance pattern as the full-text auto index. Correctness never waits on it.
   * false disables, leaving `compactTable` to the caller.
   */
  autoCompact?: boolean;
  /**
   * Background collection: a garbage-collection pass after every background fold, and one
   * every 64 commits, each keeping the 64 most recent versions readable. Without it the
   * blocks a fold supersedes and the manifest every commit writes stay on disk until the
   * caller runs `collectGarbage`. Defaults to true independently of compaction; false leaves
   * collection to the caller.
   */
  autoCollect?: boolean;
  /**
   * Successful commits tolerated while automatic collection is failing before a foreground
   * write assists and, if maintenance still fails, is refused. Defaults to 4096.
   */
  autoCollectDebtLimitCommits?: number;
  /**
   * Defaults for every compaction this database plans, background folds included. A call's
   * own `CompactTableOptions` override them.
   */
  compaction?: {
    /** Target maximum rows per level-one partition of a keyed table. Defaults to 16,384. */
    partitionRows?: number;
  };
}

export interface QuerySpillCleanupOptions {
  /** Maximum owners examined in this pass. */
  maxOwners?: number;
}

export interface QuerySpillCleanupResult {
  ownersExamined: number;
  ownersReclaimed: number;
  ownersRetained: number;
}

/**
 * How deep a delete's referential actions may cascade. A chain of CASCADE keys can reach further
 * tables; the bound stops a cycle from recursing, the same way the trigger chain is bounded.
 */
const REFERENTIAL_CASCADES = 8;

/** One foreign key and the table that declares it, indexed by the parent it points at. */
interface ChildForeignKey {
  table: TableRecord;
  key: NonNullable<TableRecord["foreignKeys"]>[number];
}

/** What one catalog epoch says beyond the tables themselves; see `#catalogFacts`. */
interface CatalogFacts {
  /** View name to its query text. */
  views: ReadonlyMap<string, string>;
  /** Parent table name to the foreign keys referencing it. */
  childKeys: ReadonlyMap<string, readonly ChildForeignKey[]>;
  /** Physical table and column names to PostgreSQL logical-domain metadata. */
  domains: ReadonlyMap<string, ReadonlyMap<string, SqlDomain>>;
  /** Physical table names to their visible columns, used for nested SQL name resolution. */
  columns: ReadonlyMap<string, readonly string[]>;
  /** Physical table and column names to the stored value type, for untyped-literal coercion. */
  types: ReadonlyMap<string, ReadonlyMap<string, SimpleDataType>>;
  /** Physical table names to their SQL integer columns, for PostgreSQL integer division. */
  integers: ReadonlyMap<string, ReadonlySet<string>>;
  /** Physical table names to their primary-key columns, for GROUP BY functional dependency. */
  keys: ReadonlyMap<string, readonly string[]>;
}

/** Thrown into a held write scope to make it abort; never surfaces to a caller. */
class TransactionRollback extends Error {
  constructor() {
    super("Transaction rolled back");
    this.name = "TransactionRollback";
  }
}

/**
 * Whether a statement may run inside a statement-level transaction. Reads and row writes stage
 * into the scope; schema changes do not, because the catalog commits outside it and a rollback
 * could not take them back.
 */
type TransactionalStatement = Extract<
  CompiledStatement,
  { kind: "insert" | "update" | "delete" | "select" }
>;

function isTransactionalStatement(
  statement: CompiledStatement,
): statement is TransactionalStatement {
  return (
    statement.kind === "insert" ||
    statement.kind === "update" ||
    statement.kind === "delete" ||
    statement.kind === "select"
  );
}

export type ExecuteResult =
  | { kind: "rows"; result: QueryResult }
  | { kind: "create-table"; table: string }
  | { kind: "create-type"; name: string }
  | { kind: "create-sequence"; name: string }
  | {
      kind: "create-index";
      index: string;
      table: string;
      /** First key column, retained for compatibility with the original single-column result. */
      column: string;
      columns: string[];
      unique: boolean;
    }
  | { kind: "drop-index"; index: string; dropped: boolean }
  | { kind: "add-column"; table: string; column: string }
  | { kind: "drop-column"; table: string; column: string; dropped: boolean }
  | { kind: "drop-table"; table: string; dropped: boolean }
  | { kind: "merge"; table: string; rowCount: number; version?: number }
  | {
      kind: "transaction";
      action: "begin" | "commit" | "rollback" | "savepoint" | "rollback-to" | "release";
      name?: string;
      version?: number;
    }
  | { kind: "create-view"; view: string }
  | { kind: "drop-view"; view: string; dropped: boolean }
  /** A session setting statement (`SET`, `RESET`), accepted and ignored. */
  | { kind: "set"; action: "set" | "reset"; name: string }
  | { kind: "create-trigger"; table: string; name: string }
  | { kind: "drop-trigger"; name: string }
  | ({
      kind: "insert";
      table: string;
      rowCount: number;
      /** Absent when the statement affected no rows (an INSERT ... SELECT of an empty set). */
      version?: number;
    } & ReturningExecuteFields)
  | ({ kind: "update"; table: string; rowCount: number; version?: number } & ReturningExecuteFields)
  | ({
      kind: "delete";
      table: string;
      rowCount: number;
      version?: number | null;
    } & ReturningExecuteFields);

interface ReturningExecuteFields {
  returnedRows?: QueryRow[];
  /** RETURNING projection order; present with returnedRows, including for an empty result. */
  returnedColumns?: string[];
  /** Logical domains aligned with returnedColumns. */
  returnedColumnDomains?: Array<SqlDomain | null>;
}

/**
 * Evaluates RETURNING expression items over the affected rows (every visible column of the
 * post-image for INSERT and UPDATE, the pre-image for DELETE) through the row executor, so a
 * function, arithmetic, or CASE in RETURNING has exactly the semantics it has in a SELECT.
 */
function projectReturningItems(
  table: TableRecord,
  alias: string,
  items: readonly ReturningItem[],
  rows: readonly QueryRow[],
  facts: Pick<CatalogFacts, "domains" | "types" | "integers">,
): Required<ReturningExecuteFields> {
  // The same catalog normalization a SELECT receives, and the same columnar executor: the
  // affected rows become a one-table input whose values carry the execution form a stored row
  // reads with, so `amount * 2` over a NUMERIC column is exact arithmetic here as well.
  const plan = normalizePlanDomainLiterals(
    {
      sql: "(returning)",
      base: { table: table.name, alias },
      joins: [],
      select: items.map((item) => ({
        expression: structuredClone(item.expression),
        alias: item.alias,
      })),
      predicates: [],
      groupBy: [],
      having: [],
      orderBy: [],
    },
    facts.domains,
    facts.types,
  );
  annotatePlanIntegerDivision(plan, (name) => facts.integers.get(name));
  const visible = visibleTableColumns(table);
  const columns = new Map<string, ColumnarColumnInput>(
    visible.map((column) => [
      column.name,
      {
        type: column.type,
        values: rows.map((row) => {
          const value = row[column.name] ?? null;
          return typeof value === "string" && value.charCodeAt(0) !== 0
            ? executionSqlValueFromInput(column, value)
            : value;
        }),
      },
    ]),
  );
  const input = createColumnarTable(table.name, columns);
  const typedSchemas = new Map<string, SqlColumnSchema[]>([
    [
      table.name,
      visible.map(({ name, type, integer, sqlDomain }) => ({
        name,
        type,
        ...(integer === true ? { integer: true as const } : {}),
        ...(sqlDomain === undefined ? {} : { sqlDomain }),
      })),
    ],
  ]);
  const memory = new QueryMemoryContext(undefined);
  const prepared = createPreparedColumnarQuery(plan, new Map([[table.name, input]]), memory);
  try {
    return {
      returnedRows: prepared.execute().rows,
      returnedColumns: items.map((item) => item.alias),
      returnedColumnDomains: inferResultColumnDomains(plan, typedSchemas),
    };
  } finally {
    prepared.close();
  }
}

function returningExecuteFields(
  table: TableRecord,
  columns: readonly string[],
  rows: QueryRow[],
): Required<ReturningExecuteFields> {
  return {
    returnedRows: rows,
    returnedColumns: [...columns],
    returnedColumnDomains: columns.map(
      (name) => table.columns.find((column) => column.name === name)?.sqlDomain ?? null,
    ),
  };
}

function externalizeExecuteResult(result: ExecuteResult): ExecuteResult {
  if (!("returnedRows" in result) || !Array.isArray(result.returnedRows)) return result;
  const columns = result.returnedColumns ?? [
    ...new Set(result.returnedRows.flatMap((row) => Object.keys(row))),
  ];
  const columnDomains = result.returnedColumnDomains ?? unknownColumnDomains(columns);
  return {
    ...result,
    returnedRows: externalizeQueryResult({
      columns,
      columnDomains,
      rows: result.returnedRows,
    }).rows,
    returnedColumns: [...columns],
    returnedColumnDomains: structuredClone(columnDomains),
  };
}

/** Rejects an INSERT value that is still an unbound `?`/`$n` slot. */
function boundInsertValue(value: InsertValue): QueryValue {
  if (isDefaultInsertValue(value)) {
    throw new TypeError("SQL DEFAULT is an omission marker, not a scalar value");
  }
  if (typeof value === "object" && value !== null && !(value instanceof Date)) {
    throw new TypeError("Statement has unbound placeholders; pass parameters when executing");
  }
  return value;
}

/** Keeps SQL DEFAULT distinct from explicit NULL while pivoting INSERT rows. */
/** The non-null unique-key values an insert batch proposes, in row order. */
function insertBatchKeyValues(input: InsertBatchInput, keyColumn: string): QueryValue[] {
  const values: readonly BatchValue[] =
    "columns" in input
      ? (input.columns[keyColumn] ?? [])
      : input.map((row) => row[keyColumn] ?? null);
  return values.filter((value): value is Exclude<BatchValue, null> => value !== null);
}

function insertStatementBatch(
  statement: Extract<CompiledStatement, { kind: "insert" }>,
): ColumnarBatch {
  const columns: Record<string, BatchValue[]> = {};
  const omitted: Record<string, boolean[]> = {};
  statement.columns.forEach((name, columnIndex) => {
    const values = new Array<BatchValue>(statement.rows.length).fill(null);
    const mask = new Array<boolean>(statement.rows.length).fill(false);
    for (let rowIndex = 0; rowIndex < statement.rows.length; rowIndex += 1) {
      const value = statement.rows[rowIndex]?.[columnIndex];
      if (value === undefined || isDefaultInsertValue(value)) {
        mask[rowIndex] = true;
      } else {
        values[rowIndex] = boundInsertValue(value);
      }
    }
    columns[name] = values;
    if (mask.some(Boolean)) omitted[name] = mask;
  });
  return {
    columns,
    ...(Object.keys(omitted).length === 0 ? {} : { omitted }),
    rowCount: statement.rows.length,
  };
}

/** Resolves CURRENT_* in every retained DML expression with one statement-start clock. */
function resolveMutationStatementDatetimes(
  statement: CompiledStatement,
  now: Date,
): CompiledStatement {
  const plan = (block: CompiledQuery): CompiledQuery =>
    resolveStatementDatetimes({ ...block, usesStatementDatetime: true }, now);
  const expression = (value: Expression): Expression => {
    const resolved = plan({
      sql: "(statement expression)",
      base: { table: DUAL_TABLE, alias: DUAL_TABLE },
      joins: [],
      select: [{ expression: value, alias: "value" }],
      predicates: [],
      groupBy: [],
      having: [],
      orderBy: [],
    });
    return resolved.select[0]?.expression ?? value;
  };
  const predicates = <T extends { left: Expression; right: Expression }>(values: T[]): T[] =>
    values.map((predicate) => ({
      ...predicate,
      left: expression(predicate.left),
      right: expression(predicate.right),
    }));

  if (statement.kind === "insert") {
    return {
      ...statement,
      rows: statement.rows.map((row) =>
        row.map((value) =>
          isDeferredInsertExpression(value) ? { expression: expression(value.expression) } : value,
        ),
      ),
      ...(statement.query === undefined ? {} : { query: plan(statement.query) }),
      ...(statement.onConflict === undefined
        ? {}
        : {
            onConflict: {
              ...statement.onConflict,
              ...(statement.onConflict.assignments === undefined
                ? {}
                : {
                    assignments: statement.onConflict.assignments.map((assignment) => ({
                      ...assignment,
                      expression: expression(assignment.expression),
                    })),
                  }),
              ...(statement.onConflict.where === undefined
                ? {}
                : { where: expression(statement.onConflict.where) }),
            },
          }),
    };
  }
  const sources = (from: MutationSources | undefined): { from?: MutationSources } =>
    from === undefined
      ? {}
      : {
          from: {
            ...from,
            predicates: predicates(from.predicates),
            joins: from.joins.map((join) => ({
              ...join,
              left: expression(join.left),
              right: expression(join.right),
              ...(join.on === undefined ? {} : { on: expression(join.on) }),
            })),
          },
        };
  if (statement.kind === "update") {
    return {
      ...statement,
      assignments: statement.assignments.map((assignment) => ({
        ...assignment,
        expression: expression(assignment.expression),
      })),
      predicates: predicates(statement.predicates),
      ...sources(statement.from),
    };
  }
  if (statement.kind === "delete") {
    return {
      ...statement,
      predicates: predicates(statement.predicates),
      ...sources(statement.from),
    };
  }
  if (statement.kind === "merge") {
    return {
      ...statement,
      on: expression(statement.on),
      branches: statement.branches.map((branch) => {
        const condition =
          branch.condition === undefined ? {} : { condition: expression(branch.condition) };
        if (branch.when === "not-matched") {
          return {
            ...branch,
            ...condition,
            action: { ...branch.action, values: branch.action.values.map(expression) },
          };
        }
        return {
          ...branch,
          ...condition,
          action:
            branch.action.kind === "update"
              ? {
                  ...branch.action,
                  assignments: branch.action.assignments.map((assignment) => ({
                    ...assignment,
                    expression: expression(assignment.expression),
                  })),
                }
              : branch.action,
        };
      }),
    };
  }
  if (statement.kind === "create-table-as") {
    return { ...statement, query: plan(statement.query) };
  }
  return statement;
}

/** Quotes a catalog identifier for internally generated SQL. */
function quoteSqlIdentifier(identifier: string): string {
  return `"${identifier.replaceAll('"', '""')}"`;
}

export interface RunStatementOptions {
  /**
   * Projects the affected rows back: column names, or "*" for every table column. Inserts echo
   * the written values; updates return post-update values; deletes return the rows as read.
   */
  readonly returning?: readonly string[] | "*";
  /**
   * Where the statement's writes go. Absent means the database itself — one commit per
   * statement. A write scope routes them into that scope instead, which is how a statement-level
   * transaction makes several statements publish together.
   */
  readonly writer?: StatementWriter;
}

/**
 * A write scope seen as somewhere statements can run: the batch operations, plus the reads the
 * keyed mutation paths need — by SQL for subqueries, by plan for the rows an UPDATE or DELETE
 * is about to touch. Both reads observe the scope's own staged writes.
 */
export interface StatementWriter extends WriteSession {
  queryPlan(plan: CompiledQuery): Promise<QueryResult>;
}

/** The extra entry point held by BEGIN so already-compiled statements are not parsed twice. */
interface TransactionStatementWriter extends StatementWriter {
  /** Snapshot-only scalar projection; undefined keeps the ordinary row-shaped fallback. */
  queryFirstColumn(plan: CompiledQuery): Promise<QueryValue[] | undefined>;
  executeStatement(statement: TransactionalStatement): Promise<ExecuteResult>;
  checkpoint(): TransactionCheckpoint;
  checkpointRetainedBytes(): number;
  rollbackTo(checkpoint: TransactionCheckpoint): Promise<void>;
}

interface OpenStatementTransaction {
  session: TransactionStatementWriter;
  settle: (outcome: "commit" | "rollback") => void;
  finished: Promise<{ version: number | null | undefined }>;
  timer: ReturnType<typeof setInterval>;
  busy: number;
  activeAt: number;
  savepoints: Array<{ name: string; checkpoint: TransactionCheckpoint; retainedBytes: number }>;
}

export interface VisibleSegment {
  id: string;
  rowCount: number;
  columnBlockIds: Readonly<Record<string, readonly string[]>>;
}

export interface VisibleSegmentPageRecord extends VisibleSegment {
  /** Stable logical scan order, exposed so bounded-page consumers can order a completed fold. */
  readonly logicalOrder: number;
  /** The commit that made the segment eligible at the captured manifest version. */
  readonly committedVersion: number;
  /** Stable order among segments from the same commit. */
  readonly commitOrdinal: number;
}

/** One public segment-inspection page; kept small for direct and worker callers alike. */
export const MAX_VISIBLE_SEGMENT_PAGE_ITEMS = 64;

/**
 * Opaque continuation state for a visible-segment scan. The manifest version and table identity
 * are captured on the first page, so later commits cannot move an in-progress scan onto different
 * data. Dropping or replacing the table makes this cursor stale and fails the next page.
 */
export interface VisibleSegmentPageCursor {
  readonly tableName: string;
  readonly tableId: string;
  readonly version: number | null;
  readonly afterId: string;
}

export interface VisibleSegmentPageOptions {
  /** First page only. Omit for the current committed version; null names the empty version. */
  readonly version?: number | null;
  /** Use the exact cursor returned by the previous page; do not combine with `version`. */
  readonly cursor?: VisibleSegmentPageCursor;
  /** Defaults to and may not exceed MAX_VISIBLE_SEGMENT_PAGE_ITEMS. */
  readonly limit?: number;
}

export interface VisibleSegmentPage {
  /** Visible records from this bounded physical segment-ID window, in lexical ID order. */
  readonly records: VisibleSegmentPageRecord[];
  /** The exact manifest version captured for every page in this scan. */
  readonly version: number | null;
  /** May be non-null when `records` is empty because historical records were filtered out. */
  readonly nextCursor: VisibleSegmentPageCursor | null;
}

/**
 * Snapshots are optional members of `BlockStore` — a store can be a complete database backend
 * without being able to copy itself out — so the database checks at the call and says plainly
 * when the capability is absent rather than failing as a missing property.
 */
type StreamingSnapshotExportStore = Required<
  Pick<
    BlockStore,
    "beginSnapshotFrameExport" | "readSnapshotExportFrame" | "closeSnapshotFrameExport"
  >
>;

function streamingSnapshotExportStore(store: BlockStore): StreamingSnapshotExportStore {
  const beginSnapshotFrameExport = store.beginSnapshotFrameExport?.bind(store);
  const readSnapshotExportFrame = store.readSnapshotExportFrame?.bind(store);
  const closeSnapshotFrameExport = store.closeSnapshotFrameExport?.bind(store);
  if (
    beginSnapshotFrameExport === undefined ||
    readSnapshotExportFrame === undefined ||
    closeSnapshotFrameExport === undefined
  ) {
    throw new Error("This database's block store cannot stream snapshots");
  }
  return { beginSnapshotFrameExport, readSnapshotExportFrame, closeSnapshotFrameExport };
}

type StreamingSnapshotImportStore = Required<
  Pick<
    BlockStore,
    | "beginSnapshotFrameImport"
    | "appendSnapshotImportFrames"
    | "finishSnapshotFrameImport"
    | "cancelSnapshotFrameImport"
  >
>;

function streamingSnapshotImportStore(store: BlockStore): StreamingSnapshotImportStore {
  const beginSnapshotFrameImport = store.beginSnapshotFrameImport?.bind(store);
  const appendSnapshotImportFrames = store.appendSnapshotImportFrames?.bind(store);
  const finishSnapshotFrameImport = store.finishSnapshotFrameImport?.bind(store);
  const cancelSnapshotFrameImport = store.cancelSnapshotFrameImport?.bind(store);
  if (
    beginSnapshotFrameImport === undefined ||
    appendSnapshotImportFrames === undefined ||
    finishSnapshotFrameImport === undefined ||
    cancelSnapshotFrameImport === undefined
  ) {
    throw new Error("This database's block store cannot stream snapshots");
  }
  return {
    beginSnapshotFrameImport,
    appendSnapshotImportFrames,
    finishSnapshotFrameImport,
    cancelSnapshotFrameImport,
  };
}

function queryCursorError(value: unknown, fallback = "Query cursor failed"): Error {
  return value instanceof Error ? value : new Error(fallback, { cause: value });
}

/** Cold compatibility helper while callers that need all table metadata migrate to page folds. */
async function listTableSegmentsPaged(
  store: BlockStore,
  tableId: string,
): Promise<SegmentRecord[]> {
  const records: SegmentRecord[] = [];
  let afterId: string | null = null;
  for (;;) {
    const page = await store.listTableSegmentPage(tableId, afterId, MAX_MAINTENANCE_BATCH_ITEMS);
    records.push(...page.records);
    if (page.nextCursor === null) return records;
    afterId = page.nextCursor;
  }
}

/** A one-page rendezvous: the producer cannot scan again until the iterator asks for the page. */
class QueryBatchChannel {
  #page:
    | {
        value: QueryResult;
        resolve: () => void;
        reject: (error: unknown) => void;
      }
    | undefined;
  #reader:
    | {
        resolve: (value: IteratorResult<QueryResult, undefined>) => void;
        reject: (error: unknown) => void;
      }
    | undefined;
  #finished = false;
  #error: Error | undefined;

  push(value: QueryResult): Promise<void> {
    if (this.#finished) return Promise.reject(this.#error ?? new Error("Query cursor is closed"));
    const reader = this.#reader;
    if (reader !== undefined) {
      this.#reader = undefined;
      reader.resolve({ done: false, value });
      return Promise.resolve();
    }
    return new Promise<void>((resolve, reject) => {
      this.#page = { value, resolve, reject };
    });
  }

  next(): Promise<IteratorResult<QueryResult, undefined>> {
    const page = this.#page;
    if (page !== undefined) {
      this.#page = undefined;
      page.resolve();
      return Promise.resolve({ done: false, value: page.value });
    }
    if (this.#finished) {
      return this.#error === undefined
        ? Promise.resolve({ done: true, value: undefined })
        : Promise.reject(this.#error);
    }
    return new Promise((resolve, reject) => {
      this.#reader = { resolve, reject };
    });
  }

  finish(): void {
    if (this.#finished) return;
    this.#finished = true;
    const reader = this.#reader;
    this.#reader = undefined;
    reader?.resolve({ done: true, value: undefined });
  }

  fail(error: unknown): void {
    if (this.#finished) return;
    const reason = queryCursorError(error);
    this.#finished = true;
    this.#error = reason;
    const page = this.#page;
    this.#page = undefined;
    page?.reject(reason);
    const reader = this.#reader;
    this.#reader = undefined;
    reader?.reject(reason);
  }
}

interface QueryBatchCursorExecution {
  readonly batchRows: number;
  readonly signal: AbortSignal;
  readonly consumeFirstColumn?: (values: readonly QueryValue[]) => Promise<void>;
  readonly consume: (batch: QueryResult) => Promise<void>;
}

export interface SnapshotExportOptions {
  /** Called as the export moves through its phases; see SnapshotExportProgress. */
  onProgress?: (progress: SnapshotExportProgress) => void;
  /** Cancels transfer and releases the durable export pin. */
  signal?: AbortSignal;
}

export interface SnapshotImportOptions {
  /** Called as blocks land, for a progress bar over a multi-megabyte file. */
  onProgress?: (progress: SnapshotLoadProgress) => void;
  /** Cancels transfer and atomically removes this caller's staged import. */
  signal?: AbortSignal;
}

const SNAPSHOT_TRANSFER_CHUNK_BYTES = 1024 * 1024;
const MAX_SNAPSHOT_BYTE_ARRAY_LENGTH = 0xffffffff;

function snapshotSessionTimes(now: Date): { createdAt: string; expiresAt: string } {
  const createdAtMs = dateMilliseconds(now);
  const expiresAtMs = createdAtMs + MAX_SNAPSHOT_SESSION_TTL_MS;
  if (!Number.isSafeInteger(expiresAtMs)) {
    throw new RangeError("Snapshot session expiration is outside the safe timestamp range");
  }
  return {
    createdAt: dateIsoString(new Date(createdAtMs)),
    expiresAt: dateIsoString(new Date(expiresAtMs)),
  };
}

function snapshotAbortError(signal: AbortSignal): Error {
  if (signal.reason instanceof Error) return signal.reason;
  const error = new Error("Snapshot operation was aborted", { cause: signal.reason });
  error.name = "AbortError";
  return error;
}

function throwIfSnapshotAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted === true) throw snapshotAbortError(signal);
}

async function* abortableSnapshotSource(
  source: AsyncIterable<Uint8Array>,
  signal: AbortSignal | undefined,
): AsyncGenerator<Uint8Array> {
  const iterator = source[Symbol.asyncIterator]();
  try {
    for (;;) {
      throwIfSnapshotAborted(signal);
      const next = await iterator.next();
      throwIfSnapshotAborted(signal);
      if (next.done === true) return;
      yield next.value;
    }
  } finally {
    await iterator.return?.();
  }
}

async function* singleSnapshotChunk(bytes: Uint8Array): AsyncGenerator<Uint8Array> {
  for (let offset = 0; offset < bytes.byteLength; offset += SNAPSHOT_TRANSFER_CHUNK_BYTES) {
    yield bytes.subarray(offset, offset + SNAPSHOT_TRANSFER_CHUNK_BYTES);
  }
}

export class MinnowDatabase<TSchema extends AnySchema = UntypedSchema> {
  readonly #schema: TSchema | undefined;
  /**
   * This database with the batch API erased to plain strings. The engine addresses tables by
   * runtime name — a statement's target, a foreign key's child — and only the public surface is
   * typed by the declaration, so internal calls go through here.
   */
  // eslint-disable-next-line @typescript-eslint/prefer-return-this-type -- the erasure is the point
  get #erased(): MinnowDatabase {
    return this;
  }
  #closed = false;
  #closePromise: Promise<void> | undefined;
  readonly #transactions: TransactionManager;
  /**
   * How long a statement-level transaction may sit untouched before it rolls itself back. The
   * bound is what makes a BEGIN a caller can walk away from safe: an abandoned scope holds
   * staged blocks and a transaction record the collector cannot reclaim while it is open.
   */
  readonly #transactionIdleTimeoutMs: number;
  /** What the catalog says, derived once per epoch; see `#catalogFacts`. */
  #catalogCache: { epoch: number; facts: CatalogFacts } | undefined;
  /** CURRVAL is connection-local, matching PostgreSQL session semantics. */
  readonly #sequenceCurrValues = new Map<string, number>();
  /** The scope a statement-level BEGIN opened, held until COMMIT, ROLLBACK, or the idle sweep. */
  #openTransaction: OpenStatementTransaction | undefined;
  /** Joins the durable abort after an idle timer has detached the statement transaction. */
  #statementTransactionCleanup: Promise<void> | undefined;
  readonly #compression: Compression;
  /** Per-column count since gzip last failed to repay itself; successful probes need no entry. */
  readonly #gzipVerdicts = new Map<string, number>();
  readonly #rowsPerBlock: number;
  readonly #targetBlockBytes: number;
  readonly #maxCommitRetries: number;
  readonly #now: () => Date;
  readonly #spillOwnerLeaseMs: number;
  readonly #transactionOwnerLeaseMs: number;
  readonly #createId: () => string;
  readonly #internalLeaseOwnerId: string;
  readonly #liveSets = new Set<LiveQuerySet>();
  /** Live proof inputs per commit window, keyed `after:until`; see #liveProofContext. */
  readonly #liveProofContexts = new Map<string, Promise<LiveProofContext>>();
  readonly #artifactCache: ArtifactCache;
  /** Finite default applied before every engine query path; MAX_SAFE is explicit unbounded mode. */
  readonly #queryExecutionMemoryBudgetBytes: number;
  readonly #ftsAutoIndexRows: number;
  readonly #autoCompact: boolean;
  readonly #compactionPartitionRows: number;
  readonly #autoCollect: boolean;
  readonly #autoCollectionDebtLimitCommits: number;
  /** Data commits since the last background collection pass. */
  #commitsSinceCollection = 0;
  /** Rotating durable-job scan cursor; keeps one quiet reconciliation pass bounded. */
  #compactionReconciliationCursor: string | null = null;
  #autoCollectionInFlight = false;
  /** A trigger that arrived while a run was in flight; honoured when the run ends. */
  #autoCollectionRequested = false;
  /** Conservative debt: reset only after a pass finds no more immediately reclaimable work. */
  #autoCollectionDebtCommits = 0;
  #manualCollectionDebtInitialized = false;
  #autoCollectionConsecutiveFailures = 0;
  #autoCollectionLastError: { name: string; message: string; at: number } | undefined;
  #lastCollectionCompletedAt: number | undefined;
  #autoCollectionRetryAt: number | undefined;
  #autoCollectionRetryTimer: ReturnType<typeof setTimeout> | undefined;
  /** When the last background collection pass started, by the database clock. */
  #lastCollectionAt: number | undefined;
  /** The idle pass scheduled after the last commit; reset by the next commit. */
  #idleCollectionTimer: ReturnType<typeof setTimeout> | undefined;
  /** The garbage-collection step in flight, so steps run one at a time: see #serializedCollectionStep. */
  #collectionSteps: Promise<unknown> = Promise.resolve();
  /** One background build attempt per (table, column) per session; misses just stay scans. */
  readonly #ftsBuildsInFlight = new Map<string, Promise<void>>();
  /** Highest authoritative commit hint observed while a postings fold is in flight. */
  readonly #postingDeltaTailCounts = new Map<string, number>();
  readonly #droppingFtsColumns = new Set<string>();
  /** Tables with a fire-and-forget compaction step already running. */
  readonly #autoCompactionsInFlight = new Map<string, Promise<void>>();
  /** Tables whose maintenance threshold was observed again while their fold was still running. */
  readonly #autoCompactionsRequested = new Set<string>();
  readonly #accountedCompactionVersions = new Set<number>();
  /** Changed tables awaiting the debounced check that closes a write burst. */
  readonly #idleCompactionTableIds = new Set<string>();
  #idleCompactionTimer: ReturnType<typeof setTimeout> | undefined;
  /** Tables whose drop is retiring data; prevents a new background fold from starting. */
  readonly #droppingTables = new Set<string>();
  /** Per table: the visible segment count a failed auto-compaction must see before retrying. */
  readonly #autoCompactionBackoff = new Map<string, AutoCompactionBackoff>();
  /** Exact current-layout counters; local commits advance them without rescanning history. */
  readonly #autoCompactionHints = new Map<string, AutoCompactionHint>();
  /** Data commits per table since its last write-path auto-compaction check. */
  readonly #commitsSinceCompactionCheck = new Map<string, number>();
  /** The compaction step in flight per table, so steps on one table run one at a time. */
  readonly #compactionSteps = new Map<string, Promise<unknown>>();
  /** The simple writes in flight, chained so they commit one after another: see #runWrite. */
  #writeChain: Promise<unknown> = Promise.resolve();
  /** Fold publications waiting for a turn on the write chain: see #withCompactionPublicationSlot. */
  readonly #pendingCompactionPublications = new Set<() => Promise<void>>();
  /** Settled by the next local commit; maintenance parked on a yield wakes on it. */
  #commitSignal: { promise: Promise<void>; resolve: () => void } | undefined;
  /** One shared pending event-loop turn, so parked maintenance holds one channel, not one each. */
  #pendingEventLoopTurn: Promise<void> | undefined;
  #pendingWriteReservations = 0;
  #activeReadReservations = 0;
  /** The complete automatic collection loop, retained so close() can join it before the store. */
  #autoCollectionTask: Promise<void> | undefined;
  /**
   * SQL text to optimized plan, LRU by insertion order. Compiled plans are never mutated after
   * optimization — subquery resolution and CTE expansion clone before rewriting and join
   * reordering spreads into fresh objects — so a hit shares the cached plan across executions
   * and skips tokenize/parse/optimize entirely.
   */
  readonly #planCache = new Map<string, CompiledQuery>();
  /** Mutation/DDL SQL to immutable parsed statement, with parameter binding cloning on hits. */
  readonly #statementCache = new Map<string, CompiledStatement>();
  readonly #visibleSegmentsMemo = new WeakMap<
    SegmentVisibilityCatalog,
    Map<string, SegmentRecord[]>
  >();
  /** Per-snapshot postings reads: statistics and pruning share one result per (column, terms). */
  readonly #ftsCandidatesMemo = new WeakMap<Snapshot, Map<string, Promise<FtsCandidatesResult>>>();
  #sharedLease: SharedLeaseEntry | undefined;
  #sharedLeaseRenewal: Promise<void> | undefined;
  /** An in-flight re-pin of the shared lease; acquirers wait for it, never join it. */
  #sharedLeaseMove: Promise<void> | undefined;
  /** Retired shared pins release off the read fast path; close joins them before store shutdown. */
  readonly #sharedLeaseReleases = new Set<Promise<void>>();
  /** Acquisitions can be suspended in store I/O before they install an entry. */
  #sharedLeaseAcquisitions = 0;
  /** Sum of refCount across current and retired shared entries. */
  #sharedLeaseUses = 0;
  readonly #sharedLeaseStateWaiters = new Set<() => void>();
  /**
   * Catalog states keyed by requested table-name set, valid only at #catalogStateEpoch.
   * The (version, epoch) probe is the sole validity signal: a matched epoch proves a cached
   * entry is byte-identical to a fresh read, and a moved epoch clears every entry.
   */
  readonly #catalogStateCache = new Map<string, QueryCatalogState>();
  #catalogStateEpoch: number | undefined;
  /**
   * Immutable maps derived from one epoch-gated catalog state. A settled table can retain many
   * historical segment and transaction records after their payloads are reclaimed; rebuilding
   * these indexes on every query would make steady-state preparation O(history), and a fresh
   * visibility object would also defeat #visibleSegmentsMemo. Weak keys keep eviction owned by
   * the bounded catalog-state cache without a second retention policy.
   */
  readonly #preparedCatalogStates = new WeakMap<
    QueryCatalogState,
    {
      readonly realTables: Map<string, TableRecord>;
      readonly visibility: SegmentVisibilityCatalog;
    }
  >();

  constructor(
    private readonly store: BlockStore,
    options: MinnowDatabaseOptions<TSchema> = {},
  ) {
    this.#schema = options.schema;
    this.#compression = options.compression ?? "gzip";
    // The block is the streamed scan's row group and the buffer pool's residency unit.
    // Measured curve (400k rows, streamed filter/group/like/top-n, 2026-08): throughput is
    // flat from ~16k rows per block and 2k-row blocks cost up to 66% on top-n; 65,536 sits
    // on the plateau while keeping eviction granularity moderate.
    this.#rowsPerBlock = options.rowsPerBlock ?? 65_536;
    if (
      !Number.isSafeInteger(this.#rowsPerBlock) ||
      this.#rowsPerBlock <= 0 ||
      this.#rowsPerBlock > MAX_BLOCK_ROW_COUNT
    ) {
      throw new RangeError(
        `Rows per block must be a positive whole number no larger than ${String(MAX_BLOCK_ROW_COUNT)}`,
      );
    }
    this.#targetBlockBytes = options.targetBlockBytes ?? DEFAULT_WRITE_TARGET_BLOCK_BYTES;
    if (
      !Number.isSafeInteger(this.#targetBlockBytes) ||
      this.#targetBlockBytes <= 0 ||
      this.#targetBlockBytes > MAX_PHYSICAL_COLUMN_BYTE_LENGTH
    ) {
      throw new RangeError(
        `Target block bytes must be a positive whole number no larger than ${String(MAX_PHYSICAL_COLUMN_BYTE_LENGTH)}`,
      );
    }
    this.#maxCommitRetries = options.maxCommitRetries ?? 8;
    if (!Number.isSafeInteger(this.#maxCommitRetries) || this.#maxCommitRetries < 0) {
      throw new RangeError("Commit retries must be a non-negative whole number");
    }
    this.#now = options.now ?? (() => new Date());
    this.#createId = options.createId ?? (() => crypto.randomUUID());
    this.#internalLeaseOwnerId = `minnow/${this.#createId()}`;
    this.#spillOwnerLeaseMs = options.spillOwnerLeaseMs ?? 60_000;
    if (
      !Number.isSafeInteger(this.#spillOwnerLeaseMs) ||
      this.#spillOwnerLeaseMs <= 0 ||
      this.#spillOwnerLeaseMs > MAX_TEMP_OWNER_TTL_MS
    ) {
      throw new RangeError(
        `Spill owner lease lifetime must be a positive whole number no greater than ${String(MAX_TEMP_OWNER_TTL_MS)}`,
      );
    }
    this.#transactionOwnerLeaseMs = options.transactionOwnerLeaseMs ?? 30_000;
    if (
      !Number.isSafeInteger(this.#transactionOwnerLeaseMs) ||
      this.#transactionOwnerLeaseMs <= 0
    ) {
      throw new RangeError("Transaction owner lease lifetime must be a positive whole number");
    }
    this.#artifactCache = new ArtifactCache(options.bufferPoolBytes ?? 64 * 1024 * 1024);
    const queryBudget = options.executionMemoryBudgetBytes;
    this.#queryExecutionMemoryBudgetBytes =
      queryBudget === null
        ? Number.MAX_SAFE_INTEGER
        : positiveWholeNumber(
            queryBudget ?? DEFAULT_QUERY_MEMORY_BUDGET_BYTES,
            "Query execution memory budget",
          );
    this.#ftsAutoIndexRows = options.ftsAutoIndexRows ?? 4096;
    this.#autoCompact = options.autoCompact ?? true;
    this.#autoCollect = options.autoCollect ?? true;
    this.#autoCollectionDebtLimitCommits = positiveWholeNumber(
      options.autoCollectDebtLimitCommits ?? AUTO_COLLECT_MAX_DEBT_COMMITS,
      "Automatic collection debt limit",
    );
    this.#compactionPartitionRows = positiveWholeNumber(
      options.compaction?.partitionRows ?? DEFAULT_COMPACTION_PARTITION_ROWS,
      "Compaction partition rows",
    );
    if (!Number.isSafeInteger(this.#ftsAutoIndexRows) || this.#ftsAutoIndexRows < 0) {
      throw new RangeError(
        "Full-text auto-index row threshold must be a non-negative whole number",
      );
    }
    this.#transactionIdleTimeoutMs = options.transactionIdleTimeoutMs ?? 30_000;
    this.#transactions = new TransactionManager(store, {
      now: this.#now,
      createId: this.#createId,
      transactionTtlMs: this.#transactionOwnerLeaseMs,
    });
    this.#armIdleCollection();
  }

  /**
   * Stops timers and background scheduling, rolls back an abandoned statement transaction,
   * closes live-query resources, releases the engine's reader lease, and drops resident caches.
   * The injected block store remains caller-owned and must be closed separately.
   */
  close(): Promise<void> {
    if (this.#closePromise !== undefined) return this.#closePromise;
    this.#closed = true;
    const closing = this.#closeResources();
    this.#closePromise = closing;
    return closing;
  }

  async #closeResources(): Promise<void> {
    if (this.#idleCompactionTimer !== undefined) {
      clearTimeout(this.#idleCompactionTimer);
      this.#idleCompactionTimer = undefined;
    }
    if (this.#idleCollectionTimer !== undefined) {
      clearTimeout(this.#idleCollectionTimer);
      this.#idleCollectionTimer = undefined;
    }
    if (this.#autoCollectionRetryTimer !== undefined) {
      clearTimeout(this.#autoCollectionRetryTimer);
      this.#autoCollectionRetryTimer = undefined;
    }

    const open = this.#openTransaction;
    const statementCleanup =
      open === undefined
        ? this.#statementTransactionCleanup
        : this.#rollbackStatementTransaction(open);

    for (const set of [...this.#liveSets]) set.close();
    this.#liveSets.clear();

    // No new background task can start after #closed flips. Join the tasks that already own
    // store work before releasing leases or allowing the caller to close the injected store.
    await Promise.allSettled([
      ...this.#autoCompactionsInFlight.values(),
      ...this.#ftsBuildsInFlight.values(),
      ...(this.#autoCollectionTask === undefined ? [] : [this.#autoCollectionTask]),
      ...(statementCleanup === undefined ? [] : [statementCleanup]),
    ]);

    // An acquire already inside store I/O can otherwise install a fresh lease after the close
    // path detached what it believed was the final entry. #closed prevents any new acquire from
    // entering after this point; join the ones that entered before it flipped.
    while (this.#sharedLeaseAcquisitions > 0) await this.#sharedLeaseStateChange();

    // A move or renewal owns the lease while suspended. Let it settle before detaching the
    // final entry, otherwise it could install a fresh persistent lease after close returned.
    await Promise.allSettled(
      [this.#sharedLeaseMove, this.#sharedLeaseRenewal].filter(
        (pending): pending is Promise<void> => pending !== undefined,
      ),
    );
    const shared = this.#sharedLease;
    this.#sharedLease = undefined;
    if (shared?.refCount === 0) await shared.lease.release().catch(() => undefined);
    // Active snapshot/query callbacks release retired entries in their finally blocks. Wait for
    // those references before draining the tracked removals, so none can enqueue store work after
    // close has returned to a caller that may immediately close the injected adapter.
    while (this.#sharedLeaseUses > 0) await this.#sharedLeaseStateChange();
    while (this.#sharedLeaseReleases.size > 0) {
      await Promise.allSettled([...this.#sharedLeaseReleases]);
    }
    if (open !== undefined) await open.finished.catch(() => undefined);

    this.#planCache.clear();
    this.#statementCache.clear();
    this.#catalogStateCache.clear();
    this.#liveProofContexts.clear();
    this.#gzipVerdicts.clear();
    this.#autoCompactionsRequested.clear();
    this.#idleCompactionTableIds.clear();
    for (const backoff of this.#autoCompactionBackoff.values()) {
      if (backoff.retryTimer !== undefined) clearTimeout(backoff.retryTimer);
    }
    this.#autoCompactionBackoff.clear();
    this.#autoCompactionHints.clear();
    this.#commitsSinceCompactionCheck.clear();
    this.#artifactCache.clear();
  }

  /** Current background-collection health, returned as a defensive snapshot. */
  maintenanceStatus(): MaintenanceStatus {
    const error = this.#autoCollectionLastError;
    return {
      autoCollectionEnabled: this.#autoCollect,
      collectionRunning: this.#autoCollectionInFlight,
      collectionRequested: this.#autoCollectionRequested,
      pendingCommitDebt: this.#autoCollectionDebtCommits,
      consecutiveFailures: this.#autoCollectionConsecutiveFailures,
      postingDeltaTailMarkers: this.#postingDeltaTailCounts.size,
      retainedPlanEntries: this.#planCache.size,
      retainedStatementEntries: this.#statementCache.size,
      lastStartedAt: this.#lastCollectionAt === undefined ? null : new Date(this.#lastCollectionAt),
      lastCompletedAt:
        this.#lastCollectionCompletedAt === undefined
          ? null
          : new Date(this.#lastCollectionCompletedAt),
      nextRetryAt:
        this.#autoCollectionRetryAt === undefined ? null : new Date(this.#autoCollectionRetryAt),
      lastError:
        error === undefined
          ? null
          : { name: error.name, message: error.message, at: new Date(error.at) },
    };
  }

  async createTable(input: CreateTableInput): Promise<void> {
    const name = validateName(input.name, "Table");
    if (input.columns.length === 0) throw new TypeError("A table needs at least one column");
    const enumDomains = new Map<string, SqlDomain>();
    for (const column of input.columns) {
      if (column.sqlDomain?.kind !== "enum" || column.sqlDomain.values.length > 0) continue;
      const record = await this.store.getTableByName(`${ENUM_TYPE_PREFIX}${column.sqlDomain.name}`);
      if (record?.enumType === undefined) {
        throw new TypeError(`Unsupported column type: ${column.sqlDomain.name}`);
      }
      enumDomains.set(column.name, {
        kind: "enum",
        name: record.enumType.name,
        values: [...record.enumType.values],
      });
    }
    const names = new Set<string>();
    const columns: TableColumnRecord[] = input.columns.map((column) => {
      const columnName = validateName(column.name, "Column");
      if (names.has(columnName)) throw new TypeError(`Duplicate column: ${columnName}`);
      names.add(columnName);
      if (!simpleDataTypes.includes(column.type)) {
        throw new TypeError(`Unsupported data type: ${column.type}`);
      }
      if (column.enumValues !== undefined && column.type !== "string") {
        throw new TypeError(`Enum values require a string column: ${columnName}`);
      }
      const sqlDomain = enumDomains.get(column.name) ?? column.sqlDomain;
      return {
        id: this.#createId(),
        name: columnName,
        type: column.type,
        ...(column.integer === true ? { integer: true } : {}),
        ...(sqlDomain === undefined ? {} : { sqlDomain: structuredClone(sqlDomain) }),
        nullable: column.nullable ?? false,
        ...(column.defaultValue === undefined ? {} : { defaultValue: column.defaultValue }),
        ...(column.generatedValue === undefined
          ? {}
          : { generatedValue: structuredClone(column.generatedValue) }),
        ...(column.enumValues === undefined
          ? {}
          : { enumValues: validateEnumValues(column.enumValues, columnName) }),
        ...(column.backfill === undefined
          ? {}
          : {
              backfill: normalizedColumnBackfill(
                {
                  name: columnName,
                  type: column.type,
                  ...(column.integer === true ? { integer: true as const } : {}),
                  ...(sqlDomain === undefined ? {} : { sqlDomain }),
                  ...(column.enumValues === undefined ? {} : { enumValues: column.enumValues }),
                },
                column.backfill,
              ),
            }),
      };
    });
    if (input.uniqueKey !== undefined && input.compositePrimaryKey !== undefined) {
      throw new TypeError("A table cannot declare both scalar and composite primary keys");
    }
    const compositePrimaryColumns = (input.compositePrimaryKey ?? []).map((columnName) => {
      const column = columns.find((candidate) => candidate.name === columnName);
      if (column === undefined) {
        throw new TypeError(`PRIMARY KEY column not found: ${columnName}`);
      }
      return column;
    });
    if (
      input.compositePrimaryKey !== undefined &&
      (compositePrimaryColumns.length < 2 ||
        new Set(compositePrimaryColumns.map((column) => column.id)).size !==
          compositePrimaryColumns.length)
    ) {
      throw new TypeError("A composite PRIMARY KEY needs at least two distinct columns");
    }
    for (const column of compositePrimaryColumns) {
      if (column.nullable) throw new TypeError(`PRIMARY KEY cannot be nullable: ${column.name}`);
    }
    const hiddenCompositeKey =
      compositePrimaryColumns.length === 0
        ? undefined
        : ({
            id: this.#createId(),
            name: COMPOSITE_KEY_COLUMN_NAME,
            type: "string",
            nullable: false,
            hidden: true,
          } satisfies TableColumnRecord);
    if (hiddenCompositeKey !== undefined) columns.push(hiddenCompositeKey);
    const uniqueKeyColumn =
      hiddenCompositeKey ??
      (input.uniqueKey === undefined
        ? undefined
        : columns.find((column) => column.name === input.uniqueKey));
    if (input.uniqueKey !== undefined && uniqueKeyColumn === undefined) {
      throw new TypeError(`Unique key column not found: ${input.uniqueKey}`);
    }
    if (uniqueKeyColumn?.nullable === true) {
      throw new TypeError(`Unique key cannot be nullable: ${uniqueKeyColumn.name}`);
    }
    for (const column of columns) {
      if (column.generatedValue !== undefined) {
        if (column.defaultValue !== undefined || column.backfill !== undefined) {
          throw new TypeError(
            `A generated column cannot also have a default or backfill: ${name}.${column.name}`,
          );
        }
        compileGeneratedColumnExpression(name, column.name, column.generatedValue.sql, columns);
        if (column === uniqueKeyColumn || compositePrimaryColumns.includes(column)) {
          throw new TypeError(
            `Generated columns cannot be row-addressing keys: ${name}.${column.name}`,
          );
        }
      }
      if (column.defaultValue !== undefined) {
        validateColumnDefault(
          { ...column, isUniqueKey: column === uniqueKeyColumn },
          column.defaultValue,
        );
        if (column.defaultValue.kind === "literal" && column.sqlDomain !== undefined) {
          normalizeSqlDomainValue(column.sqlDomain, column.defaultValue.value);
        }
        if (column.defaultValue.kind === "expression") {
          validateDefaultExpression(column.defaultValue.sql, {
            name: `${name}.${column.name}`,
            type: column.type,
            ...(column.sqlDomain === undefined ? {} : { sqlDomain: column.sqlDomain }),
          });
        }
      }
    }
    const constraintNames = new Set<string>();
    const claimConstraintName = (rawName: string): string => {
      const constraintName = validateName(rawName, "Constraint");
      if (constraintNames.has(constraintName)) {
        throw new TypeError(`Constraint already exists: ${constraintName}`);
      }
      constraintNames.add(constraintName);
      return constraintName;
    };
    const foreignKeyNames = (input.foreignKeys ?? []).map((key) => claimConstraintName(key.name));
    const checkNames = (input.checks ?? []).map((check) => claimConstraintName(check.name));
    const uniqueConstraintNames = (input.uniqueConstraints ?? []).map((constraint) =>
      claimConstraintName(constraint.name),
    );
    const foreignKeys = await Promise.all(
      (input.foreignKeys ?? []).map(async (key, keyIndex) => {
        if (key.enforced === false && key.onDelete !== "restrict") {
          throw new TypeError(
            `Informational FOREIGN KEY ${key.name} cannot declare ON DELETE actions`,
          );
        }
        const childNames = key.columns ?? [key.column];
        const children = childNames.map((columnName) => {
          const column = columns.find((candidate) => candidate.name === columnName);
          if (column === undefined) {
            throw new TypeError(
              `FOREIGN KEY ${key.name} names a column this table has no: ${columnName}`,
            );
          }
          return column;
        });
        // Self-references are allowed, and then the parent is this very table, which does not
        // exist yet — its own declaration is the authority on the key.
        const parent =
          key.parentTable === name ? undefined : await this.store.getTableByName(key.parentTable);
        if (key.parentTable !== name && parent === undefined) {
          throw new TypeError(
            `FOREIGN KEY ${key.name} references a table that does not exist: ${key.parentTable}`,
          );
        }
        const parentColumns = parent === undefined ? columns : parent.columns;
        const parentPrimaryIds =
          parent === undefined
            ? compositePrimaryColumns.length > 0
              ? compositePrimaryColumns.map((column) => column.id)
              : uniqueKeyColumn === undefined
                ? []
                : [uniqueKeyColumn.id]
            : (parent.primaryKeyColumnIds ??
              (parent.uniqueKeyColumnId === undefined ? [] : [parent.uniqueKeyColumnId]));
        const parentPrimary = parentPrimaryIds
          .map((columnId) => parentColumns.find((column) => column.id === columnId))
          .filter((column): column is TableColumnRecord => column !== undefined && !column.hidden);
        if (parentPrimary.length === 0) {
          throw new TypeError(
            `FOREIGN KEY ${key.name} references a table with no unique key: ${key.parentTable}`,
          );
        }
        const requestedParentNames =
          key.parentColumns ??
          (key.parentColumn === undefined
            ? parentPrimary.map((column) => column.name)
            : [key.parentColumn]);
        if (
          requestedParentNames.length !== parentPrimary.length ||
          requestedParentNames.some(
            (columnName, index) => columnName !== parentPrimary[index]?.name,
          )
        ) {
          throw new TypeError(
            `FOREIGN KEY ${key.name} must reference ${key.parentTable}'s primary key (${parentPrimary.map((column) => column.name).join(", ")})`,
          );
        }
        if (children.length !== parentPrimary.length) {
          throw new TypeError(
            `FOREIGN KEY ${key.name} has ${String(children.length)} child columns for ${String(parentPrimary.length)} parent columns`,
          );
        }
        children.forEach((child, index) => {
          const parentKey = parentPrimary[index];
          if (parentKey === undefined) {
            throw new TypeError(`FOREIGN KEY ${key.name} is missing a parent key column`);
          }
          if (child.type !== parentKey.type) {
            throw new TypeError(
              `FOREIGN KEY ${key.name} compares ${child.type} with ${parentKey.type}`,
            );
          }
          if ((child.integer === true) !== (parentKey.integer === true)) {
            throw new TypeError(
              `FOREIGN KEY ${key.name} compares an integer domain with an approximate number domain`,
            );
          }
          if (
            JSON.stringify(child.sqlDomain ?? null) !== JSON.stringify(parentKey.sqlDomain ?? null)
          ) {
            throw new TypeError(`FOREIGN KEY ${key.name} compares different SQL value domains`);
          }
          if (key.onDelete === "set null" && !child.nullable) {
            throw new TypeError(`FOREIGN KEY ${key.name} cannot SET NULL a NOT NULL column`);
          }
        });
        const parentNames = parentPrimary.map((column) => column.name);
        return {
          name: foreignKeyNames[keyIndex] ?? key.name,
          columns: childNames,
          parentTable: key.parentTable,
          parentColumns: parentNames,
          onDelete: key.onDelete,
          ...(key.enforced === false ? { enforced: false } : {}),
        };
      }),
    );
    const checks = (input.checks ?? []).map((check, checkIndex) => {
      // Compiling here means a constraint the engine could never evaluate is refused at
      // definition rather than on the first write.
      const referencedColumns = expressionColumnNames(
        compileCheckExpression(check.sql, check.name),
      );
      for (const reference of referencedColumns) {
        const pieces = reference.split(".");
        const columnName = pieces.at(-1) ?? reference;
        const qualifier = pieces.length > 1 ? pieces.slice(0, -1).join(".") : undefined;
        if (qualifier !== undefined && qualifier !== name) {
          throw new TypeError(`CHECK ${check.name} references another table: ${reference}`);
        }
        if (!columns.some((column) => column.name === columnName && !column.hidden)) {
          throw new TypeError(`CHECK ${check.name} names an unknown column: ${columnName}`);
        }
      }
      return { name: checkNames[checkIndex] ?? check.name, sql: check.sql };
    });
    const tableId = this.#createId();
    const currentVersion = (await this.store.getCurrentManifest())?.version ?? -1;
    const secondaryIndexes: Record<string, SecondaryIndexRecord> = {};
    for (const [constraintIndex, constraint] of (input.uniqueConstraints ?? []).entries()) {
      const indexName = uniqueConstraintNames[constraintIndex] ?? constraint.name;
      const indexedColumns = constraint.columns.map((columnName) => {
        const column = columns.find(
          (candidate) => candidate.name === columnName && !candidate.hidden,
        );
        if (column === undefined) {
          throw new TypeError(`UNIQUE ${indexName} names an unknown column: ${columnName}`);
        }
        return column;
      });
      if (
        indexedColumns.length === 0 ||
        new Set(indexedColumns.map((column) => column.id)).size !== indexedColumns.length
      ) {
        throw new TypeError(`UNIQUE ${indexName} needs distinct columns`);
      }
      const indexId = this.#createId();
      secondaryIndexes[indexId] = {
        name: indexName,
        columnId: indexedColumns[0]?.id ?? "",
        columnIds: indexedColumns.map((column) => column.id),
        directions: indexedColumns.map(() => "asc" as const),
        unique: true,
        uniqueEnforced: true,
        termEncoding: "tuple-v1",
        storage: "postings-v1",
        storageColumnId: this.#createId(),
        locator: uniqueKeyColumn === undefined ? "row-id" : "key-hash-v1",
        state: "ready",
        buildFromVersion: currentVersion,
      };
    }
    await this.store.addTable({
      id: tableId,
      name,
      columns,
      revision: 0,
      managed: input.managed === true,
      ...(foreignKeys.length === 0 ? {} : { foreignKeys }),
      ...(checks.length === 0 ? {} : { checks }),
      ...(uniqueKeyColumn === undefined ? {} : { uniqueKeyColumnId: uniqueKeyColumn.id }),
      ...(uniqueKeyColumn === undefined ? {} : { uniqueKeyLookupReady: true }),
      ...(compositePrimaryColumns.length === 0
        ? {}
        : { primaryKeyColumnIds: compositePrimaryColumns.map((column) => column.id) }),
      ...(Object.keys(secondaryIndexes).length === 0 ? {} : { secondaryIndexes }),
      createdAt: dateIsoString(this.#now()),
    });
  }

  /**
   * The published catalog: stable column IDs, key identity, constraints, triggers, and view
   * bodies. This is the introspection surface schema tooling builds on — `listTables()` answers
   * what a reader can select, this answers what a planner needs to diff.
   */
  async introspect(): Promise<Catalog> {
    return toCatalog(await this.store.listTables());
  }

  async listTables(): Promise<TableDefinition[]> {
    return (await this.store.listTables())
      .filter((table) => table.enumType === undefined && table.sequence === undefined)
      .map((table) => {
        const uniqueKey = table.columns.find(
          (column) => column.id === table.uniqueKeyColumnId,
        )?.name;
        return {
          name: table.name,
          columns: visibleTableColumns(table).map((column) => ({
            name: column.name,
            type: column.type,
            ...(column.integer === true ? { integer: true } : {}),
            ...(column.sqlDomain === undefined
              ? {}
              : { sqlDomain: structuredClone(column.sqlDomain) }),
            nullable: column.nullable,
            ...(column.defaultValue === undefined ? {} : { defaultValue: column.defaultValue }),
            ...(column.generatedValue === undefined
              ? {}
              : { generatedValue: column.generatedValue }),
            ...(column.enumValues === undefined ? {} : { enumValues: [...column.enumValues] }),
          })),
          ...(uniqueKey === undefined ? {} : { uniqueKey }),
        };
      });
  }

  /**
   * Runs one simple write — insert, upsert, update, or delete — after every simple write this
   * database already has in flight. A stale trigger derivation restarts the whole statement so
   * it re-reads pre-images and re-runs trigger bodies at the fresh state.
   *
   * Commits are optimistic: a writer reads the manifest version, stages, and publishes only if
   * the version has not moved, rebasing and retrying otherwise up to `maxCommitRetries`.
   * Writers issued concurrently from one database used to all read the same version and spend
   * a retry per rival that landed first, so past `maxCommitRetries + 1` of them the rest failed
   * for nothing — contention this database need not create, and the queue does not. Writers in
   * other instances and other tabs still contend, and the retry loop is still what resolves
   * them. Write scopes are not queued: a scope's callback may issue a plain write of its own,
   * which must not wait on the scope that contains it.
   *
   * A complete background fold whose publication lost the manifest race takes its turn here
   * first, before the write's own statement, so the queue itself is what lands it (see
   * #withCompactionPublicationSlot). That runs before collection assistance: assistance can
   * wait on the collector, and the collector on that fold.
   */
  async #runWrite<T>(run: () => Promise<T>): Promise<T> {
    const restarting = async (): Promise<T> => {
      await this.#publishPendingCompactions();
      await this.#assistAutomaticCollection();
      for (let attempt = 0; ; attempt += 1) {
        try {
          return await run();
        } catch (error) {
          if (error instanceof SchemaConflictError) {
            if (attempt >= this.#maxCommitRetries) throw error;
            continue;
          }
          if (error instanceof UniqueIndexCoverageError) {
            if (attempt >= this.#maxCommitRetries) throw error;
            continue;
          }
          if (!(error instanceof StaleTriggerDerivationsError)) throw error;
          if (attempt >= this.#maxCommitRetries) throw error.conflict;
        }
      }
    };
    const previous = this.#writeChain;
    const current = previous.then(restarting, restarting);
    this.#writeChain = current;
    try {
      return await current;
    } finally {
      if (this.#writeChain === current) this.#writeChain = Promise.resolve();
    }
  }

  /**
   * Runs one publication attempt for a compaction as a writer of this database: the next
   * write — a queued simple write or a SQL statement's scope — runs it before its own work, and
   * an idle database runs it on the next event-loop turn, whichever comes first. Writers that
   * arrive while it runs wait for it, so only writers already in flight can commit between its
   * rebase and its commit, and the attempt retries against those without yielding.
   *
   * A retry on the fold's own event-loop turn is not enough. A caller that awaits one statement
   * after another keeps this database's write queue moving, so a rebase followed by a yield lost
   * the manifest race to the next write every time; on an in-memory store such a caller never
   * even reaches the macrotask queue, and the fold sat parked on its yield — its lease expiring
   * unrenewed — while every write scanned one more level-zero segment.
   */
  async #withCompactionPublicationSlot<T>(attempt: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      // The claim stays pending until the attempt has finished, not until it has started: a
      // writer that arrives while it is in flight waits for it. Otherwise, on a store where a
      // write is in flight for several event-loop turns, the turn claims the slot mid-write,
      // that write lands between the fold's rebase and its commit, the next write starts
      // unhindered, and the fold loses every retry to a writer it can never get ahead of.
      let settled: Promise<void> | undefined;
      const claim = (): Promise<void> => {
        settled ??= (async () => {
          try {
            resolve(await attempt());
          } catch (error) {
            reject(error instanceof Error ? error : new Error(String(error)));
          } finally {
            this.#pendingCompactionPublications.delete(claim);
          }
        })();
        return settled;
      };
      this.#pendingCompactionPublications.add(claim);
      void this.#eventLoopTurn().then(claim);
    });
  }

  /**
   * Runs, or waits for, every fold publication pending a turn; a claim never throws to its
   * runner. A writer calls this before it starts, so at most the writers already in flight
   * can commit under a publication attempt.
   */
  async #publishPendingCompactions(): Promise<void> {
    while (this.#pendingCompactionPublications.size > 0) {
      const [claim] = this.#pendingCompactionPublications;
      if (claim === undefined) return;
      await claim();
    }
  }

  /** The next event-loop turn, shared by everything waiting on it at once. */
  #eventLoopTurn(): Promise<void> {
    const pending = this.#pendingEventLoopTurn;
    if (pending !== undefined) return pending;
    const turn = yieldToEventLoop().then(() => {
      if (this.#pendingEventLoopTurn === turn) this.#pendingEventLoopTurn = undefined;
    });
    this.#pendingEventLoopTurn = turn;
    return turn;
  }

  /** Settles when this database next publishes a commit. */
  #nextLocalCommit(): Promise<void> {
    if (this.#commitSignal === undefined) {
      let resolve = (): void => undefined;
      const promise = new Promise<void>((settle) => {
        resolve = settle;
      });
      this.#commitSignal = { promise, resolve };
    }
    return this.#commitSignal.promise;
  }

  /**
   * The cooperative yield of background maintenance: the next event-loop turn, or the next
   * commit this database publishes, whichever comes first. The turn is what lets rendering,
   * timers, and other clients run between bounded steps. The commit is what keeps maintenance
   * moving under a caller that never yields — a loop awaiting one statement after another on an
   * in-memory store drains only microtasks, so a fold or a collection pass parked on a timer
   * or a MessageChannel alone made no progress at all, and the table grew by one segment per
   * commit until the write ceiling. Waking on the commit gives every such step one turn per
   * commit instead; a step is bounded, so a write still pays for at most one.
   */
  async #yieldMaintenance(): Promise<void> {
    await Promise.race([this.#eventLoopTurn(), this.#nextLocalCommit()]);
  }

  async #withWriteReservation<T>(run: () => Promise<T>): Promise<T> {
    if (this.#pendingWriteReservations >= MAX_DATABASE_PENDING_WRITES) {
      throw new RangeError(
        `A database cannot queue more than ${String(MAX_DATABASE_PENDING_WRITES)} writes; await a write for backpressure`,
      );
    }
    this.#pendingWriteReservations += 1;
    try {
      return await run();
    } finally {
      this.#pendingWriteReservations -= 1;
    }
  }

  async #withReadReservation<T>(run: () => Promise<T>): Promise<T> {
    if (this.#activeReadReservations >= MAX_DATABASE_ACTIVE_READS) {
      throw new DatabaseReadBacklogError(MAX_DATABASE_ACTIVE_READS);
    }
    this.#activeReadReservations += 1;
    try {
      return await run();
    } finally {
      this.#activeReadReservations -= 1;
    }
  }

  async #queryWithReadReservation(sql: string, options: QueryOptions): Promise<QueryResult> {
    throwIfAborted(options.signal);
    await this.#settleExpiredStatementTransaction();
    throwIfAborted(options.signal);
    // An open statement transaction routes through its session, which owns the reservation for
    // the actual execution. Avoid charging the same query twice at this public boundary.
    return this.#openTransaction === undefined
      ? this.#withReadReservation(() => this.#queryUnreserved(sql, options))
      : this.#queryUnreserved(sql, options);
  }

  /**
   * A persistent collector failure must not let obsolete history grow forever. The threshold is
   * intentionally far above the normal 64-commit cadence: only a genuinely unhealthy store pays
   * foreground latency, and a write is refused only after an assisted pass still fails.
   */
  async #assistAutomaticCollection(): Promise<void> {
    if (!this.#autoCollect && !this.#manualCollectionDebtInitialized) {
      const current = await this.store.getCurrentManifestVersion();
      const first = (await this.store.listManifestPage(null, 1)).records[0];
      if (current !== null && first !== undefined) {
        const distance = current - first.version;
        const durableDebt =
          distance >= this.#autoCollectionDebtLimitCommits
            ? this.#autoCollectionDebtLimitCommits
            : distance + 1;
        this.#autoCollectionDebtCommits = Math.max(this.#autoCollectionDebtCommits, durableDebt);
      }
      this.#manualCollectionDebtInitialized = true;
    }
    if (this.#autoCollectionDebtCommits < this.#autoCollectionDebtLimitCommits) return;
    if (!this.#autoCollect) {
      throw new MaintenanceBacklogError(
        this.#autoCollectionDebtCommits,
        "automatic collection is disabled; call collectGarbage() before writing again",
      );
    }
    // Foreground work is capped at one already-bounded collector run. If a very old database
    // needs more, the run requeues itself in the background and this write refuses before it
    // starts; foreground latency must not scale with the total retained history.
    this.#maybeScheduleAutoCollection(true);
    const task = this.#autoCollectionTask;
    if (task !== undefined) await task;
    if (this.#autoCollectionDebtCommits >= this.#autoCollectionDebtLimitCommits) {
      throw new MaintenanceBacklogError(
        this.#autoCollectionDebtCommits,
        this.#autoCollectionLastError?.message ?? "bounded collection assistance left a backlog",
      );
    }
  }

  /** Turns a storage namespace/token UNIQUE conflict into the public table/constraint error. */
  async #translateUniqueConflict(error: unknown): Promise<unknown> {
    if (!(error instanceof UniqueKeyConflictError)) return error;
    for (const table of await this.store.listTables()) {
      if (table.id === error.tableId) {
        const keyColumn = getUniqueKeyColumn(table);
        if (keyColumn !== undefined) {
          return new UniqueConstraintError(
            table.name,
            publicKeyName(table, keyColumn),
            error.keyToken,
          );
        }
      }
      for (const [indexId, index] of Object.entries(table.secondaryIndexes ?? {})) {
        if (
          index.unique !== true ||
          secondaryUniqueKeyNamespace(table.id, indexId) !== error.tableId
        ) {
          continue;
        }
        const columns = secondaryIndexColumnIds(index).map((columnId) =>
          table.columns.find((column) => column.id === columnId),
        );
        if (columns.some((column) => column === undefined)) return error;
        try {
          const presentColumns = columns as TableColumnRecord[];
          const values = decodeSecondaryTupleTerm(index, presentColumns, error.keyToken);
          const columnName =
            presentColumns.length === 1
              ? (presentColumns[0]?.name ?? index.name)
              : `(${presentColumns.map((column) => column.name).join(", ")})`;
          const value =
            values.length === 1
              ? (values[0] ?? error.keyToken)
              : `(${values
                  .map((entry) => (entry === null ? "NULL" : formatValue(entry)))
                  .join(", ")})`;
          return new UniqueConstraintError(
            table.name,
            columnName,
            value instanceof Date || typeof value !== "object" ? value : String(value),
          );
        } catch {
          return error;
        }
      }
    }
    return error;
  }

  /**
   * Defines a view: a query the catalog answers to by name (F031-02). The stored record carries
   * the query's inferred output schema, so a view answers the same questions a table does —
   * what a reader can select, and of what type — and the devtools rail lists it beside them.
   * Reads expand it into the query it stands for; writes to it are refused.
   */
  async createView(
    name: string,
    sql: string,
    options: { orReplace?: boolean; managed?: boolean } = {},
  ): Promise<void> {
    const viewName = validateName(name, "View");
    const plan = compileQuery(sql);
    let pinnedExistingId: string | null | undefined;
    for (let attempt = 0; ; attempt += 1) {
      const proof = await this.#stableCatalogProof();
      const existing = proof.records.find((record) => record.name === viewName);
      const existingId = existing?.id ?? null;
      if (pinnedExistingId === undefined) pinnedExistingId = existingId;
      else if (pinnedExistingId !== existingId) {
        throw new TableRecordConflictError(viewName, 0, existing?.revision ?? null);
      }
      if (existing !== undefined) {
        if (existing.view === undefined) throw new TypeError(`Table already exists: ${viewName}`);
        if (options.orReplace !== true) throw new TypeError(`View already exists: ${viewName}`);
      }
      assertViewDefinitionAcyclic(proof.records, viewName, plan);
      const schemas = catalogQuerySchemas(proof.records);
      const inferred = inferBlockSchema(plan, schemas);
      if (inferred.length === 0) {
        throw new TypeError(`A view needs at least one column: ${viewName}`);
      }
      if (existing !== undefined) {
        schemas.set(viewName, inferred);
        assertDependentViewsKeepSchema(proof.records, existing, schemas);
      }
      const columns = inferred.map((column, index) => {
        const previous = existing?.columns[index];
        return {
          id:
            previous !== undefined && querySchemasEqual([column], [previous])
              ? previous.id
              : this.#createId(),
          name: column.name,
          type: column.type,
          ...(column.integer === true ? { integer: true as const } : {}),
          ...(column.sqlDomain === undefined ? {} : { sqlDomain: column.sqlDomain }),
          nullable: true,
        };
      });
      const view = { sql, managed: options.managed === true };
      try {
        if (existing !== undefined) {
          await this.store.updateTable(existing.id, existing.revision, {
            columns,
            ftsColumns: null,
            secondaryIndexes: null,
            triggers: null,
            view,
            expectedCatalogEpoch: proof.catalogEpoch,
          });
        } else {
          await this.store.addTable(
            {
              id: this.#createId(),
              name: viewName,
              columns,
              view,
              managed: false,
              revision: 0,
              createdAt: dateIsoString(this.#now()),
            },
            { expectedCatalogEpoch: proof.catalogEpoch },
          );
        }
        this.#planCache.clear();
        return;
      } catch (error) {
        if (!(error instanceof TableRecordConflictError) || attempt >= this.#maxCommitRetries) {
          throw error;
        }
        if (existing !== undefined) {
          const current = await this.store.getTable(existing.id);
          if (current?.revision !== existing.revision) throw error;
        }
      }
    }
  }

  /** Removes a view. Returns whether one was dropped; `ifExists` makes a missing one no error. */
  async dropView(name: string, options: { ifExists?: boolean } = {}): Promise<boolean> {
    let pinnedId: string | undefined;
    for (let attempt = 0; ; attempt += 1) {
      const proof = await this.#stableCatalogProof();
      const record = proof.records.find((candidate) => candidate.name === name);
      if (record?.view === undefined) {
        if (pinnedId !== undefined) {
          throw new TableRecordConflictError(pinnedId, 0, record?.revision ?? null);
        }
        if (record !== undefined) throw new TypeError(`Not a view: ${name}`);
        if (options.ifExists === true) return false;
        throw new Error(`View not found: ${name}`);
      }
      pinnedId ??= record.id;
      if (record.id !== pinnedId) {
        throw new TableRecordConflictError(pinnedId, 0, record.revision);
      }
      const dependent = proof.records.find(
        (candidate) =>
          candidate.id !== record.id &&
          candidate.view !== undefined &&
          viewReadsTable(candidate.view.sql, record.name),
      );
      if (dependent !== undefined) {
        throw new TypeError(`Cannot drop ${record.name}: view ${dependent.name} reads it`);
      }
      try {
        await this.store.removeTable(record.id, record.revision, {
          expectedCatalogEpoch: proof.catalogEpoch,
        });
        this.#planCache.clear();
        return true;
      } catch (error) {
        if (!(error instanceof TableRecordConflictError) || attempt >= this.#maxCommitRetries) {
          throw error;
        }
      }
    }
  }

  /** Reads all catalog records under one epoch proof, retrying only the bounded read window. */
  async #stableCatalogProof(): Promise<{
    catalogEpoch: number;
    manifestVersion: number | null;
    records: TableRecord[];
  }> {
    for (let attempt = 0; ; attempt += 1) {
      const before = await this.store.getCatalogProbe();
      const records = await this.store.listTables();
      const after = await this.store.getCatalogProbe();
      if (
        before.catalogEpoch === after.catalogEpoch &&
        before.manifestVersion === after.manifestVersion
      ) {
        return {
          catalogEpoch: before.catalogEpoch,
          manifestVersion: before.manifestVersion,
          records,
        };
      }
      if (attempt >= this.#maxCommitRetries) {
        throw new TableRecordConflictError("catalog", before.catalogEpoch, after.catalogEpoch);
      }
    }
  }

  /**
   * Drops one non-key column in one storage transaction: catalog metadata and segment references
   * change with the successor manifest that retires the column's exclusively owned live blocks.
   * Payload bytes remain readable to historical leases until ordinary collection reclaims them.
   */
  async dropColumn(
    tableName: string,
    columnName: string,
    options: { ifExists?: boolean } = {},
  ): Promise<boolean> {
    let pinnedTableId: string | undefined;
    let pinnedColumnId: string | undefined;
    for (let attempt = 0; ; attempt += 1) {
      const catalogProof = await this.store.getCatalogProbe();
      const records = await this.store.listTables();
      if ((await this.store.getCatalogProbe()).catalogEpoch !== catalogProof.catalogEpoch) {
        if (attempt >= this.#maxCommitRetries) {
          throw new TableRecordConflictError(tableName, 0, null);
        }
        continue;
      }
      const table = records.find((record) => record.name === tableName);
      if (table === undefined || table.view !== undefined) {
        if (pinnedTableId !== undefined) {
          throw new TableRecordConflictError(pinnedTableId, 0, table?.revision ?? null);
        }
        if (table?.view !== undefined) throw new TypeError(`${tableName} is a view, not a table`);
        if (options.ifExists === true) return false;
        throw new UnknownTableError(tableName);
      }
      pinnedTableId ??= table.id;
      if (table.id !== pinnedTableId) {
        throw new TableRecordConflictError(pinnedTableId, 0, table.revision);
      }
      const column = table.columns.find((candidate) => candidate.name === columnName);
      if (column === undefined) {
        if (pinnedColumnId !== undefined) {
          throw new TableRecordConflictError(pinnedTableId, table.revision, table.revision);
        }
        if (options.ifExists === true) return false;
        throw new TypeError(`Column not found: ${tableName}.${columnName}`);
      }
      pinnedColumnId ??= column.id;
      if (column.id !== pinnedColumnId) {
        throw new TableRecordConflictError(pinnedTableId, table.revision, table.revision);
      }
      this.#assertColumnDropSafe(records, table, column);
      const buildKey = `${table.id}/${column.id}`;
      this.#droppingFtsColumns.add(buildKey);
      try {
        await this.#cancelTableCompactions(table.id);
        const manifest = await this.store.dropTableColumn({
          tableId: table.id,
          columnId: column.id,
          expectedTableRevision: table.revision,
          expectedManifestVersion: await this.store.getCurrentManifestVersion(),
          expectedCatalogEpoch: catalogProof.catalogEpoch,
          committedAt: dateIsoString(this.#now()),
        });
        this.#afterCommit(manifest);
        this.#gzipVerdicts.delete(column.id);
        this.#postingDeltaTailCounts.delete(buildKey);
        this.#planCache.clear();
        return true;
      } catch (error) {
        if (
          (!(error instanceof TableRecordConflictError) &&
            !(error instanceof TableInUseError) &&
            !(error instanceof WriteConflictError)) ||
          attempt >= this.#maxCommitRetries
        ) {
          throw error;
        }
      } finally {
        this.#droppingFtsColumns.delete(buildKey);
      }
    }
  }

  /** Refuses every catalog edge a dropped column would leave dangling. */
  #assertColumnDropSafe(
    records: readonly TableRecord[],
    table: TableRecord,
    column: TableColumnRecord,
  ): void {
    if (table.columns.length === 1) {
      throw new TypeError(`The last column cannot be dropped: ${table.name}.${column.name}`);
    }
    const catalogTable = toCatalog(records).tables.find(
      (candidate) => candidate.name === table.name,
    );
    const catalogColumn = catalogTable?.columns.find((candidate) => candidate.id === column.id);
    if (catalogTable === undefined || catalogColumn === undefined) {
      throw new Error(`Catalog column disappeared while dropping: ${table.name}.${column.name}`);
    }
    assertColumnDroppable(catalogTable, catalogColumn);
    const dependentIndex = Object.values(table.secondaryIndexes ?? {}).find((index) =>
      secondaryIndexColumnIds(index).includes(column.id),
    );
    if (dependentIndex !== undefined) {
      throw new TypeError(
        `Cannot drop ${table.name}.${column.name}: index ${dependentIndex.name} depends on it`,
      );
    }

    for (const owner of records) {
      if (owner.view !== undefined && viewReadsTable(owner.view.sql, table.name)) {
        const schemas = new Map(
          records.map((record) => [
            record.name,
            (record.id === table.id
              ? record.columns.filter((candidate) => candidate.id !== column.id)
              : record.columns
            ).map(({ name, type, integer, sqlDomain }) => ({
              name,
              type,
              ...(integer === true ? { integer: true as const } : {}),
              ...(sqlDomain === undefined ? {} : { sqlDomain }),
            })),
          ]),
        );
        try {
          const inferred = inferBlockSchema(compileQuery(owner.view.sql), schemas);
          const stored = owner.columns.map(({ name, type, integer, sqlDomain }) => ({
            name,
            type,
            ...(integer === true ? { integer: true as const } : {}),
            ...(sqlDomain === undefined ? {} : { sqlDomain }),
          }));
          if (JSON.stringify(inferred) !== JSON.stringify(stored)) {
            throw new TypeError("view output would change");
          }
        } catch {
          throw new TypeError(
            `Cannot drop ${table.name}.${column.name}: view ${owner.name} reads it`,
          );
        }
      }
      for (const trigger of owner.triggers ?? []) {
        if (triggerReferencesColumn(owner, trigger, table, column.name)) {
          throw new TypeError(
            `Cannot drop ${table.name}.${column.name}: trigger ${trigger.name} references it`,
          );
        }
      }
    }
  }

  /**
   * Drops a table: its rows, its catalog record, its full-text index, and its triggers. The
   * blocks are retired through an ordinary commit rather than deleted, so a reader pinned to an
   * older version keeps resolving the bytes it already holds and the lease-aware collector
   * reclaims them when nobody can reach them. What a pinned reader does lose is the table
   * itself — the catalog has one present tense, so a snapshot open across a drop sees the table
   * disappear rather than a frozen copy of it.
   *
   * Returns whether a table was dropped; with `ifExists`, a missing table is not an error.
   */
  async dropTable(tableName: string, options: { ifExists?: boolean } = {}): Promise<boolean> {
    let pinnedTableId: string | undefined;
    for (let attempt = 0; ; attempt += 1) {
      const catalogProof = await this.store.getCatalogProbe();
      const records = await this.store.listTables();
      if ((await this.store.getCatalogProbe()).catalogEpoch !== catalogProof.catalogEpoch) {
        if (attempt >= this.#maxCommitRetries) {
          throw new TableRecordConflictError(tableName, 0, null);
        }
        continue;
      }
      const table = records.find((record) => record.name === tableName);
      if (table === undefined) {
        if (pinnedTableId !== undefined) {
          throw new TableRecordConflictError(pinnedTableId, 0, null);
        }
        if (options.ifExists === true) return false;
        throw new UnknownTableError(tableName);
      }
      pinnedTableId ??= table.id;
      if (table.id !== pinnedTableId) {
        throw new TableRecordConflictError(pinnedTableId, 0, table.revision);
      }
      if (table.view !== undefined) throw new TypeError(`${tableName} is a view; use DROP VIEW`);
      // Anything that would be left pointing at the table refuses the drop. The catalog-epoch
      // CAS below makes this complete-catalog proof serializable with concurrent DDL.
      for (const owner of records) {
        if (owner.id === table.id) continue;
        if (owner.view !== undefined && viewReadsTable(owner.view.sql, table.name)) {
          throw new TypeError(`Cannot drop ${table.name}: view ${owner.name} reads it`);
        }
        for (const key of owner.foreignKeys ?? []) {
          if (key.parentTable === table.name) {
            throw new TypeError(
              `Cannot drop ${table.name}: foreign key ${key.name} on ${owner.name} references it`,
            );
          }
        }
        for (const trigger of owner.triggers ?? []) {
          const writesHere = trigger.statements.some((triggerStatement) => {
            const compiled = compileStatement(triggerStatement.sql);
            return (
              (compiled.kind === "insert" ||
                compiled.kind === "update" ||
                compiled.kind === "delete") &&
              compiled.table === table.name
            );
          });
          if (writesHere) {
            throw new TypeError(
              `Cannot drop ${table.name}: trigger ${trigger.name} on ${owner.name} writes to it`,
            );
          }
        }
      }
      this.#droppingTables.add(table.id);
      try {
        await this.#cancelTableCompactions(table.id);
        const manifest = await this.store.dropTable({
          tableId: table.id,
          expectedTableRevision: table.revision,
          expectedManifestVersion: await this.store.getCurrentManifestVersion(),
          expectedCatalogEpoch: catalogProof.catalogEpoch,
          committedAt: dateIsoString(this.#now()),
        });
        this.#afterCommit(manifest);
        for (const column of table.columns) this.#gzipVerdicts.delete(column.id);
        this.#autoCompactionBackoff.delete(table.id);
        this.#autoCompactionHints.delete(table.id);
        this.#commitsSinceCompactionCheck.delete(table.id);
        this.#idleCompactionTableIds.delete(table.id);
        const postingPrefix = `${table.id}/`;
        for (const key of this.#postingDeltaTailCounts.keys()) {
          if (key.startsWith(postingPrefix)) this.#postingDeltaTailCounts.delete(key);
        }
        this.#planCache.clear();
        return true;
      } catch (error) {
        if (
          (!(error instanceof TableRecordConflictError) &&
            !(error instanceof TableInUseError) &&
            !(error instanceof WriteConflictError)) ||
          attempt >= this.#maxCommitRetries
        ) {
          throw error;
        }
      } finally {
        this.#droppingTables.delete(table.id);
      }
    }
  }

  insertBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchInsertInput<TSchema, TName>,
  ): Promise<InsertBatchResult>;
  insertBatch(tableName: string, input: InsertBatchInputLike): Promise<InsertBatchResult> {
    return this.#withWriteReservation(() => this.#insertBatchReserved(tableName, input));
  }

  async #insertBatchReserved(
    tableName: string,
    input: InsertBatchInputLike,
  ): Promise<InsertBatchResult> {
    const completed = await this.#runWrite(async () => {
      const table = await this.#findTable(tableName);
      const { batch, generated, autoIncrement, rowCount } = await this.#fillDefaults(table, input);
      const keys =
        autoIncrement === undefined || autoIncrement.missingIndexes.length === 0
          ? batchKeys(table, batch)
          : undefined;
      const current = await this.store.getTable(table.id);
      if (current === undefined) throw new UnknownTableError(tableName);
      const result = await this.#writeBatch(current, batch, "insert", keys, autoIncrement);
      return { result, batch, generated, autoIncrement, rowCount };
    });
    const { result, batch, generated, autoIncrement, rowCount } = completed;
    collectAutoIncrementGenerated(batch, generated, autoIncrement);
    if (result.segmentId === null) throw new Error("An insert did not create a segment");
    return {
      tableName: result.tableName,
      segmentId: result.segmentId,
      rowCount,
      blockCount: result.blockCount,
      storedBytes: result.storedBytes,
      version: result.version,
      metrics: result.metrics,
      ...(generated.size === 0 ? {} : { generatedColumns: Object.fromEntries(generated) }),
    };
  }

  /** Pivots, evaluates SQL defaults, and validates — shared by insert and upsert. */
  async #fillDefaults(
    table: TableRecord,
    input: InsertBatchInputLike,
  ): Promise<FilledBatch & { rowCount: number }> {
    const pivoted = toColumnarBatch(input);
    // The pivot stamps rowCount, so an all-default batch keeps its row count even after the
    // columnar form crossed the worker boundary.
    const statementNow = this.#now();
    const filled = await fillColumnDefaults(
      table,
      pivoted,
      (sql) => this.#evaluateDefaultExpression(sql, statementNow),
      pivoted.rowCount,
    );
    const inputRowCount =
      pivoted.rowCount ??
      Object.values(pivoted.columns).find((values) => values.length > 0)?.length ??
      0;
    normalizeDomainBatch(table, filled.batch);
    fillStoredGeneratedColumns(table, filled.batch, inputRowCount, filled.generated);
    for (const name of filled.generated.keys()) {
      const column = table.columns.find((candidate) => candidate.name === name);
      const values = filled.batch.columns[name];
      if (column?.sqlDomain === undefined || values === undefined) continue;
      filled.generated.set(
        name,
        values.map((value) => externalSqlDomainValue(value) as BatchValue),
      );
    }
    fillCompositePrimaryKey(table, filled.batch, inputRowCount);
    const rowCount = validateBatch(table, filled.batch, filled.autoIncrement?.column.name);
    return { ...filled, rowCount };
  }

  /** Evaluates a validated catalog expression through the ordinary SQL execution pipeline. */
  async #evaluateDefaultExpression(sql: string, statementNow: Date): Promise<BatchValue> {
    let plan = this.#compileCached(`SELECT ${sql} AS value`);
    // CURRENT_* is statement-stable even though each omitted row evaluates the rest of its
    // expression separately. Sequence and volatile calls deliberately remain per row.
    plan = resolveStatementDatetimes(plan, statementNow);
    const result = await this.#queryCompiled(plan);
    const value = result.rows[0]?.value ?? null;
    if (
      value === null ||
      typeof value === "boolean" ||
      typeof value === "number" ||
      typeof value === "string" ||
      value instanceof Date
    ) {
      return value;
    }
    throw new TypeError(`DEFAULT produced an unsupported value: ${sql}`);
  }

  /** Materializes volatile/catalog-backed INSERT values once per execution, never in the cache. */
  async #materializeInsertExpressions(
    statement: Extract<CompiledStatement, { kind: "insert" }>,
    statementNow: Date,
  ): Promise<Extract<CompiledStatement, { kind: "insert" }>> {
    if (!statement.rows.some((row) => row.some(isDeferredInsertExpression))) return statement;
    const rows: InsertValue[][] = [];
    for (const row of statement.rows) {
      const materialized: InsertValue[] = [];
      for (const value of row) {
        if (!isDeferredInsertExpression(value)) {
          materialized.push(value);
          continue;
        }
        let plan: CompiledQuery = {
          sql: "(insert value)",
          base: { table: DUAL_TABLE, alias: DUAL_TABLE },
          joins: [],
          select: [{ expression: value.expression, alias: "value" }],
          predicates: [],
          groupBy: [],
          having: [],
          orderBy: [],
          usesStatementDatetime: true,
          usesSequenceCalls: true,
          usesVolatileFunctions: true,
        };
        // Every CURRENT_* occurrence in all rows sees the same statement clock. RANDOM,
        // GEN_RANDOM_UUID, and NEXTVAL remain per expression, as SQL requires.
        plan = resolveStatementDatetimes(plan, statementNow);
        const result = await this.#queryCompiled(plan, { memoize: false });
        materialized.push(result.rows[0]?.value ?? null);
      }
      rows.push(materialized);
    }
    return { ...statement, rows };
  }

  insert<TName extends TableName<TSchema>>(
    tableName: TName,
    row: BatchInsertRow<TSchema, TName>,
  ): Promise<InsertBatchResult>;
  async insert(tableName: string, row: BatchRow): Promise<InsertBatchResult> {
    return this.#erased.insertBatch(tableName, [row]);
  }

  upsertBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchInsertInput<TSchema, TName>,
    options?: BatchUpsertOptions<TSchema, TName>,
  ): Promise<UpsertBatchResult>;
  upsertBatch(
    tableName: string,
    input: InsertBatchInputLike,
    options: UpsertOptions = {},
  ): Promise<UpsertBatchResult> {
    return this.#withWriteReservation(() => this.#upsertBatchReserved(tableName, input, options));
  }

  async #upsertBatchReserved(
    tableName: string,
    input: InsertBatchInputLike,
    options: UpsertOptions,
  ): Promise<UpsertBatchResult> {
    const completed = await this.#runWrite(async () => {
      const table = await this.#findTable(tableName);
      const keyColumn = getUniqueKeyColumn(table);
      if (keyColumn === undefined) {
        throw new TypeError(`Table needs a unique key before it can be upserted: ${table.name}`);
      }
      const { batch, generated, autoIncrement } = await this.#fillDefaults(table, input);
      const deferred = autoIncrement !== undefined && autoIncrement.missingIndexes.length > 0;
      const keys = deferred ? undefined : batchKeys(table, batch);
      const current = await this.store.getTable(table.id);
      if (current === undefined) throw new UnknownTableError(tableName);
      const result = await this.#writeBatch(
        current,
        batch,
        "upsert",
        keys,
        autoIncrement,
        options.conflictWhere,
      );
      return { result, batch, generated, autoIncrement };
    });
    const { result, batch, generated, autoIncrement } = completed;
    collectAutoIncrementGenerated(batch, generated, autoIncrement);
    if (result.acceptedRowIndexes.length !== result.requestedRowCount) {
      remapGeneratedColumns(generated, result.acceptedRowIndexes);
    }
    return {
      tableName: result.tableName,
      segmentId: result.segmentId,
      requestedRowCount: result.requestedRowCount,
      rowCount: result.rowCount,
      insertedRowCount: result.insertedRowCount,
      updatedRowCount: result.updatedRowCount,
      skippedRowCount: result.skippedRowCount,
      blockCount: result.blockCount,
      storedBytes: result.storedBytes,
      version: result.version,
      metrics: result.metrics,
      ...(generated.size === 0 ? {} : { generatedColumns: Object.fromEntries(generated) }),
    };
  }

  upsert<TName extends TableName<TSchema>>(
    tableName: TName,
    row: BatchInsertRow<TSchema, TName>,
    options?: BatchUpsertOptions<TSchema, TName>,
  ): Promise<UpsertBatchResult>;
  async upsert(
    tableName: string,
    row: BatchRow,
    options: UpsertOptions = {},
  ): Promise<UpsertBatchResult> {
    return this.#erased.upsertBatch(tableName, [row], options);
  }

  updateBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchUpdateInput<TSchema, TName>,
  ): Promise<UpdateBatchResult>;
  updateBatch(tableName: string, input: UpdateBatchInputLike): Promise<UpdateBatchResult> {
    return this.#withWriteReservation(() =>
      this.#updateBatchReserved(tableName, compactUpdateBatchInput(input)),
    );
  }

  async #updateBatchReserved(
    tableName: string,
    input: UpdateBatchInput,
  ): Promise<UpdateBatchResult> {
    return this.#runWrite(async () => {
      const table = await this.#findTable(tableName);
      const keyColumn = getUniqueKeyColumn(table);
      if (keyColumn === undefined) {
        throw new TypeError(`Table needs a unique key before rows can be updated: ${table.name}`);
      }
      const normalizedInput = normalizeDomainUpdate(table, input);
      rejectGeneratedUpdateAssignments(table, normalizedInput);
      const keys = validateUpdateBatch(table, keyColumn, normalizedInput);
      const current = await this.store.getTable(table.id);
      if (current === undefined) throw new UnknownTableError(tableName);
      const currentKey = getUniqueKeyColumn(current);
      if (currentKey?.id !== keyColumn.id) {
        throw new TypeError(`Table unique key changed during update: ${tableName}`);
      }
      return this.#writeUpdateBatch(current, currentKey, normalizedInput, keys);
    });
  }

  /**
   * Changes one row by the table's unique key. An explicitly `undefined` change leaves that
   * column untouched, so a patch spread from optional fields needs no filtering first.
   */
  update<TName extends TableName<TSchema>>(
    tableName: TName,
    key: BatchKeyValue<TSchema, TName>,
    changes: BatchUpdateChanges<TSchema, TName>,
  ): Promise<UpdateBatchResult>;
  async update(
    tableName: string,
    key: Exclude<BatchValue, null>,
    changes: Readonly<Record<string, BatchValue | undefined>>,
  ): Promise<UpdateBatchResult> {
    return this.#erased.updateBatch(tableName, {
      keys: [key],
      changes: Object.fromEntries(
        Object.entries(changes).flatMap(([name, value]) =>
          value === undefined ? [] : [[name, [value]]],
        ),
      ),
    });
  }

  /** Deletes one row by the table's unique key. */
  delete<TName extends TableName<TSchema>>(
    tableName: TName,
    key: BatchKeyValue<TSchema, TName>,
  ): Promise<DeleteBatchResult>;
  async delete(tableName: string, key: Exclude<BatchValue, null>): Promise<DeleteBatchResult> {
    return this.#erased.deleteBatch(tableName, { keys: [key] });
  }

  deleteBatch<TName extends TableName<TSchema>>(
    tableName: TName,
    input: BatchDeleteInput<TSchema, TName>,
  ): Promise<DeleteBatchResult>;
  deleteBatch(tableName: string, input: DeleteBatchInput): Promise<DeleteBatchResult> {
    return this.#withWriteReservation(() => this.#deleteBatchReserved(tableName, input));
  }

  async #deleteBatchReserved(
    tableName: string,
    input: DeleteBatchInput,
  ): Promise<DeleteBatchResult> {
    return this.#runWrite(async () => {
      const table = await this.#findTable(tableName);
      const keyColumn = getUniqueKeyColumn(table);
      const keyDomain = keyColumn?.sqlDomain;
      const normalizedInput =
        keyDomain === undefined
          ? input
          : { keys: input.keys.map((value) => normalizeSqlDomainValue(keyDomain, value)) };
      const dependents = await this.#childForeignKeys(tableName);
      if (dependents.length === 0) return this.#deleteBatchOnce(tableName, normalizedInput);
      // E141-04: the referential actions and the delete itself publish as one commit.
      const started = performance.now();
      const { result, version } = await this.#erased.write(async (session) => {
        await this.#applyReferentialActions(
          table,
          [...normalizedInput.keys],
          session,
          REFERENTIAL_CASCADES,
        );
        return session.deleteBatch(tableName, normalizedInput);
      });
      return {
        tableName,
        segmentId: result.segmentId,
        requestedKeyCount: normalizedInput.keys.length,
        deletedRowCount: result.rowCount,
        blockCount: 0,
        storedBytes: 0,
        version,
        metrics: {
          logicalBytes: 0,
          storedBytes: 0,
          writeAmplification: 0,
          encodeMs: 0,
          stageMs: 0,
          commitMs: 0,
          totalMs: performance.now() - started,
          retries: 0,
          rowsPerSecond: 0,
        },
      };
    });
  }

  async #deleteBatchOnce(tableName: string, input: DeleteBatchInput): Promise<DeleteBatchResult> {
    const started = performance.now();
    const table = await this.#findTable(tableName);
    await this.#assertCompactionCapacity(table);
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) {
      throw new TypeError(`Table needs a unique key before rows can be deleted: ${table.name}`);
    }
    const keyDomain = keyColumn.sqlDomain;
    if (keyDomain !== undefined) {
      input = {
        keys: input.keys.map((value) => normalizeSqlDomainValue(keyDomain, value)),
      };
    }
    if (input.keys.length === 0) throw new TypeError("A delete batch needs at least one key");
    const keys = new Map<string, Exclude<BatchValue, null>>();
    const keyStringByteLengths =
      keyColumn.type === "string" ? new Array<number>(input.keys.length) : undefined;
    for (let index = 0; index < input.keys.length; index += 1) {
      const value = input.keys[index] as BatchValue;
      const byteLength = validateValue(keyColumn, value, index);
      if (keyStringByteLengths !== undefined) keyStringByteLengths[index] = byteLength ?? 0;
      if (value === null) throw new TypeError(`Unique key cannot be null: ${keyColumn.name}`);
      const token = keyToken(keyColumn.type, value);
      if (keys.has(token))
        throw new TypeError(`Duplicate key in delete batch: ${formatValue(value)}`);
      keys.set(token, value);
    }
    if (keyStringByteLengths !== undefined) {
      validatedStringByteLengths.set(input.keys, keyStringByteLengths);
    }
    const logicalBytes = estimateValuesBytes(input.keys);

    // Deferred: the record is written only if something stages in two steps (trigger rows),
    // and otherwise rides the single-shot commit below — or never exists, for a no-op delete.
    const transaction = await this.#transactions.beginDeferred({ durableSnapshot: false });
    transaction.limitLevelZeroSegments(table.id, MAX_LEVEL_ZERO_SEGMENTS);
    const blockStager = new BoundedWriteBlockStager(transaction);
    const segmentId = this.#createId();
    transaction.setUniqueKeyChanges({
      tableId: table.id,
      keyTokens: [...keys.keys()],
      requireAbsent: false,
      remove: true,
    });
    const secondaryCoverage = buildSecondaryDeleteCoverage(table);
    if (secondaryCoverage.length > 0) {
      transaction.setFtsChanges({ tableId: table.id, columns: secondaryCoverage });
    }
    let deletedRowCount: number;
    let storedBytes = 0;
    let blockCount = 0;
    let encodeMs = 0;
    let stageMs = 0;
    let commitMs = 0;
    let retries = 0;
    try {
      deletedRowCount = (
        await this.#existingKeyTokens(table, transaction.snapshotVersion, [...keys.keys()])
      ).size;
      if (deletedRowCount === 0) {
        await transaction.abort();
        return {
          tableName: table.name,
          segmentId: null,
          requestedKeyCount: keys.size,
          deletedRowCount: 0,
          blockCount: 0,
          storedBytes: 0,
          version: transaction.snapshotVersion,
          metrics: createWriteMetrics({
            logicalBytes,
            storedBytes: 0,
            encodeMs,
            stageMs,
            commitMs,
            totalMs: performance.now() - started,
            retries,
            rows: 0,
          }),
        };
      }

      const blockIds: string[] = [];
      const values = [...keys.values()];
      if (keyStringByteLengths !== undefined) {
        validatedStringByteLengths.set(values, keyStringByteLengths);
      }
      const plannedColumn = writeColumnValues(keyColumn.type, values);
      const ranges = writeBlockRanges(
        [plannedColumn],
        values.length,
        this.#rowsPerBlock,
        this.#targetBlockBytes,
      );
      for (const [part, { start, end }] of ranges.entries()) {
        await blockStager.prepare(maximumWriteBlockStoredBytes(plannedColumn, start, end, "raw"));
        const slice = values.slice(start, end);
        const encodeStarted = performance.now();
        const bytes = await this.#encodeColumnBlock(
          keyColumn.id,
          asColumnInput(keyColumn.type, slice),
          "raw",
        );
        encodeMs += performance.now() - encodeStarted;
        const blockId = [
          "table",
          table.id,
          "segment",
          segmentId,
          "delete-key",
          keyColumn.id,
          "part",
          String(part).padStart(6, "0"),
        ].join("/");
        blockStager.add({ id: blockId, bytes });
        blockIds.push(blockId);
        storedBytes += bytes.byteLength;
        blockCount += 1;
      }
      // Triggers fire once per row that actually exists: a requested key with no row deletes
      // nothing and must not fire a phantom all-null OLD image.
      const deletePreImages = (
        await this.#triggerPreImages(
          table,
          keyColumn,
          [...keys.values()],
          "delete",
          undefined,
          readyUniqueSecondaryIndexes(table).length > 0,
        )
      ).filter((row) => row !== undefined);
      stageSecondaryUniqueMutationChanges(transaction, table, undefined, deletePreImages);
      const deleteValueAt = (
        source: "new" | "old",
        column: string,
        rowIndex: number,
      ): BatchValue => (source === "old" ? (deletePreImages[rowIndex]?.[column] ?? null) : null);
      await this.#stageTriggerDerivedInserts(
        transaction,
        table,
        "delete",
        deletePreImages.length,
        deleteValueAt,
        "before",
      );
      const segment: SegmentRecord = {
        id: segmentId,
        tableId: table.id,
        transactionId: transaction.id,
        rowCount: keys.size,
        rowIdStart: 0n,
        rowIdEndExclusive: 0n,
        columnBlockIds: { [keyColumn.id]: blockIds },
        kind: "delete",
        keyColumnId: keyColumn.id,
        level: 0,
        logicalOrder: 0,
        commitOrdinal: transaction.pendingSegmentIds.length,
        rowIdSpans: [],
        createdAt: dateIsoString(this.#now()),
      };
      // AFTER triggers stage derived rows between the segment and the commit, which keeps the
      // two apart; without them the stage and the commit collapse into one storage write.
      const stagesAfter = firesAfterTriggers(table, "delete");
      const stageStarted = performance.now();
      if (stagesAfter) {
        await blockStager.stageWithSegments([segment]);
        await this.#stageTriggerDerivedInserts(
          transaction,
          table,
          "delete",
          deletePreImages.length,
          deleteValueAt,
          "after",
        );
      }
      stageMs += performance.now() - stageStarted + blockStager.earlyStageMs;

      for (let attempt = 0; attempt <= this.#maxCommitRetries; attempt += 1) {
        const commitStarted = performance.now();
        try {
          const manifest = stagesAfter
            ? await transaction.commit()
            : await transaction.stageArtifactsAndCommit(blockStager.pendingBlocks(), [segment]);
          commitMs += performance.now() - commitStarted;
          this.#afterCommit(manifest, transaction);
          return {
            tableName: table.name,
            segmentId,
            requestedKeyCount: keys.size,
            deletedRowCount,
            blockCount,
            storedBytes,
            version: manifest.version,
            metrics: createWriteMetrics({
              logicalBytes,
              storedBytes,
              encodeMs,
              stageMs,
              commitMs,
              totalMs: performance.now() - started,
              retries,
              rows: deletedRowCount,
            }),
          };
        } catch (error) {
          commitMs += performance.now() - commitStarted;
          if (!(error instanceof WriteConflictError) || attempt === this.#maxCommitRetries) {
            throw error;
          }
          if (deletePreImages.length > 0) throw new StaleTriggerDerivationsError(error);
          retries += 1;
          const snapshot = await transaction.rebase();
          deletedRowCount = (
            await this.#existingKeyTokens(table, snapshot.version, [...keys.keys()])
          ).size;
        }
      }
      throw new Error("Commit retry limit was exceeded");
    } catch (error) {
      await transaction.abort();
      throw await this.#translateUniqueConflict(error);
    }
  }

  bufferedWriter<TName extends TableName<TSchema>>(
    tableName: TName,
    options: BufferedWriterOptions = {},
  ): BufferedTableWriter<BatchInsertRow<TSchema, TName>> {
    return new BufferedTableWriter<BatchInsertRow<TSchema, TName>>(
      this.#erased,
      tableName,
      options,
    );
  }

  async #writeUpdateBatch(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    input: UpdateBatchInput,
    keys: Map<string, Exclude<BatchValue, null>>,
  ): Promise<UpdateBatchResult> {
    await this.#assertCompactionCapacity(table);
    const started = performance.now();
    let logicalBytes: number;
    // Deferred: the record rides the single-shot commit below unless trigger rows stage first.
    const transaction = await this.#transactions.beginDeferred({ durableSnapshot: false });
    transaction.limitLevelZeroSegments(table.id, MAX_LEVEL_ZERO_SEGMENTS);
    const blockStager = new BoundedWriteBlockStager(transaction);
    const segmentId = this.#createId();
    const columnBlockIds: Record<string, string[]> = {};
    let storedBytes = 0;
    let blockCount = 0;
    let encodeMs = 0;
    let stageMs = 0;
    let commitMs = 0;
    let retries = 0;

    try {
      await this.#assertKeysExist(table, keyColumn, transaction.snapshotVersion, keys);
      const checks = table.checks ?? [];
      let changedForeignKey = (table.foreignKeys ?? []).some(
        (key) =>
          key.enforced !== false &&
          foreignKeyColumns(key).some((column) => input.changes[column] !== undefined),
      );
      const preImages = await this.#triggerPreImages(
        table,
        keyColumn,
        input.keys.filter((key): key is Exclude<BatchValue, null> => key !== null),
        "update",
        (sql, params) => this.#sessionQuery(transaction, sql, { params }),
        checks.length > 0 ||
          changedForeignKey ||
          tableGeneratedExpressions(table).length > 0 ||
          secondaryIndexUpdateNeedsPreImages(table, input) ||
          readyUniqueSecondaryIndexes(table).some(({ columns }) =>
            columns.some((column) => input.changes[column.name] !== undefined),
          ),
      );
      input = applyStoredGeneratedUpdateChanges(table, input, preImages);
      validateUpdateBatch(table, keyColumn, input);
      changedForeignKey = (table.foreignKeys ?? []).some(
        (key) =>
          key.enforced !== false &&
          foreignKeyColumns(key).some((column) => input.changes[column] !== undefined),
      );
      logicalBytes =
        estimateValuesBytes(input.keys) +
        Object.values(input.changes).reduce(
          (total, values) => total + estimateValuesBytes(values),
          0,
        );
      const changedColumns = Object.keys(input.changes).sort();
      const columns = [keyColumn, ...changedColumns.map((name) => findColumn(table, name))];
      const plannedColumns = columns.map((column) =>
        writeColumnValues(
          column.type,
          column.id === keyColumn.id ? input.keys : (input.changes[column.name] ?? []),
        ),
      );
      const ranges = writeBlockRanges(
        plannedColumns,
        input.keys.length,
        this.#rowsPerBlock,
        this.#targetBlockBytes,
      );
      for (const [columnIndex, column] of columns.entries()) {
        const values = column.id === keyColumn.id ? input.keys : (input.changes[column.name] ?? []);
        const plannedColumn = plannedColumns[columnIndex];
        if (plannedColumn === undefined) {
          throw new Error(`Write column disappeared: ${column.name}`);
        }
        const blockIds: string[] = [];
        for (const [part, { start, end }] of ranges.entries()) {
          await blockStager.prepare(
            maximumWriteBlockStoredBytes(plannedColumn, start, end, this.#compression),
          );
          const slice = values.slice(start, end);
          const encodeStarted = performance.now();
          const bytes = await this.#encodeColumnBlock(column.id, asColumnInput(column.type, slice));
          encodeMs += performance.now() - encodeStarted;
          const blockId = [
            "table",
            table.id,
            "segment",
            segmentId,
            "update-column",
            column.id,
            "part",
            String(part).padStart(6, "0"),
          ].join("/");
          blockStager.add({ id: blockId, bytes });
          blockIds.push(blockId);
          storedBytes += bytes.byteLength;
          blockCount += 1;
        }
        columnBlockIds[column.id] = blockIds;
      }
      stageSecondaryUniqueMutationChanges(transaction, table, input, preImages);
      const secondaryDeltas = buildSecondaryUpdateDeltas(table, input, preImages);
      if (secondaryDeltas.length > 0) {
        transaction.setFtsChanges({ tableId: table.id, columns: secondaryDeltas });
      }
      const updateValueAt = (
        source: "new" | "old",
        column: string,
        rowIndex: number,
      ): BatchValue => {
        if (source === "old") return preImages[rowIndex]?.[column] ?? null;
        const changed = input.changes[column];
        return changed === undefined
          ? (preImages[rowIndex]?.[column] ?? null)
          : (changed[rowIndex] ?? null);
      };
      if (changedForeignKey) {
        await this.#assertForeignKeysPresent(
          table,
          (column) => input.keys.map((_, row) => updateValueAt("new", column, row)),
          (sql, params) => this.#sessionQuery(transaction, sql, { params }),
          transaction,
        );
      }
      // E141-06 on the write that changes a row rather than writes a whole one: the constraint
      // sees the post-image, the row as it will be once this update lands.
      if (checks.length > 0) {
        for (let rowIndex = 0; rowIndex < input.keys.length; rowIndex += 1) {
          if (preImages[rowIndex] === undefined) continue;
          const row: Record<string, BatchValue> = {};
          for (const column of table.columns) {
            row[column.name] = updateValueAt("new", column.name, rowIndex);
          }
          assertRowChecks(table, row, rowIndex);
        }
      }
      await this.#stageTriggerDerivedInserts(
        transaction,
        table,
        "update",
        input.keys.length,
        updateValueAt,
        "before",
      );
      const segment: SegmentRecord = {
        id: segmentId,
        tableId: table.id,
        transactionId: transaction.id,
        rowCount: input.keys.length,
        rowIdStart: 0n,
        rowIdEndExclusive: 0n,
        columnBlockIds,
        kind: "update",
        keyColumnId: keyColumn.id,
        level: 0,
        logicalOrder: 0,
        commitOrdinal: transaction.pendingSegmentIds.length,
        rowIdSpans: [],
        createdAt: dateIsoString(this.#now()),
      };
      // AFTER triggers stage derived rows between the segment and the commit, which keeps the
      // two apart; without them the stage and the commit collapse into one storage write.
      const stagesAfter = firesAfterTriggers(table, "update");
      const stageStarted = performance.now();
      if (stagesAfter) {
        await blockStager.stageWithSegments([segment]);
        await this.#stageTriggerDerivedInserts(
          transaction,
          table,
          "update",
          input.keys.length,
          updateValueAt,
          "after",
        );
      }
      stageMs += performance.now() - stageStarted + blockStager.earlyStageMs;

      for (let attempt = 0; attempt <= this.#maxCommitRetries; attempt += 1) {
        const commitStarted = performance.now();
        try {
          const manifest = stagesAfter
            ? await transaction.commit()
            : await transaction.stageArtifactsAndCommit(blockStager.pendingBlocks(), [segment]);
          commitMs += performance.now() - commitStarted;
          this.#afterCommit(manifest, transaction);
          return {
            tableName: table.name,
            segmentId,
            requestedRowCount: input.keys.length,
            updatedRowCount: input.keys.length,
            changedColumns,
            blockCount,
            storedBytes,
            version: manifest.version,
            ...(tableGeneratedExpressions(table).length === 0
              ? {}
              : {
                  generatedColumns: Object.fromEntries(
                    tableGeneratedExpressions(table).map(({ column }) => [
                      column.name,
                      (input.changes[column.name] ?? []).map(
                        (value) => externalSqlDomainValue(value) as BatchValue,
                      ),
                    ]),
                  ),
                }),
            metrics: createWriteMetrics({
              logicalBytes,
              storedBytes,
              encodeMs,
              stageMs,
              commitMs,
              totalMs: performance.now() - started,
              retries,
              rows: input.keys.length,
            }),
          };
        } catch (error) {
          commitMs += performance.now() - commitStarted;
          if (!(error instanceof WriteConflictError) || attempt === this.#maxCommitRetries) {
            throw error;
          }
          if (preImages.length > 0) throw new StaleTriggerDerivationsError(error);
          retries += 1;
          const snapshot = await transaction.rebase();
          await this.#assertKeysExist(table, keyColumn, snapshot.version, keys);
        }
      }
      throw new Error("Commit retry limit was exceeded");
    } catch (error) {
      await transaction.abort();
      throw await this.#translateUniqueConflict(error);
    }
  }

  async #assertKeysExist(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    version: number | null,
    keys: Map<string, Exclude<BatchValue, null>>,
  ): Promise<void> {
    const existing = await this.#existingKeyTokens(table, version, [...keys.keys()]);
    if (existing.size === keys.size) return;
    const missing = [...keys].find(([token]) => !existing.has(token));
    if (missing !== undefined) {
      throw new MissingKeyError(table.name, keyColumn.name, missing[1]);
    }
    throw new Error(`Unique-key lookup returned an inconsistent result: ${table.name}`);
  }

  async #writeBatch(
    table: TableRecord,
    input: ColumnarBatch,
    kind: "insert" | "upsert",
    keys: Map<string, Exclude<BatchValue, null>> | undefined,
    autoIncrement?: AutoIncrementFill,
    conflictWhere?: UpsertConflictWhere,
  ): Promise<UpsertBatchResult & { acceptedRowIndexes: number[] }> {
    await this.#assertCompactionCapacity(table);
    const started = performance.now();
    const requestedRowCount = input.columns[table.columns[0]?.name ?? ""]?.length ?? 0;
    let rowCount = requestedRowCount;
    let logicalBytes = estimateBatchBytes(input);
    const {
      transaction,
      rowIds: reservedRowIds,
      autoIncrementValues,
    } = await this.#transactions.beginWithReservation(
      { tableId: table.id, count: requestedRowCount },
      autoIncrement === undefined
        ? undefined
        : {
            tableId: table.id,
            columnId: autoIncrement.column.id,
            count: autoIncrement.missingIndexes.length,
            atLeast: autoIncrement.atLeast,
          },
    );
    transaction.limitLevelZeroSegments(table.id, MAX_LEVEL_ZERO_SEGMENTS);
    const blockStager = new BoundedWriteBlockStager(transaction);
    let resolvedKeys = keys;
    let segmentId: string | null = null;
    const columnBlockIds: Record<string, string[]> = {};
    let storedBytes = 0;
    let blockCount = 0;
    let counts: { inserted: number; updated: number } | undefined;
    let skippedRowCount = 0;
    let acceptedRowIndexes = Array.from({ length: requestedRowCount }, (_, index) => index);
    let upsertFirings: UpsertFirings | undefined;
    let encodeMs = 0;
    let stageMs = 0;
    let commitMs = 0;
    let retries = 0;

    try {
      if (autoIncrement !== undefined && autoIncrement.missingIndexes.length > 0) {
        // Generated values are assigned once here and survive commit-retry rebase unchanged,
        // exactly like reserved row ids; an abort burns the range and leaves a gap.
        const values =
          autoIncrementValues ??
          (await this.store.reserveAutoIncrement(
            table.id,
            autoIncrement.column.id,
            autoIncrement.missingIndexes.length,
            autoIncrement.atLeast,
          ));
        patchAutoIncrementValues(input, autoIncrement, values);
        // The pending column's nulls were exempted from pre-validation; the patched slots pass
        // the same validator as caller-supplied values, so every persisted slot is validated.
        const patched = input.columns[autoIncrement.column.name] ?? [];
        for (const rowIndex of autoIncrement.missingIndexes) {
          validateValue(autoIncrement.column, patched[rowIndex] ?? null, rowIndex);
        }
        resolvedKeys = batchKeys(table, input);
      }
      const normalizedConflictWhere =
        kind === "upsert" && conflictWhere !== undefined
          ? normalizeUpsertConflictWhere(table, conflictWhere)
          : undefined;
      const upsertKeyColumn = kind === "upsert" ? getUniqueKeyColumn(table) : undefined;
      if (upsertKeyColumn !== undefined) {
        upsertFirings = await this.#upsertTriggerFirings(
          table,
          upsertKeyColumn,
          input,
          rowCount,
          (sql, params) => this.#sessionQuery(transaction, sql, { params }),
          normalizedConflictWhere,
        );
      }
      if (normalizedConflictWhere !== undefined) {
        if (upsertFirings === undefined) {
          throw new Error("Upsert conflict classification is missing");
        }
        counts = { inserted: upsertFirings.inserts.length, updated: upsertFirings.updates.length };
        const filtered = applyUpsertConflictFilter(input, rowCount, upsertFirings);
        acceptedRowIndexes = filtered.acceptedRowIndexes;
        skippedRowCount = filtered.skippedRowCount;
        input = filtered.batch;
        rowCount = filtered.rowCount;
        upsertFirings = filtered.firings;
        logicalBytes = estimateBatchBytes(input);
        resolvedKeys = batchKeys(table, input);
        if (rowCount === 0) {
          await transaction.abort();
          const version = transaction.snapshotVersion;
          if (version === null) throw new Error("An existing table has no catalog version");
          return {
            tableName: table.name,
            segmentId: null,
            requestedRowCount,
            rowCount: 0,
            insertedRowCount: 0,
            updatedRowCount: 0,
            skippedRowCount,
            acceptedRowIndexes,
            blockCount: 0,
            storedBytes: 0,
            version,
            metrics: createWriteMetrics({
              logicalBytes: 0,
              storedBytes: 0,
              encodeMs: 0,
              stageMs: 0,
              commitMs: 0,
              totalMs: performance.now() - started,
              retries: 0,
              rows: 0,
            }),
          };
        }
      }
      if (resolvedKeys !== undefined) {
        transaction.setUniqueKeyChanges({
          tableId: table.id,
          keyTokens: [...resolvedKeys.keys()],
          requireAbsent: kind === "insert",
        });
      }
      const assertForeignKeys = (): Promise<void> =>
        this.#assertForeignKeysPresent(
          table,
          (column) => input.columns[column] ?? [],
          (sql, params) => this.#sessionQuery(transaction, sql, { params }),
          transaction,
        );
      // The proof belongs to the transaction that publishes the child row. Doing it after
      // generated values are patched also covers an auto-incremented referencing column, and
      // registering this batch's key membership first permits valid self-references.
      await assertForeignKeys();
      if (normalizedConflictWhere === undefined) {
        counts =
          kind === "insert" && resolvedKeys !== undefined
            ? { inserted: resolvedKeys.size, updated: 0 }
            : await this.#classifyKeys(table, transaction.snapshotVersion, kind, resolvedKeys);
      }
      if (counts === undefined) throw new Error("Write classification is missing");
      const reserved = reservedRowIds ?? (await this.store.reserveRowIds(table.id, rowCount));
      const rowIds = {
        start: reserved.start,
        endExclusive: reserved.start + BigInt(rowCount),
      };
      segmentId = this.#createId();
      // Insert batches maintain any active full-text index by tokenizing their own rows into a
      // commit delta. Other mutation kinds emit nothing on purpose: the store's stale-writer
      // rule then flips the index to "invalid" (keyed histories are unindexable) and the scan
      // path stays correct.
      if (kind === "insert") {
        const ftsDeltas = buildFtsColumnDeltas(table, input, rowIds.start);
        if (ftsDeltas.length > 0) {
          transaction.setFtsChanges({ tableId: table.id, columns: ftsDeltas });
        }
      }
      const secondaryDeltas = buildSecondaryInsertDeltas(table, input, rowIds.start);
      if (secondaryDeltas.length > 0) {
        transaction.setFtsChanges({ tableId: table.id, columns: secondaryDeltas });
      }
      const plannedColumns = table.columns.map((column) =>
        writeColumnValues(column.type, input.columns[column.name] ?? []),
      );
      const ranges = writeBlockRanges(
        plannedColumns,
        rowCount,
        this.#rowsPerBlock,
        this.#targetBlockBytes,
      );
      const plannedBlocks = table.columns.flatMap((column, columnIndex) => {
        const values = input.columns[column.name] ?? [];
        const plannedColumn = plannedColumns[columnIndex];
        if (plannedColumn === undefined)
          throw new Error(`Write column disappeared: ${column.name}`);
        columnBlockIds[column.id] = [];
        return ranges.map(({ start, end }, part) => ({
          column,
          values,
          plannedColumn,
          start,
          end,
          part,
          maximumStoredBytes: maximumWriteBlockStoredBytes(
            plannedColumn,
            start,
            end,
            this.#compression,
          ),
        }));
      });
      for (let next = 0; next < plannedBlocks.length;) {
        const group: typeof plannedBlocks = [];
        let maximumGroupBytes = 0;
        while (next < plannedBlocks.length && group.length < WRITE_ENCODE_CONCURRENCY) {
          const candidate = plannedBlocks[next];
          if (candidate === undefined) break;
          if (
            group.length > 0 &&
            maximumGroupBytes + candidate.maximumStoredBytes > MAX_TRANSACTION_STAGE_BYTES
          ) {
            break;
          }
          group.push(candidate);
          maximumGroupBytes += candidate.maximumStoredBytes;
          next += 1;
        }
        await blockStager.prepareBatch(group.length, maximumGroupBytes);
        const encodeStarted = performance.now();
        const encoded = await Promise.all(
          group.map(async ({ column, values, start, end, part }) => {
            const bytes = await this.#encodeColumnBlock(
              column.id,
              asColumnInput(column.type, values.slice(start, end)),
            );
            const blockId = [
              "table",
              table.id,
              "segment",
              segmentId,
              "column",
              column.id,
              "part",
              String(part).padStart(6, "0"),
            ].join("/");
            return { columnId: column.id, blockId, bytes };
          }),
        );
        encodeMs += performance.now() - encodeStarted;
        // Promise.all preserves column/range order even when native compressors finish out of
        // order. The group bound means their completed buffers plus the accumulator stay finite.
        for (const block of encoded) {
          blockStager.add({ id: block.blockId, bytes: block.bytes });
          columnBlockIds[block.columnId]?.push(block.blockId);
          storedBytes += block.bytes.byteLength;
          blockCount += 1;
        }
      }

      const segment: SegmentRecord = {
        id: segmentId,
        tableId: table.id,
        transactionId: transaction.id,
        rowCount,
        rowIdStart: rowIds.start,
        rowIdEndExclusive: rowIds.endExclusive,
        columnBlockIds,
        kind,
        ...(table.uniqueKeyColumnId === undefined ? {} : { keyColumnId: table.uniqueKeyColumnId }),
        level: 0,
        logicalOrder: 0,
        commitOrdinal: transaction.pendingSegmentIds.length,
        rowIdSpans: [],
        createdAt: dateIsoString(this.#now()),
      };
      const stageStarted = performance.now();
      const insertValueAt = (
        source: "new" | "old",
        column: string,
        rowIndex: number,
      ): BatchValue => (source === "new" ? (input.columns[column]?.[rowIndex] ?? null) : null);
      // Upserts fire per-row: INSERT triggers for fresh keys, UPDATE triggers (with the
      // replaced row as OLD) for conflicting ones — ON CONFLICT DO UPDATE semantics.
      stageSecondaryUniqueInsertChanges(
        transaction,
        table,
        input,
        kind === "upsert" ? upsertFirings?.oldImages : undefined,
      );
      if (kind === "insert") {
        await this.#stageTriggerDerivedInserts(
          transaction,
          table,
          "insert",
          rowCount,
          insertValueAt,
          "before",
        );
      } else if (upsertFirings !== undefined) {
        await this.#stageUpsertTriggerFirings(transaction, table, input, upsertFirings, "before");
      }
      // AFTER triggers stage derived rows between the segment and the commit, which keeps the
      // two apart; without them the stage and the commit collapse into one storage write.
      const stagesAfter =
        kind === "insert"
          ? firesAfterTriggers(table, "insert")
          : upsertFirings !== undefined && firesAfterTriggers(table, "insert", "update");
      if (stagesAfter) {
        await blockStager.stageWithSegments([segment]);
        if (kind === "insert") {
          await this.#stageTriggerDerivedInserts(
            transaction,
            table,
            "insert",
            rowCount,
            insertValueAt,
            "after",
          );
        } else if (upsertFirings !== undefined) {
          await this.#stageUpsertTriggerFirings(transaction, table, input, upsertFirings, "after");
        }
      }
      stageMs += performance.now() - stageStarted + blockStager.earlyStageMs;

      for (let attempt = 0; attempt <= this.#maxCommitRetries; attempt += 1) {
        const commitStarted = performance.now();
        try {
          const manifest = stagesAfter
            ? await transaction.commit()
            : await transaction.stageArtifactsAndCommit(blockStager.pendingBlocks(), [segment]);
          commitMs += performance.now() - commitStarted;
          this.#afterCommit(manifest, transaction);
          return {
            tableName: table.name,
            segmentId,
            requestedRowCount,
            rowCount,
            blockCount,
            storedBytes,
            version: manifest.version,
            insertedRowCount: counts.inserted,
            updatedRowCount: counts.updated,
            skippedRowCount,
            acceptedRowIndexes,
            metrics: createWriteMetrics({
              logicalBytes,
              storedBytes,
              encodeMs,
              stageMs,
              commitMs,
              totalMs: performance.now() - started,
              retries,
              rows: rowCount,
            }),
          };
        } catch (error) {
          commitMs += performance.now() - commitStarted;
          if (!(error instanceof WriteConflictError) || attempt === this.#maxCommitRetries) {
            throw error;
          }
          const stagedDerivations =
            kind === "insert"
              ? (table.triggers ?? []).some((trigger) => trigger.event === "insert")
              : upsertFirings !== undefined || conflictWhere !== undefined;
          if (stagedDerivations) throw new StaleTriggerDerivationsError(error);
          retries += 1;
          const snapshot = await transaction.rebase();
          // A parent may have disappeared in the commit that forced this rebase. Never carry
          // the old proof across that boundary: re-prove through the rebased transaction before
          // the child transaction gets another chance to publish.
          await assertForeignKeys();
          counts =
            kind === "insert" && resolvedKeys !== undefined
              ? { inserted: resolvedKeys.size, updated: 0 }
              : await this.#classifyKeys(table, snapshot.version, kind, resolvedKeys);
        }
      }
      throw new Error("Commit retry limit was exceeded");
    } catch (error) {
      await transaction.abort();
      if (error instanceof UniqueKeyConflictError && resolvedKeys !== undefined) {
        const keyColumn = getUniqueKeyColumn(table);
        const value = resolvedKeys.get(error.keyToken);
        if (keyColumn !== undefined && value !== undefined) {
          throw new UniqueConstraintError(table.name, publicKeyName(table, keyColumn), value);
        }
      }
      throw await this.#translateUniqueConflict(error);
    }
  }

  readTable<
    TName extends TableName<TSchema>,
    const TColumns extends ReadonlyArray<BatchColumnName<TSchema, TName>>,
  >(
    tableName: TName,
    options: BatchReadOptions<TSchema, TName, TColumns> & { readonly columns: TColumns },
  ): Promise<Array<Pick<BatchReadRow<TSchema, TName>, TColumns[number]>>>;
  readTable<TName extends TableName<TSchema>>(
    tableName: TName,
    versionOrOptions?: number | BatchReadOptions<TSchema, TName>,
  ): Promise<Array<BatchReadRow<TSchema, TName>>>;
  async readTable(
    tableName: string,
    versionOrOptions?: number | ReadTableOptions,
  ): Promise<DatabaseRow[]> {
    return this.#withReadReservation(() => this.#readTableUnreserved(tableName, versionOrOptions));
  }

  async #readTableUnreserved(
    tableName: string,
    versionOrOptions?: number | ReadTableOptions,
  ): Promise<DatabaseRow[]> {
    const table = await this.#findTable(tableName);
    const options =
      typeof versionOrOptions === "number" ? { version: versionOrOptions } : versionOrOptions;
    const columns = resolvePublicReadColumns(table, options?.columns);
    const rows = (await this.#materializeTable(table, options?.version, columns)).map((row) => {
      let output = row;
      for (const column of columns) {
        const value = row[column.name];
        if (
          column.type !== "string" ||
          column.sqlDomain !== undefined ||
          typeof value !== "string" ||
          !isSqlDomainValue(value)
        ) {
          continue;
        }
        if (output === row) output = { ...row };
        output[column.name] = protectedSqlTextValue(value);
      }
      return output;
    });
    return externalizeQueryResult({
      columns: columns.map(({ name }) => name),
      columnDomains: columns.map(({ sqlDomain }) => sqlDomain ?? null),
      rows,
    }).rows;
  }

  /**
   * Runs the callback against one pinned manifest version: every query inside the scope
   * observes the same committed state, however many commits land meanwhile. This is the
   * only pinning primitive — it cannot leak, because the pin is the scope. The version's
   * blocks stay protected by an internal reader lease for the scope's duration, renewed
   * while queries run; keep scopes short so garbage collection is not held back.
   *
   * On a database with no commits yet the session has no version to pin; its queries run
   * fresh, which is indistinguishable until the first commit.
   */
  async snapshot<T>(action: (session: SnapshotSession) => Promise<T>): Promise<T> {
    for (;;) {
      const version = await this.store.getCurrentManifestVersion();
      const entry = await this.#acquireSharedLease(version);
      if (entry === undefined) continue;
      try {
        const session: SnapshotSession = {
          version,
          query: (sql: string, options: QueryOptions = {}) =>
            this.#queryWithReadReservation(sql, {
              ...options,
              ...(version === null ? {} : { version }),
            }),
        };
        return await action(session);
      } finally {
        this.#releaseSharedLease(entry);
      }
    }
  }

  #compileCached(sql: string): CompiledQuery {
    const cacheable = sql.length <= MAX_CACHEABLE_TEXT_CHARACTERS;
    const cached = cacheable ? this.#planCache.get(sql) : undefined;
    if (cached !== undefined) {
      this.#planCache.delete(sql);
      this.#planCache.set(sql, cached);
      return cached;
    }
    const plan = compileQuery(sql);
    if (!cacheable) return plan;
    this.#planCache.set(sql, plan);
    if (this.#planCache.size > PLAN_CACHE_LIMIT) {
      const oldest = this.#planCache.keys().next().value;
      if (oldest !== undefined) this.#planCache.delete(oldest);
    }
    return plan;
  }

  #compileStatementCached(sql: string): CompiledStatement {
    const cacheable = sql.length <= MAX_CACHEABLE_TEXT_CHARACTERS;
    const cached = cacheable ? this.#statementCache.get(sql) : undefined;
    if (cached !== undefined) {
      this.#statementCache.delete(sql);
      this.#statementCache.set(sql, cached);
      return cached;
    }
    const statement = compileStatement(sql);
    if (!cacheable) return statement;
    this.#statementCache.set(sql, statement);
    if (this.#statementCache.size > PLAN_CACHE_LIMIT) {
      const oldest = this.#statementCache.keys().next().value;
      if (oldest !== undefined) this.#statementCache.delete(oldest);
    }
    return statement;
  }

  async #prepareCompiledPlan(
    plan: CompiledQuery,
    options: QueryOptions = {},
    probe?: CatalogProbe,
  ): Promise<PreparedQuery> {
    options = this.#effectiveQueryOptions(options);
    throwIfAborted(options.signal);
    // One statement clock for the whole plan tree, fixed before any nested block executes on
    // its own: a scalar subquery reading CURRENT_TIMESTAMP is resolved here, not left for the
    // executor that only ever sees the block it runs.
    if (plan.usesStatementDatetime === true) plan = resolveStatementDatetimes(plan, this.#now());
    // The ORDER-BY-expression desugar's wrapper is projection-only: prepare the inner block
    // directly (no derived materialization) and project each result to the visible aliases,
    // so `.search()` costs the same whether or not the caller also selects the score.
    const wrapper = transparentProjectionSource(plan);
    if (wrapper !== undefined) {
      const prepared = await this.#prepareCompiledPlan(wrapper.inner, options, probe);
      throwIfAborted(options.signal);
      return {
        sql: prepared.sql,
        tables: prepared.tables,
        get memoryUsage() {
          return prepared.memoryUsage;
        },
        execute: () => projectResultColumns(prepared.execute(), wrapper.aliases),
        executeAsync: async (asyncOptions) =>
          projectResultColumns(await prepared.executeAsync(asyncOptions), wrapper.aliases),
        executeBatches: (batchOptions, consume) =>
          prepared.executeBatches(batchOptions, (batch) =>
            consume(projectResultColumns(batch, wrapper.aliases)),
          ),
        close: () => prepared.close(),
      };
    }
    const memory = new QueryMemoryContext(options.executionMemoryBudgetBytes);
    try {
      let columnarTables = new Map<string, ColumnarTable>();
      let resolvedPlan = plan;
      let ftsStats: Map<string, FtsStats> | undefined;
      let outputNeedsExternalization = true;
      let outputColumnDomains: Array<SqlDomain | null> = [];
      const prepareAtSnapshot = async (
        snapshot: LeasedSnapshot,
        realTables: Map<string, TableRecord>,
        visibility: SegmentVisibilityCatalog,
      ): Promise<void> => {
        throwIfAborted(options.signal);
        const typedSchemas = new Map<string, SqlColumnSchema[]>(
          [...realTables.values()].map((table) => [
            table.name,
            table.columns.map(({ name, type, integer, sqlDomain }) => ({
              name,
              type,
              ...(integer === true ? { integer: true as const } : {}),
              ...(sqlDomain === undefined ? {} : { sqlDomain }),
            })),
          ]),
        );
        // MATCH(*)/BM25(*) expand against the catalog first — copy-on-write, so the compile
        // cache's plan (and the parity tests) keep "*" — and subquery resolution then collects
        // its steps from the expanded plan so substitutions land in the object that executes.
        const expandedPlan = expandFtsColumns(plan, (tableName) =>
          searchableFtsColumns(realTables.get(tableName)),
        );
        const resolution = subqueryResolutionSteps(expandedPlan);
        for (const step of resolution.steps) {
          throwIfAborted(options.signal);
          step.substitute(
            await this.#executeBlockCached(
              step.block,
              snapshot,
              visibility,
              memory,
              realTables,
              typedSchemas,
              options.memoize !== false,
              options.spillToStorage !== false,
              options.spillToStorage === true,
              options.spillPageRows,
              options.signal,
            ),
          );
          throwIfAborted(options.signal);
        }
        resolvedPlan = resolution.plan;
        // Index-served BM25 statistics, computed against the same catalog snapshot the pruner
        // reads, so a pruned scoring scan always carries exact corpus numbers.
        ftsStats = await this.#ftsIndexStats(resolvedPlan, realTables, snapshot, visibility);
        throwIfAborted(options.signal);
        columnarTables = await this.#prepareBlockInputs(
          resolvedPlan,
          snapshot,
          visibility,
          memory,
          realTables,
          typedSchemas,
          undefined,
          // memoize: false means "compute this statement's results" — that covers the
          // columnar forms of derived and windowed sources too, not just the result memo.
          options.memoize !== false,
          options.spillToStorage !== false,
          options.spillToStorage === true,
          options.spillPageRows,
          options.signal,
        );
        throwIfAborted(options.signal);
        // After input preparation, because executing the nested blocks registered their
        // synthetic source schemas in typedSchemas — same reasoning as the domain inference.
        resolvedPlan = annotateAvgArgumentScales(resolvedPlan, typedSchemas);
        outputNeedsExternalization = queryResultNeedsExternalization(resolvedPlan, typedSchemas);
        outputColumnDomains = inferResultColumnDomains(resolvedPlan, typedSchemas);
      };
      if (options.version !== undefined) {
        // Explicit time travel keeps the per-call lease and version-anchored reads.
        const realTables = await this.#findRealBlockTables(plan);
        throwIfAborted(options.signal);
        await this.#withLeasedSnapshot(options.version, async (snapshot) => {
          const visibility = await this.#blockSegmentVisibility(realTables);
          throwIfAborted(options.signal);
          await prepareAtSnapshot(snapshot, realTables, visibility);
        });
      } else {
        await this.#withSharedCatalogSnapshot(
          collectRealTableNames(plan),
          prepareAtSnapshot,
          probe,
        );
      }
      throwIfAborted(options.signal);
      return createPreparedColumnarQuery(
        chooseJoinOrder(resolvedPlan, columnarTables),
        columnarTables,
        memory,
        {
          ...(ftsStats === undefined ? {} : { ftsStats }),
          outputNeedsExternalization,
          outputColumnDomains,
        },
      );
    } catch (error) {
      memory.close();
      throw error;
    }
  }

  /**
   * Reads the catalog state every prepare needs in one coherent store read, then runs the
   * action under a shared internal reader lease anchored to that state's manifest version.
   * The lease is reused across prepares at the same version, so steady-state preparation
   * costs one catalog read instead of per-record round trips plus lease create/release
   * write transactions. If the manifest is pruned between the read and the lease, the
   * state is re-read.
   */
  async #withSharedCatalogSnapshot<T>(
    names: readonly string[],
    action: (
      snapshot: LeasedSnapshot,
      realTables: Map<string, TableRecord>,
      visibility: SegmentVisibilityCatalog,
    ) => Promise<T>,
    probe?: CatalogProbe,
  ): Promise<T> {
    if (names.length > MAX_STORAGE_BULK_READ_ITEMS) {
      throw new RangeError(
        `A query cannot reference more than ${String(MAX_STORAGE_BULK_READ_ITEMS)} tables`,
      );
    }
    for (;;) {
      const state = await this.#cachedCatalogState(names, probe);
      let prepared = this.#preparedCatalogStates.get(state);
      if (prepared === undefined) {
        const realTables = new Map<string, TableRecord>();
        names.forEach((name, index) => {
          const table = state.tables[index];
          if (table === undefined) throw new UnknownTableError(name);
          realTables.set(table.name, table);
        });
        const segmentsByTable = new Map<string, SegmentRecord[]>();
        for (const segment of state.segments) {
          const tableSegments = segmentsByTable.get(segment.tableId) ?? [];
          tableSegments.push(segment);
          segmentsByTable.set(segment.tableId, tableSegments);
        }
        prepared = {
          realTables,
          visibility: {
            transactions: new Map(state.transactions.map((record) => [record.id, record] as const)),
            segmentsByTable,
          },
        };
        this.#preparedCatalogStates.set(state, prepared);
      }
      const entry = await this.#acquireSharedLease(state.manifestVersion);
      if (entry === undefined) {
        // The manifest disappeared between the read and the lease, so the cached state is
        // anchored to a pruned version; drop it and re-read.
        this.#catalogStateCache.clear();
        this.#catalogStateEpoch = undefined;
        continue;
      }
      try {
        return await action(entry.lease, prepared.realTables, prepared.visibility);
      } finally {
        this.#releaseSharedLease(entry);
      }
    }
  }

  /**
   * The catalog freshness probe: one atomic (version, epoch) read decides whether the cached
   * catalog state is provably identical to a fresh read. An unchanged epoch means no table
   * record, manifest publish, or commit has landed anywhere — this tab or another — since the
   * cached state was read, so reuse is exact, not heuristic. Entries key on the requested
   * table-name set; a changed epoch clears them all.
   */
  async #cachedCatalogState(
    names: readonly string[],
    probe?: CatalogProbe,
  ): Promise<QueryCatalogState> {
    // A probe the caller read moments earlier in the same statement serves: a state read under
    // it is at least as fresh, and the cache is only consulted under its epoch.
    const { catalogEpoch } = probe ?? (await this.store.getCatalogProbe());
    // Table names are only trimmed, never charset-restricted, so no join separator is
    // collision-free; JSON encoding is.
    const key = JSON.stringify(names);
    if (catalogEpoch === this.#catalogStateEpoch) {
      const cached = this.#catalogStateCache.get(key);
      if (cached !== undefined) {
        this.#catalogStateCache.delete(key);
        this.#catalogStateCache.set(key, cached);
        return cached;
      }
    }
    const state = await this.#queryCatalogState(names);
    // Only a state carrying its own epoch (read atomically with the records) can be cached;
    // the sequential fallback shape cannot prove which epoch it observed.
    if (state.catalogEpoch === undefined) return state;
    if (state.catalogEpoch !== this.#catalogStateEpoch) {
      this.#catalogStateCache.clear();
      this.#catalogStateEpoch = state.catalogEpoch;
    }
    this.#catalogStateCache.set(key, state);
    if (this.#catalogStateCache.size > CATALOG_STATE_CACHE_LIMIT) {
      const oldest = this.#catalogStateCache.keys().next().value;
      if (oldest !== undefined) this.#catalogStateCache.delete(oldest);
    }
    return state;
  }

  /** One coherent catalog read assembled from bounded pages under a stable epoch probe. */
  async #queryCatalogState(names: readonly string[]): Promise<QueryCatalogState> {
    const atomic = this.store.getQueryCatalogState?.bind(this.store);
    if (atomic !== undefined) return atomic(names);
    for (;;) {
      const before = await this.store.getCatalogProbe();
      // The version is read first so the segment listing is a superset of that version's
      // committed records; exact manifest membership filters physical reads later.
      const manifestVersion = before.manifestVersion;
      const tables = await Promise.all(names.map((name) => this.store.getTableByName(name)));
      const found = tables.filter((table): table is TableRecord => table !== undefined);
      const segments = await this.#listSegmentsForTableIds(found.map((table) => table.id));
      const transactions = await this.#transactionRecordsForSegments(segments);
      const after = await this.store.getCatalogProbe();
      if (before.catalogEpoch === after.catalogEpoch && manifestVersion === after.manifestVersion) {
        return {
          manifestVersion,
          tables,
          segments,
          transactions,
          catalogEpoch: after.catalogEpoch,
        };
      }
      await this.#yieldMaintenance();
    }
  }

  /**
   * Reuses the shared internal reader lease when it targets the requested version and has
   * not expired. Otherwise the pin has to move: with no reader left on the old version the
   * one lease record is re-pinned in place (one storage write, instead of a create now and a
   * remove once the old one drains); while readers remain, a fresh lease opens at the exact
   * version and the old one retires as they finish. Returns undefined when the version's
   * manifest disappeared between the catalog read and the lease, so the caller can re-read.
   */
  async #acquireSharedLease(version: number | null): Promise<SharedLeaseEntry | undefined> {
    if (this.#closed) throw new Error("Database is closed");
    this.#sharedLeaseAcquisitions += 1;
    try {
      for (;;) {
        // A move in flight is closing the shared snapshot it re-pins; wait for it rather than
        // hand that snapshot out, then look again.
        if (this.#sharedLeaseMove !== undefined) {
          await this.#sharedLeaseMove;
          continue;
        }
        const current = this.#sharedLease;
        if (
          current?.version === version &&
          dateMilliseconds(current.lease.expiresAt) - dateMilliseconds(this.#now()) > 0
        ) {
          current.refCount += 1;
          this.#sharedLeaseUses += 1;
          try {
            await this.#renewInternalLeaseIfNeeded(current.lease);
            return current;
          } catch (error) {
            this.#releaseSharedLease(current);
            throw error;
          }
        }
        const options = {
          id: `${this.#internalLeaseOwnerId}/${crypto.randomUUID()}`,
          ownerId: this.#internalLeaseOwnerId,
          ttlMs: INTERNAL_READ_LEASE_TTL_MS,
          version,
        };
        let lease: LeasedSnapshot;
        try {
          if (current?.refCount === 0) {
            const move = this.#transactions.moveLeasedSnapshot(current.lease, options);
            this.#sharedLeaseMove = move.then(
              () => undefined,
              () => undefined,
            );
            try {
              lease = await move;
            } finally {
              this.#sharedLeaseMove = undefined;
            }
          } else {
            lease = await this.#transactions.openLeasedSnapshot(options);
          }
        } catch (error) {
          if (error instanceof SnapshotManifestMissingError) return undefined;
          throw error;
        }
        const entry: SharedLeaseEntry = { lease, version, refCount: 1 };
        this.#sharedLeaseUses += 1;
        const previous = this.#sharedLease;
        this.#sharedLease = entry;
        if (previous?.refCount === 0) {
          // Already closed when it was the one just moved; a remove otherwise.
          this.#trackSharedLeaseRelease(previous.lease.release());
        }
        return entry;
      }
    } finally {
      this.#sharedLeaseAcquisitions -= 1;
      this.#signalSharedLeaseStateChange();
    }
  }

  /**
   * Drops the shared reader lease when nothing holds it and it has fallen behind the current
   * version. The lease outlives the query that took it so the next query at the same version
   * reuses it — but after a burst of writes and a fold, an idle database's last lease sits at a
   * pre-fold version and roots every block that version referenced, which is exactly what a
   * collection pass is trying to reclaim. The next query simply takes a fresh lease.
   */
  #releaseIdleSharedLease(): void {
    const current = this.#sharedLease;
    if (current?.refCount !== 0) return;
    this.#sharedLease = undefined;
    this.#trackSharedLeaseRelease(current.lease.release());
  }

  #releaseSharedLease(entry: SharedLeaseEntry): void {
    entry.refCount -= 1;
    this.#sharedLeaseUses -= 1;
    if (entry.refCount < 0 || this.#sharedLeaseUses < 0) {
      throw new Error("Shared lease reference accounting underflow");
    }
    if (entry.refCount === 0 && entry !== this.#sharedLease) {
      this.#trackSharedLeaseRelease(entry.lease.release());
    }
    this.#signalSharedLeaseStateChange();
  }

  #trackSharedLeaseRelease(release: Promise<void>): void {
    this.#sharedLeaseReleases.add(release);
    void release.then(
      () => this.#sharedLeaseReleases.delete(release),
      () => this.#sharedLeaseReleases.delete(release),
    );
  }

  #sharedLeaseStateChange(): Promise<void> {
    return new Promise((resolve) => this.#sharedLeaseStateWaiters.add(resolve));
  }

  #signalSharedLeaseStateChange(): void {
    for (const resolve of this.#sharedLeaseStateWaiters) resolve();
    this.#sharedLeaseStateWaiters.clear();
  }

  /** Collects every real table referenced by a block, its derived sources, or its subqueries. */
  async #findRealBlockTables(plan: CompiledQuery): Promise<Map<string, TableRecord>> {
    const names = collectRealTableNames(plan);
    const tables = await Promise.all(names.map((name) => this.#findTable(name)));
    return new Map(tables.map((table) => [table.name, table]));
  }

  async #blockSegmentVisibility(
    realTables: ReadonlyMap<string, TableRecord>,
  ): Promise<SegmentVisibilityCatalog> {
    const tableIds = new Set([...realTables.values()].map((table) => table.id));
    const segmentRecords = await this.#listSegmentsForTableIds([...tableIds]);
    const transactionRecords = await this.#transactionRecordsForSegments(segmentRecords);
    const segmentsByTable = new Map<string, SegmentRecord[]>();
    for (const segment of segmentRecords) {
      if (!tableIds.has(segment.tableId)) continue;
      const tableSegments = segmentsByTable.get(segment.tableId) ?? [];
      tableSegments.push(segment);
      segmentsByTable.set(segment.tableId, tableSegments);
    }
    return {
      transactions: new Map(transactionRecords.map((record) => [record.id, record] as const)),
      segmentsByTable,
    };
  }

  /**
   * Reads only the requested tables' segment indexes. A multi-table query must not scan every
   * unrelated table's history; the small concurrency window also prevents a generated query
   * with many joins from issuing an unbounded burst of adapter requests.
   */
  async #listSegmentsForTableIds(tableIds: readonly string[]): Promise<SegmentRecord[]> {
    const uniqueIds = [...new Set(tableIds)];
    const segments: SegmentRecord[] = [];
    for (let offset = 0; offset < uniqueIds.length; offset += CATALOG_SEGMENT_READ_CONCURRENCY) {
      const page = uniqueIds.slice(offset, offset + CATALOG_SEGMENT_READ_CONCURRENCY);
      const listed = await Promise.all(
        page.map((tableId) => listTableSegmentsPaged(this.store, tableId)),
      );
      for (const tableSegments of listed) segments.push(...tableSegments);
    }
    return segments;
  }

  /**
   * Builds one block's columnar inputs: derived sources execute first at the same snapshot and
   * become typed in-memory tables under their synthetic names, then the block's real tables
   * materialize their referenced columns. Each block resolves its own inputs, so one real table
   * projected differently by two blocks never collides.
   */
  async #prepareBlockInputs(
    block: CompiledQuery,
    snapshot: LeasedSnapshot,
    visibility: SegmentVisibilityCatalog,
    memory: QueryMemoryContext,
    realTables: ReadonlyMap<string, TableRecord>,
    typedSchemas: Map<string, SqlColumnSchema[]>,
    extraInputs?: ReadonlyMap<string, ColumnarTable>,
    cacheResults = true,
    allowSpill = true,
    forceSpill = false,
    spillPageRows?: number,
    signal?: AbortSignal,
  ): Promise<Map<string, ColumnarTable>> {
    throwIfAborted(signal);
    const inputs = new Map<string, ColumnarTable>(extraInputs ?? []);
    const sources = [block.base, ...block.joins];
    for (const source of sources) {
      throwIfAborted(signal);
      if (inputs.has(source.table)) continue;
      if (source.recursive !== undefined) {
        const { reference, base, step, all } = source.recursive;
        const { result: baseResult, schema } = await this.#executeBlockWithSchemaCached(
          base,
          snapshot,
          visibility,
          memory,
          realTables,
          typedSchemas,
          cacheResults,
          allowSpill,
          forceSpill,
          spillPageRows,
          signal,
        );
        typedSchemas.set(reference, schema);
        const state = createRecursiveCteState(baseResult, all);
        while (state.frontier.length > 0) {
          throwIfAborted(signal);
          // Each iteration's inputs release with its own context, so only the accumulated rows
          // and the final columnar table hold memory across the fixpoint loop.
          const iterationMemory = memory.createChild();
          try {
            const frontierTable = derivedColumnarTable(
              reference,
              {
                columns: [...state.columns],
                columnDomains: schema.map(({ sqlDomain }) => sqlDomain ?? null),
                rows: state.frontier,
              },
              schema,
            );
            state.absorb(
              await this.#executeBlock(
                step,
                snapshot,
                visibility,
                iterationMemory,
                realTables,
                typedSchemas,
                new Map([[reference, frontierTable]]),
                cacheResults,
                allowSpill,
                forceSpill,
                spillPageRows,
                signal,
              ),
            );
          } finally {
            iterationMemory.close();
          }
        }
        typedSchemas.set(source.table, schema);
        inputs.set(
          source.table,
          derivedColumnarTable(
            source.table,
            {
              columns: [...state.columns],
              columnDomains: schema.map(({ sqlDomain }) => sqlDomain ?? null),
              rows: state.rows,
            },
            schema,
          ),
        );
        continue;
      }
      if (source.union !== undefined) {
        const results: QueryResult[] = [];
        let schema: SqlColumnSchema[] | undefined;
        for (const member of source.union.blocks) {
          throwIfAborted(signal);
          const { result, schema: memberSchema } = await this.#executeBlockWithSchemaCached(
            member,
            snapshot,
            visibility,
            memory,
            realTables,
            typedSchemas,
            cacheResults,
            allowSpill,
            forceSpill,
            spillPageRows,
            signal,
          );
          if (schema === undefined) schema = memberSchema;
          else {
            if (memberSchema.length !== schema.length) {
              throw new TypeError("UNION members must select the same number of columns");
            }
            memberSchema.forEach((column, index) => {
              const expected = schema?.[index];
              if (expected === undefined) return;
              if (
                column.type === expected.type &&
                column.sqlDomain?.kind === "numeric" &&
                expected.sqlDomain?.kind === "numeric"
              ) {
                // Two exact NUMERIC members union regardless of declared precision or scale,
                // as in PostgreSQL; a mismatch leaves the combined column unconstrained.
                if (JSON.stringify(column.sqlDomain) !== JSON.stringify(expected.sqlDomain)) {
                  schema = schema?.map((entry, position) =>
                    position === index ? { ...entry, sqlDomain: { kind: "numeric" } } : entry,
                  );
                }
                return;
              }
              if (
                column.type !== expected.type ||
                JSON.stringify(column.sqlDomain ?? null) !==
                  JSON.stringify(expected.sqlDomain ?? null)
              ) {
                throw new TypeError(`UNION member column types must match: ${expected.name}`);
              }
            });
          }
          results.push(result);
        }
        const combined = combineUnionResults(results, source.union.ops);
        typedSchemas.set(source.table, schema ?? []);
        inputs.set(source.table, derivedColumnarTable(source.table, combined, schema ?? []));
        continue;
      }
      if (source.windowed !== undefined) {
        // The windowed source's columnar form is a pure function of the inner block's cache
        // key plus the window spec, so a warm repeat skips the window pass and the
        // rows-to-columnar conversion entirely.
        const innerKey = await this.#blockResultCacheKey(
          source.windowed.block,
          snapshot,
          visibility,
          realTables,
          cacheResults,
        );
        throwIfAborted(signal);
        const columnarKey =
          innerKey === undefined
            ? undefined
            : `ctw|${JSON.stringify(source.windowed.windows)}|${innerKey}`;
        if (columnarKey !== undefined) {
          const hit = this.#cacheGet(columnarKey) as
            { table: ColumnarTable; schema: SqlColumnSchema[] } | undefined;
          if (hit !== undefined) {
            typedSchemas.set(source.table, hit.schema);
            inputs.set(source.table, hit.table);
            continue;
          }
        }
        const { result: inner, schema: innerSchema } = await this.#executeBlockWithSchemaCached(
          source.windowed.block,
          snapshot,
          visibility,
          memory,
          realTables,
          typedSchemas,
          cacheResults,
          allowSpill,
          forceSpill,
          spillPageRows,
          signal,
        );
        const windowed = applyWindowFunctions(inner, source.windowed.windows, {
          copyRows: cacheResults,
        });
        const schema = [
          ...innerSchema,
          ...source.windowed.windows.map((window) => {
            const sqlDomain = windowOutputDomain(window, innerSchema);
            return {
              name: window.alias,
              type: windowOutputType(window, innerSchema),
              ...(sqlDomain === undefined ? {} : { sqlDomain }),
            };
          }),
        ];
        typedSchemas.set(source.table, schema);
        const table = derivedColumnarTable(source.table, windowed, schema);
        if (columnarKey !== undefined) {
          this.#cachePut(columnarKey, { table, schema }, derivedTableRetainedBytes(table));
        }
        inputs.set(source.table, table);
        continue;
      }
      const derived = source.derived;
      if (derived === undefined) continue;
      const derivedKey = await this.#blockResultCacheKey(
        derived,
        snapshot,
        visibility,
        realTables,
        cacheResults,
      );
      throwIfAborted(signal);
      const columnarKey = derivedKey === undefined ? undefined : `ctd|${derivedKey}`;
      if (columnarKey !== undefined) {
        const hit = this.#cacheGet(columnarKey) as
          { table: ColumnarTable; schema: SqlColumnSchema[] } | undefined;
        if (hit !== undefined) {
          typedSchemas.set(source.table, hit.schema);
          inputs.set(source.table, hit.table);
          continue;
        }
      }
      const { result, schema } = await this.#executeBlockWithSchemaCached(
        derived,
        snapshot,
        visibility,
        memory,
        realTables,
        typedSchemas,
        cacheResults,
        allowSpill,
        forceSpill,
        spillPageRows,
        signal,
      );
      typedSchemas.set(source.table, schema);
      const derivedTable = derivedColumnarTable(source.table, result, schema);
      if (columnarKey !== undefined) {
        this.#cachePut(
          columnarKey,
          { table: derivedTable, schema },
          derivedTableRetainedBytes(derivedTable),
        );
      }
      inputs.set(source.table, derivedTable);
    }
    const nameSchemas = new Map(
      sources.map((source) => [
        source.table,
        (typedSchemas.get(source.table) ?? []).map(({ name }) => name),
      ]),
    );
    const columns = referencedColumns(block, nameSchemas);
    const onlyRealSource =
      sources.length === 1 && sources[0]?.derived === undefined ? block : undefined;
    for (const source of sources) {
      throwIfAborted(signal);
      if (source.derived !== undefined || inputs.has(source.table)) continue;
      if (source.table === DUAL_TABLE) {
        inputs.set(DUAL_TABLE, columnarTableFromRows(DUAL_TABLE, dualTableRows()));
        continue;
      }
      const table = realTables.get(source.table);
      if (table === undefined) throw new UnknownTableError(source.table);
      const requestedColumns = columns.get(table.name) ?? [];
      inputs.set(
        table.name,
        await this.#materializeColumnarTableAtSnapshot(
          table,
          snapshot,
          requestedColumns.length === 0 ? [] : resolveReadColumns(table, requestedColumns),
          visibility,
          onlyRealSource,
        ),
      );
      throwIfAborted(signal);
    }
    return inputs;
  }

  #effectiveQueryOptions(options: QueryOptions): QueryOptions {
    if (options.executionMemoryBudgetBytes !== undefined) return options;
    return {
      ...options,
      executionMemoryBudgetBytes: this.#queryExecutionMemoryBudgetBytes,
    };
  }

  /** Executes a read-only SELECT statement through the public query API. */
  async query(sql: string, options: QueryOptions = {}): Promise<QueryResult> {
    return this.#queryWithReadReservation(sql, options);
  }

  async #queryUnreserved(sql: string, options: QueryOptions): Promise<QueryResult> {
    throwIfAborted(options.signal);
    const open = this.#openTransaction;
    if (open !== undefined) {
      // Read-your-writes: inside BEGIN … COMMIT a read sees the pre-scope snapshot plus what
      // this transaction has staged, and nothing another writer published in between.
      return externalizeQueryResult(
        await this.#duringTransaction(open, () => open.session.query(sql, options)),
      );
    }
    const compiled = this.#compileCached(sql);
    // The keyed point-read fast path answers an eligible statement before parameter binding
    // ever clones the plan. A shape, parameter, catalog, or physical-history condition it
    // cannot prove falls through to the ordinary executor below, which owns all error
    // reporting; the count check mirrors bind-time validation so a parameter-arity mistake
    // still reports through the canonical path.
    if (
      !pointReadTestHooks.disabled &&
      options.version === undefined &&
      options.spillToStorage === undefined &&
      options.spillPageRows === undefined &&
      options.executionMemoryBudgetBytes === undefined &&
      (compiled.parameterCount ?? 0) === (options.params?.length ?? 0)
    ) {
      const template = cachedPointReadTemplate(compiled);
      if (template !== null) {
        const shape = resolvePointReadShape(template, options.params ?? []);
        if (shape !== undefined) {
          let point: QueryResult | undefined;
          try {
            point = await this.#pointReadResult(shape, options);
          } catch (error) {
            // A table name that only folds case-insensitively is unknown to the fast path;
            // the general path below resolves it, so this is a miss, not a failure.
            if (!(error instanceof UnknownTableError)) throw error;
          }
          throwIfAborted(options.signal);
          if (point !== undefined) return externalizeQueryResult(point);
        }
      }
    }
    const plan = bindPlanParameters(compiled, options.params);
    // Result memoization is a pure cache over the freshness probe: the catalog epoch is part
    // of the key, so any commit or DDL changes the key and a hit can never be stale. Only
    // plain current-version queries memoize — explicit versions, budgets, and spill options
    // carry semantics of their own.
    const probe = this.store.getCatalogProbe.bind(this.store);
    const memoizable =
      options.memoize !== false &&
      cacheableQueryInput(sql, options.params ?? []) &&
      // A statement that reads the clock is not a function of the data, so the catalog epoch
      // cannot tell a fresh answer from a stale one.
      plan.usesStatementDatetime !== true &&
      plan.usesVolatileFunctions !== true &&
      // A sequence call advances connection state on every execution; a memo hit would both
      // repeat the old value and skip the advance.
      plan.usesSequenceCalls !== true &&
      options.version === undefined &&
      options.executionMemoryBudgetBytes === undefined &&
      options.spillToStorage === undefined &&
      options.spillPageRows === undefined;
    const result = !memoizable
      ? await this.#queryCompiled(plan, options)
      : await this.#memoizedQuery(
          plan,
          `res ${queryResultMemoKey(sql, options.params ?? [])}`,
          options,
          probe,
        );
    throwIfAborted(options.signal);
    return externalizeQueryResult(result);
  }

  /**
   * Pull-driven query batches. Cursor-safe scans emit directly from vector batches; blocking
   * plans (sorts, groups, joins, derived sources) use the ordinary correct execution and page
   * its result. In both cases the iterator applies backpressure and owns one snapshot at a time.
   */
  queryCursor(
    sql: string,
    options: QueryCursorOptions = {},
  ): AsyncIterableIterator<QueryResult, undefined> {
    const batchRows = positiveWholeNumber(options.batchRows ?? 2_048, "Query batch rows");
    const controller = new AbortController();
    const channel = new QueryBatchChannel();
    const { batchRows: _batchRows, signal, ...queryOptions } = options;
    void _batchRows;
    let producer: Promise<void> | undefined;
    const abort = (): void => {
      const reason = queryCursorError(signal?.reason, "Query cursor is closed");
      controller.abort(reason);
      channel.fail(reason);
    };
    signal?.addEventListener("abort", abort, { once: true });
    if (signal?.aborted === true) abort();
    const start = (): void => {
      if (producer !== undefined) return;
      if (controller.signal.aborted) {
        producer = Promise.resolve();
        return;
      }
      producer = this.#withReadReservation(() =>
        this.#queryBatches(sql, queryOptions, {
          batchRows,
          signal: controller.signal,
          consume: (batch) => channel.push(batch),
        }),
      ).then(
        () => channel.finish(),
        (error: unknown) => channel.fail(error),
      );
    };
    const close = async (): Promise<void> => {
      if (!controller.signal.aborted) controller.abort(new Error("Query cursor is closed"));
      channel.fail(controller.signal.reason);
      await producer?.catch(() => undefined);
      signal?.removeEventListener("abort", abort);
    };
    return {
      next: () => {
        start();
        return channel.next();
      },
      return: async () => {
        await close();
        return { done: true, value: undefined };
      },
      throw: async (error?: unknown) => {
        if (!controller.signal.aborted) controller.abort(error);
        channel.fail(error);
        await close();
        throw error;
      },
      [Symbol.asyncIterator]() {
        return this;
      },
    };
  }

  async #queryBatches(
    sql: string,
    options: QueryOptions,
    cursor: QueryBatchCursorExecution,
  ): Promise<void> {
    options = this.#effectiveQueryOptions({ ...options, signal: cursor.signal });
    cursor.signal.throwIfAborted();
    // A transaction's staged overlay has its own executor. Keep its read-your-writes semantics
    // and page the materialized result; native scan batching is for durable snapshots.
    if (this.#openTransaction === undefined) {
      const plan = bindPlanParameters(this.#compileCached(sql), options.params);
      const probe = await this.store.getCatalogProbe();
      const rewritten = await this.#applyCatalogRewrites(plan, probe);
      if (
        !compiledPlanIsGrouped(rewritten) &&
        rewritten.orderBy.length === 0 &&
        rewritten.joins.length === 0 &&
        this.#canStreamPlanShape(rewritten, options)
      ) {
        const spillPageRows =
          options.spillPageRows === undefined
            ? undefined
            : positiveWholeNumber(options.spillPageRows, "Query spill page rows");
        const streamed = await this.#queryStreamed(
          rewritten,
          options,
          spillPageRows,
          probe,
          cursor,
        );
        if (streamed !== undefined) return;
      }
    }
    cursor.signal.throwIfAborted();
    const result = await this.query(sql, options);
    if (result.rows.length === 0) {
      await cursor.consume(result);
      return;
    }
    for (let start = 0; start < result.rows.length; start += cursor.batchRows) {
      cursor.signal.throwIfAborted();
      await cursor.consume({
        columns: [...result.columns],
        columnDomains: [...result.columnDomains],
        rows: result.rows.slice(start, start + cursor.batchRows),
      });
    }
  }

  /**
   * The result memo: a pure cache over the freshness probe, keyed by the statement and the
   * catalog epoch it was answered at. The probe read before execution is handed down to the
   * execution itself — the view lookup and the catalog state would otherwise each probe again,
   * and on IndexedDB every probe is a read transaction, a floor under every small query.
   */
  async #memoizedQuery(
    plan: CompiledQuery,
    key: string,
    options: QueryOptions,
    probe: () => Promise<CatalogProbe>,
  ): Promise<QueryResult> {
    throwIfAborted(options.signal);
    const before = await probe();
    throwIfAborted(options.signal);
    const cached = this.#cacheGet(`${key}\u0001${String(before.catalogEpoch)}`) as
      QueryResult | undefined;
    if (cached !== undefined) {
      options.onStats?.({ peakMemoryBytes: 0 });
      return copyQueryResult(cached);
    }
    const result = await this.#queryCompiled(plan, options, before);
    throwIfAborted(options.signal);
    const bytes = queryResultRetainedBytes(result);
    if (bytes <= RESULT_MEMO_MAX_BYTES) {
      // Cache only when the epoch did not move during execution: the result is then exactly
      // that epoch's answer. A moved epoch simply skips the cache — never mis-files.
      const after = await probe();
      throwIfAborted(options.signal);
      if (after.catalogEpoch === before.catalogEpoch) {
        this.#cachePut(
          `${key}\u0001${String(before.catalogEpoch)}`,
          copyQueryResult(result),
          bytes,
        );
      }
    }
    return result;
  }

  /**
   * Applies the rewrites that need the catalog rather than the statement alone: a view becomes
   * the query it stands for (F031-02), `FROM t AS y(a, b)` renames the table's columns
   * (E051-09), and a NATURAL join becomes the equality over the columns its sides share
   * (F401-01). Reads the catalog only for the statements that ask for one of them.
   */
  async #applyCatalogRewrites(plan: CompiledQuery, probe?: CatalogProbe): Promise<CompiledQuery> {
    const aliased = planHasSourceColumnAliases(plan);
    const natural = planHasNaturalJoins(plan);
    // Whether a name is a view cannot be read off the statement, so this is the one thing every
    // read has to ask the catalog. It asks by epoch — an O(1) probe the store already serves for
    // result memoization — and only re-reads the view set when the catalog has actually moved.
    // A database with no views therefore pays one probe, not a catalog scan per query.
    const {
      views,
      domains,
      types,
      integers,
      keys,
      columns: catalogColumns,
    } = await this.#catalogFacts(probe);
    let rewritten = plan.usesSequenceCalls === true ? await this.#resolveSequenceCalls(plan) : plan;
    // Unquoted identifiers that resolve only case-insensitively are read as PostgreSQL folds
    // them; a name that resolves exactly is never touched, so this is one probing walk.
    rewritten = foldIdentifierCase(rewritten, catalogColumns);
    rewritten = expandRowReferences(rewritten, (name) => catalogColumns.get(name));
    if (views.size > 0 && planReadsViews(rewritten, (name) => views.has(name))) {
      const bodies = new Map<string, CompiledQuery>();
      rewritten = expandViewSources(rewritten, (name) => {
        const sql = views.get(name);
        if (sql === undefined) return undefined;
        const cached = bodies.get(name);
        if (cached !== undefined) return cached;
        const compiled = this.#compileCached(sql);
        bodies.set(name, compiled);
        return compiled;
      });
    }
    if (planReadsTable(rewritten, (name) => domains.has(name) || types.has(name))) {
      rewritten = normalizePlanDomainLiterals(rewritten, domains, types);
    }
    // Integer division needs the catalog: `qty / 2` truncates only once `qty` is known to be
    // an INTEGER column. The probe is one walk; a plan with a candidate is cloned so the shared
    // compiled plan stays catalog-free.
    if (integers.size > 0 && planMayHaveIntegerDivision(rewritten)) {
      rewritten = clonePlanTree(rewritten);
      annotatePlanIntegerDivision(rewritten, (name) => integers.get(name));
    }
    if (keys.size > 0) {
      rewritten = extendGroupByWithKeyDependents(
        rewritten,
        (name) => keys.get(name),
        (name) => catalogColumns.get(name),
      );
    }
    const columnsOf = (name: string): readonly string[] | undefined => {
      const columns = catalogColumns.get(name);
      if (columns === undefined) throw new UnknownTableError(name);
      return columns;
    };
    rewritten = bindPendingSelectShapes(rewritten, columnsOf);
    if (aliased) rewritten = expandSourceColumnAliases(rewritten, columnsOf);
    if (natural) rewritten = expandNaturalJoins(rewritten, columnsOf);
    // With every subquery name resolved, the rewrites compilation had to hold back can run:
    // a name still unqualified is local to its block, so an uncorrelated IN subquery may become
    // a join and an outer predicate may enter a correlation probe.
    if (!blockHasSubqueries(rewritten)) return rewritten;
    return optimizePlan(qualifyCorrelatedReferences(rewritten, catalogColumns), {
      resolvedNames: true,
    });
  }

  /** Replaces a statement's whole-row RETURNING payload with its expression items. */
  async #projectReturningItems(
    statement: CompiledStatement,
    result: ExecuteResult,
  ): Promise<ExecuteResult> {
    if (
      (statement.kind !== "insert" && statement.kind !== "update" && statement.kind !== "delete") ||
      statement.returningItems === undefined ||
      (result.kind !== "insert" && result.kind !== "update" && result.kind !== "delete") ||
      result.returnedRows === undefined
    ) {
      return result;
    }
    const table = await this.#findTable(statement.table);
    const alias =
      statement.kind !== "insert" && statement.alias !== undefined ? statement.alias : table.name;
    const facts = await this.#catalogFacts();
    return {
      ...result,
      ...projectReturningItems(table, alias, statement.returningItems, result.returnedRows, facts),
    };
  }

  /** Resolves connection-local sequence calls before either synchronous executor sees the plan. */
  async #resolveSequenceCalls(plan: CompiledQuery): Promise<CompiledQuery> {
    const usesSequence = (expression: Expression): boolean =>
      (expression.kind === "call" &&
        (expression.name === "NEXTVAL" || expression.name === "CURRVAL")) ||
      childExpressions(expression).some(usesSequence);
    const selected = new Set<Expression>();
    const markSelected = (expression: Expression): void => {
      selected.add(expression);
      childExpressions(expression).forEach(markSelected);
    };
    plan.select.forEach((item) => markSelected(item.expression));
    const sequenceExpressions: Expression[] = [];
    forEachBlockExpression(plan, (expression) => {
      if (!usesSequence(expression)) return;
      sequenceExpressions.push(expression);
      if (!selected.has(expression)) {
        throw new TypeError("NEXTVAL and CURRVAL are supported in the SELECT list");
      }
    });
    if (sequenceExpressions.length === 0) {
      if (blockCallsFunctions(plan, sequenceFunctionNames)) {
        throw new TypeError(
          "NEXTVAL and CURRVAL are supported in the SELECT list of a SELECT without FROM",
        );
      }
      return plan;
    }
    if (plan.base.table !== DUAL_TABLE || plan.joins.length > 0) {
      throw new TypeError("NEXTVAL and CURRVAL currently require a SELECT without FROM");
    }
    const resolved = structuredClone(plan);
    const rewrite = async (expression: Expression): Promise<Expression> => {
      if (
        expression.kind === "call" &&
        (expression.name === "NEXTVAL" || expression.name === "CURRVAL")
      ) {
        const argument = expression.arguments[0];
        if (
          expression.arguments.length !== 1 ||
          argument?.kind !== "literal" ||
          typeof argument.value !== "string"
        ) {
          throw new TypeError(`${expression.name} requires one constant sequence name`);
        }
        const name = argument.value;
        if (expression.name === "CURRVAL") {
          const current = this.#sequenceCurrValues.get(name);
          if (current === undefined) throw new TypeError(`CURRVAL is not defined yet: ${name}`);
          return { kind: "literal", value: current };
        }
        const record = await this.store.getTableByName(`${SEQUENCE_PREFIX}${name}`);
        if (record?.sequence === undefined) throw new TypeError(`Sequence does not exist: ${name}`);
        const range = await this.store.reserveAutoIncrement(
          record.id,
          record.sequence.columnId,
          1,
          BigInt(record.sequence.start),
        );
        const value = Number(range.start);
        if (!Number.isSafeInteger(value))
          throw new RangeError(`Sequence is outside the safe integer range: ${name}`);
        this.#sequenceCurrValues.set(name, value);
        return { kind: "literal", value };
      }
      if (
        expression.kind === "binary" ||
        expression.kind === "condition" ||
        expression.kind === "logical"
      ) {
        expression.left = await rewrite(expression.left);
        expression.right = await rewrite(expression.right);
      } else if (expression.kind === "call") {
        for (let index = 0; index < expression.arguments.length; index += 1) {
          const argument = expression.arguments[index];
          if (argument !== undefined) expression.arguments[index] = await rewrite(argument);
        }
      } else if (expression.kind === "list") {
        for (let index = 0; index < expression.items.length; index += 1) {
          const item = expression.items[index];
          if (item !== undefined) expression.items[index] = await rewrite(item);
        }
      } else if (expression.kind === "not") {
        expression.operand = await rewrite(expression.operand);
      } else if (expression.kind === "case") {
        for (const branch of expression.branches) {
          branch.when = await rewrite(branch.when);
          branch.then = await rewrite(branch.then);
        }
        if (expression.otherwise !== undefined)
          expression.otherwise = await rewrite(expression.otherwise);
      }
      return expression;
    };
    for (const item of resolved.select) item.expression = await rewrite(item.expression);
    return resolved;
  }

  /**
   * The catalog name an unquoted identifier folds to when no table has the written spelling: the
   * unique case-insensitive match, as PostgreSQL reads `USERS` as `users`. A name that matches
   * nothing, or several tables, is returned unchanged for the caller's own error.
   */
  async #foldTableName(name: string): Promise<string> {
    const { columns } = await this.#catalogFacts();
    if (columns.has(name)) return name;
    const lowered = name.toLowerCase();
    const matches = [...columns.keys()].filter((candidate) => candidate.toLowerCase() === lowered);
    return matches.length === 1 ? (matches[0] ?? name) : name;
  }

  /**
   * The two things the catalog knows that statements cannot: which names are views, and which
   * tables reference which. Both are consulted by every read or write of the relevant kind, so
   * the steady state has to be one epoch probe and no allocation; the facts are rebuilt only
   * when a catalog mutation — anywhere, including another tab — moves the epoch.
   */
  async #catalogFacts(probe?: CatalogProbe): Promise<CatalogFacts> {
    probe ??= await this.store.getCatalogProbe();
    const epoch = probe.catalogEpoch;
    const cached = this.#catalogCache;
    if (cached?.epoch === epoch) return cached.facts;
    const views = new Map<string, string>();
    const childKeys = new Map<string, ChildForeignKey[]>();
    const domains = new Map<string, ReadonlyMap<string, SqlDomain>>();
    const columns = new Map<string, readonly string[]>();
    const types = new Map<string, ReadonlyMap<string, SimpleDataType>>();
    const integers = new Map<string, ReadonlySet<string>>();
    const keys = new Map<string, readonly string[]>();
    for (const table of await this.store.listTables()) {
      const visible = table.columns.filter(({ hidden }) => hidden !== true);
      const keyColumn = getUniqueKeyColumn(table);
      const keyNames =
        keyColumn !== undefined && !keyColumn.hidden
          ? [keyColumn.name]
          : (table.primaryKeyColumnIds ?? []).flatMap((columnId) => {
              const column = table.columns.find((candidate) => candidate.id === columnId);
              return column === undefined ? [] : [column.name];
            });
      if (keyNames.length > 0) keys.set(table.name, keyNames);
      columns.set(
        table.name,
        visible.map(({ name }) => name),
      );
      types.set(table.name, new Map(visible.map((column) => [column.name, column.type])));
      const integerColumns = visible.filter((column) => column.integer === true);
      if (integerColumns.length > 0) {
        integers.set(table.name, new Set(integerColumns.map(({ name }) => name)));
      }
      const tableDomains = new Map(
        table.columns.flatMap((column) =>
          column.sqlDomain === undefined ? [] : [[column.name, column.sqlDomain] as const],
        ),
      );
      if (tableDomains.size > 0) domains.set(table.name, tableDomains);
      if (table.view !== undefined) views.set(table.name, table.view.sql);
      for (const key of table.foreignKeys ?? []) {
        const existing = childKeys.get(key.parentTable);
        if (existing === undefined) childKeys.set(key.parentTable, [{ table, key }]);
        else existing.push({ table, key });
      }
    }
    const facts: CatalogFacts = { views, childKeys, domains, columns, types, integers, keys };
    this.#catalogCache = { epoch, facts };
    return facts;
  }

  /** Every foreign key pointing at one table, with the table that declares it. */
  async #childForeignKeys(parentName: string): Promise<readonly ChildForeignKey[]> {
    return (await this.#catalogFacts()).childKeys.get(parentName) ?? [];
  }

  /**
   * The one read pipeline: every compiled plan — SQL text, the typed builder, and live-query
   * re-runs — routes through the same streaming-first execution, so builder/SQL parity holds
   * for the execution path as well as the plan.
   */
  async #queryCompiled(
    plan: CompiledQuery,
    options: QueryOptions = {},
    probe?: CatalogProbe,
  ): Promise<QueryResult> {
    options = this.#effectiveQueryOptions(options);
    throwIfAborted(options.signal);
    // One freshness probe per query: read here unless the caller already has one, and handed
    // to the view lookup and the catalog state below, which would otherwise probe again each.
    probe ??= await this.store.getCatalogProbe();
    throwIfAborted(options.signal);
    plan = await this.#applyCatalogRewrites(plan, probe);
    throwIfAborted(options.signal);
    const spillPageRows =
      options.spillPageRows === undefined
        ? undefined
        : positiveWholeNumber(options.spillPageRows, "Query spill page rows");
    if (this.#canStreamPlanShape(plan, options)) {
      const streamed = await this.#queryStreamed(plan, options, spillPageRows, probe);
      if (streamed !== undefined) return streamed;
    } else {
      // An ORDER-BY-expression wrapper is a pure projection over the real query: stream the
      // inner block and project the hidden ordering column away, so the wrap never costs a
      // query its streaming eligibility.
      const wrapper = transparentProjectionSource(plan);
      if (wrapper !== undefined && this.#canStreamPlanShape(wrapper.inner, options)) {
        const streamed = await this.#queryStreamed(wrapper.inner, options, spillPageRows, probe);
        if (streamed !== undefined) return projectResultColumns(streamed, wrapper.aliases);
      }
    }
    const prepared = await this.#prepareCompiledPlan(plan, options, probe);
    throwIfAborted(options.signal);
    // Read the peak before close(): closing releases the context and zeroes what it tracked.
    const report = (result: QueryResult): QueryResult => {
      options.onStats?.({ peakMemoryBytes: prepared.memoryUsage.peakBytes });
      return result;
    };
    try {
      const spill = options.spillToStorage ?? options.executionMemoryBudgetBytes !== undefined;
      if (!spill) {
        const result = prepared.execute();
        throwIfAborted(options.signal);
        return report(result);
      }
      if (options.spillToStorage !== true) {
        try {
          const result = prepared.execute();
          throwIfAborted(options.signal);
          return report(result);
        } catch (error) {
          if (!(error instanceof QueryMemoryBudgetError)) throw error;
        }
      }
      return report(
        await prepared.executeAsync({
          ...(spillPageRows === undefined ? {} : { spillPageRows }),
          spillStore: this.#leasedSpillStore(),
          ...(options.signal === undefined ? {} : { signal: options.signal }),
        }),
      );
    } finally {
      prepared.close();
    }
  }

  /**
   * The keyed point-read fast path: a single-table conjunction of column-equals-literal
   * predicates covering the unique key names at most one row, so it is answered directly from
   * cached decoded blocks — no plan binding, streamed view, or vector pipeline. Undefined means
   * the statement, catalog, or physical history is not provably eligible and the ordinary
   * executor (which owns all error reporting and general semantics) must run. Every literal
   * must already match its column's storage type exactly; any coercion case falls back, so the
   * fast path only ever reproduces what the ordinary path would answer.
   */
  async #pointReadResult(
    shape: PointReadShape,
    options: QueryOptions,
  ): Promise<QueryResult | undefined> {
    pointReadTestHooks.attempted += 1;
    const result = await this.#withSharedCatalogSnapshot(
      [shape.table],
      (snapshot, realTables, visibility) =>
        this.#pointReadAtSnapshot(shape, snapshot, realTables, visibility, options),
    );
    if (result !== undefined) {
      pointReadTestHooks.served += 1;
      options.onStats?.({ peakMemoryBytes: 0 });
    }
    return result;
  }

  async #pointReadAtSnapshot(
    shape: PointReadShape,
    snapshot: LeasedSnapshot,
    realTables: Map<string, TableRecord>,
    visibility: SegmentVisibilityCatalog,
    options: QueryOptions,
  ): Promise<QueryResult | undefined> {
    const table = realTables.get(shape.table);
    if (table === undefined || table.view !== undefined) return undefined;
    const columnByName = new Map(table.columns.map((column) => [column.name, column]));
    const matchesStorageType = (
      column: TableColumnRecord,
      value: PointReadEquality["value"],
    ): boolean =>
      column.sqlDomain === undefined &&
      column.hidden !== true &&
      ((column.type === "number" && typeof value === "number") ||
        (column.type === "string" && typeof value === "string") ||
        (column.type === "boolean" && typeof value === "boolean") ||
        (column.type === "datetime" && value instanceof Date));
    const equalityColumns = new Map<string, TableColumnRecord>();
    for (const equality of shape.equalities) {
      const column = columnByName.get(equality.column);
      if (column === undefined || !matchesStorageType(column, equality.value)) return undefined;
      equalityColumns.set(column.name, column);
    }
    // Key coverage is the selectivity proof: the conjunction addresses at most one row, so
    // per-row candidate verification cannot degrade into an unvectorized table scan.
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) return undefined;
    const keyComponents = keyColumn.hidden === true ? primaryKeyColumns(table) : [keyColumn];
    if (keyComponents.length === 0) return undefined;
    if (!keyComponents.every((component) => equalityColumns.has(component.name))) {
      return undefined;
    }
    // A logical-domain projection is served too: the stored scalar is the tagged internal
    // value the ordinary executor's pipeline carries for a bare column reference, and both
    // paths cross the result boundary through the same externalizeQueryResult call, so
    // reporting the column's domain below makes the answers identical by construction.
    const projected: Array<{ column: TableColumnRecord; alias: string }> = [];
    const selected =
      shape.select === "*"
        ? visibleTableColumns(table).map((column) => ({ column: column.name, alias: column.name }))
        : shape.select;
    for (const item of selected) {
      const column = columnByName.get(item.column);
      if (column === undefined || column.hidden === true) return undefined;
      projected.push({ column, alias: item.alias });
    }
    const segments = await this.#visibleSegmentRecords(table, snapshot, visibility);
    if (
      segments.some((segment) => {
        const kind = segment.kind;
        return kind !== "insert" && kind !== "base";
      })
    ) {
      // Update and delete deltas are replayed for the one key instead of the whole table: a
      // scalar key identifies its row in every segment, so the row's history is a handful of
      // small blocks. A composite (hidden) key keeps the ordinary replay.
      if (
        keyColumn.hidden === true ||
        segments.some((segment) => {
          const kind = segment.kind;
          return kind !== "insert" && kind !== "base" && kind !== "update" && kind !== "delete";
        })
      ) {
        return undefined;
      }
      return this.#pointReadThroughDeltas(
        shape,
        keyColumn,
        segments,
        equalityColumns,
        projected,
        snapshot,
        options,
      );
    }
    // The most selective searchable component wins nothing provable without statistics, so
    // prefer a numeric component (zone-map pruning plus binary search) over a string one
    // (per-block reverse dictionary), and fall back to any equality column on the key.
    const searchColumn =
      keyComponents.find(
        (component) => component.type === "number" || component.type === "datetime",
      ) ??
      keyComponents.find((component) => component.type === "string") ??
      keyComponents[0];
    if (searchColumn === undefined) return undefined;
    const searchEquality = shape.equalities.find(
      (equality) => equality.column === searchColumn.name,
    );
    if (searchEquality === undefined) return undefined;
    const searchTarget =
      searchEquality.value instanceof Date
        ? dateMilliseconds(searchEquality.value)
        : searchEquality.value;
    const neededColumns = [
      ...new Set([...equalityColumns.values(), ...projected.map((item) => item.column)]),
    ];
    const rows: QueryRow[] = [];
    let candidateBudget = MAX_POINT_READ_CANDIDATES;
    for (const segment of segments) {
      throwIfAborted(options.signal);
      if (segment.rowCount === 0) continue;
      const searchBlockIds = segment.columnBlockIds[searchColumn.id] ?? [];
      if (searchBlockIds.length === 0) return undefined;
      for (const column of neededColumns) {
        if ((segment.columnBlockIds[column.id]?.length ?? 0) !== searchBlockIds.length) {
          return undefined;
        }
      }
      let blockIndexes = searchBlockIds.map((_, index) => index);
      // A single block cannot be pruned, so skip the zone lookup entirely for the hot
      // one-block OLTP table shape.
      if (typeof searchTarget === "number" && searchBlockIds.length > 1) {
        const descriptions = await this.#zoneDescriptions(searchBlockIds, snapshot);
        blockIndexes = blockIndexes.filter((blockIndex) => {
          const zone = descriptions.get(searchBlockIds[blockIndex] ?? "")?.metadata.zoneMap;
          return zone === undefined || (zone.min <= searchTarget && searchTarget <= zone.max);
        });
      }
      if (blockIndexes.length === 0) continue;
      const searchBlocks = await this.#decodedBlocksThroughCache(
        blockIndexes.map((blockIndex) => searchBlockIds[blockIndex] ?? ""),
        snapshot,
      );
      for (const [position, blockIndex] of blockIndexes.entries()) {
        throwIfAborted(options.signal);
        const decoded = searchBlocks[position];
        if (decoded === undefined) return undefined;
        const blockId = searchBlockIds[blockIndex] ?? "";
        const vector = this.#blockColumnVector(blockId, decoded);
        if (vector.kind !== searchColumn.type) return undefined;
        const candidates: number[] = [];
        if (
          (vector.kind === "number" || vector.kind === "datetime") &&
          typeof searchTarget === "number"
        ) {
          if (decoded.description.nullCount === 0 && valuesAreAscending(vector.values)) {
            const run = equalRunRange(vector.values, searchTarget);
            for (let slot = run.begin; slot < run.end; slot += 1) candidates.push(slot);
          } else {
            for (let slot = 0; slot < vector.length; slot += 1) {
              if (vector.values[slot] === searchTarget) {
                // A null slot's backing value is unspecified; confirm through validity.
                const value = vectorValue(vector, slot);
                if (value !== null) candidates.push(slot);
              }
            }
          }
        } else if (vector.kind === "string" && typeof searchTarget === "string") {
          const code = this.#dictionaryCode(blockId, vector, searchTarget);
          if (code === undefined) continue;
          for (let slot = 0; slot < vector.length; slot += 1) {
            if (vector.codes[slot] === code) candidates.push(slot);
          }
        } else if (vector.kind === "boolean" && typeof searchTarget === "boolean") {
          for (let slot = 0; slot < vector.length; slot += 1) {
            if (vectorValue(vector, slot) === searchTarget) candidates.push(slot);
          }
        } else {
          return undefined;
        }
        if (candidates.length === 0) continue;
        candidateBudget -= candidates.length;
        if (candidateBudget < 0) return undefined;
        const remainingColumns = neededColumns.filter((column) => column.id !== searchColumn.id);
        const rowBlockIds = remainingColumns.map(
          (column) => segment.columnBlockIds[column.id]?.[blockIndex] ?? "",
        );
        const rowBlocks = await this.#decodedBlocksThroughCache(rowBlockIds, snapshot);
        const vectors = new Map<string, ColumnVector>([[searchColumn.name, vector]]);
        for (const [index, column] of remainingColumns.entries()) {
          const block = rowBlocks[index];
          if (block === undefined) return undefined;
          const columnVector = this.#blockColumnVector(rowBlockIds[index] ?? "", block);
          if (columnVector.kind !== column.type) return undefined;
          vectors.set(column.name, columnVector);
        }
        for (const slot of candidates) {
          let matches = true;
          for (const equality of shape.equalities) {
            const columnVector = vectors.get(equality.column);
            if (columnVector === undefined) return undefined;
            const stored = vectorValue(columnVector, slot);
            const wanted = equality.value;
            const equal =
              wanted instanceof Date
                ? stored instanceof Date && dateMilliseconds(stored) === dateMilliseconds(wanted)
                : stored === wanted;
            if (!equal) {
              matches = false;
              break;
            }
          }
          if (!matches) continue;
          const row: QueryRow = {};
          for (const item of projected) {
            const columnVector = vectors.get(item.column.name);
            if (columnVector === undefined) return undefined;
            const value = vectorValue(columnVector, slot);
            if (typeof value === "string" && value.charCodeAt(0) === 0) {
              // A domain column's stored scalar is expected here: it carries the internal
              // tag and is stripped by the shared externalization boundary. Anything else in
              // the NUL namespace — plain text crossing through the ordinary executor's
              // wrapping rules, or an untagged value where a tag is required — is not
              // provably reproduced, so the whole statement falls back.
              if (item.column.sqlDomain === undefined || !isSqlDomainValue(value)) {
                return undefined;
              }
            }
            row[item.alias] = value;
          }
          rows.push(row);
        }
      }
    }
    return {
      columns: projected.map((item) => item.alias),
      columnDomains: projected.map((item) => item.column.sqlDomain ?? null),
      rows,
    };
  }

  /**
   * The slots of one block's vector holding `target`: a sorted null-free numeric block by run
   * search, otherwise by scan; a string block through its reverse dictionary. Undefined when
   * the block cannot be searched for this target.
   */
  #keySlotsInBlock(
    blockId: string,
    decoded: DecodedPhysicalBlock,
    column: TableColumnRecord,
    target: number | string | boolean,
  ): number[] | undefined {
    const vector = this.#blockColumnVector(blockId, decoded);
    if (vector.kind !== column.type) return undefined;
    const slots: number[] = [];
    if ((vector.kind === "number" || vector.kind === "datetime") && typeof target === "number") {
      if (decoded.description.nullCount === 0 && valuesAreAscending(vector.values)) {
        const run = equalRunRange(vector.values, target);
        for (let slot = run.begin; slot < run.end; slot += 1) slots.push(slot);
      } else {
        for (let slot = 0; slot < vector.length; slot += 1) {
          if (vector.values[slot] === target && vectorValue(vector, slot) !== null) {
            slots.push(slot);
          }
        }
      }
      return slots;
    }
    if (vector.kind === "string" && typeof target === "string") {
      const code = this.#dictionaryCode(blockId, vector, target);
      if (code === undefined) return slots;
      for (let slot = 0; slot < vector.length; slot += 1) {
        if (vector.codes[slot] === code) slots.push(slot);
      }
      return slots;
    }
    if (vector.kind === "boolean" && typeof target === "boolean") {
      for (let slot = 0; slot < vector.length; slot += 1) {
        if (vectorValue(vector, slot) === target) slots.push(slot);
      }
      return slots;
    }
    return undefined;
  }

  /**
   * A keyed point read over a mutation history: the segments are walked in visible order,
   * an insert lands the row, a delete unmaps it, and an update patches the columns it carries
   * — the same last-writer-wins replay the streamed mutation table performs, applied to one
   * key. The remaining equalities are checked on the row as it stands at the end, since an
   * update may have changed a filtered column. Falls back when the history is wide enough
   * that decoding it would not beat the ordinary path.
   */
  async #pointReadThroughDeltas(
    shape: PointReadShape,
    keyColumn: TableColumnRecord,
    segments: readonly SegmentRecord[],
    equalityColumns: ReadonlyMap<string, TableColumnRecord>,
    projected: ReadonlyArray<{ column: TableColumnRecord; alias: string }>,
    snapshot: LeasedSnapshot,
    options: QueryOptions,
  ): Promise<QueryResult | undefined> {
    const keyEquality = shape.equalities.find((equality) => equality.column === keyColumn.name);
    if (keyEquality === undefined) return undefined;
    const target =
      keyEquality.value instanceof Date ? dateMilliseconds(keyEquality.value) : keyEquality.value;
    const neededColumns = [
      ...new Set([...equalityColumns.values(), ...projected.map((item) => item.column)]),
    ];
    let current: Map<string, QueryValue> | undefined;
    let decodedBlocks = 0;
    for (const segment of segments) {
      throwIfAborted(options.signal);
      if (segment.rowCount === 0) continue;
      const keyBlockIds = segment.columnBlockIds[keyColumn.id] ?? [];
      if (keyBlockIds.length === 0) return undefined;
      let blockIndexes = keyBlockIds.map((_, index) => index);
      if (typeof target === "number" && keyBlockIds.length > 1) {
        const descriptions = await this.#zoneDescriptions(keyBlockIds, snapshot);
        blockIndexes = blockIndexes.filter((blockIndex) => {
          const zone = descriptions.get(keyBlockIds[blockIndex] ?? "")?.metadata.zoneMap;
          return zone === undefined || (zone.min <= target && target <= zone.max);
        });
      }
      if (blockIndexes.length === 0) continue;
      decodedBlocks += blockIndexes.length;
      if (decodedBlocks > MAX_POINT_READ_DELTA_BLOCKS) return undefined;
      const keyBlocks = await this.#decodedBlocksThroughCache(
        blockIndexes.map((blockIndex) => keyBlockIds[blockIndex] ?? ""),
        snapshot,
      );
      for (const [position, blockIndex] of blockIndexes.entries()) {
        const decoded = keyBlocks[position];
        if (decoded === undefined) return undefined;
        const blockId = keyBlockIds[blockIndex] ?? "";
        const slots = this.#keySlotsInBlock(blockId, decoded, keyColumn, target);
        if (slots === undefined) return undefined;
        if (slots.length === 0) continue;
        if (slots.length > 1) return undefined;
        const slot = slots[0] ?? 0;
        if (segment.kind === "delete") {
          current = undefined;
          continue;
        }
        if (segment.kind === "update" && current === undefined) continue;
        const carried =
          segment.kind === "update"
            ? neededColumns.filter(
                (column) =>
                  column.id !== keyColumn.id && segment.columnBlockIds[column.id] !== undefined,
              )
            : neededColumns.filter((column) => column.id !== keyColumn.id);
        const blockIds = carried.map((column) => segment.columnBlockIds[column.id]?.[blockIndex]);
        if (blockIds.some((id) => id === undefined)) return undefined;
        decodedBlocks += blockIds.length;
        if (decodedBlocks > MAX_POINT_READ_DELTA_BLOCKS) return undefined;
        const blocks = await this.#decodedBlocksThroughCache(blockIds as string[], snapshot);
        const values =
          segment.kind === "update" && current !== undefined
            ? current
            : new Map<string, QueryValue>();
        if (segment.kind !== "update") {
          if (current !== undefined) return undefined;
          values.set(keyColumn.name, vectorValue(this.#blockColumnVector(blockId, decoded), slot));
        }
        for (const [index, column] of carried.entries()) {
          const block = blocks[index];
          const columnBlockId = blockIds[index];
          if (block === undefined || columnBlockId === undefined) return undefined;
          if (block.column.rowCount !== decoded.column.rowCount) return undefined;
          const vector = this.#blockColumnVector(columnBlockId, block);
          if (vector.kind !== column.type) return undefined;
          values.set(column.name, vectorValue(vector, slot));
        }
        current = values;
      }
    }
    const rows: QueryRow[] = [];
    if (current !== undefined) {
      let matches = true;
      for (const equality of shape.equalities) {
        const stored = current.get(equality.column);
        const wanted = equality.value;
        const equal =
          wanted instanceof Date
            ? stored instanceof Date && dateMilliseconds(stored) === dateMilliseconds(wanted)
            : stored === wanted;
        if (!equal) {
          matches = false;
          break;
        }
      }
      if (matches) {
        const row: QueryRow = {};
        for (const item of projected) {
          const value = current.get(item.column.name);
          if (value === undefined) return undefined;
          if (typeof value === "string" && value.charCodeAt(0) === 0) {
            if (item.column.sqlDomain === undefined || !isSqlDomainValue(value)) return undefined;
          }
          row[item.alias] = value;
        }
        rows.push(row);
      }
    }
    return {
      columns: projected.map((item) => item.alias),
      columnDomains: projected.map((item) => item.column.sqlDomain ?? null),
      rows,
    };
  }

  /** The dictionary code for a value in one block's string vector, reverse-mapped and cached. */
  #dictionaryCode(
    blockId: string,
    vector: ColumnVector & { kind: "string" },
    value: string,
  ): number | undefined {
    let reverse = this.#cacheGet(`drd ${blockId}`) as Map<string, number> | undefined;
    if (reverse === undefined) {
      reverse = new Map<string, number>();
      for (const [code, entry] of vector.dictionary.entries()) reverse.set(entry, code);
      let bytes = 64;
      for (const entry of vector.dictionary) bytes += 32 + entry.length;
      this.#cachePut(`drd ${blockId}`, reverse, bytes);
    }
    return reverse.get(value);
  }

  /**
   * Streams a one-column snapshot projection into bounded pages. DELETE uses this before its
   * first staged write: selection keeps all ordinary pruning/predicate semantics without
   * retaining every QueryRow object until the key array is complete. Undefined means the shape
   * or physical history needs the established row-shaped executor.
   */
  async #queryCompiledFirstColumn(
    plan: CompiledQuery,
    probe: CatalogProbe,
  ): Promise<QueryValue[] | undefined> {
    const options = this.#effectiveQueryOptions({ memoize: false });
    plan = await this.#applyCatalogRewrites(plan, probe);
    if (!this.#canStreamPlanShape(plan, options)) return undefined;
    const values: QueryValue[] = [];
    const streamed = await this.#queryStreamed(plan, options, undefined, probe, {
      batchRows: 2_048,
      signal: new AbortController().signal,
      consumeFirstColumn: async (batch) => {
        values.push(...batch);
      },
      consume: async () => undefined,
    });
    return streamed === undefined ? undefined : values;
  }

  /**
   * Backs the executor's spill pages with durable owner leases: each owner registers a lease
   * before its first page write and renews it while pages are read or written, so an abandoned
   * owner becomes reclaimable only after its lease expires.
   */
  #leasedSpillStore(): QuerySpillStore {
    const leases = new Map<string, { revision: number; expiresAtMs: number }>();
    const ensureLease = async (ownerId: string): Promise<void> => {
      const nowMs = dateMilliseconds(this.#now());
      const lease = leases.get(ownerId);
      if (lease === undefined) {
        const expiresAtMs = boundedExpiryMilliseconds(nowMs, this.#spillOwnerLeaseMs);
        await this.store.createTempOwner({
          ownerId,
          createdAt: dateIsoString(new Date(nowMs)),
          expiresAt: dateIsoString(new Date(expiresAtMs)),
          revision: 0,
        });
        leases.set(ownerId, { revision: 0, expiresAtMs });
        return;
      }
      if (nowMs < lease.expiresAtMs - this.#spillOwnerLeaseMs / 2) return;
      const expiresAtMs = boundedExpiryMilliseconds(nowMs, this.#spillOwnerLeaseMs);
      const renewed = await this.store.renewTempOwner({
        ownerId,
        expectedRevision: lease.revision,
        expiresAtCutoff: dateIsoString(new Date(nowMs)),
        expiresAt: dateIsoString(new Date(expiresAtMs)),
      });
      leases.set(ownerId, { revision: renewed.revision, expiresAtMs });
    };
    const batched = this.store.putTempRunPages?.bind(this.store);
    return {
      putPage: async (ownerId, runId, pageIndex, bytes) => {
        await ensureLease(ownerId);
        await this.store.putTempRunPage({ ownerId, runId, pageIndex, bytes });
      },
      ...(batched === undefined
        ? {}
        : {
            putPages: async (pages) => {
              for (const owner of new Set(pages.map((page) => page.ownerId))) {
                await ensureLease(owner);
              }
              await batched(pages);
            },
          }),
      getPage: async (ownerId, runId, pageIndex) => {
        await ensureLease(ownerId);
        return this.store.getTempRunPage(ownerId, runId, pageIndex);
      },
      removeRun: (ownerId, runId) => this.store.removeTempRun(ownerId, runId),
      removeOwner: async (ownerId) => {
        await this.store.removeTempOwner(ownerId);
        leases.delete(ownerId);
      },
    };
  }

  /**
   * Reclaims temp spill pages whose owner lease is expired or missing at a cutoff fixed when the
   * pass starts. Owners with an unexpired lease are retained; each owner is removed atomically
   * against a concurrent renewal.
   */
  async cleanupQuerySpill(
    options: QuerySpillCleanupOptions = {},
  ): Promise<QuerySpillCleanupResult> {
    const maxOwners =
      options.maxOwners === undefined
        ? Number.MAX_SAFE_INTEGER
        : positiveWholeNumber(options.maxOwners, "Spill cleanup owner limit");
    const cutoff = dateIsoString(this.#now());
    const result: QuerySpillCleanupResult = {
      ownersExamined: 0,
      ownersReclaimed: 0,
      ownersRetained: 0,
    };
    let cursor: string | null = null;
    while (result.ownersExamined < maxOwners) {
      const page = await this.store.listTempOwnerIdsPage(
        cursor,
        Math.min(64, maxOwners - result.ownersExamined),
      );
      for (const ownerId of page.records) {
        result.ownersExamined += 1;
        if (await this.store.removeTempOwnerIfExpired(ownerId, cutoff)) {
          result.ownersReclaimed += 1;
        } else {
          result.ownersRetained += 1;
        }
      }
      if (page.nextCursor === null) break;
      cursor = page.nextCursor;
      await this.#yieldMaintenance();
    }
    return result;
  }

  /** Automatic cleanup visits only actual expired candidates, so a live prefix cannot starve it. */
  async #cleanupExpiredQuerySpill(maxOwners: number): Promise<QuerySpillCleanupResult> {
    const cutoff = dateIsoString(this.#now());
    const result: QuerySpillCleanupResult = {
      ownersExamined: 0,
      ownersReclaimed: 0,
      ownersRetained: 0,
    };
    let cursor: string | null = null;
    while (result.ownersExamined < maxOwners) {
      const page = await this.store.listExpiredTempOwnerPage(
        cutoff,
        cursor,
        Math.min(64, maxOwners - result.ownersExamined),
      );
      for (const ownerId of page.records) {
        result.ownersExamined += 1;
        if (await this.store.removeTempOwnerIfExpired(ownerId, cutoff)) {
          result.ownersReclaimed += 1;
        } else {
          result.ownersRetained += 1;
        }
      }
      if (page.nextCursor === null) break;
      cursor = page.nextCursor;
      await this.#yieldMaintenance();
    }
    return result;
  }

  /**
   * Creates a live-query set over this database. Local commits hint it directly, an optional
   * channel carries cross-tab hints, and an optional poll interval bounds staleness without any
   * hint; every hint path converges on the durable manifest version, so missed messages delay a
   * refresh but never produce a stale result. Equal subscriptions retain one private exact
   * result snapshot plus a digest that rejects most inequality before exact comparison.
   */
  liveQueries(options: LiveQuerySetOptions = {}): LiveQuerySet {
    if (this.#closed) throw new Error("Database is closed");
    if (this.#liveSets.size >= MAX_LIVE_QUERY_SETS_PER_DATABASE) {
      throw new LiveQueryLimitError("set", MAX_LIVE_QUERY_SETS_PER_DATABASE);
    }
    const channelName =
      options.channel === undefined && options.channelName === undefined
        ? this.store.liveQueryChannelName
        : options.channelName;
    const compileLiveQuery = (query: LiveQueryInput): CompiledQuery => {
      if (typeof query === "string") return this.#compileCached(query);
      if (query.kind === "typed-query") return query.plan;
      return bindPlanParameters(this.#compileCached(query.sql), query.params);
    };
    const set = new LiveQuerySet(
      {
        currentProbe: async () => {
          return this.store.getCatalogProbe();
        },
        manifestPage: (afterVersion, limit) => this.store.listManifestPage(afterVersion, limit),
        dependencyTableIds: async (query) => {
          const compiled = compileLiveQuery(query);
          // A live query over a view depends on the tables behind it, not on the view's name.
          const plan = await this.#applyCatalogRewrites(compiled);
          const tables = await this.#findRealBlockTables(plan);
          return new Set([...tables.values()].map((record) => record.id));
        },
        execute: async (query) => {
          if (typeof query === "string") return this.query(query);
          if (query.kind === "typed-query") return this.#queryCompiled(query.plan);
          return this.query(query.sql, { params: query.params });
        },
        changeCanAffect: (query, tableIds, after, until) =>
          this.#liveChangeCanAffect(query, tableIds, after, until),
      },
      {
        ...options,
        ...(channelName === undefined ? {} : { channelName }),
        onClosed: () => {
          this.#liveSets.delete(set);
          options.onClosed?.();
        },
      },
    );
    this.#liveSets.add(set);
    return set;
  }

  /**
   * The data-layer proof behind a live sweep's zone skips: whether the commits in
   * (after, until] to these tables can change this query's result. False only on proof —
   * every segment the window introduced to the table is a compaction rewrite or an insert
   * whose zone maps reject the query's predicates, and every version that changed the table
   * left a segment to inspect.
   *
   * Its inputs come from `#liveProofContext`, shared by every subscription in the sweep.
   */
  async #liveChangeCanAffect(
    query: LiveQueryInput,
    tableIds: readonly string[],
    after: number | null,
    until: number,
  ): Promise<boolean> {
    const plan =
      typeof query === "string"
        ? this.#compileCached(query)
        : query.kind === "typed-query"
          ? query.plan
          : bindPlanParameters(this.#compileCached(query.sql), query.params);
    if (planContainsFts(plan)) return true;
    // Base-scan zone proofs are unsound when the plan reads the table anywhere else — a
    // subquery, EXISTS/IN, derived table, or set-operation branch can observe a row the base
    // predicates reject (e.g. `value > (SELECT AVG(value) FROM t)`).
    if (planReadsBeyondSingleScan(plan)) return true;
    const context = await this.#liveProofContext(after, until);
    for (const tableId of tableIds) {
      const entry = await this.#liveProofTable(context, tableId);
      if (entry === undefined) return true;
      const predicates = zonePredicates(plan, entry.table);
      for (const segment of entry.windowSegments) {
        const kind = segment.kind;
        // Compaction rewrites are visible-data-neutral by construction.
        if (kind === "base") continue;
        // Updates and deletes change existing rows; upserts can remove a row from a result
        // set by replacing values. Only pure inserts are append-only-safe to zone-check.
        if (kind !== "insert") return true;
        if (predicates.length === 0) return true;
        for (const predicate of predicates) {
          const blockIds = segment.columnBlockIds[predicate.column.id];
          if (blockIds === undefined) return true;
        }
        // The segment's new rows enter the result only if some row group passes every
        // predicate's zone check; block descriptions ride the same immutable-id cache the
        // streamed scan uses.
        const firstIds = segment.columnBlockIds[predicates[0]?.column.id ?? ""] ?? [];
        if (
          predicates.some(
            (predicate) =>
              (segment.columnBlockIds[predicate.column.id]?.length ?? 0) !== firstIds.length,
          )
        ) {
          return true;
        }
        // One batched read covers every uncached predicate block in the segment, instead of
        // a store round trip per block — hint processing after a wide insert stays cheap.
        const uncachedIds = [
          ...new Set(
            predicates.flatMap((predicate) =>
              (segment.columnBlockIds[predicate.column.id] ?? []).filter(
                (blockId) => this.#cacheGet(`zi ${blockId}`) === undefined,
              ),
            ),
          ),
        ];
        if (uncachedIds.length > 0) {
          const fetched = await this.#getBlocksWindowed(uncachedIds);
          for (const [index, blockId] of uncachedIds.entries()) {
            const bytes = fetched[index];
            if (bytes === undefined) return true;
            this.#cachePut(`zi ${blockId}`, inspectBlock(bytes), ZONE_DESCRIPTION_CACHE_BYTES);
          }
        }
        for (let blockIndex = 0; blockIndex < firstIds.length; blockIndex += 1) {
          let canMatch = true;
          for (const predicate of predicates) {
            const blockId = segment.columnBlockIds[predicate.column.id]?.[blockIndex] ?? "";
            const description = this.#cacheGet(`zi ${blockId}`) as
              ReturnType<typeof inspectBlock> | undefined;
            if (description === undefined) return true;
            if (description.type !== predicate.column.type) return true;
            if (!zoneMapCanMatch(description, predicate)) {
              canMatch = false;
              break;
            }
          }
          if (canMatch) return true;
        }
      }
      // A version that changed this table but left no surviving segment to inspect (its
      // segments were compacted away and reclaimed) cannot be proven neutral.
      for (const version of context.changedVersions.get(tableId) ?? []) {
        if (!entry.coveredVersions.has(version)) return true;
      }
    }
    return false;
  }

  /**
   * The inputs every live proof over one commit window shares: the versions in (after, until]
   * that recorded a change to each table, and — filled in per table as proofs ask — the table
   * record, its segments committed in the window, and the versions those segments account
   * for. A sweep proves each subscription separately, and twenty subscriptions on one table
   * used to list its segments and transactions twenty times, a readonly transaction each on
   * IndexedDB and a cross-tab round trip each on an OPFS follower. A few recent windows stay
   * resident so concurrent sets sweeping different windows do not evict each other.
   */
  async #liveProofContext(after: number | null, until: number): Promise<LiveProofContext> {
    const key = `${String(after)}:${String(until)}`;
    const cached = this.#liveProofContexts.get(key);
    if (cached !== undefined) return cached;
    const context = (async (): Promise<LiveProofContext> => {
      // Proof requires every version to be accounted for by a surviving, inspected segment:
      // garbage collection deletes reclaimed segments outright, so "no segment in the window"
      // is absence of evidence, not evidence of neutrality.
      const changedVersions = new Map<string, Set<number>>();
      let cursor = after;
      pages: for (;;) {
        const page = await this.store.listManifestPage(cursor, 64);
        for (const manifest of page.records) {
          if (manifest.version > until) break pages;
          for (const tableId of manifest.changedTableIds) {
            const versions = changedVersions.get(tableId) ?? new Set<number>();
            versions.add(manifest.version);
            changedVersions.set(tableId, versions);
          }
          if (manifest.version === until) break pages;
        }
        if (page.nextCursor === null) break;
        cursor = page.nextCursor;
      }
      return { after, until, changedVersions, tables: new Map() };
    })();
    this.#liveProofContexts.set(key, context);
    if (this.#liveProofContexts.size > LIVE_PROOF_CONTEXT_LIMIT) {
      const oldest = this.#liveProofContexts.keys().next().value;
      if (oldest !== undefined) this.#liveProofContexts.delete(oldest);
    }
    return context;
  }

  #liveProofTable(context: LiveProofContext, tableId: string): Promise<LiveProofTable | undefined> {
    const cached = context.tables.get(tableId);
    if (cached !== undefined) return cached;
    const entry = (async (): Promise<LiveProofTable | undefined> => {
      const table = await this.store.getTable(tableId);
      if (table === undefined) return undefined;
      const segments = await listTableSegmentsPaged(this.store, tableId);
      const transactions = new Map(
        (await this.#transactionRecordsForSegments(segments)).map(
          (record) => [record.id, record] as const,
        ),
      );
      const windowSegments: SegmentRecord[] = [];
      const coveredVersions = new Set<number>();
      for (const segment of segments) {
        const committed = transactions.get(segment.transactionId)?.committedVersion ?? null;
        if (committed === null || committed <= (context.after ?? -1) || committed > context.until) {
          continue;
        }
        coveredVersions.add(committed);
        windowSegments.push(segment);
      }
      return { table, windowSegments, coveredVersions };
    })();
    context.tables.set(tableId, entry);
    return entry;
  }

  /**
   * True when every manifest published in (after, until] changed no row in any table: the
   * explicitly empty `changedTableIds` that compaction publishes through
   * `markLogicallyUnchanged`. Such a commit is invisible to readers, so a write scope may
   * rebase across it rather than fail — it can invalidate neither what the scope read nor
   * what it staged, whichever tables those were.
   *
   * Everything else answers false, keeping the conflict. An *absent* `changedTableIds` is
   * unknown provenance rather than a claim of neutrality, and a window with a pruned or
   * missing version is absence of evidence rather than evidence of neutrality — the same
   * distinction `#liveChangeCanAffect` draws. Manifest versions are consecutive
   * (`createManifest` publishes `expectedVersion + 1`), so a gap is detectable.
   */
  async #commitsChangedNoData(after: number | null, until: number | null): Promise<boolean> {
    if (until === null) return false;
    let expected = after === null ? 0 : after + 1;
    let cursor = after;
    while (expected <= until) {
      const page = await this.store.listManifestPage(cursor, 64);
      if (page.records.length === 0) return false;
      for (const manifest of page.records) {
        if (expected > until) break;
        if (manifest.version !== expected) return false;
        if (manifest.changedTableIds.length !== 0) return false;
        expected += 1;
      }
      if (page.nextCursor === null) break;
      cursor = page.nextCursor;
    }
    return expected > until;
  }

  /**
   * Read-triggered self-maintenance: a streamed scan that observes heavy fragmentation
   * schedules one incremental compaction step in the background, exactly like the full-text
   * auto index — fire-and-forget, never awaited by the read, one per table at a time.
   *
   * Deltas count separately from fragmentation. Folding them is what returns a table to the
   * plain append scan, and a table can carry enough of them to matter long before it has
   * forty-eight segments. A failed attempt (a merge plan that does not fit the compaction
   * memory budget is the usual one) doubles the count the table must reach before the next
   * one, so a table that cannot be compacted today costs one attempt, not one per query.
   */
  #maybeScheduleAutoCompaction(table: TableRecord, segments: readonly SegmentRecord[]): void {
    this.#maybeScheduleAutoCompactionFromHint(table, autoCompactionHint(null, segments));
  }

  #maybeScheduleAutoCompactionFromHint(table: TableRecord, hint: AutoCompactionHint): void {
    if (this.#closed) return;
    if (!this.#autoCompact) return;
    if (this.#droppingTables.has(table.id)) return;
    if (!autoCompactionDueHint(hint)) return;
    const backoff = this.#autoCompactionBackoff.get(table.id);
    if (backoff !== undefined) {
      if (backoff.retryTimer !== undefined || hint.visible < backoff.minimumSegments) return;
    }
    if (this.#autoCompactionsInFlight.has(table.id)) {
      // A final burst can cross the threshold while the prior fold is still planning or
      // running. Remember it: otherwise no later commit or scan may arrive to trigger the fold
      // that the final state still needs.
      this.#autoCompactionsRequested.add(table.id);
      return;
    }
    const run = this.#runAutoCompaction(table)
      .then((folded) => {
        if (folded) this.#autoCompactionBackoff.delete(table.id);
        else this.#backOffAutoCompaction(table.id, hint.visible);
      })
      .catch(() => {
        this.#backOffAutoCompaction(table.id, hint.visible);
      })
      .finally(() => {
        if (this.#autoCompactionsInFlight.get(table.id) === run) {
          this.#autoCompactionsInFlight.delete(table.id);
        }
        if (this.#autoCompactionsRequested.delete(table.id)) {
          void this.#yieldMaintenance().then(() => this.#checkAutoCompaction(table.id));
        }
      });
    this.#autoCompactionsInFlight.set(table.id, run);
    void run;
  }

  /**
   * Backs off a table whose fold failed or could not help: in segments, never beyond the
   * largest level-zero prefix one fold consumes, so a transient conflict near the end of a
   * burst cannot strand hundreds of segments behind a count the idle database never reaches;
   * and in time, doubling per consecutive failure, so a table at that prefix is not re-planned
   * on every eighth commit while the failure persists. The timer, like the collector's retry
   * timer, is the clock for the time part — it re-checks the table itself when it fires, in
   * case no later commit or scan arrives — and is unreferenced, so it never keeps a process up.
   */
  #backOffAutoCompaction(tableId: string, visible: number): void {
    if (this.#closed) return;
    const previous = this.#autoCompactionBackoff.get(tableId);
    if (previous?.retryTimer !== undefined) clearTimeout(previous.retryTimer);
    const failures = (previous?.failures ?? 0) + 1;
    const delay = Math.min(
      AUTO_COMPACT_RETRY_MAX_MS,
      AUTO_COMPACT_RETRY_MIN_MS * 2 ** Math.min(16, failures - 1),
    );
    const timer = setTimeout(() => {
      const current = this.#autoCompactionBackoff.get(tableId);
      if (current?.retryTimer === timer) {
        this.#autoCompactionBackoff.set(tableId, { ...current, retryTimer: undefined });
      }
      void this.#checkAutoCompaction(tableId);
    }, delay);
    (timer as { unref?: () => void }).unref?.();
    this.#autoCompactionBackoff.set(tableId, {
      minimumSegments: Math.min(AUTO_COMPACT_MAX_LEVEL_ZERO_SEGMENTS, Math.max(2, visible * 2)),
      failures,
      retryTimer: timer,
    });
  }

  /**
   * The write-path guard on level-zero growth, in two tiers. Past the backpressure threshold
   * the write drives one bounded fold step before its own work — the step the background fold
   * would take next, on the writer's turn instead of the fold's — and then proceeds whatever
   * the step did. At the absolute ceiling it takes that step and refuses if the table is still
   * at the ceiling afterwards.
   *
   * The background fold yields once per commit, so under a writer that never pauses it gets one
   * bounded step per statement while every statement adds a segment. A fold that costs more
   * steps than the segments it retires — single-row updates spread over a table whose every
   * partition they touch — then falls behind without bound, and reached the ceiling still in
   * flight, where the one step taken there could only plan. Lending it the writer's turn past
   * two folds' worth of backlog bounds the backlog at that plus one fold's steps: the loop pays
   * a step per statement until the fold publishes, then runs free again. A step that fails or
   * cannot help backs the table off exactly as the background fold does, so a table that
   * cannot be folded costs one attempt per backoff period, not one per write.
   */
  async #assertCompactionCapacity(
    table: TableRecord,
    transaction?: DatabaseTransaction,
  ): Promise<void> {
    transaction?.limitLevelZeroSegments(table.id, MAX_LEVEL_ZERO_SEGMENTS);
    // Every commit atomically enforces the same ceiling. Without automatic compaction there is
    // no useful work for this preflight to do, so avoid a full segment/owner/manifest scan on
    // every write and let the commit return the identical CompactionBacklogError at the CAS.
    if (!this.#autoCompact) return;
    const hintVersion =
      transaction?.snapshotVersion ?? (await this.store.getCurrentManifestVersion());
    const hint = this.#autoCompactionHints.get(table.id);
    let visible: number;
    let levelZero: number;
    if (hint?.version === hintVersion) {
      ({ visible, levelZero } = hint);
    } else {
      const segments = await this.#currentVisibleSegments(table);
      visible = segments.length;
      levelZero = countLevelZeroSegments(segments);
    }
    if (levelZero < AUTO_COMPACT_BACKPRESSURE_LEVEL_ZERO_SEGMENTS) return;
    const atCeiling = levelZero >= MAX_LEVEL_ZERO_SEGMENTS;
    if (!atCeiling && this.#autoCompactionBackoff.get(table.id)?.retryTimer !== undefined) return;
    // A fold waiting to publish is the step that helps most, and stepping the table would wait
    // behind it while it waits for this write: run it here rather than deadlock on it.
    await this.#publishPendingCompactions();
    try {
      const progress = await this.compactTableStep(table.name, {
        maxBlocks: AUTO_COMPACT_STEP_BLOCKS,
        maxLevel0Segments: AUTO_COMPACT_MAX_LEVEL_ZERO_SEGMENTS,
      });
      if (!atCeiling && progress.result !== null && !progress.result.compacted) {
        this.#backOffAutoCompaction(table.id, visible);
      }
    } catch (error) {
      if (atCeiling) throw error;
      this.#backOffAutoCompaction(table.id, visible);
      return;
    }
    if (!atCeiling) return;
    levelZero = countLevelZeroSegments(await this.#currentVisibleSegments(table));
    if (levelZero >= MAX_LEVEL_ZERO_SEGMENTS) {
      throw new CompactionBacklogError(table.name, levelZero, MAX_LEVEL_ZERO_SEGMENTS);
    }
  }

  /**
   * Plans a compaction job and drives it to publication in small steps, yielding to the event
   * loop between them so queries and writes interleave with the maintenance; then, while the
   * table is still due, plans the next. A job that only advanced when the next scan happened
   * to trigger it would sit half-written in an idle tab, its output staged and its sources
   * still read on every query, and the deltas that landed while it ran would wait for a scan
   * that may never come. Returns whether anything was folded: a table compaction cannot help
   * (an unsupported layout, keys living in published partitions) must not be re-planned on
   * every trigger, so the caller backs it off as it would a failure.
   */
  async #runAutoCompaction(table: TableRecord): Promise<boolean> {
    const options = {
      maxBlocks: AUTO_COMPACT_STEP_BLOCKS,
      maxLevel0Segments: AUTO_COMPACT_MAX_LEVEL_ZERO_SEGMENTS,
    };
    let folded = false;
    for (;;) {
      if (this.#closed) return folded;
      if (this.#droppingTables.has(table.id)) return folded;
      let progress = await this.compactTableStep(table.name, options);
      while (progress.result === null) {
        if (progress.jobId === null) throw new Error("Compaction progress lost its job ID");
        await this.#yieldMaintenance();
        progress = await this.resumeCompactionJob(progress.jobId, options);
      }
      if (!progress.result.compacted) return folded;
      folded = true;
      // The fold's sources are garbage now; collect before planning the next fold.
      this.#maybeScheduleAutoCollection();
      await this.#yieldMaintenance();
      const current = await this.store.getTable(table.id);
      if (
        current === undefined ||
        !autoCompactionDue(await this.#currentVisibleSegments(current))
      ) {
        return folded;
      }
    }
  }

  /** The table's visible segments at the current manifest. */
  async #currentVisibleSegments(table: TableRecord): Promise<SegmentRecord[]> {
    // This is an optimistic metadata read, not a user snapshot: taking a durable reader lease
    // here would add a readwrite transaction to whichever foreground write happened to trigger
    // maintenance. Verify the manifest did not move while its segment records were loaded; the
    // current manifest itself cannot be pruned, so a matching version is the same stability proof
    // without persistent state. Do not chase a busy writer forever: this probe is only a hint,
    // periodic checks keep arriving during the burst, and the quiet-tail check gets a stable view
    // once it ends.
    let segments: SegmentRecord[] = [];
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const version = await this.store.getCurrentManifestVersion();
      segments = await this.#visibleSegmentRecords(table, new Snapshot(this.store, version));
      if ((await this.store.getCurrentManifestVersion()) === version) {
        this.#autoCompactionHints.set(table.id, autoCompactionHint(version, segments));
        return segments;
      }
    }
    this.#autoCompactionHints.delete(table.id);
    return segments;
  }

  /**
   * What every data commit shares: live sets learn of it, and the tables it changed count
   * toward their next write-path auto-compaction check.
   */
  #afterCommit(manifest: ManifestSummary, transaction?: DatabaseTransaction): void {
    const signal = this.#commitSignal;
    this.#commitSignal = undefined;
    signal?.resolve();
    if (this.#closed) return;
    const contribution = transaction?.committedCatalogContribution;
    this.#advanceAutoCompactionHints(manifest, contribution?.segments);
    const initial = contribution?.initialCatalogProbe;
    const contributedTableIds = new Set(
      contribution?.segments.map((segment) => segment.tableId) ?? [],
    );
    if (
      contribution !== undefined &&
      initial !== undefined &&
      this.#catalogStateEpoch === initial.catalogEpoch &&
      manifest.previousVersion === initial.manifestVersion &&
      // Fail closed if a future write path cannot describe every changed table. Leaving the
      // old epoch in place makes the next probe reload from storage; partially advancing a
      // cached state could instead return rows from before the commit indefinitely.
      manifest.changedTableIds.every((tableId) => contributedTableIds.has(tableId))
    ) {
      const nextEpoch = initial.catalogEpoch + 1;
      for (const state of this.#catalogStateCache.values()) {
        if (
          state.catalogEpoch !== initial.catalogEpoch ||
          state.manifestVersion !== initial.manifestVersion
        ) {
          continue;
        }
        // The state object is retained so cache/LRU identity stays stable, but its derived maps
        // are immutable snapshots. Drop them before appending the newly committed owner/segment;
        // otherwise the same database instance keeps reading the pre-commit visibility graph.
        this.#preparedCatalogStates.delete(state);
        const tableIds = new Set(
          state.tables.flatMap((table) => (table === undefined ? [] : [table.id])),
        );
        const additions = contribution.segments
          .filter((segment) => tableIds.has(segment.tableId))
          .map((segment) => ({
            ...segment,
            // Stores stamp newly published level-zero records with their manifest order.
            // Advance the cache with that canonical shape, not the staged placeholder order.
            logicalOrder: segment.level === 0 ? manifest.version : segment.logicalOrder,
          }));
        if (additions.length > 0) {
          // A query can run outside an open write scope after its second stage has made the
          // active transaction and segments durable. Its atomic catalog state therefore already
          // contains these ids with an active owner and pre-publication logical order. Publication
          // must replace those records, not merely append missing ids, or the cache keeps treating
          // the committed segments as invisible until another connection changes the epoch.
          const additionsById = new Map(additions.map((segment) => [segment.id, segment] as const));
          for (let index = 0; index < state.segments.length; index += 1) {
            const current = state.segments[index];
            if (current === undefined) continue;
            const replacement = additionsById.get(current.id);
            if (replacement === undefined) continue;
            state.segments[index] = replacement;
            additionsById.delete(current.id);
          }
          state.segments.push(...additionsById.values());
          state.segments.sort((left, right) => left.id.localeCompare(right.id));
          const ownerIndex = state.transactions.findIndex(
            (record) => record.id === contribution.transaction.id,
          );
          if (ownerIndex === -1) {
            state.transactions.push(contribution.transaction);
          } else {
            state.transactions[ownerIndex] = contribution.transaction;
          }
        }
        state.manifestVersion = manifest.version;
        state.catalogEpoch = nextEpoch;
      }
      this.#catalogStateEpoch = nextEpoch;
    }
    this.#notifyLiveCommit();
    for (const hint of manifest.ftsDeltaCounts ?? []) {
      if (hint.count > FTS_FOLD_DELTA_CHUNKS) {
        const key = `${hint.tableId}/${hint.columnId}`;
        this.#postingDeltaTailCounts.set(
          key,
          Math.max(this.#postingDeltaTailCounts.get(key) ?? 0, hint.count),
        );
        this.#scheduleFtsDeltaFold(hint.tableId, hint.columnId);
      }
    }
    this.#commitsSinceCollection += 1;
    this.#autoCollectionDebtCommits += 1;
    const now = dateMilliseconds(this.#now());
    if (
      this.#commitsSinceCollection >= AUTO_COLLECT_COMMIT_INTERVAL ||
      (this.#lastCollectionAt !== undefined &&
        now - this.#lastCollectionAt >= AUTO_COLLECT_QUIET_MS)
    ) {
      this.#maybeScheduleAutoCollection();
    }
    this.#armIdleCollection();
    if (!this.#autoCompact) return;
    for (const tableId of manifest.changedTableIds) {
      this.#idleCompactionTableIds.add(tableId);
      const commits = (this.#commitsSinceCompactionCheck.get(tableId) ?? 0) + 1;
      if (commits < AUTO_COMPACT_COMMIT_CHECK_INTERVAL) {
        this.#commitsSinceCompactionCheck.set(tableId, commits);
        continue;
      }
      this.#commitsSinceCompactionCheck.delete(tableId);
      void this.#checkAutoCompaction(tableId);
    }
    this.#armIdleCompactionCheck();
  }

  /** Counts one physical rewrite version once in this engine, including lost-ack recovery. */
  #afterCompactionCommit(manifest: ManifestSummary, tableId: string): void {
    if (this.#accountedCompactionVersions.has(manifest.version)) return;
    this.#accountedCompactionVersions.add(manifest.version);
    if (this.#accountedCompactionVersions.size > 128) {
      const oldest = this.#accountedCompactionVersions.values().next().value;
      if (oldest !== undefined) this.#accountedCompactionVersions.delete(oldest);
    }
    // A fold replaces source segments with a different physical layout. Its manifest is
    // logically unchanged and therefore carries no changed-table ID, so invalidate explicitly;
    // #runAutoCompaction's stable post-fold probe seeds the replacement counters.
    this.#autoCompactionHints.delete(tableId);
    this.#afterCommit(manifest);
  }

  /** Advances exact local hints, or discards them when a commit's provenance is incomplete. */
  #advanceAutoCompactionHints(
    manifest: ManifestSummary,
    contributedSegments: readonly SegmentRecord[] | undefined,
  ): void {
    for (const [tableId, hint] of this.#autoCompactionHints) {
      if (hint.version !== manifest.previousVersion) {
        // Another database committed since this instance last proved the layout.
        this.#autoCompactionHints.delete(tableId);
        continue;
      }
      this.#autoCompactionHints.set(tableId, { ...hint, version: manifest.version });
    }
    const additionsByTable = new Map<string, SegmentRecord[]>();
    for (const segment of contributedSegments ?? []) {
      const additions = additionsByTable.get(segment.tableId);
      if (additions === undefined) additionsByTable.set(segment.tableId, [segment]);
      else additions.push(segment);
    }
    for (const tableId of manifest.changedTableIds) {
      const hint = this.#autoCompactionHints.get(tableId);
      if (hint === undefined) continue;
      const additions = additionsByTable.get(tableId);
      if (additions === undefined) {
        // DDL and future write paths without an exact segment contribution fail closed.
        this.#autoCompactionHints.delete(tableId);
        continue;
      }
      const contribution = autoCompactionHint(manifest.version, additions);
      this.#autoCompactionHints.set(tableId, {
        version: manifest.version,
        visible: hint.visible + contribution.visible,
        levelZero: hint.levelZero + contribution.levelZero,
        deltas: hint.deltas + contribution.deltas,
      });
    }
  }

  /**
   * Debounces the final write-path check for a burst. Sampling every few commits keeps the hot
   * path cheap, but the last one through seven commits can be the ones that cross a fold
   * threshold. Without this check an idle table can remain due forever because no later write or
   * scan arrives to notice it.
   */
  #armIdleCompactionCheck(): void {
    if (this.#closed) return;
    if (this.#idleCompactionTableIds.size === 0) return;
    if (this.#idleCompactionTimer !== undefined) clearTimeout(this.#idleCompactionTimer);
    const timer = setTimeout(() => {
      this.#idleCompactionTimer = undefined;
      const tableIds = [...this.#idleCompactionTableIds];
      this.#idleCompactionTableIds.clear();
      for (const tableId of tableIds) {
        this.#commitsSinceCompactionCheck.delete(tableId);
        void this.#checkAutoCompaction(tableId);
      }
    }, AUTO_COMPACT_IDLE_CHECK_MS);
    (timer as { unref?: () => void }).unref?.();
    this.#idleCompactionTimer = timer;
  }

  /**
   * The write-path auto-compaction check: the table's visible segments at the current manifest,
   * judged by the same thresholds a streamed scan applies. Without it a write-heavy phase with
   * no reads in between piles deltas up unfolded, and the next query pays for all of them at
   * once. Background maintenance never surfaces through a write; a failed check waits for the
   * next one.
   */
  async #checkAutoCompaction(tableId: string): Promise<void> {
    try {
      const table = await this.store.getTable(tableId);
      if (table === undefined) return;
      const version = await this.store.getCurrentManifestVersion();
      const hint = this.#autoCompactionHints.get(tableId);
      if (hint?.version === version) {
        this.#maybeScheduleAutoCompactionFromHint(table, hint);
        return;
      }
      this.#maybeScheduleAutoCompaction(table, await this.#currentVisibleSegments(table));
    } catch {
      // Deliberately silent: the next commit or scan checks again.
    }
  }

  /**
   * Persists one AFTER trigger on its table record (compare-and-swap with retry, like
   * migration). Validation is CREATE-time so firing can trust the record: events bind only
   * the pseudo-rows they have (INSERT has NEW, DELETE has OLD, UPDATE both), binding columns
   * must exist on the trigger table, and body targets must exist, be keyless (v1 — the
   * commit's unique-key channel belongs to the primary write), differ from the trigger
   * table, and carry no triggers of their own: cascades are rejected, not silently skipped.
   */
  async #createTrigger(
    tableName: string,
    trigger: {
      name: string;
      event: "insert" | "update" | "delete";
      timing: "before" | "after";
      statements: Array<{
        sql: string;
        bindings: Array<{ source: "new" | "old"; column: string }>;
      }>;
    },
  ): Promise<void> {
    const triggerId = this.#createId();
    const createdAt = dateIsoString(this.#now());
    let pinnedTableId: string | undefined;
    for (let attempt = 0; ; attempt += 1) {
      const proof = await this.#stableCatalogProof();
      const tables = proof.records;
      const table = tables.find((record) => record.name === tableName);
      if (table === undefined) throw new UnknownTableError(tableName);
      if (table.view !== undefined)
        throw new TypeError(`Cannot create a trigger on view ${tableName}`);
      pinnedTableId ??= table.id;
      if (table.id !== pinnedTableId) {
        throw new TableRecordConflictError(pinnedTableId, 0, table.revision);
      }
      for (const record of tables) {
        if ((record.triggers ?? []).some((existing) => existing.name === trigger.name)) {
          throw new TypeError(`Trigger already exists: ${trigger.name}`);
        }
      }
      const columnNames = new Set(table.columns.map((column) => column.name));
      for (const statement of trigger.statements) {
        for (const binding of statement.bindings) {
          if (trigger.event === "insert" && binding.source === "old") {
            throw new TypeError("INSERT triggers have no OLD row");
          }
          if (trigger.event === "delete" && binding.source === "new") {
            throw new TypeError("DELETE triggers have no NEW row");
          }
          if (!columnNames.has(binding.column)) {
            throw new TypeError(`Unknown trigger column: ${binding.column}`);
          }
        }
        const compiled = compileStatement(statement.sql);
        if (
          compiled.kind !== "insert" &&
          compiled.kind !== "update" &&
          compiled.kind !== "delete"
        ) {
          throw new TypeError("Trigger bodies support INSERT, UPDATE, and DELETE statements");
        }
        const target = tables.find((record) => record.name === compiled.table);
        if (target === undefined) throw new UnknownTableError(compiled.table);
        if (target.view !== undefined) {
          throw new TypeError(`Trigger bodies cannot write to views: ${compiled.table}`);
        }
        if (target.id === table.id) {
          throw new TypeError("A trigger cannot write to its own table");
        }
        if (compiled.kind === "insert" && target.uniqueKeyColumnId !== undefined) {
          throw new TypeError(`Trigger bodies insert into keyless tables only: ${compiled.table}`);
        }
        if (compiled.kind !== "insert" && target.uniqueKeyColumnId === undefined) {
          throw new TypeError(
            `Trigger body ${compiled.kind.toUpperCase()}s need a keyed table: ${compiled.table}`,
          );
        }
        // A stored body is an executable catalog dependency. Prove its complete target schema
        // now, rather than persisting a statement that fails on every later firing.
        assertTriggerBodyTargetSchema(compiled, target);
        // Cascades are allowed one level deep; the runtime budget errors on deeper chains.
      }
      try {
        await this.store.updateTable(table.id, table.revision, {
          triggers: [...(table.triggers ?? []), { ...trigger, id: triggerId, createdAt }],
          expectedCatalogEpoch: proof.catalogEpoch,
        });
        return;
      } catch (error) {
        if (!(error instanceof TableRecordConflictError) || attempt >= this.#maxCommitRetries) {
          throw error;
        }
      }
    }
  }

  async #dropTrigger(name: string): Promise<void> {
    let pinnedOwnerId: string | undefined;
    let pinnedTriggerId: string | undefined;
    for (let attempt = 0; ; attempt += 1) {
      const proof = await this.#stableCatalogProof();
      const tables = proof.records;
      const owner = tables.find((record) =>
        (record.triggers ?? []).some((trigger) => trigger.name === name),
      );
      if (owner === undefined) {
        if (pinnedOwnerId !== undefined) {
          throw new TableRecordConflictError(pinnedOwnerId, 0, null);
        }
        throw new TypeError(`Trigger not found: ${name}`);
      }
      pinnedOwnerId ??= owner.id;
      if (owner.id !== pinnedOwnerId) {
        throw new TableRecordConflictError(pinnedOwnerId, 0, owner.revision);
      }
      const ownedTrigger = (owner.triggers ?? []).find((trigger) => trigger.name === name);
      if (ownedTrigger === undefined) {
        throw new TableRecordConflictError(pinnedOwnerId, owner.revision, owner.revision);
      }
      pinnedTriggerId ??= ownedTrigger.id;
      if (ownedTrigger.id !== pinnedTriggerId) {
        throw new TableRecordConflictError(pinnedOwnerId, 0, owner.revision);
      }
      try {
        await this.store.updateTable(owner.id, owner.revision, {
          triggers: (owner.triggers ?? []).filter((trigger) => trigger.id !== pinnedTriggerId),
          expectedCatalogEpoch: proof.catalogEpoch,
        });
        return;
      } catch (error) {
        if (!(error instanceof TableRecordConflictError) || attempt >= this.#maxCommitRetries) {
          throw error;
        }
      }
    }
  }

  /**
   * The firing plan for an upsert batch: rows whose key already names a visible row (in the
   * read the caller provides — committed state, or the session overlay) fire as UPDATEs with
   * that row as OLD, matching ON CONFLICT DO UPDATE semantics; the rest fire as INSERTs. An
   * in-batch duplicate key fires as an UPDATE of the earlier occurrence. Returns undefined
   * when the table has no insert or update triggers.
   */
  async #upsertTriggerFirings(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    batch: ColumnarBatch,
    rowCount: number,
    readRows?: (sql: string, params: QueryValue[]) => Promise<QueryResult>,
    conflictWhere?: {
      column: TableColumnRecord;
      operator: ComparisonOperator;
      value: BatchValue;
    },
  ): Promise<UpsertFirings | undefined> {
    const fires = (table.triggers ?? []).some(
      (trigger) => trigger.event === "insert" || trigger.event === "update",
    );
    if ((!fires && conflictWhere === undefined) || rowCount === 0) return undefined;
    const quote = (name: string): string => `"${name.replaceAll('"', '""')}"`;
    const keyValues = batch.columns[keyColumn.name] ?? [];
    const distinct = new Map<string, Exclude<BatchValue, null>>();
    for (const value of keyValues) {
      if (value !== null) distinct.set(keyToken(keyColumn.type, value), value);
    }
    const params = [...distinct.values()];
    const rows: QueryRow[] = [];
    // Each value also contributes a comma token, so the parser's token cap is reached before
    // its parameter cap. A fixed 1,024-key window stays comfortably inside both limits.
    const keyWindowSize = Math.min(MAX_SQL_PARAMETERS, 1_024);
    for (let start = 0; start < params.length; start += keyWindowSize) {
      const window = params.slice(start, start + keyWindowSize);
      const placeholders = window.map(() => "?").join(", ");
      const sql = `SELECT * FROM ${quote(table.name)} WHERE ${quote(keyColumn.name)} IN (${placeholders})`;
      const result =
        readRows === undefined
          ? await this.query(sql, { params: window, memoize: false })
          : await readRows(sql, window);
      rows.push(...result.rows);
    }
    const byToken = new Map(
      rows.map((row) => {
        const key = row[keyColumn.name];
        return [
          key === null || key === undefined ? "" : keyToken(keyColumn.type, key),
          row,
        ] as const;
      }),
    );
    const inserts: number[] = [];
    const updates: number[] = [];
    const skipped: number[] = [];
    const oldImages: Array<Record<string, BatchValue> | undefined> = [];
    const currentByToken = new Map(byToken);
    for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
      const key = keyValues[rowIndex] ?? null;
      const token = key === null ? "" : keyToken(keyColumn.type, key);
      const old = currentByToken.get(token);
      if (old === undefined) {
        inserts.push(rowIndex);
        oldImages.push(undefined);
      } else {
        oldImages.push(old);
        const rawLeft =
          conflictWhere === undefined ? null : (old[conflictWhere.column.name] ?? null);
        const left =
          conflictWhere?.column.sqlDomain === undefined
            ? rawLeft
            : normalizeSqlDomainValue(conflictWhere.column.sqlDomain, rawLeft);
        if (
          conflictWhere !== undefined &&
          !comparisonHolds(conflictWhere.operator, left, conflictWhere.value)
        ) {
          skipped.push(rowIndex);
          continue;
        }
        updates.push(rowIndex);
      }
      currentByToken.set(
        token,
        Object.fromEntries(
          table.columns.map((column) => [
            column.name,
            batch.columns[column.name]?.[rowIndex] ?? null,
          ]),
        ),
      );
    }
    return { inserts, updates, skipped, oldImages };
  }

  /** Fires INSERT and UPDATE triggers for one upsert batch at one timing, per the plan. */
  async #stageUpsertTriggerFirings(
    transaction: DatabaseTransaction,
    table: TableRecord,
    batch: ColumnarBatch,
    firings: UpsertFirings,
    timing: "before" | "after",
    cascadeBudget = 1,
  ): Promise<void> {
    const batchValue = (column: string, rowIndex: number): BatchValue =>
      batch.columns[column]?.[rowIndex] ?? null;
    await this.#stageTriggerDerivedInserts(
      transaction,
      table,
      "insert",
      firings.inserts.length,
      (source, column, index) =>
        source === "new" ? batchValue(column, firings.inserts[index] ?? -1) : null,
      timing,
      cascadeBudget,
    );
    await this.#stageTriggerDerivedInserts(
      transaction,
      table,
      "update",
      firings.updates.length,
      (source, column, index) => {
        const rowIndex = firings.updates[index] ?? -1;
        if (source === "new") return batchValue(column, rowIndex);
        return firings.oldImages[rowIndex]?.[column] ?? null;
      },
      timing,
      cascadeBudget,
    );
  }

  /**
   * Pre-images for UPDATE/DELETE trigger firing, keyed to the input order; fetched only when
   * the table has matching triggers. OLD reflects the values observed at statement start
   * (snapshot semantics), which is also exactly what the mutation replay supersedes.
   */
  async #triggerPreImages(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    keys: ReadonlyArray<Exclude<BatchValue, null>>,
    event: "update" | "delete",
    readRows?: (sql: string, params: QueryValue[]) => Promise<QueryResult>,
    /** Reads the rows even with no trigger to feed — CHECK constraints need the post-image. */
    force = false,
  ): Promise<Array<Record<string, BatchValue> | undefined>> {
    if (!force && !(table.triggers ?? []).some((trigger) => trigger.event === event)) return [];
    const quote = (name: string): string => `"${name.replaceAll('"', '""')}"`;
    const placeholders = keys.map(() => "?").join(", ");
    const preImageSql = `SELECT * FROM ${quote(table.name)} WHERE ${quote(keyColumn.name)} IN (${placeholders})`;
    const result =
      readRows === undefined
        ? await this.query(preImageSql, { params: [...keys] as QueryValue[], memoize: false })
        : await readRows(preImageSql, [...keys] as QueryValue[]);
    const byToken = new Map(
      result.rows.map((row) => {
        const key = row[keyColumn.name];
        return [
          key === null || key === undefined ? "" : keyToken(keyColumn.type, key),
          row,
        ] as const;
      }),
    );
    return keys.map((key) => byToken.get(keyToken(keyColumn.type, key)));
  }

  /**
   * Fires the table's AFTER triggers for one write: every body statement binds once per
   * affected row (NEW/OLD values as positional parameters), the bound rows accumulate into
   * one derived insert per statement, and each derived segment stages into the SAME
   * transaction as the triggering write — the write and its derivations publish atomically,
   * so a crashed tab loses both or neither and no tab can observe one without the other.
   */
  async #stageTriggerDerivedInserts(
    transaction: DatabaseTransaction,
    table: TableRecord,
    event: "insert" | "update" | "delete",
    rowCount: number,
    valueAt: (source: "new" | "old", column: string, rowIndex: number) => BatchValue,
    timing: "before" | "after" = "after",
    cascadeBudget = 1,
  ): Promise<void> {
    const triggers = (table.triggers ?? []).filter(
      (trigger) => trigger.event === event && trigger.timing === timing,
    );
    if (triggers.length === 0 || rowCount === 0) return;
    if (cascadeBudget < 0) {
      throw new Error(`Trigger cascade depth exceeded at table: ${table.name}`);
    }
    for (const trigger of triggers) {
      for (const statement of trigger.statements) {
        const compiled = resolveMutationStatementDatetimes(
          compileStatement(statement.sql),
          this.#now(),
        );
        if (compiled.kind === "insert") {
          await this.#applyTriggerInsertBody(
            transaction,
            compiled,
            statement.bindings,
            rowCount,
            valueAt,
            cascadeBudget,
          );
          continue;
        }
        if (compiled.kind !== "update" && compiled.kind !== "delete") continue;
        await this.#applyTriggerMutationBody(
          transaction,
          compiled,
          statement.bindings,
          rowCount,
          valueAt,
          cascadeBudget,
        );
      }
    }
  }

  /** One trigger body INSERT: rows bound per affected row, staged as one derived segment. */
  async #applyTriggerInsertBody(
    transaction: DatabaseTransaction,
    compiled: Extract<CompiledStatement, { kind: "insert" }>,
    bindings: ReadonlyArray<{ source: "new" | "old"; column: string }>,
    rowCount: number,
    valueAt: (source: "new" | "old", column: string, rowIndex: number) => BatchValue,
    cascadeBudget: number,
  ): Promise<void> {
    const derivedRows: InsertValue[][] = [];
    for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
      const params = bindings.map((binding) => valueAt(binding.source, binding.column, rowIndex));
      const bound = bindStatementParameters(compiled, params);
      if (bound.kind !== "insert") continue;
      derivedRows.push(...bound.rows);
    }
    const target = await this.#findTable(compiled.table);
    if (target.uniqueKeyColumnId !== undefined) {
      throw new TypeError(`Trigger bodies insert into keyless tables only: ${target.name}`);
    }
    // A body INSERT without a column list binds positionally to the visible columns, as the
    // top-level path does; an empty list on a batch means "every column omitted", which would
    // write NULL for each literal. DEFAULT VALUES keeps the empty list so defaults apply.
    let columns = compiled.columns;
    if (columns.length === 0 && compiled.defaultValues !== true) {
      columns = visibleTableColumns(target).map((column) => column.name);
      if (derivedRows.some((row) => row.length !== columns.length)) {
        throw new TypeError(
          `Trigger body INSERT must match the ${String(columns.length)} visible columns of ${target.name}`,
        );
      }
    }
    const statementNow = this.#now();
    const materialized = await this.#materializeInsertExpressions(
      { ...compiled, columns, rows: derivedRows },
      statementNow,
    );
    const input = insertStatementBatch(materialized);
    coerceSqlWriteBatch(target, input);
    const filled = await fillColumnDefaults(
      target,
      input,
      (sql) => this.#evaluateDefaultExpression(sql, statementNow),
      derivedRows.length,
    );
    normalizeDomainBatch(target, filled.batch);
    fillStoredGeneratedColumns(target, filled.batch, derivedRows.length, filled.generated);
    fillCompositePrimaryKey(target, filled.batch, derivedRows.length);
    validateBatch(target, filled.batch, filled.autoIncrement?.column.name);
    if (filled.autoIncrement !== undefined && filled.autoIncrement.missingIndexes.length > 0) {
      const values = await this.store.reserveAutoIncrement(
        target.id,
        filled.autoIncrement.column.id,
        filled.autoIncrement.missingIndexes.length,
        filled.autoIncrement.atLeast,
      );
      patchAutoIncrementValues(filled.batch, filled.autoIncrement, values);
    }
    const derivedValueAt = (source: "new" | "old", column: string, rowIndex: number): BatchValue =>
      source === "new" ? (filled.batch.columns[column]?.[rowIndex] ?? null) : null;
    // One cascade level: the derived insert fires the target's own INSERT triggers with a
    // spent budget, so their bodies must not need a further level.
    await this.#stageTriggerDerivedInserts(
      transaction,
      target,
      "insert",
      derivedRows.length,
      derivedValueAt,
      "before",
      cascadeBudget - 1,
    );
    await this.#stageDerivedInsert(transaction, target, filled.batch, derivedRows.length);
    await this.#stageTriggerDerivedInserts(
      transaction,
      target,
      "insert",
      derivedRows.length,
      derivedValueAt,
      "after",
      cascadeBudget - 1,
    );
  }

  /**
   * One trigger body UPDATE or DELETE against a keyed target: the statement binds per
   * affected row, its matched target rows resolve at statement-start state, and the merged
   * keys (plus computed assignments for updates) stage through the same session machinery
   * atomic write scopes use — inside the same commit, with the target's own triggers fired
   * on a spent cascade budget. A body that touches one target row from two triggering rows
   * in one firing is rejected: the reads cannot compound.
   */
  async #applyTriggerMutationBody(
    transaction: DatabaseTransaction,
    compiled: Extract<CompiledStatement, { kind: "update" | "delete" }>,
    bindings: ReadonlyArray<{ source: "new" | "old"; column: string }>,
    rowCount: number,
    valueAt: (source: "new" | "old", column: string, rowIndex: number) => BatchValue,
    cascadeBudget: number,
  ): Promise<void> {
    const target = await this.#findTable(compiled.table);
    const keyColumn = getUniqueKeyColumn(target);
    if (keyColumn === undefined) {
      throw new TypeError(
        `Trigger body ${compiled.kind.toUpperCase()}s need a keyed table: ${target.name}`,
      );
    }
    const mergedKeys: BatchValue[] = [];
    const seenKeys = new Set<string>();
    const mergedChanges: Record<string, BatchValue[]> = {};
    for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
      const params = bindings.map((binding) => valueAt(binding.source, binding.column, rowIndex));
      const bound = bindStatementParameters(compiled, params);
      if (bound.kind !== "update" && bound.kind !== "delete") continue;
      if (bound.from !== undefined) {
        throw new TypeError(`Trigger body ${bound.kind.toUpperCase()}s cannot join other sources`);
      }
      const referenced = new Set<string>([keyColumn.name]);
      if (bound.kind === "update") {
        for (const assignment of bound.assignments) {
          for (const column of expressionColumnNames(assignment.expression)) {
            referenced.add(column.split(".").at(-1) ?? column);
          }
        }
      }
      const plan: CompiledQuery = {
        sql: `(trigger ${bound.kind})`,
        base: { table: target.name, alias: target.name },
        joins: [],
        select: [...referenced].map((name) => ({
          expression: { kind: "column", reference: name },
          alias: name,
        })),
        predicates: bound.predicates,
        groupBy: [],
        having: [],
        orderBy: [],
      };
      // The read goes through the transaction's staged overlay, exactly like a scope's
      // tx.query: the body must see the triggering write, earlier statements of the same
      // firing, and everything the enclosing scope staged — reading only committed state
      // silently loses those updates.
      const matched = (await this.#sessionQueryPlan(transaction, plan)).rows;
      for (const row of matched) {
        const key = row[keyColumn.name];
        if (key === null || key === undefined) {
          throw new TypeError(`Unique key values must not be null: ${keyColumn.name}`);
        }
        const token = keyToken(keyColumn.type, key);
        if (seenKeys.has(token)) {
          throw new TypeError(
            `A trigger body ${bound.kind} touched the same ${target.name} row twice in one firing`,
          );
        }
        seenKeys.add(token);
        mergedKeys.push(storedSqlValueFromExecution(keyColumn, key));
        if (bound.kind === "update") {
          for (const assignment of bound.assignments) {
            const column = target.columns.find((candidate) => candidate.name === assignment.column);
            if (column === undefined) throw new TypeError(`Unknown column: ${assignment.column}`);
            const value = evaluateRowExpression(assignment.expression, target.name, row);
            if (typeof value === "number" && !Number.isFinite(value)) {
              throw new TypeError(
                `UPDATE assignment produced a non-finite number: ${assignment.column}`,
              );
            }
            (mergedChanges[assignment.column] ??= []).push(
              storedSqlValueFromExecution(column, value),
            );
          }
        }
      }
    }
    if (mergedKeys.length === 0) return;
    if (compiled.kind === "update") {
      await this.#sessionUpdate(
        transaction,
        target.name,
        { keys: mergedKeys, changes: mergedChanges },
        cascadeBudget - 1,
      );
    } else {
      await this.#sessionDelete(transaction, target.name, { keys: mergedKeys }, cascadeBudget - 1);
    }
  }

  /** Encodes and stages one derived insert segment into an already-open transaction. */
  async #stageDerivedInsert(
    transaction: DatabaseTransaction,
    table: TableRecord,
    batch: ColumnarBatch,
    rowCount: number,
  ): Promise<void> {
    stageSecondaryUniqueInsertChanges(transaction, table, batch);
    await this.#stageInsertSegment(transaction, table, batch, rowCount, "insert");
  }

  /** Encodes and stages one insert/upsert segment into an already-open transaction. */
  async #stageInsertSegment(
    transaction: DatabaseTransaction,
    table: TableRecord,
    batch: ColumnarBatch,
    rowCount: number,
    kind: "insert" | "upsert",
    reservedRowIds?: RowIdRange,
  ): Promise<string> {
    const rowIds = reservedRowIds ?? (await this.store.reserveRowIds(table.id, rowCount));
    if (kind === "insert") {
      const ftsDeltas = buildFtsColumnDeltas(table, batch, rowIds.start);
      if (ftsDeltas.length > 0) {
        transaction.setFtsChanges({ tableId: table.id, columns: ftsDeltas });
      }
    }
    const secondaryDeltas = buildSecondaryInsertDeltas(table, batch, rowIds.start);
    if (secondaryDeltas.length > 0) {
      transaction.setFtsChanges({ tableId: table.id, columns: secondaryDeltas });
    }
    const segmentId = this.#createId();
    const columnBlockIds: Record<string, string[]> = {};
    const blockStager = new BoundedWriteBlockStager(transaction);
    const plannedColumns = table.columns.map((column) =>
      writeColumnValues(column.type, batch.columns[column.name] ?? []),
    );
    const ranges = writeBlockRanges(
      plannedColumns,
      rowCount,
      this.#rowsPerBlock,
      this.#targetBlockBytes,
    );
    for (const [columnIndex, column] of table.columns.entries()) {
      const values = batch.columns[column.name] ?? [];
      const plannedColumn = plannedColumns[columnIndex];
      if (plannedColumn === undefined) throw new Error(`Write column disappeared: ${column.name}`);
      const blockIds: string[] = [];
      for (const [part, { start, end }] of ranges.entries()) {
        await blockStager.prepare(
          maximumWriteBlockStoredBytes(plannedColumn, start, end, this.#compression),
        );
        const slice = values.slice(start, end);
        const bytes = await this.#encodeColumnBlock(column.id, asColumnInput(column.type, slice));
        const blockId = [
          "table",
          table.id,
          "segment",
          segmentId,
          "column",
          column.id,
          "part",
          String(part).padStart(6, "0"),
        ].join("/");
        blockStager.add({ id: blockId, bytes });
        blockIds.push(blockId);
      }
      columnBlockIds[column.id] = blockIds;
    }
    const segment: SegmentRecord = {
      id: segmentId,
      tableId: table.id,
      transactionId: transaction.id,
      rowCount,
      rowIdStart: rowIds.start,
      rowIdEndExclusive: rowIds.endExclusive,
      columnBlockIds,
      kind,
      ...(table.uniqueKeyColumnId === undefined ? {} : { keyColumnId: table.uniqueKeyColumnId }),
      level: 0,
      logicalOrder: 0,
      commitOrdinal: transaction.pendingSegmentIds.length,
      rowIdSpans: [],
      createdAt: dateIsoString(this.#now()),
    };
    await blockStager.stageWithSegments([segment]);
    return segmentId;
  }

  /**
   * Runs the callback against one shared write transaction: every staged mutation — across
   * any number of keyed or keyless tables, with their AFTER triggers — publishes as one
   * atomic commit. A concurrent *write* surfaces as a WriteConflictError from the scope
   * (nothing published); retry the whole scope. Background self-maintenance is not a
   * concurrent write: the scope rebases over data-neutral manifests and commits anyway, so
   * compaction landing mid-scope never fails it. An error thrown by the callback aborts the
   * scope with nothing published. A scope that stages nothing publishes nothing.
   */
  async write<T>(
    action: (session: WriteSession<TSchema>) => Promise<T>,
  ): Promise<{ result: T; version: number | null }> {
    // The scope stages by runtime table name; the declaration only types the caller's view.
    return this.#openWriteScope((session) => action(session as WriteSession<TSchema>));
  }

  /**
   * `write()` with the scope's transaction handed to the callback as well, for the internal
   * callers that need to read through it by plan rather than by SQL text — the keyed mutation
   * paths a statement-level transaction routes through.
   */
  async #openWriteScope<T>(
    action: (
      session: WriteSession,
      transaction: DatabaseTransaction,
      writer: TransactionStatementWriter,
    ) => Promise<T>,
    options: { durableSnapshot?: boolean } = {},
  ): Promise<{ result: T; version: number | null }> {
    // A scope is not queued behind other writes, but it is a writer all the same, and SQL
    // statements are scopes: a fold waiting to publish takes its turn before the scope opens
    // its transaction (see #withCompactionPublicationSlot), where nothing of this scope's can
    // yet conflict with it. A scope inside a scope simply rebases over the neutral manifest.
    await this.#publishPendingCompactions();
    await this.#assistAutomaticCollection();
    // Keep one storage-sized statement batch process-local. The common single-statement write
    // then publishes through writeTransaction atomically; a second stage spills the first batch
    // to the durable journal before accepting more, preserving bounded memory and recovery.
    const transaction = await this.#transactions.beginDeferred({
      durableSnapshot: options.durableSnapshot ?? true,
    });
    let closed = false;
    let staged = 0;
    /**
     * A stage that throws *after* registering part of its work (key membership, full-text
     * deltas, derived segments, blocks) cannot be undone statement-by-statement, so the scope
     * is poisoned: even if the callback catches the error, the commit refuses rather than
     * publishing the fragment. A stage that fails validation before registering anything —
     * updating a missing key, say — leaves the scope clean and usable.
     */
    let poisoned: unknown;
    const open = (): void => {
      if (closed) throw new Error("The write scope has ended");
      if (poisoned !== undefined) {
        throw new Error("The write scope already failed and can only roll back", {
          cause: poisoned,
        });
      }
    };
    const guarded = async <T>(run: () => Promise<T>): Promise<T> => {
      const before = transaction.stagedWorkCount;
      try {
        return await run();
      } catch (error) {
        if (transaction.stagedWorkCount !== before) poisoned ??= error;
        throw error;
      }
    };
    const session: WriteSession = {
      query: async (sql, options) => {
        open();
        return this.#withReadReservation(() => this.#sessionQuery(transaction, sql, options));
      },
      execute: async (sql, params) => {
        open();
        const compiled = compileStatement(sql);
        if (compiled.kind === "select") {
          return this.#withReadReservation(async () => ({
            kind: "rows" as const,
            result: await this.#sessionQuery(
              transaction,
              compiled.sql,
              params === undefined ? {} : { params },
            ),
          }));
        }
        const statement = bindStatementParameters(compiled, params);
        // Session settings touch no data and no catalog, so they run inside a scope as well.
        if (statement.kind === "set" || statement.kind === "show") {
          return externalizeExecuteResult(await this.runStatement(statement));
        }
        if (!isTransactionalStatement(statement)) {
          throw new TypeError(
            `${statement.kind.toUpperCase().replace("-", " ")} is not allowed inside a write scope`,
          );
        }
        // Guard the whole SQL statement as one stage. Some INSERT forms perform more than one
        // batch operation; if a later step fails after an earlier one staged work, the caller
        // must not be able to catch the error and commit only part of the statement.
        return writer.executeStatement(statement);
      },
      insertBatch: async (tableName, input) => {
        open();
        staged += 1;
        return guarded(() => this.#sessionInsert(transaction, tableName, input, "insert"));
      },
      upsertBatch: async (tableName, input, options) => {
        open();
        staged += 1;
        return guarded(() => this.#sessionInsert(transaction, tableName, input, "upsert", options));
      },
      updateBatch: async (tableName, input) => {
        open();
        staged += 1;
        return guarded(() => this.#sessionUpdate(transaction, tableName, input));
      },
      deleteBatch: async (tableName, input) => {
        open();
        staged += 1;
        return guarded(() => this.#sessionDelete(transaction, tableName, input));
      },
    };
    const writer: TransactionStatementWriter = {
      ...session,
      queryPlan: (plan) =>
        this.#withReadReservation(async () => {
          // Before this scope stages anything, its view is exactly the catalog probe captured
          // by beginDeferred. Reuse the ordinary current-version pipeline and its compact
          // catalog/lease caches; once work is staged, switch to the overlay pipeline below.
          const probe = transaction.initialCatalogProbe;
          return transaction.stagedWorkCount === 0 && probe !== undefined
            ? this.#queryCompiled(plan, {}, probe)
            : this.#sessionQueryPlan(transaction, await this.#applyCatalogRewrites(plan));
        }),
      queryFirstColumn: (plan) =>
        this.#withReadReservation(async () => {
          // A staged overlay can add, replace, or remove keys without changing the pinned
          // manifest. Keep that case on the read-your-writes row executor; before the first
          // stage, the transaction's exact catalog probe makes the streamed snapshot safe.
          const probe = transaction.initialCatalogProbe;
          return transaction.stagedWorkCount === 0 && probe !== undefined
            ? this.#queryCompiledFirstColumn(plan, probe)
            : undefined;
        }),
      executeStatement: (statement) => {
        open();
        return guarded(() => this.runStatement(statement, { writer }));
      },
      checkpoint: () => {
        open();
        return transaction.checkpoint();
      },
      checkpointRetainedBytes: () => {
        open();
        return transaction.checkpointRetainedBytes();
      },
      rollbackTo: async (checkpoint) => {
        if (closed) throw new Error("The write scope has ended");
        await transaction.rollbackTo(checkpoint);
        poisoned = undefined;
        staged = transaction.stagedWorkCount === 0 ? 0 : 1;
      },
    };
    try {
      const result = await action(session, transaction, writer);
      closed = true;
      if (poisoned !== undefined) {
        // The outer catch aborts the transaction.
        throw new Error(
          `The write scope failed mid-stage and was rolled back: ${
            poisoned instanceof Error ? poisoned.message : "staging failed"
          }`,
          { cause: poisoned },
        );
      }
      if (staged === 0) {
        await transaction.abort();
        return { result, version: await this.store.getCurrentManifestVersion() };
      }
      for (let attempt = 0; attempt <= this.#maxCommitRetries; attempt += 1) {
        try {
          const manifest = await transaction.commit();
          this.#afterCommit(manifest, transaction);
          return { result, version: manifest.version };
        } catch (error) {
          if (!(error instanceof WriteConflictError) || attempt === this.#maxCommitRetries) {
            throw error;
          }
          // Losing the version CAS to background self-maintenance is spurious: compaction
          // publishes a manifest that changed no row anywhere, so it cannot conflict with
          // what this scope read or staged. Rebase across those and commit again. The scope
          // still does not rebase over a commit that actually changed data — a concurrent
          // write loses the race explicitly, exactly as before.
          const from = transaction.snapshotVersion;
          const rebased = await transaction.rebase();
          if (!(await this.#commitsChangedNoData(from, rebased.version))) throw error;
        }
      }
      throw new Error("Commit retry limit was exceeded");
    } catch (error) {
      closed = true;
      await transaction.abort().catch(() => undefined);
      throw await this.#translateUniqueConflict(error);
    }
  }

  /**
   * A scope's read: committed state at the scope's lease plus this transaction's staged
   * segments overlaid as committed — ordered after every committed segment, in staging
   * order — with the staged blocks readable through a snapshot wrapper. Nothing about the
   * overlay leaves the call: caches key on committed identities only.
   */
  async #sessionQuery(
    transaction: DatabaseTransaction,
    sql: string,
    options: QueryOptions = {},
  ): Promise<QueryResult> {
    options = this.#effectiveQueryOptions(options);
    throwIfAborted(options.signal);
    const bound = bindPlanParameters(this.#compileCached(sql), options.params);
    // The same catalog rewrites a read outside a scope gets: a scope that could not see a view
    // would make the scope's reads a different language from everyone else's.
    const plan = await this.#applyCatalogRewrites(bound);
    throwIfAborted(options.signal);
    return this.#sessionQueryPlan(transaction, plan, options);
  }

  /** #sessionQuery for an already-bound plan: trigger bodies resolve their reads through it. */
  async #sessionQueryPlan(
    transaction: DatabaseTransaction,
    plan: CompiledQuery,
    options: QueryOptions = {},
  ): Promise<QueryResult> {
    options = this.#effectiveQueryOptions(options);
    throwIfAborted(options.signal);
    const names = collectRealTableNames(plan);
    const tables = await Promise.all(names.map((name) => this.#findTable(name)));
    throwIfAborted(options.signal);
    const realTables = new Map(tables.map((table) => [table.name, table] as const));
    const pendingIds = new Set(transaction.pendingSegmentIds);
    const pendingBlocks = new Set(transaction.pendingBlockIds);
    const ourRecord = await this.store.getTransaction(transaction.id);
    throwIfAborted(options.signal);
    // Pinned to the scope's own snapshot, not the current manifest: the documented contract
    // is "the pre-scope snapshot plus everything this scope staged", and #assertKeysExist
    // already validates against transaction.snapshotVersion — reading the current version
    // here would let the two disagree mid-scope about a concurrent commit.
    return this.#withLeasedSnapshot(transaction.snapshotVersion, async (snapshot) => {
      const overlaySnapshot = {
        get version() {
          return snapshot.version;
        },
        get expiresAt() {
          return snapshot.expiresAt;
        },
        hasBlock: async (blockId: string) =>
          pendingBlocks.has(blockId) || (await snapshot.hasBlock(blockId)),
        hasBlocks: async (blockIds: readonly string[]) => {
          const committedIds = blockIds.filter((blockId) => !pendingBlocks.has(blockId));
          const committedMembership = await snapshot.hasBlocks(committedIds);
          let committedIndex = 0;
          return blockIds.map((blockId) =>
            pendingBlocks.has(blockId) ? true : committedMembership[committedIndex++] === true,
          );
        },
        getBlock: async (blockId: string) =>
          pendingBlocks.has(blockId) ? transaction.getBlock(blockId) : snapshot.getBlock(blockId),
        getBlocks: async (blockIds: readonly string[]) => {
          const blocks: Array<Uint8Array | undefined> = [];
          for (let start = 0; start < blockIds.length; start += 64) {
            throwIfAborted(options.signal);
            const window = blockIds.slice(start, start + 64);
            const committedIds: string[] = [];
            const committedIndexes: number[] = [];
            const stagedIds: string[] = [];
            const stagedIndexes: number[] = [];
            window.forEach((blockId, index) => {
              if (pendingBlocks.has(blockId)) {
                stagedIds.push(blockId);
                stagedIndexes.push(index);
              } else {
                committedIds.push(blockId);
                committedIndexes.push(index);
              }
            });
            // Committed membership was proved by #visibleSegmentRecords under this pinned
            // manifest, so it keeps the adapter's ordinary bulk payload path. Only journaled
            // ids need the transaction overlay; restoring their positions preserves the exact
            // positional contract without turning a large in-scope scan into one IDB read per
            // committed block.
            const [committed, staged] = await Promise.all([
              this.#getBlocksWindowed(committedIds),
              Promise.all(stagedIds.map((blockId) => transaction.getBlock(blockId))),
            ]);
            throwIfAborted(options.signal);
            const ordered = new Array<Uint8Array | undefined>(window.length);
            committedIndexes.forEach((index, offset) => {
              ordered[index] = committed[offset];
            });
            stagedIndexes.forEach((index, offset) => {
              ordered[index] = staged[offset];
            });
            blocks.push(...ordered);
          }
          return blocks;
        },
        renew: (ttlMs: number) => snapshot.renew(ttlMs),
        release: () => snapshot.release(),
      } as unknown as LeasedSnapshot;
      const segmentsByTable = new Map<string, SegmentRecord[]>();
      const transactionRecords = new Map<string, TransactionRecord>();
      const deferredSegments = transaction.deferredSegments;
      for (const table of tables) {
        throwIfAborted(options.signal);
        const segments = [
          ...(await listTableSegmentsPaged(this.store, table.id)),
          ...deferredSegments.filter((segment) => segment.tableId === table.id),
        ];
        throwIfAborted(options.signal);
        // Staged segments sort after every committed one; commitOrdinal keeps their
        // staging order (the journal's id list is sorted, so it cannot).
        const doctored = segments.map((segment) =>
          pendingIds.has(segment.id)
            ? { ...segment, logicalOrder: STAGED_OVERLAY_ORDER_BASE + segment.commitOrdinal }
            : segment,
        );
        segmentsByTable.set(table.id, doctored);
        for (const record of await this.#transactionRecordsForSegments(doctored)) {
          transactionRecords.set(record.id, record);
        }
        throwIfAborted(options.signal);
      }
      if (ourRecord !== undefined) {
        transactionRecords.set(transaction.id, {
          ...ourRecord,
          status: "committed",
          committedVersion: STAGED_OVERLAY_ORDER_BASE,
        });
      }
      const visibility: SegmentVisibilityCatalog = {
        transactions: transactionRecords,
        segmentsByTable,
        overlayTransactionId: transaction.id,
      };
      return this.#queryAtVisibility(plan, overlaySnapshot, visibility, realTables, true, options);
    });
  }

  /** Executes one plan at an explicit snapshot and visibility, covering every plan shape. */
  async #queryAtVisibility(
    plan: CompiledQuery,
    snapshot: LeasedSnapshot,
    visibility: SegmentVisibilityCatalog,
    realTables: ReadonlyMap<string, TableRecord>,
    cacheResults = true,
    options: QueryOptions = {},
  ): Promise<QueryResult> {
    options = this.#effectiveQueryOptions(options);
    throwIfAborted(options.signal);
    plan = expandFtsColumns(plan, (name) => searchableFtsColumns(realTables.get(name)));
    const typedSchemas = new Map<string, SqlColumnSchema[]>(
      [...realTables.values()].map((table) => [
        table.name,
        table.columns.map(({ name, type, integer, sqlDomain }) => ({
          name,
          type,
          ...(integer === true ? { integer: true as const } : {}),
          ...(sqlDomain === undefined ? {} : { sqlDomain }),
        })),
      ]),
    );
    const memory = new QueryMemoryContext(options.executionMemoryBudgetBytes);
    const allowSpill = options.spillToStorage !== false;
    const forceSpill = options.spillToStorage === true;
    const spillPageRows =
      options.spillPageRows === undefined
        ? undefined
        : positiveWholeNumber(options.spillPageRows, "Query spill page rows");
    const report = (result: QueryResult): QueryResult => {
      throwIfAborted(options.signal);
      options.onStats?.({ peakMemoryBytes: memory.usage.peakBytes });
      return result;
    };
    try {
      const resolution = subqueryResolutionSteps(plan);
      for (const step of resolution.steps) {
        throwIfAborted(options.signal);
        step.substitute(
          await this.#executeBlock(
            step.block,
            snapshot,
            visibility,
            memory,
            realTables,
            typedSchemas,
            undefined,
            cacheResults,
            allowSpill,
            forceSpill,
            spillPageRows,
            options.signal,
          ),
        );
      }
      const wrapper = transparentProjectionSource(resolution.plan);
      if (wrapper !== undefined) {
        return report(
          projectResultColumns(
            await this.#executeBlock(
              wrapper.inner,
              snapshot,
              visibility,
              memory,
              realTables,
              typedSchemas,
              undefined,
              cacheResults,
              allowSpill,
              forceSpill,
              spillPageRows,
              options.signal,
            ),
            wrapper.aliases,
          ),
        );
      }
      return report(
        await this.#executeBlock(
          resolution.plan,
          snapshot,
          visibility,
          memory,
          realTables,
          typedSchemas,
          undefined,
          cacheResults,
          allowSpill,
          forceSpill,
          spillPageRows,
          options.signal,
        ),
      );
    } finally {
      memory.close();
    }
  }

  /** Net staged key membership per table, replayed from the transaction's entries. */
  #stagedKeyOverlay(
    transaction: DatabaseTransaction,
    tableId: string,
  ): { added: Set<string>; removed: Set<string> } {
    const added = new Set<string>();
    const removed = new Set<string>();
    for (const entry of transaction.accumulatedUniqueKeyChanges) {
      if (entry.tableId !== tableId) continue;
      for (const token of entry.keyTokens) {
        if (entry.remove === true) {
          added.delete(token);
          removed.add(token);
        } else {
          removed.delete(token);
          added.add(token);
        }
      }
    }
    return { added, removed };
  }

  async #sessionInsert(
    transaction: DatabaseTransaction,
    tableName: string,
    input: InsertBatchInput,
    kind: "insert" | "upsert",
    options?: UpsertOptions,
    cascadeBudget = 1,
  ): Promise<StagedUpsertResult> {
    const table = await this.#findTable(tableName);
    // Session upserts classify against the scope's own staged state, so a row inserted
    // earlier in the scope makes a later upsert of its key fire as an UPDATE.
    const sessionUpsertKeyColumn = kind === "upsert" ? getUniqueKeyColumn(table) : undefined;
    const normalizedConflictWhere =
      kind === "upsert" && options?.conflictWhere !== undefined
        ? normalizeUpsertConflictWhere(table, options.conflictWhere)
        : undefined;
    if (normalizedConflictWhere !== undefined && sessionUpsertKeyColumn === undefined) {
      throw new TypeError(`Table needs a unique key before it can be upserted: ${table.name}`);
    }
    const filled = await this.#fillDefaults(table, input);
    const { generated, autoIncrement } = filled;
    let batch = filled.batch;
    let rowCount = filled.rowCount;
    if (autoIncrement !== undefined && autoIncrement.missingIndexes.length > 0) {
      const values = await this.store.reserveAutoIncrement(
        table.id,
        autoIncrement.column.id,
        autoIncrement.missingIndexes.length,
        autoIncrement.atLeast,
      );
      patchAutoIncrementValues(batch, autoIncrement, values);
      const patched = batch.columns[autoIncrement.column.name] ?? [];
      for (const rowIndex of autoIncrement.missingIndexes) {
        validateValue(autoIncrement.column, patched[rowIndex] ?? null, rowIndex);
      }
    }
    let sessionUpsertFirings =
      sessionUpsertKeyColumn === undefined
        ? undefined
        : await this.#upsertTriggerFirings(
            table,
            sessionUpsertKeyColumn,
            batch,
            rowCount,
            (sql, params) => this.#sessionQuery(transaction, sql, { params }),
            normalizedConflictWhere,
          );
    let skippedRowCount = 0;
    if (normalizedConflictWhere !== undefined) {
      if (sessionUpsertFirings === undefined) {
        throw new Error("Upsert conflict classification is missing");
      }
      const filtered = applyUpsertConflictFilter(batch, rowCount, sessionUpsertFirings);
      skippedRowCount = filtered.skippedRowCount;
      if (filtered.rowCount !== rowCount) {
        remapGeneratedColumns(generated, filtered.acceptedRowIndexes);
      }
      batch = filtered.batch;
      rowCount = filtered.rowCount;
      sessionUpsertFirings = filtered.firings;
      if (rowCount === 0) {
        // Nothing will be staged for this table, so registering a level-zero segment limit
        // here (via #assertCompactionCapacity below) would leave the transaction with a limit
        // that no pending segment covers — the store's commit planning (RecordCore#planCommit
        // and its IndexedDB equivalent) rejects that at commit time.
        collectAutoIncrementGenerated(batch, generated, autoIncrement);
        return {
          tableName: table.name,
          segmentId: null,
          rowCount: 0,
          skippedRowCount,
          ...(generated.size === 0 ? {} : { generatedColumns: Object.fromEntries(generated) }),
        };
      }
    }
    await this.#assertCompactionCapacity(table, transaction);
    const keys = batchKeys(table, batch);
    if (keys !== undefined) {
      transaction.setUniqueKeyChanges({
        tableId: table.id,
        keyTokens: [...keys.keys()],
        requireAbsent: kind === "insert",
      });
    }
    await this.#assertForeignKeysPresent(
      table,
      (column) => batch.columns[column] ?? [],
      (sql, params) => this.#sessionQuery(transaction, sql, { params }),
      transaction,
    );
    const rowIds = await this.store.reserveRowIds(table.id, rowCount);
    const insertValueAt = (source: "new" | "old", column: string, rowIndex: number): BatchValue =>
      source === "new" ? (batch.columns[column]?.[rowIndex] ?? null) : null;
    stageSecondaryUniqueInsertChanges(
      transaction,
      table,
      batch,
      kind === "upsert" ? sessionUpsertFirings?.oldImages : undefined,
    );
    if (kind === "insert") {
      await this.#stageTriggerDerivedInserts(
        transaction,
        table,
        "insert",
        rowCount,
        insertValueAt,
        "before",
        cascadeBudget,
      );
    } else if (sessionUpsertFirings !== undefined) {
      await this.#stageUpsertTriggerFirings(
        transaction,
        table,
        batch,
        sessionUpsertFirings,
        "before",
        cascadeBudget,
      );
    }
    const segmentId = await this.#stageInsertSegment(
      transaction,
      table,
      batch,
      rowCount,
      kind,
      rowIds,
    );
    if (kind === "insert") {
      await this.#stageTriggerDerivedInserts(
        transaction,
        table,
        "insert",
        rowCount,
        insertValueAt,
        "after",
        cascadeBudget,
      );
    } else if (sessionUpsertFirings !== undefined) {
      await this.#stageUpsertTriggerFirings(
        transaction,
        table,
        batch,
        sessionUpsertFirings,
        "after",
        cascadeBudget,
      );
    }
    collectAutoIncrementGenerated(batch, generated, autoIncrement);
    return {
      tableName: table.name,
      segmentId,
      rowCount,
      skippedRowCount,
      ...(generated.size === 0 ? {} : { generatedColumns: Object.fromEntries(generated) }),
    };
  }

  async #sessionUpdate(
    transaction: DatabaseTransaction,
    tableName: string,
    input: UpdateBatchInput,
    cascadeBudget = 1,
  ): Promise<StagedWriteResult> {
    const table = await this.#findTable(tableName);
    await this.#assertCompactionCapacity(table, transaction);
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) {
      throw new TypeError(`Table needs a unique key before rows can be updated: ${table.name}`);
    }
    input = normalizeDomainUpdate(table, input);
    rejectGeneratedUpdateAssignments(table, input);
    const keys = validateUpdateBatch(table, keyColumn, input);
    // Read-your-writes membership: keys staged by this scope pass, keys the scope removed
    // fail, and everything else checks against the committed snapshot as usual.
    const overlay = this.#stagedKeyOverlay(transaction, table.id);
    for (const [token, value] of keys) {
      if (overlay.removed.has(token)) {
        throw new MissingKeyError(table.name, keyColumn.name, value);
      }
    }
    const committedKeys = new Map([...keys].filter(([token]) => !overlay.added.has(token)));
    if (committedKeys.size > 0) {
      await this.#assertKeysExist(table, keyColumn, transaction.snapshotVersion, committedKeys);
    }
    const sessionChecks = table.checks ?? [];
    let changedForeignKey = (table.foreignKeys ?? []).some(
      (key) =>
        key.enforced !== false &&
        foreignKeyColumns(key).some((column) => input.changes[column] !== undefined),
    );
    const preImages = await this.#triggerPreImages(
      table,
      keyColumn,
      input.keys.filter((key): key is Exclude<BatchValue, null> => key !== null),
      "update",
      (preImageSql, params) => this.#sessionQuery(transaction, preImageSql, { params }),
      sessionChecks.length > 0 ||
        changedForeignKey ||
        tableGeneratedExpressions(table).length > 0 ||
        secondaryIndexUpdateNeedsPreImages(table, input) ||
        readyUniqueSecondaryIndexes(table).some(({ columns }) =>
          columns.some((column) => input.changes[column.name] !== undefined),
        ),
    );
    input = applyStoredGeneratedUpdateChanges(table, input, preImages);
    validateUpdateBatch(table, keyColumn, input);
    changedForeignKey = (table.foreignKeys ?? []).some(
      (key) =>
        key.enforced !== false &&
        foreignKeyColumns(key).some((column) => input.changes[column] !== undefined),
    );
    stageSecondaryUniqueMutationChanges(transaction, table, input, preImages);
    const secondaryDeltas = buildSecondaryUpdateDeltas(table, input, preImages);
    if (secondaryDeltas.length > 0) {
      transaction.setFtsChanges({ tableId: table.id, columns: secondaryDeltas });
    }
    const sessionUpdateValueAt = (
      source: "new" | "old",
      column: string,
      rowIndex: number,
    ): BatchValue => {
      if (source === "old") return preImages[rowIndex]?.[column] ?? null;
      const changed = input.changes[column];
      return changed === undefined
        ? (preImages[rowIndex]?.[column] ?? null)
        : (changed[rowIndex] ?? null);
    };
    if (changedForeignKey) {
      await this.#assertForeignKeysPresent(
        table,
        (column) => input.keys.map((_, row) => sessionUpdateValueAt("new", column, row)),
        (sql, params) => this.#sessionQuery(transaction, sql, { params }),
        transaction,
      );
    }
    // The same post-image rule as a standalone update, so a scope — and the partial upsert that
    // runs inside one — cannot write a row a direct UPDATE would refuse.
    if (sessionChecks.length > 0) {
      for (let rowIndex = 0; rowIndex < input.keys.length; rowIndex += 1) {
        if (preImages[rowIndex] === undefined) continue;
        const row: Record<string, BatchValue> = {};
        for (const column of table.columns) {
          row[column.name] = sessionUpdateValueAt("new", column.name, rowIndex);
        }
        assertRowChecks(table, row, rowIndex);
      }
    }
    await this.#stageTriggerDerivedInserts(
      transaction,
      table,
      "update",
      input.keys.length,
      sessionUpdateValueAt,
      "before",
      cascadeBudget,
    );
    const changedColumns = Object.keys(input.changes).sort();
    const columns = [keyColumn, ...changedColumns.map((name) => findColumn(table, name))];
    const segmentId = this.#createId();
    const columnBlockIds: Record<string, string[]> = {};
    const blockStager = new BoundedWriteBlockStager(transaction);
    const plannedColumns = columns.map((column) =>
      writeColumnValues(
        column.type,
        column.id === keyColumn.id ? input.keys : (input.changes[column.name] ?? []),
      ),
    );
    const ranges = writeBlockRanges(
      plannedColumns,
      input.keys.length,
      this.#rowsPerBlock,
      this.#targetBlockBytes,
    );
    for (const [columnIndex, column] of columns.entries()) {
      const values = column.id === keyColumn.id ? input.keys : (input.changes[column.name] ?? []);
      const plannedColumn = plannedColumns[columnIndex];
      if (plannedColumn === undefined) throw new Error(`Write column disappeared: ${column.name}`);
      const blockIds: string[] = [];
      for (const [part, { start, end }] of ranges.entries()) {
        await blockStager.prepare(
          maximumWriteBlockStoredBytes(plannedColumn, start, end, this.#compression),
        );
        const slice = values.slice(start, end);
        const bytes = await this.#encodeColumnBlock(column.id, asColumnInput(column.type, slice));
        const blockId = [
          "table",
          table.id,
          "segment",
          segmentId,
          "update-column",
          column.id,
          "part",
          String(part).padStart(6, "0"),
        ].join("/");
        blockStager.add({ id: blockId, bytes });
        blockIds.push(blockId);
      }
      columnBlockIds[column.id] = blockIds;
    }
    await blockStager.stageWithSegments([
      {
        id: segmentId,
        tableId: table.id,
        transactionId: transaction.id,
        rowCount: input.keys.length,
        rowIdStart: 0n,
        rowIdEndExclusive: 0n,
        columnBlockIds,
        kind: "update",
        keyColumnId: keyColumn.id,
        level: 0,
        logicalOrder: 0,
        commitOrdinal: transaction.pendingSegmentIds.length,
        rowIdSpans: [],
        createdAt: dateIsoString(this.#now()),
      },
    ]);
    await this.#stageTriggerDerivedInserts(
      transaction,
      table,
      "update",
      input.keys.length,
      sessionUpdateValueAt,
      "after",
      cascadeBudget,
    );
    return {
      tableName: table.name,
      segmentId,
      rowCount: input.keys.length,
      ...(tableGeneratedExpressions(table).length === 0
        ? {}
        : {
            generatedColumns: Object.fromEntries(
              tableGeneratedExpressions(table).map(({ column }) => [
                column.name,
                (input.changes[column.name] ?? []).map(
                  (value) => externalSqlDomainValue(value) as BatchValue,
                ),
              ]),
            ),
          }),
    };
  }

  async #sessionDelete(
    transaction: DatabaseTransaction,
    tableName: string,
    input: DeleteBatchInput,
    cascadeBudget = 1,
    referentialBudget = REFERENTIAL_CASCADES,
  ): Promise<StagedWriteResult> {
    const table = await this.#findTable(tableName);
    await this.#assertCompactionCapacity(table, transaction);
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) {
      throw new TypeError(`Table needs a unique key before rows can be deleted: ${table.name}`);
    }
    const keyDomain = keyColumn.sqlDomain;
    if (keyDomain !== undefined) {
      input = {
        keys: input.keys.map((value) => normalizeSqlDomainValue(keyDomain, value)),
      };
    }
    // The dependents go first and in this same scope, so a cascade publishes with its cause.
    await this.#applyReferentialActions(
      table,
      [...input.keys],
      {
        query: (sql, options) => this.#sessionQuery(transaction, sql, options ?? {}),
        updateBatch: (name, update) =>
          this.#sessionUpdate(transaction, name, update, cascadeBudget),
        deleteBatch: (name, remove) =>
          this.#sessionDelete(transaction, name, remove, cascadeBudget, referentialBudget - 1),
      },
      referentialBudget,
    );
    if (input.keys.length === 0) throw new TypeError("A delete batch needs at least one key");
    const keys = new Map<string, Exclude<BatchValue, null>>();
    const keyStringByteLengths =
      keyColumn.type === "string" ? new Array<number>(input.keys.length) : undefined;
    for (let index = 0; index < input.keys.length; index += 1) {
      const value = input.keys[index] as BatchValue;
      const byteLength = validateValue(keyColumn, value, index);
      if (keyStringByteLengths !== undefined) keyStringByteLengths[index] = byteLength ?? 0;
      if (value === null) throw new TypeError(`Unique key cannot be null: ${keyColumn.name}`);
      const token = keyToken(keyColumn.type, value);
      if (keys.has(token))
        throw new TypeError(`Duplicate key in delete batch: ${formatValue(value)}`);
      keys.set(token, value);
    }
    if (keyStringByteLengths !== undefined) {
      validatedStringByteLengths.set(input.keys, keyStringByteLengths);
    }
    transaction.setUniqueKeyChanges({
      tableId: table.id,
      keyTokens: [...keys.keys()],
      requireAbsent: false,
      remove: true,
    });
    const secondaryCoverage = buildSecondaryDeleteCoverage(table);
    if (secondaryCoverage.length > 0) {
      transaction.setFtsChanges({ tableId: table.id, columns: secondaryCoverage });
    }
    // Fire only per existing row (session-visible state included): missing keys must not
    // produce phantom all-null OLD images.
    const preImages = (
      await this.#triggerPreImages(
        table,
        keyColumn,
        [...keys.values()],
        "delete",
        (preImageSql, params) => this.#sessionQuery(transaction, preImageSql, { params }),
        readyUniqueSecondaryIndexes(table).length > 0,
      )
    ).filter((row) => row !== undefined);
    stageSecondaryUniqueMutationChanges(transaction, table, undefined, preImages);
    const sessionDeleteValueAt = (
      source: "new" | "old",
      column: string,
      rowIndex: number,
    ): BatchValue => (source === "old" ? (preImages[rowIndex]?.[column] ?? null) : null);
    await this.#stageTriggerDerivedInserts(
      transaction,
      table,
      "delete",
      preImages.length,
      sessionDeleteValueAt,
      "before",
      cascadeBudget,
    );
    const values = [...keys.values()];
    if (keyStringByteLengths !== undefined) {
      validatedStringByteLengths.set(values, keyStringByteLengths);
    }
    const segmentId = this.#createId();
    const blockIds: string[] = [];
    const blockStager = new BoundedWriteBlockStager(transaction);
    const plannedColumn = writeColumnValues(keyColumn.type, values);
    const ranges = writeBlockRanges(
      [plannedColumn],
      values.length,
      this.#rowsPerBlock,
      this.#targetBlockBytes,
    );
    for (const [part, { start, end }] of ranges.entries()) {
      await blockStager.prepare(maximumWriteBlockStoredBytes(plannedColumn, start, end, "raw"));
      const slice = values.slice(start, end);
      const bytes = await this.#encodeColumnBlock(
        keyColumn.id,
        asColumnInput(keyColumn.type, slice),
        "raw",
      );
      const blockId = [
        "table",
        table.id,
        "segment",
        segmentId,
        "delete-key",
        keyColumn.id,
        "part",
        String(part).padStart(6, "0"),
      ].join("/");
      blockStager.add({ id: blockId, bytes });
      blockIds.push(blockId);
    }
    await blockStager.stageWithSegments([
      {
        id: segmentId,
        tableId: table.id,
        transactionId: transaction.id,
        rowCount: keys.size,
        rowIdStart: 0n,
        rowIdEndExclusive: 0n,
        columnBlockIds: { [keyColumn.id]: blockIds },
        kind: "delete",
        keyColumnId: keyColumn.id,
        level: 0,
        logicalOrder: 0,
        commitOrdinal: transaction.pendingSegmentIds.length,
        rowIdSpans: [],
        createdAt: dateIsoString(this.#now()),
      },
    ]);
    await this.#stageTriggerDerivedInserts(
      transaction,
      table,
      "delete",
      preImages.length,
      sessionDeleteValueAt,
      "after",
      cascadeBudget,
    );
    return { tableName: table.name, segmentId, rowCount: keys.size };
  }

  #notifyLiveCommit(): void {
    for (const set of this.#liveSets) set.notifyLocalCommit();
  }

  /** Executes a built ORM query through the same streaming-first pipeline as compiled SQL. */
  async run<TRow>(query: {
    kind: "typed-query";
    plan: CompiledQuery;
    __row?: TRow;
  }): Promise<TRow[]> {
    const probe = this.store.getCatalogProbe.bind(this.store);
    // The same memo a SQL query gets, keyed by the plan: a typed query is compiled once by the
    // builder and run many times, and it used to re-execute on every run.
    if (query.plan.usesStatementDatetime === true || query.plan.usesVolatileFunctions === true) {
      return (await this.#queryCompiled(query.plan)).rows as TRow[];
    }
    return (await this.#memoizedQuery(query.plan, `typed ${planMemoKey(query.plan)}`, {}, probe))
      .rows as TRow[];
  }

  /**
   * Applies a schema definition to the catalog through metadata-only steps: creating missing
   * tables, adding nullable columns, renaming columns via their stable IDs, and widening
   * nullability. The pass is idempotent — re-running after a crash completes the remaining
   * steps — and every catalog alteration is one atomic compare-and-swap, so a concurrent
   * migrator fails explicitly with a conflict instead of interleaving.
   */
  /**
   * Brings storage in line with a schema declaration. With no argument it applies the schema the
   * database was constructed with.
   */
  async migrate(
    definition: SchemaDefinition<readonly AnyTable[]> | undefined = this.#schema,
    options: MigrateOptions = {},
  ): Promise<MigrateResult> {
    if (definition === undefined) {
      throw new TypeError(
        "migrate() needs a schema: pass a definition, or construct the database with { schema }",
      );
    }
    // Table revisions also move under background full-text index activity (build stamps,
    // stale-writer invalidation), so a lost compare-and-swap no longer implies a concurrent
    // migrator. Migration is idempotent by construction — re-plan from fresh records and retry;
    // a genuinely concurrent migrator still fails explicitly once the retries are exhausted.
    let originalSteps: MigrationStep[] | undefined;
    for (let attempt = 0; ; attempt += 1) {
      try {
        const result = await this.#migrateOnce(definition, options, (steps) => {
          originalSteps ??= [...steps];
        });
        return originalSteps === undefined ? result : migrationResult(originalSteps);
      } catch (error) {
        if (
          (!(error instanceof TableRecordConflictError) &&
            !(error instanceof WriteConflictError)) ||
          attempt >= this.#maxCommitRetries
        ) {
          throw error;
        }
      }
    }
  }

  /**
   * A declared view states the columns its author expects. The engine infers the real output
   * schema when it creates the view; if the two disagree the declaration is a lie that every
   * reader would inherit, so the migration fails here instead.
   */
  #assertViewMatchesDeclaration(record: TableRecord | undefined, step: { view: AnyView }): void {
    if (record === undefined) throw new Error(`View was not created: ${step.view.name}`);
    const declared = Object.entries(step.view.columns).map(([name, definition]) => ({
      name,
      type: definition.type,
      ...(definition.integer ? { integer: true as const } : {}),
      ...(definition.sqlDomain === undefined ? {} : { sqlDomain: definition.sqlDomain }),
    }));
    const inferred = record.columns.map(({ name, type, integer, sqlDomain }) => ({
      name,
      type,
      ...(integer === true ? { integer: true as const } : {}),
      ...(sqlDomain === undefined ? {} : { sqlDomain }),
    }));
    const render = (
      columns: Array<{
        name: string;
        type: string;
        integer?: true;
        sqlDomain?: SqlDomain;
      }>,
    ): string =>
      columns
        .map(
          ({ name, type, integer, sqlDomain }) =>
            `${name} ${type}${integer === true ? " integer" : ""}${sqlDomain === undefined ? "" : ` ${JSON.stringify(sqlDomain)}`}`,
        )
        .join(", ");
    if (render(declared) !== render(inferred)) {
      throw new TypeError(
        `View ${step.view.name} declares (${render(declared)}) but its query produces ` +
          `(${render(inferred)})`,
      );
    }
  }

  /**
   * Whether any visible row holds NULL in this column, proven from block headers alone.
   *
   * Every block records its own null count, and that field is covered by the envelope checksum
   * the format integrity-checks independently of the payload — the same guarantee zone-map
   * pruning already relies on. So tightening a column to NOT NULL costs one header read per block
   * of that column, not a scan of its values: bytes are fetched, but nothing is decompressed or
   * decoded.
   *
   * A segment written before the column existed contributes NULLs for all its rows unless the
   * column carries a backfill, which is exactly what makes those rows non-null.
   */
  async #columnHoldsNull(table: TableRecord, columnId: string): Promise<boolean> {
    const record = table.columns.find((candidate) => candidate.id === columnId);
    if (record === undefined) return true;
    const snapshot = await this.#transactions.openSnapshot();
    const segments = await this.#visibleSegmentRecords(table, snapshot);
    for (const segment of segments) {
      if (segment.rowCount === 0) continue;
      const kind = segment.kind;
      // Only append-shaped histories are provable this way: a delete or update segment means a
      // row's live value is decided by replay, which headers cannot settle.
      if (kind !== "insert" && kind !== "base") return true;
      const blockIds = segment.columnBlockIds[columnId];
      if (blockIds === undefined || blockIds.length === 0) {
        if (record.backfill === undefined) return true;
        continue;
      }
      for (let start = 0; start < blockIds.length; start += 16) {
        const window = blockIds.slice(start, start + 16);
        const fetched = await this.#getBlocksWindowed(window);
        for (const bytes of fetched) {
          if (bytes === undefined) return true;
          if (inspectBlock(bytes).nullCount > 0) return true;
        }
      }
    }
    return false;
  }

  /**
   * Bumps a column's auto-increment counter past every key already stored, so adopting the
   * generator on a populated table cannot mint an id that collides with one already written.
   *
   * The largest key comes from the numeric zone map each block carries in its header, so this
   * costs one header read per block of the key column — no decode, no scan. A block without a
   * zone map (or a non-numeric column) makes the maximum unknowable this way, and the migration
   * is refused rather than seeded from an incomplete picture.
   */
  async #autoIncrementSeed(
    table: TableRecord,
    columnName: string,
  ): Promise<{ columnId: string; atLeast: bigint }> {
    const column = table.columns.find(({ name }) => name === columnName);
    if (column === undefined) {
      throw new TypeError(`Auto-increment column does not exist: ${table.name}.${columnName}`);
    }
    if (column.type !== "number") {
      throw new TypeError(`Auto-increment requires a number column: ${table.name}.${columnName}`);
    }
    const snapshot = await this.#transactions.openSnapshot();
    const segments = await this.#visibleSegmentRecords(table, snapshot);
    let largest = 0;
    for (const segment of segments) {
      if (segment.rowCount === 0) continue;
      const blockIds = segment.columnBlockIds[column.id] ?? [];
      if (blockIds.length === 0) continue;
      for (let start = 0; start < blockIds.length; start += 16) {
        const fetched = await this.#getBlocksWindowed(blockIds.slice(start, start + 16));
        for (const bytes of fetched) {
          if (bytes === undefined) {
            throw new TypeError(
              `Auto-increment cannot be adopted for ${table.name}.${columnName}: a block is missing`,
            );
          }
          const zoneMap = inspectBlock(bytes).metadata.zoneMap;
          if (zoneMap === undefined) {
            throw new TypeError(
              `Auto-increment cannot be adopted for ${table.name}.${columnName}: a block carries ` +
                `no zone map, so the largest existing key is unknown without a scan`,
            );
          }
          if (zoneMap.max > largest) largest = zoneMap.max;
        }
      }
    }
    return {
      columnId: column.id,
      atLeast: largest <= 0 ? 1n : BigInt(Math.trunc(largest)) + 1n,
    };
  }

  async #migrateOnce(
    definition: SchemaDefinition<readonly AnyTable[]>,
    options: MigrateOptions = {},
    onPlan?: (steps: readonly MigrationStep[]) => void,
  ): Promise<MigrateResult> {
    // One listTables pass drives planning and execution: a create step exists only because the
    // table was absent from this snapshot, and each altered table applies all of its steps in a
    // single compare-and-swap, so a migration costs one catalog write per changed table however
    // many tables or steps the schema carries. A concurrent creator or migrator still fails
    // explicitly through createTable's uniqueness check or the revision conflict.
    const initialProof = await this.#stableCatalogProof();
    const records = initialProof.records;
    const plan = planMigration(toCatalog(records), definition, {
      ...(options.schemaOwnsDatabase === undefined
        ? {}
        : { schemaOwnsDatabase: options.schemaOwnsDatabase }),
    });
    onPlan?.(plan.steps);
    // A migration runs when an application opens, with nobody to review it. A schema file that
    // drifted — a rename typed wrong, a branch checked out — would otherwise delete rows on
    // launch, so destroying anything is a decision the caller makes, not a default.
    if (options.allowDestructive !== true) {
      const destructive = plan.steps.filter(isDestructiveStep);
      if (destructive.length > 0) {
        const described = destructive
          .map((step) =>
            step.kind === "drop-table"
              ? `table ${step.tableName}`
              : `column ${step.tableName}.${step.columnName}`,
          )
          .join(", ");
        throw new TypeError(
          `This migration would destroy data: ${described}. Pass { allowDestructive: true } to ` +
            `apply it, or restore the declarations.`,
        );
      }
    }
    const createdTables: string[] = [];
    const replacedViews: string[] = [];
    const droppedViews: string[] = [];
    const droppedTables: string[] = [];
    let catalogChangedBeforeAlterations = false;
    const alterationsByTable = new Map<string, MigrationStep[]>();
    for (const step of plan.steps) {
      if (step.kind === "create-table") {
        const entries = Object.entries(step.table.columns);
        const uniqueEntry = entries.find(([, columnDefinition]) => columnDefinition.isUnique);
        const primaryKey = step.table.primaryKey;
        // Constraints ride along with the columns: a table declared with a relation or a row
        // condition must reject the same writes whichever path created it. Dropping them here
        // is what made `migrate()` produce a weaker table than the equivalent SQL DDL.
        const foreignKeys = declaredForeignKeys(step.table);
        const statementForeignKeys = foreignKeys.map((key) => {
          const column = key.columns[0];
          const parentColumn = key.parentColumns[0];
          if (column === undefined || parentColumn === undefined) {
            throw new TypeError(`FOREIGN KEY ${key.name} must name at least one column`);
          }
          return { ...key, column, parentColumn };
        });
        await this.runStatement({
          kind: "create-table",
          table: step.table.name,
          ...(uniqueEntry === undefined && primaryKey.length !== 1
            ? {}
            : { uniqueKey: uniqueEntry?.[0] ?? primaryKey[0] }),
          ...(primaryKey.length < 2 ? {} : { compositePrimaryKey: [...primaryKey] }),
          columns: entries.map(([name, columnDefinition]) => ({
            name,
            type: columnDefinition.type,
            ...(columnDefinition.integer ? { integer: true as const } : {}),
            ...(columnDefinition.sqlDomain === undefined
              ? {}
              : { sqlDomain: structuredClone(columnDefinition.sqlDomain) }),
            ...(columnDefinition.isNullable ? { nullable: true } : {}),
            ...(columnDefinition.defaultSpec === undefined
              ? {}
              : { defaultValue: columnDefinition.defaultSpec }),
            ...(columnDefinition.generatedSpec === undefined
              ? {}
              : { generatedValue: columnDefinition.generatedSpec }),
            ...(columnDefinition.enumValues === undefined
              ? {}
              : { enumValues: columnDefinition.enumValues }),
            ...(columnDefinition.backfillValue === undefined
              ? {}
              : {
                  backfill:
                    typeof columnDefinition.backfillValue === "function"
                      ? columnDefinition.backfillValue()
                      : columnDefinition.backfillValue,
                }),
          })),
          ...(statementForeignKeys.length === 0 ? {} : { foreignKeys: statementForeignKeys }),
          ...(step.table.checks.length === 0 ? {} : { checks: [...step.table.checks] }),
          managed: true,
        });
        createdTables.push(step.table.name);
        catalogChangedBeforeAlterations = true;
        continue;
      }
      // Views carry no data, so they are applied directly rather than batched into a table's
      // atomic column rewrite. `orReplace` makes create and redefine one path.
      if (step.kind === "replace-view") {
        const proof = await this.#stableCatalogProof();
        const inferred = inferBlockSchema(
          compileQuery(step.view.sql),
          catalogQuerySchemas(proof.records),
        );
        this.#assertViewMatchesDeclaration(
          {
            id: "prospective-view",
            name: step.view.name,
            columns: inferred.map((column, index) => ({
              id: `prospective-column-${String(index)}`,
              ...column,
              nullable: true,
            })),
            managed: false,
            revision: 0,
            view: { sql: step.view.sql, managed: true },
            createdAt: dateIsoString(this.#now()),
          },
          step,
        );
        await this.runStatement({
          kind: "create-view",
          view: step.view.name,
          sql: step.view.sql,
          orReplace: true,
          managed: true,
        });
        this.#assertViewMatchesDeclaration(await this.store.getTableByName(step.view.name), step);
        replacedViews.push(step.view.name);
        catalogChangedBeforeAlterations = true;
        continue;
      }
      if (step.kind === "drop-table") {
        await this.runStatement({ kind: "drop-table", table: step.tableName, ifExists: true });
        droppedTables.push(step.tableName);
        catalogChangedBeforeAlterations = true;
        continue;
      }
      if (step.kind === "drop-view") {
        await this.runStatement({ kind: "drop-view", view: step.viewName, ifExists: true });
        droppedViews.push(step.viewName);
        catalogChangedBeforeAlterations = true;
        continue;
      }
      const steps = alterationsByTable.get(step.tableName) ?? [];
      steps.push(step);
      alterationsByTable.set(step.tableName, steps);
    }
    const alteredTables: string[] = [];
    let alterationProof =
      alterationsByTable.size === 0
        ? undefined
        : catalogChangedBeforeAlterations
          ? await this.#stableCatalogProof()
          : initialProof;
    for (const [tableName, plannedSteps] of alterationsByTable) {
      let changed = false;
      // Destructive migration uses the same physical-retirement primitive as SQL DROP COLUMN.
      // Each removal gets a fresh dependency/catalog/manifest proof and immediately retires its
      // blocks; an idle table therefore cannot retain dead column payloads forever.
      for (const step of plannedSteps) {
        if (step.kind !== "drop-column") continue;
        await this.dropColumn(tableName, step.columnName);
        changed = true;
        alterationProof = await this.#stableCatalogProof();
      }
      const steps = plannedSteps.filter((step) => step.kind !== "drop-column");
      if (steps.length === 0) {
        if (changed) alteredTables.push(tableName);
        continue;
      }
      const proof = alterationProof;
      if (proof === undefined) throw new Error("Migration catalog proof is missing");
      const record = proof.records.find((candidate) => candidate.name === tableName);
      if (record === undefined || record.view !== undefined) {
        throw new Error(`Migration target table is missing: ${tableName}`);
      }
      // Tightening to NOT NULL is the one step that has to be earned rather than declared: the
      // catalog cannot promise what the stored rows contain, so prove it from block headers
      // before the batched compare-and-swap makes it durable.
      for (const step of steps) {
        if (step.kind !== "tighten-nullable") continue;
        const target = record.columns.find(({ name }) => name === step.columnName);
        if (target === undefined) continue;
        if (await this.#columnHoldsNull(record, target.id)) {
          throw new TypeError(
            `Column cannot tighten to non-null: ${tableName}.${step.columnName} holds NULL in ` +
              `stored rows. Give it a value everywhere, or declare it nullable.`,
          );
        }
      }
      // Adopting auto-increment seeds the counter past the largest key already stored, so a
      // generated id can never collide with one already written.
      let autoIncrementSeed: { columnId: string; atLeast: bigint } | undefined;
      for (const step of steps) {
        if (step.kind !== "set-auto-increment" || !step.enabled) continue;
        if (autoIncrementSeed !== undefined) {
          throw new TypeError(`A table may adopt only one auto-increment column: ${tableName}`);
        }
        autoIncrementSeed = await this.#autoIncrementSeed(record, step.columnName);
      }
      // A renamed column that a trigger references would silently bind NULL forever (NEW/OLD
      // bindings) or fail every firing (body target columns), so reject the rename instead.
      for (const step of steps) {
        if (step.kind !== "rename-column") continue;
        const renamed = record.columns.find((column) => column.name === step.from);
        if (renamed === undefined) continue;
        for (const owner of proof.records) {
          for (const trigger of owner.triggers ?? []) {
            if (triggerReferencesColumn(owner, trigger, record, renamed.name, false)) {
              throw new TypeError(
                `Cannot rename ${record.name}.${step.from}: trigger ${trigger.name} references it`,
              );
            }
          }
        }
      }
      // Adopting generation on an existing physical column is metadata-only only when every
      // stored value already equals the declared expression. This supports migrations from an
      // application-maintained column without silently blessing stale historical rows.
      for (const step of steps) {
        if (step.kind !== "alter-generated" || step.generatedValue === null) continue;
        const target = record.columns.find(({ name }) => name === step.columnName);
        if (target === undefined) continue;
        const expression = compileGeneratedColumnExpression(
          record.name,
          target.name,
          step.generatedValue.sql,
          record.columns,
        );
        const rows = (
          await this.query(`SELECT * FROM ${quoteSqlIdentifier(record.name)}`, { memoize: false })
        ).rows;
        for (const [rowIndex, row] of rows.entries()) {
          const expected = normalizeGeneratedColumnValue(
            target,
            evaluateRowExpression(expression, record.name, generatedEvaluationRow(record, row)),
            rowIndex,
          );
          const actual = normalizeGeneratedColumnValue(target, row[target.name] ?? null, rowIndex);
          const equal =
            expected instanceof Date && actual instanceof Date
              ? dateMilliseconds(expected) === dateMilliseconds(actual)
              : Object.is(expected, actual);
          if (!equal) {
            throw new TypeError(
              `Generated column cannot be adopted: ${record.name}.${target.name} differs from its expression at row ${String(rowIndex)}`,
            );
          }
        }
      }
      // The remaining metadata-only steps share one catalog/manifest CAS. Physical drops ran
      // above because segment rewriting and payload retirement have a stronger atomic boundary.
      const columns = applyColumnSteps(record, steps, this.#createId);
      const foreignKeyStep = steps.find((step) => step.kind === "alter-foreign-keys");
      const foreignKeys =
        foreignKeyStep?.kind === "alter-foreign-keys"
          ? foreignKeyStep.foreignKeys.map((key) => ({ ...key }))
          : record.foreignKeys;
      if (
        JSON.stringify(columns) === JSON.stringify(record.columns) &&
        JSON.stringify(foreignKeys ?? []) === JSON.stringify(record.foreignKeys ?? [])
      ) {
        if (changed) alteredTables.push(tableName);
        continue;
      }
      assertTriggerBodiesAcceptTableSchema(proof.records, record, columns);
      const candidateSchemas = catalogQuerySchemas(proof.records);
      candidateSchemas.set(record.name, columns);
      assertDependentViewsKeepSchema(proof.records, record, candidateSchemas);
      const updated = await this.store.updateTable(record.id, record.revision, {
        columns,
        ...(foreignKeyStep === undefined ? {} : { foreignKeys }),
        ...(autoIncrementSeed === undefined ? {} : { autoIncrementSeed }),
        expectedManifestVersion: { value: proof.manifestVersion },
        expectedCatalogEpoch: proof.catalogEpoch,
      });
      proof.records = proof.records.map((candidate) =>
        candidate.id === updated.id ? updated : candidate,
      );
      proof.catalogEpoch += 1;
      alteredTables.push(tableName);
    }
    return {
      createdTables,
      alteredTables,
      droppedTables,
      replacedViews,
      droppedViews,
      steps: plan.steps,
    };
  }

  /**
   * Renders the optimized logical plan for a SELECT statement plus the physical strategy notes
   * the prepared execution would choose, without executing it.
   */
  async explain(sql: string): Promise<string> {
    let plan = this.#compileCached(sql);
    // Explain reports on the plan the engine would execute, so MATCH(*)/BM25(*) expand against
    // the catalog exactly as preparation does (copy-on-write — the cache keeps "*").
    if (planContainsFts(plan)) {
      const realTables = await this.#findRealBlockTables(plan);
      plan = expandFtsColumns(plan, (tableName) => searchableFtsColumns(realTables.get(tableName)));
    }
    // The ORDER-BY-expression desugar's transparent wrapper executes as its inner block plus a
    // projection, so every execution-path note reports against the inner block.
    const reported = transparentProjectionSource(plan)?.inner ?? plan;
    const notes: string[] = [];
    if (this.#canStreamPlanShape(reported, {})) {
      notes.push("streams the base scan through resident block windows");
    } else {
      notes.push("materializes inputs at preparation");
    }
    const table =
      reported.base.derived ??
      reported.base.union ??
      reported.base.windowed ??
      reported.base.recursive;
    // A FROM-less query reads the dual row, which has no catalog record to report on.
    if (table === undefined && reported.joins.length === 0 && reported.base.table !== DUAL_TABLE) {
      const record = await this.#findTable(reported.base.table);
      const pointTemplate = record.view === undefined ? cachedPointReadTemplate(reported) : null;
      if (pointTemplate !== null) {
        const keyColumn = getUniqueKeyColumn(record);
        const keyComponents =
          keyColumn === undefined
            ? []
            : keyColumn.hidden === true
              ? primaryKeyColumns(record)
              : [keyColumn];
        const covered = new Set(pointTemplate.equalities.map((equality) => equality.column));
        if (
          keyComponents.length > 0 &&
          keyComponents.every((component) => covered.has(component.name))
        ) {
          notes.push(
            "key-covering equality answers as a point read when the visible history allows",
          );
        }
      }
      if (zonePredicates(reported, record).length > 0) {
        notes.push("zone-map pruning applies to the unbudgeted scan");
      }
      if (secondaryIndexPredicates(reported, record).length > 0) {
        notes.push("a ready secondary index prunes the scan to candidate row groups");
      }
      const referenced = referencedColumns(
        reported,
        new Map([[record.name, record.columns.map((column) => column.name)]]),
      ).get(record.name);
      const projected =
        referenced === undefined || referenced.length === 0
          ? []
          : resolveReadColumns(record, referenced);
      if (secondaryIndexOrderForPlan(reported, record, projected, false) !== undefined) {
        notes.push("a ready secondary index supplies ORDER BY without a sort");
        if (secondaryIndexOrderForPlan(reported, record, projected) !== undefined) {
          notes.push("a covering secondary-index scan avoids table blocks");
        }
      }
    }
    if (blockHasSubqueries(reported))
      notes.push("resolves uncorrelated subqueries at one snapshot");
    if (planContainsFts(reported)) {
      notes.push("full-text MATCH evaluates via per-dictionary term tables on the scan");
      if (table === undefined && reported.joins.length === 0) {
        const record = await this.#findTable(reported.base.table);
        const readyColumnIds = new Set(
          Object.entries(record.ftsColumns ?? {})
            .filter(
              ([, state]) =>
                state.state === "ready" && state.tokenizerVersion === FTS_TOKENIZER_VERSION,
            )
            .map(([columnId]) => columnId),
        );
        const columnsByName = new Map(
          record.columns.map((column) => [column.name, column] as const),
        );
        const scoringServed = [...this.#ftsBm25Nodes(reported).values()].every((node) =>
          node.columns.every((expression) => {
            if (expression.kind !== "column") return false;
            const column = columnsByName.get(
              expression.reference.split(".").at(-1) ?? expression.reference,
            );
            return column !== undefined && readyColumnIds.has(column.id);
          }),
        );
        const scoring = planContainsFts(reported, "bm25");
        if (readyColumnIds.size > 0 && (!scoring || scoringServed)) {
          notes.push("a ready full-text index prunes the base scan to candidate segments");
        }
        if (scoring) {
          notes.push(
            scoringServed
              ? "BM25 statistics come from the full-text index"
              : "BM25 scoring reads the full scan for corpus statistics; index pruning does not apply",
          );
        }
      } else if (planContainsFts(reported, "bm25")) {
        notes.push(
          "BM25 scoring reads the full scan for corpus statistics; index pruning does not apply",
        );
      }
    }
    return `${renderPlan(plan)}\n${notes.map((note) => `-- ${note}`).join("\n")}`;
  }

  /**
   * Executes one SQL statement. SELECT statements run through the read-only query pipeline;
   * INSERT ... VALUES maps onto a column batch insert, and UPDATE/DELETE on a unique-key table
   * read the matching keys at one snapshot and then apply the keyed mutation. The read and the
   * mutation are two steps, not one serializable transaction: a key changed by a competing writer
   * in between fails the statement explicitly rather than silently mutating other rows.
   *
   * `options` carries the engine controls a query takes: a SELECT honors all of them, and every
   * other statement checks `signal` once before running (see `ExecuteOptions`).
   */
  async execute(
    sql: string,
    params?: readonly QueryValue[],
    options: ExecuteOptions = {},
  ): Promise<ExecuteResult> {
    throwIfAborted(options.signal);
    await this.#settleExpiredStatementTransaction();
    const statement = this.#compileStatementCached(sql);
    if (statement.kind === "transaction") {
      return this.#runTransactionStatement(statement.action, statement.name);
    }
    if (statement.kind === "select") {
      return {
        kind: "rows",
        result: await this.query(statement.sql, {
          ...options,
          ...(params === undefined ? {} : { params }),
        }),
      };
    }
    // Session settings touch no data and no catalog, so they run the same inside a transaction
    // (where SET LOCAL belongs) as outside one.
    if (statement.kind === "set" || statement.kind === "show") {
      return externalizeExecuteResult(await this.runStatement(statement));
    }
    const open = this.#openTransaction;
    if (open !== undefined) {
      // Inside BEGIN … COMMIT every write stages into that one scope, so the statements publish
      // together or not at all. Schema changes are refused rather than silently auto-committed:
      // the catalog is not part of the scope, so a DDL statement inside one would land even if
      // the transaction rolled back.
      const boundStatement = bindStatementParameters(statement, params);
      if (!isTransactionalStatement(boundStatement)) {
        throw new TypeError(
          `${boundStatement.kind.toUpperCase().replace("-", " ")} is not allowed inside a transaction`,
        );
      }
      return externalizeExecuteResult(
        await this.#projectReturningItems(
          boundStatement,
          await this.#duringTransaction(open, () => open.session.executeStatement(boundStatement)),
        ),
      );
    }
    const boundStatement = bindStatementParameters(statement, params);
    return externalizeExecuteResult(
      await this.#projectReturningItems(boundStatement, await this.runStatement(boundStatement)),
    );
  }

  /**
   * E141-04 on the child side: every non-null value written into a referencing column must name
   * a row that exists in the parent. The probe is the parent's own unique-key membership — the
   * same index the keyed write paths address rows by — and only what that index cannot settle
   * is read through the writing transaction, so a child inserted next to its parent in one
   * scope still sees it.
   */
  async #assertForeignKeysPresent(
    table: TableRecord,
    rowsByColumn: (column: string) => readonly BatchValue[],
    read: (sql: string, params: QueryValue[]) => Promise<QueryResult>,
    transaction?: DatabaseTransaction,
  ): Promise<void> {
    for (const key of table.foreignKeys ?? []) {
      if (key.enforced === false) continue;
      const childNames = foreignKeyColumns(key);
      const parentNames = foreignKeyParentColumns(key);
      if (childNames.length > 1) {
        const vectors = childNames.map(rowsByColumn);
        const rowCount = vectors[0]?.length ?? 0;
        if (vectors.some((values) => values.length !== rowCount)) {
          throw new TypeError(`FOREIGN KEY ${key.name} columns have different row counts`);
        }
        const tuples = new Map<string, QueryValue[]>();
        for (let row = 0; row < rowCount; row += 1) {
          const values = vectors.map((vector) => vector[row] ?? null);
          // MATCH SIMPLE: any NULL makes the whole referencing row satisfied.
          if (values.some((value) => value === null)) continue;
          const tuple = values as QueryValue[];
          tuples.set(sqlTupleToken(tuple), tuple);
        }
        if (tuples.size === 0) continue;
        const parent = await this.store.getTableByName(key.parentTable);
        if (parent === undefined) {
          throw new TypeError(
            `FOREIGN KEY ${key.name} references a missing table: ${key.parentTable}`,
          );
        }
        let wanted = [...tuples.values()];
        const parentKey = getUniqueKeyColumn(parent);
        const primaryColumns = primaryKeyColumns(parent);
        if (
          parent.uniqueKeyLookupReady === true &&
          parentKey?.hidden === true &&
          primaryColumns.map((column) => column.name).join("\u0000") === parentNames.join("\u0000")
        ) {
          const byTuple = new Map(
            wanted.map((tuple) => {
              const locator = compositeKeyValue(primaryColumns, tuple);
              return [sqlTupleToken(tuple), keyToken(parentKey.type, locator)] as const;
            }),
          );
          const overlay =
            transaction === undefined ? undefined : this.#stagedKeyOverlay(transaction, parent.id);
          const probed = [...new Set(byTuple.values())].filter(
            (token) => overlay?.added.has(token) !== true,
          );
          const present = new Set(
            probed.length === 0 ? [] : await this.#existingUniqueKeysWindowed(parent.id, probed),
          );
          wanted = wanted.filter((tuple) => {
            const token = byTuple.get(sqlTupleToken(tuple)) ?? "";
            if (overlay?.removed.has(token) === true) return true;
            if (overlay?.added.has(token) === true) return false;
            return !present.has(token);
          });
        }
        if (wanted.length === 0) continue;
        const predicates = wanted
          .map(
            () => `(${parentNames.map((name) => `${quoteSqlIdentifier(name)} = ?`).join(" AND ")})`,
          )
          .join(" OR ");
        const found = await read(
          `SELECT ${parentNames
            .map((name, index) => `${quoteSqlIdentifier(name)} AS p${String(index)}`)
            .join(", ")} FROM ${quoteSqlIdentifier(key.parentTable)} WHERE ${predicates}`,
          wanted.flat(),
        );
        const present = new Set(
          found.rows.map((row) =>
            sqlTupleToken(parentNames.map((_, index) => row[`p${String(index)}`] ?? null)),
          ),
        );
        const missing = wanted.find((tuple) => !present.has(sqlTupleToken(tuple)));
        if (missing !== undefined) {
          throw new TypeError(
            `FOREIGN KEY ${key.name} has no ${key.parentTable} row with (${parentNames.join(", ")}) (${missing.map(String).join(", ")})`,
          );
        }
        continue;
      }
      const childColumn = key.columns[0];
      const parentColumn = key.parentColumns[0];
      if (childColumn === undefined || parentColumn === undefined) {
        throw new TypeError(`FOREIGN KEY ${key.name} has no columns`);
      }
      const values = rowsByColumn(childColumn);
      const distinct = [...new Set(values.filter((value): value is QueryValue => value !== null))];
      if (distinct.length === 0) continue;
      // A NULL reference names no parent, which the standard leaves satisfied.
      const parent = await this.store.getTableByName(key.parentTable);
      if (parent === undefined) {
        throw new TypeError(
          `FOREIGN KEY ${key.name} references a missing table: ${key.parentTable}`,
        );
      }
      const wanted = [
        ...(await this.#foreignKeyValuesNeedingRead(parent, key, distinct, transaction)),
      ];
      if (wanted.length === 0) continue;
      const found = await read(
        `SELECT ${quoteSqlIdentifier(parentColumn)} AS parent_key FROM ${quoteSqlIdentifier(
          key.parentTable,
        )} WHERE ${quoteSqlIdentifier(parentColumn)} IN (${wanted.map(() => "?").join(", ")})`,
        wanted,
      );
      // Compared by the same token the keyed paths use, so 1 and '1' cannot pass for each other.
      const token = (value: QueryValue): string =>
        value instanceof Date ? `d${dateIsoString(value)}` : `${typeof value}:${String(value)}`;
      const present = new Set(
        found.rows.flatMap((row) => {
          const value = row.parent_key ?? null;
          return value === null ? [] : [token(value)];
        }),
      );
      const missing = wanted.find((value) => !present.has(token(value)));
      if (missing !== undefined) {
        throw new TypeError(
          `FOREIGN KEY ${key.name} has no ${key.parentTable} row with ${parentColumn} ${String(missing)}`,
        );
      }
    }
  }

  /**
   * Which referenced values a FOREIGN KEY probe still has to read rows for. A parent whose
   * persistent unique-key lookup is ready answers membership with point reads instead of a
   * scan, so the ordinary case — every referenced parent already committed — costs no table
   * read at all. Keys an open scope staged count as present, keys it removed stay unproven,
   * and anything the lookup cannot decide falls through to the caller's transactional read,
   * which is also what reports the violation.
   */
  async #foreignKeyValuesNeedingRead(
    parent: TableRecord,
    key: NonNullable<TableRecord["foreignKeys"]>[number],
    wanted: readonly QueryValue[],
    transaction: DatabaseTransaction | undefined,
  ): Promise<readonly QueryValue[]> {
    if (parent.uniqueKeyLookupReady !== true) return wanted;
    const parentKey = getUniqueKeyColumn(parent);
    if (parentKey === undefined || parentKey.name !== key.parentColumns[0]) return wanted;
    const tokens = new Map<QueryValue, string>();
    for (const value of wanted) {
      // A value the key encoding rejects (wrong type for the parent key, a non-finite number)
      // is a violation the read reports with its own message rather than a thrown encoding error.
      const token = tryKeyToken(parentKey.type, value);
      if (token === undefined) return wanted;
      tokens.set(value, token);
    }
    const overlay =
      transaction === undefined ? undefined : this.#stagedKeyOverlay(transaction, parent.id);
    const probed = [...new Set(tokens.values())].filter(
      (token) => overlay?.added.has(token) !== true,
    );
    const present =
      probed.length === 0
        ? new Set<string>()
        : new Set(await this.#existingUniqueKeysWindowed(parent.id, probed));
    return wanted.filter((value) => {
      const token = tokens.get(value) ?? "";
      if (overlay?.removed.has(token) === true) return true;
      if (overlay?.added.has(token) === true) return false;
      return !present.has(token);
    });
  }

  /**
   * E141-04 on the parent side: what a delete does to the rows referencing the parent it
   * removes. RESTRICT refuses, CASCADE deletes them, SET NULL clears the reference — each
   * applied inside the deleting transaction, so the parent and its dependents publish together.
   * A cascade that reaches another parent cascades again, bounded like a trigger chain.
   */
  async #applyReferentialActions(
    parent: TableRecord,
    keys: readonly QueryValue[],
    session: {
      query: (sql: string, options?: QueryOptions) => Promise<QueryResult>;
      updateBatch: (table: string, input: UpdateBatchInput) => Promise<unknown>;
      deleteBatch: (table: string, input: DeleteBatchInput) => Promise<unknown>;
    },
    cascadeBudget: number,
  ): Promise<void> {
    if (keys.length === 0) return;
    const children = (await this.#childForeignKeys(parent.name)).filter(
      ({ key }) => key.enforced !== false,
    );
    if (children.length === 0) return;
    if (cascadeBudget < 0) {
      throw new Error(`Referential cascade depth exceeded at table: ${parent.name}`);
    }
    const parentPrimary = primaryKeyColumns(parent);
    let parentTuples: QueryValue[][];
    if (parentPrimary.length > 1) {
      const locator = getUniqueKeyColumn(parent);
      if (locator?.hidden !== true)
        throw new Error(`Composite key locator is missing: ${parent.name}`);
      const found = await session.query(
        `SELECT ${parentPrimary
          .map((column, index) => `${quoteSqlIdentifier(column.name)} AS p${String(index)}`)
          .join(", ")} FROM ${quoteSqlIdentifier(parent.name)} WHERE ${quoteSqlIdentifier(
          locator.name,
        )} IN (${keys.map(() => "?").join(", ")})`,
        { params: [...keys] },
      );
      parentTuples = found.rows.map((row) =>
        parentPrimary.map((_, index) => row[`p${String(index)}`] ?? null),
      );
    } else {
      parentTuples = keys.map((key) => [key]);
    }
    if (parentTuples.length === 0) return;
    for (const { table: child, key } of children) {
      const childColumns = foreignKeyColumns(key);
      const firstChildColumn = childColumns[0];
      if (firstChildColumn === undefined) {
        throw new Error(`FOREIGN KEY ${key.name} has no child columns`);
      }
      const childKeyColumn = getUniqueKeyColumn(child);
      const selected =
        childKeyColumn === undefined
          ? quoteSqlIdentifier(firstChildColumn)
          : `${quoteSqlIdentifier(childKeyColumn.name)} AS child_key`;
      const predicates = parentTuples
        .map(
          () =>
            `(${childColumns.map((column) => `${quoteSqlIdentifier(column)} = ?`).join(" AND ")})`,
        )
        .join(" OR ");
      const affected = await session.query(
        `SELECT ${selected} FROM ${quoteSqlIdentifier(child.name)} WHERE ${predicates}`,
        { params: parentTuples.flat() },
      );
      if (affected.rows.length === 0) continue;
      if (key.onDelete === "restrict") {
        throw new TypeError(
          `FOREIGN KEY ${key.name} still has ${String(affected.rows.length)} ${child.name} row(s) referencing ${parent.name}`,
        );
      }
      if (childKeyColumn === undefined) {
        throw new TypeError(
          `FOREIGN KEY ${key.name} needs a unique key on ${child.name} to ${key.onDelete}`,
        );
      }
      const childKeys = affected.rows
        .map((row) => row.child_key ?? null)
        .filter((value): value is Exclude<BatchValue, null> => value !== null);
      if (key.onDelete === "cascade") {
        await session.deleteBatch(child.name, { keys: childKeys });
        continue;
      }
      await session.updateBatch(child.name, {
        keys: childKeys,
        changes: Object.fromEntries(
          childColumns.map((column) => [column, childKeys.map(() => null)]),
        ),
      });
    }
  }

  /** Runs one statement inside an open transaction, holding off the idle sweep while it does. */
  async #duringTransaction<T>(
    state: { busy: number; activeAt: number },
    run: () => Promise<T>,
  ): Promise<T> {
    state.busy += 1;
    state.activeAt = dateMilliseconds(this.#now());
    try {
      return await run();
    } finally {
      state.busy -= 1;
      state.activeAt = dateMilliseconds(this.#now());
    }
  }

  /**
   * Detaches one statement transaction and joins its durable abort. Timers cannot await, so the
   * cleanup promise remains database-owned and the next statement joins it before opening or
   * reading another scope.
   */
  #rollbackStatementTransaction(state: OpenStatementTransaction): Promise<void> {
    if (this.#openTransaction === state) this.#openTransaction = undefined;
    clearInterval(state.timer);
    state.settle("rollback");
    const cleanup = state.finished.then(() => undefined);
    this.#statementTransactionCleanup = cleanup;
    void cleanup
      .finally(() => {
        if (this.#statementTransactionCleanup === cleanup) {
          this.#statementTransactionCleanup = undefined;
        }
      })
      .catch(() => undefined);
    return cleanup;
  }

  /** A throttled/background timer cannot make an already-idle transaction live again. */
  async #settleExpiredStatementTransaction(): Promise<void> {
    const pending = this.#statementTransactionCleanup;
    if (pending !== undefined) await pending;
    const open = this.#openTransaction;
    if (
      open === undefined ||
      open.busy > 0 ||
      dateMilliseconds(this.#now()) - open.activeAt < this.#transactionIdleTimeoutMs
    ) {
      return;
    }
    await this.#rollbackStatementTransaction(open);
  }

  /**
   * BEGIN / COMMIT / ROLLBACK (E151). The scope is the same one `write()` opens, held between
   * statements instead of around a callback: every write stages into it, reads see what it has
   * staged, COMMIT publishes, and ROLLBACK discards.
   *
   * An abandoned transaction is the hazard a statement-level BEGIN introduces — a lost reference
   * or a closed tab would otherwise hold a scope open forever — so one that goes untouched for
   * `transactionIdleTimeoutMs` rolls itself back, and closing the database rolls back whatever
   * is open.
   */
  async #runTransactionStatement(
    action: "begin" | "commit" | "rollback" | "savepoint" | "rollback-to" | "release",
    name?: string,
  ): Promise<ExecuteResult> {
    if (action === "begin") {
      if (this.#openTransaction !== undefined) {
        throw new TypeError("A transaction is already open; COMMIT or ROLLBACK it first");
      }
      let start!: (writer: TransactionStatementWriter) => void;
      let failStart!: (error: unknown) => void;
      const opened = new Promise<TransactionStatementWriter>((resolve, reject) => {
        start = resolve;
        failStart = reject;
      });
      let settle!: (outcome: "commit" | "rollback") => void;
      const decided = new Promise<"commit" | "rollback">((resolve) => {
        settle = resolve;
      });
      const finished = this.#openWriteScope<null>(async (_session, _transaction, writer) => {
        start(writer);
        if ((await decided) === "rollback") throw new TransactionRollback();
        return null;
      });
      // Scope startup performs maintenance admission, the catalog probe, and the durable lease
      // admission before invoking its callback. Reflect any refusal into the startup rendezvous;
      // otherwise BEGIN waits forever on a resolve-only promise while `finished` rejects with no
      // state installed to observe it. Promise settlement is idempotent, so a later failure after
      // `start(writer)` cannot replace the successfully opened session.
      void finished.catch((error: unknown) => {
        failStart(error);
      });
      const session = await opened;
      const state = {
        session,
        settle,
        busy: 0,
        activeAt: dateMilliseconds(this.#now()),
        savepoints: [],
        finished: finished.then(
          ({ version }) => ({ version }),
          (error: unknown) => {
            if (error instanceof TransactionRollback) return { version: null };
            throw error;
          },
        ),
        timer: setInterval(() => {
          // Abandoned means nothing has run for the whole timeout — not that the timeout
          // elapsed. A statement in flight, however slow, and one that finished a moment ago
          // both count as activity; only a caller that walked away trips this.
          if (this.#openTransaction !== state || state.busy > 0) return;
          if (dateMilliseconds(this.#now()) - state.activeAt < this.#transactionIdleTimeoutMs)
            return;
          void this.#rollbackStatementTransaction(state).catch(() => undefined);
        }, this.#transactionIdleTimeoutMs),
      };
      // An idle sweep must never keep a process alive on its own; browsers have no unref.
      if (typeof state.timer === "object" && "unref" in state.timer) state.timer.unref();
      this.#openTransaction = state;
      return { kind: "transaction", action: "begin" };
    }
    const open = this.#openTransaction;
    if (open === undefined) {
      throw new TypeError(`${action.toUpperCase()} without an open transaction`);
    }
    if (action === "savepoint") {
      if (name === undefined) throw new TypeError("SAVEPOINT needs a name");
      await this.#duringTransaction(open, async () => {
        if (open.savepoints.length >= MAX_TRANSACTION_SAVEPOINTS) {
          throw new RangeError(
            `A transaction cannot hold more than ${String(MAX_TRANSACTION_SAVEPOINTS)} savepoints`,
          );
        }
        const retainedBytes = open.session.checkpointRetainedBytes();
        const totalBytes = open.savepoints.reduce(
          (total, savepoint) =>
            safeWholeNumberSum(
              [total, savepoint.retainedBytes],
              "Transaction savepoint retained bytes",
            ),
          retainedBytes,
        );
        if (totalBytes > MAX_TRANSACTION_SAVEPOINT_BYTES) {
          throw new RangeError(
            `Transaction savepoints cannot retain more than ${String(MAX_TRANSACTION_SAVEPOINT_BYTES)} bytes`,
          );
        }
        open.savepoints.push({ name, checkpoint: open.session.checkpoint(), retainedBytes });
      });
      return { kind: "transaction", action, name };
    }
    if (action === "rollback-to" || action === "release") {
      if (name === undefined) throw new TypeError(`${action.toUpperCase()} needs a name`);
      let index = -1;
      for (let candidate = open.savepoints.length - 1; candidate >= 0; candidate -= 1) {
        if (open.savepoints[candidate]?.name === name) {
          index = candidate;
          break;
        }
      }
      if (index === -1) throw new TypeError(`Savepoint does not exist: ${name}`);
      if (action === "rollback-to") {
        const checkpoint = open.savepoints[index]?.checkpoint;
        if (checkpoint === undefined) throw new Error(`Savepoint disappeared: ${name}`);
        await this.#duringTransaction(open, () => open.session.rollbackTo(checkpoint));
        // The named marker remains usable; everything established after it is gone.
        open.savepoints.splice(index + 1);
      } else {
        // PostgreSQL RELEASE closes the named marker and every marker nested inside it.
        open.savepoints.splice(index);
      }
      return { kind: "transaction", action, name };
    }
    this.#openTransaction = undefined;
    clearInterval(open.timer);
    open.settle(action === "commit" ? "commit" : "rollback");
    const { version } = await open.finished;
    return {
      kind: "transaction",
      action,
      ...(version === null || version === undefined ? {} : { version }),
    };
  }

  /**
   * ON CONFLICT (key) DO UPDATE SET: expressions see the statement-start target row plus the
   * default-filled EXCLUDED row. Classification, evaluation, update, insert, and RETURNING all
   * run in one write scope, so any failure aborts the statement.
   */
  async #mergeConflictingInsertRows(
    statement: Extract<CompiledStatement, { kind: "insert" }>,
    options: RunStatementOptions,
  ): Promise<ExecuteResult> {
    const table = await this.#findTable(statement.table);
    const keyColumn = getUniqueKeyColumn(table);
    const onConflict = statement.onConflict;
    if (onConflict === undefined) throw new Error("ON CONFLICT update metadata is missing");
    const conflictColumns = onConflict.columns ?? [onConflict.column];
    const addressColumns =
      keyColumn?.hidden === true
        ? primaryKeyColumns(table).map(({ name }) => name)
        : keyColumn === undefined
          ? []
          : [keyColumn.name];
    if (
      keyColumn === undefined ||
      conflictColumns.length !== addressColumns.length ||
      conflictColumns.some((name, index) => name !== addressColumns[index])
    ) {
      throw new TypeError(
        `ON CONFLICT targets the table's primary or unique key columns: ${addressColumns.join(", ") || "(none)"}`,
      );
    }
    statement = foldInsertColumns(table, statement);
    for (const name of statement.columns) {
      if (!table.columns.some((column) => column.name === name)) {
        throw new TypeError(`INSERT column does not exist: ${name}`);
      }
    }
    const proposedBatch = insertStatementBatch(statement);
    coerceSqlWriteBatch(table, proposedBatch);
    const statementNow = this.#now();
    const filledProposed = await fillColumnDefaults(
      table,
      proposedBatch,
      (sql) => this.#evaluateDefaultExpression(sql, statementNow),
      statement.rows.length,
    );
    normalizeDomainBatch(table, filledProposed.batch);
    fillStoredGeneratedColumns(
      table,
      filledProposed.batch,
      statement.rows.length,
      filledProposed.generated,
    );
    fillCompositePrimaryKey(table, filledProposed.batch, statement.rows.length);
    const proposed = filledProposed.batch;
    // UPSERT only handles a uniqueness conflict. Other INSERT-domain failures are still errors,
    // even when every proposed row happens to find an existing key.
    validateBatch(table, proposed, filledProposed.autoIncrement?.column.name);
    const keyValues = proposed.columns[keyColumn.name] ?? [];
    const keyToken = (value: QueryValue): string =>
      value instanceof Date ? `d${dateIsoString(value)}` : `${typeof value} ${String(value)}`;
    const proposedKeys = new Set<string>();
    for (const key of keyValues) {
      if (key === null) continue;
      const token = keyToken(key);
      if (proposedKeys.has(token)) {
        throw new TypeError(
          `ON CONFLICT DO UPDATE cannot affect ${publicKeyName(table, keyColumn)} ${String(key)} twice`,
        );
      }
      proposedKeys.add(token);
    }
    const returningColumns =
      options.returning === undefined
        ? undefined
        : options.returning === "*"
          ? visibleTableColumns(table).map(({ name }) => name)
          : [...options.returning];
    for (const name of returningColumns ?? []) {
      if (!table.columns.some((column) => column.name === name)) {
        throw new TypeError(`RETURNING column does not exist: ${name}`);
      }
    }
    const assignments = onConflict.assignments ?? [];
    const conflictWhere = onConflict.where;
    const conflictExpressions = [
      ...assignments.map((assignment) => assignment.expression),
      ...(conflictWhere === undefined ? [] : [conflictWhere]),
    ];
    for (const assignment of assignments) {
      const targetColumn = table.columns.find(({ name }) => name === assignment.column);
      if (targetColumn === undefined) {
        throw new TypeError(`ON CONFLICT DO UPDATE column does not exist: ${assignment.column}`);
      }
      if (
        targetColumn.id === keyColumn.id ||
        (table.primaryKeyColumnIds ?? []).includes(targetColumn.id)
      ) {
        throw new TypeError("ON CONFLICT DO UPDATE cannot reassign the conflict key");
      }
    }
    for (const expression of conflictExpressions) {
      for (const reference of expressionColumnNames(expression)) {
        const [alias, name, extra] = reference.split(".");
        if (alias === undefined || extra !== undefined || name === undefined) {
          throw new TypeError(`Invalid ON CONFLICT column reference: ${reference}`);
        }
        if (alias !== table.name && alias.toUpperCase() !== "EXCLUDED") {
          throw new TypeError(`Unknown ON CONFLICT row alias: ${alias}`);
        }
        if (!table.columns.some((column) => column.name === name)) {
          throw new TypeError(`ON CONFLICT column does not exist: ${reference}`);
        }
      }
    }
    const replacementColumns = visibleTableColumns(table).filter(
      (column) => !(table.primaryKeyColumnIds ?? [keyColumn.id]).includes(column.id),
    );
    const wholeRowReplacement =
      conflictWhere === undefined &&
      assignments.length === replacementColumns.length &&
      replacementColumns.every((column) =>
        assignments.some(
          (assignment) =>
            assignment.column === column.name &&
            assignment.expression.kind === "column" &&
            assignment.expression.reference === `EXCLUDED.${column.name}`,
        ),
      );
    if (wholeRowReplacement) {
      // The established upsert path writes the same post-image with fewer read/commit rounds and
      // retains its bounded retry behavior under many-tab contention. Materialize the proposal
      // first: re-entering with the original omission markers would evaluate sequence, random,
      // and UUID defaults twice and could even change which row conflicts.
      const columns = visibleTableColumns(table).map(({ name }) => name);
      const deferredAutoIncrement = new Set(filledProposed.autoIncrement?.missingIndexes ?? []);
      const generatedColumns = new Set(
        table.columns.flatMap((column) =>
          column.generatedValue === undefined ? [] : [column.name],
        ),
      );
      const rows: InsertValue[][] = Array.from({ length: statement.rows.length }, (_, rowIndex) =>
        columns.map((name) =>
          generatedColumns.has(name) ||
          (name === filledProposed.autoIncrement?.column.name &&
            deferredAutoIncrement.has(rowIndex))
            ? { default: true }
            : (proposed.columns[name]?.[rowIndex] ?? null),
        ),
      );
      return this.runStatement(
        {
          ...statement,
          columns,
          rows,
          onConflict: {
            column: onConflict.column,
            ...(onConflict.columns === undefined ? {} : { columns: onConflict.columns }),
            action: "replace",
          },
        },
        options,
      );
    }
    // The general DO UPDATE path classifies proposed rows itself instead of re-entering the
    // ordinary upsert writer. Materialize its deferred auto-increment slots now so an omitted
    // generated key is a fresh key, not an explicit NULL when the fresh subset is staged.
    if (
      filledProposed.autoIncrement !== undefined &&
      filledProposed.autoIncrement.missingIndexes.length > 0
    ) {
      const values = await this.store.reserveAutoIncrement(
        table.id,
        filledProposed.autoIncrement.column.id,
        filledProposed.autoIncrement.missingIndexes.length,
        filledProposed.autoIncrement.atLeast,
      );
      patchAutoIncrementValues(proposed, filledProposed.autoIncrement, values);
      const patched = proposed.columns[filledProposed.autoIncrement.column.name] ?? [];
      for (const rowIndex of filledProposed.autoIncrement.missingIndexes) {
        validateValue(filledProposed.autoIncrement.column, patched[rowIndex] ?? null, rowIndex);
      }
    }
    const proposedRow = (index: number): DatabaseRow =>
      Object.fromEntries(
        table.columns.map(({ name }) => [name, proposed.columns[name]?.[index] ?? null]),
      );
    const apply = async (
      transaction: WriteSession,
    ): Promise<{ affectedRows: number[]; returnedRows?: QueryRow[] }> => {
      const present = await transaction.query(
        `SELECT ${quoteSqlIdentifier(keyColumn.name)} AS key FROM ${quoteSqlIdentifier(
          table.name,
        )} WHERE ${quoteSqlIdentifier(keyColumn.name)} IN (${keyValues.map(() => "?").join(", ")})`,
        { params: keyValues },
      );
      const existing = new Set(present.rows.map((row) => keyToken(row.key ?? null)));
      const freshRows: number[] = [];
      const conflictingRows: number[] = [];
      const updatedRows: number[] = [];
      const seenConflicts = new Set<string>();
      for (const rowIndex of statement.rows.keys()) {
        const key = keyValues[rowIndex] ?? null;
        if (key !== null && existing.has(keyToken(key))) {
          const token = keyToken(key);
          if (seenConflicts.has(token)) {
            throw new TypeError(
              `ON CONFLICT DO UPDATE cannot affect ${publicKeyName(table, keyColumn)} ${String(key)} twice`,
            );
          }
          seenConflicts.add(token);
          conflictingRows.push(rowIndex);
        } else freshRows.push(rowIndex);
      }
      if (conflictingRows.length > 0) {
        const keys = conflictingRows.map((rowIndex) => {
          const value = keyValues[rowIndex] ?? null;
          if (value === null) {
            throw new TypeError(`Unique key values must not be null: ${keyColumn.name}`);
          }
          return value;
        });
        const selected = await transaction.query(
          `SELECT * FROM ${quoteSqlIdentifier(table.name)} WHERE ${quoteSqlIdentifier(keyColumn.name)} IN (${keys.map(() => "?").join(", ")})`,
          { params: keys },
        );
        const currentByKey = new Map(
          selected.rows.map((row) => {
            const value = keyColumn.hidden
              ? compositeKeyValue(
                  primaryKeyColumns(table),
                  primaryKeyColumns(table).map(({ name }) => row[name] ?? null),
                )
              : (row[keyColumn.name] ?? null);
            return [keyToken(value), row] as const;
          }),
        );
        const updateKeys: QueryValue[] = [];
        const changes: Record<string, BatchValue[]> = Object.fromEntries(
          assignments.map(({ column }) => [column, []]),
        );
        for (const [position, rowIndex] of conflictingRows.entries()) {
          const key = keys[position];
          if (key === undefined) throw new Error("ON CONFLICT key is missing");
          const current = currentByKey.get(keyToken(key));
          if (current === undefined) {
            throw new Error(`ON CONFLICT row disappeared before update: ${String(key)}`);
          }
          const excluded = proposedRow(rowIndex);
          const joined = { [table.name]: current, EXCLUDED: excluded };
          if (
            conflictWhere !== undefined &&
            evaluateJoinedRowExpression(conflictWhere, joined) !== true
          ) {
            continue;
          }
          updateKeys.push(key);
          updatedRows.push(rowIndex);
          for (const assignment of assignments) {
            const column = table.columns.find((candidate) => candidate.name === assignment.column);
            if (column === undefined) throw new TypeError(`Unknown column: ${assignment.column}`);
            changes[assignment.column]?.push(
              storedSqlValueFromExecution(
                column,
                evaluateJoinedRowExpression(assignment.expression, joined),
              ),
            );
          }
        }
        if (updateKeys.length > 0) {
          await transaction.updateBatch(table.name, { keys: updateKeys, changes });
        }
      }
      if (freshRows.length > 0) {
        const columns: Record<string, BatchValue[]> = {};
        for (const column of table.columns) {
          if (column.generatedValue !== undefined) continue;
          columns[column.name] = freshRows.map(
            (rowIndex) => proposed.columns[column.name]?.[rowIndex] ?? null,
          );
        }
        await transaction.insertBatch(table.name, { columns });
      }
      const affectedRows = [...freshRows, ...updatedRows].sort((left, right) => left - right);
      if (returningColumns === undefined) return { affectedRows };
      const keys = affectedRows.map((rowIndex) => keyValues[rowIndex] ?? null);
      if (keys.length === 0) return { affectedRows, returnedRows: [] };
      const selectedColumns = [...new Set([keyColumn.name, ...returningColumns])];
      const selected = selectedColumns.map(quoteSqlIdentifier).join(", ");
      const result = await transaction.query(
        `SELECT ${selected} FROM ${quoteSqlIdentifier(table.name)} WHERE ${quoteSqlIdentifier(keyColumn.name)} IN (${keys.map(() => "?").join(", ")})`,
        { params: keys },
      );
      const rowsByKey = new Map(
        result.rows.map((row) => {
          const key = row[keyColumn.name] ?? null;
          return [keyToken(key), row] as const;
        }),
      );
      const returnedRows = keys.map((key) => {
        const row = rowsByKey.get(keyToken(key)) ?? {};
        return Object.fromEntries(returningColumns.map((name) => [name, row[name] ?? null]));
      });
      return { affectedRows, returnedRows };
    };
    let outcome: { affectedRows: number[]; returnedRows?: QueryRow[] };
    let version: number | null | undefined;
    if (options.writer === undefined) {
      const completed = await this.#erased.write(apply);
      outcome = completed.result;
      version = completed.version;
    } else {
      outcome = await apply(options.writer);
    }
    return {
      kind: "insert",
      table: statement.table,
      rowCount: outcome.affectedRows.length,
      ...(version === null || version === undefined ? {} : { version }),
      ...(outcome.returnedRows === undefined || returningColumns === undefined
        ? {}
        : returningExecuteFields(table, returningColumns, outcome.returnedRows)),
    };
  }

  /** ON CONFLICT DO NOTHING: drops insert rows whose unique key already exists at a snapshot. */
  async #filterConflictingInsertRows(
    statement: Extract<CompiledStatement, { kind: "insert" }>,
    writer?: StatementWriter,
  ): Promise<Extract<CompiledStatement, { kind: "insert" }>> {
    const table = await this.#findTable(statement.table);
    const keyColumn = getUniqueKeyColumn(table);
    const addressColumns =
      keyColumn?.hidden === true
        ? primaryKeyColumns(table).map(({ name }) => name)
        : keyColumn === undefined
          ? []
          : [keyColumn.name];
    // A targetless DO NOTHING means "any unique key", which for a Minnow table is its key.
    const conflictColumns =
      statement.onConflict?.anyTarget === true
        ? addressColumns
        : (statement.onConflict?.columns ??
          (statement.onConflict === undefined ? [] : [statement.onConflict.column]));
    if (
      keyColumn === undefined ||
      conflictColumns.length !== addressColumns.length ||
      conflictColumns.some((name, index) => name !== addressColumns[index])
    ) {
      throw new TypeError(
        `ON CONFLICT targets the table's primary or unique key columns: ${addressColumns.join(", ") || "(none)"}`,
      );
    }
    const proposed = insertStatementBatch(statement);
    coerceSqlWriteBatch(table, proposed);
    const statementNow = this.#now();
    const filled = await fillColumnDefaults(
      table,
      proposed,
      (sql) => this.#evaluateDefaultExpression(sql, statementNow),
      statement.rows.length,
    );
    normalizeDomainBatch(table, filled.batch);
    fillStoredGeneratedColumns(table, filled.batch, statement.rows.length, filled.generated);
    fillCompositePrimaryKey(table, filled.batch, statement.rows.length);
    const columns = visibleTableColumns(table).map(({ name }) => name);
    const deferredAutoIncrement = new Set(filled.autoIncrement?.missingIndexes ?? []);
    const generatedColumns = new Set(
      table.columns.flatMap((column) => (column.generatedValue === undefined ? [] : [column.name])),
    );
    const materializedRows: InsertValue[][] = Array.from(
      { length: statement.rows.length },
      (_, rowIndex) =>
        columns.map((name) =>
          generatedColumns.has(name) ||
          (name === filled.autoIncrement?.column.name && deferredAutoIncrement.has(rowIndex))
            ? { default: true }
            : (filled.batch.columns[name]?.[rowIndex] ?? null),
        ),
    );
    const keys = filled.batch.columns[keyColumn.name] ?? [];
    const plan: CompiledQuery = {
      sql: "(on conflict do nothing)",
      base: { table: table.name, alias: table.name },
      joins: [],
      select: [{ expression: { kind: "column", reference: keyColumn.name }, alias: "key" }],
      predicates: [
        {
          left: { kind: "column", reference: keyColumn.name },
          operator: "IN",
          right: { kind: "list", items: keys.map((value) => ({ kind: "literal", value })) },
        },
      ],
      groupBy: [],
      having: [],
      orderBy: [],
    };
    // The streaming-first pipeline: a keyed IN list narrows to the blocks that can hold the
    // keys, where the prepared path materialized the table's columns first.
    const existingRows =
      writer === undefined ? await this.#queryCompiled(plan) : await writer.queryPlan(plan);
    const existing = new Set<QueryValue | string>(
      existingRows.rows.map((row) => {
        const value = storedSqlValueFromExecution(keyColumn, row.key ?? null);
        return value instanceof Date ? dateIsoString(value) : value;
      }),
    );
    return {
      ...statement,
      columns,
      rows: materializedRows.filter((_, index) => {
        const value = keys[index] ?? null;
        if (value === null) return true;
        const normalized = value instanceof Date ? dateIsoString(value) : value;
        if (existing.has(normalized)) return false;
        // UPSERT makes its choice per proposed row. A later duplicate in the same VALUES list
        // therefore conflicts with the first retained proposal and takes DO NOTHING too.
        existing.add(normalized);
        return true;
      }),
    };
  }

  /** Rejects an INSERT staged into a scope whose keys already exist there or in committed rows. */
  async #assertStagedInsertKeysFree(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    input: InsertBatchInput,
    writer: StatementWriter,
  ): Promise<void> {
    if (keyColumn.hidden === true) return;
    const keys = insertBatchKeyValues(input, keyColumn.name);
    if (keys.length === 0) return;
    const plan: CompiledQuery = {
      sql: "(staged insert keys)",
      base: { table: table.name, alias: table.name },
      joins: [],
      select: [{ expression: { kind: "column", reference: keyColumn.name }, alias: "key" }],
      predicates: [
        {
          left: { kind: "column", reference: keyColumn.name },
          operator: "IN",
          right: { kind: "list", items: keys.map((value) => ({ kind: "literal", value })) },
        },
      ],
      groupBy: [],
      having: [],
      orderBy: [],
    };
    const existing = (await writer.queryPlan(plan)).rows[0]?.key;
    if (
      typeof existing === "string" ||
      typeof existing === "number" ||
      typeof existing === "boolean" ||
      existing instanceof Date
    ) {
      throw new UniqueConstraintError(table.name, keyColumn.name, existing);
    }
  }

  /**
   * MERGE (F312). One pass over the source, joined to the target on the match condition, decides
   * each row's branch; the branches then apply as ordinary batched writes inside a single write
   * scope, so the whole statement publishes atomically and fires the same triggers the
   * equivalent INSERT, UPDATE, and DELETE would.
   *
   * The match condition has to equate the target's unique key with something from the source:
   * that is what the keyed write paths address rows by, and it is also why a source row can
   * match at most one target row — the standard's cardinality violation cannot arise here.
   */
  async #runMerge(
    statement: Extract<CompiledStatement, { kind: "merge" }>,
  ): Promise<ExecuteResult> {
    const target = await this.#findTable(statement.table);
    const keyColumn = getUniqueKeyColumn(target);
    if (keyColumn === undefined) {
      throw new TypeError(`MERGE requires a table with a unique key: ${target.name}`);
    }
    const sourceKey = mergeSourceKeyExpression(statement, keyColumn.name);
    // The source's key value per row, and the target row it matches (or none).
    const sourceSql = mergeSourceSql(statement);
    const { result: applied, version } = await this.#erased.write(async (session) => {
      const sourceRows = (await session.query(sourceSql)).rows;
      const keys = sourceRows.map((row) =>
        storedSqlValueFromExecution(
          keyColumn,
          evaluateJoinedRowExpression(sourceKey, { [statement.source.alias]: row }),
        ),
      );
      const present = new Map<string, DatabaseRow>();
      const wanted = keys.filter((key): key is QueryValue => key !== null);
      if (wanted.length > 0) {
        const existing = await session.query(
          `SELECT * FROM ${quoteSqlIdentifier(target.name)} WHERE ${quoteSqlIdentifier(keyColumn.name)} IN (${wanted
            .map(() => "?")
            .join(", ")})`,
          { params: wanted },
        );
        for (const row of existing.rows) {
          const key = storedSqlValueFromExecution(keyColumn, row[keyColumn.name] ?? null);
          if (key !== null) present.set(keyToken(keyColumn.type, key), row);
        }
      }
      const { updates, deletes, inserts } = classifyMergeRows({
        statement,
        target,
        keyColumn,
        sourceRows,
        keys,
        present,
      });
      // Applied in one order per kind, so a row can only be touched by the branch that claimed
      // it: updates, then deletes, then the fresh rows.
      let changedRows = 0;
      const assignedColumns = [
        ...new Set([...updates.values()].flatMap((entry) => Object.keys(entry.changes))),
      ];
      if (updates.size > 0) {
        const entries = [...updates.values()];
        const changes: Record<string, BatchValue[]> = {};
        for (const column of assignedColumns) {
          changes[column] = entries.map((entry) => entry.changes[column] ?? null);
        }
        const result = await session.updateBatch(target.name, {
          keys: entries.map((entry) => entry.key),
          changes,
        });
        changedRows += result.rowCount;
      }
      if (deletes.size > 0) {
        const result = await session.deleteBatch(target.name, {
          keys: [...deletes.values()] as Array<Exclude<BatchValue, null>>,
        });
        changedRows += result.rowCount;
      }
      if (inserts.length > 0) {
        // Keep absent properties absent: omission invokes a catalog default while explicit NULL
        // must remain SQL NULL. Pivoting every target column here used to collapse that boundary.
        const result = await session.insertBatch(target.name, inserts);
        changedRows += result.rowCount;
      }
      return changedRows;
    });
    return {
      kind: "merge",
      table: target.name,
      rowCount: applied,
      ...(version === null ? {} : { version }),
    };
  }

  async #materializeInsertSelect(
    statement: Extract<CompiledStatement, { kind: "insert" }>,
    writer?: StatementWriter,
  ): Promise<Extract<CompiledStatement, { kind: "insert" }>> {
    if (statement.query === undefined) return statement;
    const target = await this.#findTable(statement.table);
    const plan = await this.#applyCatalogRewrites(statement.query);
    let result: QueryResult;
    if (writer === undefined) {
      const prepared = await this.#prepareCompiledPlan(plan);
      try {
        result = prepared.execute();
      } finally {
        prepared.close();
      }
    } else {
      result = await writer.queryPlan(plan);
    }
    const insertColumns =
      statement.columns.length > 0
        ? statement.columns
        : visibleTableColumns(target).map(({ name }) => name);
    if (result.columns.length !== insertColumns.length) {
      throw new TypeError(
        statement.columns.length > 0
          ? "INSERT ... SELECT must produce exactly the insert column count"
          : "INSERT ... SELECT must produce exactly the table column count",
      );
    }
    const { query, ...rest } = statement;
    void query;
    const targetColumns = insertColumns.map((name) =>
      target.columns.find((column) => column.name === name),
    );
    return {
      ...rest,
      columns: insertColumns,
      rows: result.rows.map((row) =>
        result.columns.map((column, position) =>
          storedSqlValueFromExecution(targetColumns[position], row[column] ?? null),
        ),
      ),
    };
  }

  /**
   * Executes an already-compiled statement — the typed mutation builders call this directly with
   * the same statement structures SQL parses into, sharing every validation and conflict rule.
   * With `returning`, the affected rows project back: inserts echo the written values, deletes
   * return the rows as read at the statement's snapshot, and updates return post-update values
   * (the snapshot row with assignments applied — the exact values the mutation wrote).
   */
  async runStatement(
    statement: CompiledStatement,
    options: RunStatementOptions = {},
  ): Promise<ExecuteResult> {
    const statementNow = this.#now();
    statement = resolveMutationStatementDatetimes(statement, statementNow);
    if (statement.kind === "select") {
      return { kind: "rows", result: await this.query(statement.sql) };
    }
    if (statement.kind === "set") {
      return { kind: "set", action: statement.action, name: statement.name };
    }
    if (statement.kind === "show") {
      // The settings a driver or tool reads on connection, with the engine's fixed answers.
      const settings: Record<string, string> = {
        search_path: "public",
        server_version: "16.0",
        server_version_num: "160000",
        timezone: "UTC",
        time_zone: "UTC",
        transaction_isolation: "repeatable read",
        default_transaction_isolation: "repeatable read",
        client_encoding: "UTF8",
        server_encoding: "UTF8",
        standard_conforming_strings: "on",
        integer_datetimes: "on",
        datestyle: "ISO, MDY",
        intervalstyle: "postgres",
        application_name: "",
        is_superuser: "on",
        max_identifier_length: "63",
      };
      const name = statement.name.toLowerCase();
      const value = settings[name];
      if (value === undefined) {
        throw new TypeError(`unrecognized configuration parameter "${statement.name}"`);
      }
      return {
        kind: "rows",
        result: await this.query(`SELECT $1 AS ${quoteIdentifier(name)}`, { params: [value] }),
      };
    }
    if (statement.kind === "create-enum") {
      const values = validateEnumValues(statement.values, statement.name);
      const storageName = `${ENUM_TYPE_PREFIX}${statement.name}`;
      if (await this.store.getTableByName(storageName)) {
        throw new TypeError(`Type already exists: ${statement.name}`);
      }
      await this.store.addTable({
        id: this.#createId(),
        name: storageName,
        columns: [
          {
            id: this.#createId(),
            name: "value",
            type: "string",
            nullable: false,
            hidden: true,
          },
        ],
        managed: false,
        revision: 0,
        enumType: { name: statement.name, values },
        createdAt: dateIsoString(this.#now()),
      });
      this.#planCache.clear();
      return { kind: "create-type", name: statement.name };
    }
    if (statement.kind === "create-sequence") {
      const storageName = `${SEQUENCE_PREFIX}${statement.name}`;
      if (await this.store.getTableByName(storageName)) {
        throw new TypeError(`Sequence already exists: ${statement.name}`);
      }
      const columnId = this.#createId();
      await this.store.addTable({
        id: this.#createId(),
        name: storageName,
        columns: [
          {
            id: columnId,
            name: "value",
            type: "number",
            integer: true,
            nullable: false,
            hidden: true,
            defaultValue: { kind: "autoincrement" },
          },
        ],
        managed: false,
        revision: 0,
        sequence: { name: statement.name, start: 1, columnId },
        createdAt: dateIsoString(this.#now()),
      });
      return { kind: "create-sequence", name: statement.name };
    }
    if (statement.kind === "create-table") {
      if (statement.ifNotExists === true) {
        const existing = await this.store.getTableByName(statement.table);
        if (existing !== undefined) return { kind: "create-table", table: statement.table };
      }
      try {
        await this.createTable({
          name: statement.table,
          columns: statement.columns,
          ...(statement.checks === undefined ? {} : { checks: statement.checks }),
          ...(statement.foreignKeys === undefined ? {} : { foreignKeys: statement.foreignKeys }),
          ...(statement.uniqueKey === undefined ? {} : { uniqueKey: statement.uniqueKey }),
          ...(statement.compositePrimaryKey === undefined
            ? {}
            : { compositePrimaryKey: statement.compositePrimaryKey }),
          ...(statement.uniqueConstraints === undefined
            ? {}
            : { uniqueConstraints: statement.uniqueConstraints }),
          ...(statement.managed === undefined ? {} : { managed: statement.managed }),
        });
      } catch (error) {
        // The optimistic existence read is not the admission point. When another engine wins
        // after it, IF NOT EXISTS converges on that durable object instead of leaking the
        // adapter's duplicate-name error.
        if (
          statement.ifNotExists !== true ||
          (await this.store.getTableByName(statement.table)) === undefined
        ) {
          throw error;
        }
      }
      return { kind: "create-table", table: statement.table };
    }
    if (statement.kind === "create-table-as") {
      // T172: the catalog record is transaction-owned and invisible while its blocks and
      // segments stage. The commit publishes the table, its row-id counter, and its first
      // manifest together, so a crash/fault exposes either the complete result or no table.
      for (let attempt = 0; ; attempt += 1) {
        const before = await this.store.getCatalogProbe();
        const existing = await this.store.getTableByName(statement.table);
        if (existing !== undefined) {
          if (statement.ifNotExists === true) {
            return { kind: "create-table", table: statement.table };
          }
          throw new TypeError(`Table already exists: ${statement.table}`);
        }
        const records = await this.store.listTables();
        const after = await this.store.getCatalogProbe();
        if (after.catalogEpoch !== before.catalogEpoch) {
          if (attempt >= this.#maxCommitRetries) {
            throw new TableRecordConflictError(statement.table, 0, null);
          }
          continue;
        }
        const schemas = new Map(
          records.map((record) => [
            record.name,
            record.columns.map(({ name, type, integer, sqlDomain }) => ({
              name,
              type,
              ...(integer === true ? { integer: true as const } : {}),
              ...(sqlDomain === undefined ? {} : { sqlDomain }),
            })),
          ]),
        );
        const plan = await this.#applyCatalogRewrites(statement.query, before);
        const tableColumns: TableColumnRecord[] = inferBlockSchema(plan, schemas).map(
          ({ name, type, integer, sqlDomain }) => ({
            id: this.#createId(),
            name: validateName(name, "Column"),
            type,
            ...(integer === true ? { integer: true as const } : {}),
            ...(sqlDomain === undefined ? {} : { sqlDomain: structuredClone(sqlDomain) }),
            nullable: true,
          }),
        );
        const pendingTable: TableRecord = {
          id: this.#createId(),
          name: validateName(statement.table, "Table"),
          columns: tableColumns,
          revision: 0,
          managed: false,
          createdAt: dateIsoString(this.#now()),
        };
        const transaction = await this.#transactions.beginWithPendingTable(
          pendingTable,
          before.catalogEpoch,
        );
        try {
          const executionMemoryBudgetBytes = Math.min(
            this.#queryExecutionMemoryBudgetBytes,
            DEFAULT_QUERY_MEMORY_BUDGET_BYTES,
          );
          const stageBatchRows = 16_384;
          let nextRowId = 1n;
          let stagedRows = 0;
          transaction.limitLevelZeroSegments(pendingTable.id, MAX_LEVEL_ZERO_SEGMENTS);
          const stageRows = async (rows: readonly QueryRow[]): Promise<void> => {
            if (rows.length === 0) return;
            const batchResult = {
              columns: tableColumns.map(({ name }) => name),
              columnDomains: tableColumns.map(({ sqlDomain }) => sqlDomain ?? null),
              rows: [...rows],
            };
            if (queryResultRetainedBytes(batchResult) > executionMemoryBudgetBytes) {
              throw new QueryMemoryBudgetError(
                "CREATE TABLE AS result batch",
                queryResultRetainedBytes(batchResult),
                0,
                executionMemoryBudgetBytes,
              );
            }
            const batch: ColumnarBatch = {
              columns: Object.fromEntries(
                tableColumns.map((column) => [
                  column.name,
                  rows.map((row) => storedSqlValueFromExecution(column, row[column.name] ?? null)),
                ]),
              ),
              rowCount: rows.length,
            };
            normalizeDomainBatch(pendingTable, batch);
            validateBatch(pendingTable, batch);
            const endExclusive = nextRowId + BigInt(rows.length);
            await this.#stageInsertSegment(
              transaction,
              pendingTable,
              batch,
              rows.length,
              "insert",
              { start: nextRowId, endExclusive },
            );
            nextRowId = endExclusive;
            stagedRows += rows.length;
          };
          const queryOptions: QueryOptions = {
            ...(transaction.snapshotVersion === null
              ? {}
              : { version: transaction.snapshotVersion }),
            executionMemoryBudgetBytes,
            spillToStorage: true,
            memoize: false,
          };
          let streamed: QueryResult | undefined;
          if (
            !compiledPlanIsGrouped(plan) &&
            plan.orderBy.length === 0 &&
            plan.joins.length === 0 &&
            this.#canStreamPlanShape(plan, queryOptions)
          ) {
            streamed = await this.#queryStreamed(plan, queryOptions, undefined, undefined, {
              batchRows: stageBatchRows,
              signal: new AbortController().signal,
              consume: async (batch) => stageRows(batch.rows),
            });
          }
          if (streamed === undefined) {
            if (stagedRows !== 0) {
              throw new Error("CREATE TABLE AS streaming stopped after staging rows");
            }
            // Blocking shapes use the ordinary spillable executor under a CTAS-specific hard
            // ceiling even when the database was configured with an unbounded query budget.
            // The retained-result check is a second guard before the first durable artifact.
            const result = await this.#sessionQueryPlan(transaction, plan, queryOptions);
            const retainedBytes = queryResultRetainedBytes(result);
            if (retainedBytes > executionMemoryBudgetBytes) {
              throw new QueryMemoryBudgetError(
                "CREATE TABLE AS result",
                retainedBytes,
                0,
                executionMemoryBudgetBytes,
              );
            }
            for (let start = 0; start < result.rows.length; start += stageBatchRows) {
              await stageRows(result.rows.slice(start, start + stageBatchRows));
            }
          }
          transaction.markTableChanged(pendingTable.id);
          const manifest = await transaction.commit();
          this.#afterCommit(manifest);
          return { kind: "create-table", table: statement.table };
        } catch (error) {
          await transaction.abort().catch(() => undefined);
          if (
            (error instanceof WriteConflictError ||
              error instanceof SchemaConflictError ||
              error instanceof TableRecordConflictError) &&
            attempt < this.#maxCommitRetries
          ) {
            continue;
          }
          throw error;
        }
      }
    }
    if (statement.kind === "create-index") {
      const indexStatement = statement;
      const existing = (await this.store.listTables()).some((table) =>
        Object.values(table.secondaryIndexes ?? {}).some(
          (index) => index.name === indexStatement.index,
        ),
      );
      if (existing && statement.ifNotExists === true) {
        return {
          kind: "create-index",
          index: statement.index,
          table: statement.table,
          column: statement.columns[0]?.name ?? "",
          columns: statement.columns.map((column) => column.name),
          unique: statement.unique === true,
        };
      }
      try {
        await this.createIndex(statement.index, statement.table, statement.columns, {
          unique: statement.unique === true,
        });
      } catch (error) {
        const admitted =
          statement.ifNotExists === true &&
          (await this.store.listTables()).some((table) =>
            Object.values(table.secondaryIndexes ?? {}).some(
              (index) => index.name === indexStatement.index,
            ),
          );
        if (!admitted) throw error;
      }
      return {
        kind: "create-index",
        index: statement.index,
        table: statement.table,
        column: statement.columns[0]?.name ?? "",
        columns: statement.columns.map((column) => column.name),
        unique: statement.unique === true,
      };
    }
    if (statement.kind === "drop-index") {
      const dropped = await this.dropIndex(statement.index, {
        ...(statement.ifExists === true ? { ifExists: true } : {}),
      });
      return { kind: "drop-index", index: statement.index, dropped };
    }
    if (statement.kind === "add-column") {
      // F031-04. Existing rows have no value for the new column, so it is always nullable;
      // a DEFAULT fills the rows written afterwards.
      let pinnedTableId: string | undefined;
      const addColumnStatement = statement;
      for (let attempt = 0; ; attempt += 1) {
        const proof = await this.#stableCatalogProof();
        try {
          let added = addColumnStatement.column;
          if (added.sqlDomain?.kind === "enum" && added.sqlDomain.values.length === 0) {
            const enumName = added.sqlDomain.name;
            const enumRecord = proof.records.find(
              (record) => record.name === `${ENUM_TYPE_PREFIX}${enumName}`,
            );
            if (enumRecord?.enumType === undefined) {
              throw new TypeError(`Unsupported column type: ${enumName}`);
            }
            added = {
              ...added,
              sqlDomain: {
                kind: "enum",
                name: enumRecord.enumType.name,
                values: [...enumRecord.enumType.values],
              },
            };
          }
          const record = proof.records.find(
            (candidate) => candidate.name === addColumnStatement.table,
          );
          if (record === undefined) throw new UnknownTableError(addColumnStatement.table);
          if (record.view !== undefined)
            throw new TypeError(`${addColumnStatement.table} is a view, not a table`);
          pinnedTableId ??= record.id;
          if (record.id !== pinnedTableId) {
            throw new TableRecordConflictError(pinnedTableId, 0, record.revision);
          }
          if (
            added.nullable !== true &&
            !(
              addColumnStatement.allowNonNullableWithBackfill === true &&
              added.backfill !== undefined
            )
          ) {
            throw new TypeError(
              "ALTER TABLE ADD COLUMN adds a nullable column; existing rows have no value for it",
            );
          }
          if (record.columns.some(({ name }) => name === added.name)) {
            throw new TypeError(`Column already exists: ${addColumnStatement.table}.${added.name}`);
          }
          if (added.generatedValue !== undefined) {
            throw new TypeError(
              "ALTER TABLE cannot add a generated column without rewriting existing rows",
            );
          }
          if (added.defaultValue !== undefined) {
            validateColumnDefault(
              {
                name: added.name,
                type: added.type,
                ...(added.integer === true ? { integer: true as const } : {}),
                ...(added.sqlDomain === undefined ? {} : { sqlDomain: added.sqlDomain }),
                nullable: added.nullable ?? false,
                isUniqueKey: false,
                ...(added.enumValues === undefined ? {} : { enumValues: added.enumValues }),
              },
              added.defaultValue,
            );
            if (added.defaultValue.kind === "literal" && added.sqlDomain !== undefined) {
              normalizeSqlDomainValue(added.sqlDomain, added.defaultValue.value);
            }
            if (added.defaultValue.kind === "expression") {
              validateDefaultExpression(added.defaultValue.sql, {
                name: `${addColumnStatement.table}.${added.name}`,
                type: added.type,
                ...(added.sqlDomain === undefined ? {} : { sqlDomain: added.sqlDomain }),
              });
            }
          }
          const columns = [
            ...structuredClone(record.columns),
            {
              id: this.#createId(),
              name: added.name,
              type: added.type,
              ...(added.integer === true ? { integer: true as const } : {}),
              ...(added.sqlDomain === undefined
                ? {}
                : { sqlDomain: structuredClone(added.sqlDomain) }),
              nullable: added.nullable ?? false,
              ...(added.defaultValue === undefined ? {} : { defaultValue: added.defaultValue }),
              ...(added.enumValues === undefined ? {} : { enumValues: [...added.enumValues] }),
              ...(added.backfill === undefined
                ? {}
                : { backfill: normalizedColumnBackfill(added, added.backfill) }),
            },
          ];
          assertTriggerBodiesAcceptTableSchema(proof.records, record, columns);
          const candidateSchemas = catalogQuerySchemas(proof.records);
          candidateSchemas.set(record.name, columns);
          assertDependentViewsKeepSchema(proof.records, record, candidateSchemas);
          await this.store.updateTable(record.id, record.revision, {
            columns,
            expectedCatalogEpoch: proof.catalogEpoch,
          });
          return { kind: "add-column", table: addColumnStatement.table, column: added.name };
        } catch (error) {
          if (!(error instanceof TableRecordConflictError) || attempt >= this.#maxCommitRetries) {
            throw error;
          }
        }
      }
    }
    if (statement.kind === "drop-column") {
      const dropped = await this.dropColumn(statement.table, statement.column, {
        ...(statement.ifExists === true ? { ifExists: true } : {}),
      });
      return {
        kind: "drop-column",
        table: statement.table,
        column: statement.column,
        dropped,
      };
    }
    if (statement.kind === "merge") return this.#runMerge(statement);
    if (statement.kind === "create-view") {
      await this.createView(statement.view, statement.sql, {
        ...(statement.orReplace === true ? { orReplace: true } : {}),
        ...(statement.managed === true ? { managed: true } : {}),
      });
      return { kind: "create-view", view: statement.view };
    }
    if (statement.kind === "drop-view") {
      const dropped = await this.dropView(statement.view, {
        ...(statement.ifExists === true ? { ifExists: true } : {}),
      });
      return { kind: "drop-view", view: statement.view, dropped };
    }
    if (statement.kind === "drop-table") {
      const dropped = await this.dropTable(statement.table, {
        ...(statement.ifExists === true ? { ifExists: true } : {}),
      });
      return { kind: "drop-table", table: statement.table, dropped };
    }
    if (statement.kind === "create-trigger") {
      await this.#createTrigger(statement.table, statement.trigger);
      return { kind: "create-trigger", table: statement.table, name: statement.trigger.name };
    }
    if (statement.kind === "drop-trigger") {
      await this.#dropTrigger(statement.name);
      return { kind: "drop-trigger", name: statement.name };
    }
    if (statement.kind === "transaction") {
      return this.#runTransactionStatement(statement.action, statement.name);
    }
    if (statement.kind === "insert") {
      statement = await this.#materializeInsertExpressions(statement, statementNow);
    }
    if (options.writer === undefined) {
      // Selection, assignment evaluation, constraint proofs, trigger derivation, and the write
      // itself are one statement transaction. A genuine concurrent data commit does not rebase
      // stale derived values: it aborts this scope, then the loop restarts the whole statement
      // against a fresh snapshot. Maintenance-only commits are handled inside #openWriteScope.
      for (let attempt = 0; ; attempt += 1) {
        try {
          const completed = await this.#openWriteScope(
            (_session, _transaction, writer) =>
              this.runStatement(statement, { ...options, writer }),
            // A standalone statement has no user-controlled idle gap. Its selection reads hold
            // their own lease and a data conflict restarts the complete statement, so retain the
            // atomic one-write fast path; public write() scopes keep the durable pin by default.
            { durableSnapshot: false },
          );
          const result = completed.result;
          if (result.kind !== "insert" && result.kind !== "update" && result.kind !== "delete") {
            throw new Error(`Mutation statement returned an unexpected result: ${result.kind}`);
          }
          return result.rowCount === 0 || completed.version === null
            ? result
            : { ...result, version: completed.version };
        } catch (error) {
          if (
            (!(error instanceof WriteConflictError) && !(error instanceof SchemaConflictError)) ||
            attempt >= this.#maxCommitRetries
          ) {
            throw error;
          }
        }
      }
    }
    if (statement.kind === "insert" && statement.query !== undefined) {
      statement = await this.#materializeInsertSelect(statement, options.writer);
    }
    if (statement.kind === "insert" && statement.columns.length === 0) {
      const table = await this.#findTable(statement.table);
      const columns = visibleTableColumns(table).map((column) => column.name);
      if (statement.defaultValues === true) {
        // Keep the empty column list: omission, not NULL, is what invokes catalog defaults.
      } else if (statement.rows.some((row) => row.length !== columns.length)) {
        throw new TypeError("Each INSERT row must match the table column count");
      } else {
        statement = { ...statement, columns };
      }
    }
    if (statement.kind === "insert") {
      statement = await this.#materializeInsertExpressions(statement, statementNow);
    }
    // A RETURNING clause parsed from SQL text applies unless the caller overrides it. Expression
    // items read every column of the affected rows here; execute() projects them afterwards.
    if (statement.returning !== undefined && options.returning === undefined) {
      options = { ...options, returning: statement.returning };
    } else if (statement.returningItems !== undefined && options.returning === undefined) {
      options = { ...options, returning: "*" };
    }
    if (statement.kind === "insert" && statement.onConflict?.action === "nothing") {
      statement = await this.#filterConflictingInsertRows(statement, options.writer);
    }
    if (statement.kind === "insert" && statement.onConflict?.action === "update") {
      return this.#mergeConflictingInsertRows(statement, options);
    }
    if (statement.kind === "insert" && statement.rows.length === 0) {
      const table = await this.#findTable(statement.table);
      const returningColumns =
        options.returning === undefined
          ? undefined
          : options.returning === "*"
            ? visibleTableColumns(table).map(({ name }) => name)
            : [...options.returning];
      return {
        kind: "insert",
        table: statement.table,
        rowCount: 0,
        ...(returningColumns === undefined
          ? {}
          : returningExecuteFields(table, returningColumns, [])),
      };
    }
    if (statement.kind === "insert") {
      const table = await this.#findTable(statement.table);
      const viaUpsert = statement.onConflict?.action === "replace";
      if (viaUpsert) {
        const keyColumn = getUniqueKeyColumn(table);
        const conflictColumns =
          statement.onConflict?.columns ??
          (statement.onConflict === undefined ? [] : [statement.onConflict.column]);
        const addressColumns =
          keyColumn?.hidden === true
            ? primaryKeyColumns(table).map(({ name }) => name)
            : keyColumn === undefined
              ? []
              : [keyColumn.name];
        if (
          keyColumn === undefined ||
          conflictColumns.length !== addressColumns.length ||
          conflictColumns.some((name, index) => name !== addressColumns[index])
        ) {
          throw new TypeError(
            `ON CONFLICT targets the table's primary or unique key columns: ${addressColumns.join(", ") || "(none)"}`,
          );
        }
      }
      // Narrowing does not survive a reassignment inside the closures below, so the folded
      // spelling lives beside the statement rather than replacing it.
      const spelledColumns = foldInsertColumns(table, statement).columns;
      for (const name of spelledColumns) {
        if (!table.columns.some((column) => column.name === name)) {
          throw new TypeError(`INSERT column does not exist: ${name}`);
        }
      }
      const input = insertStatementBatch({ ...statement, columns: spelledColumns });
      // Normalize before dispatch as well as inside the write path so RETURNING echoes the exact
      // stored/public domain value rather than the caller's unnormalized spelling.
      coerceSqlWriteBatch(table, input);
      normalizeDomainBatch(table, input);
      let returningColumns: readonly string[] | undefined;
      if (options.returning !== undefined) {
        returningColumns =
          options.returning === "*"
            ? visibleTableColumns(table).map((column) => column.name)
            : options.returning;
        // RETURNING is statement validation, not result decoration. Reject it before the first
        // byte or key-membership delta is staged so an invalid projection can never commit data.
        for (const name of returningColumns) {
          if (!table.columns.some((column) => column.name === name)) {
            throw new TypeError(`RETURNING column does not exist: ${name}`);
          }
        }
      }
      const writer = options.writer;
      const stagedKeyColumn = writer === undefined ? undefined : getUniqueKeyColumn(table);
      if (writer !== undefined && !viaUpsert && stagedKeyColumn !== undefined) {
        // Statement validity first, so an invalid projection reports as itself, not as a
        // duplicate the invalid statement would also have hit.
        const assignedGenerated = table.columns.find(
          (column) => column.generatedValue !== undefined && spelledColumns.includes(column.name),
        );
        if (assignedGenerated !== undefined) {
          throw new TypeError(`Generated column cannot be assigned: ${assignedGenerated.name}`);
        }
        // Inside BEGIN ... COMMIT a duplicate key must fail the INSERT itself, as it does in
        // PostgreSQL, not surface at COMMIT after the application has moved on. The scope's
        // read sees committed rows plus everything it staged, so one keyed lookup settles it;
        // commit still re-validates as the last word.
        await this.#assertStagedInsertKeysFree(table, stagedKeyColumn, input, writer);
      }
      // A scope stages and reports rows; a standalone write also publishes a version and any
      // values the engine generated. Both shapes answer here, and the narrow one has less to
      // report rather than something different.
      const result: StagedWriteResult & {
        version?: number;
        generatedColumns?: Record<string, BatchValue[]>;
      } = await (viaUpsert
        ? (writer?.upsertBatch(statement.table, input) ??
          this.#erased.upsertBatch(statement.table, input))
        : (writer?.insertBatch(statement.table, input) ??
          this.#erased.insertBatch(statement.table, input)));
      const generated = "generatedColumns" in result ? (result.generatedColumns ?? {}) : {};
      return {
        kind: "insert",
        table: statement.table,
        rowCount: result.rowCount,
        // A staged write has no version yet: the scope it belongs to has not published.
        ...(result.version === undefined ? {} : { version: result.version }),
        ...(returningColumns === undefined
          ? {}
          : {
              ...returningExecuteFields(
                table,
                returningColumns,
                statement.rows.map((row, rowIndex) =>
                  Object.fromEntries(
                    returningColumns.map((name) => {
                      const column = table.columns.find((candidate) => candidate.name === name);
                      const position = spelledColumns.indexOf(name);
                      const inserted = position < 0 ? undefined : row[position];
                      const value =
                        generated[name]?.[rowIndex] ??
                        input.columns[name]?.[rowIndex] ??
                        (inserted === undefined || isDefaultInsertValue(inserted)
                          ? null
                          : boundInsertValue(inserted));
                      return [name, executionSqlValueFromInput(column, value)];
                    }),
                  ),
                ),
              ),
            }),
      };
    }
    const table = await this.#findTable(statement.table);
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) {
      throw new TypeError(
        `${statement.kind === "update" ? "UPDATE" : "DELETE"} requires a table with a unique key: ${statement.table}`,
      );
    }
    const returningColumns =
      options.returning === undefined
        ? undefined
        : options.returning === "*"
          ? visibleTableColumns(table).map(({ name }) => name)
          : [...options.returning];
    const updateAssignments =
      statement.kind !== "update"
        ? []
        : await (async () => {
            const spelled = foldAssignmentColumns(table, statement.assignments);
            if (!table.columns.some((column) => column.sqlDomain !== undefined)) {
              return spelled;
            }
            const { domains } = await this.#catalogFacts();
            if (!domains.has(table.name)) return statement.assignments;
            const normalized = normalizePlanDomainLiterals(
              {
                sql: `UPDATE ${table.name}`,
                base: { table: table.name, alias: table.name },
                joins: [],
                select: spelled.map((assignment) => ({
                  expression: assignment.expression,
                  alias: assignment.column,
                })),
                predicates: [],
                groupBy: [],
                having: [],
                orderBy: [],
              },
              domains,
            );
            return spelled.map((assignment, index) => ({
              ...assignment,
              expression: normalized.select[index]?.expression ?? assignment.expression,
            }));
          })();
    const referenced = new Set([keyColumn.name, ...(returningColumns ?? [])]);
    // Each assignment rides the read as a hidden select item, so a scalar subquery in SET —
    // correlated or not — resolves through the ordinary query pipeline (decorrelation, one
    // snapshot for the uncorrelated) instead of a per-row evaluator that cannot run one.
    const assignmentAlias = (column: string): string => `\u0000set:${column}`;
    // UPDATE … FROM / DELETE … USING: the extra sources join the target as a cross product that
    // the WHERE filters, as PostgreSQL plans them; the target's own columns are then read
    // qualified, since a source may share a column name.
    const targetAlias = statement.alias ?? table.name;
    const from = statement.from;
    const plan = optimizePlan({
      sql: `(${statement.kind})`,
      base: { table: table.name, alias: targetAlias },
      joins: from === undefined ? [] : [crossJoinPlan(from.base), ...from.joins],
      select: [
        ...[...referenced].map((name) => ({
          expression: {
            kind: "column" as const,
            reference: from === undefined ? name : `${targetAlias}.${name}`,
          },
          alias: name,
        })),
        ...(statement.kind === "update"
          ? updateAssignments.map((assignment) => ({
              expression: assignment.expression,
              alias: assignmentAlias(assignment.column),
            }))
          : []),
      ],
      predicates:
        from === undefined ? statement.predicates : [...statement.predicates, ...from.predicates],
      groupBy: [],
      having: [],
      orderBy: [],
    });
    if (statement.kind === "delete" && returningColumns === undefined && from === undefined) {
      const internalWriter = options.writer as StatementWriter &
        Partial<Pick<TransactionStatementWriter, "queryFirstColumn">>;
      if (internalWriter.queryFirstColumn !== undefined) {
        const selectedKeys = await internalWriter.queryFirstColumn(plan);
        if (selectedKeys !== undefined) {
          const keys = selectedKeys as BatchValue[];
          if (keyColumn.type === "string" && keyColumn.sqlDomain === undefined) {
            for (let index = 0; index < keys.length; index += 1) {
              keys[index] = storedSqlValueFromExecution(keyColumn, keys[index] ?? null);
            }
          }
          if (keys.some((key) => key === null)) {
            throw new TypeError(`Unique key values must not be null: ${keyColumn.name}`);
          }
          if (keys.length === 0) {
            return { kind: "delete", table: table.name, rowCount: 0 };
          }
          const deleted = await internalWriter.deleteBatch(table.name, { keys });
          return {
            kind: "delete",
            table: table.name,
            rowCount: deleted.rowCount,
          };
        }
      }
    }
    let rows: QueryResult["rows"];
    if (options.writer !== undefined) {
      // Inside a scope the rows to touch are the ones the scope can see, which includes what it
      // has already staged — an UPDATE after an INSERT in the same transaction finds that row.
      rows = (await options.writer.queryPlan(plan)).rows;
    } else {
      // The same streaming-first pipeline a SELECT takes: its zone pruning and ascending-range
      // narrowing find the rows to touch, where the prepared path materialized the table's
      // columns first — most of a bulk delete's cost, at 200k rows.
      rows = (await this.#queryCompiled(plan)).rows;
    }
    if (from !== undefined) {
      // A target row matched by several source rows is touched once, from its first match —
      // PostgreSQL's rule for UPDATE … FROM, where the join may fan out.
      const seen = new Set<string>();
      rows = rows.filter((row) => {
        const key = JSON.stringify(row[keyColumn.name] ?? null);
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });
    }
    const keys =
      keyColumn.type === "string" && keyColumn.sqlDomain === undefined
        ? rows.map((row) => storedSqlValueFromExecution(keyColumn, row[keyColumn.name] ?? null))
        : rows.map((row) => row[keyColumn.name] ?? null);
    if (keys.some((key) => key === null)) {
      throw new TypeError(`Unique key values must not be null: ${keyColumn.name}`);
    }
    if (statement.kind === "delete") {
      const returnedRows =
        returningColumns === undefined
          ? undefined
          : rows.map((row) =>
              Object.fromEntries(returningColumns.map((name) => [name, row[name] ?? null])),
            );
      if (keys.length === 0) {
        return {
          kind: "delete",
          table: table.name,
          rowCount: 0,
          ...(returnedRows === undefined || returningColumns === undefined
            ? {}
            : returningExecuteFields(table, returningColumns, returnedRows)),
        };
      }
      const deleted: { deletedRowCount?: number; rowCount?: number; version?: number | null } =
        options.writer === undefined
          ? await this.#erased.deleteBatch(table.name, { keys })
          : await options.writer.deleteBatch(table.name, { keys });
      return {
        kind: "delete",
        table: table.name,
        rowCount: deleted.deletedRowCount ?? deleted.rowCount ?? 0,
        ...(deleted.version === undefined || deleted.version === null
          ? {}
          : { version: deleted.version }),
        ...(returnedRows === undefined || returningColumns === undefined
          ? {}
          : returningExecuteFields(table, returningColumns, returnedRows)),
      };
    }
    if (keys.length === 0) {
      return {
        kind: "update",
        table: table.name,
        rowCount: 0,
        ...(returningColumns === undefined
          ? {}
          : returningExecuteFields(table, returningColumns, [])),
      };
    }
    const changes: Record<string, Array<BatchValue | null>> = {};
    const returnedChanges: Record<string, Array<BatchValue | null>> | undefined =
      returningColumns === undefined ? undefined : {};
    for (const assignment of updateAssignments) {
      const column = table.columns.find((candidate) => candidate.name === assignment.column);
      if (column === undefined) throw new TypeError(`Unknown column: ${assignment.column}`);
      const executionValues = returnedChanges === undefined ? undefined : ([] as BatchValue[]);
      changes[assignment.column] = rows.map((row) => {
        const value = row[assignmentAlias(assignment.column)] ?? null;
        if (typeof value === "number" && !Number.isFinite(value)) {
          throw new TypeError(
            `UPDATE assignment produced a non-finite number: ${assignment.column}`,
          );
        }
        // The stored form: a plain-TEXT value unprotected, an untyped string constant read in
        // the column's type. RETURNING echoes the same form, as PostgreSQL returns the typed value.
        const stored = storedSqlValueFromExecution(column, value);
        executionValues?.push(
          column.type === "string" && column.sqlDomain === undefined ? value : stored,
        );
        return stored;
      });
      if (executionValues !== undefined && returnedChanges !== undefined) {
        returnedChanges[assignment.column] = executionValues;
      }
    }
    const updated: {
      updatedRowCount?: number;
      rowCount?: number;
      version?: number | null;
      generatedColumns?: Record<string, BatchValue[]>;
    } =
      options.writer === undefined
        ? await this.#erased.updateBatch(table.name, { keys, changes })
        : await options.writer.updateBatch(table.name, { keys, changes });
    const returnedRows =
      returningColumns === undefined
        ? undefined
        : rows.map((row, index) =>
            Object.fromEntries(
              returningColumns.map((name) => [
                name,
                returnedChanges !== undefined && name in returnedChanges
                  ? (returnedChanges[name]?.[index] ?? null)
                  : updated.generatedColumns?.[name] !== undefined
                    ? (updated.generatedColumns[name][index] ?? null)
                    : (row[name] ?? null),
              ]),
            ),
          );
    return {
      kind: "update",
      table: table.name,
      rowCount: updated.updatedRowCount ?? updated.rowCount ?? 0,
      ...(updated.version === undefined || updated.version === null
        ? {}
        : { version: updated.version }),
      ...(returnedRows === undefined || returningColumns === undefined
        ? {}
        : returningExecuteFields(table, returningColumns, returnedRows)),
    };
  }

  /**
   * A plan shape can stream its scan input: every asynchronous execution path, including both
   * spill paths, consumes scan rows batch-forward and copies values out, so a sliding resident
   * window can back the scan source while join build sides stay fully materialized. A self-join
   * is excluded because the base table would also be probed as a build side at arbitrary rows.
   * Streaming is the default execution: scan cost stays proportional to blocks actually read
   * through the buffer pool instead of a whole-table materialization per prepared snapshot.
   * The one excluded option combination is an explicit budget with spill disabled, where the
   * materialized path owns the memory-budget error contract.
   */
  #canStreamPlanShape(plan: CompiledQuery, options: QueryOptions): boolean {
    return (
      (options.executionMemoryBudgetBytes === undefined || options.spillToStorage !== false) &&
      // WITH TIES cannot stop at the limit: whether the next row belongs is only known after
      // reading it, so those plans take the materialized path that trims the ordered result.
      plan.limitWithTies !== true &&
      plan.base.table !== DUAL_TABLE &&
      plan.base.derived === undefined &&
      plan.base.union === undefined &&
      plan.base.windowed === undefined &&
      plan.base.recursive === undefined &&
      plan.joins.every((join) => join.derived === undefined && join.recursive === undefined) &&
      !plan.joins.some((join) => join.table === plan.base.table) &&
      !blockHasSubqueries(plan)
    );
  }

  /**
   * Executes a plan with a sliding block-aligned scan window over the base table instead of a
   * fully materialized scan input; join build sides are materialized at the same snapshot.
   * Returns undefined when the base table's visible shape is ineligible (keyed mutation replay),
   * so the caller falls back to the materialized path.
   */
  async #queryStreamed(
    plan: CompiledQuery,
    options: QueryOptions,
    spillPageRows: number | undefined,
    probe?: CatalogProbe,
    cursor?: QueryBatchCursorExecution,
  ): Promise<QueryResult | undefined> {
    options = this.#effectiveQueryOptions(options);
    throwIfAborted(options.signal);
    const tableNames = [plan.base.table, ...plan.joins.map((join) => join.table)];
    const uniqueTableNames = [...new Set(tableNames)];
    if (options.version === undefined) {
      // The common path shares the probe-gated catalog state and the shared reader lease
      // with every other statement at the current version.
      return this.#withSharedCatalogSnapshot(
        uniqueTableNames,
        (snapshot, realTables, visibility) =>
          this.#queryStreamedAtSnapshot(
            plan,
            options,
            spillPageRows,
            snapshot,
            [...realTables.values()],
            visibility,
            cursor,
          ),
        probe,
      );
    }
    // Explicit time travel keeps the per-call lease and version-anchored reads.
    const tables = await Promise.all(uniqueTableNames.map((name) => this.#findTable(name)));
    return this.#withLeasedSnapshot(options.version, async (snapshot) => {
      const tableIds = new Set(tables.map((table) => table.id));
      const segmentRecords = await this.#listSegmentsForTableIds([...tableIds]);
      const transactionRecords = await this.#transactionRecordsForSegments(segmentRecords);
      const segmentsByTable = new Map<string, SegmentRecord[]>();
      for (const segment of segmentRecords) {
        if (!tableIds.has(segment.tableId)) continue;
        const tableSegments = segmentsByTable.get(segment.tableId) ?? [];
        tableSegments.push(segment);
        segmentsByTable.set(segment.tableId, tableSegments);
      }
      const visibility: SegmentVisibilityCatalog = {
        transactions: new Map(transactionRecords.map((record) => [record.id, record] as const)),
        segmentsByTable,
      };
      return this.#queryStreamedAtSnapshot(
        plan,
        options,
        spillPageRows,
        snapshot,
        tables,
        visibility,
        cursor,
      );
    });
  }

  async #queryStreamedAtSnapshot(
    plan: CompiledQuery,
    options: QueryOptions,
    spillPageRows: number | undefined,
    snapshot: LeasedSnapshot,
    tables: readonly TableRecord[],
    visibility: SegmentVisibilityCatalog,
    cursor?: QueryBatchCursorExecution,
  ): Promise<QueryResult | undefined> {
    throwIfAborted(options.signal);
    // Copy-on-write: expansion clones only full-text plans, leaving the compile cache's copy
    // untouched.
    plan = expandFtsColumns(plan, (tableName) =>
      searchableFtsColumns(tables.find((table) => table.name === tableName)),
    );
    const schemas = new Map(
      tables.map((table) => [table.name, table.columns.map(({ name }) => name)]),
    );
    const typedSchemas = new Map<string, SqlColumnSchema[]>(
      tables.map((table) => [
        table.name,
        table.columns.map(({ name, type, integer, sqlDomain }) => ({
          name,
          type,
          ...(integer === true ? { integer: true as const } : {}),
          ...(sqlDomain === undefined ? {} : { sqlDomain }),
        })),
      ]),
    );
    // Streamed plans scan real tables only, so the catalog schemas resolve every AVG argument.
    plan = annotateAvgArgumentScales(plan, typedSchemas);
    const columns = referencedColumns(plan, schemas);
    // Streaming must choose the scan/build orientation before creating its sliding base view.
    // Plain append histories have exact row counts in segment metadata; mutation histories keep
    // their written order because their visible cardinality requires replay to determine.
    const visibleByTable = new Map<string, SegmentRecord[]>();
    const rowCounts = new Map<string, { rowCount: number }>();
    for (const table of tables) {
      throwIfAborted(options.signal);
      const segments = await this.#visibleSegmentRecords(table, snapshot, visibility);
      throwIfAborted(options.signal);
      visibleByTable.set(table.name, segments);
      if (
        segments.every((segment) => {
          const kind = segment.kind;
          return kind === "insert" || kind === "base";
        })
      ) {
        rowCounts.set(table.name, {
          rowCount: segments.reduce((total, segment) => total + segment.rowCount, 0),
        });
      }
    }
    if (rowCounts.size === tables.length) plan = chooseJoinOrder(plan, rowCounts);
    const baseTable = tables.find((table) => table.name === plan.base.table);
    if (baseTable === undefined) throw new UnknownTableError(plan.base.table);
    const requestedBaseColumns = columns.get(baseTable.name) ?? [];
    const projectedBaseColumns =
      requestedBaseColumns.length === 0 ? [] : resolveReadColumns(baseTable, requestedBaseColumns);
    if (secondaryIndexOrderForPlan(plan, baseTable, projectedBaseColumns, false) !== undefined) {
      return undefined;
    }
    {
      // The fts invalidation flip commits atomically with its segments, so a record fetched
      // after the segment reads above cannot claim "ready" for data those segments miss.
      const freshBaseTable = planContainsFts(plan)
        ? ((await this.store.getTable(baseTable.id)) ?? baseTable)
        : baseTable;
      // Scoring needs corpus statistics: streamed windows cannot run the scan-side stats pass,
      // so a BM25 plan streams only when the index serves exact statistics; otherwise fall
      // back to the materialized path.
      const ftsStats = await this.#ftsIndexStats(
        plan,
        new Map(
          tables.map((record) => [
            record.name,
            record.id === freshBaseTable.id ? freshBaseTable : record,
          ]),
        ),
        snapshot,
        visibility,
      );
      throwIfAborted(options.signal);
      if (planContainsFts(plan, "bm25") && ftsStats === undefined) return undefined;
      // The streamed scan honors the same index pruning as the materialized path; a budgeted
      // MATCH query must not silently pay the full scan just because it streams.
      const visibleBaseSegments =
        visibleByTable.get(freshBaseTable.name) ??
        (await this.#visibleSegmentRecords(freshBaseTable, snapshot, visibility));
      this.#maybeScheduleAutoCompaction(freshBaseTable, visibleBaseSegments);
      const ftsSegments = await this.#ftsPrunedSegments(
        freshBaseTable,
        visibleBaseSegments,
        plan,
        snapshot,
      );
      throwIfAborted(options.signal);
      const indexed = await this.#secondaryIndexPrunedSegments(
        freshBaseTable,
        ftsSegments,
        plan,
        snapshot,
      );
      throwIfAborted(options.signal);
      const baseSegments = indexed.segments;
      // Zone-map elimination composes after index pruning: whole row groups whose statistics
      // reject the plan's predicates never stream at all. An exact index row selection is
      // numbered over the pruned blocks, so it is used as is.
      const zonePruned =
        indexed.rows === undefined
          ? await this.#zonePrunedStreamSegments(
              plan,
              freshBaseTable,
              projectedBaseColumns,
              baseSegments,
              snapshot,
            )
          : undefined;
      throwIfAborted(options.signal);
      const baseView = this.#streamedViewFactory(
        baseTable,
        projectedBaseColumns,
        zonePruned?.segments ?? baseSegments,
        snapshot,
        zonePruned?.storedBlocks,
        zonePruned !== undefined || indexed.pruned,
      );
      if (baseView === undefined) return undefined;

      // A single unordered/ungrouped inner equi-join whose build side is too big to materialize
      // executes as a partitioned hash join: each pass keeps one hash partition of the build
      // rows resident and re-streams both inputs, so memory stays bounded by partition size.
      const partitionedShape = partitionedJoinShape(plan);
      if (partitionedShape !== undefined && options.executionMemoryBudgetBytes !== undefined) {
        const buildTable = tables.find((table) => table.name === partitionedShape.buildTableName);
        if (buildTable !== undefined) {
          const requestedBuildColumns = columns.get(buildTable.name) ?? [];
          const projectedBuildColumns =
            requestedBuildColumns.length === 0
              ? []
              : resolveReadColumns(buildTable, requestedBuildColumns);
          if (
            projectedBuildColumns.some((column) => column.name === partitionedShape.buildKeyName)
          ) {
            const buildSegments =
              visibleByTable.get(buildTable.name) ??
              (await this.#visibleSegmentRecords(buildTable, snapshot, visibility));
            const buildView = this.#streamedViewFactory(
              buildTable,
              projectedBuildColumns,
              buildSegments,
              snapshot,
            );
            const budget = options.executionMemoryBudgetBytes;
            const estimate = estimatedColumnarBytes(buildSegments, projectedBuildColumns);
            if (buildView !== undefined && estimate > budget / 4) {
              return this.#runPartitionedJoin(
                plan,
                budget,
                estimate,
                baseView,
                buildView,
                buildTable.name,
                partitionedShape.buildKeyName,
                options.signal,
              );
            }
          }
        }
      }

      const runStreamedExecution = async (attempt: {
        spill: boolean;
      }): Promise<QueryResult | undefined> => {
        throwIfAborted(options.signal);
        const memory = new QueryMemoryContext(options.executionMemoryBudgetBytes);
        let prepared: PreparedQuery | undefined;
        try {
          const streamed = await baseView.create(memory);
          throwIfAborted(options.signal);
          const inputTables = new Map<string, ColumnarTable>([[baseTable.name, streamed.table]]);
          for (const table of tables) {
            throwIfAborted(options.signal);
            if (table.name === baseTable.name) continue;
            const requestedColumns = columns.get(table.name) ?? [];
            inputTables.set(
              table.name,
              await this.#materializeColumnarTableAtSnapshot(
                table,
                snapshot,
                requestedColumns.length === 0 ? [] : resolveReadColumns(table, requestedColumns),
                visibility,
                plan,
              ),
            );
            throwIfAborted(options.signal);
          }
          prepared = createPreparedColumnarQuery(plan, inputTables, memory, {
            ...(ftsStats === undefined ? {} : { ftsStats }),
            outputNeedsExternalization: queryResultNeedsExternalization(plan, typedSchemas),
            outputColumnDomains: inferResultColumnDomains(plan, typedSchemas),
          });
          if (cursor !== undefined) {
            const emission = { happened: false };
            const columns = await prepared.executeBatches(
              {
                batchRows: cursor.batchRows,
                signal: cursor.signal,
                loadScanWindow: streamed.load,
                ...(cursor.consumeFirstColumn === undefined
                  ? {}
                  : {
                      consumeFirstColumn: async (values: readonly QueryValue[]) => {
                        emission.happened = true;
                        await cursor.consumeFirstColumn?.(values);
                      },
                    }),
              },
              async (batch) => {
                emission.happened = true;
                await cursor.consume(externalizeQueryResult(batch));
              },
            );
            if (!emission.happened) {
              await cursor.consume({
                columns: [...columns],
                columnDomains: inferResultColumnDomains(plan, typedSchemas),
                rows: [],
              });
            }
            options.onStats?.({ peakMemoryBytes: memory.usage.peakBytes });
            return {
              columns: [...columns],
              columnDomains: inferResultColumnDomains(plan, typedSchemas),
              rows: [],
            };
          }
          if (!attempt.spill) {
            try {
              const streamedResult = await prepared.executeAsync({
                loadScanWindow: streamed.load,
                ...(indexed.rows === undefined
                  ? {}
                  : { scanRows: streamed.remapScanRows?.(indexed.rows) ?? indexed.rows }),
                ...(options.signal === undefined ? {} : { signal: options.signal }),
              });
              options.onStats?.({ peakMemoryBytes: memory.usage.peakBytes });
              return streamedResult;
            } catch (error) {
              if (error instanceof QueryMemoryBudgetError) return undefined;
              throw error;
            }
          }
          const spilledResult = await prepared.executeAsync({
            ...(spillPageRows === undefined ? {} : { spillPageRows }),
            spillStore: this.#leasedSpillStore(),
            loadScanWindow: streamed.load,
            ...(indexed.rows === undefined
              ? {}
              : { scanRows: streamed.remapScanRows?.(indexed.rows) ?? indexed.rows }),
            ...(options.signal === undefined ? {} : { signal: options.signal }),
          });
          options.onStats?.({ peakMemoryBytes: memory.usage.peakBytes });
          return spilledResult;
        } finally {
          if (prepared === undefined) memory.close();
          else prepared.close();
        }
      };
      // Without a budget or an explicit spill request there is nothing to spill for: the
      // scan streams in windows and retained state grows unbounded exactly like the
      // materialized path would.
      const spill = options.spillToStorage ?? options.executionMemoryBudgetBytes !== undefined;
      if (!spill) return runStreamedExecution({ spill: false });
      // A finite budget permits in-memory execution up to the budget; it does not itself mean
      // that every spill-capable plan should use durable temporary storage. In particular, a
      // full ORDER BY that fits comfortably in the default budget is tens of times faster in
      // the typed radix kernel than after serializing and merging spill pages. Try the bounded
      // in-memory execution first and spill only on a genuine budget overflow. The streamed
      // loader is forward-only, so the fallback rebuilds the stream rather than rewinding it.
      if (options.spillToStorage !== true) {
        const bounded = await runStreamedExecution({ spill: false });
        if (bounded !== undefined) return bounded;
      }
      return runStreamedExecution({ spill: true });
    }
  }

  /**
   * Zone-map row-group pruning for the streamed scan: header-only inspection of the
   * predicate columns' blocks selects the block indexes that can match, and the scan then
   * streams only those row groups — the same elimination the materialized pruned projection
   * performs, paid at scan time instead of cached under a mutable fingerprint. The inspected
   * bytes ride along so surviving predicate blocks decode without a second store fetch.
   * Returns undefined when the shape cannot prune (no zone predicates, a mutation history
   * whose slot arithmetic depends on every row group, scan-derived BM25 statistics, or
   * misaligned per-column block counts); the caller keeps the original segments.
   */
  async #zonePrunedStreamSegments(
    plan: CompiledQuery,
    table: TableRecord,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
  ): Promise<{ segments: SegmentRecord[]; storedBlocks: Map<string, Uint8Array> } | undefined> {
    const mutations = segments.filter(
      (segment) => segment.kind === "delete" || segment.kind === "update",
    );
    const appends = segments.filter((segment) => {
      const kind = segment.kind;
      return kind === "insert" || kind === "base";
    });
    if (appends.length + mutations.length !== segments.length) return undefined;
    const predicates = zonePredicates(plan, table);
    if (predicates.length === 0) return undefined;
    if (planContainsFts(plan, "bm25") && !this.#ftsIndexServesScoring(plan, table, segments)) {
      return undefined;
    }
    const predicateColumns = [
      ...new Map(predicates.map((predicate) => [predicate.column.id, predicate.column])).values(),
    ];
    const keyColumn = getUniqueKeyColumn(table);
    if (mutations.length > 0) {
      // The replay addresses base rows by their slot in the streamed scan, so the key column
      // has to be pruned in lockstep with everything else the scan reads.
      if (keyColumn === undefined) return undefined;
      // An update can move a row's value into a predicate's range, which the base block's zone
      // map cannot know: eliminating that row group would drop a row the update makes match.
      // A delete only ever removes rows, so it composes with elimination unchanged.
      //
      // The key column is the exception, and it is the one that matters most. An update segment
      // always stores it — that is how the replay addresses the rows it patches — but it never
      // *changes* it, because updating a unique key is refused outright (see
      // validateUpdateBatch). Reading its presence as a hazard is what made a single updated row
      // demote every later keyed lookup to a full scan: `WHERE id = ?` has a predicate on the
      // key, every update segment carries the key, so pruning switched off and stayed off until
      // compaction. At 200k rows that is a point lookup at 7.6ms instead of 0.06ms, scaling with
      // the table from there.
      const hazardColumns = predicateColumns.filter((column) => column.id !== keyColumn.id);
      if (
        mutations.some(
          (segment) =>
            segment.kind === "update" &&
            hazardColumns.some((column) => (segment.columnBlockIds[column.id]?.length ?? 0) > 0),
        )
      ) {
        return undefined;
      }
    }
    const involvedColumns = [
      ...new Map(
        [
          ...projectedColumns,
          ...predicateColumns,
          ...(mutations.length > 0 && keyColumn !== undefined ? [keyColumn] : []),
        ].map((column) => [column.id, column]),
      ).values(),
    ];
    if (
      involvedColumns.some((column) =>
        appends.some((segment) => segment.columnBlockIds[column.id] === undefined),
      )
    ) {
      return undefined;
    }
    const storedBlocks = new Map<string, Uint8Array>();
    const descriptions = new Map<string, ReturnType<typeof inspectBlock>>();
    const keyPredicates =
      keyColumn === undefined
        ? []
        : predicates.filter((predicate) => predicate.column.id === keyColumn.id);
    const predicateBlockIds = [
      ...new Set([
        ...appends.flatMap((segment) =>
          predicateColumns.flatMap((column) => segment.columnBlockIds[column.id] ?? []),
        ),
        // A mutation never changes the unique key it carries. Its key block can therefore
        // prove that the whole delta cannot affect a key-range query, before the replay loads
        // any patched columns. The descriptions are header-only and stay in the byte-bounded
        // cache, so a long point-update history costs one new header per commit rather than a
        // replay of every old patch on every following statement.
        ...(keyColumn === undefined || keyPredicates.length === 0
          ? []
          : mutations.flatMap((segment) => segment.columnBlockIds[keyColumn.id] ?? [])),
      ]),
    ];
    // Block descriptions are immutable per id, like decoded blocks, so a repeated pruned
    // query pays zero store reads for elimination once its descriptions are resident.
    const missingIds = predicateBlockIds.filter((id) => {
      const cached = this.#cacheGet(`zi ${id}`) as ReturnType<typeof inspectBlock> | undefined;
      if (cached === undefined) return true;
      descriptions.set(id, cached);
      return false;
    });
    for (let start = 0; start < missingIds.length; start += 16) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const ids = missingIds.slice(start, start + 16);
      const blocks = await this.#getSnapshotBlocksWindowed(snapshot, ids);
      for (let index = 0; index < ids.length; index += 1) {
        const id = ids[index] ?? "";
        const bytes = blocks[index];
        if (bytes === undefined) throw new Error(`Visible block is missing: ${id}`);
        storedBlocks.set(id, bytes);
        // Header and metadata only: zone-map elimination must not pay the decompress,
        // checksum, and payload-validation cost of blocks it is about to discard.
        const description = inspectBlock(bytes);
        descriptions.set(id, description);
        this.#cachePut(`zi ${id}`, description, ZONE_DESCRIPTION_CACHE_BYTES);
      }
    }
    const prunedSegments: SegmentRecord[] = [];
    for (const segment of segments) {
      if (segment.kind === "delete" || segment.kind === "update") {
        const keyBlockIds =
          keyColumn === undefined ? [] : (segment.columnBlockIds[keyColumn.id] ?? []);
        const canAffect =
          keyPredicates.length === 0 ||
          keyBlockIds.length === 0 ||
          keyBlockIds.some((blockId) => {
            const description = descriptions.get(blockId);
            if (description === undefined || description.type !== keyColumn?.type) return true;
            return keyPredicates.every((predicate) => zoneMapCanMatch(description, predicate));
          });
        // Retained deltas keep their original place in the overlay. A delta ruled out by its
        // immutable key cannot alter any row the predicate may return, including a delete.
        if (canAffect) prunedSegments.push(segment);
        continue;
      }
      const firstIds = segment.columnBlockIds[predicateColumns[0]?.id ?? ""] ?? [];
      if (
        involvedColumns.some(
          (column) => (segment.columnBlockIds[column.id]?.length ?? 0) !== firstIds.length,
        )
      ) {
        return undefined;
      }
      const blockIndexes: number[] = [];
      let segmentRows = 0;
      let prunedRows = 0;
      for (let blockIndex = 0; blockIndex < firstIds.length; blockIndex += 1) {
        let rowCount: number | undefined;
        let canMatch = true;
        for (const predicate of predicates) {
          const blockId = segment.columnBlockIds[predicate.column.id]?.[blockIndex] ?? "";
          const description = descriptions.get(blockId);
          if (description === undefined) throw new Error(`Visible block is missing: ${blockId}`);
          if (description.type !== predicate.column.type) {
            throw new Error(`Column type mismatch: ${predicate.column.name}`);
          }
          if (rowCount !== undefined && description.rowCount !== rowCount) return undefined;
          rowCount = description.rowCount;
          if (!zoneMapCanMatch(description, predicate)) canMatch = false;
        }
        if (rowCount === undefined) return undefined;
        segmentRows += rowCount;
        if (canMatch) {
          blockIndexes.push(blockIndex);
          prunedRows += rowCount;
        }
      }
      if (segmentRows !== segment.rowCount) return undefined;
      if (blockIndexes.length === 0) continue;
      prunedSegments.push({
        ...segment,
        rowCount: prunedRows,
        columnBlockIds: Object.fromEntries(
          involvedColumns.map((column) => [
            column.id,
            blockIndexes.map((blockIndex) => segment.columnBlockIds[column.id]?.[blockIndex] ?? ""),
          ]),
        ),
      });
    }
    // Elimination read every predicate block, but only the surviving ones are worth handing
    // to the scan; the rest are dropped here instead of riding along until the query ends.
    const survivingIds = new Set(
      prunedSegments.flatMap((segment) => Object.values(segment.columnBlockIds).flat()),
    );
    for (const id of [...storedBlocks.keys()]) {
      if (!survivingIds.has(id)) storedBlocks.delete(id);
    }
    return { segments: prunedSegments, storedBlocks };
  }

  #streamedViewFactory(
    table: TableRecord,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    storedBlocks?: Map<string, Uint8Array>,
    zonePruned = false,
  ):
    | {
        create: (memory: QueryMemoryContext) => Promise<{
          table: ColumnarTable;
          load: (start: number, length: number) => number | Promise<number>;
          remapScanRows?: (rows: readonly number[]) => number[];
        }>;
      }
    | undefined {
    const scanSegments = segments.filter((segment) => {
      const kind = segment.kind;
      return kind === "insert" || kind === "base";
    });
    const mutationSegments = segments.filter(
      (segment) => segment.kind === "update" || segment.kind === "delete",
    );
    if (scanSegments.length + mutationSegments.length !== segments.length) return undefined;
    const keyColumn = getUniqueKeyColumn(table);
    if (mutationSegments.length > 0) {
      if (keyColumn === undefined) return undefined;
      // The key replay is block-driven over every segment, so the key column must have blocks
      // wherever rows exist; older histories without that shape keep the materialized path.
      const keyBlocksPresent = segments.every(
        (segment) =>
          segment.rowCount === 0 || (segment.columnBlockIds[keyColumn.id]?.length ?? 0) > 0,
      );
      if (!keyBlocksPresent) return undefined;
    }
    // A projected column absent from an older segment reads as NULL through the materialized
    // null-fill; the streaming loader is block-driven, so those plans keep the materialized path.
    const columnsPresent = projectedColumns.every((column) =>
      scanSegments.every((segment) => segment.columnBlockIds[column.id] !== undefined),
    );
    if (!columnsPresent) return undefined;
    const scanRowCount = scanSegments.reduce((total, segment) => total + segment.rowCount, 0);
    return {
      create: async (memory: QueryMemoryContext) =>
        mutationSegments.length > 0 && keyColumn !== undefined
          ? this.#createStreamedMutationTable(
              table,
              keyColumn,
              projectedColumns,
              segments,
              snapshot,
              memory,
              zonePruned,
              storedBlocks,
            )
          : this.#createStreamedTable(
              table,
              projectedColumns,
              scanSegments,
              snapshot,
              scanRowCount,
              memory,
              storedBlocks,
            ),
    };
  }

  /**
   * Executes a single unordered/ungrouped inner equi-join whose build side is too big to
   * materialize under the budget. Grace-style partition-by-rescan: pass i re-streams the build
   * table and keeps resident only rows whose join-key hash falls in partition i (about one
   * P-th of the build, reserved as usual), then runs the unchanged plan against a fresh
   * streamed base scan. Equal keys share a partition, so each inner match occurs in exactly
   * one pass and the union of pass results is the join; build rows with NULL or NaN keys can
   * never match and drop at partition time. Row order across passes is implementation-defined,
   * like any unordered query. The rescans trade time for bounded memory; the decoded-block
   * cache keeps repeat decodes cheap.
   */
  async #runPartitionedJoin(
    plan: CompiledQuery,
    budgetBytes: number,
    estimatedBuildBytes: number,
    baseView: {
      create: (memory: QueryMemoryContext) => Promise<{
        table: ColumnarTable;
        load: (start: number, length: number) => number | Promise<number>;
        remapScanRows?: (rows: readonly number[]) => number[];
      }>;
    },
    buildView: {
      create: (memory: QueryMemoryContext) => Promise<{
        table: ColumnarTable;
        load: (start: number, length: number) => number | Promise<number>;
        remapScanRows?: (rows: readonly number[]) => number[];
      }>;
    },
    buildTableName: string,
    buildKeyName: string,
    signal?: AbortSignal,
  ): Promise<QueryResult> {
    throwIfAborted(signal);
    // One partition should fit in an eighth of the budget: the resident partition briefly
    // exists twice (boxed rows, then their vectors) and shares the budget with both streamed
    // windows and the accumulating result.
    let partitions = 2;
    while (partitions < 64 && estimatedBuildBytes / partitions > budgetBytes / 8) partitions *= 2;
    const { limit, offset, ...strippedPlan } = plan;
    const wantedRows = (offset ?? 0) + (limit ?? Number.POSITIVE_INFINITY);
    const root = new QueryMemoryContext(budgetBytes);
    try {
      const combined: QueryRow[] = [];
      for (let partition = 0; partition < partitions; partition += 1) {
        throwIfAborted(signal);
        if (combined.length >= wantedRows) break;
        const passMemory = root.createChild();
        let prepared: PreparedQuery | undefined;
        try {
          // The boxed rows live only until their vectors are built; a nested context releases
          // them so each partition is charged once while the pass executes.
          const collectMemory = passMemory.createChild();
          const buildScanMemory = collectMemory.createChild();
          const build = await buildView.create(buildScanMemory);
          throwIfAborted(signal);
          let buildRows: DatabaseRow[] = [];
          const buildColumns = [...build.table.columns.entries()];
          // Small steps keep the collection windows a minor budget term next to the resident
          // partition itself. The loader serves up to its current block boundary, so the
          // consumed length clamps to the returned resident end.
          const step = 1_024;
          for (let start = 0; start < build.table.rowCount;) {
            throwIfAborted(signal);
            let length = Math.min(step, build.table.rowCount - start);
            const residentEnd = await build.load(start, length);
            throwIfAborted(signal);
            if (typeof residentEnd === "number" && residentEnd > start) {
              length = Math.min(length, residentEnd - start);
            }
            const keyVector = build.table.columns.get(buildKeyName);
            if (keyVector === undefined) {
              throw new Error(`Join key column is missing: ${buildTableName}.${buildKeyName}`);
            }
            for (let row = start; row < start + length; row += 1) {
              const key = columnVectorValueAt(keyVector, row);
              if (key === null || (typeof key === "number" && Number.isNaN(key))) continue;
              if (joinPartitionOf(key, partitions) !== partition) continue;
              const buildRow: DatabaseRow = {};
              for (const [name, vector] of buildColumns) {
                buildRow[name] = columnVectorValueAt(vector, row);
              }
              collectMemory.tally(
                estimateRowBytes(buildRow) + 2 * QUERY_ROW_OVERHEAD_BYTES,
                "Partitioned join build rows",
              );
              buildRows.push(buildRow);
            }
            start += length;
          }
          buildScanMemory.close();
          if (buildRows.length === 0) {
            collectMemory.close();
            continue;
          }
          const buildInput = columnarTableFromRows(buildTableName, buildRows, undefined, false);
          buildRows = [];
          const streamedBase = await baseView.create(passMemory);
          throwIfAborted(signal);
          const inputTables = new Map<string, ColumnarTable>([
            [buildTableName, buildInput],
            [streamedBase.table.name, streamedBase.table],
          ]);
          prepared = createPreparedColumnarQuery(strippedPlan, inputTables, passMemory);
          collectMemory.close();
          const result = await prepared.executeAsync({
            loadScanWindow: streamedBase.load,
            ...(signal === undefined ? {} : { signal }),
          });
          for (const row of result.rows) {
            if (combined.length >= wantedRows) break;
            root.tally(
              estimateRowBytes(row) + QUERY_ROW_OVERHEAD_BYTES,
              "Partitioned join result rows",
            );
            combined.push(row);
          }
        } finally {
          prepared?.close();
          passMemory.close();
        }
      }
      const startRow = offset ?? 0;
      const rows =
        startRow > 0 || limit !== undefined
          ? combined.slice(startRow, limit === undefined ? undefined : startRow + limit)
          : combined;
      const columns = plan.select.map((item) => item.alias);
      return { columns, columnDomains: unknownColumnDomains(columns), rows };
    } finally {
      root.close();
    }
  }

  /**
   * The vectorized form of one immutable block: validity, typed values, and for strings the
   * per-block dictionary with codes. Cached by block id beside the decoded physical form, so
   * a streamed scan installs whole blocks by reference — zero copies, zero re-decoding, and
   * dictionary objects that stay identical across queries, which keeps per-dictionary
   * expression caches (equality codes, LIKE match sets) hot between statements.
   */
  /**
   * Secondary-index key locators for one block's key column, mapped to the block rows that
   * carry them, pooled by block id. A locator is a hash, so two keys may share one; the scan's
   * own predicate settles such collisions.
   */
  #blockKeyLocators(
    blockId: string,
    vector: ColumnVector,
    type: SimpleDataType,
  ): Map<bigint, number | number[]> {
    const cached = this.#cacheGet(`dkl ${blockId}`) as Map<bigint, number | number[]> | undefined;
    if (cached !== undefined) return cached;
    const locators = new Map<bigint, number | number[]>();
    for (let row = 0; row < vector.length; row += 1) {
      const value = vectorValue(vector, row);
      if (value === null) continue;
      const locator = secondaryKeyLocator(type, value);
      const existing = locators.get(locator);
      if (existing === undefined) locators.set(locator, row);
      else if (typeof existing === "number") locators.set(locator, [existing, row]);
      else existing.push(row);
    }
    // A Map entry for a small bigint and a row number: key, value, hash slot, chain pointer.
    this.#cachePut(`dkl ${blockId}`, locators, 64 + locators.size * 48);
    return locators;
  }

  #blockColumnVector(blockId: string, decoded: DecodedPhysicalBlock): ColumnVector {
    const cached = this.#cacheGet(`dbv ${blockId}`) as ColumnVector | undefined;
    if (cached !== undefined) return cached;
    const column = decoded.column;
    const rows = column.rowCount;
    const validity = new Uint8Array(Math.ceil(rows / 8));
    const values =
      column.type === "boolean"
        ? new Uint8Array(rows)
        : column.type === "number" || column.type === "datetime"
          ? new Float64Array(rows)
          : undefined;
    const codes = column.type === "string" ? new Uint32Array(rows) : undefined;
    codes?.fill(NULL_STRING_VECTOR_CODE);
    const builder = new StringDictionaryBuilder();
    appendPhysicalColumnToVector(column, 0, validity, values, codes, builder);
    const vector = (
      codes !== undefined
        ? { kind: "string", length: rows, validity, codes, dictionary: builder.dictionary }
        : { kind: column.type, length: rows, validity, values }
    ) as ColumnVector;
    this.#cachePut(`dbv ${blockId}`, vector, blockVectorRetainedBytes(vector));
    return vector;
  }

  #createStreamedTable(
    table: TableRecord,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    rowCount: number,
    memory: QueryMemoryContext,
    storedBlocks?: Map<string, Uint8Array>,
  ): { table: ColumnarTable; load: (start: number, length: number) => number | Promise<number> } {
    interface StreamedColumnState {
      column: TableColumnRecord;
      vector: ColumnVector;
      blockIds: readonly string[];
      nextBlockIndex: number;
      nextBlockStartRow: number;
      resident: ResidentStreamBlock[];
      reservations: QueryMemoryReservation[];
    }
    const states: StreamedColumnState[] = projectedColumns.map((column) => ({
      column,
      vector: createStreamedColumnVector(column.type, rowCount),
      blockIds: segments.flatMap((segment) => segment.columnBlockIds[column.id] ?? []),
      nextBlockIndex: 0,
      nextBlockStartRow: 0,
      resident: [],
      reservations: [],
    }));
    // The load contract: make a prefix of [start, start + length) resident and return its
    // exclusive end. Serving less than requested is normal — the window never extends past
    // the current block, so every install is a whole-block reference and a batch straddling
    // a block boundary is the caller's clamp to handle, not a stitched copy to build.
    // Synchronous fast path: when every column's resident window already contains the batch
    // start — every batch but the first per block — the loader answers without a promise, so
    // the scan loop stays allocation-free between slides.
    const load = (start: number, length: number): number | Promise<number> => {
      let syncEnd = rowCount;
      let allResident = states.length > 0;
      for (const state of states) {
        const window = state.vector.window;
        if (window !== undefined && start >= window.start && start < window.start + window.length) {
          syncEnd = Math.min(syncEnd, window.start + window.length);
          continue;
        }
        allResident = false;
        break;
      }
      if (allResident) return syncEnd;
      if (states.length === 0) return rowCount;
      return slide(start, length);
    };
    const slide = async (start: number, length: number): Promise<number> => {
      const end = Math.min(start + length, rowCount);
      let residentEnd = rowCount;
      for (const state of states) {
        const window = state.vector.window;
        if (window !== undefined && start >= window.start && start < window.start + window.length) {
          residentEnd = Math.min(residentEnd, window.start + window.length);
          continue;
        }
        if (window !== undefined && start < window.start) {
          throw new Error(`Streamed scan moved backward: ${table.name}.${state.column.name}`);
        }
        state.resident = state.resident.filter(
          (block) => block.startRow + block.vector.length > start,
        );
        while (state.nextBlockStartRow <= start && state.nextBlockIndex < state.blockIds.length) {
          // Fetch a short run of upcoming blocks in one round trip through the buffer pool.
          // The scan is forward-only over exactly these ids, so a decoded block beyond this
          // window is never wasted: it stays warm for the next load.
          const run = state.blockIds.slice(
            state.nextBlockIndex,
            state.nextBlockIndex + STREAMED_SCAN_LOOKAHEAD_BLOCKS,
          );
          const decodedRun = await this.#decodedBlocksThroughCache(run, snapshot, storedBlocks);
          for (let index = 0; index < decodedRun.length; index += 1) {
            const decoded = decodedRun[index];
            if (decoded === undefined) continue;
            if (decoded.column.type !== state.column.type) {
              throw new Error(`Column type mismatch: ${state.column.name}`);
            }
            state.resident.push({
              vector: plainTextExecutionVector(
                state.column,
                this.#blockColumnVector(run[index] ?? "", decoded),
              ),
              startRow: state.nextBlockStartRow,
            });
            state.nextBlockIndex += 1;
            state.nextBlockStartRow += decoded.column.rowCount;
            if (state.nextBlockStartRow > start) break;
          }
        }
        state.resident = state.resident.filter(
          (block) => block.startRow + block.vector.length > start,
        );
        const first = state.resident[0];
        if (first === undefined || first.startRow > start) {
          throw new Error(`Column row count mismatch: ${state.column.name}`);
        }
        const windowStart = first.startRow;
        const windowRows = state.nextBlockStartRow - windowStart;
        const replacements: QueryMemoryReservation[] = [];
        try {
          installStreamedWindow(
            state.vector,
            state.resident,
            windowStart,
            windowRows,
            memory,
            `Streamed window ${state.column.name}`,
            replacements,
          );
        } catch (error) {
          for (const replacement of replacements) replacement.release();
          throw error;
        }
        for (const previous of state.reservations) previous.release();
        state.reservations = replacements;
        residentEnd = Math.min(residentEnd, windowStart + windowRows);
      }
      if (residentEnd <= start && end > start) {
        throw new Error(`Streamed scan made no progress: ${table.name}`);
      }
      return residentEnd;
    };
    return {
      table: {
        name: table.name,
        rowCount,
        columns: new Map(states.map((state) => [state.column.name, state.vector])),
      },
      load,
    };
  }

  /**
   * Block header/metadata descriptions, cached and fetched in one round trip: no decompress and
   * no payload validation. Descriptions are immutable per block id, so a repeated query pays
   * nothing — including the await, which is why the misses are batched rather than looped.
   */
  async #zoneDescriptions(
    blockIds: readonly string[],
    snapshot: LeasedSnapshot,
  ): Promise<Map<string, ReturnType<typeof inspectBlock>>> {
    const descriptions = new Map<string, ReturnType<typeof inspectBlock>>();
    const missing: string[] = [];
    for (const blockId of blockIds) {
      const cached = this.#cacheGet(`zi ${blockId}`) as ReturnType<typeof inspectBlock> | undefined;
      if (cached === undefined) missing.push(blockId);
      else descriptions.set(blockId, cached);
    }
    for (let start = 0; start < missing.length; start += 16) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const ids = missing.slice(start, start + 16);
      const blocks = await this.#getSnapshotBlocksWindowed(snapshot, ids);
      for (let index = 0; index < ids.length; index += 1) {
        const id = ids[index] ?? "";
        const bytes = blocks[index];
        if (bytes === undefined) throw new Error(`Visible block is missing: ${id}`);
        const description = inspectBlock(bytes);
        descriptions.set(id, description);
        this.#cachePut(`zi ${id}`, description, ZONE_DESCRIPTION_CACHE_BYTES);
      }
    }
    return descriptions;
  }

  /**
   * Builds a streamed view of a keyed table whose visible history contains update and delete
   * segments (no upserts — those interleave new rows into slot order and keep the materialized
   * path). Mutation deltas are the small part of such a history, so they replay into resident
   * state — a dead-row bitmap over the base rows plus per-slot column patches referencing the
   * resident update vectors — while the base rows stream through the block-aligned inner
   * window. The outer view compacts dead rows and overlays patches per window, producing
   * exactly the materialized replay's rows in exactly its order.
   *
   * The replay is a pure function of the visible segment set, so it is built once per commit
   * and shared by every query until the next one (`#streamedOverlayState`). The outer loader
   * serves whole inner windows: one whose rows nothing touched is installed by reference, the
   * difference between a copy per window and none; one with a dead or patched row is compacted
   * once, in runs rather than cells.
   *
   * The replay tracks only mutation-touched keys, so its memory is bounded by the mutation
   * size, not the table; the duplicate-key corruption guard consequently only fires for
   * touched keys on this path.
   */
  async #createStreamedMutationTable(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    projectedColumns: readonly TableColumnRecord[],
    baseSegments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    memory: QueryMemoryContext,
    zonePruned = false,
    storedBlocks?: Map<string, Uint8Array>,
  ): Promise<{
    table: ColumnarTable;
    load: (start: number, length: number) => number | Promise<number>;
    remapScanRows?: (rows: readonly number[]) => number[];
  }> {
    const scanSegments = baseSegments.filter((segment) => {
      const kind = segment.kind;
      return kind === "insert" || kind === "base";
    });
    const overlay = await this.#streamedOverlayState(
      table,
      keyColumn,
      baseSegments,
      scanSegments,
      snapshot,
      memory,
      zonePruned,
    );
    const { baseRows, dead, deadCount, patches, patchedSlots } = overlay;
    const hasPatches = patchedSlots.length > 0;
    const outputRows = baseRows - deadCount;
    const inner = this.#createStreamedTable(
      table,
      projectedColumns,
      scanSegments,
      snapshot,
      baseRows,
      memory,
      storedBlocks,
    );
    // Deltas that touch no row this scan reads — every one of them eliminated with its row
    // group, or aimed at keys this table no longer holds — leave the scan exactly as it was.
    if (deadCount === 0 && !hasPatches) return inner;
    interface OuterColumnState {
      column: TableColumnRecord;
      vector: ColumnVector;
      reservations: QueryMemoryReservation[];
    }
    const states: OuterColumnState[] = projectedColumns.map((column) => ({
      column,
      vector: createStreamedColumnVector(column.type, outputRows),
      reservations: [],
    }));
    // Forward-only cursor: cursorOutput live rows exist strictly before base row cursorBase.
    let cursorOutput = 0;
    let cursorBase = 0;
    const load = async (start: number, length: number): Promise<number> => {
      const end = Math.min(start + length, outputRows);
      // COUNT(*) and friends project nothing: the replay already knows how many rows survive,
      // so there is no window to build and no reason to walk the base rows to build it.
      if (states.length === 0) return end;
      const window = states[0]?.vector.window;
      if (window !== undefined && start >= window.start && start < window.start + window.length) {
        return window.start + window.length;
      }
      if (window !== undefined && start < window.start) {
        throw new Error(`Streamed scan moved backward: ${table.name}`);
      }
      // The cursor stops at the end of the window it last served, which can sit past a start
      // that falls before it. Rewinding costs one pass over the dead-row bitmap.
      if (cursorOutput > start) {
        cursorOutput = 0;
        cursorBase = 0;
      }
      while (cursorOutput < start && cursorBase < baseRows) {
        if (!bitmapHasValue(dead, cursorBase)) cursorOutput += 1;
        cursorBase += 1;
      }
      // Skip the dead rows in front of the first live one, so a window never starts dead.
      while (cursorBase < baseRows && bitmapHasValue(dead, cursorBase)) cursorBase += 1;
      if (cursorOutput !== start || cursorBase >= baseRows) {
        throw new Error(`Column row count mismatch: ${table.name}`);
      }
      const baseStart = cursorBase;
      // The inner loader serves whole blocks; the outer window covers the suffix of the inner
      // window from baseStart, however long, and the caller clamps to what it asked for.
      const innerEnd = await inner.load(baseStart, baseRows - baseStart);
      const baseEnd = typeof innerEnd === "number" ? Math.min(innerEnd, baseRows) : baseRows;
      if (baseEnd <= baseStart) throw new Error(`Column row count mismatch: ${table.name}`);
      const deadInWindow = bitmapCountRange(dead, baseStart, baseEnd);
      const patchedInWindow = hasPatches ? sortedCountRange(patchedSlots, baseStart, baseEnd) : 0;
      const liveRows = baseEnd - baseStart - deadInWindow;
      const untouched = deadInWindow === 0 && patchedInWindow === 0;
      const runs = untouched
        ? undefined
        : overlayWindowRuns(dead, patchedSlots, baseStart, baseEnd, patchedInWindow);
      interface OuterTarget {
        state: OuterColumnState;
        fields: MutableStreamedVectorFields;
        replacements: QueryMemoryReservation[];
      }
      const targets: OuterTarget[] = [];
      try {
        for (const state of states) {
          const innerVector = inner.table.columns.get(state.column.name);
          const innerWindow = innerVector?.window;
          if (innerVector === undefined || innerWindow === undefined) {
            throw new Error(`Streamed column is missing: ${state.column.name}`);
          }
          const offset = baseStart - innerWindow.start;
          if (offset < 0 || offset + (baseEnd - baseStart) > innerWindow.length) {
            throw new Error(`Column row count mismatch: ${state.column.name}`);
          }
          const replacements: QueryMemoryReservation[] = [];
          const fields =
            runs === undefined
              ? overlayWindowView(innerVector, offset, liveRows, memory, state.column, replacements)
              : overlayWindowCompacted(
                  innerVector,
                  innerWindow.start,
                  runs,
                  liveRows,
                  hasPatches ? patches : undefined,
                  state.column,
                  memory,
                  replacements,
                );
          fields.window = { start, length: liveRows };
          targets.push({ state, fields, replacements });
        }
        // Every fallible byte is reserved above; the installs below cannot throw, so a budget
        // overflow leaves every state's previous window and reservations intact.
        for (const { state, fields, replacements } of targets) {
          const mutable = state.vector as unknown as MutableStreamedVectorFields;
          mutable.validity = fields.validity;
          if (fields.values !== undefined) mutable.values = fields.values;
          if (fields.codes !== undefined) {
            mutable.codes = fields.codes;
            mutable.dictionary = fields.dictionary ?? [];
          }
          mutable.window = fields.window;
          for (const previous of state.reservations) previous.release();
          state.reservations = replacements;
        }
      } catch (error) {
        for (const entry of targets) {
          for (const replacement of entry.replacements) replacement.release();
        }
        throw error;
      }
      cursorOutput = start + liveRows;
      cursorBase = baseEnd;
      return start + liveRows;
    };
    // Index-selected rows are numbered over the base scan; the replay removes dead rows, so a
    // selected row's output position is its base position less the dead rows before it, and a
    // dead selected row is not visited at all.
    const remapScanRows = (rows: readonly number[]): number[] => {
      const remapped: number[] = [];
      let removedBefore = 0;
      let scanned = 0;
      for (const row of rows) {
        if (row >= baseRows) break;
        for (; scanned < row; scanned += 1) {
          if (((dead[scanned >>> 3] ?? 0) & (1 << (scanned & 7))) !== 0) removedBefore += 1;
        }
        if (((dead[row >>> 3] ?? 0) & (1 << (row & 7))) !== 0) continue;
        remapped.push(row - removedBefore);
      }
      return remapped;
    };
    return {
      table: {
        name: table.name,
        rowCount: outputRows,
        columns: new Map(states.map((state) => [state.column.name, state.vector])),
      },
      load,
      remapScanRows,
    };
  }

  /**
   * The replayed mutation state for one visible segment set: which base rows are dead, and
   * which columns of which slots an update replaced. Cached under the segment ids in the
   * artifact LRU, because nothing about it changes between commits — before this, every query
   * over a table with so much as one deleted row rebuilt it, which made COUNT(*) on such a
   * table cost twenty times what it costs on a clean one. A cache hit is charged to the
   * query's memory as a tally, the same bytes a build reserves.
   */
  async #streamedOverlayState(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    baseSegments: readonly SegmentRecord[],
    scanSegments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    memory: QueryMemoryContext,
    zonePruned: boolean,
  ): Promise<StreamedOverlayState> {
    // A zone-pruned scan keeps a segment's id with a subset of its blocks, and the slots the
    // replay addresses are the key blocks' rows in order — so the key blocks, not the segment
    // ids alone, are what identify the state.
    const key = [
      "overlay",
      table.id,
      zonePruned ? "pruned" : "full",
      baseSegments
        .map((segment) =>
          mutationSegmentKind(segment)
            ? segment.id
            : `${segment.id}:${(segment.columnBlockIds[keyColumn.id] ?? []).join("+")}`,
        )
        .join(","),
    ].join(" ");
    const cached = this.#cacheGet(key) as StreamedOverlayState | undefined;
    if (cached !== undefined) {
      memory.tally(cached.bytes, "Streamed mutation replay");
      return cached;
    }
    const state = await this.#buildStreamedOverlayState(
      table,
      keyColumn,
      baseSegments,
      scanSegments,
      snapshot,
      memory,
      zonePruned,
    );
    this.#cachePut(key, state, state.bytes);
    return state;
  }

  async #buildStreamedOverlayState(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    baseSegments: readonly SegmentRecord[],
    scanSegments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    memory: QueryMemoryContext,
    zonePruned: boolean,
  ): Promise<StreamedOverlayState> {
    // Phase A: each mutation segment's key vector, and every column an update changed —
    // resident and reserved, bounded by the mutation history's size. All of an update's
    // columns, not only the ones this query projects: the state outlives the query. The
    // history's blocks come out of the buffer pool in one round trip, as block vectors: one
    // await per segment is what made a table with a few hundred deltas pay ten milliseconds
    // to rebuild this state after every commit.
    const deltaSegments = baseSegments.filter(mutationSegmentKind);
    const deltaBlockIds = new Set<string>();
    for (const segment of deltaSegments) {
      for (const column of table.columns) {
        for (const blockId of segment.columnBlockIds[column.id] ?? []) deltaBlockIds.add(blockId);
      }
    }
    const decodedDeltaBlocks = new Map<string, DecodedPhysicalBlock>();
    if (deltaBlockIds.size > 0) {
      const ids = [...deltaBlockIds];
      const decoded = await this.#decodedBlocksThroughCache(ids, snapshot);
      ids.forEach((id, index) => {
        const block = decoded[index];
        if (block !== undefined) decodedDeltaBlocks.set(id, block);
      });
    }
    const deltaVector = async (
      column: TableColumnRecord,
      segment: SegmentRecord,
    ): Promise<ColumnVector> => {
      const blockIds = segment.columnBlockIds[column.id] ?? [];
      const blockId = blockIds[0];
      if (blockIds.length !== 1 || blockId === undefined) {
        // A delta written in more than one block — a bulk update past rowsPerBlock — concatenates.
        return this.#materializeAppendColumnVector(column, [segment], snapshot, segment.rowCount);
      }
      const decoded = decodedDeltaBlocks.get(blockId);
      if (decoded === undefined) throw new Error(`Visible block is missing: ${blockId}`);
      if (decoded.column.type !== column.type) {
        throw new Error(`Column type mismatch: ${column.name}`);
      }
      const vector = this.#blockColumnVector(blockId, decoded);
      if (vector.length !== segment.rowCount) {
        throw new Error(`Column row count mismatch: ${column.name}`);
      }
      return vector;
    };
    const mutationKeyVectors = new Map<string, ColumnVector>();
    const mutationChangedVectors = new Map<string, Map<string, ColumnVector>>();
    // Keys as the primitives the vectors already hold. The replay used to build one string
    // token per row on both sides, which made a single deleted row cost an allocation and a
    // hash of every key in the table.
    const touched = new Set<OverlayKey>();
    let retainedBytes = 0;
    for (const segment of deltaSegments) {
      const kind = segment.kind;
      const keyVector = await deltaVector(keyColumn, segment);
      memory.reserve(columnVectorRetainedBytes(keyVector), "Streamed mutation replay");
      mutationKeyVectors.set(segment.id, keyVector);
      const readMutationKey = requiredColumnVectorKeyReader(keyVector);
      for (let row = 0; row < segment.rowCount; row += 1) {
        touched.add(readMutationKey(row));
      }
      if (kind === "update") {
        const changed = new Map<string, ColumnVector>();
        for (const column of table.columns) {
          if (column.id === keyColumn.id) continue;
          if ((segment.columnBlockIds[column.id]?.length ?? 0) === 0) continue;
          const vector = await deltaVector(column, segment);
          const bytes = columnVectorRetainedBytes(vector);
          memory.reserve(bytes, "Streamed mutation replay");
          retainedBytes += bytes;
          changed.set(column.id, plainTextExecutionVector(column, vector));
        }
        mutationChangedVectors.set(segment.id, changed);
      }
    }

    // Phase B: one bounded pass over the scan segments' key blocks — a single block resident
    // at a time — recording, per scan segment, the touched keys and their absolute slots.
    const touchedByScanSegment = new Map<string, Array<{ key: OverlayKey; slot: number }>>();
    // A mutation history is small, and a unique key is usually written in order, so most key
    // blocks cannot hold any touched key at all. Their zone maps say so from the header alone,
    // which is what keeps one deleted row from costing a decode of every key block in the table.
    const touchedPredicate = touchedKeyPredicate(keyColumn, touched);
    const keyDescriptions =
      touchedPredicate === undefined
        ? new Map<string, ReturnType<typeof inspectBlock>>()
        : await this.#zoneDescriptions(
            scanSegments.flatMap((segment) => segment.columnBlockIds[keyColumn.id] ?? []),
            snapshot,
          );
    let baseRows = 0;
    for (const segment of scanSegments) {
      const entries: Array<{ key: OverlayKey; slot: number }> = [];
      touchedByScanSegment.set(segment.id, entries);
      let segmentRows = 0;
      for (const blockId of segment.columnBlockIds[keyColumn.id] ?? []) {
        const description = keyDescriptions.get(blockId);
        if (touchedPredicate !== undefined && description !== undefined) {
          if (description.type !== keyColumn.type) {
            throw new Error(`Column type mismatch: ${keyColumn.name}`);
          }
          if (!zoneMapCanMatch(description, touchedPredicate)) {
            segmentRows += description.rowCount;
            continue;
          }
        }
        const [decoded] = await this.#decodedBlocksThroughCache([blockId], snapshot);
        if (decoded === undefined) throw new Error(`Visible block is missing: ${blockId}`);
        if (decoded.column.type !== keyColumn.type) {
          throw new Error(`Column type mismatch: ${keyColumn.name}`);
        }
        // The block's vector form is what a scan of this table reads anyway, so it comes from
        // (and stays in) the buffer pool rather than being rebuilt for the replay.
        const blockVector = this.#blockColumnVector(blockId, decoded);
        const rows = blockVector.length;
        const readBlockKey = requiredColumnVectorKeyReader(blockVector);
        for (let row = 0; row < rows; row += 1) {
          const key = readBlockKey(row);
          if (touched.has(key)) entries.push({ key, slot: baseRows + segmentRows + row });
        }
        segmentRows += rows;
      }
      if (segmentRows !== segment.rowCount) {
        throw new Error(`Column row count mismatch: ${keyColumn.name}`);
      }
      baseRows += segment.rowCount;
      memory.tally(entries.length * 64, "Streamed mutation replay");
    }

    // Replay in visible segment order, exactly like the materialized path: a delete unmaps the
    // key (a later insert re-adds at a new slot), an update requires a live mapped key and
    // patches per changed column with last-writer-wins.
    const dead = new Uint8Array(Math.ceil(baseRows / 8));
    memory.reserve(dead.byteLength, "Streamed mutation replay");
    const slotByKey = new Map<OverlayKey, number>();
    const patches = new Map<number, Map<string, OverlayPatch>>();
    let deadCount = 0;
    for (const segment of baseSegments) {
      const kind = segment.kind;
      if (kind === "insert" || kind === "base") {
        for (const entry of touchedByScanSegment.get(segment.id) ?? []) {
          if (slotByKey.has(entry.key)) {
            throw new Error(`Stored table contains a duplicate unique key: ${table.name}`);
          }
          slotByKey.set(entry.key, entry.slot);
        }
        continue;
      }
      const keyVector = mutationKeyVectors.get(segment.id);
      if (keyVector === undefined) {
        throw new Error(`Mutation segment key vector is missing: ${segment.id}`);
      }
      const readKey = requiredColumnVectorKeyReader(keyVector);
      if (kind === "delete") {
        for (let row = 0; row < segment.rowCount; row += 1) {
          const key = readKey(row);
          const slot = slotByKey.get(key);
          if (slot !== undefined && !bitmapHasValue(dead, slot)) {
            setBitmapValue(dead, slot);
            deadCount += 1;
            patches.delete(slot);
          }
          slotByKey.delete(key);
        }
        continue;
      }
      const changed = mutationChangedVectors.get(segment.id) ?? new Map<string, ColumnVector>();
      for (let row = 0; row < segment.rowCount; row += 1) {
        const slot = slotByKey.get(readKey(row));
        if (slot === undefined) {
          // Zone-map elimination only drops row groups this plan's predicates reject, and it
          // refuses to run at all when an update touches one of those predicate columns — so
          // an eliminated row's patch cannot change what the query returns.
          if (zonePruned) continue;
          throw new Error(`Update segment references a missing key: ${segment.id}`);
        }
        let slotPatches = patches.get(slot);
        if (slotPatches === undefined) {
          slotPatches = new Map();
          patches.set(slot, slotPatches);
        }
        for (const [columnId, vector] of changed) slotPatches.set(columnId, { vector, row });
      }
    }
    let patchCells = 0;
    for (const slotPatches of patches.values()) patchCells += slotPatches.size;
    memory.tally(patches.size * 96 + patchCells * 48, "Streamed mutation replay");
    const patchedSlots = Uint32Array.from(patches.keys()).sort();
    return {
      baseRows,
      deadCount,
      dead,
      patches,
      patchedSlots,
      bytes:
        dead.byteLength +
        retainedBytes +
        patchedSlots.byteLength +
        patches.size * 96 +
        patchCells * 48,
    };
  }

  /** Prepares one block's inputs and executes it, returning the caller-owned result. */
  async #executeBlock(
    block: CompiledQuery,
    snapshot: LeasedSnapshot,
    visibility: SegmentVisibilityCatalog,
    memory: QueryMemoryContext,
    realTables: ReadonlyMap<string, TableRecord>,
    typedSchemas: Map<string, SqlColumnSchema[]>,
    extraInputs?: ReadonlyMap<string, ColumnarTable>,
    cacheResults = true,
    allowSpill = true,
    forceSpill = false,
    spillPageRows?: number,
    signal?: AbortSignal,
  ): Promise<QueryResult> {
    throwIfAborted(signal);
    const ftsStats = await this.#ftsIndexStats(block, realTables, snapshot, visibility);
    throwIfAborted(signal);
    const inputs = await this.#prepareBlockInputs(
      block,
      snapshot,
      visibility,
      memory,
      realTables,
      typedSchemas,
      extraInputs,
      cacheResults,
      allowSpill,
      forceSpill,
      spillPageRows,
      signal,
    );
    throwIfAborted(signal);
    // After input preparation, because executing this block's nested sources registered their
    // synthetic schemas in typedSchemas, which is what resolves a derived column's domain.
    block = annotateAvgArgumentScales(block, typedSchemas);
    const prepared = createPreparedColumnarQuery(
      block,
      inputs,
      memory.createChild(),
      ftsStats === undefined ? {} : { ftsStats },
    );
    // The columnar preparation only knows vector kinds, so a plain domain column projects with a
    // null domain. Catalog-backed inference fills those in — at miss time, because executing the
    // block registered its nested synthetic sources in typedSchemas — so a substituted scalar or
    // IN subquery literal carries its domain to the outer result (T694).
    const withCatalogColumnDomains = (result: QueryResult): QueryResult => {
      if (!result.columnDomains.includes(null)) return result;
      try {
        const inferred = inferResultColumnDomains(block, typedSchemas);
        result.columnDomains = result.columnDomains.map(
          (domain, index) => domain ?? inferred[index] ?? null,
        );
      } catch {
        // A shape this schema registry cannot type keeps its expression-level domains.
      }
      return result;
    };
    try {
      if (!allowSpill || memory.usage.budgetBytes === Number.MAX_SAFE_INTEGER) {
        const result = prepared.execute();
        throwIfAborted(signal);
        return withCatalogColumnDomains(result);
      }
      if (!forceSpill) {
        try {
          const result = prepared.execute();
          throwIfAborted(signal);
          return withCatalogColumnDomains(result);
        } catch (error) {
          if (!(error instanceof QueryMemoryBudgetError)) throw error;
        }
      }
      return withCatalogColumnDomains(
        await prepared.executeAsync({
          spillStore: this.#leasedSpillStore(),
          ...(spillPageRows === undefined ? {} : { spillPageRows }),
          ...(signal === undefined ? {} : { signal }),
        }),
      );
    } finally {
      prepared.close();
    }
  }

  /**
   * Executes a real-table-rooted block through the prepare cache: the result of a
   * derived table, union member, windowed inner block, recursive base, or scalar/IN
   * subquery is a pure function of its compiled plan and the visible segment ids of the
   * real tables it references, so an identical block over identical table states reuses
   * the previous result instead of re-reading and re-executing.
   */
  async #executeBlockCached(
    block: CompiledQuery,
    snapshot: LeasedSnapshot,
    visibility: SegmentVisibilityCatalog,
    memory: QueryMemoryContext,
    realTables: ReadonlyMap<string, TableRecord>,
    typedSchemas: Map<string, SqlColumnSchema[]>,
    cacheResults = true,
    allowSpill = true,
    forceSpill = false,
    spillPageRows?: number,
    signal?: AbortSignal,
  ): Promise<QueryResult> {
    throwIfAborted(signal);
    const key = await this.#blockResultCacheKey(
      block,
      snapshot,
      visibility,
      realTables,
      cacheResults,
    );
    throwIfAborted(signal);
    if (key !== undefined) {
      const cached = this.#cacheGet(key) as QueryResult | undefined;
      if (cached !== undefined) return cached;
    }
    const result = await this.#executeBlock(
      block,
      snapshot,
      visibility,
      memory,
      realTables,
      typedSchemas,
      undefined,
      cacheResults,
      allowSpill,
      forceSpill,
      spillPageRows,
      signal,
    );
    throwIfAborted(signal);
    if (key !== undefined) this.#cachePut(key, result, queryResultRetainedBytes(result));
    return result;
  }

  /**
   * Like #executeBlockCached, but also carries the block's inferred output schema. The
   * schema must be captured at miss time: executing the block registers its nested
   * synthetic sources in typedSchemas, and a later cache hit skips that registration, so
   * re-inferring the schema at hit time would find those names missing.
   */
  async #executeBlockWithSchemaCached(
    block: CompiledQuery,
    snapshot: LeasedSnapshot,
    visibility: SegmentVisibilityCatalog,
    memory: QueryMemoryContext,
    realTables: ReadonlyMap<string, TableRecord>,
    typedSchemas: Map<string, SqlColumnSchema[]>,
    cacheResults = true,
    allowSpill = true,
    forceSpill = false,
    spillPageRows?: number,
    signal?: AbortSignal,
  ): Promise<{ result: QueryResult; schema: SqlColumnSchema[] }> {
    throwIfAborted(signal);
    const key = await this.#blockResultCacheKey(
      block,
      snapshot,
      visibility,
      realTables,
      cacheResults,
    );
    throwIfAborted(signal);
    const schemaKey = key === undefined ? undefined : `s${key}`;
    if (schemaKey !== undefined) {
      const cached = this.#cacheGet(schemaKey) as
        { result: QueryResult; schema: SqlColumnSchema[] } | undefined;
      if (cached !== undefined) return cached;
    }
    const result = await this.#executeBlock(
      block,
      snapshot,
      visibility,
      memory,
      realTables,
      typedSchemas,
      undefined,
      cacheResults,
      allowSpill,
      forceSpill,
      spillPageRows,
      signal,
    );
    throwIfAborted(signal);
    const schema = inferBlockSchema(block, typedSchemas);
    const entry = { result, schema };
    if (schemaKey !== undefined) {
      this.#cachePut(schemaKey, entry, queryResultRetainedBytes(result) + 64);
    }
    return entry;
  }

  async #blockResultCacheKey(
    block: CompiledQuery,
    snapshot: LeasedSnapshot,
    visibility: SegmentVisibilityCatalog,
    realTables: ReadonlyMap<string, TableRecord>,
    cacheResults = true,
  ): Promise<string | undefined> {
    // Every computed-result cache — whole-block results, their schemas, and the columnar
    // forms of derived and windowed sources — is keyed from here, and each one skips both
    // its read and its write when the key is undefined. Returning undefined is therefore
    // the single switch that makes a statement compute its results instead of reusing them.
    if (!cacheResults) return undefined;
    if (!this.#artifactCache.enabled) return undefined;
    // A block whose value is not a function of the data — RANDOM(), a sequence call, an
    // unresolved clock — must run every time; the version key cannot tell its answers apart.
    if (blockCallsFunctions(block, nonDeterministicFunctionNames)) return undefined;
    // Staged writes can change repeatedly without changing either the pinned manifest version or
    // their transaction id. Do not cache them under an identity that could become stale.
    if (visibility.overlayTransactionId !== undefined) return undefined;
    const parts: string[] = [];
    for (const name of collectRealTableNames(block).sort()) {
      const table = realTables.get(name);
      if (table === undefined) return undefined;
      // A manifest version is an exact immutable database identity. It deliberately invalidates
      // a table result after an unrelated-table commit: that small hit-rate cost keeps key work
      // and retained characters independent of the table's segment count.
      parts.push(`${table.id}=${String(snapshot.version ?? -1)}`);
    }
    try {
      return `blk\u0000${parts.join(";")}\u0000${JSON.stringify(block)}`;
    } catch {
      return undefined;
    }
  }

  /**
   * Inspects exactly one bounded physical segment-ID window at a stable manifest version.
   * Historical records that are not visible are filtered rather than replaced from later
   * windows, so callers must follow `nextCursor` even when a page returns no records.
   */
  async listVisibleSegmentPage(
    tableName: string,
    options: VisibleSegmentPageOptions = {},
  ): Promise<VisibleSegmentPage> {
    const normalizedTableName = validateName(tableName, "Table");
    const limit = positiveWholeNumber(
      options.limit ?? MAX_VISIBLE_SEGMENT_PAGE_ITEMS,
      "Visible segment page limit",
    );
    if (limit > MAX_VISIBLE_SEGMENT_PAGE_ITEMS) {
      throw new RangeError(
        `Visible segment page limit cannot exceed ${String(MAX_VISIBLE_SEGMENT_PAGE_ITEMS)}`,
      );
    }

    const rawCursor: unknown = options.cursor;
    if (rawCursor !== undefined && (typeof rawCursor !== "object" || rawCursor === null)) {
      throw new TypeError("A visible segment cursor must be an object");
    }
    const cursor = rawCursor as VisibleSegmentPageCursor | undefined;
    if (cursor !== undefined && options.version !== undefined) {
      throw new TypeError("A visible segment cursor cannot be combined with a version");
    }
    let tableId: string;
    let version: number | null | undefined;
    let afterId: string | null;
    if (cursor === undefined) {
      tableId = (await this.#findTable(normalizedTableName)).id;
      version = visibleSegmentManifestVersion(options.version, "Visible segment version");
      afterId = null;
    } else {
      if (cursor.tableName !== normalizedTableName) {
        throw new TypeError("A visible segment cursor belongs to a different table name");
      }
      tableId = validateStorageId(cursor.tableId, "Visible segment cursor table ID");
      version = visibleSegmentManifestVersion(cursor.version, "Visible segment cursor version");
      if (version === undefined) throw new TypeError("A visible segment cursor needs a version");
      afterId = validateStorageId(cursor.afterId, "Visible segment cursor ID");
    }

    return this.#withLeasedSnapshot(version, async (snapshot) => {
      await this.#assertVisibleSegmentCursorTable(normalizedTableName, tableId);
      const page = await this.store.listTableSegmentPage(tableId, afterId, limit);
      // A drop can interleave with the async physical read and remove the old table's segment
      // metadata. Check again so that race fails closed instead of returning a truncated page.
      await this.#assertVisibleSegmentCursorTable(normalizedTableName, tableId);
      const transactions = new Map(
        (await this.#transactionRecordsForSegments(page.records)).map((record) => [
          record.id,
          record,
        ]),
      );
      const versionEligible = page.records.filter((segment) => {
        const committedVersion = transactions.get(segment.transactionId)?.committedVersion;
        return (
          snapshot.version !== null &&
          committedVersion !== null &&
          committedVersion !== undefined &&
          committedVersion <= snapshot.version
        );
      });
      const visible = await filterSnapshotSegments(snapshot, versionEligible);
      return {
        records: visible.map((segment) => ({
          id: segment.id,
          rowCount: segment.rowCount,
          columnBlockIds: structuredClone(segment.columnBlockIds),
          logicalOrder: segment.logicalOrder,
          committedVersion: transactions.get(segment.transactionId)?.committedVersion ?? -1,
          commitOrdinal: segment.commitOrdinal,
        })),
        version: snapshot.version,
        nextCursor:
          page.nextCursor === null
            ? null
            : {
                tableName: normalizedTableName,
                tableId,
                version: snapshot.version,
                afterId: page.nextCursor,
              },
      };
    });
  }

  /**
   * Collects the pull-driven framed snapshot stream into one portable byte array. This helper is
   * convenient for small and medium databases, but it necessarily retains the complete file and
   * has the Uint8Array 4-GiB ceiling. Use `exportSnapshotStream()` for larger databases or direct
   * file/network transfer. See the snapshots guide for framing and durability guarantees.
   */
  async exportSnapshot(options: SnapshotExportOptions = {}): Promise<Uint8Array> {
    const chunks: Uint8Array[] = [];
    let byteLength = 0;
    for await (const chunk of this.exportSnapshotStream(options)) {
      byteLength = safeWholeNumberSum([byteLength, chunk.byteLength], "Snapshot byte-array length");
      if (byteLength > MAX_SNAPSHOT_BYTE_ARRAY_LENGTH) {
        throw new RangeError("Snapshot exceeds the byte-array API's 4 GiB limit");
      }
      chunks.push(chunk);
    }
    const bytes = new Uint8Array(byteLength);
    let offset = 0;
    for (const chunk of chunks) {
      bytes.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return bytes;
  }

  /**
   * Streams one pinned committed snapshot with at most one payload block resident. Stopping the
   * iterator releases its durable backup lease in `finally`.
   */
  async *exportSnapshotStream(
    options: SnapshotExportOptions = {},
  ): AsyncGenerator<Uint8Array, void, void> {
    const store = streamingSnapshotExportStore(this.store);
    throwIfSnapshotAborted(options.signal);
    options.onProgress?.({ phase: "reading", transferredBytes: 0, totalBytes: 0 });
    const ownerId = `snapshot-export/${crypto.randomUUID()}`;
    const initialTimes = snapshotSessionTimes(this.#now());
    const session = await store.beginSnapshotFrameExport({ ownerId, ...initialTimes });
    let succeeded = false;
    let transferredBytes = 0;
    let checksum = 0;
    let frameCount = 0;
    let itemCount = 0;
    let storedBytes = 0;
    try {
      const header = session.header;
      const observed = Object.fromEntries(
        SNAPSHOT_FRAME_KINDS.map((kind) => [kind, { frameCount: 0, itemCount: 0, storedBytes: 0 }]),
      ) as Record<
        (typeof SNAPSHOT_FRAME_KINDS)[number],
        { frameCount: number; itemCount: number; storedBytes: number }
      >;
      const encodedHeader = encodeSnapshotFrameStreamHeader(header);
      const expectedFrames = Object.values(header.kinds).reduce(
        (total, kind) => safeWholeNumberSum([total, kind.frameCount], "Snapshot frame count"),
        0,
      );
      const transfer = async function* (bytes: Uint8Array): AsyncGenerator<Uint8Array> {
        for (let offset = 0; offset < bytes.byteLength; offset += SNAPSHOT_TRANSFER_CHUNK_BYTES) {
          yield bytes.subarray(offset, offset + SNAPSHOT_TRANSFER_CHUNK_BYTES);
        }
      };
      for await (const chunk of transfer(encodedHeader)) {
        throwIfSnapshotAborted(options.signal);
        yield chunk;
        transferredBytes += chunk.byteLength;
        options.onProgress?.({ phase: "transfer", transferredBytes, totalBytes: 0 });
      }
      for (let sequence = 0; sequence < expectedFrames; sequence += 1) {
        throwIfSnapshotAborted(options.signal);
        const times = snapshotSessionTimes(this.#now());
        const frame = await store.readSnapshotExportFrame({
          sessionId: session.sessionId,
          ownerId,
          sequence,
          expiresAtCutoff: times.createdAt,
          expiresAt: times.expiresAt,
        });
        throwIfSnapshotAborted(options.signal);
        if (frame?.sequence !== sequence) {
          throw new Error(`Snapshot export omitted frame ${String(sequence)}`);
        }
        const parts = snapshotFrameEnvelopeParts(frame);
        checksum = extendSnapshotFrameStreamChecksum(checksum, parts);
        frameCount = safeWholeNumberSum([frameCount, 1], "Snapshot frame count");
        itemCount = safeWholeNumberSum([itemCount, frame.itemCount], "Snapshot frame item count");
        storedBytes = safeWholeNumberSum(
          [storedBytes, frame.payload.byteLength],
          "Snapshot frame stored bytes",
        );
        const kindObserved = observed[frame.kind];
        kindObserved.frameCount = safeWholeNumberSum(
          [kindObserved.frameCount, 1],
          "Snapshot kind frame count",
        );
        kindObserved.itemCount = safeWholeNumberSum(
          [kindObserved.itemCount, frame.itemCount],
          "Snapshot kind item count",
        );
        kindObserved.storedBytes = safeWholeNumberSum(
          [kindObserved.storedBytes, frame.payload.byteLength],
          "Snapshot kind stored bytes",
        );
        const expected = header.kinds[frame.kind];
        if (
          kindObserved.frameCount > expected.frameCount ||
          kindObserved.itemCount > expected.itemCount ||
          kindObserved.storedBytes > expected.storedBytes
        ) {
          throw new Error(`Snapshot export exceeded its ${frame.kind} summary`);
        }
        for (const part of parts) {
          for await (const chunk of transfer(part)) {
            throwIfSnapshotAborted(options.signal);
            yield chunk;
            transferredBytes = safeWholeNumberSum(
              [transferredBytes, chunk.byteLength],
              "Snapshot transferred bytes",
            );
            options.onProgress?.({ phase: "transfer", transferredBytes, totalBytes: 0 });
          }
        }
      }
      for (const kind of SNAPSHOT_FRAME_KINDS) {
        const actual = observed[kind];
        const expected = header.kinds[kind];
        if (
          actual.frameCount !== expected.frameCount ||
          actual.itemCount !== expected.itemCount ||
          actual.storedBytes !== expected.storedBytes
        ) {
          throw new Error(`Snapshot export did not satisfy its ${kind} summary`);
        }
      }
      const footer: SnapshotFrameFooter = { frameCount, itemCount, storedBytes, checksum };
      for await (const chunk of transfer(encodeSnapshotFrameStreamFooter(footer))) {
        throwIfSnapshotAborted(options.signal);
        yield chunk;
        transferredBytes = safeWholeNumberSum(
          [transferredBytes, chunk.byteLength],
          "Snapshot transferred bytes",
        );
        options.onProgress?.({ phase: "transfer", transferredBytes, totalBytes: 0 });
      }
      succeeded = true;
    } finally {
      await store.closeSnapshotFrameExport({ sessionId: session.sessionId, ownerId });
      if (succeeded) {
        options.onProgress?.({
          phase: "done",
          transferredBytes,
          totalBytes: transferredBytes,
        });
      }
    }
  }

  /**
   * Loads a snapshot file into this database's store, which must be empty. Every block is
   * integrity-checked while decoding, so a corrupt file fails here rather than mid-query, and a
   * store that already holds a database throws rather than merging two histories.
   */
  async importSnapshot(bytes: Uint8Array, options: SnapshotImportOptions = {}): Promise<void> {
    await this.importSnapshotStream(singleSnapshotChunk(bytes), options);
  }

  /** Incrementally validates and stages a snapshot; only the final adapter CAS makes it visible. */
  async importSnapshotStream(
    source: AsyncIterable<Uint8Array>,
    options: SnapshotImportOptions = {},
  ): Promise<void> {
    const store = streamingSnapshotImportStore(this.store);
    const ownerId = `snapshot-import/${crypto.randomUUID()}`;
    let identity: string | undefined;
    let acquired = false;
    let totalBytes = 0;
    let writtenBytes = 0;
    let batchBytes = 0;
    let metadataBatchBytes = 0;
    let batchBlockCount = 0;
    const batch: SnapshotFrame[] = [];
    const flush = async (): Promise<void> => {
      if (batch.length === 0 || identity === undefined) return;
      throwIfSnapshotAborted(options.signal);
      const times = snapshotSessionTimes(this.#now());
      const session = await store.appendSnapshotImportFrames({
        identity,
        ownerId,
        expiresAtCutoff: times.createdAt,
        expiresAt: times.expiresAt,
        frames: batch.splice(0),
      });
      batchBytes = 0;
      metadataBatchBytes = 0;
      batchBlockCount = 0;
      writtenBytes = session.stagedBytes;
      options.onProgress?.({ phase: "blocks", writtenBytes, totalBytes });
    };
    try {
      throwIfSnapshotAborted(options.signal);
      for await (const entry of decodeSnapshotFrameStream(
        abortableSnapshotSource(source, options.signal),
      )) {
        throwIfSnapshotAborted(options.signal);
        if (entry.type === "header") {
          if (identity !== undefined) throw new Error("Snapshot stream repeats its header");
          identity = snapshotFrameStreamHeaderIdentity(entry.header);
          totalBytes = Object.values(entry.header.kinds).reduce(
            (total, kind) =>
              safeWholeNumberSum([total, kind.storedBytes], "Snapshot streamed payload length"),
            0,
          );
          const times = snapshotSessionTimes(this.#now());
          await store.beginSnapshotFrameImport({
            identity,
            ownerId,
            ...times,
            header: entry.header,
          });
          acquired = true;
          options.onProgress?.({ phase: "blocks", writtenBytes: 0, totalBytes });
          continue;
        }
        if (entry.type === "frame") {
          if (identity === undefined) throw new Error("Snapshot frame precedes its header");
          if (
            batch.length > 0 &&
            (batch.length >= MAX_SNAPSHOT_FRAME_BATCH_ITEMS ||
              batchBytes + entry.frame.payload.byteLength > MAX_SNAPSHOT_FRAME_BATCH_BYTES ||
              (entry.frame.kind === "block" && batchBlockCount > 0) ||
              (entry.frame.kind !== "block" &&
                metadataBatchBytes + entry.frame.payload.byteLength >
                  MAX_SNAPSHOT_METADATA_BATCH_BYTES))
          ) {
            await flush();
          }
          batch.push(entry.frame);
          batchBytes = safeWholeNumberSum(
            [batchBytes, entry.frame.payload.byteLength],
            "Snapshot import batch bytes",
          );
          if (entry.frame.kind !== "block") {
            metadataBatchBytes = safeWholeNumberSum(
              [metadataBatchBytes, entry.frame.payload.byteLength],
              "Snapshot import metadata batch bytes",
            );
          } else {
            batchBlockCount += 1;
          }
          continue;
        }
        if (identity === undefined) throw new Error("Snapshot footer precedes its header");
        await flush();
        throwIfSnapshotAborted(options.signal);
        const cutoff = dateIsoString(this.#now());
        options.onProgress?.({ phase: "catalog", writtenBytes, totalBytes });
        await store.finishSnapshotFrameImport({
          identity,
          ownerId,
          expiresAtCutoff: cutoff,
          footer: entry.footer,
        });
        acquired = false;
      }
      if (identity === undefined) throw new Error("Snapshot stream is empty");
      if (acquired) throw new Error("Snapshot stream ended without its footer");
    } catch (error) {
      if (options.signal?.aborted === true && acquired && identity !== undefined) {
        await store.cancelSnapshotFrameImport({ identity, ownerId });
      }
      throw error;
    }
    this.#planCache.clear();
    this.#catalogStateCache.clear();
    this.#catalogStateEpoch = undefined;
    options.onProgress?.({ phase: "done", writtenBytes, totalBytes });
  }

  /** Verifies adapter metadata, or metadata plus every live payload, without changing storage. */
  async checkIntegrity(
    options: {
      mode?: StorageIntegrityMode;
      maxIssues?: number;
    } = {},
  ): Promise<StorageIntegrityReport> {
    const check = this.store.checkIntegrity?.bind(this.store);
    if (check === undefined) throw new Error("This database's block store cannot check integrity");
    return check(options);
  }

  /** Explicit, potentially storage-scanning accounting for live, obsolete, temp, and WAL bytes. */
  async storageStats(): Promise<StorageStats> {
    const inspect = this.store.getStorageStats?.bind(this.store);
    if (inspect === undefined)
      throw new Error("This database's block store cannot report storage stats");
    return inspect();
  }

  async inspectInterruptedImport(): Promise<InterruptedSnapshotImport | null> {
    const inspect = this.store.inspectInterruptedImport?.bind(this.store);
    if (inspect === undefined) return null;
    return inspect();
  }

  async abortInterruptedImport(identity: string): Promise<InterruptedSnapshotImportAbortResult> {
    const abort = this.store.abortInterruptedImport?.bind(this.store);
    if (abort === undefined) {
      throw new Error("This database's block store cannot abort interrupted imports");
    }
    return abort(identity);
  }

  async compactTable(
    tableName: string,
    options: CompactTableOptions = {},
  ): Promise<CompactTableResult> {
    const maxBlocks = boundedMaintenanceBatchItems(
      options.maxBlocksPerStep ?? 16,
      "Compaction blocks per step",
    );
    let progress = await this.compactTableStep(tableName, { ...options, maxBlocks });
    while (progress.result === null) {
      if (progress.jobId === null) throw new Error("Compaction progress lost its job ID");
      progress = await this.resumeCompactionJob(progress.jobId, { maxBlocks });
    }
    return progress.result;
  }

  /** Plans or advances one restart-safe physical compaction job. */
  async compactTableStep(
    tableName: string,
    options: CompactTableStepOptions = {},
  ): Promise<CompactionJobProgress> {
    const maxBlocks = boundedMaintenanceBatchItems(
      options.maxBlocks ?? options.maxBlocksPerStep ?? 1,
      "Compaction step block limit",
    );
    const table = await this.#findTable(tableName);
    return this.#serializedCompactionStep(table.id, async () => {
      const active = await this.#findActiveCompactionJob(table.id);
      let job = active;
      if (job === undefined) {
        const planned = await this.#planCompaction(table, options);
        if ("compacted" in planned) return compactionSkippedProgress(planned);
        job = planned;
      }
      return this.#runCompactionJob(table, job, maxBlocks);
    });
  }

  /** Continues a persisted compaction job after a cooperative yield or restart. */
  async resumeCompactionJob(
    jobId: string,
    options: { maxBlocks?: number } = {},
  ): Promise<CompactionJobProgress> {
    const maxBlocks = boundedMaintenanceBatchItems(
      options.maxBlocks ?? 1,
      "Compaction step block limit",
    );
    const job = await this.store.getCompactionJob(jobId);
    if (job === undefined) throw new Error(`Compaction job not found: ${jobId}`);
    const table = await this.store.getTable(job.tableId);
    if (table === undefined) throw new Error(`Compaction table not found: ${job.tableId}`);
    return this.#serializedCompactionStep(table.id, () =>
      this.#runCompactionJob(table, job, maxBlocks),
    );
  }

  /**
   * One compaction step at a time per table within this database: background compaction
   * drives a job in steps, and a caller stepping the same table explicitly must take turns with
   * it rather than advance the same job concurrently, which would write its output blocks
   * twice. Each step loads the job record fresh, so alternating drivers simply continue where
   * the other left off. Between instances and tabs the job's revision is the guard.
   */
  async #serializedCompactionStep<T>(tableId: string, step: () => Promise<T>): Promise<T> {
    const previous = this.#compactionSteps.get(tableId) ?? Promise.resolve();
    const run = previous.then(step, step);
    this.#compactionSteps.set(tableId, run);
    try {
      return await run;
    } finally {
      if (this.#compactionSteps.get(tableId) === run) this.#compactionSteps.delete(tableId);
    }
  }

  async #findActiveCompactionJob(tableId?: string): Promise<CompactionJobRecord | undefined> {
    let cursor: string | null = null;
    do {
      const page = await this.store.listCompactionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      const active = page.records.find(
        (job) =>
          (tableId === undefined || job.tableId === tableId) && isActiveCompactionState(job.state),
      );
      if (active !== undefined) return active;
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
    return undefined;
  }

  async listCompactionJobs(tableName?: string): Promise<CompactionJobRecord[]> {
    if (tableName === undefined) return this.store.listCompactionJobs();
    const table = await this.#findTable(tableName);
    return this.store.listCompactionJobs(table.id);
  }

  /** Atomically prevents an unpublished compaction job from committing its transaction. */
  async cancelCompactionJob(jobId: string): Promise<CancelCompactionJobResult> {
    for (;;) {
      const job = await this.store.getCompactionJob(jobId);
      if (job === undefined) throw new Error(`Compaction job not found: ${jobId}`);
      if (job.state === "cancelled" || job.state === "published" || job.state === "aborted") {
        return compactionCancellationResult(job);
      }
      try {
        return compactionCancellationResult(
          await this.store.cancelCompactionJob(job.id, job.revision, dateIsoString(this.#now())),
        );
      } catch (error) {
        if (error instanceof CompactionJobConflictError) continue;
        throw error;
      }
    }
  }

  async #cancelTableCompactions(tableId: string): Promise<void> {
    let cursor: string | null = null;
    do {
      const page = await this.store.listCompactionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const job of page.records) {
        if (
          job.tableId === tableId &&
          (job.state === "planned" || job.state === "running" || job.state === "ready")
        ) {
          await this.cancelCompactionJob(job.id);
        }
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
  }

  /** Runs restart-safe lease-aware reclamation to completion in bounded durable steps. */
  async collectGarbage(options: CollectGarbageOptions = {}): Promise<GarbageCollectionResult> {
    const maxItems = boundedMaintenanceBatchItems(
      options.maxItemsPerStep ?? 64,
      "Garbage collection items per step",
    );
    // Crash-left and abandoned compaction work first, over every job record, as a background
    // pass does over a page: an owner past its lease is aborted and its job resumed or
    // cancelled. An explicit call is how a caller repairs a store, and repair that only the
    // background retry timer performed left a write at the level-zero ceiling failing on a
    // dead owner after this call had returned.
    let reconciliationCursor: string | null = null;
    do {
      reconciliationCursor = (await this.#reconcileCompactionPage(reconciliationCursor)).nextCursor;
    } while (reconciliationCursor !== null);
    let progress = await this.collectGarbageStep({
      maxItems,
      ...(options.maxPlanningItems === undefined
        ? {}
        : { maxPlanningItems: options.maxPlanningItems }),
      ...(options.retainRecentVersions === undefined
        ? {}
        : { retainRecentVersions: options.retainRecentVersions }),
    });
    while (progress.result === null) {
      progress = await this.resumeGarbageCollectionJob(progress.jobId, { maxItems });
    }
    await this.#pruneFinishedJobRecords();
    // An explicit successful pass is the caller accepting responsibility for manual mode. It
    // reopens the generous write window; if the store cannot complete, the exception leaves the
    // ceiling in place.
    this.#autoCollectionDebtCommits = 0;
    this.#manualCollectionDebtInitialized = true;
    this.#commitsSinceCollection = 0;
    this.#lastCollectionCompletedAt = dateMilliseconds(this.#now());
    return progress.result;
  }

  /** Plans or advances one durable garbage-collection pass. */
  async collectGarbageStep(
    options: CollectGarbageStepOptions = {},
  ): Promise<GarbageCollectionProgress> {
    return this.#collectGarbageStep(options);
  }

  /** `collectGarbageStep`, with the age bound background collection adds to its retention. */
  async #collectGarbageStep(
    options: CollectGarbageStepOptions,
    retainedVersionMaxAgeMs = Number.POSITIVE_INFINITY,
  ): Promise<GarbageCollectionProgress> {
    const maxPlanningItems = boundedMaintenanceBatchItems(
      options.maxPlanningItems ?? 1_024,
      "Garbage collection planning limit",
    );
    const maxItems = boundedMaintenanceBatchItems(
      options.maxItems ?? 1,
      "Garbage collection item limit",
    );
    return this.#serializedCollectionStep(async () => {
      const active = await this.#findActiveGarbageCollectionJob();
      const job =
        active ??
        (await this.#planGarbageCollection(
          maxPlanningItems,
          boundedRetainedVersions(options.retainRecentVersions ?? 0),
          retainedVersionMaxAgeMs,
        ));
      return this.#runGarbageCollectionJob(job, maxItems);
    });
  }

  async #findActiveGarbageCollectionJob(): Promise<GarbageCollectionJobRecord | undefined> {
    let cursor: string | null = null;
    do {
      const page = await this.store.listGarbageCollectionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      const active = page.records.find((job) => job.state === "planned" || job.state === "running");
      if (active !== undefined) return active;
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
    return undefined;
  }

  /** Continues a persisted reclamation pass after a cooperative yield or restart. */
  async resumeGarbageCollectionJob(
    jobId: string,
    options: CollectGarbageStepOptions = {},
  ): Promise<GarbageCollectionProgress> {
    const job = await this.store.getGarbageCollectionJob(jobId);
    if (job === undefined) throw new Error(`Garbage collection job not found: ${jobId}`);
    return this.#serializedCollectionStep(() =>
      this.#runGarbageCollectionJob(
        job,
        boundedMaintenanceBatchItems(options.maxItems ?? 1, "Garbage collection item limit"),
      ),
    );
  }

  /**
   * One garbage-collection step at a time within this database, for the same reason
   * compaction steps take turns (`#serializedCompactionStep`): background collection drives
   * a job in steps, and a caller stepping collection explicitly continues the same job rather
   * than racing it.
   */
  async #serializedCollectionStep<T>(step: () => Promise<T>): Promise<T> {
    const previous = this.#collectionSteps;
    const run = previous.then(step, step);
    this.#collectionSteps = run;
    try {
      return await run;
    } finally {
      if (this.#collectionSteps === run) this.#collectionSteps = Promise.resolve();
    }
  }

  /**
   * Background collection: plans one pass and drives it to completion in yielding steps.
   * Runs after a background fold, whose superseded blocks are what a pass reclaims, and every
   * AUTO_COLLECT_COMMIT_INTERVAL commits, since every commit writes a manifest that stays on
   * disk until pruned. Keeps the most recent versions readable. Never surfaces through a
   * write or a scan; a failed pass backs off for an interval of commits.
   */
  #maybeScheduleAutoCollection(force = false): void {
    if (this.#closed) return;
    if (!this.#autoCollect) return;
    if (this.#autoCollectionInFlight) {
      // A fold finishing or a quiet minute passing while a run is under way is a reason for
      // one more run once this one ends — a dropped trigger after the last commit of a burst
      // would otherwise leave the burst's leftovers until the next one.
      this.#autoCollectionRequested = true;
      return;
    }
    if (this.#autoCollectionRetryTimer !== undefined && !force) return;
    if (force && this.#autoCollectionRetryTimer !== undefined) {
      clearTimeout(this.#autoCollectionRetryTimer);
      this.#autoCollectionRetryTimer = undefined;
      this.#autoCollectionRetryAt = undefined;
    }
    this.#autoCollectionInFlight = true;
    this.#autoCollectionRequested = false;
    this.#commitsSinceCollection = 0;
    this.#lastCollectionAt = dateMilliseconds(this.#now());
    const run = this.#runAutoCollection()
      .then(({ moreWork, reclaimed }) => {
        this.#autoCollectionConsecutiveFailures = 0;
        this.#autoCollectionLastError = undefined;
        this.#lastCollectionCompletedAt = dateMilliseconds(this.#now());
        this.#autoCollectionRetryAt = undefined;
        if (moreWork) this.#autoCollectionRequested = true;
        // Debt counts commits the collector has not kept up with. A pass that reclaimed
        // something kept up; only a run that found nothing to reclaim while compaction work
        // is still outstanding leaves the count for the next one to settle.
        if (reclaimed || !moreWork) this.#autoCollectionDebtCommits = 0;
      })
      .catch((error: unknown) => {
        this.#autoCollectionConsecutiveFailures += 1;
        const at = dateMilliseconds(this.#now());
        this.#autoCollectionLastError = {
          name: error instanceof Error ? error.name : "Error",
          message: error instanceof Error ? error.message : String(error),
          at,
        };
        this.#scheduleAutoCollectionRetry();
      })
      .finally(() => {
        if (this.#autoCollectionTask === run) this.#autoCollectionTask = undefined;
        this.#autoCollectionInFlight = false;
        if (this.#autoCollectionRequested) {
          void this.#yieldMaintenance().then(() => {
            // Keep `collectionRequested` true until the continuation takes ownership. Otherwise
            // maintenanceStatus briefly reports a false idle state between bounded runs, and a
            // caller waiting for quiescence can leave a real backlog behind.
            if (this.#closed) {
              this.#autoCollectionRequested = false;
              return;
            }
            // A commit may already have started the requested run during the yield. Its start
            // clears the flag, and any newer request made while it runs remains set for that
            // run's own continuation.
            if (this.#autoCollectionInFlight) return;
            this.#maybeScheduleAutoCollection();
          });
        }
      });
    this.#autoCollectionTask = run;
    void run;
  }

  #scheduleAutoCollectionRetry(): void {
    if (this.#closed || !this.#autoCollect || this.#autoCollectionRetryTimer !== undefined) return;
    const exponent = Math.min(16, Math.max(0, this.#autoCollectionConsecutiveFailures - 1));
    const delay = Math.min(AUTO_COLLECT_RETRY_MAX_MS, AUTO_COLLECT_RETRY_MIN_MS * 2 ** exponent);
    this.#autoCollectionRetryAt = dateMilliseconds(this.#now()) + delay;
    const timer = setTimeout(() => {
      this.#autoCollectionRetryTimer = undefined;
      this.#autoCollectionRetryAt = undefined;
      this.#maybeScheduleAutoCollection(true);
    }, delay);
    (timer as { unref?: () => void }).unref?.();
    this.#autoCollectionRetryTimer = timer;
  }

  /**
   * A pass a quiet period after the last commit, for a tab that stops writing: the retained
   * window's age bound lets that pass reclaim what the last burst superseded, which no commit
   * would otherwise arrive to trigger. Re-armed by every commit; unreferenced, so it never
   * keeps a process alive.
   */
  #armIdleCollection(): void {
    if (this.#closed) return;
    if (!this.#autoCollect) return;
    if (this.#idleCollectionTimer !== undefined) clearTimeout(this.#idleCollectionTimer);
    const timer = setTimeout(() => {
      this.#idleCollectionTimer = undefined;
      this.#maybeScheduleAutoCollection();
    }, AUTO_COLLECT_QUIET_MS);
    (timer as { unref?: () => void }).unref?.();
    this.#idleCollectionTimer = timer;
  }

  async #runAutoCollection(): Promise<{ moreWork: boolean; reclaimed: boolean }> {
    const reconciliationMoreWork = await this.#reconcileCompactionMaintenance();
    // One pass plans a bounded number of candidates, so a backlog — a burst of commits that
    // outran the passes between them — takes several. Keep passing while a pass still finds
    // something, up to a ceiling that keeps a pathological store from pinning the loop.
    let moreWork = false;
    let reclaimed = false;
    for (let pass = 0; pass < AUTO_COLLECT_MAX_PASSES; pass += 1) {
      if (this.#closed) break;
      this.#releaseIdleSharedLease();
      let progress = await this.#collectGarbageStep(
        {
          maxItems: AUTO_COLLECT_STEP_ITEMS,
          maxPlanningItems: AUTO_COLLECT_STEP_ITEMS,
          retainRecentVersions: AUTO_COLLECT_RETAINED_VERSIONS,
        },
        AUTO_COLLECT_RETAINED_VERSION_MS,
      );
      while (progress.result === null) {
        await this.#yieldMaintenance();
        progress = await this.resumeGarbageCollectionJob(progress.jobId, {
          maxItems: AUTO_COLLECT_STEP_ITEMS,
        });
      }
      const result = progress.result;
      moreWork = !(
        result.prunedManifestCount === 0 &&
        result.reclaimedBlockCount === 0 &&
        result.reclaimedSegmentCount === 0 &&
        result.reclaimedTransactionCount === 0
      );
      if (!moreWork) {
        break;
      }
      reclaimed = true;
      await this.#yieldMaintenance();
    }
    await this.#pruneFinishedJobRecords();
    return { moreWork: moreWork || reconciliationMoreWork, reclaimed };
  }

  /**
   * Advances or cancels a bounded page of crash-left compaction work before collection plans
   * roots. A rotating cursor prevents old terminal diagnostics from starving later active jobs;
   * one output block per job keeps a quiet pass out of the foreground latency budget.
   */
  async #reconcileCompactionMaintenance(): Promise<boolean> {
    const { nextCursor, moreWork } = await this.#reconcileCompactionPage(
      this.#compactionReconciliationCursor,
    );
    this.#compactionReconciliationCursor = nextCursor;
    return moreWork;
  }

  /** One page of #reconcileCompactionMaintenance, from a caller-chosen cursor. */
  async #reconcileCompactionPage(
    cursor: string | null,
  ): Promise<{ nextCursor: string | null; moreWork: boolean }> {
    const page = await this.store.listCompactionJobPage(cursor, AUTO_COMPACTION_RECONCILE_RECORDS);
    let moreWork = page.nextCursor !== null;
    const cutoff = dateIsoString(this.#now());
    for (const listed of page.records) {
      if (!isActiveCompactionState(listed.state)) continue;
      let job = (await this.store.getCompactionJob(listed.id)) ?? listed;
      if (!isActiveCompactionState(job.state)) continue;
      moreWork = true;

      const table = await this.store.getTable(job.tableId);
      if (table === undefined) {
        await this.cancelCompactionJob(job.id);
        continue;
      }

      if (job.transactionId !== null) {
        let owner = await this.store.getTransaction(job.transactionId);
        if (owner?.status === "active" && Date.parse(owner.expiresAt) <= Date.parse(cutoff)) {
          await this.store.abortTransactionIfExpired({
            transactionId: owner.id,
            expectedOwnerId: owner.ownerId,
            expiresAtCutoff: cutoff,
            updatedAt: cutoff,
          });
          owner = await this.store.getTransaction(job.transactionId);
        }
        if (owner?.status === "committed" && owner.committedVersion !== null) {
          await this.resumeCompactionJob(job.id, { maxBlocks: 1 });
          continue;
        }
        if (owner?.status !== "active") {
          await this.cancelCompactionJob(job.id);
          this.#maybeScheduleAutoCompaction(table, await this.#currentVisibleSegments(table));
          continue;
        }
      }

      const currentVersion = await this.store.getCurrentManifestVersion();
      const sourcePresence = await this.#manifestBlockPresence(currentVersion, job.sourceBlockIds);
      const visibleSegmentIds = new Set(
        (await this.#currentVisibleSegments(table)).map((segment) => segment.id),
      );
      if (
        sourcePresence.some((present) => !present) ||
        job.sourceSegmentIds.some((id) => !visibleSegmentIds.has(id))
      ) {
        await this.cancelCompactionJob(job.id);
        this.#maybeScheduleAutoCompaction(table, await this.#currentVisibleSegments(table));
        continue;
      }

      // One step of the job, as this database's own fold would take it. A step that fails —
      // publication abandoned, a source gone, a budget exceeded — is recorded on the job, and
      // the next check re-plans the table; it is not a collection failure, and must not put
      // the collector on its retry timer for it.
      try {
        const progress = await this.resumeCompactionJob(job.id, { maxBlocks: 1 });
        if (progress.result !== null) {
          job = (await this.store.getCompactionJob(job.id)) ?? job;
          if (!isActiveCompactionState(job.state)) continue;
        }
      } catch (error) {
        if (error instanceof CompactionJobCancelledError) continue;
        if (this.#closed) throw error;
        this.#maybeScheduleAutoCompaction(table, await this.#currentVisibleSegments(table));
      }
    }
    return { nextCursor: page.nextCursor, moreWork };
  }

  /** Drops finished maintenance records while preserving the state needed for safe L2 retries. */
  async #pruneFinishedJobRecords(): Promise<void> {
    interface UpdatedRecord {
      id: string;
      updatedAt: string;
    }
    const newestFirst = (left: UpdatedRecord, right: UpdatedRecord): number =>
      right.updatedAt.localeCompare(left.updatedAt) || right.id.localeCompare(left.id);
    const retainNewest = <T extends UpdatedRecord>(retained: T[], record: T): void => {
      retained.push(record);
      retained.sort(newestFirst);
      if (retained.length > AUTO_COLLECT_RETAINED_JOB_RECORDS) retained.pop();
    };

    // First pass retains only a fixed-size diagnostic tail. This is deliberately not the public
    // list API: a million old job records cost one adapter page plus eight IDs of resident memory.
    const newestCompactions: CompactionJobRecord[] = [];
    let cursor: string | null = null;
    do {
      const page = await this.store.listCompactionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const job of page.records) {
        if (job.state === "published" || job.state === "cancelled" || job.state === "aborted") {
          retainNewest(newestCompactions, job);
        }
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
    const retainedCompactionIds = new Set(newestCompactions.map((job) => job.id));

    // Retry IDs sort next to their base ID. Keep at most one newest failed attempt for each
    // still-readable source snapshot; it carries the cumulative lifetime write budget. The
    // single group candidate avoids an unbounded base-id map, while the diagnostic tail above
    // remains independently retained.
    cursor = null;
    let failureBaseId: string | undefined;
    let newestReadableFailure: CompactionJobRecord | undefined;
    let readableManifestVersion: number | undefined;
    let readableManifest = false;
    do {
      const page = await this.store.listCompactionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const job of page.records) {
        if (job.state !== "published" && job.state !== "cancelled" && job.state !== "aborted") {
          continue;
        }
        if (job.state === "published") {
          if (!retainedCompactionIds.has(job.id)) await this.store.removeCompactionJob(job.id);
          continue;
        }

        const baseId = job.id.split("/retry/", 1)[0] ?? job.id;
        if (baseId !== failureBaseId) {
          failureBaseId = baseId;
          newestReadableFailure = undefined;
          readableManifestVersion = undefined;
        }
        if (readableManifestVersion !== job.sourceManifestVersion) {
          const manifest = await this.store.getManifest(job.sourceManifestVersion);
          readableManifest = manifest !== undefined && manifest.prunedAt === undefined;
          readableManifestVersion = job.sourceManifestVersion;
        }
        if (!readableManifest) {
          if (!retainedCompactionIds.has(job.id)) await this.store.removeCompactionJob(job.id);
          continue;
        }

        if (newestReadableFailure === undefined) {
          newestReadableFailure = job;
          continue;
        }
        if (newestFirst(job, newestReadableFailure) < 0) {
          if (!retainedCompactionIds.has(newestReadableFailure.id)) {
            await this.store.removeCompactionJob(newestReadableFailure.id);
          }
          newestReadableFailure = job;
        } else if (!retainedCompactionIds.has(job.id)) {
          await this.store.removeCompactionJob(job.id);
        }
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);

    const newestCollections: GarbageCollectionJobRecord[] = [];
    cursor = null;
    do {
      const page = await this.store.listGarbageCollectionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const job of page.records) {
        if (job.state === "completed") retainNewest(newestCollections, job);
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
    const retainedCollectionIds = new Set(newestCollections.map((job) => job.id));
    cursor = null;
    do {
      const page = await this.store.listGarbageCollectionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const job of page.records) {
        if (job.state === "completed" && !retainedCollectionIds.has(job.id)) {
          await this.store.removeGarbageCollectionJob(job.id);
        }
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
  }

  async listGarbageCollectionJobs(): Promise<GarbageCollectionJobRecord[]> {
    return this.store.listGarbageCollectionJobs();
  }

  async #planGarbageCollection(
    maxPlanningItems: number,
    retainRecentVersions: number,
    retainedVersionMaxAgeMs = Number.POSITIVE_INFINITY,
  ): Promise<GarbageCollectionJobRecord> {
    // Crashed readers and query spill owners are metadata roots too. Sweep their expired
    // records as part of every explicit or background collection so callers never need a
    // separate maintenance loop to keep either family bounded.
    await this.#transactions.removeExpiredLeases(this.#now());
    await this.#cleanupExpiredQuerySpill(MAINTENANCE_JOB_PAGE_SIZE);
    const discoveryCutoff = dateIsoString(this.#now());
    const discoveryCurrent = await this.store.getCurrentManifestVersion();
    const continuation = await this.#garbageCollectionDiscoveryContinuation();
    const input = {
      id: `garbage-collection/${this.#createId()}`,
      candidateManifestVersions: [],
      candidateSegmentIds: [],
      candidateBlockIds: [],
      candidateTransactionIds: [],
      leaseCutoff: discoveryCutoff,
      createdAt: discoveryCutoff,
      discovery: {
        phase: "manifests",
        currentManifestVersion: discoveryCurrent,
        retainAboveVersion: (discoveryCurrent ?? 0) - retainRecentVersions,
        retainAfter: Number.isFinite(retainedVersionMaxAgeMs)
          ? dateMilliseconds(this.#now()) - retainedVersionMaxAgeMs
          : Number.MIN_SAFE_INTEGER,
        maxPlanningItems,
        manifestCursor:
          continuation?.discovery.resumePhase === "manifests"
            ? continuation.discovery.manifestCursor
            : null,
        segmentCursor: continuation?.discovery.segmentCursor ?? null,
        transactionCursor: continuation?.discovery.transactionCursor ?? null,
        compactionCursor: continuation?.discovery.compactionCursor ?? null,
        visitedRecords: 0,
        resumePhase: null,
        postManifestPhase:
          continuation?.discovery.resumePhase === "manifests"
            ? (continuation.discovery.postManifestPhase ?? null)
            : (continuation?.discovery.resumePhase ?? null),
        artifactCursor: continuation?.discovery.artifactCursor ?? null,
      },
    } satisfies Parameters<BlockStore["createGarbageCollectionJob"]>[0];
    let discovered: GarbageCollectionJobRecord;
    try {
      discovered = await this.store.createGarbageCollectionJob(input);
    } catch (error) {
      if (!(error instanceof GarbageCollectionJobConflictError)) throw error;
      const raced = await this.#findActiveGarbageCollectionJob();
      if (raced === undefined) throw error;
      return raced;
    }
    // The successor job now durably owns the exact continuation cursor. Retaining the source
    // forever makes a same-timestamp reopen choose an arbitrary old cursor and can replay or
    // lose a bounded provenance tail. Handoff is create-before-delete, so a crash always leaves
    // at least one durable owner of the cursor.
    if (continuation !== undefined) {
      await this.store.removeGarbageCollectionJob(continuation.jobId);
    }
    return this.#advanceGarbageCollectionPlanning(discovered);
  }

  async #garbageCollectionDiscoveryContinuation(): Promise<
    | {
        jobId: string;
        discovery: NonNullable<GarbageCollectionJobRecord["discovery"]>;
      }
    | undefined
  > {
    let cursor: string | null = null;
    let newest: GarbageCollectionJobRecord | undefined;
    do {
      const page = await this.store.listGarbageCollectionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const job of page.records) {
        if (
          job.state !== "completed" ||
          job.discovery?.resumePhase === undefined ||
          job.discovery.resumePhase === null
        ) {
          continue;
        }
        if (
          newest === undefined ||
          job.updatedAt > newest.updatedAt ||
          (job.updatedAt === newest.updatedAt && job.id > newest.id)
        ) {
          newest = job;
        }
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
    return newest?.discovery === undefined
      ? undefined
      : { jobId: newest.id, discovery: newest.discovery };
  }

  async #advanceGarbageCollectionPlanning(
    initialJob: GarbageCollectionJobRecord,
  ): Promise<GarbageCollectionJobRecord> {
    let job = initialJob;
    for (;;) {
      const discovery = job.discovery;
      if (discovery === undefined || discovery.phase === "complete") return job;
      const candidateCount =
        job.candidateManifestVersions.length +
        job.candidateBlockIds.length +
        job.candidateSegmentIds.length +
        job.candidateTransactionIds.length;
      let remaining = discovery.maxPlanningItems - candidateCount;
      const currentVersion = discovery.currentManifestVersion;
      const appendManifestVersions: number[] = [];
      const appendBlockIds: string[] = [];
      const appendSegmentIds: string[] = [];
      const appendTransactionIds: string[] = [];
      const knownBlocks = new Set(job.candidateBlockIds);
      const knownSegments = new Set(job.candidateSegmentIds);
      const knownTransactions = new Set(job.candidateTransactionIds);
      let next: NonNullable<GarbageCollectionJobRecord["discovery"]> = {
        ...discovery,
      };
      const addBlocks = (ids: readonly string[]) => {
        for (const id of ids) {
          if (remaining <= 0) break;
          if (knownBlocks.has(id)) continue;
          knownBlocks.add(id);
          appendBlockIds.push(id);
          remaining -= 1;
        }
      };
      const addManifests = (versions: readonly number[]) => {
        const known = new Set([...job.candidateManifestVersions, ...appendManifestVersions]);
        for (const version of versions) {
          if (remaining <= 0) break;
          if (known.has(version)) continue;
          known.add(version);
          appendManifestVersions.push(version);
          remaining -= 1;
        }
      };
      const addSegments = (ids: readonly string[]) => {
        for (const id of ids) {
          if (remaining <= 0) break;
          if (knownSegments.has(id)) continue;
          knownSegments.add(id);
          appendSegmentIds.push(id);
          remaining -= 1;
        }
      };
      const addTransactions = (ids: readonly string[]) => {
        for (const id of ids) {
          if (remaining <= 0) break;
          if (knownTransactions.has(id)) continue;
          knownTransactions.add(id);
          appendTransactionIds.push(id);
          remaining -= 1;
        }
      };

      if (remaining <= 0) {
        next = {
          ...next,
          phase: "complete",
          resumePhase: discovery.phase,
        };
      } else if (discovery.phase === "manifests") {
        const page = await this.store.listManifestPage(
          discovery.manifestCursor,
          MAINTENANCE_JOB_PAGE_SIZE,
        );
        let reachedPlanningCurrent = false;
        let lastVisited = discovery.manifestCursor;
        for (const manifest of page.records) {
          if (
            discovery.currentManifestVersion !== null &&
            manifest.version >= discovery.currentManifestVersion
          ) {
            reachedPlanningCurrent = true;
            break;
          }
          lastVisited = manifest.version;
          const retained =
            manifest.version > discovery.retainAboveVersion &&
            Date.parse(manifest.createdAt) > discovery.retainAfter;
          if (retained) continue;
          if (manifest.prunedAt === undefined) addManifests([manifest.version]);
          if (remaining <= 0) break;
        }
        const complete = reachedPlanningCurrent || page.nextCursor === null || remaining <= 0;
        next = {
          ...next,
          phase: complete
            ? remaining <= 0
              ? "complete"
              : (discovery.postManifestPhase ?? "manifest-blocks")
            : "manifests",
          resumePhase: remaining <= 0 ? "manifests" : null,
          postManifestPhase: remaining <= 0 ? (discovery.postManifestPhase ?? null) : null,
          manifestCursor: remaining <= 0 ? lastVisited : complete ? null : page.nextCursor,
          visitedRecords: safeWholeNumberSum(
            [discovery.visitedRecords, page.records.length],
            "Garbage collection discovery records",
          ),
        };
      } else if (discovery.phase === "manifest-blocks") {
        const cursor = discovery.artifactCursor;
        const afterBlockId = cursor?.family === "manifest" ? cursor.blockId : null;
        const page = await this.store.listRetiredManifestBlockPage({
          removedThroughVersion: currentVersion ?? 0,
          afterBlockId,
          limit: MAINTENANCE_JOB_PAGE_SIZE,
        });
        const pageIds = page.records.map((record) => record.blockId);
        const scanned = await this.#existingGarbageBlockCandidatesFrom(
          pageIds,
          currentVersion,
          knownBlocks,
          0,
          remaining,
        );
        addBlocks(scanned.candidateIds);
        const pageComplete = scanned.nextIndex >= pageIds.length;
        const reachedEnd = pageComplete && page.nextCursor === null;
        const lastExaminedBlockId =
          scanned.nextIndex === 0 ? afterBlockId : (pageIds[scanned.nextIndex - 1] ?? afterBlockId);
        next = {
          ...next,
          phase: remaining <= 0 ? "complete" : reachedEnd ? "segments" : "manifest-blocks",
          resumePhase: remaining <= 0 ? "manifest-blocks" : null,
          manifestCursor: null,
          artifactCursor:
            reachedEnd && remaining > 0
              ? null
              : {
                  family: "manifest",
                  recordId: String(currentVersion ?? 0),
                  blockId: lastExaminedBlockId,
                  blockIndex: 0,
                  segmentIndex: 0,
                },
          visitedRecords: safeWholeNumberSum(
            [discovery.visitedRecords, page.records.length],
            "Garbage collection discovery records",
          ),
        };
      } else if (discovery.phase === "segments") {
        const page = await this.store.listSegmentPage(discovery.segmentCursor, 1);
        for (const segment of page.records) {
          const listedOwner = await this.store.getTransaction(segment.transactionId);
          if (
            listedOwner?.status === "active" &&
            Date.parse(listedOwner.expiresAt) <= Date.parse(job.leaseCutoff)
          ) {
            await this.store.abortTransactionIfExpired({
              transactionId: listedOwner.id,
              expectedOwnerId: listedOwner.ownerId,
              expiresAtCutoff: job.leaseCutoff,
              updatedAt: job.leaseCutoff,
            });
          }
          const segmentBlockIds = [...new Set(Object.values(segment.columnBlockIds).flat())];
          const touchesCurrent = (
            await this.#manifestBlockPresence(currentVersion, segmentBlockIds)
          ).some(Boolean);
          if (!touchesCurrent) addSegments([segment.id]);
          if (remaining <= 0) break;
        }
        const record = page.records[0];
        const filled = remaining <= 0;
        next = {
          ...next,
          phase: record === undefined ? "transactions" : filled ? "complete" : "segments",
          resumePhase: filled ? "segments" : null,
          segmentCursor: record?.id ?? null,
          artifactCursor: null,
          visitedRecords: safeWholeNumberSum(
            [discovery.visitedRecords, page.records.length],
            "Garbage collection discovery records",
          ),
        };
      } else if (discovery.phase === "transactions") {
        const cursor = discovery.artifactCursor;
        let transaction: TransactionRecord | undefined;
        let blockIndex = 0;
        let segmentIndex = 0;
        if (cursor?.family === "transaction") {
          transaction = await this.store.getTransaction(cursor.recordId);
          blockIndex = cursor.blockIndex;
          segmentIndex = cursor.segmentIndex;
        } else {
          const page = await this.store.listTransactionPage(discovery.transactionCursor, 1);
          transaction = page.records[0];
          if (transaction === undefined) {
            next = {
              ...next,
              phase: "compactions",
              transactionCursor: null,
              artifactCursor: null,
              resumePhase: null,
            };
          }
        }
        if (transaction !== undefined) {
          if (
            transaction.status === "active" &&
            Date.parse(transaction.expiresAt) <= Date.parse(job.leaseCutoff)
          ) {
            transaction =
              (await this.store.abortTransactionIfExpired({
                transactionId: transaction.id,
                expectedOwnerId: transaction.ownerId,
                expiresAtCutoff: job.leaseCutoff,
                updatedAt: job.leaseCutoff,
              })) ?? transaction;
          }
          let revisit = false;
          if (transaction.status === "aborted") {
            const blocks = await this.#existingGarbageBlockCandidatesFrom(
              transaction.pendingBlockIds,
              currentVersion,
              knownBlocks,
              blockIndex,
              remaining,
            );
            addBlocks(blocks.candidateIds);
            blockIndex = blocks.nextIndex;
            if (blockIndex >= transaction.pendingBlockIds.length && remaining > 0) {
              const segments = await this.#existingGarbageSegmentCandidatesFrom(
                transaction.pendingSegmentIds,
                knownSegments,
                segmentIndex,
                remaining,
              );
              addSegments(segments.candidateIds);
              segmentIndex = segments.nextIndex;
            }
            revisit =
              blocks.candidateIds.length > 0 ||
              appendSegmentIds.length > 0 ||
              blockIndex < transaction.pendingBlockIds.length ||
              segmentIndex < transaction.pendingSegmentIds.length;
            if (!revisit) addTransactions([transaction.id]);
          } else if (transaction.status === "committed" && transaction.committedVersion !== null) {
            const manifest = await this.store.getManifest(transaction.committedVersion);
            if (
              manifest === undefined ||
              manifest.prunedAt !== undefined ||
              job.candidateManifestVersions.includes(transaction.committedVersion) ||
              appendManifestVersions.includes(transaction.committedVersion)
            ) {
              addTransactions([transaction.id]);
            }
          }
          const filled = remaining <= 0;
          next = {
            ...next,
            phase: filled ? "complete" : "transactions",
            resumePhase: filled ? "transactions" : null,
            transactionCursor: revisit ? discovery.transactionCursor : transaction.id,
            artifactCursor: revisit
              ? {
                  family: "transaction",
                  recordId: transaction.id,
                  blockId: null,
                  blockIndex,
                  segmentIndex,
                }
              : null,
            visitedRecords: safeWholeNumberSum(
              [discovery.visitedRecords, cursor?.family === "transaction" ? 0 : 1],
              "Garbage collection discovery records",
            ),
          };
        } else if (cursor?.family === "transaction") {
          next = {
            ...next,
            transactionCursor: cursor.recordId,
            artifactCursor: null,
            resumePhase: null,
          };
        }
      } else {
        const cursor = discovery.artifactCursor;
        let compaction: CompactionJobRecord | undefined;
        let blockIndex = 0;
        let segmentIndex = 0;
        if (cursor?.family === "compaction") {
          compaction = await this.store.getCompactionJob(cursor.recordId);
          blockIndex = cursor.blockIndex;
          segmentIndex = cursor.segmentIndex;
        } else {
          const page = await this.store.listCompactionJobPage(discovery.compactionCursor, 1);
          compaction = page.records[0];
          if (compaction === undefined) {
            next = {
              ...next,
              phase: "complete",
              compactionCursor: null,
              artifactCursor: null,
              resumePhase: null,
            };
          }
        }
        if (compaction !== undefined) {
          const terminal =
            compaction.state === "published" ||
            compaction.state === "cancelled" ||
            compaction.state === "aborted";
          let revisit = false;
          if (terminal) {
            const blockIds = [...compaction.sourceBlockIds, ...compaction.outputBlockIds];
            const blocks = await this.#existingGarbageBlockCandidatesFrom(
              blockIds,
              currentVersion,
              knownBlocks,
              blockIndex,
              remaining,
            );
            addBlocks(blocks.candidateIds);
            blockIndex = blocks.nextIndex;
            const segmentIds = [
              ...compaction.sourceSegmentIds,
              ...compactionOutputSegmentIds(compaction),
            ];
            if (blockIndex >= blockIds.length && remaining > 0) {
              const segments = await this.#existingGarbageSegmentCandidatesFrom(
                segmentIds,
                knownSegments,
                segmentIndex,
                remaining,
              );
              addSegments(segments.candidateIds);
              segmentIndex = segments.nextIndex;
            }
            revisit =
              blocks.candidateIds.length > 0 ||
              appendSegmentIds.length > 0 ||
              blockIndex < blockIds.length ||
              segmentIndex < segmentIds.length;
          }
          const filled = remaining <= 0;
          next = {
            ...next,
            phase: filled ? "complete" : "compactions",
            resumePhase: filled ? "compactions" : null,
            compactionCursor: revisit ? discovery.compactionCursor : compaction.id,
            artifactCursor: revisit
              ? {
                  family: "compaction",
                  recordId: compaction.id,
                  blockId: null,
                  blockIndex,
                  segmentIndex,
                }
              : null,
            visitedRecords: safeWholeNumberSum(
              [discovery.visitedRecords, cursor?.family === "compaction" ? 0 : 1],
              "Garbage collection discovery records",
            ),
          };
        } else if (cursor?.family === "compaction") {
          next = {
            ...next,
            compactionCursor: cursor.recordId,
            artifactCursor: null,
            resumePhase: null,
          };
        }
      }

      try {
        job = await this.store.updateGarbageCollectionPlanning({
          jobId: job.id,
          expectedRevision: job.revision,
          ...(appendManifestVersions.length === 0
            ? {}
            : { candidateManifestVersions: appendManifestVersions }),
          ...(appendSegmentIds.length === 0 ? {} : { candidateSegmentIds: appendSegmentIds }),
          ...(appendBlockIds.length === 0 ? {} : { candidateBlockIds: appendBlockIds }),
          ...(appendTransactionIds.length === 0
            ? {}
            : { candidateTransactionIds: appendTransactionIds }),
          discovery: next,
          updatedAt: dateIsoString(this.#now()),
        });
        return job;
      } catch (error) {
        if (!(error instanceof GarbageCollectionJobConflictError)) throw error;
        const latest = await this.store.getGarbageCollectionJob(job.id);
        if (latest === undefined) throw error;
        job = latest;
      }
    }
  }

  async #existingGarbageBlockCandidatesFrom(
    ids: readonly string[],
    currentVersion: number | null,
    alreadyPlanned: ReadonlySet<string>,
    startIndex: number,
    limit: number,
  ): Promise<{ candidateIds: string[]; nextIndex: number }> {
    if (limit <= 0) return { candidateIds: [], nextIndex: startIndex };
    // A block the current manifest still carries is not garbage, whatever else references it.
    // Ask the adapter's interval-membership index in bounded windows instead of materializing
    // the current database-sized membership set in the planner.
    const candidates: string[] = [];
    let nextIndex = startIndex;
    while (nextIndex < ids.length && candidates.length < limit) {
      const page: string[] = [];
      const pageLimit = Math.min(64, limit - candidates.length);
      while (nextIndex < ids.length && page.length < pageLimit) {
        const id = ids[nextIndex];
        nextIndex += 1;
        if (id === undefined || alreadyPlanned.has(id)) continue;
        page.push(id);
      }
      if (page.length === 0) continue;
      const present = await this.#manifestBlockPresence(currentVersion, page);
      const blocks = await this.#getBlocksWindowed(page);
      for (let index = 0; index < page.length && candidates.length < limit; index += 1) {
        const id = page[index] ?? "";
        if (present[index] !== true && blocks[index] !== undefined) candidates.push(id);
      }
    }
    return { candidateIds: candidates, nextIndex };
  }

  async #existingGarbageSegmentCandidatesFrom(
    ids: readonly string[],
    alreadyPlanned: ReadonlySet<string>,
    startIndex: number,
    limit: number,
  ): Promise<{ candidateIds: string[]; nextIndex: number }> {
    const candidates: string[] = [];
    let nextIndex = startIndex;
    while (nextIndex < ids.length && candidates.length < limit) {
      const id = ids[nextIndex];
      nextIndex += 1;
      if (
        id === undefined ||
        alreadyPlanned.has(id) ||
        (await this.store.getSegment(id)) === undefined
      ) {
        continue;
      }
      candidates.push(id);
    }
    return { candidateIds: candidates, nextIndex };
  }

  async #runGarbageCollectionJob(
    initialJob: GarbageCollectionJobRecord,
    maxItems: number,
  ): Promise<GarbageCollectionProgress> {
    let job = initialJob;
    for (;;) {
      if (job.discovery !== undefined && job.discovery.phase !== "complete") {
        for (
          let page = 0;
          page < GARBAGE_COLLECTION_DISCOVERY_PAGES_PER_STEP &&
          job.discovery !== undefined &&
          job.discovery.phase !== "complete";
          page += 1
        ) {
          job = await this.#advanceGarbageCollectionPlanning(job);
        }
        if (job.discovery !== undefined && job.discovery.phase !== "complete") {
          return garbageCollectionProgress(job);
        }
      }
      if (job.state === "completed") {
        await this.store.removePrunedManifestRecords(MAINTENANCE_JOB_PAGE_SIZE);
        return garbageCollectionProgress(job);
      }
      try {
        const step = await this.store.runGarbageCollectionStep({
          jobId: job.id,
          expectedRevision: job.revision,
          maxItems,
          updatedAt: dateIsoString(this.#now()),
        });
        if (step.job.state === "completed") {
          await this.store.removePrunedManifestRecords(MAINTENANCE_JOB_PAGE_SIZE);
        }
        return garbageCollectionProgress(step.job);
      } catch (error) {
        if (!(error instanceof GarbageCollectionJobConflictError)) throw error;
        const latest = await this.store.getGarbageCollectionJob(job.id);
        if (latest === undefined)
          throw new Error(`Garbage collection job not found: ${job.id}`, { cause: error });
        job = latest;
      }
    }
  }

  async #planCompaction(
    table: TableRecord,
    options: CompactTableOptions,
  ): Promise<CompactionJobRecord | CompactTableResult> {
    for (;;) {
      const version = await this.store.getCurrentManifestVersion();
      try {
        return await this.#withLeasedSnapshot(version, (snapshot) =>
          this.#planCompactionAtSnapshot(table, options, version, snapshot),
        );
      } catch (error) {
        if (error instanceof SnapshotManifestMissingError) continue;
        throw error;
      }
    }
  }

  async #planCompactionAtSnapshot(
    table: TableRecord,
    options: CompactTableOptions,
    version: number | null,
    snapshot: LeasedSnapshot,
  ): Promise<CompactionJobRecord | CompactTableResult> {
    const minimumLevel0Segments = positiveWholeNumber(
      options.minimumLevel0Segments ?? DEFAULT_COMPACTION_MINIMUM_LEVEL_ZERO_SEGMENTS,
      "Compaction minimum L0 segments",
    );
    const maxLevel0Segments = positiveWholeNumber(
      options.maxLevel0Segments ?? DEFAULT_COMPACTION_MAXIMUM_LEVEL_ZERO_SEGMENTS,
      "Compaction maximum L0 segments",
    );
    if (maxLevel0Segments < minimumLevel0Segments) {
      throw new RangeError("Compaction maximum L0 segments cannot be smaller than its minimum");
    }
    const maxLevel0StoredBytes = positiveWholeNumber(
      options.maxLevel0StoredBytes ?? DEFAULT_COMPACTION_MAXIMUM_LEVEL_ZERO_STORED_BYTES,
      "Compaction maximum L0 stored bytes",
    );
    const visibleSegments = await this.#visibleSegmentRecords(table, snapshot);
    const visibleBlockIds = uniqueSegmentBlockIds(visibleSegments);
    const inferredLevelTwoLayout = appendLevelTwoLayout(visibleSegments);
    const inferredTargetLevel =
      inferredLevelTwoLayout !== null && inferredLevelTwoLayout.levelTwoSegments.length > 0 ? 2 : 1;
    const targetLevel = positiveWholeNumber(
      options.targetLevel ?? inferredTargetLevel,
      "Compaction target level",
    );
    if (targetLevel !== 1 && targetLevel !== 2) {
      throw new RangeError("Compaction target level must be 1 or 2");
    }
    if (targetLevel === 1 && options.maxWriteAmplification !== undefined) {
      throw new RangeError("Compaction write amplification is only supported for L2 output");
    }
    const levelTwoMaxWriteAmplification =
      targetLevel === 2
        ? positiveFiniteNumber(
            options.maxWriteAmplification ?? DEFAULT_LEVEL_TWO_MAX_WRITE_AMPLIFICATION,
            "Compaction maximum write amplification",
          )
        : undefined;

    const targetBlockBytes = positiveWholeNumber(
      options.targetBlockBytes ?? DEFAULT_COMPACTION_TARGET_BLOCK_BYTES,
      "Compaction target block bytes",
    );
    if (targetBlockBytes > MAX_COMPACTION_TARGET_BLOCK_BYTES) {
      throw new RangeError(
        `Compaction target block bytes cannot exceed ${String(MAX_COMPACTION_TARGET_BLOCK_BYTES)}`,
      );
    }
    const outputCompression = validateCompression(
      options.outputCompression ?? "gzip",
      "Compaction output compression",
    );
    if (
      getCompressionMemoryBound(outputCompression, targetBlockBytes).maximumOutputBytes >
      MAX_COMPACTION_TARGET_BLOCK_BYTES
    ) {
      throw new RangeError(
        `Compaction target block bytes exceed the ${outputCompression} worst-case format limit`,
      );
    }
    const memoryBudgetBytes = positiveWholeNumber(
      options.memoryBudgetBytes ?? DEFAULT_COMPACTION_MEMORY_BUDGET_BYTES,
      "Compaction memory budget",
    );
    const partitionRows = positiveWholeNumber(
      options.partitionRows ?? this.#compactionPartitionRows,
      "Compaction partition rows",
    );

    let anchors: readonly SegmentRecord[] = [];
    let level0Segments: readonly SegmentRecord[];
    let effectiveMinimumLevel0Segments: number;
    let outputPartitionOrdinal: number | undefined;
    let keyedLevelTwo = false;
    let keyedLevelOne: KeyedLevelOneLayout | undefined;
    let keylessLevelOne: KeyedLevelOneLayout | undefined;
    if (targetLevel === 1 && table.uniqueKeyColumnId !== undefined) {
      // Keyed L1: a prefix of level-one partitions, then level-zero history. A fold rewrites
      // only the partitions the selected deltas touch (and the tail partition new rows join),
      // so which partitions it sources is decided after the level-zero selection below.
      const layout = keyedLevelOneLayout(visibleSegments);
      if (layout === null) {
        return compactTableSkipped(
          table.name,
          "unsupported-level-layout",
          visibleSegments,
          visibleBlockIds,
          version,
        );
      }
      keyedLevelOne = layout;
      level0Segments = layout.level0Segments;
      effectiveMinimumLevel0Segments =
        layout.partitions.length > 0 ? minimumLevel0Segments : Math.max(2, minimumLevel0Segments);
    } else if (targetLevel === 1) {
      const layout = keylessLevelOneLayout(visibleSegments);
      if (layout === null) {
        return compactTableSkipped(
          table.name,
          "unsupported-level-layout",
          visibleSegments,
          visibleBlockIds,
          version,
        );
      }
      keylessLevelOne = layout;
      level0Segments = layout.level0Segments;
      effectiveMinimumLevel0Segments =
        layout.partitions.length > 0 ? minimumLevel0Segments : Math.max(2, minimumLevel0Segments);
    } else if (
      table.uniqueKeyColumnId !== undefined ||
      visibleSegments.some(
        (segment) => segment.kind !== "insert" || segment.rowIdSpans.length !== 0,
      )
    ) {
      // Keyed multi-range L2: merge (the level-one partitions + oldest level-zero prefix) into
      // a new span-carrying partition. Published partitions are never rewritten; mutation
      // kinds without a unique key cannot merge and keep the materialized skip.
      if (table.uniqueKeyColumnId === undefined) {
        return compactTableSkipped(
          table.name,
          "contains-mutation-segments",
          visibleSegments,
          visibleBlockIds,
          version,
        );
      }
      const layout = keyedLevelTwoLayout(visibleSegments);
      if (layout === null) {
        return compactTableSkipped(
          table.name,
          "unsupported-level-layout",
          visibleSegments,
          visibleBlockIds,
          version,
        );
      }
      anchors = layout.anchors;
      level0Segments = layout.level0Segments;
      effectiveMinimumLevel0Segments = minimumLevel0Segments;
      outputPartitionOrdinal = layout.levelTwoSegments.length;
      keyedLevelTwo = true;
    } else {
      const layout = appendLevelTwoLayout(visibleSegments);
      if (layout === null) {
        return compactTableSkipped(
          table.name,
          "unsupported-level-layout",
          visibleSegments,
          visibleBlockIds,
          version,
        );
      }
      level0Segments = layout.level0Segments;
      effectiveMinimumLevel0Segments = minimumLevel0Segments;
      outputPartitionOrdinal = layout.levelTwoSegments.length;
    }
    if (level0Segments.length < effectiveMinimumLevel0Segments) {
      return compactTableSkipped(
        table.name,
        "below-segment-threshold",
        visibleSegments,
        visibleBlockIds,
        version,
      );
    }
    if (version === null) throw new Error("Visible compaction segments require a manifest");
    const level0Selection = await this.#selectLevelZeroSources(
      level0Segments,
      effectiveMinimumLevel0Segments,
      maxLevel0Segments,
      maxLevel0StoredBytes,
      snapshot,
    );
    let partitioning: KeyedPartitioning | undefined;
    let rechunkPartitioning: RechunkPartitioning | undefined;
    if (keyedLevelOne !== undefined) {
      const keyColumn = getUniqueKeyColumn(table);
      if (keyColumn === undefined) {
        throw new Error(`Mutation compaction requires a unique key: ${table.name}`);
      }
      const touched = await this.#touchedPartitionIds(
        keyColumn,
        keyedLevelOne.partitions,
        level0Selection.segments,
        memoryBudgetBytes,
        snapshot,
      );
      // New rows join the last partition while it is small, or when it is being rewritten
      // anyway; otherwise they open a new partition behind it and it stays untouched.
      const last = keyedLevelOne.partitions[keyedLevelOne.partitions.length - 1];
      const bearsNewRows = level0Selection.segments.some((segment) =>
        mergeSourceBearsRows(segment.kind),
      );
      const absorbsTail =
        last !== undefined &&
        bearsNewRows &&
        (touched.has(last.id) || last.rowCount < partitionRows);
      anchors = keyedLevelOne.partitions.filter(
        (partition) =>
          partition.rowCount > partitionRows ||
          touched.has(partition.id) ||
          (absorbsTail && partition.id === last.id),
      );
      partitioning = {
        partitions: keyedLevelOne.partitions,
        partitionRows,
        absorbsTail,
        nextLevelZeroOrder:
          level0Selection.nextLogicalOrder ??
          safeWholeNumberSum([version, 1], "Compaction successor logical order"),
      };
    } else if (keylessLevelOne !== undefined) {
      const last = keylessLevelOne.partitions.at(-1);
      // A partial tail is extended. A pre-existing oversized anchor is included once so this fold
      // heals it into bounded partitions; a full tail stays immutable and new rows start after it.
      const absorbsTail =
        last !== undefined && (last.rowCount < partitionRows || last.rowCount > partitionRows);
      anchors = absorbsTail ? [last] : [];
      rechunkPartitioning = {
        partitionRows,
        nextLevelZeroOrder:
          level0Selection.nextLogicalOrder ??
          safeWholeNumberSum([version, 1], "Compaction successor logical order"),
      };
    }
    const anchorMeasurement = await this.#measureCompactionSources(
      anchors,
      level0Selection.blockIds,
      snapshot,
    );
    const selection = {
      sourceSegments: [...anchors, ...level0Selection.segments],
      level0SourceStoredBytes: level0Selection.storedBytes,
      anchorSourceStoredBytes: anchorMeasurement.storedBytes,
    };
    const sourceSegments = selection.sourceSegments;
    const sourceBlockIds = uniqueSegmentBlockIds(sourceSegments);
    const hasContiguousSourceRowIds = hasContiguousRowIds(sourceSegments);
    const hasPositiveSourceRowIds = (sourceSegments[0]?.rowIdStart ?? 0n) > 0n;
    // A keyed fold always merges: one uniform partition shape (a full-row base with row-ID
    // spans, bounded by `partitionRows`) regardless of whether the selected prefix happens to
    // be pure inserts.
    const requiresMerge =
      keyedLevelTwo || keyedLevelOne !== undefined
        ? true
        : targetLevel === 1 &&
          sourceSegments.some(
            (segment) => segment.kind !== "insert" || segment.rowIdSpans.length !== 0,
          );
    if (
      !requiresMerge &&
      (!hasContiguousSourceRowIds || (targetLevel === 2 && !hasPositiveSourceRowIds))
    ) {
      return compactTableSkipped(
        table.name,
        "non-contiguous-row-ids",
        sourceSegments,
        sourceBlockIds,
        version,
      );
    }

    let mergePlan: MergeCompactionRewritePlan | undefined;
    if (requiresMerge) {
      try {
        mergePlan = await this.#createMergeCompactionPlan(
          table,
          sourceSegments,
          targetBlockBytes,
          outputCompression,
          memoryBudgetBytes,
          snapshot,
          partitioning,
        );
      } catch (error) {
        // A keyed L2 prefix whose mutations reference keys living in already-published
        // partitions cannot fold them without rewriting those partitions (key-range rewrite
        // remains future work); those deltas stay as replayable level-zero history.
        if (keyedLevelTwo && errorMessage(error).includes("references a missing key")) {
          return compactTableSkipped(
            table.name,
            "keys-outside-selected-sources",
            sourceSegments,
            sourceBlockIds,
            version,
          );
        }
        throw error;
      }
    }
    const rewritePlan =
      mergePlan ??
      (await this.#createRechunkCompactionPlan(
        table,
        sourceSegments,
        targetBlockBytes,
        outputCompression,
        memoryBudgetBytes,
        snapshot,
        rechunkPartitioning,
      ));
    const minimumMemoryBytes = compactionMinimumMemoryBytes(rewritePlan);
    if (minimumMemoryBytes > memoryBudgetBytes) {
      throw new CompactionMemoryBudgetError(memoryBudgetBytes, minimumMemoryBytes);
    }
    const sourceStoredBytes = physicalRewriteSourceStoredBytes(rewritePlan);
    if (
      selection.anchorSourceStoredBytes + selection.level0SourceStoredBytes !==
      sourceStoredBytes
    ) {
      throw new Error("Compaction source byte accounting differs from its rewrite plan");
    }

    const baseJobId = ["compaction", table.id, "manifest", String(version)].join("/");
    let levelTwoBudget:
      | {
          outputPartitionOrdinal: number;
          maxWriteAmplification: number;
          maximumOutputStoredBytes: number;
          plannedOutputStoredBytesUpperBound: number;
          priorAttemptOutputStoredBytes: number;
        }
      | undefined;
    if (targetLevel === 2) {
      if (outputPartitionOrdinal === undefined) {
        throw new Error("L2 compaction requires an append-only or merged physical rewrite");
      }
      const maxWriteAmplification = levelTwoMaxWriteAmplification;
      if (maxWriteAmplification === undefined) {
        throw new Error("L2 compaction write-amplification policy is missing");
      }
      // Attempts at promoting the same sources share one lifetime ceiling: bytes a cancelled
      // or aborted attempt already wrote for this manifest version reduce what the next
      // attempt may spend, so repeated failures cannot multiply the physical write budget.
      const priorAttemptOutputStoredBytes = await this.#priorCompactionAttemptOutputStoredBytes(
        table.id,
        baseJobId,
      );
      const maximumOutputStoredBytes = Math.max(
        0,
        floorWholeNumberProduct(
          selection.level0SourceStoredBytes,
          maxWriteAmplification,
          "Compaction maximum output stored bytes",
        ) - priorAttemptOutputStoredBytes,
      );
      const plannedOutputStoredBytesUpperBound =
        await this.#plannedPhysicalOutputStoredBytesUpperBound(
          rewritePlan,
          memoryBudgetBytes,
          snapshot,
        );
      levelTwoBudget = {
        outputPartitionOrdinal,
        maxWriteAmplification,
        maximumOutputStoredBytes,
        plannedOutputStoredBytesUpperBound,
        priorAttemptOutputStoredBytes,
      };
      if (plannedOutputStoredBytesUpperBound > maximumOutputStoredBytes) {
        return compactionWriteAmplificationSkipped({
          tableName: table.name,
          sourceSegments,
          sourceBlockIds,
          sourceStoredBytes,
          level0SourceStoredBytes: selection.level0SourceStoredBytes,
          outputPartitionOrdinal,
          maxWriteAmplification,
          maximumOutputStoredBytes,
          plannedOutputStoredBytesUpperBound,
          priorAttemptOutputStoredBytes,
          targetBlockBytes,
          outputCompression,
          memoryBudgetBytes,
          minimumMemoryBytes,
          version,
        });
      }
    }

    let id = baseJobId;
    const existing = await this.store.getCompactionJob(id);
    if (existing !== undefined && existing.state !== "aborted" && existing.state !== "cancelled") {
      return existing;
    }
    if (existing !== undefined) id = `${id}/retry/${this.#createId()}`;
    const timestamp = dateIsoString(this.#now());
    const job: CompactionJobRecord = {
      id,
      tableId: table.id,
      sourceManifestVersion: version,
      sourceSegmentIds: sourceSegments.map((segment) => segment.id),
      sourceBlockIds,
      outputBlockIds: [],
      cursor: { sourceSegmentIndex: 0, sourceBlockIndex: 0 },
      processedRows: 0,
      sourceStoredBytes,
      level0SourceStoredBytes: selection.level0SourceStoredBytes,
      anchorSourceStoredBytes: selection.anchorSourceStoredBytes,
      outputStoredBytes: 0,
      logicalBytes: physicalRewriteSourceEncodedBytes(rewritePlan),
      rewritePlan,
      outputCursor: {
        outputIndex: 0,
        columnIndex: 0,
        rowStart: rewritePlan.outputs[0]?.rowStart ?? 0,
      },
      memoryBudgetBytes,
      minimumMemoryBytes,
      ...(levelTwoBudget ?? {}),
      peakWorkingBytes: 0,
      outputLogicalBytes: 0,
      targetLevel,
      state: "planned",
      transactionId: null,
      outputSegmentId:
        rewritePlan.kind === "merge-v1" && rewritePlan.totalRows === 0
          ? null
          : `${id}/output-segment`,
      publishedVersion: null,
      revision: 0,
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    await snapshot.renew(INTERNAL_READ_LEASE_TTL_MS);
    try {
      await this.store.createCompactionJob(job);
      return job;
    } catch (error) {
      const raced = await this.store.getCompactionJob(id);
      if (raced !== undefined) return raced;
      if (error instanceof CompactionJobConflictError) {
        const active = await this.#findActiveCompactionJob(table.id);
        if (active !== undefined) return active;
      }
      throw error;
    }
  }

  async #priorCompactionAttemptOutputStoredBytes(
    tableId: string,
    baseJobId: string,
  ): Promise<number> {
    let largest = 0;
    let cursor: string | null = null;
    do {
      const page = await this.store.listCompactionJobPage(cursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const candidate of page.records) {
        if (
          candidate.tableId !== tableId ||
          (candidate.state !== "cancelled" && candidate.state !== "aborted") ||
          (candidate.id !== baseJobId && !candidate.id.startsWith(`${baseJobId}/retry/`))
        ) {
          continue;
        }
        largest = Math.max(
          largest,
          safeWholeNumberSum(
            [candidate.priorAttemptOutputStoredBytes ?? 0, candidate.outputStoredBytes],
            "Compaction prior-attempt output stored bytes",
          ),
        );
      }
      cursor = page.nextCursor;
      if (cursor !== null) await this.#yieldMaintenance();
    } while (cursor !== null);
    return largest;
  }

  /**
   * Sums the stored bytes of the given segments' blocks, refusing a block that appears twice
   * among them or in `seenBlockIds` — a source block may only be superseded once.
   */
  async #measureCompactionSources(
    segments: readonly SegmentRecord[],
    seenBlockIds: ReadonlySet<string>,
    snapshot: LeasedSnapshot,
  ): Promise<{ storedBytes: number; blockIds: string[] }> {
    let total = 0;
    const blockIds: string[] = [];
    const measuredBlockIds = new Set<string>();
    for (const segment of segments) {
      for (const blockId of Object.values(segment.columnBlockIds).flat()) {
        if (seenBlockIds.has(blockId) || measuredBlockIds.has(blockId)) {
          throw new Error(`Compaction source block is referenced more than once: ${blockId}`);
        }
        measuredBlockIds.add(blockId);
        blockIds.push(blockId);
        await this.#renewInternalLeaseIfNeeded(snapshot);
        const bytes = await this.store.getBlock(blockId);
        if (bytes === undefined) throw new Error(`Compaction source block is missing: ${blockId}`);
        total = safeWholeNumberSum([total, bytes.byteLength], "Compaction selected stored bytes");
      }
    }
    return { storedBytes: total, blockIds };
  }

  /**
   * The oldest level-zero prefix one job promotes: whole equal-order groups, at least the
   * minimum, and past it no more than the segment and stored-byte ceilings allow. Also reports
   * the order of the first segment left behind, which bounds the orders a fold may publish.
   */
  async #selectLevelZeroSources(
    level0Segments: readonly SegmentRecord[],
    minimumLevel0Segments: number,
    maxLevel0Segments: number,
    maxLevel0StoredBytes: number,
    snapshot: LeasedSnapshot,
  ): Promise<{
    segments: SegmentRecord[];
    storedBytes: number;
    blockIds: Set<string>;
    nextLogicalOrder: number | null;
  }> {
    const transactions = new Map(
      (await this.#transactionRecordsForSegments(level0Segments)).map((record) => [
        record.id,
        record,
      ]),
    );
    const logicalOrder = (segment: SegmentRecord): number => {
      const owner = transactions.get(segment.transactionId);
      if (owner?.status !== "committed" || owner.committedVersion === null) {
        throw new Error(`Compaction source segment has no committed owner: ${segment.id}`);
      }
      return segment.logicalOrder;
    };
    const seenBlockIds = new Set<string>();
    const selected: SegmentRecord[] = [];
    let storedBytes = 0;
    let start = 0;
    while (start < level0Segments.length) {
      const first = level0Segments[start];
      if (first === undefined) throw new Error("Compaction L0 source selection is unavailable");
      const order = logicalOrder(first);
      let end = start + 1;
      for (;;) {
        const next = level0Segments[end];
        if (next === undefined || logicalOrder(next) !== order) break;
        end += 1;
      }
      const group = level0Segments.slice(start, end);
      if (
        selected.length >= minimumLevel0Segments &&
        selected.length + group.length > maxLevel0Segments
      ) {
        break;
      }
      const measurement = await this.#measureCompactionSources(group, seenBlockIds, snapshot);
      if (
        selected.length >= minimumLevel0Segments &&
        measurement.storedBytes > maxLevel0StoredBytes - storedBytes
      ) {
        break;
      }
      measurement.blockIds.forEach((blockId) => seenBlockIds.add(blockId));
      selected.push(...group);
      storedBytes = safeWholeNumberSum(
        [storedBytes, measurement.storedBytes],
        "Compaction selected L0 stored bytes",
      );
      start = end;
    }
    if (selected.length < minimumLevel0Segments) {
      throw new Error("Compaction source selection did not satisfy its minimum L0 segment count");
    }
    const next = level0Segments[start];
    return {
      segments: selected,
      storedBytes,
      blockIds: seenBlockIds,
      nextLogicalOrder: next === undefined ? null : logicalOrder(next),
    };
  }

  /**
   * Which level-one partitions the selected deltas reach into: those holding a key that some
   * delete, update, or upsert among them names. Inserts and upserts of new keys touch nothing;
   * their rows join the tail. Key blocks whose zone map rules every referenced key out are
   * skipped from the header, so a sorted key costs one decoded block per partition at most and
   * usually none; the referenced-key set is the same size the merge planner's is.
   */
  async #touchedPartitionIds(
    keyColumn: TableColumnRecord,
    partitions: readonly SegmentRecord[],
    level0Segments: readonly SegmentRecord[],
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
  ): Promise<Set<string>> {
    const touched = new Set<string>();
    if (partitions.length === 0) return touched;
    const deltas = level0Segments.filter((segment) => mergeSourceReferencesKeys(segment.kind));
    if (deltas.length === 0) return touched;
    const referencedBytes = safeWholeNumberProduct(
      deltas.reduce((total, segment) => total + segment.rowCount, 0),
      MERGE_PLANNER_KEY_BYTES,
      "Compaction referenced keys",
    );
    if (referencedBytes > memoryBudgetBytes) {
      throw new CompactionMemoryBudgetError(memoryBudgetBytes, referencedBytes);
    }
    const referenced = new Set<OverlayKey>();
    for (const segment of deltas) {
      await this.#forEachSegmentKey(segment, keyColumn, snapshot, (value) => {
        referenced.add(overlayKeyOf(keyColumn.type, value));
      });
    }
    const predicate = touchedKeyPredicate(keyColumn, referenced);
    const descriptions =
      predicate === undefined
        ? new Map<string, ReturnType<typeof inspectBlock>>()
        : await this.#zoneDescriptions(
            partitions.flatMap((partition) => partition.columnBlockIds[keyColumn.id] ?? []),
            snapshot,
          );
    for (const partition of partitions) {
      const blockIds = partition.columnBlockIds[keyColumn.id] ?? [];
      if (blockIds.length === 0) {
        throw new Error(`Partition has no key column blocks: ${partition.id}`);
      }
      for (const blockId of blockIds) {
        const description = descriptions.get(blockId);
        if (
          predicate !== undefined &&
          description !== undefined &&
          !zoneMapCanMatch(description, predicate)
        ) {
          continue;
        }
        await this.#renewInternalLeaseIfNeeded(snapshot);
        const bytes = await this.store.getBlock(blockId);
        if (bytes === undefined) throw new Error(`Compaction source block is missing: ${blockId}`);
        const decoded = await decodeBlock(bytes);
        if (decoded.column.type !== keyColumn.type) {
          throw new Error(`Compaction source block differs from table schema: ${blockId}`);
        }
        if (
          decoded.column.values.some((value) => referenced.has(overlayKeyOf(keyColumn.type, value)))
        ) {
          touched.add(partition.id);
          break;
        }
      }
    }
    return touched;
  }

  /** Decodes a segment's key column in row order, one block resident at a time. */
  async #forEachSegmentKey(
    segment: SegmentRecord,
    keyColumn: TableColumnRecord,
    snapshot: LeasedSnapshot,
    action: (value: BatchValue, rowIndex: number) => void,
  ): Promise<void> {
    let rowIndex = 0;
    for (const blockId of segment.columnBlockIds[keyColumn.id] ?? []) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const bytes = await this.store.getBlock(blockId);
      if (bytes === undefined) throw new Error(`Compaction source block is missing: ${blockId}`);
      const decoded = await decodeBlock(bytes);
      if (decoded.column.type !== keyColumn.type) {
        throw new Error(`Compaction source block differs from table schema: ${blockId}`);
      }
      for (const value of decoded.column.values) {
        action(value, rowIndex);
        rowIndex += 1;
      }
    }
    if (rowIndex !== segment.rowCount) {
      throw new Error(`Mutation segment key rows differ: ${segment.id}`);
    }
  }

  async #createRechunkCompactionPlan(
    table: TableRecord,
    sourceSegments: readonly SegmentRecord[],
    targetBlockBytes: number,
    outputCompression: Compression,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
    partitioning?: RechunkPartitioning,
  ): Promise<RechunkCompactionRewritePlan> {
    const first = sourceSegments[0];
    const last = sourceSegments[sourceSegments.length - 1];
    if (first === undefined || last === undefined) {
      throw new Error("Compaction needs at least one source segment");
    }
    const totalRows = safeWholeNumberSum(
      sourceSegments.map((segment) => segment.rowCount),
      "Compaction source row count",
    );
    const columns: RechunkCompactionSourceColumn[] = [];
    let maximumEncodedBytesPerRow = 0;

    for (const column of table.columns) {
      const sourceBlocks: RechunkCompactionSourceBlock[] = [];
      let rowStart = 0;
      for (const segment of sourceSegments) {
        const segmentStart = rowStart;
        const blockIds = segment.columnBlockIds[column.id] ?? [];
        if (blockIds.length === 0) {
          throw new Error(`Compaction source column is missing blocks: ${column.name}`);
        }
        for (const blockId of blockIds) {
          await this.#renewInternalLeaseIfNeeded(snapshot);
          const bytes = await this.store.getBlock(blockId);
          if (bytes === undefined)
            throw new Error(`Compaction source block is missing: ${blockId}`);
          const description = inspectBlock(bytes);
          if (description.type !== column.type) {
            throw new Error(`Compaction source block type differs: ${blockId}`);
          }
          if (description.rowCount === 0) {
            throw new Error(`Compaction source block is empty: ${blockId}`);
          }
          sourceBlocks.push({
            blockId,
            rowStart,
            rowCount: description.rowCount,
            storedBytes: bytes.byteLength,
            encodedBytes: description.encodedLength,
            checksum: description.checksum,
          });
          maximumEncodedBytesPerRow = Math.max(
            maximumEncodedBytesPerRow,
            description.encodedLength / description.rowCount,
          );
          rowStart = safeWholeNumberSum(
            [rowStart, description.rowCount],
            "Compaction source block rows",
          );
        }
        if (rowStart - segmentStart !== segment.rowCount) {
          throw new Error(`Compaction source blocks do not cover segment ${segment.id}`);
        }
      }
      if (rowStart !== totalRows) {
        throw new Error(`Compaction source column does not cover every row: ${column.name}`);
      }
      columns.push({ columnId: column.id, type: column.type, sourceBlocks });
    }

    if (!Number.isFinite(maximumEncodedBytesPerRow) || maximumEncodedBytesPerRow <= 0) {
      throw new Error("Compaction could not estimate an output block size");
    }
    const rowsPerOutput = estimateCompactionRowsPerOutput(
      targetBlockBytes,
      maximumEncodedBytesPerRow,
    );
    const logicalOrder = this.#firstLogicalOrder(sourceSegments);
    const partitions =
      partitioning === undefined
        ? undefined
        : planLinearOutputPartitions(
            totalRows,
            partitioning.partitionRows,
            logicalOrder,
            partitioning.nextLevelZeroOrder,
          );
    const estimatedOutputs: RechunkCompactionOutputWindow[] = [];
    const outputRegions = partitions ?? [{ rowStart: 0, rowCount: totalRows }];
    for (const region of outputRegions) {
      const regionEnd = region.rowStart + region.rowCount;
      for (let rowStart = region.rowStart; rowStart < regionEnd; rowStart += rowsPerOutput) {
        estimatedOutputs.push({
          rowStart,
          rowCount: Math.min(rowsPerOutput, regionEnd - rowStart),
        });
      }
    }
    const outputs = await this.#refinePhysicalOutputWindows(
      rechunkPhysicalColumns(columns),
      estimatedOutputs,
      targetBlockBytes,
      outputCompression,
      memoryBudgetBytes,
      snapshot,
    );

    return {
      kind: "rechunk-v1",
      targetBlockBytes,
      outputCompression,
      totalRows,
      rowIdStart: first.rowIdStart,
      rowIdEndExclusive: last.rowIdEndExclusive,
      logicalOrder,
      columns,
      outputs,
      ...(partitions === undefined ? {} : { partitions }),
    };
  }

  /**
   * Plans a merge of the sources into one canonical output. With `partitioning`, the output
   * is also cut into level-one partitions: each rewritten source partition keeps its rows (and
   * its logical order) in place, new rows form the tail, and every run is chunked to at most
   * `partitionRows`, using fractional orders between unchanged neighbours.
   */
  async #createMergeCompactionPlan(
    table: TableRecord,
    sourceSegments: readonly SegmentRecord[],
    targetBlockBytes: number,
    outputCompression: Compression,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
    partitioning?: KeyedPartitioning,
  ): Promise<MergeCompactionRewritePlan> {
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) {
      throw new Error(`Mutation compaction requires a unique key: ${table.name}`);
    }
    const transactions = new Map(
      (await this.#transactionRecordsForSegments(sourceSegments)).map((record) => [
        record.id,
        record,
      ]),
    );
    const describedSegments: MergeCompactionSourceSegment[] = [];
    const sourceBlocksById = new Map<string, MergeCompactionSourceBlock>();

    for (const segment of sourceSegments) {
      const transaction = transactions.get(segment.transactionId);
      if (transaction?.status !== "committed" || transaction.committedVersion === null) {
        throw new Error(`Compaction source segment has no committed owner: ${segment.id}`);
      }
      const kind = segment.kind;
      const keyColumnId = segment.keyColumnId ?? table.uniqueKeyColumnId ?? null;
      if (keyColumnId !== keyColumn.id) {
        throw new Error(`Compaction source key differs from the table key: ${segment.id}`);
      }
      const unknownColumnId = Object.keys(segment.columnBlockIds).find(
        (columnId) => !table.columns.some((column) => column.id === columnId),
      );
      if (unknownColumnId !== undefined) {
        throw new Error(`Compaction source contains an unknown column: ${unknownColumnId}`);
      }
      const columns: MergeCompactionSourceColumn[] = [];
      for (const column of table.columns) {
        const blockIds = segment.columnBlockIds[column.id] ?? [];
        if (blockIds.length === 0) continue;
        const sourceBlocks: MergeCompactionSourceBlock[] = [];
        let rowStart = 0;
        for (const blockId of blockIds) {
          await this.#renewInternalLeaseIfNeeded(snapshot);
          const bytes = await this.store.getBlock(blockId);
          if (bytes === undefined) {
            throw new Error(`Compaction source block is missing: ${blockId}`);
          }
          const description = inspectBlock(bytes);
          if (description.type !== column.type || description.rowCount === 0) {
            throw new Error(`Compaction source block differs from table schema: ${blockId}`);
          }
          if (sourceBlocksById.has(blockId)) {
            throw new Error(`Compaction source block is referenced more than once: ${blockId}`);
          }
          const sourceBlock: MergeCompactionSourceBlock = {
            blockId,
            rowStart,
            rowCount: description.rowCount,
            storedBytes: bytes.byteLength,
            encodedBytes: description.encodedLength,
            checksum: description.checksum,
          };
          sourceBlocks.push(sourceBlock);
          sourceBlocksById.set(blockId, sourceBlock);
          rowStart = safeWholeNumberSum(
            [rowStart, description.rowCount],
            "Mutation compaction source rows",
          );
        }
        if (rowStart !== segment.rowCount) {
          throw new Error(`Compaction source blocks do not cover segment ${segment.id}`);
        }
        columns.push({ columnId: column.id, type: column.type, sourceBlocks });
      }
      validateMergeSegmentShape(table, segment.id, kind, columns, keyColumn.id);
      describedSegments.push({
        segmentId: segment.id,
        transactionId: segment.transactionId,
        committedVersion: transaction.committedVersion,
        kind,
        keyColumnId,
        level: segment.level,
        logicalOrder: segment.logicalOrder,
        rowCount: segment.rowCount,
        rowIdStart: segment.rowIdStart,
        rowIdEndExclusive: segment.rowIdEndExclusive,
        rowIdSpans: mergeSourceRowIdSpans(segment, kind),
        columns,
      });
    }

    assertCanonicalMergeSourceOrder(describedSegments);
    const resolved = await this.#resolveMergeOutput(
      table,
      describedSegments,
      keyColumn,
      memoryBudgetBytes,
      snapshot,
    );
    const { columns, rowIdSpans, totalRows } = resolved;
    const rowIdEnvelope = rowIdSpanEnvelope(rowIdSpans);
    const partitions =
      partitioning === undefined
        ? undefined
        : planOutputPartitions(
            partitioning,
            describedSegments,
            resolved.sourceOutputRowStarts,
            totalRows,
          );
    let outputs: RechunkCompactionOutputWindow[] = [];
    if (totalRows > 0) {
      let maximumEncodedBytesPerRow = 0;
      for (const column of columns) {
        for (const range of column.sourceRanges) {
          const source = sourceBlocksById.get(range.sourceBlockId);
          if (source === undefined) {
            throw new Error(
              `Mutation compaction source fingerprint is missing: ${range.sourceBlockId}`,
            );
          }
          maximumEncodedBytesPerRow = Math.max(
            maximumEncodedBytesPerRow,
            source.encodedBytes / source.rowCount,
          );
        }
      }
      if (!Number.isFinite(maximumEncodedBytesPerRow) || maximumEncodedBytesPerRow <= 0) {
        throw new Error("Compaction could not estimate an output block size");
      }
      const rowsPerOutput = estimateCompactionRowsPerOutput(
        targetBlockBytes,
        maximumEncodedBytesPerRow,
      );
      // Windows never straddle a partition: each partition's blocks are its own.
      const estimatedOutputs: RechunkCompactionOutputWindow[] = [];
      for (const region of partitions ?? [{ rowStart: 0, rowCount: totalRows }]) {
        const regionEnd = region.rowStart + region.rowCount;
        for (let rowStart = region.rowStart; rowStart < regionEnd; rowStart += rowsPerOutput) {
          estimatedOutputs.push({
            rowStart,
            rowCount: Math.min(rowsPerOutput, regionEnd - rowStart),
          });
        }
      }
      outputs = await this.#refinePhysicalOutputWindows(
        mergePhysicalColumns(columns, describedSegments),
        estimatedOutputs,
        targetBlockBytes,
        outputCompression,
        memoryBudgetBytes,
        snapshot,
      );
    }

    return {
      kind: "merge-v1",
      targetBlockBytes,
      outputCompression,
      keyColumnId: keyColumn.id,
      totalRows,
      rowIdStart: rowIdEnvelope.start,
      rowIdEndExclusive: rowIdEnvelope.endExclusive,
      rowIdSpans,
      logicalOrder: Math.min(...describedSegments.map((segment) => segment.logicalOrder)),
      sourceSegments: describedSegments,
      columns,
      outputs,
      ...(partitions === undefined ? {} : { partitions }),
    };
  }

  /**
   * Replays the source segments' mutations into one canonical output order, in memory that
   * scales with the deltas rather than with the table.
   *
   * Every row of every row-bearing source (base, insert, upsert) gets a slot, numbered in
   * canonical source order, and the output is the live slots in slot order. A row can only be
   * referenced later through its key, and only delete, update, and upsert sources reference
   * keys, so the first pass collects those keys — the touched set — and the replay then tracks
   * slots for touched keys alone. An untouched row can never be deleted, patched, or replaced:
   * it passes through as part of a run, one output range per source block rather than one per
   * row. Memory is O(delta rows + touched rows) plus two bytes per slot.
   *
   * The semantics are those of a per-row replay:
   * - delete: the key's live slot dies; a later insert of the key takes a new slot.
   * - update: the named columns of the key's live slot come from the update row; the key must
   *   be live.
   * - upsert: when the key is live, every column of that slot comes from the upsert row and the
   *   upsert row's own slot dies, so the row keeps its position and row ID; otherwise the
   *   upsert row is a new live row.
   * - insert/base: a new live row; a second live occurrence of a touched key is an error.
   */
  async #resolveMergeOutput(
    table: TableRecord,
    segments: readonly MergeCompactionSourceSegment[],
    keyColumn: TableColumnRecord,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
  ): Promise<{
    columns: MergeCompactionOutputColumn[];
    rowIdSpans: RowIdSpan[];
    totalRows: number;
    /** The output row at which each row-bearing source's surviving rows begin. */
    sourceOutputRowStarts: Map<string, number>;
  }> {
    const plannerMemoryBytes = mergePlannerMemoryBound(table, segments, keyColumn.id);
    if (plannerMemoryBytes > memoryBudgetBytes) {
      throw new CompactionMemoryBudgetError(memoryBudgetBytes, plannerMemoryBytes);
    }
    const columnIndexById = new Map(table.columns.map((column, index) => [column.id, index]));

    // Pass 1: the keys any delta references, and each delta's keys in row order. The deltas'
    // key blocks are decoded together: the bound above reserved decode scratch for them, and
    // whatever of the budget it left unused is theirs as well.
    const touched = new Set<OverlayKey>();
    const deltaKeys = new Map<string, OverlayKey[]>();
    const deltas = segments.filter((segment) => mergeSourceReferencesKeys(segment.kind));
    for (const segment of deltas) deltaKeys.set(segment.segmentId, []);
    const unusedBudgetBytes = memoryBudgetBytes - plannerMemoryBytes;
    await this.#forEachMergeSourceKey(
      deltas,
      keyColumn,
      unusedBudgetBytes,
      snapshot,
      (segment, value) => {
        const key = overlayKeyOf(keyColumn.type, value);
        deltaKeys.get(segment.segmentId)?.push(key);
        touched.add(key);
      },
    );

    // Pass 2: replay into slot state.
    let slotCount = 0;
    for (const segment of segments) {
      if (mergeSourceBearsRows(segment.kind)) slotCount += segment.rowCount;
    }
    const dead = new Uint8Array(slotCount);
    const patched = new Uint8Array(slotCount);
    const patches = new Map<number, Array<MergeResolvedSource | undefined>>();
    const liveSlotByKey = new Map<OverlayKey, number>();
    let slotBase = 0;
    for (const segment of segments) {
      if (segment.kind === "delete") {
        for (const key of deltaKeys.get(segment.segmentId) ?? []) {
          const slot = liveSlotByKey.get(key);
          if (slot === undefined) continue;
          dead[slot] = 1;
          patched[slot] = 0;
          patches.delete(slot);
          liveSlotByKey.delete(key);
        }
        continue;
      }
      if (segment.kind === "update") {
        const changedColumns = segment.columns
          .map((column) => column.columnId)
          .filter((columnId) => columnId !== keyColumn.id)
          .map((columnId) => {
            const columnIndex = columnIndexById.get(columnId);
            if (columnIndex === undefined) {
              throw new Error(`Mutation compaction column is missing: ${columnId}`);
            }
            return { columnId, columnIndex };
          });
        const keys = deltaKeys.get(segment.segmentId) ?? [];
        for (let rowIndex = 0; rowIndex < keys.length; rowIndex += 1) {
          const key = keys[rowIndex];
          const slot = key === undefined ? undefined : liveSlotByKey.get(key);
          if (slot === undefined) {
            throw new Error(`Update segment references a missing key: ${segment.segmentId}`);
          }
          let patch = patches.get(slot);
          if (patch === undefined) {
            patch = new Array<MergeResolvedSource | undefined>(table.columns.length).fill(
              undefined,
            );
            patches.set(slot, patch);
            patched[slot] = 1;
          }
          for (const { columnId, columnIndex } of changedColumns) {
            patch[columnIndex] = mergeSourceAt(segment, columnId, rowIndex);
          }
        }
        continue;
      }
      // A row-bearing source: base, insert, or upsert.
      const base = slotBase;
      const visit = (key: OverlayKey, rowIndex: number): void => {
        if (!touched.has(key)) return;
        const slot = base + rowIndex;
        const existing = liveSlotByKey.get(key);
        if (existing === undefined) {
          liveSlotByKey.set(key, slot);
          return;
        }
        if (segment.kind !== "upsert") {
          throw new Error(`Insert segment contains a duplicate unique key: ${segment.segmentId}`);
        }
        patches.set(
          existing,
          table.columns.map((column) => mergeSourceAt(segment, column.id, rowIndex)),
        );
        patched[existing] = 1;
        dead[slot] = 1;
      };
      const keys = deltaKeys.get(segment.segmentId);
      if (keys !== undefined) {
        keys.forEach(visit);
      } else if (touched.size > 0) {
        // With nothing referencing keys there is nothing to track: every row passes through.
        await this.#forEachMergeSourceKey(
          [segment],
          keyColumn,
          unusedBudgetBytes,
          snapshot,
          (_, value, rowIndex) => {
            visit(overlayKeyOf(keyColumn.type, value), rowIndex);
          },
        );
      }
      slotBase += segment.rowCount;
    }
    touched.clear();
    liveSlotByKey.clear();
    deltaKeys.clear();

    // Pass 3: the live slots in slot order, as runs wherever nothing touched them.
    const output = new MergeOutputBuilder(table.columns);
    const sourceOutputRowStarts = new Map<string, number>();
    slotBase = 0;
    for (const segment of segments) {
      if (!mergeSourceBearsRows(segment.kind)) continue;
      sourceOutputRowStarts.set(segment.segmentId, output.totalRows);
      let runStart = -1;
      for (let rowIndex = 0; rowIndex < segment.rowCount; rowIndex += 1) {
        const slot = slotBase + rowIndex;
        if (dead[slot] === 1 || patched[slot] === 1) {
          if (runStart >= 0) {
            output.appendRun(segment, runStart, rowIndex - runStart);
            runStart = -1;
          }
          if (patched[slot] === 1) output.appendPatchedRow(segment, rowIndex, patches.get(slot));
          continue;
        }
        if (runStart < 0) runStart = rowIndex;
      }
      if (runStart >= 0) output.appendRun(segment, runStart, segment.rowCount - runStart);
      slotBase += segment.rowCount;
    }
    return { ...output.finish(), sourceOutputRowStarts };
  }

  /**
   * Streams the key column of each segment to `action`, in segment order and row order. The
   * key blocks are read and decoded in groups (#decodeCompactionBlocks) within the decode
   * scratch the merge planner's bound reserved — a multiple of the largest key block — plus
   * whatever of the fold's memory budget that bound left unused; a decoded block is dropped
   * once its keys are handed over, so nothing accumulates across groups.
   */
  async #forEachMergeSourceKey(
    segments: readonly MergeCompactionSourceSegment[],
    column: TableColumnRecord,
    unusedBudgetBytes: number,
    snapshot: LeasedSnapshot,
    action: (segment: MergeCompactionSourceSegment, value: BatchValue, rowIndex: number) => void,
  ): Promise<void> {
    const blocks: Array<
      CompactionSourceBlockRef & {
        readonly segment: MergeCompactionSourceSegment;
        readonly source: MergeCompactionSourceBlock;
      }
    > = [];
    let largestEncodedBytes = 0;
    for (const segment of segments) {
      const planned = segment.columns.find((candidate) => candidate.columnId === column.id);
      if (planned === undefined) {
        throw new Error(`Mutation segment has no key column: ${segment.segmentId}`);
      }
      for (const source of planned.sourceBlocks) {
        blocks.push({
          blockId: source.blockId,
          storedBytes: source.storedBytes,
          encodedBytes: source.encodedBytes,
          segment,
          source,
        });
        largestEncodedBytes = Math.max(largestEncodedBytes, source.encodedBytes);
      }
    }
    const limitBytes = safeWholeNumberSum(
      [
        Math.max(0, unusedBudgetBytes),
        safeWholeNumberProduct(
          largestEncodedBytes,
          MERGE_PLANNER_DECODED_KEY_BLOCK_FACTOR,
          "Mutation compaction key decode memory",
        ),
      ],
      "Mutation compaction key decode memory",
    );
    const rowIndexes = new Map<string, number>();
    await this.#decodeCompactionBlocks(
      blocks,
      { limitBytes, retainsDecoded: false },
      snapshot,
      async (bytes, { source }) => {
        const description = inspectBlock(bytes);
        if (
          bytes.byteLength !== source.storedBytes ||
          description.encodedLength !== source.encodedBytes ||
          description.checksum !== source.checksum ||
          description.rowCount !== source.rowCount ||
          description.type !== column.type
        ) {
          throw new Error(`Compaction source block differs from its plan: ${source.blockId}`);
        }
        return (await decodeBlock(bytes)).column.values;
      },
      (values, { segment }) => {
        let rowIndex = rowIndexes.get(segment.segmentId) ?? 0;
        for (const value of values) {
          action(segment, value, rowIndex);
          rowIndex += 1;
        }
        rowIndexes.set(segment.segmentId, rowIndex);
      },
    );
    for (const segment of segments) {
      if ((rowIndexes.get(segment.segmentId) ?? 0) !== segment.rowCount) {
        throw new Error(`Mutation segment key rows differ: ${segment.segmentId}`);
      }
    }
  }

  async #refinePhysicalOutputWindows(
    columns: readonly PhysicalCompactionSourceColumn[],
    estimatedOutputs: readonly RechunkCompactionOutputWindow[],
    targetBlockBytes: number,
    outputCompression: Compression,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
  ): Promise<RechunkCompactionOutputWindow[]> {
    const outputs: RechunkCompactionOutputWindow[] = [];
    for (const output of estimatedOutputs) {
      outputs.push(
        ...(await this.#refinePhysicalOutputWindow(
          columns,
          output,
          targetBlockBytes,
          outputCompression,
          memoryBudgetBytes,
          snapshot,
        )),
      );
    }
    return outputs;
  }

  async #refinePhysicalOutputWindow(
    columns: readonly PhysicalCompactionSourceColumn[],
    output: RechunkCompactionOutputWindow,
    targetBlockBytes: number,
    outputCompression: Compression,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
  ): Promise<RechunkCompactionOutputWindow[]> {
    let splitReason: "target" | "format" | "memory" | null = null;
    const requiredMemoryBytes = Math.max(
      ...columns.map((column) => physicalOutputMemoryBound(column, output, outputCompression)),
    );
    if (requiredMemoryBytes > memoryBudgetBytes) {
      splitReason = "memory";
    } else {
      for (const column of columns) {
        let encodedByteLength: number;
        try {
          encodedByteLength = (
            await this.#measurePhysicalCompactionOutput(
              column,
              output,
              outputCompression,
              memoryBudgetBytes,
              snapshot,
            )
          ).encodedByteLength;
        } catch (error) {
          if (!isPhysicalColumnLimitError(error)) throw error;
          splitReason = "format";
          break;
        }
        if (
          getCompressionMemoryBound(outputCompression, encodedByteLength).maximumOutputBytes >
          MAX_COMPACTION_TARGET_BLOCK_BYTES
        ) {
          splitReason = "format";
          break;
        }
        if (encodedByteLength > targetBlockBytes) {
          splitReason = "target";
        }
      }
    }
    if (splitReason === null || (splitReason === "target" && output.rowCount === 1)) {
      return [output];
    }
    if (output.rowCount === 1) {
      if (splitReason === "memory") {
        throw new CompactionMemoryBudgetError(memoryBudgetBytes, requiredMemoryBytes);
      }
      throw new RangeError(
        `A single compaction row exceeds the ${outputCompression} block format limit`,
      );
    }

    const leftRowCount = Math.floor(output.rowCount / 2);
    const left = { rowStart: output.rowStart, rowCount: leftRowCount };
    const right = {
      rowStart: safeWholeNumberSum(
        [output.rowStart, leftRowCount],
        "Compaction split output row start",
      ),
      rowCount: output.rowCount - leftRowCount,
    };
    return [
      ...(await this.#refinePhysicalOutputWindow(
        columns,
        left,
        targetBlockBytes,
        outputCompression,
        memoryBudgetBytes,
        snapshot,
      )),
      ...(await this.#refinePhysicalOutputWindow(
        columns,
        right,
        targetBlockBytes,
        outputCompression,
        memoryBudgetBytes,
        snapshot,
      )),
    ];
  }

  async #measurePhysicalCompactionOutput(
    column: PhysicalCompactionSourceColumn,
    output: RechunkCompactionOutputWindow,
    outputCompression: Compression,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
  ) {
    const loaded = await this.#loadPhysicalCompactionRanges(
      column,
      output,
      outputCompression,
      memoryBudgetBytes,
      snapshot,
    );
    return measurePhysicalColumnRanges(column.type, loaded.ranges);
  }

  async #plannedPhysicalOutputStoredBytesUpperBound(
    plan: PhysicalCompactionRewritePlan,
    memoryBudgetBytes: number,
    snapshot: LeasedSnapshot,
  ): Promise<number> {
    const layout = physicalRewriteLayout(plan);
    let total = 0;
    for (const output of layout.outputs) {
      for (const column of layout.columns) {
        const measurement = await this.#measurePhysicalCompactionOutput(
          column,
          output,
          plan.outputCompression,
          memoryBudgetBytes,
          snapshot,
        );
        total = safeWholeNumberSum(
          [
            total,
            maximumPhysicalBlockByteLength(
              measurement.encodedByteLength,
              measurement.metadata,
              plan.outputCompression,
            ),
          ],
          "Compaction planned output stored-byte upper bound",
        );
      }
    }
    return total;
  }

  async #runCompactionJob(
    table: TableRecord,
    initialJob: CompactionJobRecord,
    maxBlocks: number,
  ): Promise<CompactionJobProgress> {
    let job = (await this.store.getCompactionJob(initialJob.id)) ?? initialJob;
    if (job.state === "cancelled") throw new CompactionJobCancelledError(job.id);
    if (job.state === "aborted") throw new Error(job.error ?? `Compaction job aborted: ${job.id}`);
    if (job.state === "published") {
      return this.#publishedCompactionProgress(table, job);
    }
    let linkedTransaction =
      job.transactionId === null ? undefined : await this.store.getTransaction(job.transactionId);
    if (
      job.transactionId !== null &&
      linkedTransaction?.status === "active" &&
      Date.parse(linkedTransaction.expiresAt) <= dateMilliseconds(this.#now())
    ) {
      // An owner past its lease is dead whoever held it — a closed tab, or this database's own
      // fold parked on a starved event loop. The store will not renew it, so resuming it fails
      // every step; and at the level-zero ceiling every write takes a step. Abort it here and
      // begin again below rather than wait for the background reconciler's retry timer.
      const cutoff = dateIsoString(this.#now());
      await this.store.abortTransactionIfExpired({
        transactionId: linkedTransaction.id,
        expectedOwnerId: linkedTransaction.ownerId,
        expiresAtCutoff: cutoff,
        updatedAt: cutoff,
      });
      linkedTransaction = await this.store.getTransaction(job.transactionId);
    }
    if (linkedTransaction?.status === "committed" && linkedTransaction.committedVersion !== null) {
      job = await this.#markCompactionPublished(job, linkedTransaction.committedVersion);
      const recoveredManifest = await this.store.getManifest(linkedTransaction.committedVersion);
      if (recoveredManifest === undefined) {
        throw new Error(
          `Compaction manifest is missing: ${String(linkedTransaction.committedVersion)}`,
        );
      }
      this.#afterCompactionCommit(recoveredManifest, table.id);
      return this.#publishedCompactionProgress(table, job);
    }
    const rewritePlan = job.rewritePlan;
    if (rewritePlan.kind !== "copy-v1") validatePhysicalTablePlan(table, rewritePlan);
    const sourceSegments =
      rewritePlan.kind === "copy-v1" ? await this.#loadCompactionSources(job) : [];

    let transaction: DatabaseTransaction;
    try {
      if (job.transactionId === null) {
        const linked = await this.#beginCompactionTransaction(job);
        if (linked.transaction === null) {
          return await this.#runCompactionJob(table, linked.job, maxBlocks);
        }
        ({ job, transaction } = linked);
      } else {
        if (linkedTransaction?.status !== "active") {
          const linked = await this.#beginCompactionTransaction(job);
          if (linked.transaction === null) {
            return await this.#runCompactionJob(table, linked.job, maxBlocks);
          }
          ({ job, transaction } = linked);
        } else {
          transaction = await this.#transactions.resume(job.transactionId);
          if (job.state !== "running") {
            job = await this.store.updateCompactionJob(job.id, job.revision, {
              state: "running",
              updatedAt: dateIsoString(this.#now()),
              error: null,
            });
          }
        }
      }
    } catch (error) {
      if ((await this.store.getCompactionJob(job.id))?.state === "cancelled") {
        throw new CompactionJobCancelledError(job.id);
      }
      throw error;
    }

    // Recovery may need to atomically adopt the prior aborted attempt's exact output segment
    // before this replacement reaches publication. Bind the replacement transaction to the
    // durable job as soon as it is acquired; delaying until commit leaves adoption unable to
    // prove which compaction authorized the journal transfer.
    transaction.setCompactionIntent(job.id, job.sourceBlockIds);

    try {
      if (job.outputBlockIds.length > 0) {
        const pendingBlockIds = new Set(transaction.pendingBlockIds);
        const unjournaledOutputIds = job.outputBlockIds.filter((id) => !pendingBlockIds.has(id));
        if (unjournaledOutputIds.length > 0) {
          await transaction.stageExistingBlocks(unjournaledOutputIds);
        }
      }
      if (rewritePlan.kind !== "copy-v1") {
        job = await this.#advancePhysicalCompaction(job, transaction, rewritePlan, maxBlocks);
        if ((job.outputCursor?.outputIndex ?? 0) < rewritePlan.outputs.length) {
          return compactionProgress(table.name, job, null);
        }
      } else {
        let processedBlocks = 0;
        while (
          job.cursor.sourceSegmentIndex < sourceSegments.length &&
          processedBlocks < maxBlocks
        ) {
          const segmentIndex = job.cursor.sourceSegmentIndex;
          const segment = sourceSegments[segmentIndex];
          if (segment === undefined) throw new Error("Compaction source cursor is invalid");
          const entries = compactionBlockEntries(table, segment, segmentIndex, job.id);
          const entry = entries[job.cursor.sourceBlockIndex];
          if (entry === undefined) {
            job = await this.store.updateCompactionJob(job.id, job.revision, {
              cursor: { sourceSegmentIndex: segmentIndex + 1, sourceBlockIndex: 0 },
              processedRows: job.processedRows + segment.rowCount,
              updatedAt: dateIsoString(this.#now()),
            });
            continue;
          }

          const source = await this.store.getBlock(entry.sourceBlockId);
          if (source === undefined) {
            throw new Error(`A compaction source block is missing: ${entry.sourceBlockId}`);
          }
          const existing = await this.store.getBlock(entry.outputBlockId);
          if (existing === undefined) {
            await transaction.stageBlock(entry.outputBlockId, source);
          } else {
            if (!sameBytes(existing, source)) {
              throw new Error(`A resumed compaction block differs: ${entry.outputBlockId}`);
            }
            await transaction.stageExistingBlocks([entry.outputBlockId]);
          }

          const segmentComplete = job.cursor.sourceBlockIndex + 1 === entries.length;
          const description = inspectBlock(source);
          job = await this.store.updateCompactionJob(job.id, job.revision, {
            outputBlockIds: [...job.outputBlockIds, entry.outputBlockId],
            cursor: segmentComplete
              ? { sourceSegmentIndex: segmentIndex + 1, sourceBlockIndex: 0 }
              : {
                  sourceSegmentIndex: segmentIndex,
                  sourceBlockIndex: job.cursor.sourceBlockIndex + 1,
                },
            processedRows: job.processedRows + (segmentComplete ? segment.rowCount : 0),
            sourceStoredBytes: job.sourceStoredBytes + source.byteLength,
            outputStoredBytes: job.outputStoredBytes + source.byteLength,
            logicalBytes: job.logicalBytes + description.encodedLength,
            updatedAt: dateIsoString(this.#now()),
            error: null,
          });
          processedBlocks += 1;
        }

        if (job.cursor.sourceSegmentIndex < sourceSegments.length) {
          return compactionProgress(table.name, job, null);
        }
      }

      const expectedOutputIds =
        rewritePlan.kind !== "copy-v1"
          ? physicalOutputBlockIds(job.id, rewritePlan)
          : sourceSegments.flatMap((segment, segmentIndex) =>
              compactionBlockEntries(table, segment, segmentIndex, job.id).map(
                (entry) => entry.outputBlockId,
              ),
            );
      const pendingOutputIds = new Set(transaction.pendingBlockIds);
      const unjournaledOutputId = expectedOutputIds.find((id) => !pendingOutputIds.has(id));
      if (unjournaledOutputId !== undefined) {
        throw new Error(`Compaction output block was not journaled: ${unjournaledOutputId}`);
      }
      const outputSegmentId = job.outputSegmentId;
      const first = sourceSegments[0];
      const last = sourceSegments[sourceSegments.length - 1];
      if (rewritePlan.kind === "copy-v1" && (first === undefined || last === undefined)) {
        throw new Error("Compaction sources disappeared");
      }
      const outputRowCount =
        rewritePlan.kind === "copy-v1"
          ? sourceSegments.reduce((total, segment) => total + segment.rowCount, 0)
          : rewritePlan.totalRows;
      if (outputRowCount === 0) {
        if (outputSegmentId !== null) {
          throw new Error("An empty compaction cannot have an output segment");
        }
      } else {
        if (outputSegmentId === null) throw new Error("Compaction output segment ID is missing");
        const createdAt = dateIsoString(this.#now());
        const desiredOutputSegments: SegmentRecord[] =
          rewritePlan.kind === "copy-v1"
            ? [
                {
                  id: outputSegmentId,
                  tableId: table.id,
                  transactionId: transaction.id,
                  rowCount: outputRowCount,
                  rowIdStart: first?.rowIdStart ?? 0n,
                  rowIdEndExclusive: last?.rowIdEndExclusive ?? 0n,
                  columnBlockIds: compactionOutputColumns(table, sourceSegments, job.id),
                  kind: "insert",
                  ...(table.uniqueKeyColumnId === undefined
                    ? {}
                    : { keyColumnId: table.uniqueKeyColumnId }),
                  level: job.targetLevel,
                  ...(job.outputPartitionOrdinal === undefined
                    ? {}
                    : { partitionOrdinal: job.outputPartitionOrdinal }),
                  logicalOrder: this.#firstLogicalOrder(sourceSegments),
                  commitOrdinal: 0,
                  rowIdSpans: [],
                  createdAt,
                },
              ]
            : compactionOutputSegments(table, job, rewritePlan, transaction.id, createdAt);
        for (const desiredOutputSegment of desiredOutputSegments) {
          await this.#stageCompactionOutputSegment(
            transaction,
            desiredOutputSegment,
            expectedOutputIds,
          );
        }
      }
      if (job.state !== "ready") {
        job = await this.store.updateCompactionJob(job.id, job.revision, {
          outputBlockIds: expectedOutputIds,
          state: "ready",
          updatedAt: dateIsoString(this.#now()),
          error: null,
        });
      }

      transaction.setCompactionIntent(job.id, job.sourceBlockIds);
      transaction.markLogicallyUnchanged();
      let publicationConflict: WriteConflictError | undefined;
      const publish = async (): Promise<ManifestSummary | undefined> => {
        try {
          const manifest = await transaction.commit();
          this.#afterCompactionCommit(manifest, table.id);
          return manifest;
        } catch (error) {
          if (!(error instanceof WriteConflictError)) throw error;
          publicationConflict = error;
          return undefined;
        }
      };
      // Publication is logically neutral, so it may follow any number of concurrent data
      // commits while every source remains visible and in the same logical position.
      const rebaseOverConcurrentCommits = async (): Promise<void> => {
        const currentVersion = await this.store.getCurrentManifestVersion();
        const sourcePresence = await this.#manifestBlockPresence(
          currentVersion,
          job.sourceBlockIds,
        );
        if (sourcePresence.some((present) => !present)) {
          if (transaction.status === "active") await transaction.abort();
          job = await this.#abortCompactionJob(
            job,
            "Compaction sources changed before publication",
          );
          throw new Error(job.error, { cause: publicationConflict });
        }
        const rebased = await transaction.rebase();
        try {
          await this.#assertCompactionSnapshotOrder(job, rebased);
        } catch (error) {
          if (transaction.status === "active") await transaction.abort();
          job = await this.#abortCompactionJob(job, errorMessage(error));
          throw new Error(job.error, { cause: error });
        }
        const missingSourceId = await firstMissingSnapshotBlock(rebased, job.sourceBlockIds);
        if (missingSourceId !== undefined) {
          if (transaction.status === "active") await transaction.abort();
          job = await this.#abortCompactionJob(
            job,
            `Compaction source is no longer visible: ${missingSourceId}`,
          );
          throw new Error(job.error, { cause: publicationConflict });
        }
        transaction.setCompactionIntent(job.id, job.sourceBlockIds);
        transaction.markLogicallyUnchanged();
      };
      let manifest = await publish();
      if (manifest === undefined) {
        // A retry on this fold's own turn is not sufficient: this database's writers win the
        // manifest CAS again between rebase and commit, every time, leaving a complete job in
        // `ready` while the table grows. So the rebase and the commit take a turn as a writer
        // (#withCompactionPublicationSlot), and inside that turn they retry without yielding:
        // what can still commit in between is a writer already in flight — a pipelined scope,
        // another tab — and those are finite, where a fold that yielded between attempts met
        // a fresh one each time. Past the limit the job is abandoned and the next check plans
        // a fresh one.
        manifest = await this.#withCompactionPublicationSlot(async () => {
          for (
            let conflicts = 1;
            conflicts <= MAX_COMPACTION_PUBLICATION_CONFLICTS;
            conflicts += 1
          ) {
            await rebaseOverConcurrentCommits();
            const published = await publish();
            if (published !== undefined) return published;
          }
          return undefined;
        });
        if (manifest === undefined) {
          if (transaction.status === "active") await transaction.abort();
          job = await this.#abortCompactionJob(
            job,
            `Compaction publication lost ${String(MAX_COMPACTION_PUBLICATION_CONFLICTS + 1)} manifest races`,
          );
          throw new Error(job.error, { cause: publicationConflict });
        }
      }
      job = await this.#markCompactionPublished(job, manifest.version);
      return compactionProgress(
        table.name,
        job,
        this.#compactionResult(table, job, manifest.version),
      );
    } catch (error) {
      const latest = await this.store.getCompactionJob(job.id);
      if (latest?.state === "cancelled") {
        throw new CompactionJobCancelledError(job.id);
      }
      if (error instanceof CompactionWriteAmplificationError) {
        if (transaction.status === "active") await transaction.abort();
        if (latest !== undefined && latest.state !== "published" && latest.state !== "aborted") {
          try {
            await this.#abortCompactionJob(latest, error.message);
          } catch (updateError) {
            if (!(updateError instanceof CompactionJobConflictError)) throw updateError;
          }
        }
        throw error;
      }
      if (
        !(error instanceof CompactionJobConflictError) &&
        !(error instanceof TransactionRecordConflictError) &&
        latest?.revision === job.revision &&
        latest.state !== "published" &&
        latest.state !== "aborted"
      ) {
        try {
          await this.store.updateCompactionJob(latest.id, latest.revision, {
            updatedAt: dateIsoString(this.#now()),
            error: errorMessage(error),
          });
        } catch {
          // Another coordinator advanced the same persisted job.
        }
      }
      throw error;
    }
  }

  async #advancePhysicalCompaction(
    initialJob: CompactionJobRecord,
    transaction: DatabaseTransaction,
    plan: PhysicalCompactionRewritePlan,
    maxBlocks: number,
  ): Promise<CompactionJobRecord> {
    const layout = physicalRewriteLayout(plan);
    let job = initialJob;
    let processedBlocks = 0;
    while ((job.outputCursor?.outputIndex ?? 0) < layout.outputs.length) {
      if (processedBlocks >= maxBlocks) break;
      const cursor = job.outputCursor;
      if (cursor === null) {
        throw new Error("Physical compaction cursor is missing");
      }
      const output = layout.outputs[cursor.outputIndex];
      const column = layout.columns[cursor.columnIndex];
      if (output === undefined || column === undefined) {
        throw new Error("Physical compaction cursor is invalid");
      }
      const outputBlockId = physicalOutputBlockId(job.id, cursor.outputIndex, cursor.columnIndex);
      const built = await this.#buildPhysicalCompactionOutput(
        layout,
        column,
        output,
        job.memoryBudgetBytes,
      );
      const existing = await this.store.getBlock(outputBlockId);
      let outputBytes: Uint8Array;
      if (existing === undefined) {
        outputBytes = await this.#encodePreferredBlock(
          column.columnId,
          plan.outputCompression,
          built.physical.bytes.byteLength < GZIP_MINIMUM_INPUT_BYTES,
          (compression) => encodePhysicalBlock(built.physical, compression),
        );
      } else {
        const decoded = await decodePhysicalBlock(existing);
        if (
          decoded.description.type !== column.type ||
          (plan.outputCompression === "raw" && decoded.description.compression !== "raw") ||
          decoded.description.rowCount !== output.rowCount ||
          !sameBytes(decoded.column.bytes, built.physical.bytes)
        ) {
          throw new Error(`A resumed compaction block differs: ${outputBlockId}`);
        }
        outputBytes = existing;
      }
      const nextOutputStoredBytes = safeWholeNumberSum(
        [job.outputStoredBytes, outputBytes.byteLength],
        "Compaction output stored bytes",
      );
      const maximumOutputStoredBytes = job.maximumOutputStoredBytes;
      const plannedOutputStoredBytesUpperBound = job.plannedOutputStoredBytesUpperBound;
      if (
        (maximumOutputStoredBytes !== undefined &&
          nextOutputStoredBytes > maximumOutputStoredBytes) ||
        (plannedOutputStoredBytesUpperBound !== undefined &&
          nextOutputStoredBytes > plannedOutputStoredBytesUpperBound)
      ) {
        throw new CompactionWriteAmplificationError(
          nextOutputStoredBytes,
          Math.min(
            maximumOutputStoredBytes ?? Number.MAX_SAFE_INTEGER,
            plannedOutputStoredBytesUpperBound ?? Number.MAX_SAFE_INTEGER,
          ),
        );
      }
      if (existing === undefined) await transaction.stageBlock(outputBlockId, outputBytes);
      else await transaction.stageExistingBlocks([outputBlockId]);
      const description = inspectBlock(outputBytes);
      const nextColumnIndex = cursor.columnIndex + 1;
      const nextOutputIndex =
        nextColumnIndex === layout.columns.length ? cursor.outputIndex + 1 : cursor.outputIndex;
      const canonicalColumnIndex = nextColumnIndex === layout.columns.length ? 0 : nextColumnIndex;
      const nextRowStart =
        nextOutputIndex === layout.outputs.length
          ? layout.totalRows
          : (layout.outputs[nextOutputIndex]?.rowStart ?? output.rowStart);
      job = await this.store.updateCompactionJob(job.id, job.revision, {
        outputBlockIds: [...job.outputBlockIds, outputBlockId],
        outputCursor: {
          outputIndex: nextOutputIndex,
          columnIndex: canonicalColumnIndex,
          rowStart: nextRowStart,
        },
        processedRows: nextRowStart,
        outputStoredBytes: nextOutputStoredBytes,
        outputLogicalBytes: safeWholeNumberSum(
          [job.outputLogicalBytes, description.encodedLength],
          "Compaction output logical bytes",
        ),
        peakWorkingBytes: Math.max(job.peakWorkingBytes, built.peakWorkingBytes),
        updatedAt: dateIsoString(this.#now()),
        error: null,
      });
      processedBlocks += 1;
    }
    return job;
  }

  async #buildPhysicalCompactionOutput(
    plan: PhysicalCompactionLayout,
    column: PhysicalCompactionSourceColumn,
    output: RechunkCompactionOutputWindow,
    memoryBudgetBytes: number,
  ): Promise<{ physical: ValidatedPhysicalColumn; peakWorkingBytes: number }> {
    const loaded = await this.#loadPhysicalCompactionRanges(
      column,
      output,
      plan.outputCompression,
      memoryBudgetBytes,
    );
    const measurement = measurePhysicalColumnRanges(column.type, loaded.ranges);
    if (measurement.rowCount !== output.rowCount) {
      throw new Error("Compaction source ranges do not cover the planned output");
    }
    const physical = buildPhysicalColumnFromRanges(column.type, loaded.ranges);
    return { physical, peakWorkingBytes: loaded.peakWorkingBytes };
  }

  /**
   * The decoded source slices one output block of one column is built from. Every distinct
   * source block is read and decoded once, however many runs of the output it feeds — a
   * partition's block feeds one run per patched row between its rows — and the distinct blocks
   * are decoded in groups (#decodeCompactionBlocks) within the fold's memory budget, of which
   * the plan reserved `physicalOutputMemoryBound` for this output.
   */
  async #loadPhysicalCompactionRanges(
    column: PhysicalCompactionSourceColumn,
    output: RechunkCompactionOutputWindow,
    outputCompression: Compression,
    memoryBudgetBytes: number,
    snapshot?: LeasedSnapshot,
  ): Promise<{ ranges: PhysicalColumnRange[]; peakWorkingBytes: number }> {
    const memoryBound = physicalOutputMemoryBound(column, output, outputCompression);
    if (memoryBound > memoryBudgetBytes) {
      throw new CompactionMemoryBudgetError(memoryBudgetBytes, memoryBound);
    }
    const outputEnd = safeWholeNumberSum(
      [output.rowStart, output.rowCount],
      "Compaction output row range",
    );
    const sourceBlocks = overlappingPhysicalSourceRanges(column, output);
    const distinct: PhysicalCompactionSourceRange[] = [];
    const seen = new Set<string>();
    for (const sourceBlock of sourceBlocks) {
      if (seen.has(sourceBlock.blockId)) continue;
      seen.add(sourceBlock.blockId);
      distinct.push(sourceBlock);
    }
    const decoded = new Map<string, DecodedPhysicalBlock>();
    const peakWorkingBytes = await this.#decodeCompactionBlocks(
      distinct,
      { limitBytes: memoryBudgetBytes, retainsDecoded: true },
      snapshot,
      async (bytes, sourceBlock) => {
        const description = inspectBlock(bytes);
        if (
          bytes.byteLength !== sourceBlock.storedBytes ||
          description.encodedLength !== sourceBlock.encodedBytes ||
          description.checksum !== sourceBlock.checksum ||
          description.rowCount !== sourceBlock.sourceBlockRowCount ||
          description.type !== column.type
        ) {
          throw new Error(
            `A compaction source block differs from its plan: ${sourceBlock.blockId}`,
          );
        }
        return decodePhysicalBlock(bytes);
      },
      (block, sourceBlock) => {
        decoded.set(sourceBlock.blockId, block);
      },
    );
    const ranges: PhysicalColumnRange[] = [];
    for (const sourceBlock of sourceBlocks) {
      const block = decoded.get(sourceBlock.blockId);
      if (block === undefined) {
        throw new Error(`A compaction source block is missing: ${sourceBlock.blockId}`);
      }
      const sourceEnd = safeWholeNumberSum(
        [sourceBlock.outputRowStart, sourceBlock.rowCount],
        "Compaction source row range",
      );
      const start =
        sourceBlock.sourceRowStart +
        Math.max(output.rowStart, sourceBlock.outputRowStart) -
        sourceBlock.outputRowStart;
      const end =
        sourceBlock.sourceRowStart + Math.min(outputEnd, sourceEnd) - sourceBlock.outputRowStart;
      const slice = slicePhysicalColumn(block.column, start, end);
      ranges.push({ column: slice, start: 0, end: slice.rowCount });
    }
    return { ranges, peakWorkingBytes: Math.max(memoryBound, peakWorkingBytes) };
  }

  /**
   * Reads and decodes compaction source blocks in groups: one bulk read and one concurrent
   * decode per group, sized so that the group's modeled decode memory — twice the stored and
   * twice the encoded bytes of each block, as `physicalOutputMemoryBound` models a decode —
   * plus what earlier groups retained stays within `limitBytes`. `consume` sees every block in
   * the order given, whatever order the decodes complete in. Returns the modeled peak.
   *
   * A block decoded on its own costs one event-loop turn: decompression completes as a task,
   * not a microtask. Under a writer that never pauses, background maintenance gets one turn per
   * commit, so a fold that decoded its sources one after another advanced by one block per
   * statement while every statement added a level-zero segment, and a fold of a few thousand
   * reads fell further behind a loop of a few thousand statements until the ceiling refused
   * them. A group costs one turn however many blocks it holds.
   */
  async #decodeCompactionBlocks<B extends CompactionSourceBlockRef, T>(
    blocks: readonly B[],
    budget: { limitBytes: number; retainsDecoded: boolean },
    snapshot: LeasedSnapshot | undefined,
    decode: (bytes: Uint8Array, block: B) => Promise<T>,
    consume: (decoded: T, block: B) => void,
  ): Promise<number> {
    let retainedBytes = 0;
    let peakBytes = 0;
    let start = 0;
    while (start < blocks.length) {
      let end = start;
      let transientBytes = 0;
      let storedBytes = 0;
      for (; end < blocks.length && end - start < MAX_STORAGE_BULK_READ_ITEMS; end += 1) {
        const block = blocks[end];
        if (block === undefined) break;
        const blockTransientBytes = safeWholeNumberSum(
          [
            safeWholeNumberProduct(block.storedBytes, 2, "Compaction decode memory"),
            safeWholeNumberProduct(block.encodedBytes, 2, "Compaction decode memory"),
          ],
          "Compaction decode memory",
        );
        if (
          end > start &&
          (transientBytes + blockTransientBytes > budget.limitBytes - retainedBytes ||
            storedBytes + block.storedBytes > MAX_BLOCK_READ_BATCH_BYTES)
        ) {
          break;
        }
        transientBytes += blockTransientBytes;
        storedBytes += block.storedBytes;
      }
      const group = blocks.slice(start, end);
      if (snapshot !== undefined) await this.#renewInternalLeaseIfNeeded(snapshot);
      const bytes = await this.#readBlockWindow(group.map((block) => block.blockId));
      const decoded = await Promise.all(
        group.map((block, index) => {
          const stored = bytes[index];
          if (stored === undefined) {
            throw new Error(`A compaction source block is missing: ${block.blockId}`);
          }
          return decode(stored, block);
        }),
      );
      peakBytes = Math.max(peakBytes, retainedBytes + transientBytes);
      for (const [index, block] of group.entries()) {
        const value = decoded[index];
        if (value === undefined) throw new Error("Compaction decode lost a block");
        consume(value, block);
        if (budget.retainsDecoded) retainedBytes += block.encodedBytes;
      }
      start = end;
    }
    return peakBytes;
  }

  async #loadCompactionSources(job: CompactionJobRecord): Promise<SegmentRecord[]> {
    const segments = await Promise.all(job.sourceSegmentIds.map((id) => this.store.getSegment(id)));
    const missingIndex = segments.findIndex((segment) => segment === undefined);
    if (missingIndex >= 0) {
      throw new Error(
        `Compaction source segment is missing: ${job.sourceSegmentIds[missingIndex] ?? ""}`,
      );
    }
    return segments as SegmentRecord[];
  }

  async #assertCompactionSnapshotOrder(
    job: CompactionJobRecord,
    snapshot: Snapshot,
  ): Promise<void> {
    const plan = job.rewritePlan;
    const sourceIds = new Set(job.sourceSegmentIds);
    const tableSegments = await listTableSegmentsPaged(this.store, job.tableId);
    const visibleSegments = await filterSnapshotSegments(snapshot, tableSegments);
    const plannedSourceSegments = (
      await Promise.all(job.sourceSegmentIds.map((id) => this.store.getSegment(id)))
    ).filter((segment): segment is SegmentRecord => segment !== undefined);
    const transactions = new Map(
      (
        await this.#transactionRecordsForSegments([...visibleSegments, ...plannedSourceSegments])
      ).map((record) => [record.id, record]),
    );
    const sourceBlockIds = new Set(job.sourceBlockIds);
    let segmentCursor: string | null = null;
    do {
      const page = await this.store.listSegmentPage(segmentCursor, MAINTENANCE_JOB_PAGE_SIZE);
      for (const segment of page.records) {
        if (sourceIds.has(segment.id)) continue;
        if (
          Object.values(segment.columnBlockIds)
            .flat()
            .some((blockId) => sourceBlockIds.has(blockId))
        ) {
          throw new Error(`Concurrent segment shares a compaction source block: ${segment.id}`);
        }
      }
      segmentCursor = page.nextCursor;
      if (segmentCursor !== null) await this.#yieldMaintenance();
    } while (segmentCursor !== null);
    if (
      job.outputPartitionOrdinal === undefined &&
      job.targetLevel === 1 &&
      plan.kind !== "copy-v1" &&
      plan.partitions !== undefined
    ) {
      const table = await this.store.getTable(job.tableId);
      if (table === undefined) throw new Error(`Compaction table is missing: ${job.tableId}`);
      await this.#assertPartitionedLevelOneSnapshotOrder(
        job,
        plan,
        table,
        visibleSegments,
        transactions,
      );
      return;
    }
    if (job.outputPartitionOrdinal !== undefined) {
      if (plan.kind === "rechunk-v1") {
        await this.#assertLevelTwoSnapshotOrder(job, plan, snapshot, transactions);
        return;
      }
      if (plan.kind !== "merge-v1") {
        throw new Error("L2 compaction requires a rechunk or merge rewrite plan");
      }
      // A keyed multi-range promotion falls through to the merge-source and ordering checks
      // below; the retained partitions are validated against the planned ordinal there.
    }
    let latestSource: Pick<
      MergeCompactionSourceSegment,
      "logicalOrder" | "committedVersion" | "segmentId"
    > | null = null;
    let outputLogicalOrder: number | null = null;
    if (plan.kind === "merge-v1") {
      const visibleById = new Map(visibleSegments.map((segment) => [segment.id, segment]));
      for (const planned of plan.sourceSegments) {
        const actual = visibleById.get(planned.segmentId);
        if (actual === undefined) {
          throw new Error(`Compaction source is no longer visible: ${planned.segmentId}`);
        }
        const owner = transactions.get(actual.transactionId);
        if (!sameMergeSourceSegment(actual, owner, planned)) {
          throw new Error(`Compaction source segment differs from its plan: ${planned.segmentId}`);
        }
      }
      latestSource = plan.sourceSegments[plan.sourceSegments.length - 1] ?? null;
      outputLogicalOrder = plan.logicalOrder;
    } else {
      const sourceSegments = await this.#loadCompactionSources(job);
      for (const segment of sourceSegments) {
        const committedVersion = transactions.get(segment.transactionId)?.committedVersion;
        if (committedVersion === null || committedVersion === undefined) {
          throw new Error(`Compaction source segment has no committed owner: ${segment.id}`);
        }
        const tuple = {
          logicalOrder: segment.logicalOrder,
          committedVersion,
          segmentId: segment.id,
        };
        if (latestSource === null || compareMergeSourceOrder(latestSource, tuple) < 0) {
          latestSource = tuple;
        }
        outputLogicalOrder = Math.min(outputLogicalOrder ?? tuple.logicalOrder, tuple.logicalOrder);
      }
    }
    if (latestSource === null || outputLogicalOrder === null) {
      throw new Error("Compaction source order is unavailable");
    }
    const retainedPartitionOrdinals: number[] = [];
    for (const segment of visibleSegments) {
      if (sourceIds.has(segment.id)) continue;
      // A keyed L2 promotion retains the already-published partitions untouched; they precede
      // the merge sources by construction and are validated against the planned ordinal below.
      if (job.outputPartitionOrdinal !== undefined && segment.partitionOrdinal !== undefined) {
        retainedPartitionOrdinals.push(segment.partitionOrdinal);
        continue;
      }
      if (segment.level !== 0) {
        throw new Error(`Concurrent segment has an unsupported compaction level: ${segment.id}`);
      }
      const committedVersion = transactions.get(segment.transactionId)?.committedVersion;
      if (committedVersion === null || committedVersion === undefined) {
        throw new Error(`Concurrent compaction segment has no committed owner: ${segment.id}`);
      }
      const logicalOrder = segment.logicalOrder;
      if (
        logicalOrder <= outputLogicalOrder ||
        compareMergeSourceOrder(latestSource, {
          logicalOrder,
          committedVersion,
          segmentId: segment.id,
        }) >= 0
      ) {
        throw new Error(`Concurrent segment would reorder compaction output: ${segment.id}`);
      }
    }
    if (job.outputPartitionOrdinal !== undefined) {
      retainedPartitionOrdinals.sort((left, right) => left - right);
      if (
        retainedPartitionOrdinals.length !== job.outputPartitionOrdinal ||
        retainedPartitionOrdinals.some((ordinal, index) => ordinal !== index)
      ) {
        throw new Error("Concurrent segments violate the planned L2 layout");
      }
    }
  }

  /**
   * The partitioned level-one rebase rule, shared by keyed merges and keyless rechunks. The
   * sources must be exactly as planned. Every partition the plan left alone must still be visible
   * and unchanged — they are read back from the planning snapshot's manifest, which the job
   * roots until it ends, so the check needs no record of its own. Every other visible segment
   * must be level-zero history committed after the latest source and ordered after every
   * partition the job publishes, so the output slots into the same place relative to the deltas
   * it did not absorb.
   */
  async #assertPartitionedLevelOneSnapshotOrder(
    job: CompactionJobRecord,
    plan: PhysicalCompactionRewritePlan,
    table: TableRecord,
    visibleSegments: readonly SegmentRecord[],
    transactions: ReadonlyMap<string, { status: string; committedVersion: number | null }>,
  ): Promise<void> {
    const sourceIds = new Set(job.sourceSegmentIds);
    const visibleById = new Map(visibleSegments.map((segment) => [segment.id, segment]));
    const sourceManifest = await this.store.getManifest(job.sourceManifestVersion);
    if (sourceManifest === undefined || sourceManifest.prunedAt !== undefined) {
      throw new Error(
        `Compaction source manifest is unavailable: ${String(job.sourceManifestVersion)}`,
      );
    }
    const plannedVisible = await this.#visibleSegmentRecords(
      table,
      new Snapshot(this.store, sourceManifest.version),
    );
    const plannedById = new Map(plannedVisible.map((segment) => [segment.id, segment]));
    const plannedLayout =
      table.uniqueKeyColumnId === undefined
        ? keylessLevelOneLayout(plannedVisible)
        : keyedLevelOneLayout(plannedVisible);
    if (plannedLayout === null) throw new Error("Compaction planned layout is no longer valid");

    let latestSource: Pick<
      MergeCompactionSourceSegment,
      "logicalOrder" | "committedVersion" | "segmentId"
    > | null = null;
    if (plan.kind === "merge-v1") {
      for (const planned of plan.sourceSegments) {
        const actual = visibleById.get(planned.segmentId);
        if (actual === undefined) {
          throw new Error(`Compaction source is no longer visible: ${planned.segmentId}`);
        }
        const owner = transactions.get(actual.transactionId);
        if (!sameMergeSourceSegment(actual, owner, planned)) {
          throw new Error(`Compaction source segment differs from its plan: ${planned.segmentId}`);
        }
      }
      latestSource = plan.sourceSegments[plan.sourceSegments.length - 1] ?? null;
    } else {
      for (const id of job.sourceSegmentIds) {
        const actual = visibleById.get(id);
        const planned = plannedById.get(id);
        if (actual === undefined) throw new Error(`Compaction source is no longer visible: ${id}`);
        if (
          actual.transactionId !== planned?.transactionId ||
          !sameCompactionSegment(actual, planned)
        ) {
          throw new Error(`Compaction source segment differs from its plan: ${id}`);
        }
        const tuple = sourceOrderTuple(actual, transactions, "Compaction source");
        if (latestSource === null || compareMergeSourceOrder(latestSource, tuple) < 0) {
          latestSource = tuple;
        }
      }
    }
    if (latestSource === null) throw new Error("Compaction source order is unavailable");
    const maxOutputOrder =
      plan.partitions === undefined
        ? plan.logicalOrder
        : Math.max(
            plan.logicalOrder,
            ...plan.partitions.map((partition) => partition.logicalOrder),
          );
    const retained = new Map(
      plannedLayout.partitions
        .filter((partition) => !sourceIds.has(partition.id))
        .map((partition) => [partition.id, partition]),
    );
    for (const segment of visibleSegments) {
      if (sourceIds.has(segment.id)) continue;
      if (segment.level === 1) {
        const planned = retained.get(segment.id);
        if (
          planned?.transactionId !== segment.transactionId ||
          !sameCompactionSegment(segment, planned)
        ) {
          throw new Error(`Concurrent segment is not a retained partition: ${segment.id}`);
        }
        continue;
      }
      if (segment.level !== 0) {
        throw new Error(`Concurrent segment has an unsupported compaction level: ${segment.id}`);
      }
      const tuple = sourceOrderTuple(segment, transactions, "Concurrent compaction segment");
      if (
        tuple.logicalOrder <= maxOutputOrder ||
        compareMergeSourceOrder(latestSource, tuple) >= 0
      ) {
        throw new Error(`Concurrent segment would reorder compaction output: ${segment.id}`);
      }
    }
    for (const id of retained.keys()) {
      if (!visibleById.has(id)) {
        throw new Error(`Retained compaction partition is no longer visible: ${id}`);
      }
    }
  }

  async #assertLevelTwoSnapshotOrder(
    job: CompactionJobRecord,
    plan: RechunkCompactionRewritePlan,
    snapshot: Snapshot,
    transactions: ReadonlyMap<string, { status: string; committedVersion: number | null }>,
  ): Promise<void> {
    const table = await this.store.getTable(job.tableId);
    if (table === undefined) throw new Error(`Compaction table is missing: ${job.tableId}`);
    const sourceManifest = await this.store.getManifest(job.sourceManifestVersion);
    if (sourceManifest === undefined || sourceManifest.prunedAt !== undefined) {
      throw new Error(
        `Compaction source manifest is unavailable: ${String(job.sourceManifestVersion)}`,
      );
    }
    const plannedSnapshot = new Snapshot(this.store, sourceManifest.version);
    const plannedVisible = await this.#visibleSegmentRecords(table, plannedSnapshot);
    const plannedLayout = appendLevelTwoLayout(plannedVisible);
    if (
      plannedLayout === null ||
      plannedLayout.levelTwoSegments.length !== job.outputPartitionOrdinal
    ) {
      throw new Error("Compaction retained L2 prefix differs from its plan");
    }
    const plannedSources = plannedLayout.level0Segments.slice(0, job.sourceSegmentIds.length);
    if (
      plannedSources.length !== job.sourceSegmentIds.length ||
      plannedSources.some((segment, index) => segment.id !== job.sourceSegmentIds[index])
    ) {
      throw new Error("Compaction L2 sources are not the planned oldest L0 prefix");
    }
    for (const column of plan.columns) {
      const plannedBlockIds = column.sourceBlocks.map((block) => block.blockId);
      const descriptorBlockIds = plannedSources.flatMap(
        (segment) => segment.columnBlockIds[column.columnId] ?? [],
      );
      if (
        plannedBlockIds.length !== descriptorBlockIds.length ||
        plannedBlockIds.some((blockId, index) => blockId !== descriptorBlockIds[index])
      ) {
        throw new Error(`Compaction L2 source column differs from its plan: ${column.columnId}`);
      }
    }

    const currentVisible = await this.#visibleSegmentRecords(table, snapshot);
    const currentLayout = appendLevelTwoLayout(currentVisible);
    if (currentLayout?.levelTwoSegments.length !== job.outputPartitionOrdinal) {
      throw new Error("Concurrent segments violate the planned L2 layout");
    }
    const fixedPrefix = [...plannedLayout.retainedPrefix, ...plannedSources];
    if (currentVisible.length < fixedPrefix.length) {
      throw new Error("Compaction retained L2 prefix is no longer visible");
    }
    for (const [index, planned] of fixedPrefix.entries()) {
      const actual = currentVisible[index];
      if (
        actual?.id !== planned.id ||
        actual.transactionId !== planned.transactionId ||
        !sameCompactionSegment(actual, planned)
      ) {
        throw new Error(`Compaction retained segment differs from its plan: ${planned.id}`);
      }
    }
    const currentTail = currentVisible.slice(fixedPrefix.length);
    const earliestSource = sourceOrderTuple(plannedSources[0], transactions, "Compaction source");
    const latestSource = sourceOrderTuple(
      plannedSources[plannedSources.length - 1],
      transactions,
      "Compaction source",
    );
    const outputLogicalOrder = plan.logicalOrder;
    if (earliestSource.logicalOrder !== outputLogicalOrder) {
      throw new Error("Compaction L2 output order differs from its source prefix");
    }
    const latestRetained = plannedLayout.retainedPrefix.at(-1);
    if (
      latestRetained !== undefined &&
      compareMergeSourceOrder(
        sourceOrderTuple(latestRetained, transactions, "Retained compaction segment"),
        earliestSource,
      ) >= 0
    ) {
      throw new Error(`Retained compaction segment would reorder L2 output: ${latestRetained.id}`);
    }
    for (const segment of currentTail) {
      if (
        segment.level !== 0 ||
        segment.partitionOrdinal !== undefined ||
        segment.kind !== "insert" ||
        segment.rowIdSpans.length !== 0
      ) {
        throw new Error(`Concurrent segment has an unsupported compaction level: ${segment.id}`);
      }
      const tuple = sourceOrderTuple(segment, transactions, "Concurrent compaction segment");
      if (
        tuple.logicalOrder <= outputLogicalOrder ||
        compareMergeSourceOrder(latestSource, tuple) >= 0
      ) {
        throw new Error(`Concurrent segment would reorder compaction output: ${segment.id}`);
      }
    }
  }

  async #beginCompactionTransaction(job: CompactionJobRecord): Promise<{
    job: CompactionJobRecord;
    transaction: DatabaseTransaction | null;
  }> {
    const candidate = await this.#transactions.begin();
    const snapshot = await candidate.snapshot();
    try {
      await this.#assertCompactionSnapshotOrder(job, snapshot);
    } catch (error) {
      if (candidate.status === "active") await candidate.abort();
      const latest = await this.store.getCompactionJob(job.id);
      if (
        latest?.revision === job.revision &&
        latest.state !== "published" &&
        latest.state !== "cancelled" &&
        latest.state !== "aborted"
      ) {
        await this.#abortCompactionJob(latest, errorMessage(error));
      }
      throw error;
    }
    const missingSourceId = await firstMissingSnapshotBlock(snapshot, job.sourceBlockIds);
    if (missingSourceId !== undefined) {
      if (candidate.status === "active") await candidate.abort();
      const latest = await this.store.getCompactionJob(job.id);
      if (latest !== undefined && latest.revision !== job.revision) {
        return { job: latest, transaction: null };
      }
      const reason = `Compaction source is no longer visible: ${missingSourceId}`;
      if (
        latest !== undefined &&
        latest.state !== "published" &&
        latest.state !== "aborted" &&
        latest.state !== "cancelled"
      ) {
        await this.#abortCompactionJob(latest, reason);
      }
      throw new Error(reason);
    }
    try {
      const linked = await this.store.updateCompactionJob(job.id, job.revision, {
        state: "running",
        transactionId: candidate.id,
        updatedAt: dateIsoString(this.#now()),
        error: null,
      });
      return { job: linked, transaction: candidate };
    } catch (error) {
      const latest = await this.store.getCompactionJob(job.id);
      if (latest?.transactionId === candidate.id) {
        return { job: latest, transaction: candidate };
      }
      if (candidate.status === "active") await candidate.abort();
      if (error instanceof CompactionJobConflictError && latest !== undefined) {
        return { job: latest, transaction: null };
      }
      throw error;
    }
  }

  async #markCompactionPublished(
    job: CompactionJobRecord,
    version: number,
  ): Promise<CompactionJobRecord> {
    if (job.state === "published") return job;
    try {
      return await this.store.updateCompactionJob(job.id, job.revision, {
        state: "published",
        publishedVersion: version,
        updatedAt: dateIsoString(this.#now()),
        error: null,
      });
    } catch (error) {
      const latest = await this.store.getCompactionJob(job.id);
      if (latest?.state === "published") return latest;
      if (latest?.transactionId === job.transactionId) {
        return this.store.updateCompactionJob(latest.id, latest.revision, {
          state: "published",
          publishedVersion: version,
          updatedAt: dateIsoString(this.#now()),
          error: null,
        });
      }
      throw error;
    }
  }

  /**
   * Stages one output segment, reconciling with what a previous attempt left: the same
   * segment staged by this transaction is reused, one left by an aborted transaction is
   * adopted when it matches and was never published, anything else is an error.
   */
  async #stageCompactionOutputSegment(
    transaction: DatabaseTransaction,
    desired: SegmentRecord,
    expectedOutputIds: readonly string[],
  ): Promise<void> {
    const existing = await this.store.getSegment(desired.id);
    if (existing === undefined) {
      await transaction.stageSegment(desired);
      return;
    }
    if (existing.transactionId === transaction.id) {
      if (!sameCompactionSegment(existing, desired)) {
        throw new Error(`A resumed compaction segment differs: ${desired.id}`);
      }
      await transaction.stageExistingSegment(desired.id);
      return;
    }
    const owner = await this.store.getTransaction(existing.transactionId);
    if (owner?.status !== "aborted" || !sameCompactionSegment(existing, desired)) {
      throw new Error(`Compaction output segment cannot be adopted: ${desired.id}`);
    }
    if (await this.#unprunedManifestContainsAll(expectedOutputIds)) {
      throw new Error(`Compaction output segment is already visible: ${desired.id}`);
    }
    await transaction.adoptAbortedCompactionSegment(
      {
        ...desired,
        // The timestamp was fixed by the first durable staging attempt. commitOrdinal belongs to
        // the replacement journal and is rewritten atomically when an earlier partition has
        // already moved out of the aborted owner's journal.
        createdAt: existing.createdAt,
      },
      owner,
    );
  }

  async #abortCompactionJob(job: CompactionJobRecord, error: string): Promise<CompactionJobRecord> {
    return this.store.updateCompactionJob(job.id, job.revision, {
      state: "aborted",
      updatedAt: dateIsoString(this.#now()),
      error,
    });
  }

  async #publishedCompactionProgress(
    table: TableRecord,
    job: CompactionJobRecord,
  ): Promise<CompactionJobProgress> {
    const version = job.publishedVersion;
    if (version === null) {
      throw new Error(`Published compaction has no committed version: ${job.id}`);
    }
    return compactionProgress(table.name, job, this.#compactionResult(table, job, version));
  }

  #compactionResult(
    table: TableRecord,
    job: CompactionJobRecord,
    version: number,
  ): CompactTableResult {
    const rewritePlan = job.rewritePlan;
    const rowCount = rewritePlan.kind === "copy-v1" ? job.processedRows : rewritePlan.totalRows;
    const outputLogicalBytes = job.outputLogicalBytes;
    const totalMs = Math.max(Date.parse(job.updatedAt) - Date.parse(job.createdAt), 0);
    return {
      jobId: job.id,
      tableName: table.name,
      compacted: true,
      sourceSegmentCount: job.sourceSegmentIds.length,
      sourceBlockCount: job.sourceBlockIds.length,
      outputSegmentId: job.outputSegmentId,
      outputSegmentIds: compactionOutputSegmentIds(job),
      outputBlockCount: job.outputBlockIds.length,
      rowCount,
      sourceStoredBytes: job.sourceStoredBytes,
      outputStoredBytes: job.outputStoredBytes,
      level0SourceStoredBytes: job.level0SourceStoredBytes,
      anchorSourceStoredBytes: job.anchorSourceStoredBytes,
      compactionWriteAmplification: job.outputStoredBytes / job.level0SourceStoredBytes,
      ...(job.outputPartitionOrdinal === undefined
        ? {}
        : {
            outputPartitionOrdinal: job.outputPartitionOrdinal,
            maxWriteAmplification: job.maxWriteAmplification ?? 0,
            maximumOutputStoredBytes: job.maximumOutputStoredBytes ?? 0,
            plannedOutputStoredBytesUpperBound: job.plannedOutputStoredBytesUpperBound ?? 0,
            priorAttemptOutputStoredBytes: job.priorAttemptOutputStoredBytes ?? 0,
            lifetimeOutputStoredBytes:
              (job.priorAttemptOutputStoredBytes ?? 0) + job.outputStoredBytes,
          }),
      outputLogicalBytes,
      ...(rewritePlan.kind !== "copy-v1"
        ? {
            targetBlockBytes: rewritePlan.targetBlockBytes,
            outputCompression: rewritePlan.outputCompression,
            memoryBudgetBytes: job.memoryBudgetBytes,
            minimumMemoryBytes: job.minimumMemoryBytes,
            peakWorkingBytes: job.peakWorkingBytes,
          }
        : {}),
      supersededBlockCount: job.sourceBlockIds.length,
      physicallyReclaimedBytes: 0,
      version,
      metrics: createWriteMetrics({
        logicalBytes: outputLogicalBytes,
        storedBytes: job.outputStoredBytes,
        encodeMs: 0,
        stageMs: totalMs,
        commitMs: 0,
        totalMs,
        retries: 0,
        rows: rowCount,
      }),
    };
  }

  #firstLogicalOrder(sourceSegments: readonly SegmentRecord[]): number {
    return Math.min(...sourceSegments.map((segment) => segment.logicalOrder));
  }

  async #classifyKeys(
    table: TableRecord,
    version: number | null,
    kind: "insert" | "upsert",
    keys: Map<string, Exclude<BatchValue, null>> | undefined,
  ): Promise<{ inserted: number; updated: number }> {
    if (keys === undefined) return { inserted: 0, updated: 0 };
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) throw new Error("Unique key metadata is missing");
    const existing = await this.#existingKeyTokens(table, version, [...keys.keys()]);
    let inserted = 0;
    let updated = 0;
    for (const [token, value] of keys) {
      if (existing.has(token)) {
        if (kind === "insert") {
          throw new UniqueConstraintError(table.name, publicKeyName(table, keyColumn), value);
        }
        updated += 1;
      } else {
        inserted += 1;
      }
    }
    return { inserted, updated };
  }

  async #existingKeyTokens(
    table: TableRecord,
    version: number | null,
    requestedTokens: readonly string[],
  ): Promise<Set<string>> {
    if (table.uniqueKeyLookupReady === true) {
      return new Set(await this.#existingUniqueKeysWindowed(table.id, requestedTokens));
    }
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) throw new Error("Unique key metadata is missing");
    const requested = new Set(requestedTokens);
    return new Set(
      (await this.#materializeTable(table, version))
        .map((row) => keyToken(keyColumn.type, row[keyColumn.name] ?? null))
        .filter((token) => requested.has(token)),
    );
  }

  async #existingUniqueKeysWindowed(
    tableId: string,
    requestedTokens: readonly string[],
  ): Promise<string[]> {
    const found: string[] = [];
    for (let start = 0; start < requestedTokens.length; start += MAX_STORAGE_BULK_READ_ITEMS) {
      found.push(
        ...(await this.store.getExistingUniqueKeys(
          tableId,
          requestedTokens.slice(start, start + MAX_STORAGE_BULK_READ_ITEMS),
        )),
      );
    }
    return found;
  }

  async #materializeTable(
    table: TableRecord,
    version?: number | null,
    projectedColumns: readonly TableColumnRecord[] = table.columns,
  ): Promise<DatabaseRow[]> {
    return this.#withLeasedSnapshot(version, (snapshot) =>
      this.#materializeTableAtSnapshot(table, snapshot, projectedColumns),
    );
  }

  async #materializeTableAtSnapshot(
    table: TableRecord,
    snapshot: LeasedSnapshot,
    projectedColumns: readonly TableColumnRecord[] = table.columns,
  ): Promise<DatabaseRow[]> {
    const segments = await this.#visibleSegmentRecords(table, snapshot);
    const keyColumn = getUniqueKeyColumn(table);
    const neededColumns = [
      ...projectedColumns,
      ...(keyColumn === undefined || projectedColumns.some((column) => column.id === keyColumn.id)
        ? []
        : [keyColumn]),
    ];
    const neededColumnIds = new Set(neededColumns.map((column) => column.id));
    const rows: Array<DatabaseRow | undefined> = [];
    const rowIndexByKey = new Map<string, number>();
    for (const segment of segments) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const segmentBlockIds = Object.entries(segment.columnBlockIds)
        .filter(([columnId]) => neededColumnIds.has(columnId))
        .flatMap(([, ids]) => ids);
      const decodedColumns = await this.#loadDecodedBlocks(segmentBlockIds, snapshot);
      if (segment.kind === "delete") {
        if (keyColumn === undefined)
          throw new Error(`Delete segment has no unique key: ${segment.id}`);
        for (const value of this.#readSegmentColumn(keyColumn, segment, decodedColumns)) {
          const token = keyToken(keyColumn.type, value);
          const existingIndex = rowIndexByKey.get(token);
          if (existingIndex !== undefined) rows[existingIndex] = undefined;
          rowIndexByKey.delete(token);
        }
        continue;
      }
      if (segment.kind === "update") {
        if (keyColumn === undefined)
          throw new Error(`Update segment has no unique key: ${segment.id}`);
        const keyValues = this.#readSegmentColumn(keyColumn, segment, decodedColumns);
        const changedColumns = projectedColumns.filter(
          (column) =>
            column.id !== keyColumn.id && (segment.columnBlockIds[column.id]?.length ?? 0) > 0,
        );
        const changedValues = new Map(
          changedColumns.map(
            (column) =>
              [column.id, this.#readSegmentColumn(column, segment, decodedColumns)] as const,
          ),
        );
        keyValues.forEach((value, rowIndex) => {
          const token = keyToken(keyColumn.type, value);
          const existingIndex = rowIndexByKey.get(token);
          if (existingIndex === undefined) {
            throw new Error(`Update segment references a missing key: ${segment.id}`);
          }
          const existing = rows[existingIndex];
          if (existing === undefined) {
            throw new Error(`Update segment references a deleted row: ${segment.id}`);
          }
          for (const column of changedColumns) {
            existing[column.name] = changedValues.get(column.id)?.[rowIndex] ?? null;
          }
        });
        continue;
      }
      const segmentRows = this.#readSegment(neededColumns, segment, decodedColumns);
      for (const row of segmentRows) {
        if (segment.kind === "upsert") {
          if (keyColumn === undefined)
            throw new Error(`Upsert segment has no unique key: ${segment.id}`);
          const token = keyToken(keyColumn.type, row[keyColumn.name] ?? null);
          const existingIndex = rowIndexByKey.get(token);
          if (existingIndex === undefined) {
            rowIndexByKey.set(token, rows.length);
            rows.push(row);
          } else {
            rows[existingIndex] = row;
          }
        } else {
          if (keyColumn !== undefined) {
            const token = keyToken(keyColumn.type, row[keyColumn.name] ?? null);
            if (rowIndexByKey.has(token)) {
              throw new Error(`Stored table contains a duplicate unique key: ${table.name}`);
            }
            rowIndexByKey.set(token, rows.length);
          }
          rows.push(row);
        }
      }
    }
    const visibleRows = rows.filter((row): row is DatabaseRow => row !== undefined);
    if (neededColumns.length === projectedColumns.length) return visibleRows;
    return visibleRows.map((row) =>
      Object.fromEntries(projectedColumns.map((column) => [column.name, row[column.name] ?? null])),
    );
  }

  #cacheGet(key: string): unknown {
    return this.#artifactCache.get(key);
  }

  /**
   * Buffer pool observability: byte budget and residency plus lifetime hit/miss/eviction
   * counters across every entry family (decoded blocks, block vectors, zone descriptions,
   * derived results, memoized results). Use it to size bufferPoolBytes from real workloads.
   */
  bufferPoolStats(): BufferPoolStats {
    return this.#artifactCache.stats();
  }

  /**
   * Caches one prepared artifact under the byte-bounded LRU. Payloads are shared
   * read-only across prepared queries; entries for superseded segment sets simply stop
   * matching and age out the same way evicted entries do.
   */
  #cachePut(key: string, payload: unknown, bytes: number): void {
    this.#artifactCache.put(key, payload, bytes);
  }

  /**
   * Creates and fully builds a durable secondary index. The catalog's global
   * index-name namespace matches the SQL DDL: a duplicate name is rejected even on another
   * table. The building state makes the operation crash-safe; readers scan until the base and
   * every concurrent commit delta are known to be covered.
   */
  async createIndex(
    indexName: string,
    tableName: string,
    requestedColumns: string | ReadonlyArray<{ name: string; direction: "asc" | "desc" }>,
    options: { unique?: boolean } = {},
  ): Promise<void> {
    // Keep the original low-level single-column API source-compatible while SQL and new callers
    // use the explicit ordered key shape.
    const indexColumns =
      typeof requestedColumns === "string"
        ? [{ name: requestedColumns, direction: "asc" as const }]
        : requestedColumns;
    const tables = await this.store.listTables();
    if (
      tables.some((table) =>
        Object.values(table.secondaryIndexes ?? {}).some((index) => index.name === indexName),
      )
    ) {
      throw new TypeError(`Index already exists: ${indexName}`);
    }
    const table = tables.find((candidate) => candidate.name === tableName);
    if (table === undefined || table.view !== undefined) {
      throw new UnknownTableError(tableName);
    }
    if (indexColumns.length === 0) throw new TypeError("An index needs at least one column");
    const duplicate = indexColumns.find(
      (column, position) =>
        indexColumns.findIndex((candidate) => candidate.name === column.name) !== position,
    );
    if (duplicate !== undefined) {
      throw new TypeError(`Index column appears more than once: ${duplicate.name}`);
    }
    const columns = indexColumns.map(({ name }) => {
      const column = table.columns.find((candidate) => candidate.name === name);
      if (column === undefined) throw new TypeError(`Unknown column: ${name}`);
      return column;
    });
    const indexId = this.#createId();
    const storageColumnId = `secondary-index:${indexId}`;
    const buildId = this.#createId();
    const marked = await this.store.updateTable(table.id, table.revision, {
      secondaryIndexes: {
        ...table.secondaryIndexes,
        [indexId]: {
          name: indexName,
          columnId: columns[0]?.id ?? "",
          columnIds: columns.map((column) => column.id),
          directions: indexColumns.map((column) => column.direction),
          ...(options.unique === true ? { unique: true as const } : {}),
          termEncoding: "tuple-v1",
          storage: "postings-v1",
          storageColumnId,
          locator: table.uniqueKeyColumnId === undefined ? "row-id" : "key-hash-v1",
          state: "building",
          buildId,
          buildFromVersion: -1,
        },
      },
    });
    try {
      await this.#buildSecondaryIndex(marked, indexId);
    } catch (error) {
      // A caller that sees CREATE INDEX fail must not inherit an unusable schema object. An
      // abandoned tab is different: it never runs this catch, so the durable `building` marker
      // remains available for another connection to take over.
      await this.#removeSecondaryIndexIfOwned(marked.id, indexId, indexName, storageColumnId).catch(
        (cleanupError: unknown) => {
          throw new AggregateError(
            [error, cleanupError],
            `CREATE INDEX ${indexName} failed and its catalog cleanup also failed`,
          );
        },
      );
      throw error;
    }
  }

  /** Removes only the exact failed build this caller created, retrying catalog CAS races. */
  async #removeSecondaryIndexIfOwned(
    tableId: string,
    indexId: string,
    indexName: string,
    storageColumnId: string,
  ): Promise<void> {
    for (let attempt = 0; attempt <= this.#maxCommitRetries; attempt += 1) {
      const fresh = await this.store.getTable(tableId);
      if (fresh === undefined) return;
      const owned = fresh.secondaryIndexes?.[indexId];
      if (owned?.name !== indexName || owned.storageColumnId !== storageColumnId) {
        return;
      }
      const secondaryIndexes = Object.fromEntries(
        Object.entries(fresh.secondaryIndexes ?? {}).filter(([candidate]) => candidate !== indexId),
      );
      try {
        await this.store.updateTable(fresh.id, fresh.revision, {
          secondaryIndexes: Object.keys(secondaryIndexes).length === 0 ? null : secondaryIndexes,
        });
        return;
      } catch (error) {
        if (!(error instanceof TableRecordConflictError) || attempt === this.#maxCommitRetries) {
          throw error;
        }
      }
    }
  }

  /** Drops one globally named secondary index. */
  async dropIndex(indexName: string, options: { ifExists?: boolean } = {}): Promise<boolean> {
    for (const table of await this.store.listTables()) {
      const entry = Object.entries(table.secondaryIndexes ?? {}).find(
        ([, index]) => index.name === indexName,
      );
      if (entry === undefined) continue;
      const [indexId] = entry;
      const indexes = Object.fromEntries(
        Object.entries(table.secondaryIndexes ?? {}).filter(
          ([candidateId]) => candidateId !== indexId,
        ),
      );
      await this.store.updateTable(table.id, table.revision, {
        secondaryIndexes: Object.keys(indexes).length === 0 ? null : indexes,
      });
      return true;
    }
    if (options.ifExists === true) return false;
    throw new TypeError(`Unknown index: ${indexName}`);
  }

  async #buildSecondaryIndex(table: TableRecord, indexId: string): Promise<void> {
    const index = table.secondaryIndexes?.[indexId];
    if (index === undefined) return;
    const key = `${table.id}/${index.storageColumnId}`;
    const existing = this.#ftsBuildsInFlight.get(key);
    if (existing !== undefined) return existing;
    const build = (async () => {
      let currentTable = table;
      let currentIndex = index;
      let ownedBuildId = index.buildId;
      for (let attempt = 0; ; attempt += 1) {
        try {
          await this.#buildSecondaryIndexBase(currentTable, indexId, currentIndex, ownedBuildId);
          return;
        } catch (error) {
          if (!(error instanceof WriteConflictError) || attempt >= this.#maxCommitRetries) {
            throw error;
          }
          const fresh = await this.store.getTable(table.id);
          const freshIndex = fresh?.secondaryIndexes?.[indexId];
          if (fresh === undefined || freshIndex === undefined) return;
          currentTable = fresh;
          currentIndex = freshIndex;
          ownedBuildId = freshIndex.buildId;
        }
      }
    })();
    this.#ftsBuildsInFlight.set(key, build);
    try {
      await build;
    } finally {
      if (this.#ftsBuildsInFlight.get(key) === build) this.#ftsBuildsInFlight.delete(key);
    }
  }

  async #buildSecondaryIndexBase(
    table: TableRecord,
    indexId: string,
    index: SecondaryIndexRecord,
    ownedBuildId?: string,
  ): Promise<void> {
    const current = await this.store.getTable(table.id);
    if (current === undefined) return;
    const held = current.secondaryIndexes?.[indexId];
    if (held === undefined) return;
    const ownsMarkedBuild =
      ownedBuildId !== undefined && held.state === "building" && held.buildId === ownedBuildId;
    const buildId = ownsMarkedBuild ? ownedBuildId : this.#createId();
    const marked = ownsMarkedBuild
      ? current
      : await this.store.updateTable(current.id, current.revision, {
          secondaryIndexes: {
            ...current.secondaryIndexes,
            [indexId]: { ...held, state: "building", buildId, buildFromVersion: -1 },
          },
        });
    try {
      await this.#withLeasedSnapshot(undefined, async (snapshot) => {
        const columns = secondaryIndexColumnIds(index).map((columnId) =>
          marked.columns.find((candidate) => candidate.id === columnId),
        );
        if (columns.some((column) => column === undefined)) return;
        const indexedColumns = columns as TableColumnRecord[];
        const keyColumn = getUniqueKeyColumn(marked);
        const projected = keyColumn === undefined ? indexedColumns : [...indexedColumns, keyColumn];
        const coversVersion = snapshot.version ?? -1;
        const projectedColumns = [...new Map(projected.map((entry) => [entry.id, entry])).values()];
        const uniqueTerms = index.unique === true ? new Set<string>() : undefined;
        const streamed = await this.#writeStreamedSecondaryIndexBase(
          marked,
          indexedColumns,
          keyColumn,
          index,
          projectedColumns,
          snapshot,
          coversVersion,
          buildId,
          uniqueTerms,
        );
        if (!streamed) {
          if (index.unique === true) {
            await this.#writeMaterializedSecondaryIndexBase(
              marked,
              indexedColumns,
              keyColumn,
              index,
              projectedColumns,
              snapshot,
              coversVersion,
              buildId,
              uniqueTerms ?? new Set<string>(),
            );
          } else {
            await this.#writeHistoricalSecondaryIndexBase(
              marked,
              indexedColumns,
              keyColumn,
              index,
              snapshot,
              coversVersion,
              buildId,
            );
          }
        }
        const fresh = await this.store.getTable(marked.id);
        const freshIndex = fresh?.secondaryIndexes?.[indexId];
        if (freshIndex === undefined) {
          // DROP INDEX / DROP TABLE can win while a whole-base build is writing.
          // Its storage identity is never reused, so reclaiming it here cannot touch a new index.
          await this.store.removeFtsColumn(marked.id, index.storageColumnId);
          return;
        }
        if (
          fresh !== undefined &&
          freshIndex.state === "building" &&
          freshIndex.buildId === buildId
        ) {
          const { buildId: _completedBuild, ...readyIndex } = freshIndex;
          void _completedBuild;
          await this.store.updateTable(fresh.id, fresh.revision, {
            secondaryIndexes: {
              ...fresh.secondaryIndexes,
              [indexId]: {
                ...readyIndex,
                state: "ready",
                buildFromVersion: coversVersion,
                ...(index.unique === true ? { uniqueEnforced: true as const } : {}),
              },
            },
            ...(index.unique === true
              ? {
                  expectedManifestVersion: {
                    value: coversVersion < 0 ? null : coversVersion,
                  },
                  uniqueKeySeed: {
                    namespaceId: secondaryUniqueKeyNamespace(fresh.id, indexId),
                    keyTokens: [...(uniqueTerms ?? [])],
                  },
                }
              : {}),
          });
        }
      });
    } catch (error) {
      const fresh = await this.store.getTable(table.id);
      const freshIndex = fresh?.secondaryIndexes?.[indexId];
      if (
        fresh !== undefined &&
        freshIndex?.state === "building" &&
        freshIndex.buildId === buildId
      ) {
        const { buildId: _failedBuild, ...invalidIndex } = freshIndex;
        void _failedBuild;
        const invalidated = await this.store
          .updateTable(fresh.id, fresh.revision, {
            secondaryIndexes: {
              ...fresh.secondaryIndexes,
              [indexId]: { ...invalidIndex, state: "invalid" },
            },
          })
          .then(() => true)
          .catch(() => false);
        // Catalog first: every intermediate reader scans. Once invalid, postings are neither
        // truth nor maintained; removing their base and deltas bounds a persistently failing
        // rebuild without touching a UNIQUE index's separate membership namespace.
        if (invalidated) {
          await this.store
            .removeFtsColumn(fresh.id, freshIndex.storageColumnId)
            .catch(() => undefined);
        }
      }
      throw error;
    }
  }

  #postingBuildExpiry(now: Date): string {
    const expiresAt = dateMilliseconds(now) + MAX_POSTING_BUILD_TTL_MS;
    if (!Number.isSafeInteger(expiresAt)) throw new RangeError("Posting build expiry overflow");
    return dateIsoString(new Date(expiresAt));
  }

  async #beginPostingBuild(tableId: string, columnId: string, buildId: string): Promise<void> {
    const now = this.#now();
    await this.store.beginFtsBaseBuild({
      tableId,
      columnId,
      buildId,
      ownerId: this.#internalLeaseOwnerId,
      createdAt: dateIsoString(now),
      expiresAt: this.#postingBuildExpiry(now),
    });
  }

  async #writePostingBuildChunk(
    tableId: string,
    columnId: string,
    buildId: string,
    ordinal: number,
    chunk: readonly FtsPosting[],
  ): Promise<void> {
    const now = this.#now();
    await this.store.writeFtsBaseBuildChunk({
      tableId,
      columnId,
      buildId,
      ownerId: this.#internalLeaseOwnerId,
      expiresAtCutoff: dateIsoString(now),
      expiresAt: this.#postingBuildExpiry(now),
      updatedAt: dateIsoString(now),
      ordinal,
      chunk,
    });
  }

  async #finishPostingBuild(
    tableId: string,
    columnId: string,
    buildId: string,
    input: { coversVersion: number; chunkCount: number; totalTokens: number },
  ): Promise<void> {
    const now = this.#now();
    await this.store.finishFtsBaseBuild({
      tableId,
      columnId,
      buildId,
      ownerId: this.#internalLeaseOwnerId,
      expiresAtCutoff: dateIsoString(now),
      ...input,
      completedAt: dateIsoString(now),
    });
  }

  async #abortPostingBuild(tableId: string, columnId: string, buildId: string): Promise<void> {
    await this.store.abortFtsBaseBuild({
      tableId,
      columnId,
      buildId,
      ownerId: this.#internalLeaseOwnerId,
      expiresAtCutoff: dateIsoString(this.#now()),
    });
  }

  /**
   * Exact fallback for a UNIQUE build over a history the forward streamer cannot replay (today,
   * an uncompacted upsert history). The ordinary current-row materializer is the source of truth;
   * output still lands in row-group chunks, and the common append/update/delete path above stays
   * window-bounded. This fallback is intentionally unique-only: a non-unique accelerator can use
   * the bounded historical superset instead.
   */
  async #writeMaterializedSecondaryIndexBase(
    table: TableRecord,
    columns: readonly TableColumnRecord[],
    keyColumn: TableColumnRecord | undefined,
    index: SecondaryIndexRecord,
    projectedColumns: readonly TableColumnRecord[],
    snapshot: LeasedSnapshot,
    coversVersion: number,
    buildId: string,
    uniqueTerms: Set<string>,
  ): Promise<void> {
    if (keyColumn === undefined) {
      throw new Error(`Materialized UNIQUE-index fallback needs a table key: ${table.name}`);
    }
    const begin = this.#beginPostingBuild.bind(this);
    const writeChunk = this.#writePostingBuildChunk.bind(this);
    const finish = this.#finishPostingBuild.bind(this);
    const abort = this.#abortPostingBuild.bind(this);
    await begin(table.id, index.storageColumnId, buildId);
    try {
      const materialized = await this.#materializeColumnarTableAtSnapshot(
        table,
        snapshot,
        projectedColumns,
      );
      const valueVectors = columns.map((column) => materialized.columns.get(column.name));
      const keyVector = materialized.columns.get(keyColumn.name);
      if (valueVectors.some((vector) => vector === undefined) || keyVector === undefined) {
        throw new Error(`UNIQUE-index source columns are missing: ${index.name}`);
      }
      let ordinal = 0;
      let totalTokens = 0;
      for (let start = 0; start < materialized.rowCount; start += this.#rowsPerBlock) {
        const end = Math.min(materialized.rowCount, start + this.#rowsPerBlock);
        const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
        for (let row = start; row < end; row += 1) {
          const values = valueVectors.map((vector, position) =>
            vector === undefined
              ? null
              : storedSqlValueFromExecution(columns[position], vectorValue(vector, row)),
          );
          if (values.some((value) => value === null)) continue;
          const locator = secondaryKeyLocator(
            keyColumn.type,
            storedSqlValueFromExecution(keyColumn, vectorValue(keyVector, row)),
          );
          addSecondaryPosting(byTerm, index, columns, values, locator, uniqueTerms);
        }
        const postings = sortedSecondaryPostings(byTerm);
        for (const chunk of chunkFtsPostings(postings)) {
          totalTokens = safeWholeNumberSum(
            [totalTokens, postingFrequencyTotal(chunk)],
            "Secondary-index posting count",
          );
          await writeChunk(table.id, index.storageColumnId, buildId, ordinal, chunk);
          ordinal += 1;
        }
      }
      await finish(table.id, index.storageColumnId, buildId, {
        coversVersion,
        chunkCount: ordinal,
        totalTokens,
      });
    } catch (error) {
      await abort(table.id, index.storageColumnId, buildId).catch(() => undefined);
      throw error;
    }
  }

  async #writeStreamedSecondaryIndexBase(
    table: TableRecord,
    columns: readonly TableColumnRecord[],
    keyColumn: TableColumnRecord | undefined,
    index: SecondaryIndexRecord,
    projectedColumns: readonly TableColumnRecord[],
    snapshot: LeasedSnapshot,
    coversVersion: number,
    buildId: string,
    uniqueTerms?: Set<string>,
  ): Promise<boolean> {
    const begin = this.#beginPostingBuild.bind(this);
    const writeChunk = this.#writePostingBuildChunk.bind(this);
    const finish = this.#finishPostingBuild.bind(this);
    const abort = this.#abortPostingBuild.bind(this);
    const segments = await this.#visibleSegmentRecords(table, snapshot);
    const factory = this.#streamedViewFactory(table, projectedColumns, segments, snapshot);
    if (factory === undefined) return false;
    await begin(table.id, index.storageColumnId, buildId);
    const memory = new QueryMemoryContext(DEFAULT_COMPACTION_MEMORY_BUDGET_BYTES);
    try {
      const streamed = await factory.create(memory);
      const valueVectors = columns.map((column) => streamed.table.columns.get(column.name));
      if (valueVectors.some((vector) => vector === undefined)) {
        throw new Error(
          `Indexed column is missing: ${columns.map((column) => column.name).join(", ")}`,
        );
      }
      const keyVector =
        keyColumn === undefined ? undefined : streamed.table.columns.get(keyColumn.name);
      const rowIdAt =
        keyColumn === undefined ? appendRowIdLocator(segments, streamed.table.rowCount) : undefined;
      let ordinal = 0;
      let totalTokens = 0;
      for (let start = 0; start < streamed.table.rowCount;) {
        const requested = Math.min(this.#rowsPerBlock, streamed.table.rowCount - start);
        const residentEnd = await streamed.load(start, requested);
        const end = Math.min(start + requested, residentEnd);
        if (end <= start) throw new Error(`Secondary-index scan made no progress: ${table.name}`);
        const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
        for (let row = start; row < end; row += 1) {
          const values = valueVectors.map((vector, position) =>
            vector === undefined
              ? null
              : storedSqlValueFromExecution(columns[position], vectorValue(vector, row)),
          );
          if (values.some((value) => value === null)) continue;
          const locator =
            keyColumn === undefined
              ? (rowIdAt?.(row) ?? 0n)
              : secondaryKeyLocator(
                  keyColumn.type,
                  keyVector === undefined
                    ? null
                    : storedSqlValueFromExecution(keyColumn, vectorValue(keyVector, row)),
                );
          addSecondaryPosting(byTerm, index, columns, values, locator, uniqueTerms);
        }
        const postings = sortedSecondaryPostings(byTerm);
        for (const chunk of chunkFtsPostings(postings)) {
          totalTokens = safeWholeNumberSum(
            [totalTokens, postingFrequencyTotal(chunk)],
            "Secondary-index posting count",
          );
          await writeChunk(table.id, index.storageColumnId, buildId, ordinal, chunk);
          ordinal += 1;
        }
        start = end;
      }
      await finish(table.id, index.storageColumnId, buildId, {
        coversVersion,
        chunkCount: ordinal,
        totalTokens,
      });
      return true;
    } catch (error) {
      await abort(table.id, index.storageColumnId, buildId).catch(() => undefined);
      throw error;
    } finally {
      memory.close();
    }
  }

  /**
   * Bounded fallback for histories the exact-current-row streamer cannot represent (notably
   * upsert segments and columns added after old segments were written). Index every historical
   * value under its stable row/key locator, one physical row group at a time. Old values are
   * harmless false positives because the query rechecks current rows; omitting them would be a
   * false negative. This keeps peak build memory at two decoded blocks instead of materializing
   * the table.
   */
  async #writeHistoricalSecondaryIndexBase(
    table: TableRecord,
    columns: readonly TableColumnRecord[],
    keyColumn: TableColumnRecord | undefined,
    index: SecondaryIndexRecord,
    snapshot: LeasedSnapshot,
    coversVersion: number,
    buildId: string,
  ): Promise<void> {
    const begin = this.#beginPostingBuild.bind(this);
    const writeChunk = this.#writePostingBuildChunk.bind(this);
    const finish = this.#finishPostingBuild.bind(this);
    const abort = this.#abortPostingBuild.bind(this);
    const segments = await this.#visibleSegmentRecords(table, snapshot);
    await begin(table.id, index.storageColumnId, buildId);
    try {
      let ordinal = 0;
      let totalTokens = 0;
      for (const segment of segments) {
        const anchorIds =
          (keyColumn === undefined ? undefined : segment.columnBlockIds[keyColumn.id]) ??
          columns
            .map((column) => segment.columnBlockIds[column.id])
            .find((ids) => ids !== undefined) ??
          Object.values(segment.columnBlockIds)[0] ??
          [];
        if (anchorIds.length === 0) {
          if (segment.rowCount === 0) continue;
          throw new Error(`Secondary-index segment has no row-group anchor: ${segment.id}`);
        }
        for (const column of columns) {
          const ids = segment.columnBlockIds[column.id];
          if (ids !== undefined && ids.length !== anchorIds.length) {
            throw new Error(`Secondary-index blocks differ for ${column.name}`);
          }
        }
        const keyIds = keyColumn === undefined ? undefined : segment.columnBlockIds[keyColumn.id];
        if (keyColumn !== undefined && keyIds?.length !== anchorIds.length) {
          throw new Error(`Secondary-index key blocks differ from indexed blocks`);
        }
        const rowIdAt =
          keyColumn === undefined ? appendRowIdLocator([segment], segment.rowCount) : undefined;
        let segmentRow = 0;
        for (let blockIndex = 0; blockIndex < anchorIds.length; blockIndex += 1) {
          await this.#renewInternalLeaseIfNeeded(snapshot);
          const valueIds = columns.map((column) => segment.columnBlockIds[column.id]?.[blockIndex]);
          const anchorId = anchorIds[blockIndex] ?? "";
          const keyId = keyIds?.[blockIndex];
          const ids = [
            ...new Set(
              [anchorId, ...valueIds, keyId].filter((id): id is string => id !== undefined),
            ),
          ];
          const decoded = await this.#decodedBlocksThroughCache(ids, snapshot);
          const byId = new Map(ids.map((id, position) => [id, decoded[position]] as const));
          const anchorBlock = byId.get(anchorId);
          if (anchorBlock === undefined)
            throw new Error(`Secondary-index anchor block is invalid: ${anchorId}`);
          const rowCount = anchorBlock.column.rowCount;
          const vectors = columns.map((column, position) => {
            const id = valueIds[position];
            if (id === undefined) return undefined;
            const block = byId.get(id);
            if (block?.column.type !== column.type || block.column.rowCount !== rowCount) {
              throw new Error(`Secondary-index value block is invalid: ${id}`);
            }
            return this.#blockColumnVector(id, block);
          });
          const keyBlock = keyId === undefined ? undefined : byId.get(keyId);
          if (
            keyColumn !== undefined &&
            (keyBlock?.column.type !== keyColumn.type || keyBlock.column.rowCount !== rowCount)
          ) {
            throw new Error(`Secondary-index key block is invalid: ${keyId ?? ""}`);
          }
          const keys =
            keyColumn === undefined || keyBlock === undefined || keyId === undefined
              ? undefined
              : this.#blockColumnVector(keyId, keyBlock);
          const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
          for (let row = 0; row < rowCount; row += 1) {
            const values = columns.map((column, position) => {
              const vector = vectors[position];
              return vector === undefined ? (column.backfill ?? null) : vectorValue(vector, row);
            });
            if (values.some((value) => value === null)) continue;
            const locator =
              keyColumn === undefined
                ? (rowIdAt?.(segmentRow + row) ?? 0n)
                : secondaryKeyLocator(
                    keyColumn.type,
                    keys === undefined ? null : vectorValue(keys, row),
                  );
            addSecondaryPosting(byTerm, index, columns, values, locator);
          }
          const postings = sortedSecondaryPostings(byTerm);
          for (const chunk of chunkFtsPostings(postings)) {
            totalTokens = safeWholeNumberSum(
              [totalTokens, postingFrequencyTotal(chunk)],
              "Secondary-index posting count",
            );
            await writeChunk(table.id, index.storageColumnId, buildId, ordinal, chunk);
            ordinal += 1;
          }
          segmentRow += rowCount;
        }
        if (segmentRow !== segment.rowCount) {
          throw new Error(`Secondary-index column row count differs in segment ${segment.id}`);
        }
      }
      await finish(table.id, index.storageColumnId, buildId, {
        coversVersion,
        chunkCount: ordinal,
        totalTokens,
      });
    } catch (error) {
      await abort(table.id, index.storageColumnId, buildId).catch(() => undefined);
      throw error;
    }
  }

  /**
   * Builds (or rebuilds) the persisted full-text pruning index for one column from the current
   * snapshot. Append-only tables only. The planner consults the index when the column is
   * "ready" with a matching tokenizer version and re-verifies every candidate row, so a stale,
   * missing, or lost index costs speed, never correctness. Searches schedule this lazily once
   * a table crosses the auto-index threshold; calling it directly is just a warm-up.
   */
  async buildFtsIndex(tableName: string, columnName: string): Promise<void> {
    const table = await this.#findTable(tableName);
    const column = table.columns.find((candidate) => candidate.name === columnName);
    if (column === undefined) throw new TypeError(`Unknown column: ${columnName}`);
    const key = `${table.id}/${column.id}`;
    if (this.#droppingFtsColumns.has(key)) {
      throw new TypeError(`Column is being dropped: ${tableName}.${columnName}`);
    }
    const existing = this.#ftsBuildsInFlight.get(key);
    if (existing !== undefined) return existing;
    const build = this.#buildFtsIndex(table, column);
    this.#ftsBuildsInFlight.set(key, build);
    try {
      await build;
    } finally {
      if (this.#ftsBuildsInFlight.get(key) === build) this.#ftsBuildsInFlight.delete(key);
    }
  }

  async #buildFtsIndex(table: TableRecord, column: TableColumnRecord): Promise<void> {
    const tableName = table.name;
    const columnName = column.name;
    if (this.#droppingFtsColumns.has(`${table.id}/${column.id}`)) {
      throw new TypeError(`Column is being dropped: ${tableName}.${columnName}`);
    }
    if (column.type === "boolean") {
      throw new TypeError(`Full-text indexes cannot cover boolean columns: ${columnName}`);
    }
    const stamp = (
      record: TableRecord,
      state: FtsColumnIndexRecord["state"],
      buildFromVersion: number,
    ): Promise<TableRecord> =>
      this.store.updateTable(record.id, record.revision, {
        ftsColumns: {
          ...record.ftsColumns,
          [column.id]: {
            storage: "fts-chunks-v1",
            tokenizerVersion: FTS_TOKENIZER_VERSION,
            state,
            buildFromVersion,
          },
        },
      });
    // From this flip on, every writer that reads the record emits commit deltas; writers that
    // committed against the older record flip the column to "invalid" in the store, which the
    // ready-CAS below observes as a revision conflict and abandons the build.
    const marked = await stamp(table, "building", -1);
    try {
      await this.#withLeasedSnapshot(undefined, async (snapshot) => {
        const segments = await this.#visibleSegmentRecords(marked, snapshot);
        if (segments.some((segment) => segment.kind !== "insert")) {
          await stamp(marked, "invalid", -1).catch(() => undefined);
          throw new TypeError(
            `Full-text indexes support append-only tables; ${tableName} has keyed mutations`,
          );
        }
        const buildId = this.#createId();
        const begin = this.#beginPostingBuild.bind(this);
        const writeChunk = this.#writePostingBuildChunk.bind(this);
        const finish = this.#finishPostingBuild.bind(this);
        const abort = this.#abortPostingBuild.bind(this);
        const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
        let totalTokens = 0;
        let pendingTokens = 0;
        let ordinal = 0;
        const flush = async (): Promise<void> => {
          if (byTerm.size === 0) return;
          for (const postings of chunkFtsPostings(sortedFtsPostings(byTerm))) {
            await writeChunk(table.id, column.id, buildId, ordinal, postings);
            ordinal += 1;
          }
          byTerm.clear();
          pendingTokens = 0;
        };
        await begin(table.id, column.id, buildId);
        try {
          for (const segment of segments) {
            const blockIds = segment.columnBlockIds[column.id];
            let segmentRow = 0;
            if (blockIds === undefined || blockIds.length === 0) {
              while (segmentRow < segment.rowCount) {
                const end = Math.min(segment.rowCount, segmentRow + this.#rowsPerBlock);
                for (; segmentRow < end; segmentRow += 1) {
                  const tokens = addFtsDocument(
                    byTerm,
                    column.backfill ?? null,
                    segment.rowIdStart + BigInt(segmentRow),
                  );
                  totalTokens = safeWholeNumberSum(
                    [totalTokens, tokens],
                    "Full-text base token count",
                  );
                  pendingTokens += tokens;
                  if (pendingTokens >= FTS_BUILD_POSTING_WINDOW) await flush();
                }
              }
              continue;
            }
            for (const blockId of blockIds) {
              await this.#renewInternalLeaseIfNeeded(snapshot);
              const [decoded] = await this.#decodedBlocksThroughCache([blockId], snapshot);
              if (decoded?.column.type !== column.type) {
                throw new Error(`Full-text source block is invalid: ${blockId}`);
              }
              const vector = this.#blockColumnVector(blockId, decoded);
              for (let row = 0; row < decoded.column.rowCount; row += 1) {
                const tokens = addFtsDocument(
                  byTerm,
                  vectorValue(vector, row),
                  segment.rowIdStart + BigInt(segmentRow),
                );
                totalTokens = safeWholeNumberSum(
                  [totalTokens, tokens],
                  "Full-text base token count",
                );
                pendingTokens += tokens;
                segmentRow += 1;
                if (pendingTokens >= FTS_BUILD_POSTING_WINDOW) await flush();
              }
            }
            if (segmentRow !== segment.rowCount) {
              throw new Error(`Full-text source row count differs in segment ${segment.id}`);
            }
          }
          await flush();
          await finish(table.id, column.id, buildId, {
            coversVersion: snapshot.version ?? -1,
            chunkCount: ordinal,
            totalTokens,
          });
        } catch (error) {
          await abort(table.id, column.id, buildId).catch(() => undefined);
          throw error;
        }
        const coversVersion = snapshot.version ?? -1;
        const fresh = await this.store.getTable(table.id);
        const current = fresh?.ftsColumns?.[column.id];
        if (fresh?.columns.some((candidate) => candidate.id === column.id) !== true) {
          // A concurrent DROP COLUMN won after this build took its snapshot. The catalog update
          // already removed any older index; remove the base this stale builder just wrote too.
          await this.store.removeFtsColumn(table.id, column.id);
          return;
        }
        if (current?.state === "building") {
          await this.store.updateTable(fresh.id, fresh.revision, {
            ftsColumns: {
              ...fresh.ftsColumns,
              [column.id]: { ...current, state: "ready", buildFromVersion: coversVersion },
            },
          });
        }
      });
    } catch (error) {
      // A failed build must never leave a catalog entry perpetually "building" or a partial
      // generation pinning chunks. Make scan-correctness durable first, then discard the cold
      // accelerator. A concurrent successful replacement is left untouched.
      const fresh = await this.store.getTable(table.id);
      const current = fresh?.ftsColumns?.[column.id];
      if (fresh !== undefined && current?.state === "building") {
        const invalidated = await this.store
          .updateTable(fresh.id, fresh.revision, {
            ftsColumns: {
              ...fresh.ftsColumns,
              [column.id]: { ...current, state: "invalid" },
            },
          })
          .then(() => true)
          .catch(() => false);
        if (invalidated)
          await this.store.removeFtsColumn(table.id, column.id).catch(() => undefined);
      } else if (current?.state === "invalid") {
        await this.store.removeFtsColumn(table.id, column.id).catch(() => undefined);
      }
      throw error;
    }
  }

  /**
   * The top block's BM25 nodes, deduplicated by their compiled signature — the same key the
   * executor's bind step uses, so served statistics land on exactly the nodes that asked.
   */
  #ftsBm25Nodes(plan: CompiledQuery): Map<string, { columns: Expression[]; query: string }> {
    const nodes = new Map<string, { columns: Expression[]; query: string }>();
    const visit = (expression: Expression): void => {
      if (expression.kind === "fts" && expression.op === "bm25" && expression.columns !== "*") {
        nodes.set(JSON.stringify(expression), {
          columns: expression.columns,
          query: expression.query,
        });
        return;
      }
      for (const child of childExpressions(expression)) visit(child);
    };
    forEachBlockExpression(plan, visit);
    return nodes;
  }

  /**
   * Whether the persisted index can serve exact BM25 statistics for every scoring node of the
   * plan. This single predicate is shared by the stats service and the segment pruner over the
   * same catalog snapshot, so "the scan was pruned" implies "statistics came from the index" —
   * the invariant that keeps scores identical whether or not an index exists.
   */
  #ftsIndexServesScoring(
    plan: CompiledQuery,
    table: TableRecord,
    segments: readonly SegmentRecord[],
  ): boolean {
    if (plan.joins.length > 0 || plan.base.table !== table.name) return false;
    if (!segments.every((segment) => segment.kind === "insert")) return false;
    const columnsByName = new Map(table.columns.map((column) => [column.name, column] as const));
    for (const node of this.#ftsBm25Nodes(plan).values()) {
      for (const expression of node.columns) {
        if (expression.kind !== "column") return false;
        const column = columnsByName.get(
          expression.reference.split(".").at(-1) ?? expression.reference,
        );
        const state = column === undefined ? undefined : table.ftsColumns?.[column.id];
        if (state?.state !== "ready" || state.tokenizerVersion !== FTS_TOKENIZER_VERSION) {
          return false;
        }
      }
    }
    return true;
  }

  /**
   * One postings read per (column, terms) per snapshot: the statistics service and the segment
   * pruner ask for the same candidates in the canonical search shape, and sharing the promise
   * both halves the index I/O and guarantees the two make identical freshness decisions.
   */
  #readFtsCandidatesMemoized(
    snapshot: Snapshot,
    tableId: string,
    columnId: string,
    terms: readonly FtsPostingQuery[],
    upToVersion: number,
  ): Promise<FtsCandidatesResult> {
    let memo = this.#ftsCandidatesMemo.get(snapshot);
    if (memo === undefined) {
      memo = new Map();
      this.#ftsCandidatesMemo.set(snapshot, memo);
    }
    const key = `${tableId}\u0000${columnId}\u0000${String(upToVersion)}\u0000${JSON.stringify(terms)}`;
    const cacheable =
      key.length <= MAX_CACHEABLE_TEXT_CHARACTERS &&
      terms.every((term) => !("term" in term) || term.term.length <= MAX_CACHEABLE_TEXT_CHARACTERS);
    if (!cacheable) {
      return this.store.readFtsCandidates(
        tableId,
        columnId,
        terms,
        upToVersion,
        MAX_FTS_CANDIDATE_ROW_IDS,
      );
    }
    const cached = memo.get(key);
    if (cached !== undefined) return cached;
    // The result is a function of the postings at one version, so it is also pooled across
    // snapshots: a repeated point lookup then skips the chunk read and validation entirely.
    const pooled = this.#cacheGet(`ftc\0${key}`) as FtsCandidatesResult | undefined;
    if (pooled !== undefined) return Promise.resolve(pooled);
    // Shared leases live across queries at one version; results are version-deterministic, but
    // candidate arrays can be large, so the memo sheds wholesale rather than growing unbounded.
    if (memo.size >= 1) memo.clear();
    const read = this.store
      .readFtsCandidates(tableId, columnId, terms, upToVersion, MAX_FTS_CANDIDATE_ROW_IDS)
      .then((result) => {
        const rowIds = result.rowIdsByTerm.reduce((total, ids) => total + ids.length, 0);
        // Only a complete answer is pooled: a missing base or a build past the asked version
        // is transient state the next read must observe again, not a fact about the version.
        if (
          result.hasBase &&
          !result.overflow &&
          result.coversVersion <= upToVersion &&
          rowIds <= MAX_POOLED_FTS_CANDIDATE_ROW_IDS
        ) {
          this.#cachePut(`ftc\0${key}`, result, 128 + key.length * 2 + rowIds * 16);
        }
        return result;
      });
    memo.set(key, read);
    return read;
  }

  /**
   * Exact BM25 corpus statistics from the postings index, keyed by node signature, or
   * undefined when any scoring node cannot be served (the scan then computes its own).
   * docCount is the visible row count (every row is a document); per-term document frequency
   * is the size of the union of the term's posting row ids across the document's columns; and
   * token totals merge from the base plus commit deltas. All exact for append-only histories —
   * including under time travel or a concurrent rebuild, because a base covering a version
   * ahead of this snapshot disqualifies the index here (and, through the shared reads, in the
   * pruner) rather than mixing corpora.
   */
  async #ftsIndexStats(
    plan: CompiledQuery,
    realTables: ReadonlyMap<string, TableRecord>,
    snapshot: LeasedSnapshot,
    visibility?: SegmentVisibilityCatalog,
  ): Promise<Map<string, FtsStats> | undefined> {
    if (!planContainsFts(plan, "bm25")) return undefined;
    const table = realTables.get(plan.base.table);
    if (table === undefined) return undefined;
    const nodes = this.#ftsBm25Nodes(plan);
    if (nodes.size === 0) return undefined;
    const segments = await this.#visibleSegmentRecords(table, snapshot, visibility);
    if (!this.#ftsIndexServesScoring(plan, table, segments)) return undefined;
    const docCount = segments.reduce((total, segment) => total + segment.rowCount, 0);
    const columnsByName = new Map(table.columns.map((column) => [column.name, column] as const));
    const upToVersion = snapshot.version ?? -1;
    const stats = new Map<string, FtsStats>();
    for (const [signature, node] of nodes) {
      const terms = cachedQueryTerms(node.query);
      const columns = node.columns.map((expression) =>
        expression.kind === "column"
          ? columnsByName.get(expression.reference.split(".").at(-1) ?? expression.reference)
          : undefined,
      );
      if (columns.some((column) => column === undefined)) return undefined;
      const perColumn = await Promise.all(
        (columns as TableColumnRecord[]).map((column) =>
          this.#readFtsCandidatesMemoized(snapshot, table.id, column.id, terms, upToVersion),
        ),
      );
      if (
        perColumn.some(
          (result) => result.overflow || !result.hasBase || result.coversVersion > upToVersion,
        )
      ) {
        return undefined;
      }
      if (perColumn.some((result) => result.deltaChunkCount > FTS_FOLD_DELTA_CHUNKS)) {
        this.#scheduleFtsBuilds(table, columns as TableColumnRecord[], segments, true);
      }
      const dfByTerm = terms.map(
        (_, term) =>
          unionSortedRowIds(perColumn.map((result) => result.rowIdsByTerm[term] ?? [])).length,
      );
      stats.set(signature, {
        docCount,
        totalTokens: perColumn.reduce((total, result) => total + result.totalTokens, 0),
        dfByTerm,
      });
    }
    return stats;
  }

  async #ftsPrunedSegments(
    table: TableRecord,
    segments: SegmentRecord[],
    plan: CompiledQuery,
    snapshot: LeasedSnapshot,
  ): Promise<SegmentRecord[]> {
    if (plan.joins.length > 0 || plan.base.table !== table.name) return segments;
    const matches = topLevelFtsMatchConjuncts(plan);
    if (matches.length === 0) return segments;
    if (!segments.every((segment) => segment.kind === "insert")) return segments;
    // A scoring plan may only prune when the index serves its corpus statistics — otherwise
    // the scan-side stats pass would measure a shrunken corpus and scores would change the
    // moment an index appeared. The shared predicate keeps this in lockstep with the stats
    // service reading the same catalog snapshot.
    if (planContainsFts(plan, "bm25") && !this.#ftsIndexServesScoring(plan, table, segments)) {
      return segments;
    }
    const columnsByName = new Map(table.columns.map((column) => [column.name, column] as const));
    let surviving = segments;
    for (const match of matches) {
      const terms = cachedQueryTerms(match.query);
      if (terms.length === 0) continue;
      const columns = match.columns.flatMap((expression) =>
        expression.kind === "column"
          ? [columnsByName.get(expression.reference.split(".").at(-1) ?? expression.reference)]
          : [undefined],
      );
      if (columns.some((column) => column === undefined)) continue;
      const resolved = columns as TableColumnRecord[];
      const ready = resolved.every((column) => {
        const state = table.ftsColumns?.[column.id];
        return state?.state === "ready" && state.tokenizerVersion === FTS_TOKENIZER_VERSION;
      });
      if (!ready) {
        this.#scheduleFtsBuilds(
          table,
          resolved,
          segments,
          resolved.some((column) => table.ftsColumns?.[column.id] !== undefined),
        );
        continue;
      }
      const upToVersion = snapshot.version ?? -1;
      const perColumn = await Promise.all(
        resolved.map((column) =>
          this.#readFtsCandidatesMemoized(snapshot, table.id, column.id, terms, upToVersion),
        ),
      );
      if (perColumn.some((result) => result.overflow)) return segments;
      if (perColumn.some((result) => !result.hasBase)) {
        this.#scheduleFtsBuilds(table, resolved, segments, true);
        return segments;
      }
      // A base rebuilt past this snapshot yields a candidate SUPERSET — safe for match-only
      // pruning, but a scoring plan's statistics would have bailed on the same shared reads,
      // so pruning must bail with them to keep "pruned ⟹ statistics served".
      if (
        planContainsFts(plan, "bm25") &&
        perColumn.some((result) => result.coversVersion > upToVersion)
      ) {
        return segments;
      }
      // A long delta tail re-merges on every read; folding is just a rebuild at a newer version.
      if (perColumn.some((result) => result.deltaChunkCount > FTS_FOLD_DELTA_CHUNKS)) {
        this.#scheduleFtsBuilds(table, resolved, segments, true);
      }
      // Document semantics over sorted candidate arrays: per term, union across the document's
      // columns; across terms, intersection. Both are linear merges, and the segment filter is
      // then one binary search per segment — no per-candidate scans.
      let candidates: bigint[] | undefined;
      for (let term = 0; term < terms.length; term += 1) {
        const union = unionSortedRowIds(perColumn.map((result) => result.rowIdsByTerm[term] ?? []));
        candidates = candidates === undefined ? union : intersectSortedRowIds(candidates, union);
        if (candidates.length === 0) break;
      }
      const candidateList = candidates ?? [];
      surviving =
        candidateList.length === 0
          ? []
          : surviving.filter((segment) =>
              sortedRowIdsIntersectRange(
                candidateList,
                segment.rowIdStart,
                segment.rowIdEndExclusive,
              ),
            );
      if (surviving.length === 0) break;
    }
    return surviving;
  }

  /**
   * Row-group pruning from ready scalar indexes. Base postings plus bounded commit deltas yield
   * stable row locators; the locator selects blocks, and the ordinary executor still evaluates
   * every SQL predicate in each surviving row. Stale entries therefore cost I/O only.
   */
  async #secondaryIndexPrunedSegments(
    table: TableRecord,
    segments: SegmentRecord[],
    plan: CompiledQuery,
    snapshot: LeasedSnapshot,
  ): Promise<{ segments: SegmentRecord[]; pruned: boolean; rows?: number[] }> {
    const predicates = secondaryIndexPredicates(plan, table);
    if (predicates.length === 0) {
      // A killed build or a stale-writer invalidation self-heals on the next relevant query.
      for (const [indexId, index] of Object.entries(table.secondaryIndexes ?? {})) {
        if (index.state === "ready") continue;
        if (
          !secondaryIndexColumnIds(index).some((columnId) =>
            planReferencesColumn(plan, table, columnId),
          )
        ) {
          continue;
        }
        this.#scheduleSecondaryIndexBuild(table, indexId);
      }
      return { segments, pruned: false };
    }
    if (segments.some((segment) => segment.kind === "upsert")) {
      return { segments, pruned: false };
    }
    const keyColumn = getUniqueKeyColumn(table);
    if (keyColumn === undefined) {
      if (
        segments.some((segment) => {
          const kind = segment.kind;
          return kind !== "insert" && kind !== "base";
        })
      ) {
        return { segments, pruned: false };
      }
      if (predicates.some((predicate) => predicate.index.locator !== "row-id")) {
        return { segments, pruned: false };
      }
    } else if (predicates.some((predicate) => predicate.index.locator !== "key-hash-v1")) {
      return { segments, pruned: false };
    }

    // A postings lookup can only repay itself by eliminating a physical row group. Small OLTP
    // tables commonly fit in one block; probing the durable index and mapping its key locators
    // back through that same block adds work but cannot reduce I/O. Let the ordinary cached block
    // scan answer those tables directly. Multiple one-block segments still qualify because the
    // index can eliminate whole segments.
    const anchorColumn = keyColumn ?? table.columns[0];
    if (
      anchorColumn === undefined ||
      segments.reduce(
        (total, segment) => total + (segment.columnBlockIds[anchorColumn.id]?.length ?? 0),
        0,
      ) <= 1
    ) {
      return { segments, pruned: false };
    }

    const upToVersion = snapshot.version ?? -1;
    let candidates: bigint[] | undefined;
    for (const predicate of predicates) {
      const result = await this.#readFtsCandidatesMemoized(
        snapshot,
        table.id,
        predicate.index.storageColumnId,
        predicate.queries,
        upToVersion,
      );
      if (result.overflow) return { segments, pruned: false };
      if (!result.hasBase) {
        this.#scheduleSecondaryIndexBuild(table, predicate.indexId);
        return { segments, pruned: false };
      }
      // A newer rebuild may omit rows an old time-travel snapshot still saw.
      if (result.coversVersion > upToVersion) return { segments, pruned: false };
      if (result.deltaChunkCount > FTS_FOLD_DELTA_CHUNKS) {
        this.#scheduleSecondaryIndexBuild(table, predicate.indexId);
      }
      const forPredicate = predicate.union
        ? unionSortedRowIds(result.rowIdsByTerm)
        : (result.rowIdsByTerm[0] ?? []);
      candidates =
        candidates === undefined ? forPredicate : intersectSortedRowIds(candidates, forPredicate);
      if (candidates.length === 0) return { segments: [], pruned: true };
    }
    if (candidates === undefined) return { segments, pruned: false };
    const candidateSet = keyColumn === undefined ? undefined : new Set(candidates);
    // With a key column and only appended segments, the block locator maps give the exact scan
    // rows, in the streamed scan's numbering over the kept blocks: an equality lookup then
    // visits a handful of rows instead of every block that holds one. Mutation segments replay
    // keys and renumber rows, so they keep block-level pruning. A very wide candidate list is
    // cheaper to scan than to probe.
    // Positions count the scan segments' kept rows only; update and delete deltas are replayed
    // over that numbering by the streamed mutation table, which remaps the selection past the
    // rows the deltas removed.
    const rowPositions: number[] | undefined =
      keyColumn !== undefined &&
      candidates.length <= SECONDARY_INDEX_ROW_SELECTION_CAP &&
      segments.every(
        (segment) =>
          segment.kind === "insert" ||
          segment.kind === "base" ||
          segment.kind === "update" ||
          segment.kind === "delete",
      )
        ? []
        : undefined;
    let selectedRowStart = 0;
    const selected: SegmentRecord[] = [];
    for (const segment of segments) {
      const anchorColumn = keyColumn ?? table.columns[0];
      if (anchorColumn === undefined) return { segments, pruned: false };
      const anchorIds = segment.columnBlockIds[anchorColumn.id] ?? [];
      if (anchorIds.length === 0 && segment.rowCount > 0) return { segments, pruned: false };
      if (Object.values(segment.columnBlockIds).some((ids) => ids.length !== anchorIds.length)) {
        return { segments, pruned: false };
      }
      const blockIndexes: number[] = [];
      const rowCounts: number[] = [];
      let rowStart = 0;
      if (keyColumn === undefined) {
        const descriptions = await this.#zoneDescriptions(anchorIds, snapshot);
        for (const [blockIndex, blockId] of anchorIds.entries()) {
          const rowCount = descriptions.get(blockId)?.rowCount;
          if (rowCount === undefined) return { segments, pruned: false };
          if (segmentRowsIntersectLocators(segment, rowStart, rowCount, candidates)) {
            blockIndexes.push(blockIndex);
            rowCounts.push(rowCount);
          }
          rowStart += rowCount;
        }
      } else {
        const decoded = await this.#decodedBlocksThroughCache(anchorIds, snapshot);
        for (const [blockIndex, block] of decoded.entries()) {
          if (block.column.type !== keyColumn.type) {
            return { segments, pruned: false };
          }
          const blockId = anchorIds[blockIndex] ?? "";
          const vector = this.#blockColumnVector(blockId, block);
          // A block's key locators are a pure function of its immutable bytes, so they are
          // hashed once and pooled; a lookup then probes the (few) candidates against the
          // block's set instead of re-hashing every stored key on every query. A candidate
          // list wider than the block walks the block's locators against the candidate set.
          const locators = this.#blockKeyLocators(blockId, vector, keyColumn.type);
          const positions: number[] = [];
          const collect = (hit: number | number[] | undefined): boolean => {
            if (hit === undefined) return false;
            if (typeof hit === "number") positions.push(hit);
            else positions.push(...hit);
            return rowPositions === undefined;
          };
          if (candidates.length <= locators.size) {
            for (const candidate of candidates) if (collect(locators.get(candidate))) break;
          } else if (candidateSet !== undefined) {
            for (const [locator, hit] of locators) {
              if (candidateSet.has(locator) && collect(hit)) break;
            }
          }
          if (positions.length > 0) {
            if (
              rowPositions !== undefined &&
              (segment.kind === "insert" || segment.kind === "base")
            ) {
              positions.sort((a, b) => a - b);
              const keptRows = rowCounts.reduce((total, count) => total + count, 0);
              for (const position of positions) {
                rowPositions.push(selectedRowStart + keptRows + position);
              }
            }
            blockIndexes.push(blockIndex);
            rowCounts.push(vector.length);
          }
          rowStart += vector.length;
        }
      }
      if (rowStart !== segment.rowCount) return { segments, pruned: false };
      if (blockIndexes.length === 0) continue;
      const keptRowCount = rowCounts.reduce((total, count) => total + count, 0);
      if (segment.kind === "insert" || segment.kind === "base") selectedRowStart += keptRowCount;
      selected.push({
        ...segment,
        rowCount: keptRowCount,
        columnBlockIds: Object.fromEntries(
          Object.entries(segment.columnBlockIds).map(([columnId, ids]) => [
            columnId,
            blockIndexes.map((blockIndex) => ids[blockIndex] ?? ""),
          ]),
        ),
      });
    }
    return rowPositions === undefined
      ? { segments: selected, pruned: true }
      : { segments: selected, pruned: true, rows: rowPositions };
  }

  #scheduleSecondaryIndexBuild(table: TableRecord, indexId: string): void {
    if (this.#closed) return;
    const index = table.secondaryIndexes?.[indexId];
    if (index === undefined) return;
    const key = `${table.id}/${index.storageColumnId}`;
    if (this.#ftsBuildsInFlight.has(key)) return;
    const build = this.#buildSecondaryIndexBase(table, indexId, index)
      .catch(() => undefined)
      .finally(() => {
        if (this.#ftsBuildsInFlight.get(key) === build) this.#ftsBuildsInFlight.delete(key);
      });
    this.#ftsBuildsInFlight.set(key, build);
    void build;
  }

  /**
   * Fire-and-forget lazy index builds. Keys release when the attempt settles, so a failed or
   * lost build (including a column durably stuck in "building" after a killed tab) retries on
   * the next search rather than wedging for the session.
   */
  #scheduleFtsBuilds(
    table: TableRecord,
    columns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    rebuild = false,
  ): void {
    if (this.#closed) return;
    const rowCount = segments.reduce((total, segment) => total + segment.rowCount, 0);
    if (!rebuild && rowCount < this.#ftsAutoIndexRows) return;
    for (const column of columns) {
      const key = `${table.id}/${column.id}`;
      if (this.#ftsBuildsInFlight.has(key)) continue;
      const build = this.#buildFtsIndex(table, column)
        .catch(() => undefined)
        .finally(() => {
          if (this.#ftsBuildsInFlight.get(key) === build) this.#ftsBuildsInFlight.delete(key);
        });
      this.#ftsBuildsInFlight.set(key, build);
      void build;
    }
  }

  /**
   * A commit can grow a ready index's persistent delta tail without any later search to notice.
   * Storage returns the authoritative tail length with the commit, so whichever tab crosses the
   * bound rebuilds it. This keeps both the record count and per-read merge work bounded without
   * adding a catalog probe to ordinary writes.
   */
  #scheduleFtsDeltaFold(tableId: string, columnId: string): void {
    if (this.#closed) return;
    const key = `${tableId}/${columnId}`;
    if (this.#ftsBuildsInFlight.has(key)) return;
    let observedCount: number | undefined;
    let invalidated = false;
    const build = (async () => {
      try {
        const table = await this.store.getTable(tableId);
        // Once scheduled, finish even if close() starts: close joins this promise specifically so
        // the durable tail reaches its bound before the caller closes the store.
        if (table === undefined) {
          invalidated = true;
          this.#postingDeltaTailCounts.delete(key);
          return;
        }
        const state = table.ftsColumns?.[columnId];
        if (state !== undefined && state.state !== "invalid") {
          const column = table.columns.find((candidate) => candidate.id === columnId);
          if (column !== undefined) await this.#buildFtsIndex(table, column);
        } else {
          const secondary = Object.entries(table.secondaryIndexes ?? {}).find(
            ([, index]) => index.storageColumnId === columnId && index.state !== "invalid",
          );
          if (secondary !== undefined) {
            await this.#buildSecondaryIndexBase(table, secondary[0], secondary[1]);
          } else {
            invalidated = true;
            this.#postingDeltaTailCounts.delete(key);
            return;
          }
        }
        const version = (await this.store.getCurrentManifestVersion()) ?? -1;
        observedCount = (await this.store.readFtsCandidates(tableId, columnId, [], version))
          .deltaChunkCount;
        this.#postingDeltaTailCounts.set(key, observedCount);
      } catch {
        if ((this.#postingDeltaTailCounts.get(key) ?? 0) >= FTS_HARD_DELTA_CHUNKS) {
          try {
            await this.#invalidateOversizedPostingTail(tableId, columnId);
            invalidated = true;
            this.#postingDeltaTailCounts.delete(key);
          } catch {
            // Keep the hard-threshold marker. A later commit or relevant read will retry; losing
            // it here would turn a transient catalog/cleanup refusal into silent unbounded growth.
          }
        }
      }
    })().finally(() => {
      if (this.#ftsBuildsInFlight.get(key) === build) this.#ftsBuildsInFlight.delete(key);
      if (!invalidated && observedCount !== undefined && observedCount <= FTS_FOLD_DELTA_CHUNKS) {
        this.#postingDeltaTailCounts.delete(key);
      }
    });
    this.#ftsBuildsInFlight.set(key, build);
    void build;
  }

  /**
   * Turns a persistently unhealthy accelerator into a scan-correct catalog state before
   * deleting its bounded base/delta storage. UNIQUE membership is a separate namespace and is
   * deliberately untouched. A later relevant query can rebuild the invalid accelerator.
   */
  async #invalidateOversizedPostingTail(tableId: string, columnId: string): Promise<void> {
    for (let attempt = 0; attempt <= this.#maxCommitRetries; attempt += 1) {
      const table = await this.store.getTable(tableId);
      if (table === undefined) return;
      const fts = table.ftsColumns?.[columnId];
      const secondary = Object.entries(table.secondaryIndexes ?? {}).find(
        ([, index]) => index.storageColumnId === columnId,
      );
      if (fts === undefined && secondary === undefined) return;
      if (fts?.state === "invalid" || secondary?.[1].state === "invalid") break;
      try {
        if (fts !== undefined) {
          await this.store.updateTable(table.id, table.revision, {
            ftsColumns: {
              ...table.ftsColumns,
              [columnId]: { ...fts, state: "invalid", buildFromVersion: -1 },
            },
          });
        } else if (secondary !== undefined) {
          const [indexId, index] = secondary;
          const { buildId: _buildId, ...stable } = index;
          void _buildId;
          await this.store.updateTable(table.id, table.revision, {
            secondaryIndexes: {
              ...table.secondaryIndexes,
              [indexId]: { ...stable, state: "invalid", buildFromVersion: -1 },
            },
          });
        }
        break;
      } catch (error) {
        if (!(error instanceof TableRecordConflictError) || attempt === this.#maxCommitRetries) {
          throw error;
        }
      }
    }
    await this.store.removeFtsColumn(tableId, columnId);
  }

  async #materializeColumnarTableAtSnapshot(
    table: TableRecord,
    snapshot: LeasedSnapshot,
    projectedColumns: readonly TableColumnRecord[],
    visibility?: SegmentVisibilityCatalog,
    plan?: CompiledQuery,
  ): Promise<ColumnarTable> {
    const visibleSegments = await this.#visibleSegmentRecords(table, snapshot, visibility);
    if (plan !== undefined) {
      const covering = await this.#secondaryIndexCoveringTable(
        table,
        projectedColumns,
        visibleSegments,
        plan,
        snapshot,
      );
      if (covering !== undefined) return covering;
    }
    const ftsSegments =
      plan === undefined
        ? visibleSegments
        : await this.#ftsPrunedSegments(table, visibleSegments, plan, snapshot);
    const indexed =
      plan === undefined
        ? { segments: ftsSegments, pruned: false }
        : await this.#secondaryIndexPrunedSegments(table, ftsSegments, plan, snapshot);
    const segments = indexed.segments;
    const keyColumn = getUniqueKeyColumn(table);
    if (
      segments.every((segment) => {
        const kind = segment.kind;
        return kind === "insert" || kind === "base";
      })
    ) {
      const rowCount = segments.reduce((total, segment) => total + segment.rowCount, 0);
      if (projectedColumns.length === 0) {
        return { name: table.name, rowCount, columns: new Map() };
      }
      const projectedKey =
        keyColumn !== undefined && projectedColumns.some((column) => column.id === keyColumn.id)
          ? keyColumn.name
          : undefined;
      // An exact row selection materializes just those rows: a join side narrowed to a handful
      // of rows is then a handful of rows, not a table's worth of decoded columns. The rows
      // come from a secondary index, or from the unique key itself when the plan pins it to
      // literals (zone maps and sorted-run search locate them without an index).
      if (keyColumn !== undefined) {
        const rows =
          indexed.rows ??
          (plan === undefined
            ? undefined
            : await this.#uniqueKeyRowSelection(table, keyColumn, segments, plan, snapshot));
        if (rows !== undefined) {
          const selected = await this.#materializeSelectedRows(
            table,
            keyColumn,
            projectedColumns,
            segments,
            rows,
            snapshot,
            projectedKey,
          );
          if (selected !== undefined) return selected;
        }
      }
      // Zone-map pruning shrinks the scan the same way index pruning does, so a scoring plan
      // whose statistics come from the scan (no index serving it) must see the whole corpus.
      const zonePruningAllowed =
        plan === undefined ||
        !planContainsFts(plan, "bm25") ||
        this.#ftsIndexServesScoring(plan, table, visibleSegments);
      const predicates =
        plan === undefined || !zonePruningAllowed ? [] : zonePredicates(plan, table);
      if (predicates.length > 0) {
        const pruned = await this.#materializePrunedAppendTable(
          table,
          snapshot,
          projectedColumns,
          segments,
          predicates,
        );
        if (pruned !== undefined) return pruned;
      }
      const columns = new Map<string, ColumnVector>();
      for (const column of projectedColumns) {
        columns.set(
          column.name,
          await this.#materializeAppendColumnVector(column, segments, snapshot, rowCount),
        );
      }
      const materialized: ColumnarTable = {
        name: table.name,
        rowCount,
        columns,
        ...(projectedKey ? { uniqueKey: projectedKey } : {}),
      };
      return plan === undefined
        ? materialized
        : ((await this.#secondaryIndexOrderedTable(
            table,
            materialized,
            segments,
            plan,
            snapshot,
          )) ?? materialized);
    }
    if (
      keyColumn !== undefined &&
      segments.every((segment) => {
        const kind = segment.kind;
        return kind === "insert" || kind === "base" || kind === "delete" || kind === "update";
      })
    ) {
      const overlay = await this.#materializeOverlayTable(
        table,
        snapshot,
        projectedColumns,
        segments,
        keyColumn,
        plan,
        indexed.pruned,
      );
      if (overlay !== undefined) return overlay;
    }
    const neededColumns = [
      ...projectedColumns,
      ...(keyColumn === undefined || projectedColumns.some((column) => column.id === keyColumn.id)
        ? []
        : [keyColumn]),
    ];
    const maximumRows = segments.reduce((total, segment) => {
      const kind = segment.kind;
      return (
        total + (kind === "insert" || kind === "base" || kind === "upsert" ? segment.rowCount : 0)
      );
    }, 0);
    const vectorsByColumn = new Map(
      neededColumns.map((column) => {
        const vector = createEmptyColumnVector(column.type, maximumRows);
        // Seeded, not filled per segment: replay overwrites a slot whenever a segment carries
        // the column, so what survives is exactly the rows no segment ever wrote it for.
        if (column.backfill !== undefined) {
          fillColumnVectorRange(vector, 0, maximumRows, column.backfill);
        }
        return [column.id, vector] as const;
      }),
    );
    const dictionaryIndexes = new Map(
      neededColumns
        .filter((column) => column.type === "string")
        .map((column) => [column.id, new Map<string, number>()] as const),
    );
    const alive = new Uint8Array(maximumRows);
    const rowIndexByKey = new Map<string, number>();
    let slotCount = 0;

    for (const segment of segments) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const segmentVectors = new Map<string, ColumnVector>();
      for (const column of neededColumns) {
        if ((segment.columnBlockIds[column.id]?.length ?? 0) === 0) continue;
        segmentVectors.set(
          column.id,
          await this.#materializeAppendColumnVector(column, [segment], snapshot, segment.rowCount),
        );
      }
      if (segment.kind === "delete") {
        if (keyColumn === undefined)
          throw new Error(`Delete segment has no unique key: ${segment.id}`);
        const keyVector = requiredColumnVector(segmentVectors, keyColumn, segment);
        for (let row = 0; row < segment.rowCount; row += 1) {
          const token = columnVectorKeyToken(keyColumn.type, keyVector, row);
          const existingIndex = rowIndexByKey.get(token);
          if (existingIndex !== undefined) alive[existingIndex] = 0;
          rowIndexByKey.delete(token);
        }
        continue;
      }
      if (segment.kind === "update") {
        if (keyColumn === undefined)
          throw new Error(`Update segment has no unique key: ${segment.id}`);
        const keyVector = requiredColumnVector(segmentVectors, keyColumn, segment);
        const changedColumns = projectedColumns.filter(
          (column) =>
            column.id !== keyColumn.id && (segment.columnBlockIds[column.id]?.length ?? 0) > 0,
        );
        for (let row = 0; row < segment.rowCount; row += 1) {
          const existingIndex = rowIndexByKey.get(
            columnVectorKeyToken(keyColumn.type, keyVector, row),
          );
          if (existingIndex === undefined || alive[existingIndex] !== 1) {
            throw new Error(`Update segment references a missing key: ${segment.id}`);
          }
          for (const column of changedColumns) {
            copyColumnVectorValue(
              requiredColumnVector(segmentVectors, column, segment),
              row,
              requiredColumnVector(vectorsByColumn, column, segment),
              existingIndex,
              dictionaryIndexes.get(column.id),
            );
          }
        }
        continue;
      }

      for (let segmentRow = 0; segmentRow < segment.rowCount; segmentRow += 1) {
        let existingIndex: number | undefined;
        let token: string | undefined;
        if (keyColumn !== undefined) {
          token = columnVectorKeyToken(
            keyColumn.type,
            requiredColumnVector(segmentVectors, keyColumn, segment),
            segmentRow,
          );
          existingIndex = rowIndexByKey.get(token);
        }
        if (segment.kind === "upsert" && existingIndex !== undefined) {
          for (const column of neededColumns) {
            // A column absent from this segment joined the catalog later; the replayed slot
            // keeps its NULL default. Older segments always replay before newer ones, so an
            // absent-column segment can never overwrite a value written with the column.
            if (segment.columnBlockIds[column.id] === undefined) continue;
            copyColumnVectorValue(
              requiredColumnVector(segmentVectors, column, segment),
              segmentRow,
              requiredColumnVector(vectorsByColumn, column, segment),
              existingIndex,
              dictionaryIndexes.get(column.id),
            );
          }
          alive[existingIndex] = 1;
          continue;
        }
        if (existingIndex !== undefined) {
          throw new Error(`Stored table contains a duplicate unique key: ${table.name}`);
        }
        const outputIndex = slotCount;
        for (const column of neededColumns) {
          if (segment.columnBlockIds[column.id] === undefined) continue;
          copyColumnVectorValue(
            requiredColumnVector(segmentVectors, column, segment),
            segmentRow,
            requiredColumnVector(vectorsByColumn, column, segment),
            outputIndex,
            dictionaryIndexes.get(column.id),
          );
        }
        alive[outputIndex] = 1;
        slotCount += 1;
        if (token !== undefined) rowIndexByKey.set(token, outputIndex);
      }
    }

    let visibleRowCount = 0;
    for (let row = 0; row < slotCount; row += 1) visibleRowCount += alive[row] ?? 0;
    if (projectedColumns.length === 0) {
      return { name: table.name, rowCount: visibleRowCount, columns: new Map() };
    }
    const columns = new Map<string, ColumnVector>();
    for (const column of projectedColumns) {
      const source = requiredColumnVector(vectorsByColumn, column);
      const output = createEmptyColumnVector(column.type, visibleRowCount);
      const outputDictionaryIndex =
        column.type === "string" ? new Map<string, number>() : undefined;
      let outputRow = 0;
      for (let sourceRow = 0; sourceRow < slotCount; sourceRow += 1) {
        if (alive[sourceRow] !== 1) continue;
        copyColumnVectorValue(source, sourceRow, output, outputRow, outputDictionaryIndex);
        outputRow += 1;
      }
      columns.set(column.name, output);
    }
    const projectedKey =
      keyColumn !== undefined && projectedColumns.some((column) => column.id === keyColumn.id)
        ? keyColumn.name
        : undefined;
    return {
      name: table.name,
      rowCount: visibleRowCount,
      columns,
      ...(projectedKey ? { uniqueKey: projectedKey } : {}),
    };
  }

  /**
   * Exact covering scan for an append-only keyless table. Tuple terms carry every requested
   * value, and row-ID cardinality/span checks prove the ready index covers this snapshot before
   * table blocks are skipped. Any uncertainty falls back to the ordinary scan.
   */
  async #secondaryIndexCoveringTable(
    table: TableRecord,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    plan: CompiledQuery,
    snapshot: LeasedSnapshot,
  ): Promise<ColumnarTable | undefined> {
    const ordered = secondaryIndexOrderForPlan(plan, table, projectedColumns);
    if (ordered === undefined || table.uniqueKeyColumnId !== undefined) return undefined;
    if (
      segments.some((segment) => {
        const kind = segment.kind;
        return kind !== "insert" && kind !== "base";
      })
    ) {
      return undefined;
    }
    const expectedRows = segments.reduce((total, segment) => total + segment.rowCount, 0);
    if (expectedRows > MAX_FTS_CANDIDATE_ROW_IDS) return undefined;
    const result = await this.store.readFtsPostings(
      table.id,
      ordered.index.storageColumnId,
      snapshot.version ?? -1,
      MAX_FTS_CANDIDATE_ROW_IDS,
    );
    const rebuild = (): undefined => {
      this.#scheduleSecondaryIndexBuild(table, ordered.indexId);
      return undefined;
    };
    if (result.overflow || !result.hasBase) return rebuild();
    if (result.coversVersion > (snapshot.version ?? -1)) return undefined;
    if (result.deltaChunkCount > FTS_FOLD_DELTA_CHUNKS) {
      this.#scheduleSecondaryIndexBuild(table, ordered.indexId);
    }
    const indexColumns = secondaryIndexColumnIds(ordered.index).map((columnId) =>
      table.columns.find((column) => column.id === columnId),
    );
    if (indexColumns.some((column) => column === undefined)) return rebuild();
    const columns = indexColumns as TableColumnRecord[];
    const postings = ordered.reverse ? [...result.postings].reverse() : result.postings;
    const rowForLocator = appendRowForLocator(segments, expectedRows);
    // A byte per visible row is substantially smaller than retaining every bigint locator in a
    // Set, and the inverse span lookup also proves that each posting names a real current row.
    const seenRows = new Uint8Array(expectedRows);
    let seenRowCount = 0;
    const valuesById = new Map(projectedColumns.map((column) => [column.id, [] as BatchValue[]]));
    for (const posting of postings) {
      const values = decodeSecondaryTupleTerm(ordered.index, columns, posting.term);
      for (const locator of posting.rowIds) {
        const row = rowForLocator(locator);
        if (row === undefined || seenRows[row] === 1) return rebuild();
        seenRows[row] = 1;
        seenRowCount += 1;
        for (const [position, column] of columns.entries()) {
          valuesById.get(column.id)?.push(values[position] ?? null);
        }
      }
    }
    if (seenRowCount !== expectedRows) return rebuild();
    const columnInputs = new Map(
      projectedColumns.map(
        (column) =>
          [
            column.name,
            {
              type: column.type,
              values:
                column.type === "string" && column.sqlDomain === undefined
                  ? (valuesById.get(column.id) ?? []).map((value) =>
                      typeof value === "string" ? protectedSqlTextValue(value) : value,
                    )
                  : (valuesById.get(column.id) ?? []),
            },
          ] as const,
      ),
    );
    return { ...createColumnarTable(table.name, columnInputs), orderedForPlan: true };
  }

  /** Index order over ordinary table vectors when the projection is not covered by the key. */
  async #secondaryIndexOrderedTable(
    table: TableRecord,
    materialized: ColumnarTable,
    segments: readonly SegmentRecord[],
    plan: CompiledQuery,
    snapshot: LeasedSnapshot,
  ): Promise<ColumnarTable | undefined> {
    if (plan.predicates.length > 0 || table.uniqueKeyColumnId !== undefined) return undefined;
    const projectedColumns = [...materialized.columns.keys()].flatMap((name) => {
      const column = table.columns.find((candidate) => candidate.name === name);
      return column === undefined ? [] : [column];
    });
    const ordered = secondaryIndexOrderForPlan(plan, table, projectedColumns, false);
    if (ordered === undefined) return undefined;
    if (materialized.rowCount > MAX_FTS_CANDIDATE_ROW_IDS) return undefined;
    const result = await this.store.readFtsPostings(
      table.id,
      ordered.index.storageColumnId,
      snapshot.version ?? -1,
      MAX_FTS_CANDIDATE_ROW_IDS,
    );
    const rebuild = (): undefined => {
      this.#scheduleSecondaryIndexBuild(table, ordered.indexId);
      return undefined;
    };
    if (result.overflow || !result.hasBase) return rebuild();
    if (result.coversVersion > (snapshot.version ?? -1)) return undefined;
    if (result.deltaChunkCount > FTS_FOLD_DELTA_CHUNKS) {
      this.#scheduleSecondaryIndexBuild(table, ordered.indexId);
    }
    const rowForLocator = appendRowForLocator(segments, materialized.rowCount);
    const scanOrder = new Uint32Array(materialized.rowCount);
    const seen = new Uint8Array(materialized.rowCount);
    let output = 0;
    const postings = ordered.reverse ? [...result.postings].reverse() : result.postings;
    for (const posting of postings) {
      for (const locator of posting.rowIds) {
        const row = rowForLocator(locator);
        if (row === undefined || seen[row] === 1) return rebuild();
        seen[row] = 1;
        scanOrder[output] = row;
        output += 1;
      }
    }
    if (output !== materialized.rowCount) return rebuild();
    return { ...materialized, scanOrder, orderedForPlan: true };
  }

  /**
   * An append scan of the base segments with the table's delete and update deltas applied on
   * top. The replay path below rebuilds every row of every segment through a keyed map because
   * one segment is not an append, so a single deleted row used to cost a full-table replay —
   * and cost it on every later query, since only compaction folds the delta away. This path
   * pays for the deltas instead: base columns are copied in runs, deleted keys mask rows out,
   * and updated keys patch the cells they changed.
   *
   * Returns undefined for any history it does not cover (a windowed vector, a null key, an
   * update whose key no live row carries), which falls through to the replay unchanged.
   */
  async #materializeOverlayTable(
    table: TableRecord,
    snapshot: LeasedSnapshot,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    keyColumn: TableColumnRecord,
    plan: CompiledQuery | undefined,
    externallyPruned = false,
  ): Promise<ColumnarTable | undefined> {
    const appends: SegmentRecord[] = [];
    const appendOrders: number[] = [];
    const deltas: Array<{ segment: SegmentRecord; order: number }> = [];
    segments.forEach((segment, order) => {
      const kind = segment.kind;
      if (kind === "insert" || kind === "base") {
        appends.push(segment);
        appendOrders.push(order);
        return;
      }
      deltas.push({ segment, order });
    });
    if (deltas.length === 0) return undefined;

    // The deltas are the small side: key markers, and for an update the columns it changed.
    const deletedAt = new Map<OverlayKey, number>();
    const updatesByKey = new Map<OverlayKey, OverlayUpdate[]>();
    const patchedColumnIds = new Set<string>();
    const allUpdates: OverlayUpdate[] = [];
    for (const { segment, order } of deltas) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const keyVector = await this.#materializeAppendColumnVector(
        keyColumn,
        [segment],
        snapshot,
        segment.rowCount,
      );
      const readKey = columnVectorKeyReader(keyVector);
      if (readKey === undefined) return undefined;
      if (segment.kind === "delete") {
        for (let row = 0; row < segment.rowCount; row += 1) {
          const key = readKey(row);
          if (key === undefined) return undefined;
          deletedAt.set(key, order);
        }
        continue;
      }
      const changed = projectedColumns.filter(
        (column) =>
          column.id !== keyColumn.id && (segment.columnBlockIds[column.id]?.length ?? 0) > 0,
      );
      const vectors = new Map<string, ColumnVector>();
      for (const column of changed) {
        vectors.set(
          column.id,
          await this.#materializeAppendColumnVector(column, [segment], snapshot, segment.rowCount),
        );
        patchedColumnIds.add(column.id);
      }
      for (let row = 0; row < segment.rowCount; row += 1) {
        const key = readKey(row);
        if (key === undefined) return undefined;
        const update: OverlayUpdate = { order, row, vectors, applied: false };
        allUpdates.push(update);
        const existing = updatesByKey.get(key);
        if (existing === undefined) updatesByKey.set(key, [update]);
        else existing.push(update);
      }
    }

    const projectsKey = projectedColumns.some((column) => column.id === keyColumn.id);
    const neededColumns = projectsKey ? projectedColumns : [...projectedColumns, keyColumn];
    // Zone-map elimination drops whole row groups, so it can only compose with deltas that
    // cannot bring a pruned row back. Two conditions decide that, and they are independent.
    //
    // The first is ordering. A pruned scan reports no runs, so an update's position cannot be
    // compared against the segment a row came from -- but it does not need to be, as long as
    // every delta is newer than every base segment, because then every delta wins outright.
    //
    // The second is which columns the predicate reads. Zone maps are built from the base blocks,
    // so a predicate on a column an update rewrites is unsafe: the update could move a value into
    // the predicate's range, and the row group holding it would already have been eliminated. A
    // predicate on a column no update touches has no such hazard -- the unique key most of all,
    // which updates address rows *by* and never change.
    //
    // Requiring no updates at all conflated the two, and it is the write path that paid: a SQL
    // UPDATE resolves the rows it will touch by reading them back, so `UPDATE ... WHERE id = ?`
    // read every row of the table once any earlier update existed. Separating the conditions took
    // a 200k-row point update from 14.9ms to 2.4ms.
    const lastAppendOrder = appendOrders.at(-1) ?? -1;
    const deltasFollowAppends = deltas.every(({ order }) => order > lastAppendOrder);
    const candidates =
      plan === undefined || !deltasFollowAppends ? [] : zonePredicates(plan, table);
    // Dropping an unsafe predicate only prunes less, never more, so keeping the safe ones is
    // both correct and worth doing even when the two kinds are mixed.
    const predicates = candidates.filter((predicate) => !patchedColumnIds.has(predicate.column.id));
    let base: ColumnarTable | undefined;
    if (predicates.length > 0) {
      base = await this.#materializePrunedAppendTable(
        table,
        snapshot,
        neededColumns,
        appends,
        predicates,
      );
    }
    /** Whether the rows below are a pruned subset rather than every base row. */
    const prunedScan = externallyPruned || base !== undefined;
    // Runs map an output row back to the segment that wrote it; a pruned scan reports no runs,
    // and orderFree is what makes that safe.
    const runs: Array<{ end: number; order: number }> = [];
    if (base === undefined) {
      const appendRowCount = appends.reduce((total, segment) => total + segment.rowCount, 0);
      const columns = new Map<string, ColumnVector>();
      for (const column of neededColumns) {
        columns.set(
          column.name,
          await this.#materializeAppendColumnVector(column, appends, snapshot, appendRowCount),
        );
      }
      base = { name: table.name, rowCount: appendRowCount, columns };
      let end = 0;
      appends.forEach((segment, index) => {
        end += segment.rowCount;
        runs.push({ end, order: appendOrders[index] ?? 0 });
      });
    }

    const rowCount = base.rowCount;
    const baseKeyVector = base.columns.get(keyColumn.name);
    if (baseKeyVector === undefined) return undefined;
    const readBaseKey = columnVectorKeyReader(baseKeyVector);
    if (readBaseKey === undefined) return undefined;
    const alive = new Uint8Array(rowCount).fill(1);
    const patches = new Map<number, OverlayUpdate[]>();
    let aliveCount = rowCount;
    let runIndex = 0;
    for (let row = 0; row < rowCount; row += 1) {
      while (runIndex < runs.length && row >= (runs[runIndex]?.end ?? 0)) runIndex += 1;
      const order = runs.length === 0 ? -1 : (runs[runIndex]?.order ?? -1);
      const key = readBaseKey(row);
      if (key === undefined) return undefined;
      const updates = updatesByKey.get(key);
      if (updates !== undefined) {
        const applicable = updates.filter((update) => update.order > order);
        for (const update of applicable) update.applied = true;
        if (applicable.length > 0) patches.set(row, applicable);
      }
      const deleted = deletedAt.get(key);
      if (deleted !== undefined && deleted > order) {
        alive[row] = 0;
        aliveCount -= 1;
      }
    }
    // An update whose key no base row carries means the replay's corruption check would fire,
    // or that a shape this path does not model let the row escape it. Either way, defer.
    //
    // A pruned scan is the one case where an unapplied update is expected rather than alarming:
    // its row was eliminated by a predicate on a column no update touches, so the row cannot
    // satisfy this query whatever the update did to it, and the patch is irrelevant here. The
    // check still applies in full to every unpruned scan, which is where a genuinely dangling
    // update would surface.
    if (!prunedScan && allUpdates.some((update) => !update.applied)) return undefined;

    const columns = new Map<string, ColumnVector>();
    for (const column of projectedColumns) {
      const source = base.columns.get(column.name);
      if (source === undefined) return undefined;
      if (aliveCount === rowCount && !patchedColumnIds.has(column.id)) {
        columns.set(column.name, source);
        continue;
      }
      columns.set(
        column.name,
        patchedColumnIds.has(column.id)
          ? patchColumnVector(source, column, alive, aliveCount, patches)
          : compactColumnVector(source, alive, aliveCount),
      );
    }
    return {
      name: table.name,
      rowCount: aliveCount,
      columns,
      ...(projectsKey ? { uniqueKey: keyColumn.name } : {}),
    };
  }

  async #materializePrunedAppendTable(
    table: TableRecord,
    snapshot: LeasedSnapshot,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    predicates: readonly ZonePredicate[],
  ): Promise<ColumnarTable | undefined> {
    const predicateColumns = [
      ...new Map(predicates.map((predicate) => [predicate.column.id, predicate.column])).values(),
    ];
    // Row-group alignment assumes every involved column stored blocks in every segment; a column
    // added after a segment was written reads as NULL through the full-scan path instead.
    const involvedColumns = [...projectedColumns, ...predicateColumns];
    if (
      involvedColumns.some((column) =>
        segments.some((segment) => segment.columnBlockIds[column.id] === undefined),
      )
    ) {
      return undefined;
    }
    const storedBlocks = new Map<string, Uint8Array>();
    const predicateBlockDescriptions = new Map<string, ReturnType<typeof inspectBlock>>();
    const predicateBlockIds = [
      ...new Set(
        segments.flatMap((segment) =>
          predicateColumns.flatMap((column) => segment.columnBlockIds[column.id] ?? []),
        ),
      ),
    ];
    for (let start = 0; start < predicateBlockIds.length; start += 16) {
      await this.#renewInternalLeaseIfNeeded(snapshot);
      const ids = predicateBlockIds.slice(start, start + 16);
      const blocks = await this.#getSnapshotBlocksWindowed(snapshot, ids);
      for (let index = 0; index < ids.length; index += 1) {
        const id = ids[index] ?? "";
        const bytes = blocks[index];
        if (bytes === undefined) throw new Error(`Visible block is missing: ${id}`);
        storedBlocks.set(id, bytes);
        // Header and metadata only: zone-map elimination must not pay the decompress,
        // checksum, and payload-validation cost of blocks it is about to discard. The
        // surviving blocks are decoded (and fully verified) during materialization.
        predicateBlockDescriptions.set(id, inspectBlock(bytes));
      }
    }

    const selectedSegments: SelectedAppendSegment[] = [];
    for (const segment of segments) {
      const firstIds = segment.columnBlockIds[predicateColumns[0]?.id ?? ""] ?? [];
      if (
        predicateColumns.some(
          (column) => (segment.columnBlockIds[column.id]?.length ?? 0) !== firstIds.length,
        ) ||
        projectedColumns.some(
          (column) => (segment.columnBlockIds[column.id]?.length ?? 0) !== firstIds.length,
        )
      ) {
        return undefined;
      }
      const blockIndexes: number[] = [];
      const rowCounts: number[] = [];
      let segmentRows = 0;
      for (let blockIndex = 0; blockIndex < firstIds.length; blockIndex += 1) {
        let rowCount: number | undefined;
        let canMatch = true;
        for (const predicate of predicates) {
          const blockId = segment.columnBlockIds[predicate.column.id]?.[blockIndex] ?? "";
          const description = predicateBlockDescriptions.get(blockId);
          if (description === undefined) throw new Error(`Visible block is missing: ${blockId}`);
          if (description.type !== predicate.column.type) {
            throw new Error(`Column type mismatch: ${predicate.column.name}`);
          }
          if (rowCount !== undefined && description.rowCount !== rowCount) return undefined;
          rowCount = description.rowCount;
          if (!zoneMapCanMatch(description, predicate)) canMatch = false;
        }
        if (rowCount === undefined) return undefined;
        segmentRows += rowCount;
        if (canMatch) {
          blockIndexes.push(blockIndex);
          rowCounts.push(rowCount);
        }
      }
      if (segmentRows !== segment.rowCount) return undefined;
      if (blockIndexes.length > 0) selectedSegments.push({ segment, blockIndexes, rowCounts });
    }

    const expectedRows = new Map<string, number>();
    const candidateSegments = selectedSegments.map(({ segment, blockIndexes, rowCounts }) => {
      const columnBlockIds = Object.fromEntries(
        projectedColumns.map((column) => [
          column.id,
          blockIndexes.map((blockIndex, index) => {
            const blockId = segment.columnBlockIds[column.id]?.[blockIndex] ?? "";
            expectedRows.set(blockId, rowCounts[index] ?? 0);
            return blockId;
          }),
        ]),
      );
      return {
        ...segment,
        rowCount: rowCounts.reduce((total, count) => total + count, 0),
        columnBlockIds,
      };
    });
    const candidateRowCount = candidateSegments.reduce(
      (total, segment) => total + segment.rowCount,
      0,
    );
    const candidateVectors = new Map<string, ColumnVector>();
    for (const column of predicateColumns) {
      candidateVectors.set(
        column.id,
        await this.#materializeAppendColumnVector(
          column,
          candidateSegments,
          snapshot,
          candidateRowCount,
          storedBlocks,
          expectedRows,
        ),
      );
    }
    const selectedRows = new Uint32Array(candidateRowCount);
    let selectedRowCount = 0;
    for (let row = 0; row < candidateRowCount; row += 1) {
      if (
        predicates.every((predicate) =>
          vectorPredicateMatches(
            requiredColumnVector(candidateVectors, predicate.column),
            row,
            predicate,
          ),
        )
      ) {
        selectedRows[selectedRowCount] = row;
        selectedRowCount += 1;
      }
    }
    for (const column of projectedColumns) {
      if (candidateVectors.has(column.id)) continue;
      candidateVectors.set(
        column.id,
        selectedRowCount === 0
          ? createEmptyColumnVector(column.type, 0)
          : await this.#materializeAppendColumnVector(
              column,
              candidateSegments,
              snapshot,
              candidateRowCount,
              storedBlocks,
              expectedRows,
            ),
      );
    }
    const columns = new Map<string, ColumnVector>();
    for (const column of projectedColumns) {
      const candidate = requiredColumnVector(candidateVectors, column);
      if (selectedRowCount === candidateRowCount) {
        columns.set(column.name, candidate);
        continue;
      }
      const output = createEmptyColumnVector(column.type, selectedRowCount);
      const dictionaryIndex = column.type === "string" ? new Map<string, number>() : undefined;
      for (let outputRow = 0; outputRow < selectedRowCount; outputRow += 1) {
        copyColumnVectorValue(
          candidate,
          selectedRows[outputRow] ?? 0,
          output,
          outputRow,
          dictionaryIndex,
        );
      }
      columns.set(column.name, output);
    }
    const keyColumn = getUniqueKeyColumn(table);
    const projectedKey =
      keyColumn !== undefined && projectedColumns.some((column) => column.id === keyColumn.id)
        ? keyColumn.name
        : undefined;
    return {
      name: table.name,
      rowCount: selectedRowCount,
      columns,
      ...(projectedKey ? { uniqueKey: projectedKey } : {}),
    };
  }

  /**
   * The block buffer pool: every read path decodes physical blocks through here. Block
   * content is immutable, so the decoded form caches by id alone and can never be stale —
   * a commit only ever introduces new ids, and superseded blocks simply stop being
   * referenced and age out of the byte-bounded LRU. Returns one decoded block per id, in
   * order; `storedBlocks` short-circuits the store fetch for bytes the caller already holds.
   */
  async #decodedBlocksThroughCache(
    ids: readonly string[],
    snapshot: LeasedSnapshot,
    storedBlocks?: Map<string, Uint8Array>,
  ): Promise<DecodedPhysicalBlock[]> {
    await this.#renewInternalLeaseIfNeeded(snapshot);
    const decodedBlocks = new Array<DecodedPhysicalBlock | undefined>(ids.length);
    const pendingIndexes: number[] = [];
    const fetchIds: string[] = [];
    for (let index = 0; index < ids.length; index += 1) {
      const id = ids[index] ?? "";
      const cached = this.#cacheGet(`dpb\0${id}`) as DecodedPhysicalBlock | undefined;
      if (cached !== undefined) {
        decodedBlocks[index] = cached;
        continue;
      }
      pendingIndexes.push(index);
      if (storedBlocks?.has(id) !== true) fetchIds.push(id);
    }
    // Fetched bytes live in a local map that dies with this call. Writing them into the
    // caller's `storedBlocks` would retain every block the scan ever touched for the whole
    // query — outside the buffer pool's budget and never charged to the memory context.
    const fetchedBytes = new Map<string, Uint8Array>();
    if (fetchIds.length > 0) {
      const fetched = await this.#getSnapshotBlocksWindowed(snapshot, fetchIds);
      for (let index = 0; index < fetchIds.length; index += 1) {
        const id = fetchIds[index] ?? "";
        const bytes = fetched[index];
        if (bytes === undefined) throw new Error(`Visible block is missing: ${id}`);
        fetchedBytes.set(id, bytes);
      }
    }
    for (const index of pendingIndexes) {
      const id = ids[index] ?? "";
      const bytes = fetchedBytes.get(id) ?? storedBlocks?.get(id);
      if (bytes === undefined) throw new Error(`Visible block is missing: ${id}`);
      const decoded = await decodePhysicalBlock(bytes);
      this.#cachePut(`dpb\0${id}`, decoded, decodedPhysicalBlockRetainedBytes(decoded));
      decodedBlocks[index] = decoded;
    }
    return decodedBlocks.map((decoded, index) => {
      if (decoded === undefined) {
        throw new Error(`Visible block is missing: ${ids[index] ?? ""}`);
      }
      return decoded;
    });
  }

  /**
   * Scan positions of the rows whose unique key the plan pins to literals (`alias.key = 4`,
   * `alias.key IN (...)`), over append-only segments: zone maps skip blocks a numeric key
   * cannot be in, a sorted block is searched by run, and a string key goes through the block
   * dictionary. Undefined when the plan does not pin the key or a block cannot be searched.
   */
  async #uniqueKeyRowSelection(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    segments: readonly SegmentRecord[],
    plan: CompiledQuery,
    snapshot: LeasedSnapshot,
  ): Promise<number[] | undefined> {
    const members = uniqueKeyMembers(plan, table, keyColumn);
    if (members === undefined || members.length > SECONDARY_INDEX_ROW_SELECTION_CAP) {
      return undefined;
    }
    const targets = new Set(
      members.map((value) => (value instanceof Date ? dateMilliseconds(value) : value)),
    );
    const numericTargets = [...targets].filter(
      (value): value is number => typeof value === "number",
    );
    const rows: number[] = [];
    let rowStart = 0;
    for (const segment of segments) {
      const segmentStart = rowStart;
      const blockIds = segment.columnBlockIds[keyColumn.id] ?? [];
      if (blockIds.length === 0 && segment.rowCount > 0) return undefined;
      if (Object.values(segment.columnBlockIds).some((ids) => ids.length !== blockIds.length)) {
        return undefined;
      }
      const descriptions =
        keyColumn.type === "number" || keyColumn.type === "datetime"
          ? await this.#zoneDescriptions(blockIds, snapshot)
          : undefined;
      for (const blockId of blockIds) {
        const description = descriptions?.get(blockId);
        const zone = description?.metadata.zoneMap;
        if (description !== undefined && zone !== undefined) {
          if (!numericTargets.some((target) => zone.min <= target && target <= zone.max)) {
            rowStart += description.rowCount;
            continue;
          }
        }
        const [decoded] = await this.#decodedBlocksThroughCache([blockId], snapshot);
        if (decoded === undefined) return undefined;
        const vector = this.#blockColumnVector(blockId, decoded);
        if (vector.kind !== keyColumn.type) return undefined;
        const found: number[] = [];
        if (vector.kind === "number" || vector.kind === "datetime") {
          if (decoded.description.nullCount === 0 && valuesAreAscending(vector.values)) {
            for (const target of numericTargets) {
              const run = equalRunRange(vector.values, target);
              for (let slot = run.begin; slot < run.end; slot += 1) found.push(slot);
            }
          } else {
            for (let slot = 0; slot < vector.length; slot += 1) {
              const value = vector.values[slot] ?? 0;
              if (targets.has(value) && vectorValue(vector, slot) !== null) found.push(slot);
            }
          }
        } else if (vector.kind === "string") {
          const codes = new Set<number>();
          for (const target of targets) {
            if (typeof target !== "string") continue;
            const code = this.#dictionaryCode(blockId, vector, target);
            if (code !== undefined) codes.add(code);
          }
          if (codes.size > 0) {
            for (let slot = 0; slot < vector.length; slot += 1) {
              const code = vector.codes[slot];
              if (code !== undefined && codes.has(code)) found.push(slot);
            }
          }
        } else {
          for (let slot = 0; slot < vector.length; slot += 1) {
            if (targets.has(vectorValue(vector, slot) as boolean)) found.push(slot);
          }
        }
        found.sort((a, b) => a - b);
        for (const slot of found) rows.push(rowStart + slot);
        rowStart += vector.length;
      }
      if (rowStart - segmentStart !== segment.rowCount) return undefined;
    }
    return rows;
  }

  /**
   * Materializes the rows at ascending scan positions over append-only segments, reading only
   * the blocks that hold a selected row. Undefined when the block layout does not line up,
   * which sends the caller to the whole-segment path.
   */
  async #materializeSelectedRows(
    table: TableRecord,
    keyColumn: TableColumnRecord,
    projectedColumns: readonly TableColumnRecord[],
    segments: readonly SegmentRecord[],
    rows: readonly number[],
    snapshot: LeasedSnapshot,
    projectedKey: string | undefined,
  ): Promise<ColumnarTable | undefined> {
    const values = projectedColumns.map((): QueryValue[] => []);
    let cursor = 0;
    let rowStart = 0;
    for (const segment of segments) {
      const anchorIds = segment.columnBlockIds[keyColumn.id] ?? [];
      const anchorBlocks = await this.#decodedBlocksThroughCache(anchorIds, snapshot);
      for (let blockIndex = 0; blockIndex < anchorIds.length; blockIndex += 1) {
        const count = anchorBlocks[blockIndex]?.column.rowCount ?? 0;
        const end = rowStart + count;
        const local: number[] = [];
        while (cursor < rows.length && (rows[cursor] ?? Number.POSITIVE_INFINITY) < end) {
          local.push((rows[cursor] ?? 0) - rowStart);
          cursor += 1;
        }
        rowStart = end;
        if (local.length === 0) continue;
        const blockIds = projectedColumns.map(
          (column) => segment.columnBlockIds[column.id]?.[blockIndex],
        );
        if (blockIds.some((id) => id === undefined)) return undefined;
        const decoded = await this.#decodedBlocksThroughCache(blockIds as string[], snapshot);
        for (let index = 0; index < projectedColumns.length; index += 1) {
          const column = projectedColumns[index];
          const block = decoded[index];
          const blockId = blockIds[index];
          if (column === undefined || block === undefined || blockId === undefined)
            return undefined;
          if (block.column.rowCount !== count || block.column.type !== column.type)
            return undefined;
          const vector = plainTextExecutionVector(column, this.#blockColumnVector(blockId, block));
          const output = values[index];
          if (output === undefined) return undefined;
          for (const row of local) output.push(vectorValue(vector, row));
        }
      }
    }
    if (cursor !== rows.length) return undefined;
    return createColumnarTable(
      table.name,
      new Map(
        projectedColumns.map((column, index) => [
          column.name,
          { type: column.type, values: values[index] ?? [] },
        ]),
      ),
      projectedKey,
    );
  }

  /**
   * A whole-segment column vector is a pure function of its immutable blocks, so the plain
   * shape (no caller-supplied bytes or row expectations) is pooled by segment list: a
   * dimension table joined on every query is then decoded once, not per query.
   */
  async #materializeAppendColumnVector(
    column: TableColumnRecord,
    segments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    rowCount: number,
    storedBlocks?: Map<string, Uint8Array>,
    expectedRows?: ReadonlyMap<string, number>,
  ): Promise<ColumnVector> {
    const poolable = storedBlocks === undefined && expectedRows === undefined;
    const key = poolable
      ? `mav\0${column.id}\0${String(rowCount)}\0${segments.map((segment) => segment.id).join("\0")}`
      : undefined;
    if (key !== undefined) {
      const cached = this.#cacheGet(key) as ColumnVector | undefined;
      if (cached !== undefined) return cached;
    }
    const vector = await this.#buildAppendColumnVector(
      column,
      segments,
      snapshot,
      rowCount,
      storedBlocks,
      expectedRows,
    );
    if (key !== undefined && key.length <= MAX_CACHEABLE_TEXT_CHARACTERS) {
      this.#cachePut(key, vector, 128 + columnVectorPayloadBytes(vector));
    }
    return vector;
  }

  async #buildAppendColumnVector(
    column: TableColumnRecord,
    segments: readonly SegmentRecord[],
    snapshot: LeasedSnapshot,
    rowCount: number,
    storedBlocks?: Map<string, Uint8Array>,
    expectedRows?: ReadonlyMap<string, number>,
  ): Promise<ColumnVector> {
    const validity = new Uint8Array(Math.ceil(rowCount / 8));
    const values =
      column.type === "boolean"
        ? new Uint8Array(rowCount)
        : column.type === "number" || column.type === "datetime"
          ? new Float64Array(rowCount)
          : undefined;
    const stringCodes = column.type === "string" ? new Uint32Array(rowCount) : undefined;
    stringCodes?.fill(NULL_STRING_VECTOR_CODE);
    const stringDictionary = new StringDictionaryBuilder();
    let outputRow = 0;

    for (const segment of segments) {
      const blockIds = segment.columnBlockIds[column.id];
      if (blockIds === undefined) {
        // The column joined the catalog after this segment was written. Its rows read as the
        // column's backfill, or as NULL through the preallocated validity default when it has
        // none. A present-but-empty block list still fails the row-count check below, preserving
        // the corruption guard.
        if (column.backfill !== undefined) {
          const backfill = column.backfill;
          const stringCode =
            stringCodes === undefined
              ? 0
              : dictionaryCodeForText(stringDictionary, String(backfill));
          const numeric = backfill instanceof Date ? dateMilliseconds(backfill) : Number(backfill);
          for (let offset = 0; offset < segment.rowCount; offset += 1) {
            const index = outputRow + offset;
            setBitmapValue(validity, index);
            if (stringCodes !== undefined) stringCodes[index] = stringCode;
            else if (values instanceof Uint8Array) values[index] = backfill === true ? 1 : 0;
            else if (values !== undefined) values[index] = numeric;
          }
        }
        outputRow += segment.rowCount;
        continue;
      }
      let segmentRows = 0;
      for (let start = 0; start < blockIds.length; start += 16) {
        const ids = blockIds.slice(start, start + 16);
        // Immutable block content decodes through the buffer pool: unchanged blocks skip the
        // store fetch, decompression, checksum, and payload validation on every re-read.
        const decodedBlocks = await this.#decodedBlocksThroughCache(ids, snapshot, storedBlocks);
        for (let index = 0; index < decodedBlocks.length; index += 1) {
          const decoded = decodedBlocks[index];
          if (decoded === undefined) {
            throw new Error(`Visible block is missing: ${ids[index] ?? ""}`);
          }
          const expected = expectedRows?.get(ids[index] ?? "");
          if (expected !== undefined && decoded.column.rowCount !== expected) {
            throw new Error(`Column block row count mismatch: ${column.name}`);
          }
          if (decoded.column.type !== column.type) {
            throw new Error(`Column type mismatch: ${column.name}`);
          }
          if (outputRow + decoded.column.rowCount > rowCount) {
            throw new Error(`Column row count mismatch: ${column.name}`);
          }
          appendPhysicalColumnToVector(
            decoded.column,
            outputRow,
            validity,
            values,
            stringCodes,
            stringDictionary,
          );
          outputRow += decoded.column.rowCount;
          segmentRows += decoded.column.rowCount;
        }
      }
      if (segmentRows !== segment.rowCount) {
        throw new Error(`Column row count mismatch: ${column.name}`);
      }
    }
    if (outputRow !== rowCount) throw new Error(`Column row count mismatch: ${column.name}`);
    if (column.type === "string") {
      const dictionary = stringDictionary.dictionary;
      const protectedDictionary =
        column.sqlDomain === undefined && stringDictionary.hasSqlDomainValue
          ? dictionary.map(protectedSqlTextValue)
          : dictionary;
      return {
        kind: "string",
        length: rowCount,
        validity,
        codes: stringCodes ?? new Uint32Array(),
        dictionary: protectedDictionary,
      };
    }
    if (column.type === "boolean") {
      return {
        kind: "boolean",
        length: rowCount,
        validity,
        values: values as Uint8Array,
      };
    }
    return {
      kind: column.type,
      length: rowCount,
      validity,
      values: values as Float64Array,
    };
  }

  #readSegment(
    columns: readonly TableColumnRecord[],
    segment: SegmentRecord,
    decodedColumns: ReadonlyMap<string, DecodedColumn>,
  ): DatabaseRow[] {
    const columnValues = new Map(
      columns.map(
        (column) => [column.id, this.#readSegmentColumn(column, segment, decodedColumns)] as const,
      ),
    );
    return Array.from({ length: segment.rowCount }, (_, rowIndex) =>
      Object.fromEntries(
        columns.map((column) => [column.name, columnValues.get(column.id)?.[rowIndex] ?? null]),
      ),
    );
  }

  #readSegmentColumn(
    column: TableColumnRecord,
    segment: SegmentRecord,
    decodedColumns: ReadonlyMap<string, DecodedColumn>,
  ): BatchValue[] {
    const blockIds = segment.columnBlockIds[column.id];
    if (blockIds === undefined) {
      // The column joined the catalog after this segment was written; its rows read as the
      // column's backfill, or NULL when it has none.
      const absent = column.backfill ?? null;
      return Array.from({ length: segment.rowCount }, () => absent);
    }
    const values: BatchValue[] = [];
    for (const blockId of blockIds) {
      const decoded = decodedColumns.get(blockId);
      if (decoded === undefined) throw new Error(`Visible block is missing: ${blockId}`);
      if (decoded.type !== column.type) {
        throw new Error(`Column type mismatch: ${column.name}`);
      }
      for (const value of decoded.values) values.push(value);
    }
    if (values.length !== segment.rowCount) {
      throw new Error(`Column row count mismatch: ${column.name}`);
    }
    return values;
  }

  async #loadDecodedBlocks(
    blockIds: readonly string[],
    snapshot?: LeasedSnapshot,
  ): Promise<Map<string, DecodedColumn>> {
    if (blockIds.length === 0) return new Map();
    const decoded = new Map<string, DecodedColumn>();
    const decodeWindow = 16;
    for (let start = 0; start < blockIds.length; start += decodeWindow) {
      if (snapshot !== undefined) await this.#renewInternalLeaseIfNeeded(snapshot);
      const ids = blockIds.slice(start, start + decodeWindow);
      const blocks =
        snapshot === undefined
          ? await this.#getBlocksWindowed(ids)
          : await this.#getSnapshotBlocksWindowed(snapshot, ids);
      const columns = await Promise.all(
        blocks.map(async (bytes, index) => {
          const blockId = ids[index] ?? "";
          if (bytes === undefined) throw new Error(`Visible block is missing: ${blockId}`);
          return [blockId, (await decodeBlock(bytes)).column] as const;
        }),
      );
      for (const [blockId, column] of columns) decoded.set(blockId, column);
    }
    return decoded;
  }

  async #getBlocksWindowed(ids: readonly string[]): Promise<Array<Uint8Array | undefined>> {
    const blocks: Array<Uint8Array | undefined> = [];
    for (let start = 0; start < ids.length; start += 64) {
      blocks.push(...(await this.#readBlockWindow(ids.slice(start, start + 64))));
    }
    return blocks;
  }

  /**
   * Reads query-visible bytes through a staged overlay when the snapshot supplies one. Ordinary
   * committed snapshots deliberately have no bulk method: their manifest membership was proved
   * while the reader lease pinned the version, so the store's bulk payload path stays fast.
   * A write scope's wrapper does supply one and routes each pending id through its transaction;
   * bypassing it would report a journaled block as missing until the scope publishes.
   */
  async #getSnapshotBlocksWindowed(
    snapshot: LeasedSnapshot,
    ids: readonly string[],
  ): Promise<Array<Uint8Array | undefined>> {
    const overlayRead = (
      snapshot as LeasedSnapshot & {
        getBlocks?: (blockIds: readonly string[]) => Promise<Array<Uint8Array | undefined>>;
      }
    ).getBlocks;
    if (overlayRead === undefined) return this.#getBlocksWindowed(ids);
    const blocks: Array<Uint8Array | undefined> = [];
    for (let start = 0; start < ids.length; start += 64) {
      blocks.push(...(await overlayRead.call(snapshot, ids.slice(start, start + 64))));
    }
    return blocks;
  }

  async #manifestBlockPresence(version: number | null, ids: readonly string[]): Promise<boolean[]> {
    const present: boolean[] = [];
    for (let start = 0; start < ids.length; start += MAX_MANIFEST_BLOCK_PRESENCE_IDS) {
      present.push(
        ...(await this.store.hasManifestBlocks(
          version,
          ids.slice(start, start + MAX_MANIFEST_BLOCK_PRESENCE_IDS),
        )),
      );
    }
    return present;
  }

  async #readBlockWindow(ids: readonly string[]): Promise<Array<Uint8Array | undefined>> {
    try {
      return await this.store.getBlocks(ids);
    } catch (error) {
      if (!(error instanceof BlockReadBatchTooLargeError) || ids.length <= 1) throw error;
      const middle = ids.length >>> 1;
      const left = await this.#readBlockWindow(ids.slice(0, middle));
      const right = await this.#readBlockWindow(ids.slice(middle));
      return [...left, ...right];
    }
  }

  async #visibleSegmentRecords(
    table: TableRecord,
    snapshot: Snapshot,
    catalog?: SegmentVisibilityCatalog,
  ): Promise<SegmentRecord[]> {
    // One prepare asks for the same table's visible segments several times (statistics,
    // fingerprints, materialization); the visibility catalog is per-prepare state, so the
    // filtered-and-sorted result memoizes on it, like #visibilityFingerprints.
    if (catalog !== undefined) {
      let memo = this.#visibleSegmentsMemo.get(catalog);
      if (memo === undefined) {
        memo = new Map<string, SegmentRecord[]>();
        this.#visibleSegmentsMemo.set(catalog, memo);
      }
      const key = `${table.id}\u0000${String(snapshot.version ?? -1)}`;
      const cached = memo.get(key);
      if (cached !== undefined) return cached;
      const computed = await this.#visibleSegmentRecordsUncached(table, snapshot, catalog);
      memo.set(key, computed);
      return computed;
    }
    return this.#visibleSegmentRecordsUncached(table, snapshot, catalog);
  }

  async #visibleSegmentRecordsUncached(
    table: TableRecord,
    snapshot: Snapshot,
    catalog?: SegmentVisibilityCatalog,
  ): Promise<SegmentRecord[]> {
    const segments =
      catalog === undefined
        ? await listTableSegmentsPaged(this.store, table.id)
        : (catalog.segmentsByTable.get(table.id) ?? []);
    const transactions =
      catalog?.transactions ??
      new Map(
        (await this.#transactionRecordsForSegments(segments)).map((record) => [record.id, record]),
      );
    // Segment metadata outlives the manifest version that made it visible. Block membership is
    // necessary but not sufficient for historical reads: a later compaction can publish a new
    // segment that aliases blocks already present in the old manifest. Always gate on the
    // owner's committed version as well as exact manifest membership. The sole exception is a
    // transaction-scoped overlay, whose pending owner is deliberately presented after the
    // pinned committed snapshot.
    const versionEligible = segments.filter((segment) => {
      if (segment.transactionId === catalog?.overlayTransactionId) return true;
      const committedVersion = transactions.get(segment.transactionId)?.committedVersion;
      return (
        snapshot.version !== null &&
        committedVersion !== null &&
        committedVersion !== undefined &&
        committedVersion <= snapshot.version
      );
    });
    const visible = await filterSnapshotSegments(snapshot, versionEligible);
    return [...visible].sort((left, right) => {
      const leftVersion = transactions.get(left.transactionId)?.committedVersion ?? -1;
      const rightVersion = transactions.get(right.transactionId)?.committedVersion ?? -1;
      const leftOrder = left.logicalOrder;
      const rightOrder = right.logicalOrder;
      return (
        leftOrder - rightOrder ||
        leftVersion - rightVersion ||
        left.commitOrdinal - right.commitOrdinal ||
        left.id.localeCompare(right.id)
      );
    });
  }

  async #transactionRecordsForSegments(
    segments: readonly SegmentRecord[],
  ): Promise<TransactionRecord[]> {
    const transactionIds = [...new Set(segments.map((segment) => segment.transactionId))];
    const records: TransactionRecord[] = [];
    for (let start = 0; start < transactionIds.length; start += 64) {
      const window = transactionIds.slice(start, start + 64);
      const loaded = await this.store.getTransactions(window);
      for (const record of loaded) if (record !== undefined) records.push(record);
    }
    return records;
  }

  async #unprunedManifestContainsAll(blockIds: readonly string[]): Promise<boolean> {
    let cursor: number | null = null;
    do {
      const page = await this.store.listManifestPage(cursor, 8);
      for (const manifest of page.records) {
        if (manifest.prunedAt !== undefined) continue;
        if ((await this.#manifestBlockPresence(manifest.version, blockIds)).every(Boolean)) {
          return true;
        }
      }
      cursor = page.nextCursor;
    } while (cursor !== null);
    return false;
  }

  async #withLeasedSnapshot<T>(
    version: number | null | undefined,
    action: (snapshot: LeasedSnapshot) => Promise<T>,
  ): Promise<T> {
    for (;;) {
      const lease = await this.#transactions.openLeasedSnapshot({
        id: `${this.#internalLeaseOwnerId}/${crypto.randomUUID()}`,
        ownerId: this.#internalLeaseOwnerId,
        ttlMs: INTERNAL_READ_LEASE_TTL_MS,
        ...(version === undefined ? {} : { version }),
      });
      try {
        return await action(lease);
      } catch (error) {
        if (version !== undefined || !(error instanceof SnapshotManifestMissingError)) throw error;
      } finally {
        await lease.release();
      }
    }
  }

  async #renewInternalLeaseIfNeeded(snapshot: LeasedSnapshot): Promise<void> {
    if (
      dateMilliseconds(snapshot.expiresAt) - dateMilliseconds(this.#now()) >
      INTERNAL_READ_LEASE_TTL_MS / 2
    ) {
      return;
    }
    if (snapshot === this.#sharedLease?.lease) {
      // Overlapping prepares share one lease record; concurrent renewals would race the
      // lease's revision compare-and-swap, so they share one in-flight renewal instead.
      this.#sharedLeaseRenewal ??= snapshot
        .renew(INTERNAL_READ_LEASE_TTL_MS)
        .then(() => undefined)
        .finally(() => {
          this.#sharedLeaseRenewal = undefined;
        });
      await this.#sharedLeaseRenewal;
      return;
    }
    await snapshot.renew(INTERNAL_READ_LEASE_TTL_MS);
  }

  /**
   * Encodes one column block, choosing its codec from what gzip achieved on this column's
   * previous block. Columns are homogeneous down their length, so one observation predicts the
   * next block; a column that gzip cannot compress is written raw until it is re-probed, and
   * the codec each block actually used is recorded in the block itself, so a wrong guess costs
   * bytes and never correctness.
   */
  async #encodeColumnBlock(
    columnId: string,
    input: ColumnInput,
    /**
     * "raw" for delete-key blocks: they hold only the doomed keys, compaction folds them away,
     * and a 50k-key range delete otherwise spends more time in gzip than in the whole rest of
     * the statement. The stored format carries the codec per block, so nothing changes on disk
     * beyond the byte count.
     */
    preferred: Compression = this.#compression,
  ): Promise<Uint8Array> {
    return this.#encodePreferredBlock(
      columnId,
      preferred,
      columnInputBytesBelow(input, GZIP_MINIMUM_INPUT_BYTES),
      (compression) => encodeBlock(input, compression),
    );
  }

  /**
   * Applies the same adaptive gzip rule to ordinary writes and compaction output. `gzip` is a
   * preference, not a promise: tiny inputs and probes that save less than 20% stay raw. Only a
   * failed verdict is cached, so successful columns do not leave one map entry behind forever.
   */
  async #encodePreferredBlock(
    columnId: string,
    preferred: Compression,
    belowMinimum: boolean,
    encode: (compression: Compression) => Promise<Uint8Array>,
  ): Promise<Uint8Array> {
    if (preferred !== "gzip") return encode(preferred);
    if (belowMinimum) return encode("raw");
    const verdict = this.#gzipVerdicts.get(columnId);
    if (verdict !== undefined) {
      if (verdict < GZIP_REPROBE_BLOCKS) {
        this.#gzipVerdicts.set(columnId, verdict + 1);
        return encode("raw");
      }
      this.#gzipVerdicts.delete(columnId);
    }
    let bytes: Uint8Array;
    try {
      bytes = await encode("gzip");
    } catch (error) {
      // A legal physical column can sit exactly below the 64 MiB logical ceiling while an
      // incompressible gzip representation grows a few bytes past the stored-payload ceiling.
      // Gzip is adaptive here, so preserve the legal write as raw. The dedicated error class
      // keeps malformed input and every other encoder failure visible to the caller.
      if (error instanceof StoredBlockPayloadTooLargeError) return encode("raw");
      throw error;
    }
    const description = inspectBlock(bytes);
    const worthwhile = description.encodedLength >= bytes.byteLength * GZIP_WORTHWHILE_RATIO;
    if (!worthwhile) {
      if (
        !this.#gzipVerdicts.has(columnId) &&
        this.#gzipVerdicts.size >= GZIP_VERDICT_CACHE_LIMIT
      ) {
        const oldest = this.#gzipVerdicts.keys().next().value;
        if (oldest !== undefined) this.#gzipVerdicts.delete(oldest);
      }
      this.#gzipVerdicts.set(columnId, 0);
      // Nothing was gained, so hand back the uncompressed form rather than make every read of
      // this block pay to inflate it.
      return encode("raw");
    }
    this.#gzipVerdicts.delete(columnId);
    return bytes;
  }

  async #findTable(name: string): Promise<TableRecord> {
    validateName(name, "Table");
    const table =
      (await this.store.getTableByName(name)) ??
      (await this.store.getTableByName(await this.#foldTableName(name)));
    if (table === undefined) throw new UnknownTableError(name);
    // Reads resolve a view into its query before reaching here, so a view arriving at this
    // point is a write, a DDL statement, or a path that forgot to rewrite: all of them errors.
    if (table.view !== undefined) throw new TypeError(`${name} is a view, not a table`);
    return table;
  }

  async #assertVisibleSegmentCursorTable(
    tableName: string,
    capturedTableId: string,
  ): Promise<void> {
    const current = await this.store.getTableByName(tableName);
    if (current?.id === capturedTableId) return;
    throw new VisibleSegmentCursorStaleError(tableName, capturedTableId, current?.id ?? null);
  }
}

/** What a MERGE decided for one source's rows, ready to apply as three batched writes. */
interface MergeWork {
  updates: Map<string, { key: Exclude<BatchValue, null>; changes: Record<string, BatchValue> }>;
  deletes: Map<string, QueryValue>;
  inserts: Array<Record<string, BatchValue>>;
}

/**
 * Chooses each source row's branch and evaluates what that branch would write (F312). Pure: it
 * reads the source rows and the target rows they matched and returns the work, so every decision
 * is made before any of it is applied — which is what lets the caller apply the result as three
 * batches instead of row by row.
 */
function classifyMergeRows(input: {
  statement: Extract<CompiledStatement, { kind: "merge" }>;
  target: TableRecord;
  keyColumn: TableColumnRecord;
  sourceRows: QueryResult["rows"];
  keys: readonly QueryValue[];
  present: ReadonlyMap<string, DatabaseRow>;
}): MergeWork {
  const { statement, target, keyColumn, sourceRows, keys, present } = input;
  const work: MergeWork = { updates: new Map(), deletes: new Map(), inserts: [] };
  const claimed = new Set<string>();
  sourceRows.forEach((sourceRow, index) => {
    const key = keys[index] ?? null;
    const token = key === null ? undefined : keyToken(keyColumn.type, key);
    const matched = token === undefined ? undefined : present.get(token);
    if (key !== null && token !== undefined && matched !== undefined) {
      // PostgreSQL raises a cardinality violation when two source rows act on one target row.
      // silently would make the result depend on the order the source happened to produce.
      if (claimed.has(token)) {
        throw new TypeError(
          `MERGE matched ${target.name} row ${formatValue(key)} from more than one source row`,
        );
      }
      claimed.add(token);
    }
    const context = { [statement.source.alias]: sourceRow, [statement.alias]: matched };
    for (const branch of statement.branches) {
      // The first branch whose match state and condition both hold decides this row.
      if ((branch.when === "matched") !== (matched !== undefined)) continue;
      if (
        branch.condition !== undefined &&
        evaluateJoinedRowExpression(branch.condition, context) !== true
      ) {
        continue;
      }
      if (branch.action.kind === "delete") {
        if (key !== null && token !== undefined) {
          work.deletes.set(token, key);
          work.updates.delete(token);
        }
        return;
      }
      if (branch.action.kind === "update") {
        if (key === null || token === undefined) return;
        const changes: Record<string, BatchValue> = {};
        for (const assignment of branch.action.assignments) {
          if (assignment.column === keyColumn.name) {
            throw new TypeError(`MERGE cannot update the unique key: ${keyColumn.name}`);
          }
          const column = target.columns.find((candidate) => candidate.name === assignment.column);
          if (column === undefined) throw new TypeError(`Unknown column: ${assignment.column}`);
          changes[assignment.column] = storedSqlValueFromExecution(
            column,
            evaluateJoinedRowExpression(assignment.expression, context),
          );
        }
        work.updates.set(token, { key, changes });
        return;
      }
      const values = branch.action.values;
      const columns =
        branch.action.columns.length > 0
          ? branch.action.columns
          : target.columns.map(({ name }) => name);
      if (columns.length !== values.length) {
        throw new TypeError("MERGE INSERT values must match the table's columns");
      }
      const row: Record<string, BatchValue> = {};
      columns.forEach((column, position) => {
        const value = values[position];
        if (value === undefined) return;
        const targetColumn = target.columns.find((candidate) => candidate.name === column);
        if (targetColumn === undefined) throw new TypeError(`Unknown column: ${column}`);
        row[column] = storedSqlValueFromExecution(
          targetColumn,
          evaluateJoinedRowExpression(value, context),
        );
      });
      work.inserts.push(row);
      return;
    }
  });
  return work;
}

/** Whether a view's body reads one table by name, at any depth of its query. */
function viewReadsTable(sql: string, table: string): boolean {
  try {
    return collectRealTableNames(compileQuery(sql)).includes(table);
  } catch {
    // A malformed stored dependency is corruption, not proof that destructive DDL is safe.
    return true;
  }
}

type QueryColumnShape = SqlColumnSchema;

function catalogQuerySchemas(records: readonly TableRecord[]): Map<string, QueryColumnShape[]> {
  return new Map(
    records.map((record) => [
      record.name,
      record.columns.map(({ name, type, integer, sqlDomain }) => ({
        name,
        type,
        ...(integer === true ? { integer: true as const } : {}),
        ...(sqlDomain === undefined ? {} : { sqlDomain }),
      })),
    ]),
  );
}

function querySchemasEqual(
  left: readonly QueryColumnShape[],
  right: readonly QueryColumnShape[],
): boolean {
  return (
    left.length === right.length &&
    left.every((column, index) => {
      const other = right[index];
      return (
        column.name === other?.name &&
        column.type === other.type &&
        column.integer === other.integer &&
        JSON.stringify(column.sqlDomain) === JSON.stringify(other.sqlDomain)
      );
    })
  );
}

function assertDependentViewsKeepSchema(
  records: readonly TableRecord[],
  replaced: TableRecord,
  candidateSchemas: ReadonlyMap<string, QueryColumnShape[]>,
): void {
  for (const dependent of records) {
    if (
      dependent.id === replaced.id ||
      dependent.view === undefined ||
      !viewReadsTable(dependent.view.sql, replaced.name)
    ) {
      continue;
    }
    try {
      const inferred = inferBlockSchema(compileQuery(dependent.view.sql), candidateSchemas);
      if (!querySchemasEqual(inferred, dependent.columns)) {
        throw new TypeError("view output would change");
      }
    } catch {
      throw new TypeError(
        `Cannot replace ${replaced.name}: view ${dependent.name} depends on its current schema`,
      );
    }
  }
}

function assertViewDefinitionAcyclic(
  records: readonly TableRecord[],
  viewName: string,
  plan: CompiledQuery,
): void {
  const views = new Map(
    records.flatMap((record) =>
      record.view === undefined ? [] : ([[record.name, record.view.sql]] as const),
    ),
  );
  const reaches = (name: string, target: string, visited: Set<string>): boolean => {
    if (name === target) return true;
    if (visited.has(name)) return false;
    visited.add(name);
    const sql = views.get(name);
    if (sql === undefined) return false;
    let dependencies: string[];
    try {
      dependencies = collectRealTableNames(compileQuery(sql));
    } catch {
      throw new TypeError(`Stored view has an invalid definition: ${name}`);
    }
    return dependencies.some((dependency) => reaches(dependency, target, visited));
  };
  if (
    collectRealTableNames(plan).some((dependency) =>
      reaches(dependency, viewName, new Set<string>()),
    )
  ) {
    throw new TypeError(`View dependency cycle: ${viewName}`);
  }
}

function assertTriggerBodyTargetSchema(
  compiled: Extract<CompiledStatement, { kind: "insert" | "update" | "delete" }>,
  target: TableRecord,
): void {
  const columns = visibleTableColumns(target);
  const columnsByName = new Map(columns.map((column) => [column.name, column] as const));
  if (compiled.kind === "insert") {
    let provided: Set<string>;
    let insertColumns: TableColumnRecord[] = [];
    if (compiled.defaultValues === true) {
      provided = new Set();
    } else if (compiled.columns.length === 0) {
      for (const row of compiled.rows) {
        if (row.length !== columns.length) {
          throw new TypeError(
            `Trigger body INSERT has ${String(row.length)} values for ${String(columns.length)} target columns`,
          );
        }
      }
      provided = new Set(columnsByName.keys());
      insertColumns = columns;
    } else {
      provided = new Set(compiled.columns);
      for (const name of provided) {
        if (!columnsByName.has(name)) {
          throw new TypeError(`Trigger body INSERT column does not exist: ${name}`);
        }
      }
      insertColumns = compiled.columns.flatMap((name) => {
        const column = columnsByName.get(name);
        return column === undefined ? [] : [column];
      });
    }
    for (const row of compiled.rows) {
      for (const [index, value] of row.entries()) {
        const column = insertColumns[index];
        if (
          column !== undefined &&
          isDefaultInsertValue(value) &&
          !column.nullable &&
          column.defaultValue === undefined &&
          column.generatedValue === undefined
        ) {
          throw new TypeError(
            `Trigger body INSERT uses DEFAULT for a non-nullable column without a default: ${column.name}`,
          );
        }
      }
    }
    for (const [index, column] of insertColumns.entries()) {
      if (column.generatedValue === undefined) continue;
      for (const row of compiled.rows) {
        const value = row[index];
        if (value === undefined || !isDefaultInsertValue(value)) {
          throw new TypeError(`Trigger body INSERT assigns generated column: ${column.name}`);
        }
      }
    }
    for (const column of columns) {
      if (
        !provided.has(column.name) &&
        !column.nullable &&
        column.defaultValue === undefined &&
        column.generatedValue === undefined
      ) {
        throw new TypeError(
          `Trigger body INSERT omits a non-nullable column without a default: ${column.name}`,
        );
      }
    }
    return;
  }

  const assertReference = (reference: string): void => {
    const pieces = reference.split(".");
    const name = pieces.at(-1) ?? reference;
    const qualifier = pieces.length === 2 ? pieces[0] : undefined;
    if (
      pieces.length > 2 ||
      (qualifier !== undefined && qualifier !== target.name) ||
      !columnsByName.has(name)
    ) {
      throw new TypeError(
        `Trigger body ${compiled.kind.toUpperCase()} column does not exist: ${reference}`,
      );
    }
  };
  if (compiled.kind === "update") {
    for (const assignment of compiled.assignments) {
      const assignedColumn = columnsByName.get(assignment.column);
      if (assignedColumn === undefined) {
        throw new TypeError(
          `Trigger body UPDATE assignment column does not exist: ${assignment.column}`,
        );
      }
      if (assignedColumn.generatedValue !== undefined) {
        throw new TypeError(`Trigger body UPDATE assigns generated column: ${assignment.column}`);
      }
      if (
        assignedColumn.id === target.uniqueKeyColumnId ||
        (target.primaryKeyColumnIds ?? []).includes(assignedColumn.id)
      ) {
        throw new TypeError(`Trigger body UPDATE cannot update a key column: ${assignment.column}`);
      }
      for (const reference of expressionColumnNames(assignment.expression)) {
        assertReference(reference);
      }
    }
  }
  for (const predicate of compiled.predicates) {
    for (const expression of [predicate.left, predicate.right]) {
      for (const reference of expressionColumnNames(expression)) assertReference(reference);
    }
  }
}

/** Every stored body that targets this table must remain executable after a schema change. */
function assertTriggerBodiesAcceptTableSchema(
  records: readonly TableRecord[],
  target: TableRecord,
  columns: TableColumnRecord[],
): void {
  const candidate = { ...target, columns };
  for (const owner of records) {
    for (const trigger of owner.triggers ?? []) {
      for (const statement of trigger.statements) {
        let compiled: CompiledStatement;
        try {
          compiled = compileStatement(statement.sql);
        } catch (error) {
          throw new TypeError(
            `Cannot alter ${target.name}: trigger ${trigger.name} has an invalid stored body`,
            { cause: error },
          );
        }
        if (
          (compiled.kind !== "insert" &&
            compiled.kind !== "update" &&
            compiled.kind !== "delete") ||
          compiled.table !== target.name
        ) {
          continue;
        }
        try {
          assertTriggerBodyTargetSchema(compiled, candidate);
        } catch (error) {
          throw new TypeError(
            `Cannot alter ${target.name}: trigger ${trigger.name} would become invalid: ${error instanceof Error ? error.message : String(error)}`,
            { cause: error },
          );
        }
      }
    }
  }
}

function triggerReferencesColumn(
  owner: TableRecord,
  trigger: NonNullable<TableRecord["triggers"]>[number],
  target: TableRecord,
  columnName: string,
  implicitInsertDepends = true,
): boolean {
  for (const statement of trigger.statements) {
    if (
      owner.id === target.id &&
      statement.bindings.some((binding) => binding.column === columnName)
    ) {
      return true;
    }
    let compiled: CompiledStatement;
    try {
      compiled = compileStatement(statement.sql);
    } catch {
      // A body that cannot be re-read cannot prove it is independent of the dropped column.
      return true;
    }
    if (
      (compiled.kind !== "insert" && compiled.kind !== "update" && compiled.kind !== "delete") ||
      compiled.table !== target.name
    ) {
      continue;
    }
    if (compiled.kind === "insert") {
      if (
        (compiled.columns.length === 0 && implicitInsertDepends) ||
        compiled.columns.includes(columnName)
      ) {
        return true;
      }
      continue;
    }
    const references = new Set<string>();
    for (const predicate of compiled.predicates) {
      for (const expression of [predicate.left, predicate.right]) {
        for (const name of expressionColumnNames(expression)) {
          references.add(name.split(".").at(-1) ?? name);
        }
      }
    }
    if (compiled.kind === "update") {
      for (const assignment of compiled.assignments) {
        references.add(assignment.column);
        for (const name of expressionColumnNames(assignment.expression)) {
          references.add(name.split(".").at(-1) ?? name);
        }
      }
    }
    if (references.has(columnName)) return true;
  }
  return false;
}

/**
 * The source-side expression a MERGE matches on. The condition has to be an equality naming the
 * target's unique key on one side, because that is the address the keyed write paths use; the
 * other side is what each source row contributes.
 */
function mergeSourceKeyExpression(
  statement: Extract<CompiledStatement, { kind: "merge" }>,
  keyColumn: string,
): Expression {
  const namesKey = (expression: Expression): boolean =>
    expression.kind === "column" &&
    (expression.reference === `${statement.alias}.${keyColumn}` ||
      expression.reference === keyColumn);
  const condition = statement.on;
  if (condition.kind === "condition" && condition.operator === "=") {
    if (namesKey(condition.left)) return condition.right;
    if (namesKey(condition.right)) return condition.left;
  }
  throw new TypeError(
    `MERGE ON must equate ${statement.alias}.${keyColumn} with a source value: the unique key is how rows are addressed`,
  );
}

/** The SELECT that materializes a MERGE's source rows under its correlation name. */
function mergeSourceSql(statement: Extract<CompiledStatement, { kind: "merge" }>): string {
  const alias = quoteSqlIdentifier(statement.source.alias);
  if (statement.source.table !== undefined) {
    return `SELECT * FROM ${quoteSqlIdentifier(statement.source.table)} AS ${alias}`;
  }
  const query = statement.source.sql;
  if (query === undefined) throw new TypeError("A MERGE source needs a table or a query");
  return `SELECT * FROM (${query}) AS ${alias}`;
}

/** True when a compiled block groups rows, either explicitly or through select aggregates. */
function compiledPlanIsGrouped(plan: CompiledQuery): boolean {
  return plan.groupBy.length > 0 || plan.select.some((item) => hasAggregate(item.expression));
}

function validateName(name: string, kind: string): string {
  const trimmed = name.trim();
  if (trimmed.length === 0) throw new TypeError(`${kind} name cannot be empty`);
  if (trimmed.length > MAX_CATALOG_NAME_CHARACTERS) {
    throw new TypeError(`${kind} name exceeds ${String(MAX_CATALOG_NAME_CHARACTERS)} characters`);
  }
  return trimmed;
}

function visibleSegmentManifestVersion(value: unknown, label: string): number | null | undefined {
  if (value === undefined || value === null) return value;
  if (!Number.isSafeInteger(value) || (value as number) < 0) {
    throw new RangeError(`${label} must be a non-negative safe integer or null`);
  }
  return value as number;
}

/**
 * Compiled CHECK expressions, keyed by table id and catalog revision rather than by the record
 * object: the store hands out a fresh clone on every read, so an identity-keyed cache would miss
 * every time and recompile the constraints once per written batch. A changed revision compiles
 * again, which is what makes an altered constraint take effect.
 */
const compiledChecks = new Map<string, ReadonlyArray<{ name: string; expression: Expression }>>();
const COMPILED_CHECK_CACHE_LIMIT = 64;
const compiledGeneratedColumns = new Map<
  string,
  ReadonlyArray<{ column: TableColumnRecord; expression: Expression }>
>();

function tableChecks(table: TableRecord): ReadonlyArray<{ name: string; expression: Expression }> {
  const key = `${table.id}/${String(table.revision)}`;
  const cached = compiledChecks.get(key);
  if (cached !== undefined) return cached;
  const compiled = (table.checks ?? []).map((check) => ({
    name: check.name,
    expression: compileCheckExpression(check.sql, check.name),
  }));
  const cacheable =
    (table.checks ?? []).reduce(
      (characters, check) => characters + check.name.length + check.sql.length,
      0,
    ) <= MAX_CACHEABLE_TEXT_CHARACTERS;
  if (!cacheable) return compiled;
  // Bounded and insertion-ordered: the oldest entry leaves, which is the table written least
  // recently. Constraint expressions are small, so the cap bounds the map, not the memory.
  if (compiledChecks.size >= COMPILED_CHECK_CACHE_LIMIT) {
    const oldest = compiledChecks.keys().next().value;
    if (oldest !== undefined) compiledChecks.delete(oldest);
  }
  compiledChecks.set(key, compiled);
  return compiled;
}

function tableGeneratedExpressions(
  table: TableRecord,
): ReadonlyArray<{ column: TableColumnRecord; expression: Expression }> {
  const key = `${table.id}/${String(table.revision)}`;
  const cached = compiledGeneratedColumns.get(key);
  if (cached !== undefined) return cached;
  const compiled = table.columns.flatMap((column) =>
    column.generatedValue === undefined
      ? []
      : [
          {
            column,
            expression: compileGeneratedColumnExpression(
              table.name,
              column.name,
              column.generatedValue.sql,
              table.columns,
            ),
          },
        ],
  );
  if (compiledGeneratedColumns.size >= COMPILED_CHECK_CACHE_LIMIT) {
    const oldest = compiledGeneratedColumns.keys().next().value;
    if (oldest !== undefined) compiledGeneratedColumns.delete(oldest);
  }
  compiledGeneratedColumns.set(key, compiled);
  return compiled;
}

function normalizeGeneratedColumnValue(
  column: TableColumnRecord,
  value: BatchValue,
  rowIndex: number,
): BatchValue {
  const stored =
    column.sqlDomain === undefined
      ? storedSqlValueFromExecution(column, value)
      : (normalizeSqlDomainValue(column.sqlDomain, value) as BatchValue);
  validateValue(column, stored, rowIndex);
  return stored;
}

/** Computes every stored generated column after defaults/domains have produced the base row. */
function fillStoredGeneratedColumns(
  table: TableRecord,
  batch: ColumnarBatch,
  rowCount: number,
  generated?: Map<string, BatchValue[]>,
): void {
  for (const { column, expression } of tableGeneratedExpressions(table)) {
    const values = new Array<BatchValue>(rowCount);
    for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
      const row = batchRowAt(table, batch, rowIndex);
      const value = evaluateRowExpression(expression, table.name, row);
      values[rowIndex] = normalizeGeneratedColumnValue(column, value, rowIndex);
    }
    (batch.columns as Record<string, readonly BatchValue[]>)[column.name] = values;
    generated?.set(
      column.name,
      values.map((value) => externalSqlDomainValue(value) as BatchValue),
    );
  }
}

function rejectGeneratedUpdateAssignments(table: TableRecord, input: UpdateBatchInput): void {
  for (const column of table.columns) {
    if (column.generatedValue !== undefined && input.changes[column.name] !== undefined) {
      throw new TypeError(`Generated column cannot be assigned: ${column.name}`);
    }
  }
}

function generatedEvaluationRow(
  table: TableRecord,
  source: Record<string, BatchValue>,
): Record<string, BatchValue> {
  const row: Record<string, BatchValue> = {};
  for (const column of table.columns) {
    const value = source[column.name] ?? null;
    row[column.name] =
      column.sqlDomain === undefined
        ? executionSqlValueFromStorage(column, value)
        : normalizeSqlDomainValue(column.sqlDomain, value);
  }
  return row;
}

function applyStoredGeneratedUpdateChanges(
  table: TableRecord,
  input: UpdateBatchInput,
  preImages: ReadonlyArray<Record<string, BatchValue> | undefined>,
): UpdateBatchInput {
  const generated = tableGeneratedExpressions(table);
  if (generated.length === 0) return input;
  const changes: Record<string, readonly BatchValue[]> = { ...input.changes };
  for (const { column, expression } of generated) {
    changes[column.name] = input.keys.map((_, rowIndex) => {
      const old = preImages[rowIndex];
      if (old === undefined)
        throw new Error(`Generated-column pre-image is missing: ${table.name}`);
      const row = generatedEvaluationRow(table, old);
      for (const [name, values] of Object.entries(input.changes)) {
        row[name] = values[rowIndex] ?? null;
      }
      return normalizeGeneratedColumnValue(
        column,
        evaluateRowExpression(expression, table.name, row),
        rowIndex,
      );
    });
  }
  return { keys: input.keys, changes };
}

/**
 * Applies a table's CHECK constraints to one row (E141-06). A constraint fails only when it
 * evaluates to false: SQL's three-valued logic lets an unknown pass, which is why a NULL column
 * satisfies `CHECK (amount > 0)` unless the column is also NOT NULL.
 */
function assertRowChecks(table: TableRecord, row: Record<string, BatchValue>, index: number): void {
  for (const check of tableChecks(table)) {
    let value: unknown;
    try {
      // The row binds under the table's own name, so `CHECK (t.a > 0)` and `CHECK (a > 0)`
      // both resolve.
      value = evaluateRowExpression(check.expression, table.name, row);
    } catch (error) {
      throw new TypeError(
        `CHECK ${check.name} could not be evaluated for row ${String(index)}: ${
          error instanceof Error ? error.message : String(error)
        }`,
        { cause: error },
      );
    }
    if (value === false) {
      throw new TypeError(`CHECK ${check.name} failed for row ${String(index)} of ${table.name}`);
    }
  }
}

/** Reads one row out of a columnar batch, for the row-shaped checks. */
function batchRowAt(
  table: TableRecord,
  input: ColumnarBatch,
  index: number,
): Record<string, BatchValue> {
  const row: Record<string, BatchValue> = {};
  for (const column of table.columns)
    row[column.name] = input.columns[column.name]?.[index] ?? null;
  return row;
}

/**
 * Exact UTF-8 lengths measured by input validation, keyed by the caller's column array. The weak
 * keys keep this operation-local in practice: once a batch is released, its sizing data follows
 * it. Range planning can reuse the validation pass instead of walking every string a second time.
 */
const validatedStringByteLengths = new WeakMap<readonly BatchValue[], readonly number[]>();

function validateBatch(table: TableRecord, input: ColumnarBatch, pendingColumn?: string): number {
  const expected = new Set(table.columns.map((column) => column.name));
  for (const name of Object.keys(input.columns)) {
    if (!expected.has(name)) throw new TypeError(`Unknown column: ${name}`);
  }
  for (const column of table.columns) {
    if (!(column.name in input.columns)) throw new TypeError(`Missing column: ${column.name}`);
  }
  const first = table.columns[0];
  if (first === undefined) throw new Error("Table has no columns");
  const rowCount = input.columns[first.name]?.length ?? 0;
  if (rowCount === 0) throw new TypeError("A batch needs at least one row");
  for (const column of table.columns) {
    const values = input.columns[column.name] ?? [];
    if (values.length !== rowCount) throw new TypeError("All columns must have the same row count");
    // The pending auto-increment column keeps its null slots until the write path reserves a
    // range from storage, so nulls pass here; every explicit value still type-checks.
    const allowNull = column.name === pendingColumn;
    // An index loop rather than forEach: forEach skips holes in sparse arrays, which would let an
    // undefined value reach the block encoder and persist a corrupt block that only fails at read
    // time. Every slot is validated, holes included.
    const stringByteLengths =
      column.type === "string" ? new Array<number>(values.length) : undefined;
    for (let index = 0; index < values.length; index += 1) {
      const value = values[index] as BatchValue;
      if (allowNull && value === null) {
        if (stringByteLengths !== undefined) stringByteLengths[index] = 0;
        continue;
      }
      const byteLength = validateValue(column, value, index);
      if (stringByteLengths !== undefined) stringByteLengths[index] = byteLength ?? 0;
    }
    if (stringByteLengths !== undefined) validatedStringByteLengths.set(values, stringByteLengths);
  }
  // The constraints run last, over whole rows, once every column has been type-checked.
  if ((table.checks ?? []).length > 0) {
    for (let index = 0; index < rowCount; index += 1) {
      assertRowChecks(table, batchRowAt(table, input, index), index);
    }
  }
  return rowCount;
}

/** Folds the storage-generated auto-increment vector into the generated-columns result map. */
function collectAutoIncrementGenerated(
  batch: ColumnarBatch,
  generated: Map<string, BatchValue[]>,
  autoIncrement: AutoIncrementFill | undefined,
): void {
  if (autoIncrement === undefined || autoIncrement.missingIndexes.length === 0) return;
  generated.set(autoIncrement.column.name, [...(batch.columns[autoIncrement.column.name] ?? [])]);
}

function validateUpdateBatch(
  table: TableRecord,
  keyColumn: TableColumnRecord,
  input: UpdateBatchInput,
): Map<string, Exclude<BatchValue, null>> {
  if (input.keys.length === 0) throw new TypeError("An update batch needs at least one key");
  const changeNames = Object.keys(input.changes);
  if (changeNames.length === 0) throw new TypeError("An update batch needs at least one change");
  const keys = new Map<string, Exclude<BatchValue, null>>();
  const keyStringByteLengths =
    keyColumn.type === "string" ? new Array<number>(input.keys.length) : undefined;
  for (let index = 0; index < input.keys.length; index += 1) {
    const value = input.keys[index] as BatchValue;
    const byteLength = validateValue(keyColumn, value, index);
    if (keyStringByteLengths !== undefined) keyStringByteLengths[index] = byteLength ?? 0;
    if (value === null) throw new TypeError(`Unique key cannot be null: ${keyColumn.name}`);
    const token = keyToken(keyColumn.type, value);
    if (keys.has(token)) throw new TypeError(`Duplicate update key: ${formatValue(value)}`);
    keys.set(token, value);
  }
  if (keyStringByteLengths !== undefined) {
    validatedStringByteLengths.set(input.keys, keyStringByteLengths);
  }
  for (const name of changeNames) {
    const column = table.columns.find((candidate) => candidate.name === name);
    if (column === undefined) throw new TypeError(`Unknown column: ${name}`);
    if (column.id === keyColumn.id) throw new TypeError(`Unique key cannot be updated: ${name}`);
    if ((table.primaryKeyColumnIds ?? []).includes(column.id)) {
      throw new TypeError(`Primary key column cannot be updated: ${name}`);
    }
    const values = input.changes[name] ?? [];
    if (values.length !== input.keys.length) {
      throw new TypeError("Every changed column must have the same row count as the keys");
    }
    const stringByteLengths =
      column.type === "string" ? new Array<number>(values.length) : undefined;
    for (let index = 0; index < values.length; index += 1) {
      const value = values[index] as BatchValue;
      const byteLength = validateValue(column, value, index);
      if (stringByteLengths !== undefined) stringByteLengths[index] = byteLength ?? 0;
    }
    if (stringByteLengths !== undefined) validatedStringByteLengths.set(values, stringByteLengths);
  }
  return keys;
}

function findColumn(table: TableRecord, name: string): TableColumnRecord {
  const column = table.columns.find((candidate) => candidate.name === name);
  if (column === undefined) throw new Error(`Column not found: ${name}`);
  return column;
}

function resolveReadColumns(
  table: TableRecord,
  names: readonly string[] | undefined,
): TableColumnRecord[] {
  if (names === undefined) return table.columns;
  if (names.length === 0) throw new TypeError("A projected read needs at least one column");
  const seen = new Set<string>();
  return names.map((name) => {
    if (seen.has(name)) throw new TypeError(`Duplicate projected column: ${name}`);
    seen.add(name);
    const column = table.columns.find((candidate) => candidate.name === name);
    if (column === undefined) throw new TypeError(`Unknown column: ${name}`);
    return column;
  });
}

/** Public table reads never reveal physical implementation columns, even by explicit name. */
function resolvePublicReadColumns(
  table: TableRecord,
  names: readonly string[] | undefined,
): TableColumnRecord[] {
  const visible = visibleTableColumns(table);
  if (names === undefined) return visible;
  if (names.length === 0) throw new TypeError("A projected read needs at least one column");
  const seen = new Set<string>();
  return names.map((name) => {
    if (seen.has(name)) throw new TypeError(`Duplicate projected column: ${name}`);
    seen.add(name);
    const column = visible.find((candidate) => candidate.name === name);
    if (column === undefined) throw new TypeError(`Unknown column: ${name}`);
    return column;
  });
}

function validateValue(
  column: TableColumnRecord,
  value: BatchValue,
  index: number,
): number | undefined {
  if (value === null) {
    if (!column.nullable) throw new TypeError(`${column.name}[${String(index)}] cannot be null`);
    return column.type === "string" ? 0 : undefined;
  }
  const valid =
    (column.type === "boolean" && typeof value === "boolean") ||
    (column.type === "number" &&
      typeof value === "number" &&
      Number.isFinite(value) &&
      (column.integer !== true || Number.isSafeInteger(value))) ||
    (column.type === "string" && typeof value === "string") ||
    (column.type === "datetime" &&
      value instanceof Date &&
      Number.isFinite(dateMilliseconds(value)));
  if (!valid) {
    throw new TypeError(
      `${column.name}[${String(index)}] must be ${column.integer === true ? "a safe integer" : column.type}`,
    );
  }
  const stringByteLength =
    column.type === "string" && typeof value === "string"
      ? wellFormedUtf8ByteLength(value, `${column.name}[${String(index)}]`)
      : undefined;
  if (
    column.enumValues !== undefined &&
    typeof value === "string" &&
    !column.enumValues.includes(value)
  ) {
    throw new TypeError(
      `${column.name}[${String(index)}] must be one of: ${column.enumValues.join(", ")}`,
    );
  }
  return stringByteLength;
}

/** Merges per-column sorted row-id arrays into one sorted, de-duplicated array. */
function unionSortedRowIds(arrays: ReadonlyArray<readonly bigint[]>): bigint[] {
  const nonEmpty = arrays.filter((array) => array.length > 0);
  if (nonEmpty.length === 0) return [];
  if (nonEmpty.length === 1) return [...(nonEmpty[0] ?? [])];
  // Pairwise linear merges: inputs are already sorted, so no comparison sort is needed.
  let merged: readonly bigint[] = nonEmpty[0] ?? [];
  for (let index = 1; index < nonEmpty.length; index += 1) {
    const other = nonEmpty[index] ?? [];
    const result: bigint[] = [];
    let leftIndex = 0;
    let rightIndex = 0;
    while (leftIndex < merged.length && rightIndex < other.length) {
      const left = merged[leftIndex] ?? 0n;
      const right = other[rightIndex] ?? 0n;
      const next = left <= right ? left : right;
      if (left <= right) leftIndex += 1;
      if (right <= left) rightIndex += 1;
      if (result.length === 0 || result[result.length - 1] !== next) result.push(next);
    }
    while (leftIndex < merged.length) {
      const value = merged[leftIndex] ?? 0n;
      if (result.length === 0 || result[result.length - 1] !== value) result.push(value);
      leftIndex += 1;
    }
    while (rightIndex < other.length) {
      const value = other[rightIndex] ?? 0n;
      if (result.length === 0 || result[result.length - 1] !== value) result.push(value);
      rightIndex += 1;
    }
    merged = result;
  }
  return merged as bigint[];
}

/** Two-pointer intersection of sorted row-id arrays. */
function intersectSortedRowIds(left: readonly bigint[], right: readonly bigint[]): bigint[] {
  const result: bigint[] = [];
  let leftIndex = 0;
  let rightIndex = 0;
  while (leftIndex < left.length && rightIndex < right.length) {
    const a = left[leftIndex] ?? 0n;
    const b = right[rightIndex] ?? 0n;
    if (a === b) {
      result.push(a);
      leftIndex += 1;
      rightIndex += 1;
    } else if (a < b) {
      leftIndex += 1;
    } else {
      rightIndex += 1;
    }
  }
  return result;
}

/** Whether any sorted row id falls inside [start, endExclusive) — one binary search. */
function sortedRowIdsIntersectRange(
  sorted: readonly bigint[],
  start: bigint,
  endExclusive: bigint,
): boolean {
  let low = 0;
  let high = sorted.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if ((sorted[middle] ?? 0n) < start) low = middle + 1;
    else high = middle;
  }
  return low < sorted.length && (sorted[low] ?? 0n) < endExclusive;
}

/**
 * Tokenizes one cell into the term accumulator, tracking per-document term frequency, and
 * returns the cell's token count so producers can total the column's tokens for BM25 stats.
 */
function addFtsDocument(
  byTerm: Map<string, { rowIds: bigint[]; tf: number[] }>,
  value: BatchValue,
  rowId: bigint,
): number {
  const rendered = renderDocumentValue(value);
  if (rendered === undefined) return 0;
  const tokens = ftsTokenize(rendered);
  const counts = new Map<string, number>();
  for (const token of tokens) counts.set(token, (counts.get(token) ?? 0) + 1);
  for (const [term, tf] of counts) {
    const posting = byTerm.get(term) ?? { rowIds: [], tf: [] };
    posting.rowIds.push(rowId);
    posting.tf.push(tf);
    byTerm.set(term, posting);
  }
  return tokens.length;
}

function sortedFtsPostings(byTerm: Map<string, { rowIds: bigint[]; tf: number[] }>): FtsPosting[] {
  return [...byTerm.entries()]
    .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
    .map(([term, posting]) => ({ term, rowIds: posting.rowIds, tf: posting.tf }));
}

function postingFrequencyTotal(postings: readonly FtsPosting[]): number {
  let total = 0;
  for (const posting of postings) {
    for (const frequency of posting.tf) {
      total = safeWholeNumberSum([total, frequency], "Posting term-frequency total");
    }
  }
  return total;
}

const secondaryNumberBits = new DataView(new ArrayBuffer(8));

/** Converts a SQL evaluator's unambiguous TEXT representation back to its physical user value. */
function storedSqlValueFromExecution(
  column: Pick<TableColumnRecord, "type" | "sqlDomain"> | undefined,
  value: BatchValue,
): BatchValue {
  if (column?.type === "string" && column.sqlDomain === undefined && typeof value === "string") {
    return externalSqlTextValue(value) as BatchValue;
  }
  return coerceSqlWriteValue(column, value);
}

/**
 * A SQL statement's untyped string constant or parameter reaching a datetime, number, or
 * boolean column is read in the column's type — `SET at = '2026-04-01'`, `VALUES (1, '7')`,
 * a string bound to `$1` — as PostgreSQL types an unknown-typed literal by its target. Text that
 * does not parse is left for validation to refuse. Domain columns (DATE, NUMERIC, …) already
 * normalize their text through the domain, and the typed programmatic API never passes here.
 */
function coerceSqlWriteValue(
  column: Pick<TableColumnRecord, "type" | "sqlDomain"> | undefined,
  value: BatchValue,
): BatchValue {
  if (
    column === undefined ||
    column.sqlDomain !== undefined ||
    column.type === "string" ||
    typeof value !== "string" ||
    isSqlDomainValue(value)
  ) {
    return value;
  }
  return readUntypedText(column.type, value) as BatchValue;
}

/** Applies `coerceSqlWriteValue` to every typed column of a SQL INSERT batch, in place. */
function coerceSqlWriteBatch(table: TableRecord, input: ColumnarBatch): void {
  for (const column of table.columns) {
    if (column.type === "string" || column.sqlDomain !== undefined) continue;
    const values = input.columns[column.name];
    if (!values?.some((value) => typeof value === "string")) continue;
    (input.columns as Record<string, readonly BatchValue[]>)[column.name] = values.map((value) =>
      coerceSqlWriteValue(column, value),
    );
  }
}

/** Protects a physical plain-TEXT value before a schema-less result externalizer sees it. */
function executionSqlValueFromStorage(
  column: Pick<TableColumnRecord, "type" | "sqlDomain"> | undefined,
  value: BatchValue,
): BatchValue {
  return column?.type === "string" && column.sqlDomain === undefined && typeof value === "string"
    ? protectedSqlTextValue(value)
    : value;
}

/** Canonicalizes an INSERT input exactly as storage does before exposing it through RETURNING. */
function executionSqlValueFromInput(
  column: Pick<TableColumnRecord, "type" | "sqlDomain"> | undefined,
  value: BatchValue,
): BatchValue {
  const stored =
    column?.sqlDomain === undefined
      ? value
      : (normalizeSqlDomainValue(column.sqlDomain, value) as BatchValue);
  return executionSqlValueFromStorage(column, stored);
}

/** Lexicographic scalar encoding whose byte order is the engine's SQL order for one type. */
function secondaryIndexTerm(type: SimpleDataType, value: BatchValue): string {
  if (value === null) throw new TypeError("A NULL has no secondary-index comparison term");
  if (type === "string") {
    if (typeof value !== "string") throw new TypeError("Invalid string index value");
    assertIndexedStringLength(value);
    return value;
  }
  if (type === "boolean") {
    if (typeof value !== "boolean") throw new TypeError("Invalid boolean index value");
    return value ? "1" : "0";
  }
  const numeric = type === "datetime" && value instanceof Date ? dateMilliseconds(value) : value;
  if (typeof numeric !== "number" || !Number.isFinite(numeric)) {
    throw new TypeError(`Invalid ${type} index value`);
  }
  secondaryNumberBits.setFloat64(0, numeric === 0 ? 0 : numeric, false);
  const bits = secondaryNumberBits.getBigUint64(0, false);
  const sortable =
    (bits & 0x8000_0000_0000_0000n) === 0n
      ? bits ^ 0x8000_0000_0000_0000n
      : ~bits & 0xffff_ffff_ffff_ffffn;
  return sortable.toString(16).padStart(16, "0");
}

/** Prefix-free hexadecimal scalar component used by tuple-v1 composite keys. */
function secondaryTupleComponent(type: SimpleDataType, value: BatchValue): string {
  if (value === null) throw new TypeError("A NULL has no secondary-index comparison term");
  if (type === "string") {
    if (typeof value !== "string") throw new TypeError("Invalid string index value");
    assertIndexedStringLength(value);
    if (value.length * 5 + 5 > MAX_FTS_POSTING_TERM_CHARACTERS) {
      throw new RangeError("Composite index term exceeds the persisted term limit");
    }
    let encoded = "";
    for (let index = 0; index < value.length; index += 1) {
      encoded += (value.charCodeAt(index) + 1).toString(16).padStart(5, "0");
    }
    return `${encoded}00000`;
  }
  if (type === "boolean") {
    if (typeof value !== "boolean") throw new TypeError("Invalid boolean index value");
    return value ? "1" : "0";
  }
  return secondaryIndexTerm(type, value);
}

const reversedHex = new Map(
  Array.from("0123456789abcdef", (character, index) => [
    character,
    "fedcba9876543210"[index] ?? "",
  ]),
);

/** Reverses the order of an internal hexadecimal term one UTF-16 code unit at a time. */
function reverseSecondaryHex(input: string): string {
  let output = "";
  for (let index = 0; index < input.length; index += 1) {
    const character = input.charAt(index);
    const reversed = reversedHex.get(character);
    if (reversed === undefined) throw new Error("Secondary index has a non-hexadecimal term");
    output += reversed;
  }
  return output;
}

function secondaryTupleIndexTerm(
  index: SecondaryIndexRecord,
  columns: readonly TableColumnRecord[],
  values: readonly BatchValue[],
): string {
  if (columns.length !== values.length) throw new TypeError("Index key has the wrong arity");
  const directions = secondaryIndexDirections(index);
  let term = "";
  for (const [position, column] of columns.entries()) {
    const component = secondaryTupleComponent(column.type, values[position] ?? null);
    if (term.length + component.length > MAX_FTS_POSTING_TERM_CHARACTERS) {
      throw new RangeError("Composite index term exceeds the persisted term limit");
    }
    term += directions[position] === "desc" ? reverseSecondaryHex(component) : component;
  }
  return term;
}

function secondaryIndexComponentTerm(
  index: SecondaryIndexRecord,
  column: TableColumnRecord,
  position: number,
  value: BatchValue,
): string {
  const component = secondaryTupleComponent(column.type, value);
  if (secondaryIndexDirections(index)[position] !== "desc") return component;
  return reverseSecondaryHex(component);
}

function decodeSecondaryTupleTerm(
  index: SecondaryIndexRecord,
  columns: readonly TableColumnRecord[],
  term: string,
): BatchValue[] {
  const directions = secondaryIndexDirections(index);
  let offset = 0;
  const values = columns.map((column, position) => {
    const descending = directions[position] === "desc";
    const restore = (encoded: string): string =>
      descending ? reverseSecondaryHex(encoded) : encoded;
    if (column.type === "string") {
      let value = "";
      for (;;) {
        const group = restore(term.slice(offset, offset + 5));
        if (group.length !== 5) throw new Error(`Secondary index ${index.name} has a bad term`);
        offset += 5;
        if (group === "00000") return value;
        const code = Number.parseInt(group, 16) - 1;
        if (!Number.isInteger(code) || code < 0 || code > 0xffff) {
          throw new Error(`Secondary index ${index.name} has a bad string term`);
        }
        value += String.fromCharCode(code);
      }
    }
    if (column.type === "boolean") {
      const encoded = restore(term.slice(offset, offset + 1));
      offset += 1;
      if (encoded !== "0" && encoded !== "1") {
        throw new Error(`Secondary index ${index.name} has a bad boolean term`);
      }
      return encoded === "1";
    }
    const encoded = restore(term.slice(offset, offset + 16));
    if (encoded.length !== 16) throw new Error(`Secondary index ${index.name} has a bad term`);
    offset += 16;
    const sortable = BigInt(`0x${encoded}`);
    const bits =
      (sortable & 0x8000_0000_0000_0000n) === 0n
        ? ~sortable & 0xffff_ffff_ffff_ffffn
        : sortable ^ 0x8000_0000_0000_0000n;
    secondaryNumberBits.setBigUint64(0, bits, false);
    const value = secondaryNumberBits.getFloat64(0, false);
    return column.type === "datetime" ? new Date(value) : value;
  });
  if (offset !== term.length) throw new Error(`Secondary index ${index.name} has a bad term`);
  return values;
}

/** Stable 32-bit key locator. Collisions retain extra candidates and are rechecked by SQL. */
function secondaryKeyLocator(type: SimpleDataType, value: BatchValue): bigint {
  const token = keyToken(type, value);
  let hash = 0x811c9dc5;
  for (let index = 0; index < token.length; index += 1) {
    const code = token.charCodeAt(index);
    hash = Math.imul(hash ^ (code & 0xff), 0x01000193) >>> 0;
    hash = Math.imul(hash ^ (code >>> 8), 0x01000193) >>> 0;
  }
  return BigInt(hash >>> 0);
}

function addSecondaryPosting(
  byTerm: Map<string, { rowIds: bigint[]; tf: number[] }>,
  index: SecondaryIndexRecord,
  columns: readonly TableColumnRecord[],
  values: readonly BatchValue[],
  locator: bigint,
  uniqueTerms?: Set<string>,
): void {
  if (values.some((value) => value === null)) return;
  const first = columns[0];
  if (first === undefined) return;
  const term = secondaryTupleIndexTerm(index, columns, values);
  if (uniqueTerms?.has(term) === true) {
    throw new TypeError(`UNIQUE index ${index.name} has a duplicate key`);
  }
  uniqueTerms?.add(term);
  const posting = byTerm.get(term) ?? { rowIds: [], tf: [] };
  posting.rowIds.push(locator);
  posting.tf.push(1);
  byTerm.set(term, posting);
}

function sortedSecondaryPostings(
  byTerm: Map<string, { rowIds: bigint[]; tf: number[] }>,
): FtsPosting[] {
  return [...byTerm.entries()]
    .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
    .map(([term, posting]) => {
      const rowIds = [...new Set(posting.rowIds)].sort((left, right) =>
        left < right ? -1 : left > right ? 1 : 0,
      );
      return { term, rowIds, tf: rowIds.map(() => 1) };
    });
}

/** Hidden row-ID lookup over append/base segment order without retaining one bigint per row. */
function appendRowIdLocator(
  segments: readonly SegmentRecord[],
  expectedRows: number,
): (row: number) => bigint {
  const spans = appendRowIdSpans(segments, expectedRows);
  let spanIndex = 0;
  return (row) => {
    while (
      spanIndex < spans.length &&
      row >= (spans[spanIndex]?.rowStart ?? 0) + (spans[spanIndex]?.rowCount ?? 0)
    ) {
      spanIndex += 1;
    }
    const span = spans[spanIndex];
    if (span === undefined || row < span.rowStart) {
      throw new Error(`Secondary-index row ID is missing: ${String(row)}`);
    }
    return span.rowIdStart + BigInt(row - span.rowStart);
  };
}

/** Visible append/base row-ID spans with their logical output offsets attached. */
function appendRowIdSpans(segments: readonly SegmentRecord[], expectedRows: number): RowIdSpan[] {
  const spans: RowIdSpan[] = [];
  let outputStart = 0;
  for (const segment of segments) {
    const kind = segment.kind;
    if (kind !== "insert" && kind !== "base") continue;
    for (const span of mergeSourceRowIdSpans(segment, kind)) {
      spans.push({ ...span, rowStart: outputStart + span.rowStart });
    }
    outputStart += segment.rowCount;
  }
  const rows = spans.reduce((total, span) => total + span.rowCount, 0);
  if (rows !== expectedRows) throw new Error("Secondary-index row IDs differ from table rows");
  return spans;
}

/** Inverse append locator without allocating a bigint-keyed Map entry for every visible row. */
function appendRowForLocator(
  segments: readonly SegmentRecord[],
  expectedRows: number,
): (locator: bigint) => number | undefined {
  const spans = appendRowIdSpans(segments, expectedRows).sort((left, right) =>
    left.rowIdStart < right.rowIdStart ? -1 : left.rowIdStart > right.rowIdStart ? 1 : 0,
  );
  return (locator) => {
    let low = 0;
    let high = spans.length;
    while (low < high) {
      const middle = (low + high) >>> 1;
      if ((spans[middle]?.rowIdStart ?? 0n) <= locator) low = middle + 1;
      else high = middle;
    }
    const span = spans[low - 1];
    if (span === undefined) return undefined;
    const offset = locator - span.rowIdStart;
    if (offset < 0n || offset >= BigInt(span.rowCount)) return undefined;
    return span.rowStart + Number(offset);
  };
}

/** Term-range partitioning bounded by both record count and aggregate posting cardinality. */
function chunkFtsPostings(postings: FtsPosting[], size = 128): FtsPosting[][] {
  const chunks: FtsPosting[][] = [];
  let chunk: FtsPosting[] = [];
  let rowIds = 0;
  const flush = (): void => {
    if (chunk.length === 0) return;
    chunks.push(chunk);
    chunk = [];
    rowIds = 0;
  };
  for (const posting of postings) {
    if (posting.rowIds.length > MAX_FTS_POSTING_ROW_IDS_PER_CHUNK) {
      throw new RangeError("One posting exceeds the persisted row-id chunk limit");
    }
    if (
      chunk.length >= Math.min(size, MAX_FTS_POSTINGS_PER_CHUNK) ||
      rowIds + posting.rowIds.length > MAX_FTS_POSTING_ROW_IDS_PER_CHUNK
    ) {
      flush();
    }
    chunk.push(posting);
    rowIds += posting.rowIds.length;
  }
  flush();
  return chunks;
}

/** Tokenizes an insert batch's values for every active full-text column into commit deltas. */
function buildFtsColumnDeltas(
  table: TableRecord,
  input: ColumnarBatch,
  rowIdStart: bigint,
): FtsColumnDelta[] {
  const active = Object.entries(table.ftsColumns ?? {}).filter(
    ([, record]) => record.state !== "invalid",
  );
  if (active.length === 0) return [];
  const columnsById = new Map(table.columns.map((column) => [column.id, column] as const));
  return active.flatMap(([columnId]) => {
    const column = columnsById.get(columnId);
    if (column === undefined) return [];
    const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
    let totalTokens = 0;
    (input.columns[column.name] ?? []).forEach((value, index) => {
      const documentValue =
        column.type === "string" && column.sqlDomain === undefined && typeof value === "string"
          ? protectedSqlTextValue(value)
          : value;
      totalTokens += addFtsDocument(byTerm, documentValue, rowIdStart + BigInt(index));
    });
    return [{ columnId, postings: sortedFtsPostings(byTerm), totalTokens }];
  });
}

/** Scalar postings for an inserted/replaced full row, including empty coverage entries. */
function buildSecondaryInsertDeltas(
  table: TableRecord,
  input: ColumnarBatch,
  rowIdStart: bigint,
): FtsColumnDelta[] {
  const active = Object.values(table.secondaryIndexes ?? {}).filter(
    (index) => index.state !== "invalid",
  );
  if (active.length === 0) return [];
  const columnsById = new Map(table.columns.map((column) => [column.id, column] as const));
  const keyColumn = getUniqueKeyColumn(table);
  return active.flatMap((index) => {
    const columns = secondaryIndexColumnIds(index).map((columnId) => columnsById.get(columnId));
    if (columns.some((column) => column === undefined)) return [];
    const indexedColumns = columns as TableColumnRecord[];
    const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
    const keys = keyColumn === undefined ? undefined : (input.columns[keyColumn.name] ?? []);
    const rowCount = input.rowCount ?? Object.values(input.columns)[0]?.length ?? 0;
    try {
      for (let row = 0; row < rowCount; row += 1) {
        const values = indexedColumns.map((column) => input.columns[column.name]?.[row] ?? null);
        if (values.some((value) => value === null)) continue;
        const locator =
          keyColumn === undefined
            ? rowIdStart + BigInt(row)
            : secondaryKeyLocator(keyColumn.type, keys?.[row] ?? null);
        addSecondaryPosting(byTerm, index, indexedColumns, values, locator);
      }
    } catch (error) {
      if (error instanceof RangeError && index.unique !== true) return [];
      throw error;
    }
    const postings = sortedSecondaryPostings(byTerm);
    return [
      {
        columnId: index.storageColumnId,
        postings,
        totalTokens: postingFrequencyTotal(postings),
      },
    ];
  });
}

/** Scalar postings for changed indexed values; unchanged indexes still carry stale-writer coverage. */
function buildSecondaryUpdateDeltas(
  table: TableRecord,
  input: UpdateBatchInput,
  preImages: ReadonlyArray<Record<string, BatchValue> | undefined> = [],
): FtsColumnDelta[] {
  const active = Object.values(table.secondaryIndexes ?? {}).filter(
    (index) => index.state !== "invalid",
  );
  if (active.length === 0) return [];
  const keyColumn = getUniqueKeyColumn(table);
  if (keyColumn === undefined) return [];
  const columnsById = new Map(table.columns.map((column) => [column.id, column] as const));
  return active.flatMap((index) => {
    const columns = secondaryIndexColumnIds(index).map((columnId) => columnsById.get(columnId));
    if (columns.some((column) => column === undefined)) return [];
    const indexedColumns = columns as TableColumnRecord[];
    const byTerm = new Map<string, { rowIds: bigint[]; tf: number[] }>();
    const affected = indexedColumns.some((column) => input.changes[column.name] !== undefined);
    if (affected) {
      try {
        for (let row = 0; row < input.keys.length; row += 1) {
          const values = indexedColumns.map((column) =>
            input.changes[column.name] === undefined
              ? (preImages[row]?.[column.name] ?? null)
              : (input.changes[column.name]?.[row] ?? null),
          );
          if (values.some((value) => value === null)) continue;
          addSecondaryPosting(
            byTerm,
            index,
            indexedColumns,
            values,
            secondaryKeyLocator(keyColumn.type, input.keys[row] ?? null),
          );
        }
      } catch (error) {
        if (error instanceof RangeError && index.unique !== true) return [];
        throw error;
      }
    }
    const postings = sortedSecondaryPostings(byTerm);
    return [
      {
        columnId: index.storageColumnId,
        postings,
        totalTokens: postingFrequencyTotal(postings),
      },
    ];
  });
}

function secondaryIndexUpdateNeedsPreImages(table: TableRecord, input: UpdateBatchInput): boolean {
  const changed = new Set(Object.keys(input.changes));
  const columnsById = new Map(table.columns.map((column) => [column.id, column.name] as const));
  return Object.values(table.secondaryIndexes ?? {}).some((index) => {
    if (index.state === "invalid") return false;
    const names = secondaryIndexColumnIds(index).map((columnId) => columnsById.get(columnId));
    return (
      names.some((name) => name !== undefined && changed.has(name)) &&
      names.some((name) => name === undefined || !changed.has(name))
    );
  });
}

/** Empty postings still prove that a delete writer observed every active scalar index. */
function buildSecondaryDeleteCoverage(table: TableRecord): FtsColumnDelta[] {
  return Object.values(table.secondaryIndexes ?? {}).flatMap((index) =>
    index.state === "invalid"
      ? []
      : [
          {
            columnId: index.storageColumnId,
            postings: [],
            totalTokens: 0,
          },
        ],
  );
}

function readyUniqueSecondaryIndexes(
  table: TableRecord,
): Array<{ indexId: string; index: SecondaryIndexRecord; columns: TableColumnRecord[] }> {
  const columnsById = new Map(table.columns.map((column) => [column.id, column] as const));
  return Object.entries(table.secondaryIndexes ?? {}).flatMap(([indexId, index]) => {
    if (index.unique !== true || index.uniqueEnforced !== true) return [];
    const columns = secondaryIndexColumnIds(index).map((columnId) => columnsById.get(columnId));
    return columns.some((column) => column === undefined)
      ? []
      : [{ indexId, index, columns: columns as TableColumnRecord[] }];
  });
}

function secondaryUniqueTerm(
  index: SecondaryIndexRecord,
  columns: readonly TableColumnRecord[],
  values: readonly BatchValue[],
): string | undefined {
  if (values.some((value) => value === null)) return undefined;
  return secondaryTupleIndexTerm(index, columns, values);
}

function assertNoDuplicateUniqueTerms(index: SecondaryIndexRecord, terms: readonly string[]): void {
  const seen = new Set<string>();
  for (const term of terms) {
    if (seen.has(term)) throw new TypeError(`UNIQUE index ${index.name} has a duplicate key`);
    seen.add(term);
  }
}

function stageSecondaryUniqueInsertChanges(
  transaction: DatabaseTransaction,
  table: TableRecord,
  input: ColumnarBatch,
  oldImages?: ReadonlyArray<Record<string, BatchValue> | undefined>,
): void {
  const rowCount = input.rowCount ?? Object.values(input.columns)[0]?.length ?? 0;
  for (const { indexId, index, columns } of readyUniqueSecondaryIndexes(table)) {
    const namespaceId = secondaryUniqueKeyNamespace(table.id, indexId);
    const removed = (oldImages ?? []).flatMap((old) => {
      if (old === undefined) return [];
      const term = secondaryUniqueTerm(
        index,
        columns,
        columns.map((column) => old[column.name] ?? null),
      );
      return term === undefined ? [] : [term];
    });
    if (removed.length > 0) {
      transaction.setUniqueKeyChanges({
        tableId: namespaceId,
        keyTokens: removed,
        requireAbsent: false,
        remove: true,
      });
    }
    const added: string[] = [];
    for (let row = 0; row < rowCount; row += 1) {
      const term = secondaryUniqueTerm(
        index,
        columns,
        columns.map((column) => input.columns[column.name]?.[row] ?? null),
      );
      if (term !== undefined) added.push(term);
    }
    assertNoDuplicateUniqueTerms(index, added);
    // The empty entry is deliberate coverage: a stale writer that never saw this enforced unique
    // index supplies no namespace entry, which the atomic store rejects instead of accepting an
    // unenforced commit.
    transaction.setUniqueKeyChanges({
      tableId: namespaceId,
      keyTokens: added,
      requireAbsent: true,
    });
  }
}

function stageSecondaryUniqueMutationChanges(
  transaction: DatabaseTransaction,
  table: TableRecord,
  input: UpdateBatchInput | undefined,
  oldImages: ReadonlyArray<Record<string, BatchValue> | undefined>,
): void {
  for (const { indexId, index, columns } of readyUniqueSecondaryIndexes(table)) {
    const namespaceId = secondaryUniqueKeyNamespace(table.id, indexId);
    const removed = oldImages.flatMap((old) => {
      if (old === undefined) return [];
      const term = secondaryUniqueTerm(
        index,
        columns,
        columns.map((column) => old[column.name] ?? null),
      );
      return term === undefined ? [] : [term];
    });
    transaction.setUniqueKeyChanges({
      tableId: namespaceId,
      keyTokens: removed,
      requireAbsent: false,
      remove: true,
    });
    if (input === undefined) continue;
    const added = oldImages.flatMap((old, row) => {
      if (old === undefined) return [];
      const term = secondaryUniqueTerm(
        index,
        columns,
        columns.map((column) => input.changes[column.name]?.[row] ?? old[column.name] ?? null),
      );
      return term === undefined ? [] : [term];
    });
    assertNoDuplicateUniqueTerms(index, added);
    transaction.setUniqueKeyChanges({
      tableId: namespaceId,
      keyTokens: added,
      requireAbsent: true,
    });
  }
}

/** One column's postings read: candidates plus the freshness/fold metadata callers gate on. */
type FtsCandidatesResult = Awaited<ReturnType<BlockStore["readFtsCandidates"]>>;

/** The columns a MATCH(*) document draws from: everything except booleans. */
function searchableFtsColumns(table: TableRecord | undefined): readonly string[] | undefined {
  if (table === undefined) return undefined;
  return visibleTableColumns(table)
    .filter((column) => column.type !== "boolean")
    .map((column) => column.name);
}

function getUniqueKeyColumn(table: TableRecord): TableColumnRecord | undefined {
  if (table.uniqueKeyColumnId === undefined) return undefined;
  return table.columns.find((column) => column.id === table.uniqueKeyColumnId);
}

function visibleTableColumns(table: TableRecord): TableColumnRecord[] {
  return table.columns.filter((column) => column.hidden !== true);
}

function publicKeyName(table: TableRecord, keyColumn: TableColumnRecord): string {
  if (!keyColumn.hidden) return keyColumn.name;
  const names = (table.primaryKeyColumnIds ?? []).map(
    (columnId) => table.columns.find((column) => column.id === columnId)?.name ?? columnId,
  );
  return `(${names.join(", ")})`;
}

function primaryKeyColumns(table: TableRecord): TableColumnRecord[] {
  const ids = table.primaryKeyColumnIds;
  if (ids !== undefined) {
    return ids.map((columnId) => {
      const column = table.columns.find((candidate) => candidate.id === columnId);
      if (column === undefined) throw new Error(`Primary key column is missing: ${table.name}`);
      return column;
    });
  }
  const scalar = getUniqueKeyColumn(table);
  return scalar === undefined || scalar.hidden ? [] : [scalar];
}

function foreignKeyColumns(
  key: NonNullable<TableRecord["foreignKeys"]>[number],
): readonly string[] {
  return key.columns;
}

function foreignKeyParentColumns(
  key: NonNullable<TableRecord["foreignKeys"]>[number],
): readonly string[] {
  return key.parentColumns;
}

function sqlTupleToken(values: readonly unknown[]): string {
  return JSON.stringify(values.map(encodeSqlEqualityValue));
}

function compositeKeyValue(
  columns: readonly TableColumnRecord[],
  values: readonly BatchValue[],
): string {
  if (columns.length !== values.length || values.some((value) => value === null)) {
    throw new TypeError("A composite key needs one non-null value per column");
  }
  return columns
    .map((column, index) => secondaryTupleComponent(column.type, values[index] ?? null))
    .join("");
}

/**
 * Folds a statement's column names the way PostgreSQL folds unquoted identifiers: a name with
 * no exact column keeps the unique case-insensitive match. Names with an exact column, and
 * names with no match at all, are returned as written for the caller's own error.
 */
function foldColumnName(table: TableRecord, name: string): string {
  const columns = visibleTableColumns(table);
  if (columns.some((column) => column.name === name)) return name;
  const lowered = name.toLowerCase();
  const matches = columns.filter((column) => column.name.toLowerCase() === lowered);
  return matches.length === 1 ? (matches[0]?.name ?? name) : name;
}

function foldInsertColumns<T extends { columns: readonly string[] }>(
  table: TableRecord,
  statement: T,
): T {
  const columns = statement.columns.map((name) => foldColumnName(table, name));
  return columns.some((name, index) => name !== statement.columns[index])
    ? { ...statement, columns }
    : statement;
}

function foldAssignmentColumns<T extends { column: string }>(
  table: TableRecord,
  assignments: readonly T[],
): readonly T[] {
  const folded = assignments.map((assignment) => {
    const column = foldColumnName(table, assignment.column);
    return column === assignment.column ? assignment : { ...assignment, column };
  });
  return folded.some((assignment, index) => assignment !== assignments[index])
    ? folded
    : assignments;
}

function quoteIdentifier(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/** Canonicalizes logical PostgreSQL domains before validation and primitive block encoding. */
function normalizeDomainBatch(table: TableRecord, input: ColumnarBatch): void {
  for (const column of table.columns) {
    const values = input.columns[column.name];
    if (values === undefined) continue;
    if (
      column.sqlDomain !== undefined ||
      column.type === "datetime" ||
      // A number column rewrites only when a tagged exact-NUMERIC constant actually reached it
      // (a SQL literal like 0.1/3 evaluated exactly), so plain bulk loads never copy here.
      (column.type === "number" &&
        values.some((value) => typeof value === "string" && isExactNumeric(value)))
    ) {
      (input.columns as Record<string, readonly BatchValue[]>)[column.name] = values.map((value) =>
        normalizeColumnLogicalValue(column, value),
      );
    }
  }
}

function normalizeColumnLogicalValue(column: TableColumnRecord, value: BatchValue): BatchValue {
  if (column.sqlDomain !== undefined) return normalizeSqlDomainValue(column.sqlDomain, value);
  if (column.type === "datetime" && isDateDomainValue(value)) {
    const external = externalSqlDomainValue(value);
    if (typeof external !== "string") throw new TypeError("Invalid DATE value");
    return new Date(`${external}T00:00:00.000Z`);
  }
  if (column.type === "number" && typeof value === "string" && isExactNumeric(value)) {
    // PostgreSQL's assignment cast: an exact-NUMERIC value reaching a float column rounds to
    // the nearest Float64. An integer column keeps its exactness guarantee instead — a value
    // Float64 cannot hold exactly is rejected rather than silently rounded.
    const exact = exactNumericAsNumber(value);
    if (exact !== undefined) return exact;
    if (column.integer === true) {
      throw new TypeError(`${column.name} must be a safe integer`);
    }
    return Number(externalSqlDomainValue(value));
  }
  return value;
}

/** Merges two ascending, disjoint row-index arrays into one ascending array, without a sort. */
function mergeAscendingIndexes(left: readonly number[], right: readonly number[]): number[] {
  const merged: number[] = [];
  let leftIndex = 0;
  let rightIndex = 0;
  while (leftIndex < left.length || rightIndex < right.length) {
    const a = left[leftIndex];
    const b = right[rightIndex];
    if (b === undefined || (a !== undefined && a <= b)) {
      if (a !== undefined) merged.push(a);
      leftIndex += 1;
    } else {
      merged.push(b);
      rightIndex += 1;
    }
  }
  return merged;
}

interface UpsertFirings {
  inserts: number[];
  updates: number[];
  skipped: number[];
  oldImages: Array<Record<string, BatchValue> | undefined>;
}

/**
 * Filters a `conflictWhere`-classified upsert batch down to its accepted rows (inserts + updates,
 * dropping skips) and remaps the firing indexes to match — shared by the autocommit and
 * write-scope upsert paths so a fix to this logic cannot silently miss one of them. Returns the
 * input batch and firings unchanged (no copy) when nothing was skipped.
 */
function applyUpsertConflictFilter(
  batch: ColumnarBatch,
  rowCount: number,
  classified: UpsertFirings,
): {
  batch: ColumnarBatch;
  rowCount: number;
  skippedRowCount: number;
  acceptedRowIndexes: number[];
  firings: UpsertFirings;
} {
  const acceptedRowIndexes = mergeAscendingIndexes(classified.inserts, classified.updates);
  const skippedRowCount = classified.skipped.length;
  if (acceptedRowIndexes.length === rowCount) {
    return { batch, rowCount, skippedRowCount, acceptedRowIndexes, firings: classified };
  }
  const acceptedPosition = new Map(
    acceptedRowIndexes.map((original, position) => [original, position] as const),
  );
  return {
    batch: selectBatchRows(batch, acceptedRowIndexes),
    rowCount: acceptedRowIndexes.length,
    skippedRowCount,
    acceptedRowIndexes,
    firings: {
      inserts: classified.inserts.map((index) => acceptedPosition.get(index) ?? -1),
      updates: classified.updates.map((index) => acceptedPosition.get(index) ?? -1),
      skipped: [],
      oldImages: acceptedRowIndexes.map((index) => classified.oldImages[index]),
    },
  };
}

/** Reindexes generated-column values onto an accepted row subset; callers skip it when every row was accepted. */
function remapGeneratedColumns(
  generated: Map<string, BatchValue[]>,
  acceptedRowIndexes: readonly number[],
): void {
  for (const [name, values] of generated) {
    generated.set(
      name,
      acceptedRowIndexes.map((index) => values[index] ?? null),
    );
  }
}

function selectBatchRows(input: ColumnarBatch, indexes: readonly number[]): ColumnarBatch {
  return {
    columns: Object.fromEntries(
      Object.entries(input.columns).map(([name, values]) => [
        name,
        indexes.map((index) => values[index] ?? null),
      ]),
    ),
    ...(input.omitted === undefined
      ? {}
      : {
          omitted: Object.fromEntries(
            Object.entries(input.omitted).map(([name, values]) => [
              name,
              indexes.map((index) => values[index] ?? false),
            ]),
          ),
        }),
    rowCount: indexes.length,
  };
}

function normalizeUpsertConflictWhere(
  table: TableRecord,
  predicate: UpsertConflictWhere,
): { column: TableColumnRecord; operator: ComparisonOperator; value: BatchValue } {
  const operators: readonly ComparisonOperator[] = ["=", "!=", "<>", ">", ">=", "<", "<="];
  if (!operators.includes(predicate.operator)) {
    throw new TypeError(`Unsupported upsert conflict operator: ${predicate.operator}`);
  }
  const column = visibleTableColumns(table).find(({ name }) => name === predicate.column);
  if (column === undefined) {
    throw new TypeError(`Unknown upsert conflict column: ${table.name}.${predicate.column}`);
  }
  const value = normalizeColumnLogicalValue(column, predicate.value);
  if (value !== null) validateValue({ ...column, nullable: true }, value, 0);
  return { column, operator: predicate.operator, value };
}

function normalizeDomainUpdate(table: TableRecord, input: UpdateBatchInput): UpdateBatchInput {
  const numberColumnNeedsCast = (column: TableColumnRecord, values: readonly BatchValue[]) =>
    column.type === "number" &&
    values.some((value) => typeof value === "string" && isExactNumeric(value));
  if (
    !table.columns.some((column) => column.sqlDomain !== undefined || column.type === "datetime") &&
    !Object.entries(input.changes).some(([name, values]) => {
      const column = table.columns.find((candidate) => candidate.name === name);
      return column !== undefined && numberColumnNeedsCast(column, values);
    })
  ) {
    return input;
  }
  let changed = false;
  const changes: Record<string, readonly BatchValue[]> = { ...input.changes };
  for (const [name, values] of Object.entries(input.changes)) {
    const column = table.columns.find((candidate) => candidate.name === name);
    if (
      column === undefined ||
      (column.sqlDomain === undefined &&
        column.type !== "datetime" &&
        !numberColumnNeedsCast(column, values))
    ) {
      continue;
    }
    changed = true;
    changes[name] = values.map((value) => normalizeColumnLogicalValue(column, value));
  }
  const key = getUniqueKeyColumn(table);
  const keys =
    key === undefined || (key.sqlDomain === undefined && key.type !== "datetime")
      ? input.keys
      : input.keys.map((value) => normalizeColumnLogicalValue(key, value));
  return changed || keys !== input.keys ? { keys, changes } : input;
}

/**
 * Coerces literals and bound parameters opposite a domain column before planning/index probes,
 * and reads an untyped string constant beside a datetime, number, or boolean column in that
 * column's type — `joined >= '2026-01-01'`, `id = '5'`, `active = 't'` — the way PostgreSQL
 * types an unknown-typed literal by its context. Text that does not parse is left alone and
 * fails at comparison time as a type mismatch. Coercing here, rather than only at comparison,
 * keeps the typed kernels, zone-map pruning, and the keyed point read on the fast paths.
 */
function normalizePlanDomainLiterals(
  input: CompiledQuery,
  domains: ReadonlyMap<string, ReadonlyMap<string, SqlDomain>>,
  types: ReadonlyMap<string, ReadonlyMap<string, SimpleDataType>> = new Map(),
): CompiledQuery {
  // Most plans have nothing to coerce. A probing pass over the shared (cached) plan finds out
  // without touching it; only a plan that needs a rewrite is cloned and rewritten, so the
  // per-query cost of a plan that compares typed columns to typed literals is one walk, not a
  // structured clone.
  const pass = { probing: true, needed: false };
  const coerceText = (type: SimpleDataType, text: string): QueryValue | undefined => {
    const read = readUntypedText(type, text);
    return read === text ? undefined : (read as QueryValue);
  };
  const rewriteBlock = (block: CompiledQuery): void => {
    if (pass.probing && pass.needed) return;
    for (const source of [block.base, ...block.joins]) {
      if (source.derived !== undefined) rewriteBlock(source.derived);
      source.union?.blocks.forEach(rewriteBlock);
      if (source.windowed !== undefined) rewriteBlock(source.windowed.block);
      if (source.recursive !== undefined) {
        rewriteBlock(source.recursive.base);
        rewriteBlock(source.recursive.step);
      }
    }
    const sources = [block.base, ...block.joins];
    const lookup = <T>(
      reference: string,
      catalog: ReadonlyMap<string, ReadonlyMap<string, T>>,
    ): T | undefined => {
      const separator = reference.indexOf(".");
      if (separator !== -1) {
        const alias = reference.slice(0, separator);
        const name = reference.slice(separator + 1);
        const source = sources.find((candidate) => candidate.alias === alias);
        return source === undefined ? undefined : catalog.get(source.table)?.get(name);
      }
      const matches = sources.flatMap((source) => {
        const found = catalog.get(source.table)?.get(reference);
        return found === undefined ? [] : [found];
      });
      return matches.length === 1 ? matches[0] : undefined;
    };
    const domainFor = (reference: string): SqlDomain | undefined => lookup(reference, domains);
    const coerceTyped = (column: Expression, value: Expression): void => {
      if (column.kind !== "column") return;
      const type = lookup(column.reference, types);
      if (type === undefined || type === "string") return;
      const literals =
        value.kind === "literal" ? [value] : value.kind === "list" ? value.items : [];
      for (const literal of literals) {
        if (literal.kind !== "literal" || typeof literal.value !== "string") continue;
        if (literal.internalSqlValue === true) continue;
        const coerced = coerceText(type, literal.value);
        if (coerced === undefined) continue;
        if (pass.probing) pass.needed = true;
        else literal.value = coerced;
      }
    };
    const coercePair = (column: Expression, value: Expression): void => {
      if (column.kind !== "column") return;
      const domain = domainFor(column.reference);
      if (domain === undefined) {
        coerceTyped(column, value);
        return;
      }
      if (value.kind === "literal") {
        if (pass.probing) {
          pass.needed = true;
          return;
        }
        value.value = normalizeSqlDomainValue(domain, value.value);
        value.internalSqlValue = true;
        value.sqlDomain = domain;
      } else if (value.kind === "list") {
        for (const item of value.items) {
          if (item.kind === "literal") {
            if (pass.probing) {
              pass.needed = true;
              return;
            }
            item.value = normalizeSqlDomainValue(domain, item.value);
            item.internalSqlValue = true;
            item.sqlDomain = domain;
          }
        }
      }
    };
    const rewrite = (expression: Expression): Expression => {
      if (expression.kind === "binary") {
        expression.left = rewrite(expression.left);
        expression.right = rewrite(expression.right);
      } else if (expression.kind === "call") {
        expression.arguments = expression.arguments.map(rewrite);
      } else if (expression.kind === "list") {
        expression.items = expression.items.map(rewrite);
      } else if (expression.kind === "condition") {
        expression.left = rewrite(expression.left);
        expression.right = rewrite(expression.right);
        coercePair(expression.left, expression.right);
        coercePair(expression.right, expression.left);
      } else if (expression.kind === "logical") {
        expression.left = rewrite(expression.left);
        expression.right = rewrite(expression.right);
      } else if (expression.kind === "not") {
        expression.operand = rewrite(expression.operand);
      } else if (expression.kind === "case") {
        for (const branch of expression.branches) {
          branch.when = rewrite(branch.when);
          branch.then = rewrite(branch.then);
        }
        if (expression.otherwise !== undefined)
          expression.otherwise = rewrite(expression.otherwise);
      } else if (expression.kind === "window") {
        expression.partitionBy = expression.partitionBy.map(rewrite);
        for (const order of expression.orderBy) order.expression = rewrite(order.expression);
        if (expression.argument !== undefined) expression.argument = rewrite(expression.argument);
      } else if (expression.kind === "subquery") {
        rewriteBlock(expression.block);
      } else if (expression.kind === "exists") {
        rewriteBlock(expression.block);
      } else if (expression.kind === "fts" && expression.columns !== "*") {
        expression.columns = expression.columns.map(rewrite);
      }
      return expression;
    };
    for (const item of block.select) item.expression = rewrite(item.expression);
    for (const join of block.joins) {
      join.left = rewrite(join.left);
      join.right = rewrite(join.right);
      if (join.on !== undefined) join.on = rewrite(join.on);
    }
    for (const predicate of [...block.predicates, ...block.having]) {
      predicate.left = rewrite(predicate.left);
      predicate.right = rewrite(predicate.right);
      coercePair(predicate.left, predicate.right);
      coercePair(predicate.right, predicate.left);
    }
    block.groupBy = block.groupBy.map(rewrite);
    for (const order of block.orderBy) order.expression = rewrite(order.expression);
  };
  rewriteBlock(input);
  if (!pass.needed) return input;
  pass.probing = false;
  const plan = structuredClone(input);
  rewriteBlock(plan);
  return plan;
}

/** Materializes a composite PRIMARY KEY's hidden scalar locator without touching public values. */
function fillCompositePrimaryKey(table: TableRecord, input: ColumnarBatch, rowCount: number): void {
  const ids = table.primaryKeyColumnIds;
  if (ids === undefined || ids.length < 2) return;
  const keyColumn = getUniqueKeyColumn(table);
  if (keyColumn?.hidden !== true)
    throw new Error(`Composite key locator is missing: ${table.name}`);
  const columns = ids.map((columnId) => {
    const column = table.columns.find(
      (candidate) => candidate.id === columnId && !candidate.hidden,
    );
    if (column === undefined) throw new Error(`Composite key column is missing: ${table.name}`);
    return column;
  });
  const keys: string[] = [];
  for (let row = 0; row < rowCount; row += 1) {
    const values = columns.map((column) => input.columns[column.name]?.[row] ?? null);
    const nullAt = values.findIndex((value) => value === null);
    if (nullAt !== -1) {
      throw new TypeError(
        `PRIMARY KEY ${columns[nullAt]?.name ?? ""}[${String(row)}] cannot be null`,
      );
    }
    keys.push(compositeKeyValue(columns, values));
  }
  (input.columns as Record<string, readonly BatchValue[]>)[keyColumn.name] = keys;
}

function batchKeys(
  table: TableRecord,
  input: ColumnarBatch,
): Map<string, Exclude<BatchValue, null>> | undefined {
  const keyColumn = getUniqueKeyColumn(table);
  if (keyColumn === undefined) return undefined;
  const keys = new Map<string, Exclude<BatchValue, null>>();
  for (const value of input.columns[keyColumn.name] ?? []) {
    if (value === null) throw new TypeError(`Unique key cannot be null: ${keyColumn.name}`);
    const token = keyToken(keyColumn.type, value);
    if (keys.has(token)) {
      throw new UniqueConstraintError(table.name, publicKeyName(table, keyColumn), value);
    }
    keys.set(token, value);
  }
  return keys;
}

/**
 * Whether a column block's logical payload is under `limit` bytes: strings by length (two
 * bytes a code unit, stopping as soon as the limit is reached), everything else eight bytes a
 * value. An estimate, for the write path's codec choice — not an encoded size.
 */
function columnInputBytesBelow(input: ColumnInput, limit: number): boolean {
  if (input.type !== "string") return input.values.length * 8 < limit;
  let bytes = 0;
  for (const value of input.values) {
    bytes += 8 + (value === null ? 0 : value.length * 2);
    if (bytes >= limit) return false;
  }
  return true;
}

/** `keyToken` for values that may not encode: undefined instead of a thrown encoding error. */
function tryKeyToken(type: SimpleDataType, value: BatchValue): string | undefined {
  try {
    return keyToken(type, value);
  } catch {
    return undefined;
  }
}

/**
 * Whether a table's visible history warrants a background fold: enough level-zero segments to
 * fragment a scan, or enough deltas to cost one. Partitions compaction itself published
 * (level one and above) are the folded state, not fragmentation, and do not count — a large
 * keyed table is many partitions by design.
 */
function autoCompactionHint(
  version: number | null,
  segments: readonly SegmentRecord[],
): AutoCompactionHint {
  let levelZero = 0;
  let deltas = 0;
  for (const segment of segments) {
    if (segment.level === 0) levelZero += 1;
    const kind = segment.kind;
    if (kind !== "insert" && kind !== "base") deltas += 1;
  }
  return {
    version,
    visible: segments.length,
    levelZero,
    deltas,
  };
}

function countLevelZeroSegments(segments: readonly SegmentRecord[]): number {
  let levelZero = 0;
  for (const segment of segments) {
    if (segment.level === 0) levelZero += 1;
  }
  return levelZero;
}

function autoCompactionDueHint(hint: AutoCompactionHint): boolean {
  return hint.levelZero >= AUTO_COMPACT_SCAN_SEGMENTS || hint.deltas >= AUTO_COMPACT_DELTA_SEGMENTS;
}

function autoCompactionDue(segments: readonly SegmentRecord[]): boolean {
  return autoCompactionDueHint(autoCompactionHint(null, segments));
}

/** A macrotask boundary, so background work lets queued queries and writes run between steps. */
function yieldToEventLoop(): Promise<void> {
  // A timer is clamped to roughly 1–4 ms in the runtimes Minnow targets. Maintenance can yield
  // once per bounded page, so using timers turns a healthy thousand-page cleanup into seconds of
  // artificial latency. MessageChannel is still a genuine task boundary (rendering, timers, and
  // other clients can run) without the timer clamp.
  // Vitest/Sinon fake timers expose a `clock` marker and intentionally expect cooperative work
  // to remain timer-driven. Production timers have no such property.
  if (typeof MessageChannel !== "undefined" && !Reflect.has(setTimeout, "clock")) {
    return new Promise((resolve) => {
      const channel = new MessageChannel();
      channel.port1.onmessage = () => {
        channel.port1.close();
        channel.port2.close();
        resolve();
      };
      channel.port2.postMessage(undefined);
    });
  }
  return new Promise((resolve) => setTimeout(resolve, 0));
}

function boundedExpiryMilliseconds(nowMs: number, ttlMs: number): number {
  const expiresAt = nowMs + ttlMs;
  if (
    !Number.isSafeInteger(nowMs) ||
    !Number.isSafeInteger(ttlMs) ||
    !Number.isSafeInteger(expiresAt) ||
    expiresAt > 8_640_000_000_000_000
  ) {
    throw new RangeError("Lease expiry is outside the supported Date range");
  }
  return expiresAt;
}

function keyToken(type: SimpleDataType, value: BatchValue): string {
  if (value === null) throw new TypeError("Unique key cannot be null");
  switch (type) {
    case "boolean":
      if (typeof value !== "boolean") throw new TypeError("Invalid boolean unique key");
      return value ? "boolean:true" : "boolean:false";
    case "number":
      if (typeof value !== "number" || !Number.isFinite(value)) {
        throw new TypeError("Invalid number unique key");
      }
      return `number:${String(value)}`;
    case "string":
      if (typeof value !== "string") throw new TypeError("Invalid string unique key");
      assertIndexedStringLength(value);
      return `string:${value}`;
    case "datetime":
      if (!(value instanceof Date) || !Number.isFinite(dateMilliseconds(value))) {
        throw new TypeError("Invalid datetime unique key");
      }
      return `datetime:${String(dateMilliseconds(value))}`;
  }
}

function assertIndexedStringLength(value: string): void {
  if (value.length > MAX_INDEXED_STRING_CHARACTERS) {
    throw new RangeError(
      `Indexed strings cannot exceed ${String(MAX_INDEXED_STRING_CHARACTERS)} characters`,
    );
  }
}

function formatValue(value: Exclude<BatchValue, null>): string {
  return value instanceof Date ? dateIsoString(value) : String(value);
}

function nonNegativeWholeNumber(value: number, name: string): number {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative whole number`);
  }
  return value;
}

function boundedRetainedVersions(value: number): number {
  const retained = nonNegativeWholeNumber(value, "Garbage collection retained versions");
  if (retained > MAX_GARBAGE_COLLECTION_RETAIN_RECENT_VERSIONS) {
    throw new RangeError(
      `Garbage collection retained versions cannot exceed ${String(MAX_GARBAGE_COLLECTION_RETAIN_RECENT_VERSIONS)}`,
    );
  }
  return retained;
}

function positiveWholeNumber(value: number, name: string): number {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive whole number`);
  }
  return value;
}

function positiveFiniteNumber(value: number, name: string): number {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive finite number`);
  }
  return value;
}

const INITIAL_DICTIONARY_CAPACITY = 8;
const INITIAL_DICTIONARY_ARENA_BYTES = 256;
/** Physical dictionaries known to contain at least one value in the private domain namespace. */
const sqlDomainDictionaries = new WeakSet<readonly string[]>();

/**
 * Interns decoded strings by their raw UTF-8 bytes. The columns that grouping and filtering
 * target repeat the same byte ranges across millions of rows, so probing an owned byte arena
 * holds `TextDecoder` calls to one per distinct value rather than one per row. Entries live in
 * flat typed arrays so a high-cardinality column pays no per-value object overhead.
 */
class StringDictionaryBuilder {
  readonly dictionary: string[] = [];
  #buckets = filledInt32Array(INITIAL_DICTIONARY_CAPACITY);
  #next = filledInt32Array(INITIAL_DICTIONARY_CAPACITY);
  #hashes = new Uint32Array(INITIAL_DICTIONARY_CAPACITY);
  #offsets = new Uint32Array(INITIAL_DICTIONARY_CAPACITY);
  #lengths = new Uint32Array(INITIAL_DICTIONARY_CAPACITY);
  #arena = new Uint8Array(INITIAL_DICTIONARY_ARENA_BYTES);
  #arenaLength = 0;
  #hasSqlDomainValue = false;

  /** UTF-8 bytes held by the distinct values, tracked so callers skip a re-encoding pass. */
  get byteLength(): number {
    return this.#arenaLength;
  }

  get hasSqlDomainValue(): boolean {
    return this.#hasSqlDomainValue;
  }

  codeForBytes(content: Uint8Array, start: number, end: number): number {
    const length = end - start;
    const hash = hashByteRange(content, start, end);
    let index = this.#buckets[hash & (this.#buckets.length - 1)] ?? -1;
    while (index >= 0) {
      if (
        this.#hashes[index] === hash &&
        this.#lengths[index] === length &&
        equalByteRange(this.#arena, this.#offsets[index] ?? 0, content, start, length)
      ) {
        return index;
      }
      index = this.#next[index] ?? -1;
    }
    return this.#insert(content, start, end, hash);
  }

  #insert(content: Uint8Array, start: number, end: number, hash: number): number {
    const code = this.dictionary.length;
    const length = end - start;
    this.#growEntries(code + 1);
    this.#growArena(this.#arenaLength + length);
    this.#arena.set(content.subarray(start, end), this.#arenaLength);
    this.#hashes[code] = hash;
    this.#offsets[code] = this.#arenaLength;
    this.#lengths[code] = length;
    this.#arenaLength += length;
    const bucket = hash & (this.#buckets.length - 1);
    this.#next[code] = this.#buckets[bucket] ?? -1;
    this.#buckets[bucket] = code;
    const decoded = vectorTextDecoder.decode(content.subarray(start, end));
    this.dictionary.push(decoded);
    // Check raw bytes before asking the decoded string about its prefix. Ordinary data almost
    // never starts with NUL, so high-cardinality TEXT avoids one startsWith call per distinct
    // value while the rare private-namespace collision is still detected exactly.
    if (
      !this.#hasSqlDomainValue &&
      length >= SQL_DOMAIN_PREFIX_BYTES.length &&
      content[start] === 0 &&
      equalByteRange(SQL_DOMAIN_PREFIX_BYTES, 0, content, start, SQL_DOMAIN_PREFIX_BYTES.length)
    ) {
      this.#hasSqlDomainValue = true;
      sqlDomainDictionaries.add(this.dictionary);
    }
    return code;
  }

  #growEntries(required: number): void {
    if (required <= this.#hashes.length) return;
    let capacity = this.#hashes.length;
    while (capacity < required)
      capacity = safeWholeNumberProduct(capacity, 2, "String dictionary entries");
    const hashes = new Uint32Array(capacity);
    const offsets = new Uint32Array(capacity);
    const lengths = new Uint32Array(capacity);
    hashes.set(this.#hashes);
    offsets.set(this.#offsets);
    lengths.set(this.#lengths);
    this.#hashes = hashes;
    this.#offsets = offsets;
    this.#lengths = lengths;
    // Buckets track entry capacity, so chains stay short as the distinct-value count grows.
    this.#buckets = filledInt32Array(capacity);
    this.#next = filledInt32Array(capacity);
    for (let code = 0; code < this.dictionary.length; code += 1) {
      const bucket = (this.#hashes[code] ?? 0) & (capacity - 1);
      this.#next[code] = this.#buckets[bucket] ?? -1;
      this.#buckets[bucket] = code;
    }
  }

  #growArena(required: number): void {
    if (required <= this.#arena.byteLength) return;
    let capacity = this.#arena.byteLength;
    while (capacity < required)
      capacity = safeWholeNumberProduct(capacity, 2, "String dictionary arena");
    const arena = new Uint8Array(capacity);
    arena.set(this.#arena.subarray(0, this.#arenaLength));
    this.#arena = arena;
  }
}

function filledInt32Array(length: number): Int32Array {
  const array = new Int32Array(length);
  array.fill(-1);
  return array;
}

function hashByteRange(bytes: Uint8Array, start: number, end: number): number {
  let hash = 0x811c9dc5;
  for (let index = start; index < end; index += 1) {
    hash = Math.imul(hash ^ (bytes[index] ?? 0), 0x01000193) >>> 0;
  }
  return hash;
}

function equalByteRange(
  arena: Uint8Array,
  arenaOffset: number,
  content: Uint8Array,
  contentStart: number,
  length: number,
): boolean {
  for (let index = 0; index < length; index += 1) {
    if (arena[arenaOffset + index] !== content[contentStart + index]) return false;
  }
  return true;
}

/** Reusable copy arena that realigns misaligned float64 payloads for one bulk typed copy. */
let alignmentScratch = new ArrayBuffer(0);

function appendPhysicalColumnToVector(
  column: ValidatedPhysicalColumn,
  outputRowStart: number,
  outputValidity: Uint8Array,
  outputValues: Uint8Array | Float64Array | undefined,
  outputStringCodes: Uint32Array | undefined,
  stringDictionary: StringDictionaryBuilder,
): void {
  const sourceValidityLength = Math.ceil(column.rowCount / 8);
  const sourceValidity = column.bytes.subarray(0, sourceValidityLength);
  if (outputRowStart % 8 === 0) {
    // Byte-aligned append: the physical format zeroes every padding bit past rowCount (enforced
    // by validatePhysicalColumn), so copying whole bytes cannot leak stray validity into rows a
    // later block will own.
    outputValidity.set(sourceValidity, outputRowStart / 8);
  } else {
    for (let row = 0; row < column.rowCount; row += 1) {
      if (bitmapHasValue(sourceValidity, row)) {
        setBitmapValue(outputValidity, outputRowStart + row);
      }
    }
  }

  if (column.type === "boolean") {
    if (!(outputValues instanceof Uint8Array)) throw new Error("Boolean vector is missing");
    const sourceValues = column.bytes.subarray(sourceValidityLength);
    for (let row = 0; row < column.rowCount; row += 1) {
      if (bitmapHasValue(sourceValues, row)) outputValues[outputRowStart + row] = 1;
    }
    return;
  }
  if (column.type === "number" || column.type === "datetime") {
    if (!(outputValues instanceof Float64Array))
      throw new Error(`${column.type} vector is missing`);
    const valueOffset = column.bytes.byteOffset + sourceValidityLength;
    if (PLATFORM_LITTLE_ENDIAN) {
      // Values at invalid slots are never read (every consumer checks the validity bitmap
      // first), so bulk-copying them is safe. A misaligned payload — the common case, since the
      // validity prefix rarely ends on an 8-byte boundary — realigns through a reusable scratch
      // buffer: two memcpys still beat a per-row DataView loop by a wide margin.
      if (valueOffset % Float64Array.BYTES_PER_ELEMENT === 0) {
        outputValues.set(
          new Float64Array(column.bytes.buffer, valueOffset, column.rowCount),
          outputRowStart,
        );
        return;
      }
      const byteLength = column.rowCount * Float64Array.BYTES_PER_ELEMENT;
      if (alignmentScratch.byteLength < byteLength) {
        alignmentScratch = new ArrayBuffer(byteLength);
      }
      const scratchBytes = new Uint8Array(alignmentScratch, 0, byteLength);
      scratchBytes.set(new Uint8Array(column.bytes.buffer, valueOffset, byteLength));
      outputValues.set(new Float64Array(alignmentScratch, 0, column.rowCount), outputRowStart);
      return;
    }
    const sourceValues = new DataView(column.bytes.buffer, valueOffset, column.rowCount * 8);
    for (let row = 0; row < column.rowCount; row += 1) {
      if (bitmapHasValue(sourceValidity, row)) {
        outputValues[outputRowStart + row] = sourceValues.getFloat64(row * 8, true);
      }
    }
    return;
  }
  if (outputStringCodes === undefined) throw new Error("String vector is missing");
  const offsetsLength = (column.rowCount + 1) * 4;
  const offsets = new DataView(
    column.bytes.buffer,
    column.bytes.byteOffset + sourceValidityLength,
    offsetsLength,
  );
  const content = column.bytes.subarray(sourceValidityLength + offsetsLength);
  for (let row = 0; row < column.rowCount; row += 1) {
    if (!bitmapHasValue(sourceValidity, row)) continue;
    const start = offsets.getUint32(row * 4, true);
    const end = offsets.getUint32((row + 1) * 4, true);
    outputStringCodes[outputRowStart + row] = stringDictionary.codeForBytes(content, start, end);
  }
}

/**
 * A streamed vector starts with an empty resident window; its logical length is the full table so
 * bound plans see the true scan cardinality before the first load.
 */
function createStreamedColumnVector(type: SimpleDataType, length: number): ColumnVector {
  const window: VectorWindow = { start: 0, length: 0 };
  const validity = new Uint8Array(0);
  if (type === "boolean") {
    return { kind: type, length, validity, values: new Uint8Array(0), window };
  }
  if (type === "number" || type === "datetime") {
    return { kind: type, length, validity, values: new Float64Array(0), window };
  }
  return { kind: type, length, validity, codes: new Uint32Array(0), dictionary: [], window };
}

/**
 * Gives a physical plain-TEXT vector its unambiguous execution representation. Domain columns
 * deliberately keep their tags; ordinary TEXT only copies the rare dictionary that collides
 * with that namespace, preserving the cached zero-copy vector for every normal dictionary.
 */
/** Bytes a materialized vector retains, for the buffer pool's accounting. */
function columnVectorPayloadBytes(vector: ColumnVector): number {
  let total = vector.validity.byteLength;
  if (vector.kind === "string") {
    total += vector.codes.byteLength;
    for (const value of vector.dictionary) total += 16 + value.length * 2;
  } else {
    total += vector.values.byteLength;
  }
  return total;
}

function plainTextExecutionVector(column: TableColumnRecord, vector: ColumnVector): ColumnVector {
  if (
    column.type !== "string" ||
    column.sqlDomain !== undefined ||
    vector.kind !== "string" ||
    !sqlDomainDictionaries.has(vector.dictionary)
  ) {
    return vector;
  }
  return { ...vector, dictionary: vector.dictionary.map(protectedSqlTextValue) };
}

interface MutableStreamedVectorFields {
  validity: Uint8Array;
  window: VectorWindow;
  values?: Uint8Array | Float64Array;
  codes?: Uint32Array;
  dictionary?: string[];
}

/** One decoded block resident in a streamed scan, in its vectorized (buffer pool) form. */
interface ResidentStreamBlock {
  vector: ColumnVector;
  startRow: number;
}

/**
 * Replaces a streamed vector's resident window. The common case — a batch-aligned window
 * covering exactly one block — installs the buffer pool's block vector by reference: no
 * copies, no re-decoding, and a dictionary object that stays identical across queries so
 * per-dictionary expression caches survive. A window straddling blocks (only where block
 * row counts are not batch-aligned) stitches the block vectors into one copied window.
 * Modeled bytes are reserved either way; the caller releases the superseded reservations.
 */
function installStreamedWindow(
  vector: ColumnVector,
  resident: readonly ResidentStreamBlock[],
  windowStart: number,
  windowRows: number,
  memory: QueryMemoryContext,
  label: string,
  reservations: QueryMemoryReservation[],
): void {
  const single = resident.length === 1 ? resident[0] : undefined;
  const mutable = vector as unknown as MutableStreamedVectorFields;
  if (single !== undefined) {
    const block = single.vector;
    if (single.startRow === windowStart && block.length === windowRows) {
      reservations.push(memory.reserve(blockVectorRetainedBytes(block), label));
      mutable.validity = block.validity;
      if (block.kind === "string") {
        mutable.codes = block.codes;
        mutable.dictionary = block.dictionary as string[];
      } else {
        mutable.values = block.values;
      }
      mutable.window = { start: windowStart, length: windowRows };
      return;
    }
  }
  const validityBytes = Math.ceil(windowRows / 8);
  const typedBytes =
    validityBytes +
    (vector.kind === "boolean"
      ? windowRows
      : vector.kind === "string"
        ? windowRows * Uint32Array.BYTES_PER_ELEMENT
        : windowRows * Float64Array.BYTES_PER_ELEMENT);
  reservations.push(memory.reserve(typedBytes, label));
  const validity = new Uint8Array(validityBytes);
  const values =
    vector.kind === "boolean"
      ? new Uint8Array(windowRows)
      : vector.kind === "number" || vector.kind === "datetime"
        ? new Float64Array(windowRows)
        : undefined;
  const codes = vector.kind === "string" ? new Uint32Array(windowRows) : undefined;
  codes?.fill(NULL_STRING_VECTOR_CODE);
  const dictionary: string[] = [];
  const dictionaryIndex = new Map<string, number>();
  let dictionaryBytes = 0;
  for (const block of resident) {
    const offset = block.startRow - windowStart;
    const blockVector = block.vector;
    for (let row = 0; row < blockVector.length; row += 1) {
      if (bitmapHasValue(blockVector.validity, row)) setBitmapValue(validity, offset + row);
    }
    if (blockVector.kind === "string") {
      if (codes === undefined) throw new Error("String vector is missing");
      // Remap block codes through the merged window dictionary; the remap array makes the
      // per-row cost one lookup regardless of dictionary size.
      const remap = new Int32Array(blockVector.dictionary.length).fill(-1);
      for (let row = 0; row < blockVector.length; row += 1) {
        const code = blockVector.codes[row] ?? NULL_STRING_VECTOR_CODE;
        if (code === NULL_STRING_VECTOR_CODE) continue;
        let mapped = remap[code] ?? -1;
        if (mapped < 0) {
          const value = blockVector.dictionary[code] ?? "";
          let existing = dictionaryIndex.get(value);
          if (existing === undefined) {
            existing = dictionary.length;
            dictionary.push(value);
            dictionaryIndex.set(value, existing);
            dictionaryBytes += value.length;
          }
          remap[code] = existing;
          mapped = existing;
        }
        codes[offset + row] = mapped;
      }
    } else if (values !== undefined) {
      values.set(blockVector.values, offset);
    }
  }
  if (dictionary.length > 0) reservations.push(memory.reserve(dictionaryBytes, label));
  mutable.validity = validity;
  if (values !== undefined) mutable.values = values;
  if (codes !== undefined) {
    mutable.codes = codes;
    mutable.dictionary = dictionary;
  }
  mutable.window = { start: windowStart, length: windowRows };
}

/** Converts an executed derived-block result into a typed columnar input table. */
function derivedColumnarTable(
  name: string,
  result: QueryResult,
  schema: readonly SqlColumnSchema[],
): ColumnarTable {
  const columns = new Map(
    schema.map(({ name: columnName, type, sqlDomain }) => [
      columnName,
      {
        type,
        values:
          sqlDomain?.kind === "numeric"
            ? // COALESCE(amount, 0) or a CASE branch can hand an exact NUMERIC column a plain
              // number; PostgreSQL casts it to the column's type, and the string vector
              // needs the tagged form.
              result.rows.map((row) => {
                const value = row[columnName] ?? null;
                return typeof value === "number" ? exactNumericValue(value) : value;
              })
            : result.rows.map((row) => row[columnName] ?? null),
      },
    ]),
  );
  return createColumnarTable(name, columns);
}

/**
 * Writes a column's backfill across a run of slots, for rows whose segment predates the column.
 * Doing it here rather than at write time is what keeps adding a column metadata-only: the stored
 * segments never change, and compaction folds the value in the next time it rewrites them.
 */
function fillColumnVectorRange(
  vector: ColumnVector,
  start: number,
  count: number,
  value: boolean | number | string | Date,
): void {
  for (let offset = 0; offset < count; offset += 1) {
    setBitmapValue(vector.validity, start + offset);
  }
  if (vector.kind === "boolean") {
    vector.values.fill(value === true ? 1 : 0, start, start + count);
    return;
  }
  if (vector.kind === "number" || vector.kind === "datetime") {
    vector.values.fill(
      value instanceof Date ? dateMilliseconds(value) : Number(value),
      start,
      start + count,
    );
    return;
  }
  const text = String(value);
  const dictionary = vector.dictionary as string[];
  let code = dictionary.indexOf(text);
  if (code === -1) code = dictionary.push(text) - 1;
  vector.codes.fill(code, start, start + count);
}

/** Interns one string in a builder-backed dictionary, for the append path's own arrays. */
function dictionaryCodeForText(builder: StringDictionaryBuilder, text: string): number {
  const bytes = new TextEncoder().encode(text);
  return builder.codeForBytes(bytes, 0, bytes.length);
}

function createEmptyColumnVector(type: SimpleDataType, length: number): ColumnVector {
  const validity = new Uint8Array(Math.ceil(length / 8));
  if (type === "boolean") {
    return { kind: type, length, validity, values: new Uint8Array(length) };
  }
  if (type === "number" || type === "datetime") {
    return { kind: type, length, validity, values: new Float64Array(length) };
  }
  const codes = new Uint32Array(length);
  codes.fill(NULL_STRING_VECTOR_CODE);
  return { kind: type, length, validity, codes, dictionary: [] };
}

function requiredColumnVector(
  vectors: ReadonlyMap<string, ColumnVector>,
  column: TableColumnRecord,
  segment?: SegmentRecord,
): ColumnVector {
  const vector = vectors.get(column.id);
  if (vector === undefined) {
    throw new Error(
      segment === undefined
        ? `Projected column is missing: ${column.name}`
        : `Visible column is missing: ${segment.id}.${column.name}`,
    );
  }
  return vector;
}

function copyColumnVectorValue(
  source: ColumnVector,
  sourceRow: number,
  target: ColumnVector,
  targetRow: number,
  targetDictionaryIndex?: Map<string, number>,
): void {
  if (source.kind !== target.kind) throw new Error("Column vector type mismatch");
  if (!bitmapHasValue(source.validity, sourceRow)) {
    clearBitmapValue(target.validity, targetRow);
    if (target.kind === "string") target.codes[targetRow] = NULL_STRING_VECTOR_CODE;
    else target.values[targetRow] = 0;
    return;
  }
  setBitmapValue(target.validity, targetRow);
  if (source.kind === "boolean" && target.kind === "boolean") {
    target.values[targetRow] = source.values[sourceRow] ?? 0;
    return;
  }
  if (
    (source.kind === "number" || source.kind === "datetime") &&
    (target.kind === "number" || target.kind === "datetime")
  ) {
    target.values[targetRow] = source.values[sourceRow] ?? 0;
    return;
  }
  if (source.kind !== "string" || target.kind !== "string" || targetDictionaryIndex === undefined) {
    throw new Error("String vector dictionary is missing");
  }
  const sourceCode = source.codes[sourceRow] ?? NULL_STRING_VECTOR_CODE;
  const value = source.dictionary[sourceCode];
  if (value === undefined) throw new Error("String vector code is invalid");
  let targetCode = targetDictionaryIndex.get(value);
  if (targetCode === undefined) {
    targetCode = target.dictionary.length;
    (target.dictionary as string[]).push(value);
    targetDictionaryIndex.set(value, targetCode);
  }
  target.codes[targetRow] = targetCode;
}

/** Rough per-row bookkeeping overhead used when tallying retained row objects. */
const QUERY_ROW_OVERHEAD_BYTES = 16;

/** Reads one value from a (possibly windowed) column vector as a query value. */
function columnVectorValueAt(vector: ColumnVector, rowIndex: number): QueryValue {
  const window = vector.window;
  let slot = rowIndex;
  if (window !== undefined) {
    slot = rowIndex - window.start;
    if (slot < 0 || slot >= window.length) {
      throw new RangeError("Streamed vector row is outside the resident window");
    }
  }
  if (!bitmapHasValue(vector.validity, slot)) return null;
  if (vector.kind === "boolean") return vector.values[slot] === 1;
  if (vector.kind === "number") return vector.values[slot] ?? 0;
  if (vector.kind === "datetime") return new Date(vector.values[slot] ?? 0);
  const code = vector.codes[slot] ?? NULL_STRING_VECTOR_CODE;
  return code === NULL_STRING_VECTOR_CODE ? null : (vector.dictionary[code] ?? null);
}

const joinHashScratch = new DataView(new ArrayBuffer(8));

/**
 * Hash-partitions a join key so values the executor's equi-join treats as equal share a
 * partition: datetimes hash as their epoch milliseconds exactly like numbers (the executor
 * compares them coerced), -0 folds to 0, and strings hash their UTF-16 code units. The
 * partition count is a power of two.
 */
function joinPartitionOf(value: Exclude<QueryValue, null>, partitions: number): number {
  let hash = 0x811c9dc5;
  const mix = (word: number): void => {
    hash = Math.imul(hash ^ word, 0x01000193) >>> 0;
  };
  if (typeof value === "string") {
    for (let index = 0; index < value.length; index += 1) mix(value.charCodeAt(index));
    mix(0x53);
  } else if (typeof value === "boolean") {
    mix(value ? 1 : 0);
    mix(0x42);
  } else {
    const numeric = value instanceof Date ? dateMilliseconds(value) : value;
    joinHashScratch.setFloat64(0, numeric === 0 ? 0 : numeric, true);
    mix(joinHashScratch.getUint32(0, true));
    mix(joinHashScratch.getUint32(4, true));
    mix(0x4e);
  }
  // Multiplicative mixing only propagates input variation toward high bits (small integers as
  // float64 vary in no low word bits at all), so a final avalanche folds the high bits back
  // down before the low-bit partition mask.
  hash ^= hash >>> 16;
  hash = Math.imul(hash, 0x85ebca6b) >>> 0;
  hash ^= hash >>> 13;
  hash = Math.imul(hash, 0xc2b2ae35) >>> 0;
  hash ^= hash >>> 16;
  return (hash >>> 0) & (partitions - 1);
}

/**
 * Detects the partitioned-join eligible shape: exactly one inner equi-join with no ON residue,
 * ungrouped and unordered (grouped joins need partial aggregation, ordered joins a final
 * re-sort pass), non-wildcard select, and both join sides written as qualified bare columns —
 * one resolving to the joined table (the build side) and one to the base.
 */
function partitionedJoinShape(
  plan: CompiledQuery,
): { buildTableName: string; buildKeyName: string } | undefined {
  const join = plan.joins[0];
  if (plan.joins.length !== 1 || join === undefined) return undefined;
  if (join.kind !== "inner" || join.on !== undefined) return undefined;
  if (compiledPlanIsGrouped(plan) || plan.orderBy.length > 0) return undefined;
  if (plan.select.some((item) => item.expression.kind === "wildcard")) return undefined;
  const buildNames = new Set([join.table, join.alias]);
  const baseNames = new Set([plan.base.table, plan.base.alias]);
  const sideOf = (expression: Expression): "build" | "base" | undefined => {
    if (expression.kind !== "column") return undefined;
    const parts = expression.reference.split(".");
    if (parts.length !== 2) return undefined;
    if (buildNames.has(parts[0] ?? "")) return "build";
    if (baseNames.has(parts[0] ?? "")) return "base";
    return undefined;
  };
  const leftSide = sideOf(join.left);
  const rightSide = sideOf(join.right);
  const buildExpression =
    leftSide === "build" && rightSide === "base"
      ? join.left
      : leftSide === "base" && rightSide === "build"
        ? join.right
        : undefined;
  if (buildExpression?.kind !== "column") return undefined;
  const buildKeyName = buildExpression.reference.split(".")[1] ?? "";
  if (buildKeyName.length === 0) return undefined;
  return { buildTableName: join.table, buildKeyName };
}

/** Crude resident-size guess used only to pick a strategy; reservations gate real memory. */
function estimatedColumnarBytes(
  segments: readonly SegmentRecord[],
  columns: readonly TableColumnRecord[],
): number {
  let rows = 0;
  for (const segment of segments) {
    const kind = segment.kind;
    if (kind === "insert" || kind === "base") rows += segment.rowCount;
  }
  let rowWidth = 0;
  for (const column of columns) rowWidth += column.type === "string" ? 32 : 8;
  return rows * Math.max(rowWidth, 1);
}

/** A unique key read straight out of a vector: no per-row string token, no allocation. */
type OverlayKey = string | number | boolean;

/** One update segment row: which columns it changed, and whether a base row took it. */
interface OverlayUpdate {
  readonly order: number;
  readonly row: number;
  readonly vectors: ReadonlyMap<string, ColumnVector>;
  applied: boolean;
}

/** Whether a visible segment is a delete or update delta rather than appended rows. */
function mutationSegmentKind(segment: SegmentRecord): boolean {
  const kind = segment.kind;
  return kind !== "insert" && kind !== "base";
}

/** One update row standing in for a base row's column: the resident update vector and the row in it. */
interface OverlayPatch {
  readonly vector: ColumnVector;
  readonly row: number;
}

/**
 * The replayed mutation state of one visible segment set, shared by every query over it until
 * the next commit: see `#streamedOverlayState`.
 */
interface StreamedOverlayState {
  /** Rows in the scan (insert/base) segments, before deletes. */
  readonly baseRows: number;
  readonly deadCount: number;
  /** One bit per base row; set when a delete removed it. */
  readonly dead: Uint8Array;
  /** Per patched base row, the column IDs an update replaced. */
  readonly patches: ReadonlyMap<number, ReadonlyMap<string, OverlayPatch>>;
  /** The patched base rows in ascending order, for range counts. */
  readonly patchedSlots: Uint32Array;
  /** Modeled retained bytes, as charged to the buffer pool and tallied to each query. */
  readonly bytes: number;
}

/**
 * The shape of one outer overlay window over base rows `[from, to)`, as a flat list of steps
 * in base order: a pair `(start, length)` with a positive length is a run of live rows nothing
 * patched, copied as one slice; a pair `(row, 0)` is a single patched live row. Dead rows
 * appear in neither. Built once per window and applied to every projected column.
 */
type OverlayWindowSteps = number[];

const BYTE_POPCOUNT = new Uint8Array(256).map((_, byte) => {
  let count = 0;
  for (let value = byte; value !== 0; value &= value - 1) count += 1;
  return count;
});

/** Set bits in `bitmap` over bit indexes `[from, to)`. */
function bitmapCountRange(bitmap: Uint8Array, from: number, to: number): number {
  let count = 0;
  let index = from;
  while (index < to && (index & 7) !== 0) {
    if (bitmapHasValue(bitmap, index)) count += 1;
    index += 1;
  }
  while (index + 8 <= to) {
    count += BYTE_POPCOUNT[bitmap[index >>> 3] ?? 0] ?? 0;
    index += 8;
  }
  while (index < to) {
    if (bitmapHasValue(bitmap, index)) count += 1;
    index += 1;
  }
  return count;
}

/** The first index in ascending `sorted` whose value is at least `value`. */
function sortedLowerBound(sorted: Uint32Array, value: number): number {
  let low = 0;
  let high = sorted.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if ((sorted[middle] ?? 0) < value) low = middle + 1;
    else high = middle;
  }
  return low;
}

/** Members of ascending `sorted` in `[from, to)`. */
function sortedCountRange(sorted: Uint32Array, from: number, to: number): number {
  return sortedLowerBound(sorted, to) - sortedLowerBound(sorted, from);
}

function overlayWindowRuns(
  dead: Uint8Array,
  patchedSlots: Uint32Array,
  from: number,
  to: number,
  patchedInWindow: number,
): OverlayWindowSteps {
  const steps: OverlayWindowSteps = [];
  let nextPatched = patchedInWindow > 0 ? sortedLowerBound(patchedSlots, from) : -1;
  let row = from;
  while (row < to) {
    // Dead rows, eight at a time where a whole byte is dead.
    if (bitmapHasValue(dead, row)) {
      row += 1;
      while (row < to && (row & 7) === 0 && dead[row >>> 3] === 0xff && row + 8 <= to) row += 8;
      while (row < to && bitmapHasValue(dead, row)) row += 1;
      continue;
    }
    const patchedRow = nextPatched >= 0 ? (patchedSlots[nextPatched] ?? to) : to;
    if (row === patchedRow) {
      steps.push(row, 0);
      row += 1;
      nextPatched += 1;
      if (nextPatched >= patchedSlots.length) nextPatched = -1;
      continue;
    }
    // A live run: up to the next patched row, the window end, or the next dead row — live
    // rows are consecutive except where a delete cut them, and whole live bytes skip in one.
    const limit = Math.min(to, patchedRow);
    const runStart = row;
    row += 1;
    while (row < limit && (row & 7) === 0 && row + 8 <= limit && dead[row >>> 3] === 0) row += 8;
    while (row < limit && !bitmapHasValue(dead, row)) row += 1;
    steps.push(runStart, row - runStart);
  }
  return steps;
}

/**
 * Copies `length` bits from `source` at bit `sourceStart` to `target` at bit `targetStart`,
 * whole bytes at a time once the target is byte-aligned: the target bytes it overwrites lie
 * entirely inside the copied range, so the target's other bits are left alone. This is what
 * makes a validity copy proportional to bytes rather than to cells.
 */
function copyBitRun(
  source: Uint8Array,
  sourceStart: number,
  target: Uint8Array,
  targetStart: number,
  length: number,
): void {
  let remaining = length;
  let from = sourceStart;
  let to = targetStart;
  while (remaining > 0 && (to & 7) !== 0) {
    if (bitmapHasValue(source, from)) setBitmapValue(target, to);
    from += 1;
    to += 1;
    remaining -= 1;
  }
  const shift = from & 7;
  if (shift === 0) {
    const bytes = remaining >>> 3;
    if (bytes > 0) {
      target.set(source.subarray(from >>> 3, (from >>> 3) + bytes), to >>> 3);
      from += bytes * 8;
      to += bytes * 8;
      remaining -= bytes * 8;
    }
  } else {
    while (remaining >= 8) {
      const sourceByte = from >>> 3;
      target[to >>> 3] =
        (((source[sourceByte] ?? 0) >>> shift) | ((source[sourceByte + 1] ?? 0) << (8 - shift))) &
        0xff;
      from += 8;
      to += 8;
      remaining -= 8;
    }
  }
  while (remaining > 0) {
    if (bitmapHasValue(source, from)) setBitmapValue(target, to);
    from += 1;
    to += 1;
    remaining -= 1;
  }
}

/**
 * An outer window that is the inner window's rows from `offset` on, by reference: typed-array
 * views over the resident block, and its dictionary as-is. Validity is a view too when the
 * offset falls on a byte, and otherwise the one small copy a bit offset forces.
 */
function overlayWindowView(
  inner: ColumnVector,
  offset: number,
  rows: number,
  memory: QueryMemoryContext,
  column: TableColumnRecord,
  reservations: QueryMemoryReservation[],
): MutableStreamedVectorFields {
  let validity: Uint8Array;
  if ((offset & 7) === 0) {
    validity = inner.validity.subarray(offset >>> 3, (offset >>> 3) + Math.ceil(rows / 8));
  } else {
    validity = new Uint8Array(Math.ceil(rows / 8));
    reservations.push(memory.reserve(validity.byteLength, `Streamed window ${column.name}`));
    copyBitRun(inner.validity, offset, validity, 0, rows);
  }
  const fields: MutableStreamedVectorFields = { validity, window: { start: 0, length: rows } };
  if (inner.kind === "string") {
    fields.codes = inner.codes.subarray(offset, offset + rows);
    fields.dictionary = inner.dictionary as string[];
  } else {
    fields.values = inner.values.subarray(offset, offset + rows);
  }
  return fields;
}

/**
 * An outer window compacted from an inner window: live runs copied as slices, patched rows
 * read from their update vectors. A string window shares the inner dictionary unless a patch
 * has to add to it, in which case it copies the dictionary first.
 */
function overlayWindowCompacted(
  inner: ColumnVector,
  innerWindowStart: number,
  steps: OverlayWindowSteps,
  rows: number,
  patches: ReadonlyMap<number, ReadonlyMap<string, OverlayPatch>> | undefined,
  column: TableColumnRecord,
  memory: QueryMemoryContext,
  reservations: QueryMemoryReservation[],
): MutableStreamedVectorFields {
  const validityBytes = Math.ceil(rows / 8);
  const typedBytes =
    validityBytes +
    (inner.kind === "boolean"
      ? rows
      : inner.kind === "string"
        ? rows * Uint32Array.BYTES_PER_ELEMENT
        : rows * Float64Array.BYTES_PER_ELEMENT);
  reservations.push(memory.reserve(typedBytes, `Streamed window ${column.name}`));
  const validity = new Uint8Array(validityBytes);
  const values =
    inner.kind === "boolean"
      ? new Uint8Array(rows)
      : inner.kind === "string"
        ? undefined
        : new Float64Array(rows);
  const codes = inner.kind === "string" ? new Uint32Array(rows) : undefined;
  codes?.fill(NULL_STRING_VECTOR_CODE);
  let dictionary = inner.kind === "string" ? (inner.dictionary as string[]) : undefined;
  let dictionaryIndex: Map<string, number> | undefined;
  let dictionaryCopied = false;
  const target = (
    codes !== undefined
      ? { kind: "string", length: rows, validity, codes, dictionary: dictionary ?? [] }
      : { kind: inner.kind, length: rows, validity, values }
  ) as ColumnVector;
  let out = 0;
  for (let index = 0; index < steps.length; index += 2) {
    const start = steps[index] ?? 0;
    const length = steps[index + 1] ?? 0;
    const patch = length === 0 ? patches?.get(start)?.get(column.id) : undefined;
    if (patch === undefined) {
      const count = Math.max(1, length);
      copyVectorSpan(inner, start - innerWindowStart, count, target, out);
      out += count;
      continue;
    }
    if (target.kind === "string" && !dictionaryCopied) {
      // A patch value may be new to this window's dictionary, and the inner's belongs to the
      // buffer pool: copy before the first append, and index the copy for the lookups.
      dictionary = [...(dictionary ?? [])];
      (target as unknown as { dictionary: string[] }).dictionary = dictionary;
      dictionaryIndex = new Map(dictionary.map((value, code) => [value, code]));
      dictionaryCopied = true;
    }
    copyColumnVectorValue(patch.vector, patch.row, target, out, dictionaryIndex);
    out += 1;
  }
  if (out !== rows) throw new Error(`Column row count mismatch: ${column.name}`);
  if (dictionaryCopied && dictionary !== undefined) {
    let dictionaryBytes = 0;
    for (const value of dictionary) dictionaryBytes += 16 + value.length * 2;
    reservations.push(memory.reserve(dictionaryBytes, `Streamed window ${column.name}`));
  }
  const fields: MutableStreamedVectorFields = { validity, window: { start: 0, length: rows } };
  if (codes !== undefined) {
    fields.codes = codes;
    fields.dictionary = dictionary ?? [];
  } else if (values !== undefined) {
    fields.values = values;
  }
  return fields;
}

/**
 * Reads a key column's values as primitives. Dictionary-coded strings resolve through the
 * dictionary the vector already holds, so a string key costs one array index and no encoding.
 * Undefined for a windowed vector or a null key — shapes the overlay refuses rather than guesses.
 */
function columnVectorKeyReader(
  vector: ColumnVector,
): ((row: number) => OverlayKey | undefined) | undefined {
  if (vector.window !== undefined) return undefined;
  const validity = vector.validity;
  if (vector.kind === "string") {
    const { codes, dictionary } = vector;
    return (row) =>
      bitmapHasValue(validity, row) ? dictionary[codes[row] ?? NULL_STRING_VECTOR_CODE] : undefined;
  }
  if (vector.kind === "boolean") {
    const values = vector.values;
    return (row) => (bitmapHasValue(validity, row) ? values[row] === 1 : undefined);
  }
  const values = vector.values;
  return (row) => (bitmapHasValue(validity, row) ? values[row] : undefined);
}

/** `columnVectorKeyReader` for a key column that must be readable: a null key is corruption. */
function requiredColumnVectorKeyReader(vector: ColumnVector): (row: number) => OverlayKey {
  const read = columnVectorKeyReader(vector);
  if (read === undefined) throw new Error("Unique key vector cannot be read as keys");
  return (row) => {
    const key = read(row);
    if (key === undefined) throw new TypeError("Unique key cannot be null");
    return key;
  };
}

/**
 * The touched keys as one IN zone predicate, or undefined when zone maps cannot judge them
 * (a string key has no numeric zone map, and an empty set has nothing to prune against).
 */
function touchedKeyPredicate(
  keyColumn: TableColumnRecord,
  touched: ReadonlySet<OverlayKey>,
): ZonePredicate | undefined {
  if (keyColumn.type !== "number" && keyColumn.type !== "datetime") return undefined;
  if (touched.size === 0) return undefined;
  const members = new Float64Array(touched.size);
  let index = 0;
  for (const key of touched) {
    if (typeof key !== "number") return undefined;
    members[index] = key;
    index += 1;
  }
  members.sort();
  return { column: keyColumn, operator: "IN", value: members[0] ?? 0, members };
}

/**
 * Copies a run of rows between vectors: values as one typed-array slice, validity as a bit run.
 * A string run needs `remap` unless both sides share a dictionary — the codes mean nothing on
 * their own. This is what keeps a copy proportional to bytes rather than to cells. The target
 * validity bits of the run must be clear beforehand, as a fresh window's are.
 */
function copyVectorSpan(
  source: ColumnVector,
  sourceStart: number,
  length: number,
  target: ColumnVector,
  targetStart: number,
  remap?: Uint32Array,
): void {
  if (source.kind === "string") {
    if (target.kind !== "string") throw new Error("Column vector type mismatch");
    if (remap === undefined) {
      target.codes.set(source.codes.subarray(sourceStart, sourceStart + length), targetStart);
    } else {
      for (let index = 0; index < length; index += 1) {
        if (!bitmapHasValue(source.validity, sourceStart + index)) continue;
        target.codes[targetStart + index] =
          remap[source.codes[sourceStart + index] ?? NULL_STRING_VECTOR_CODE] ??
          NULL_STRING_VECTOR_CODE;
      }
    }
  } else if (source.kind === "boolean") {
    if (target.kind !== "boolean") throw new Error("Column vector type mismatch");
    target.values.set(source.values.subarray(sourceStart, sourceStart + length), targetStart);
  } else {
    if (target.kind === "string" || target.kind === "boolean") {
      throw new Error("Column vector type mismatch");
    }
    target.values.set(source.values.subarray(sourceStart, sourceStart + length), targetStart);
  }
  copyBitRun(source.validity, sourceStart, target.validity, targetStart, length);
}

/**
 * The live rows of a vector, in order. Runs between deletions copy as typed-array slices and
 * the dictionary is shared, so dropping one row of a million does not rebuild the column.
 */
function compactColumnVector(
  source: ColumnVector,
  alive: Uint8Array,
  aliveCount: number,
): ColumnVector {
  const validity = new Uint8Array(Math.ceil(aliveCount / 8));
  const target: ColumnVector =
    source.kind === "string"
      ? {
          kind: "string",
          length: aliveCount,
          validity,
          codes: new Uint32Array(aliveCount).fill(NULL_STRING_VECTOR_CODE),
          dictionary: source.dictionary,
        }
      : source.kind === "boolean"
        ? { kind: "boolean", length: aliveCount, validity, values: new Uint8Array(aliveCount) }
        : { kind: source.kind, length: aliveCount, validity, values: new Float64Array(aliveCount) };
  let output = 0;
  let runStart = -1;
  for (let row = 0; row <= source.length; row += 1) {
    const live = row < source.length && alive[row] === 1;
    if (live) {
      if (runStart < 0) runStart = row;
      continue;
    }
    if (runStart < 0) continue;
    copyVectorSpan(source, runStart, row - runStart, target, output);
    output += row - runStart;
    runStart = -1;
  }
  return target;
}

/**
 * The live rows of a column an update changed: cell by cell, because a patched string value can
 * be one the source dictionary never held. Later updates win, in segment order.
 */
function patchColumnVector(
  source: ColumnVector,
  column: TableColumnRecord,
  alive: Uint8Array,
  aliveCount: number,
  patches: ReadonlyMap<number, readonly OverlayUpdate[]>,
): ColumnVector {
  const target = createEmptyColumnVector(column.type, aliveCount);
  const dictionaryIndex = column.type === "string" ? new Map<string, number>() : undefined;
  let output = 0;
  for (let row = 0; row < source.length; row += 1) {
    if (alive[row] !== 1) continue;
    let from = source;
    let fromRow = row;
    for (const update of patches.get(row) ?? []) {
      const vector = update.vectors.get(column.id);
      if (vector === undefined) continue;
      from = vector;
      fromRow = update.row;
    }
    copyColumnVectorValue(from, fromRow, target, output, dictionaryIndex);
    output += 1;
  }
  return target;
}

function columnVectorKeyToken(type: SimpleDataType, vector: ColumnVector, row: number): string {
  if (!bitmapHasValue(vector.validity, row)) return keyToken(type, null);
  if (type === "boolean" && vector.kind === "boolean") {
    return keyToken(type, vector.values[row] === 1);
  }
  if (type === "number" && vector.kind === "number") {
    return keyToken(type, vector.values[row] ?? Number.NaN);
  }
  if (type === "datetime" && vector.kind === "datetime") {
    return keyToken(type, new Date(vector.values[row] ?? Number.NaN));
  }
  if (type === "string" && vector.kind === "string") {
    return keyToken(type, vector.dictionary[vector.codes[row] ?? NULL_STRING_VECTOR_CODE] ?? null);
  }
  throw new Error("Column vector type mismatch");
}

function normalizedDatetimeLiteral(value: QueryValue): Date | undefined {
  if (value instanceof Date) return Number.isFinite(dateMilliseconds(value)) ? value : undefined;
  if (!isDateDomainValue(value)) return undefined;
  const external = externalSqlDomainValue(value);
  if (typeof external !== "string") return undefined;
  const date = new Date(`${external}T00:00:00.000Z`);
  return Number.isFinite(dateMilliseconds(date)) ? date : undefined;
}

function zonePredicates(plan: CompiledQuery, table: TableRecord): ZonePredicate[] {
  if (plan.joins.length > 0 || plan.base.table !== table.name) return [];
  const output: ZonePredicate[] = [];
  const resolveColumn = (reference: string): TableColumnRecord | undefined => {
    const parts = reference.split(".");
    if (parts.length === 2 && parts[0] !== plan.base.alias && parts[0] !== table.name) {
      return undefined;
    }
    const name = parts.length === 2 ? parts[1] : parts[0];
    const column = table.columns.find((candidate) => candidate.name === name);
    return column?.type === "number" || column?.type === "datetime" ? column : undefined;
  };
  const comparisons = new Set<ComparisonOperator>(["=", "!=", "<>", ">", ">=", "<", "<="]);
  const asComparison = (operator: PredicateOperator): ComparisonOperator | undefined =>
    comparisons.has(operator as ComparisonOperator) ? (operator as ComparisonOperator) : undefined;
  const literalValue = (column: TableColumnRecord, expression: Expression): number | undefined => {
    if (expression.kind !== "literal") return undefined;
    const datetime =
      column.type === "datetime" ? normalizedDatetimeLiteral(expression.value) : undefined;
    const value =
      column.type === "datetime"
        ? datetime === undefined
          ? undefined
          : dateMilliseconds(datetime)
        : typeof expression.value === "number"
          ? expression.value
          : undefined;
    return value === undefined || !Number.isFinite(value) ? undefined : value;
  };
  for (const predicate of plan.predicates) {
    // A literal list prunes like a comparison does: a block whose range holds no member of
    // the list cannot contain a matching row.
    if (predicate.operator === "IN" && predicate.left.kind === "column") {
      const column = resolveColumn(predicate.left.reference);
      if (column === undefined || predicate.right.kind !== "list") continue;
      const members = new Set<number>();
      let usable = true;
      for (const item of predicate.right.items) {
        // A NULL member matches nothing, so it narrows nothing either; anything that is not a
        // literal of the column's type leaves the list unprunable.
        if (item.kind === "literal" && item.value === null) continue;
        const value = literalValue(column, item);
        if (value === undefined) {
          usable = false;
          break;
        }
        members.add(value);
      }
      if (!usable || members.size === 0) continue;
      const sorted = Float64Array.from(members).sort();
      output.push({ column, operator: "IN", value: sorted[0] ?? 0, members: sorted });
      continue;
    }
    // Zone-map pruning understands plain comparisons only; every other operator scans.
    const comparisonOperator = asComparison(predicate.operator);
    if (comparisonOperator === undefined) continue;
    const leftColumn =
      predicate.left.kind === "column" ? resolveColumn(predicate.left.reference) : undefined;
    const rightColumn =
      predicate.right.kind === "column" ? resolveColumn(predicate.right.reference) : undefined;
    const literal = leftColumn === undefined ? predicate.left : predicate.right;
    const column = leftColumn ?? rightColumn;
    if (column === undefined || literal.kind !== "literal") continue;
    const datetime =
      column.type === "datetime" ? normalizedDatetimeLiteral(literal.value) : undefined;
    const value =
      column.type === "datetime"
        ? datetime === undefined
          ? undefined
          : dateMilliseconds(datetime)
        : typeof literal.value === "number"
          ? literal.value
          : undefined;
    if (value === undefined || !Number.isFinite(value)) continue;
    output.push({
      column,
      operator:
        leftColumn === undefined ? reverseComparison(comparisonOperator) : comparisonOperator,
      value,
    });
  }
  return output;
}

/** Top-level scalar predicates a ready index can answer through a leftmost key prefix. */
function secondaryIndexPredicates(
  plan: CompiledQuery,
  table: TableRecord,
): SecondaryIndexPredicate[] {
  // The table may be the base or one join source; a self-join names it twice, and a
  // predicate on one alias says nothing about the other, so that shape gets no index.
  const sources = [plan.base, ...plan.joins].filter((source) => source.table === table.name);
  const source = sources[0];
  if (source === undefined || sources.length !== 1) return [];
  // In a join, an unqualified reference is resolved at execution against every source, so only
  // a reference qualified by this source's alias (or the table name) can be claimed for its
  // index.
  const joined = plan.joins.length > 0;
  const resolveColumn = (reference: string): TableColumnRecord | undefined => {
    const parts = reference.split(".");
    if (parts.length === 2 && parts[0] !== source.alias && parts[0] !== table.name) {
      return undefined;
    }
    if (parts.length !== 2 && joined) return undefined;
    const name = parts.length === 2 ? parts[1] : parts[0];
    return table.columns.find((candidate) => candidate.name === name);
  };
  interface Constraint {
    members?: BatchValue[];
    lower?: { value: BatchValue; inclusive: boolean };
    upper?: { value: BatchValue; inclusive: boolean };
  }
  const constraints = new Map<string, Constraint>();
  const literalValue = (
    column: TableColumnRecord,
    expression: Expression,
  ): BatchValue | undefined => {
    if (expression.kind !== "literal" || expression.value === null) return undefined;
    let value = expression.value;
    if (column.type === "datetime" && isDateDomainValue(value)) {
      const datetime = normalizedDatetimeLiteral(value);
      if (datetime === undefined) return undefined;
      value = datetime;
    }
    try {
      secondaryIndexTerm(column.type, value);
      return value;
    } catch {
      return undefined;
    }
  };
  for (const predicate of plan.predicates) {
    if (predicate.operator === "IN" && predicate.left.kind === "column") {
      const column = resolveColumn(predicate.left.reference);
      if (column === undefined || predicate.right.kind !== "list") continue;
      const members: BatchValue[] = [];
      let usable = true;
      for (const item of predicate.right.items) {
        if (item.kind === "literal" && item.value === null) continue;
        const value = literalValue(column, item);
        if (value === undefined) {
          usable = false;
          break;
        }
        members.push(value);
      }
      if (!usable || members.length === 0) continue;
      const current = constraints.get(column.id);
      if (current === undefined) constraints.set(column.id, { members });
      continue;
    }
    const comparison =
      predicate.operator === "=" ||
      predicate.operator === ">" ||
      predicate.operator === ">=" ||
      predicate.operator === "<" ||
      predicate.operator === "<="
        ? predicate.operator
        : undefined;
    if (comparison === undefined) continue;
    const leftColumn =
      predicate.left.kind === "column" ? resolveColumn(predicate.left.reference) : undefined;
    const rightColumn =
      predicate.right.kind === "column" ? resolveColumn(predicate.right.reference) : undefined;
    const column = leftColumn ?? rightColumn;
    if (column === undefined) continue;
    const value = literalValue(column, leftColumn === undefined ? predicate.left : predicate.right);
    if (value === undefined) continue;
    const operator = leftColumn === undefined ? reverseComparison(comparison) : comparison;
    const current = constraints.get(column.id) ?? {};
    if (operator === "=") {
      current.members ??= [value];
    } else if (operator === ">" || operator === ">=") {
      current.lower ??= { value, inclusive: operator === ">=" };
    } else {
      current.upper ??= { value, inclusive: operator === "<=" };
    }
    constraints.set(column.id, current);
  }
  const candidates: Array<SecondaryIndexPredicate & { matchedColumns: number }> = [];
  for (const [indexId, index] of Object.entries(table.secondaryIndexes ?? {})) {
    if (index.state !== "ready") continue;
    const columns = secondaryIndexColumnIds(index).map((columnId) =>
      table.columns.find((column) => column.id === columnId),
    );
    if (columns.some((column) => column === undefined)) continue;
    const indexedColumns = columns as TableColumnRecord[];
    let prefixes = [""];
    let matchedColumns = 0;
    let queries: FtsPostingQuery[] | undefined;
    for (let position = 0; position < indexedColumns.length; position += 1) {
      const column = indexedColumns[position];
      if (column === undefined) break;
      const constraint = constraints.get(column.id);
      if (constraint === undefined) break;
      if (constraint.members !== undefined) {
        if (prefixes.length * constraint.members.length > 256) break;
        prefixes = prefixes.flatMap(
          (prefix) =>
            constraint.members?.map(
              (value) => prefix + secondaryIndexComponentTerm(index, column, position, value),
            ) ?? [],
        );
        matchedColumns += 1;
        continue;
      }
      // Domain encodings are stable equality keys, but are not all bytewise SQL orderings
      // (notably exact NUMERIC and declaration-ordered ENUM). Range pruning on them would be
      // unsound, so preserve equality acceleration and let range predicates scan/recheck.
      if (column.sqlDomain !== undefined) break;
      if (constraint.lower === undefined && constraint.upper === undefined) break;
      const descending = secondaryIndexDirections(index)[position] === "desc";
      queries = prefixes.map((prefix) => {
        const query: FtsPostingQuery = {};
        const logicalLower = descending ? constraint.upper : constraint.lower;
        const logicalUpper = descending ? constraint.lower : constraint.upper;
        if (logicalLower === undefined) {
          query.lower = prefix;
          query.lowerInclusive = true;
        } else {
          const term =
            prefix + secondaryIndexComponentTerm(index, column, position, logicalLower.value);
          query.lower = logicalLower.inclusive ? term : `${term}\uffff`;
          query.lowerInclusive = logicalLower.inclusive;
        }
        if (logicalUpper === undefined) {
          query.upper = `${prefix}\uffff`;
          query.upperInclusive = false;
        } else {
          const term =
            prefix + secondaryIndexComponentTerm(index, column, position, logicalUpper.value);
          query.upper = logicalUpper.inclusive ? `${term}\uffff` : term;
          query.upperInclusive = logicalUpper.inclusive;
        }
        return query;
      });
      matchedColumns += 1;
      break;
    }
    if (matchedColumns === 0) continue;
    if (queries === undefined) {
      const complete = matchedColumns === indexedColumns.length;
      queries = prefixes.map((term) => ({ term, prefix: !complete }));
    }
    candidates.push({
      columns: indexedColumns.slice(0, matchedColumns),
      indexId,
      index,
      queries,
      union: queries.length > 1,
      matchedColumns,
    });
  }
  candidates.sort(
    (left, right) =>
      right.matchedColumns - left.matchedColumns || left.queries.length - right.queries.length,
  );
  const usedColumns = new Set<string>();
  const output: SecondaryIndexPredicate[] = [];
  for (const candidate of candidates) {
    const ids = candidate.columns.map((column) => column.id);
    if (ids.every((columnId) => usedColumns.has(columnId))) continue;
    ids.forEach((columnId) => usedColumns.add(columnId));
    output.push(candidate);
  }
  return output;
}

function secondaryIndexOrderForPlan(
  plan: CompiledQuery,
  table: TableRecord,
  projectedColumns: readonly TableColumnRecord[],
  requireCovering = true,
): { indexId: string; index: SecondaryIndexRecord; reverse: boolean } | undefined {
  if (
    plan.joins.length > 0 ||
    plan.base.table !== table.name ||
    plan.orderBy.length === 0 ||
    projectedColumns.length === 0 ||
    compiledPlanIsGrouped(plan) ||
    plan.distinctWildcard === true ||
    planContainsFts(plan)
  ) {
    return undefined;
  }
  const resolveOrderColumn = (expression: Expression): TableColumnRecord | undefined => {
    let resolved = expression;
    if (resolved.kind === "column") {
      const reference = resolved.reference;
      const alias = plan.select.find((item) => item.alias === reference);
      if (alias !== undefined) resolved = alias.expression;
    }
    if (resolved.kind !== "column") return undefined;
    const parts = resolved.reference.split(".");
    if (parts.length === 2 && parts[0] !== plan.base.alias && parts[0] !== table.name) {
      return undefined;
    }
    return table.columns.find((column) => column.name === (parts.at(-1) ?? ""));
  };
  const orderColumns = plan.orderBy.map((order) => resolveOrderColumn(order.expression));
  if (orderColumns.some((column) => column === undefined)) return undefined;
  for (const [indexId, index] of Object.entries(table.secondaryIndexes ?? {})) {
    if (index.state !== "ready" || index.locator !== "row-id") {
      continue;
    }
    const ids = secondaryIndexColumnIds(index);
    const indexColumns = ids.map((columnId) =>
      table.columns.find((column) => column.id === columnId),
    );
    if (
      indexColumns.some(
        (column) => column === undefined || column.nullable || column.sqlDomain !== undefined,
      ) ||
      (requireCovering && projectedColumns.some((column) => !ids.includes(column.id))) ||
      orderColumns.length > ids.length ||
      orderColumns.some((column, position) => column?.id !== ids[position])
    ) {
      continue;
    }
    const declared = secondaryIndexDirections(index).slice(0, orderColumns.length);
    const requested = plan.orderBy.map((order) => order.direction);
    const forward = requested.every((direction, position) => direction === declared[position]);
    const reverse = requested.every((direction, position) => direction !== declared[position]);
    if (!forward && !reverse) continue;
    return { indexId, index, reverse };
  }
  return undefined;
}

function planReferencesColumn(plan: CompiledQuery, table: TableRecord, columnId: string): boolean {
  const column = table.columns.find((candidate) => candidate.id === columnId);
  if (column === undefined) return false;
  const aliases = new Set([table.name, plan.base.alias]);
  const references = (expression: Expression): boolean => {
    if (expression.kind === "column") {
      const parts = expression.reference.split(".");
      return parts.length === 1
        ? parts[0] === column.name
        : aliases.has(parts[0] ?? "") && parts[1] === column.name;
    }
    return childExpressions(expression).some(references);
  };
  return plan.predicates.some(
    (predicate) => references(predicate.left) || references(predicate.right),
  );
}

function segmentRowsIntersectLocators(
  segment: SegmentRecord,
  rowStart: number,
  rowCount: number,
  candidates: readonly bigint[],
): boolean {
  const rowEnd = rowStart + rowCount;
  const kind = segment.kind;
  for (const span of mergeSourceRowIdSpans(segment, kind)) {
    const from = Math.max(rowStart, span.rowStart);
    const to = Math.min(rowEnd, span.rowStart + span.rowCount);
    if (from >= to) continue;
    const locatorStart = span.rowIdStart + BigInt(from - span.rowStart);
    if (sortedRowIdsIntersectRange(candidates, locatorStart, locatorStart + BigInt(to - from))) {
      return true;
    }
  }
  return false;
}

/** Index of the first ascending member at or above `value`, or the member count. */
function firstMemberAtLeast(members: Float64Array, value: number): number {
  let low = 0;
  let high = members.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if ((members[middle] ?? 0) < value) low = middle + 1;
    else high = middle;
  }
  return low;
}

const sequenceFunctionNames: ReadonlySet<string> = new Set(["NEXTVAL", "CURRVAL"]);
const nonDeterministicFunctionNames: ReadonlySet<string> = new Set([
  ...volatileScalarFunctionNames,
  ...sequenceFunctionNames,
  "CURRENT_DATE",
  "CURRENT_TIMESTAMP",
  "CURRENT_TIME",
  "LOCALTIME",
  "LOCALTIMESTAMP",
  "NOW",
]);

/** Whether any expression of a block, or of a block nested anywhere under it, calls a name. */
function blockCallsFunctions(block: CompiledQuery, names: ReadonlySet<string>): boolean {
  const state = { found: false };
  const visit = (expression: Expression): void => {
    if (state.found) return;
    if (expression.kind === "call" && names.has(expression.name)) {
      state.found = true;
      return;
    }
    if (expression.kind === "subquery" || expression.kind === "exists") {
      if (blockCallsFunctions(expression.block, names)) state.found = true;
      return;
    }
    childExpressions(expression).forEach(visit);
  };
  forEachBlockExpression(block, visit);
  forEachNestedBlock(block, (nested) => {
    if (!state.found && blockCallsFunctions(nested, names)) state.found = true;
  });
  return state.found;
}

/**
 * The literal values a plan's conjunctive predicates pin one table's unique key to, through
 * `alias.key = literal` and `alias.key IN (literals)`; undefined when the key is unconstrained.
 * References are resolved with the same alias rules as secondary-index predicates.
 */
function uniqueKeyMembers(
  plan: CompiledQuery,
  table: TableRecord,
  keyColumn: TableColumnRecord,
): BatchValue[] | undefined {
  const sources = [plan.base, ...plan.joins].filter((source) => source.table === table.name);
  const source = sources[0];
  if (source === undefined || sources.length !== 1) return undefined;
  const joined = plan.joins.length > 0;
  const isKey = (expression: Expression): boolean => {
    if (expression.kind !== "column") return false;
    const parts = expression.reference.split(".");
    if (parts.length === 2) {
      return (parts[0] === source.alias || parts[0] === table.name) && parts[1] === keyColumn.name;
    }
    return !joined && parts[0] === keyColumn.name;
  };
  const literal = (expression: Expression): BatchValue | undefined => {
    if (expression.kind !== "literal" || expression.value === null) return undefined;
    let value = expression.value;
    if (keyColumn.type === "datetime" && isDateDomainValue(value)) {
      const datetime = normalizedDatetimeLiteral(value);
      if (datetime === undefined) return undefined;
      value = datetime;
    }
    if (keyColumn.type === "datetime" && !(value instanceof Date)) return undefined;
    if (keyColumn.type === "number" && typeof value !== "number") return undefined;
    if (keyColumn.type === "string" && typeof value !== "string") return undefined;
    if (keyColumn.type === "boolean" && typeof value !== "boolean") return undefined;
    return value;
  };
  let members: BatchValue[] | undefined;
  for (const predicate of plan.predicates) {
    let found: BatchValue[] | undefined;
    if (predicate.operator === "=") {
      const value = isKey(predicate.left)
        ? literal(predicate.right)
        : isKey(predicate.right)
          ? literal(predicate.left)
          : undefined;
      if (value !== undefined) found = [value];
    } else if (
      predicate.operator === "IN" &&
      isKey(predicate.left) &&
      predicate.right.kind === "list"
    ) {
      const values: BatchValue[] = [];
      for (const item of predicate.right.items) {
        const value = literal(item);
        if (value === undefined) {
          if (item.kind === "literal" && item.value === null) continue;
          values.length = 0;
          break;
        }
        values.push(value);
      }
      if (values.length > 0) found = values;
    }
    if (found === undefined) continue;
    // Two constraints on the key intersect; the narrower one is enough for a superset.
    if (members === undefined || found.length < members.length) members = found;
  }
  return members;
}

function reverseComparison(operator: ComparisonOperator): ComparisonOperator {
  if (operator === ">") return "<";
  if (operator === ">=") return "<=";
  if (operator === "<") return ">";
  if (operator === "<=") return ">=";
  return operator;
}

function zoneMapCanMatch(
  description: ReturnType<typeof inspectBlock>,
  predicate: ZonePredicate,
): boolean {
  if (description.nullCount === description.rowCount) return false;
  const zoneMap = description.metadata.zoneMap;
  if (zoneMap === undefined) return true;
  if (predicate.operator === "IN") {
    const members = predicate.members;
    if (members === undefined) return true;
    const first = firstMemberAtLeast(members, zoneMap.min);
    return first < members.length && (members[first] ?? 0) <= zoneMap.max;
  }
  if (predicate.operator === "=") {
    return predicate.value >= zoneMap.min && predicate.value <= zoneMap.max;
  }
  if (predicate.operator === "!=" || predicate.operator === "<>") {
    return zoneMap.min !== predicate.value || zoneMap.max !== predicate.value;
  }
  if (predicate.operator === ">") return zoneMap.max > predicate.value;
  if (predicate.operator === ">=") return zoneMap.max >= predicate.value;
  if (predicate.operator === "<") return zoneMap.min < predicate.value;
  return zoneMap.min <= predicate.value;
}

function vectorPredicateMatches(
  vector: ColumnVector,
  row: number,
  predicate: ZonePredicate,
): boolean {
  if (!bitmapHasValue(vector.validity, row)) return false;
  if (
    (predicate.column.type !== "number" || vector.kind !== "number") &&
    (predicate.column.type !== "datetime" || vector.kind !== "datetime")
  ) {
    throw new Error("Predicate vector type mismatch");
  }
  const value = vector.values[row] ?? Number.NaN;
  if (predicate.operator === "IN") {
    const members = predicate.members;
    if (members === undefined) return true;
    const first = firstMemberAtLeast(members, value);
    return first < members.length && (members[first] ?? 0) === value;
  }
  if (predicate.operator === "=") return value === predicate.value;
  if (predicate.operator === "!=" || predicate.operator === "<>") return value !== predicate.value;
  if (predicate.operator === ">") return value > predicate.value;
  if (predicate.operator === ">=") return value >= predicate.value;
  if (predicate.operator === "<") return value < predicate.value;
  return value <= predicate.value;
}

function bitmapHasValue(bitmap: Uint8Array, index: number): boolean {
  return ((bitmap[index >>> 3] ?? 0) & (1 << (index & 7))) !== 0;
}

function setBitmapValue(bitmap: Uint8Array, index: number): void {
  const byte = index >>> 3;
  bitmap[byte] = (bitmap[byte] ?? 0) | (1 << (index & 7));
}

function clearBitmapValue(bitmap: Uint8Array, index: number): void {
  const byte = index >>> 3;
  bitmap[byte] = (bitmap[byte] ?? 0) & ~(1 << (index & 7));
}

function validateCompression(value: unknown, name: string): Compression {
  if (value !== "raw" && value !== "gzip") {
    throw new TypeError(`${name} must be raw or gzip`);
  }
  return value;
}

function isPhysicalColumnLimitError(error: unknown): boolean {
  return (
    error instanceof RangeError && error.message === "Physical column exceeds maximum byte length"
  );
}

function safeWholeNumberSum(values: readonly number[], name: string): number {
  let total = 0;
  for (const value of values) {
    if (!Number.isSafeInteger(value) || value < 0 || total > Number.MAX_SAFE_INTEGER - value) {
      throw new RangeError(`${name} exceeds the safe integer range`);
    }
    total += value;
  }
  return total;
}

function safeWholeNumberProduct(left: number, right: number, name: string): number {
  if (
    !Number.isSafeInteger(left) ||
    left < 0 ||
    !Number.isSafeInteger(right) ||
    right < 0 ||
    (left !== 0 && right > Math.floor(Number.MAX_SAFE_INTEGER / left))
  ) {
    throw new RangeError(`${name} exceeds the safe integer range`);
  }
  return left * right;
}

function validateMergeSegmentShape(
  table: TableRecord,
  segmentId: string,
  kind: SegmentKind,
  columns: readonly MergeCompactionSourceColumn[],
  keyColumnId: string,
): void {
  const columnIds = columns.map((column) => column.columnId);
  const tableColumnIds = table.columns.map((column) => column.id);
  if (kind === "insert" || kind === "upsert" || kind === "base") {
    if (
      columnIds.length !== tableColumnIds.length ||
      columnIds.some((columnId, index) => columnId !== tableColumnIds[index])
    ) {
      throw new Error(`Full-row compaction source is missing columns: ${segmentId}`);
    }
    return;
  }
  if (kind === "delete") {
    if (columnIds.length !== 1 || columnIds[0] !== keyColumnId) {
      throw new Error(`Delete compaction source has invalid columns: ${segmentId}`);
    }
    return;
  }
  if (
    columnIds.length < 2 ||
    !columnIds.includes(keyColumnId) ||
    columnIds.every((columnId) => columnId === keyColumnId)
  ) {
    throw new Error(`Update compaction source has invalid columns: ${segmentId}`);
  }
}

function mergeSourceRowIdSpans(segment: SegmentRecord, kind: SegmentKind): RowIdSpan[] {
  if (kind === "update" || kind === "delete") {
    if (
      segment.rowIdStart !== 0n ||
      segment.rowIdEndExclusive !== 0n ||
      segment.rowIdSpans.length !== 0
    ) {
      throw new Error(`Mutation marker unexpectedly owns row IDs: ${segment.id}`);
    }
    return [];
  }
  const spans =
    segment.rowIdSpans.length === 0
      ? [{ rowStart: 0, rowCount: segment.rowCount, rowIdStart: segment.rowIdStart }]
      : segment.rowIdSpans.map((span) => ({ ...span }));
  const envelope = rowIdSpanEnvelope(spans);
  let rowStart = 0;
  for (const [index, span] of spans.entries()) {
    if (span.rowStart !== rowStart || span.rowCount <= 0) {
      throw new Error(`Segment row ID spans are not contiguous: ${segment.id}`);
    }
    const previous = spans[index - 1];
    if (
      previous !== undefined &&
      previous.rowIdStart + BigInt(previous.rowCount) === span.rowIdStart
    ) {
      throw new Error(`Segment row ID spans are not coalesced: ${segment.id}`);
    }
    rowStart = safeWholeNumberSum([rowStart, span.rowCount], "Segment row ID span rows");
  }
  if (
    rowStart !== segment.rowCount ||
    envelope.start !== segment.rowIdStart ||
    envelope.endExclusive !== segment.rowIdEndExclusive
  ) {
    throw new Error(`Segment row ID spans differ from their envelope: ${segment.id}`);
  }
  const intervals = spans
    .map((span) => ({
      start: span.rowIdStart,
      end: span.rowIdStart + BigInt(span.rowCount),
    }))
    .sort((left, right) => (left.start < right.start ? -1 : left.start > right.start ? 1 : 0));
  for (let index = 1; index < intervals.length; index += 1) {
    const previous = intervals[index - 1];
    const current = intervals[index];
    if (previous !== undefined && current !== undefined && current.start < previous.end) {
      throw new Error(`Segment row IDs overlap: ${segment.id}`);
    }
  }
  return spans;
}

function assertCanonicalMergeSourceOrder(segments: readonly MergeCompactionSourceSegment[]): void {
  for (let index = 1; index < segments.length; index += 1) {
    const previous = segments[index - 1];
    const current = segments[index];
    if (
      previous !== undefined &&
      current !== undefined &&
      compareMergeSourceOrder(previous, current) >= 0
    ) {
      throw new Error("Mutation compaction sources are not in canonical logical order");
    }
  }
}

function compareMergeSourceOrder(
  left: Pick<MergeCompactionSourceSegment, "logicalOrder" | "committedVersion" | "segmentId">,
  right: Pick<MergeCompactionSourceSegment, "logicalOrder" | "committedVersion" | "segmentId">,
): number {
  return (
    left.logicalOrder - right.logicalOrder ||
    left.committedVersion - right.committedVersion ||
    left.segmentId.localeCompare(right.segmentId)
  );
}

function sourceOrderTuple(
  segment: SegmentRecord | undefined,
  transactions: ReadonlyMap<string, { status: string; committedVersion: number | null }>,
  label: string,
): Pick<MergeCompactionSourceSegment, "logicalOrder" | "committedVersion" | "segmentId"> {
  if (segment === undefined) throw new Error(`${label} is unavailable`);
  const owner = transactions.get(segment.transactionId);
  if (owner?.status !== "committed" || owner.committedVersion === null) {
    throw new Error(`${label} has no committed owner: ${segment.id}`);
  }
  return {
    logicalOrder: segment.logicalOrder,
    committedVersion: owner.committedVersion,
    segmentId: segment.id,
  };
}

/** Modeled bytes per referenced key the merge planner and the partition probe hold resident. */
const MERGE_PLANNER_KEY_BYTES = 96;
/** Decode scratch the merge planner reserves, as a multiple of its largest key block. */
const MERGE_PLANNER_DECODED_KEY_BLOCK_FACTOR = 4;

/** How a keyed level-one fold cuts its output into partitions. */
interface KeyedPartitioning {
  /** Every level-one partition of the table at planning, in visible order. */
  readonly partitions: readonly SegmentRecord[];
  /** Target maximum rows per published partition. */
  readonly partitionRows: number;
  /** Whether new rows join the last partition rather than opening a partition behind it. */
  readonly absorbsTail: boolean;
  /** Exclusive upper bound for a published partition's order: the first unselected level-zero segment's order, or the next manifest version. */
  readonly nextLevelZeroOrder: number;
}

interface RechunkPartitioning {
  readonly partitionRows: number;
  /** Exclusive upper bound: first unselected L0 order, or the next manifest version. */
  readonly nextLevelZeroOrder: number;
}

function planLinearOutputPartitions(
  totalRows: number,
  partitionRows: number,
  firstOrder: number,
  nextOrder: number,
): MergeOutputPartition[] {
  const count = Math.max(1, Math.ceil(totalRows / partitionRows));
  const orders = fractionalLogicalOrders(firstOrder, nextOrder, count);
  const partitions: MergeOutputPartition[] = [];
  for (let index = 0, rowStart = 0; index < count; index += 1) {
    const rowCount = Math.min(partitionRows, totalRows - rowStart);
    const logicalOrder = orders[index];
    if (rowCount <= 0 || logicalOrder === undefined) {
      throw new Error("Rechunk partition layout is incomplete");
    }
    partitions.push({ rowStart, rowCount, logicalOrder });
    rowStart += rowCount;
  }
  return partitions;
}

/**
 * Cuts the canonical merged output into the partitions a keyed fold publishes.
 *
 * Each rewritten source partition's surviving rows form one region that keeps the partition's
 * logical order, and so its place among the partitions the fold leaves alone. The rows of the
 * level-zero sources — the tail — form a region behind every existing partition, or extend
 * the last partition's region when the fold absorbs them into it. A region is then chunked to
 * at most `partitionRows` rows per published partition. The first chunk keeps the source
 * partition's order and every further chunk takes an evenly spaced fractional order before
 * the unchanged successor;
 * a fresh tail starts at its earliest source's order. Fractional orders make room independent
 * of adjacent commit versions, so every output is bounded by `partitionRows`. The order is
 * stable: a published partition sorts strictly between its neighbours and below every
 * level-zero segment, so a later fold rewrites it alone without moving a row.
 */
function planOutputPartitions(
  partitioning: KeyedPartitioning,
  sources: readonly MergeCompactionSourceSegment[],
  sourceOutputRowStarts: ReadonlyMap<string, number>,
  totalRows: number,
): MergeOutputPartition[] {
  const { partitions, partitionRows, absorbsTail, nextLevelZeroOrder } = partitioning;
  const startOf = (segmentId: string): number => {
    const start = sourceOutputRowStarts.get(segmentId);
    if (start === undefined) throw new Error(`Merge source has no output position: ${segmentId}`);
    return start;
  };
  const levelZeroRowSources = sources.filter(
    (source) => source.level === 0 && mergeSourceBearsRows(source.kind),
  );
  const tailStart =
    levelZeroRowSources.length === 0 ? totalRows : startOf(levelZeroRowSources[0]?.segmentId ?? "");
  const sourceIds = new Set(sources.map((source) => source.segmentId));
  const sourcedPartitionIndexes = partitions.flatMap((partition, index) =>
    sourceIds.has(partition.id) ? [index] : [],
  );

  interface Region {
    rowStart: number;
    rowCount: number;
    /** The order the first chunk keeps, or null for a fresh tail. */
    anchorOrder: number | null;
    /** Exclusive lower bound for the orders of chunks that take fresh integers. */
    roomStart: number;
    /** Exclusive upper bound for every chunk order. */
    roomEnd: number;
    /** The order a fresh tail starts at when it fits. */
    preferredOrder: number;
  }
  const regions: Region[] = [];
  for (const [position, index] of sourcedPartitionIndexes.entries()) {
    const partition = partitions[index];
    const order = partition?.logicalOrder;
    if (partition === undefined || order === undefined) {
      throw new Error("Partitioned merge source is not a level-one partition");
    }
    const nextSourced = sourcedPartitionIndexes[position + 1];
    const isLast = index === partitions.length - 1;
    const rowStart = startOf(partition.id);
    const rowEnd =
      isLast && absorbsTail
        ? totalRows
        : nextSourced === undefined
          ? tailStart
          : startOf(partitions[nextSourced]?.id ?? "");
    const successorOrder = partitions[index + 1]?.logicalOrder ?? nextLevelZeroOrder;
    regions.push({
      rowStart,
      rowCount: rowEnd - rowStart,
      anchorOrder: order,
      roomStart: order,
      roomEnd: successorOrder,
      preferredOrder: order,
    });
  }
  if (!(absorbsTail && partitions.length > 0)) {
    const lastOrder = partitions[partitions.length - 1]?.logicalOrder ?? -1;
    regions.push({
      rowStart: tailStart,
      rowCount: totalRows - tailStart,
      anchorOrder: null,
      roomStart: lastOrder,
      roomEnd: nextLevelZeroOrder,
      preferredOrder: Math.min(
        ...sources.filter((source) => source.level === 0).map((source) => source.logicalOrder),
      ),
    });
  }

  const output: MergeOutputPartition[] = [];
  for (const region of regions) {
    if (region.rowCount <= 0) continue;
    const chunks = Math.max(1, Math.ceil(region.rowCount / partitionRows));
    const firstOrder = region.anchorOrder ?? region.preferredOrder;
    if (
      !validLogicalOrder(firstOrder) ||
      firstOrder >= region.roomEnd ||
      (region.anchorOrder === null && firstOrder <= region.roomStart)
    ) {
      throw new Error("Partitioned merge has no logical-order interval for its output");
    }
    const logicalOrders = fractionalLogicalOrders(firstOrder, region.roomEnd, chunks);
    const baseRows = Math.floor(region.rowCount / chunks);
    const extraRows = region.rowCount % chunks;
    let rowStart = region.rowStart;
    for (let chunk = 0; chunk < chunks; chunk += 1) {
      const rowCount = baseRows + (chunk < extraRows ? 1 : 0);
      const logicalOrder = logicalOrders[chunk];
      if (logicalOrder === undefined) throw new Error("Partition logical order is unavailable");
      output.push({ rowStart, rowCount, logicalOrder });
      rowStart += rowCount;
    }
  }
  let coveredRows = 0;
  for (const [index, partition] of output.entries()) {
    const previous = output[index - 1];
    if (
      partition.rowStart !== coveredRows ||
      partition.rowCount <= 0 ||
      partition.logicalOrder >= nextLevelZeroOrder ||
      (previous !== undefined && previous.logicalOrder >= partition.logicalOrder)
    ) {
      throw new Error("Partitioned merge produced an invalid partition layout");
    }
    coveredRows += partition.rowCount;
  }
  if (coveredRows !== totalRows) {
    throw new Error("Partitioned merge partitions do not cover the merged output");
  }
  return output;
}

/** `count` increasing doubles in [first, upper), retaining `first` exactly. */
function fractionalLogicalOrders(first: number, upper: number, count: number): number[] {
  if (!validLogicalOrder(first) || !Number.isFinite(upper) || upper <= first || count < 1) {
    throw new Error("Partition logical-order interval is invalid");
  }
  const orders: number[] = [];
  for (let index = 0; index < count; index += 1) {
    const order = index === 0 ? first : first + ((upper - first) * index) / count;
    const previous = orders[index - 1];
    if (
      !validLogicalOrder(order) ||
      order >= upper ||
      (previous !== undefined && order <= previous)
    ) {
      throw new Error("Partition logical-order precision is exhausted");
    }
    orders.push(order);
  }
  return orders;
}

/**
 * The planner's working memory, as `#resolveMergeOutput` allocates it: two bytes per slot, the
 * touched-key set and live-slot map over the delta keys, one patch array per patched row, one
 * decoded key block at a time, and the output ranges themselves — which number the source
 * blocks plus one per patched cell, not one per row. Deliberately generous per element; this
 * bound is what a caller's `memoryBudgetBytes` is judged against, so it must not be optimistic.
 */
function mergePlannerMemoryBound(
  table: TableRecord,
  segments: readonly MergeCompactionSourceSegment[],
  keyColumnId: string,
): number {
  const SLOT_BYTES = 2;
  const KEY_BYTES = MERGE_PLANNER_KEY_BYTES;
  const PATCH_ROW_BYTES = 64;
  const PATCH_CELL_BYTES = 48;
  const RANGE_BYTES = 80;
  let slotRows = 0;
  let deltaKeys = 0;
  let patchRows = 0;
  let sourceBlocks = 0;
  let largestKeyBlockBytes = 0;
  for (const segment of segments) {
    if (mergeSourceBearsRows(segment.kind)) slotRows += segment.rowCount;
    if (mergeSourceReferencesKeys(segment.kind)) deltaKeys += segment.rowCount;
    if (segment.kind === "update" || segment.kind === "upsert") patchRows += segment.rowCount;
    for (const column of segment.columns) {
      sourceBlocks += column.sourceBlocks.length;
      if (column.columnId !== keyColumnId) continue;
      for (const block of column.sourceBlocks) {
        largestKeyBlockBytes = Math.max(largestKeyBlockBytes, block.encodedBytes);
      }
    }
  }
  const columns = table.columns.length;
  return safeWholeNumberSum(
    [
      safeWholeNumberProduct(slotRows, SLOT_BYTES, "Mutation compaction slots"),
      safeWholeNumberProduct(deltaKeys, KEY_BYTES, "Mutation compaction keys"),
      safeWholeNumberProduct(
        patchRows,
        safeWholeNumberSum(
          [
            PATCH_ROW_BYTES,
            safeWholeNumberProduct(columns, PATCH_CELL_BYTES, "Mutation patch cells"),
          ],
          "Mutation compaction patch row",
        ),
        "Mutation compaction patches",
      ),
      safeWholeNumberProduct(
        safeWholeNumberSum(
          [sourceBlocks, safeWholeNumberProduct(patchRows, columns, "Mutation patched cells")],
          "Mutation compaction ranges",
        ),
        RANGE_BYTES,
        "Mutation compaction range bytes",
      ),
      safeWholeNumberProduct(
        largestKeyBlockBytes,
        MERGE_PLANNER_DECODED_KEY_BLOCK_FACTOR,
        "Mutation compaction decoded key block",
      ),
    ],
    "Mutation compaction planner memory",
  );
}

/** Whether a source of this kind contributes rows to the merged output. */
function mergeSourceBearsRows(kind: SegmentKind): boolean {
  return kind === "insert" || kind === "upsert" || kind === "base";
}

/** Whether a source of this kind names existing rows by key. */
function mergeSourceReferencesKeys(kind: SegmentKind): boolean {
  return kind === "delete" || kind === "update" || kind === "upsert";
}

/**
 * A decoded key value as the primitive the overlay replay keys on (`OverlayKey`): equal keys
 * are equal primitives, and one table's key has one type, so nothing can collide.
 */
function overlayKeyOf(type: SimpleDataType, value: BatchValue): OverlayKey {
  if (value === null) throw new TypeError("Unique key cannot be null");
  switch (type) {
    case "boolean":
      if (typeof value !== "boolean") throw new TypeError("Invalid boolean unique key");
      return value;
    case "number":
      if (typeof value !== "number" || !Number.isFinite(value)) {
        throw new TypeError("Invalid number unique key");
      }
      return value;
    case "string":
      if (typeof value !== "string") throw new TypeError("Invalid string unique key");
      return value;
    case "datetime":
      if (!(value instanceof Date) || !Number.isFinite(dateMilliseconds(value))) {
        throw new TypeError("Invalid datetime unique key");
      }
      return dateMilliseconds(value);
  }
}

interface MutableRowIdSpan {
  rowStart: number;
  rowCount: number;
  rowIdStart: bigint;
}

interface MutableMergeOutputSourceRange {
  outputRowStart: number;
  sourceBlockId: string;
  sourceRowStart: number;
  rowCount: number;
}

/**
 * Accumulates the merged output as coalesced row-ID spans and per-column source ranges. A run
 * of untouched rows appends at most one range per source block it crosses, whatever its
 * length; a patched row appends one range per column. Adjacent ranges over the same block
 * merge in place, so the finished plan is proportional to blocks plus patched cells.
 */
class MergeOutputBuilder {
  readonly #columns: readonly TableColumnRecord[];
  readonly #rowIdSpans: MutableRowIdSpan[] = [];
  readonly #rangesByColumn: MutableMergeOutputSourceRange[][];
  readonly #blocksBySegment = new Map<
    string,
    ReadonlyArray<readonly MergeCompactionSourceBlock[]>
  >();
  #totalRows = 0;

  constructor(columns: readonly TableColumnRecord[]) {
    this.#columns = columns;
    this.#rangesByColumn = columns.map(() => []);
  }

  /** Output rows appended so far. */
  get totalRows(): number {
    return this.#totalRows;
  }

  /** Rows `[rowStart, rowStart + rowCount)` of a row-bearing source, unchanged. */
  appendRun(segment: MergeCompactionSourceSegment, rowStart: number, rowCount: number): void {
    if (rowCount <= 0) return;
    this.#appendRowIds(segment, rowStart, rowCount);
    const blocksByColumn = this.#sourceBlocks(segment);
    for (let columnIndex = 0; columnIndex < this.#columns.length; columnIndex += 1) {
      const blocks = blocksByColumn[columnIndex];
      const ranges = this.#rangesByColumn[columnIndex];
      if (blocks === undefined || ranges === undefined) {
        throw new Error("Mutation output column is missing");
      }
      let outputRow = this.#totalRows;
      let remaining = rowCount;
      let rowIndex = rowStart;
      while (remaining > 0) {
        const block = rowRangeAt(blocks, rowIndex);
        if (block === undefined) {
          throw new Error(`Mutation source row is missing: ${segment.segmentId}`);
        }
        const count = Math.min(remaining, block.rowStart + block.rowCount - rowIndex);
        appendMergeOutputRange(ranges, outputRow, block.blockId, rowIndex - block.rowStart, count);
        outputRow += count;
        rowIndex += count;
        remaining -= count;
      }
    }
    this.#totalRows += rowCount;
  }

  /** One row of a row-bearing source whose columns may come from later mutations. */
  appendPatchedRow(
    segment: MergeCompactionSourceSegment,
    rowIndex: number,
    patch: ReadonlyArray<MergeResolvedSource | undefined> | undefined,
  ): void {
    this.#appendRowIds(segment, rowIndex, 1);
    for (let columnIndex = 0; columnIndex < this.#columns.length; columnIndex += 1) {
      const column = this.#columns[columnIndex];
      const ranges = this.#rangesByColumn[columnIndex];
      if (column === undefined || ranges === undefined) {
        throw new Error("Mutation output column is missing");
      }
      const source = patch?.[columnIndex] ?? mergeSourceAt(segment, column.id, rowIndex);
      appendMergeOutputRange(ranges, this.#totalRows, source.blockId, source.sourceRowIndex, 1);
    }
    this.#totalRows += 1;
  }

  finish(): {
    columns: MergeCompactionOutputColumn[];
    rowIdSpans: RowIdSpan[];
    totalRows: number;
  } {
    return {
      rowIdSpans: this.#rowIdSpans,
      columns: this.#columns.map((column, columnIndex) => {
        const sourceRanges = this.#rangesByColumn[columnIndex];
        if (sourceRanges === undefined) throw new Error("Mutation output column is missing");
        return { columnId: column.id, type: column.type, sourceRanges };
      }),
      totalRows: this.#totalRows,
    };
  }

  #sourceBlocks(
    segment: MergeCompactionSourceSegment,
  ): ReadonlyArray<readonly MergeCompactionSourceBlock[]> {
    let blocks = this.#blocksBySegment.get(segment.segmentId);
    if (blocks === undefined) {
      blocks = this.#columns.map((column) => {
        const source = segment.columns.find((candidate) => candidate.columnId === column.id);
        if (source === undefined) {
          throw new Error(`Mutation source row is missing: ${segment.segmentId}:${column.id}`);
        }
        return source.sourceBlocks;
      });
      this.#blocksBySegment.set(segment.segmentId, blocks);
    }
    return blocks;
  }

  #appendRowIds(segment: MergeCompactionSourceSegment, rowStart: number, rowCount: number): void {
    let outputRow = this.#totalRows;
    let remaining = rowCount;
    let rowIndex = rowStart;
    while (remaining > 0) {
      const span = rowRangeAt(segment.rowIdSpans, rowIndex);
      if (span === undefined) {
        throw new Error(`Mutation source row ID is missing: ${String(rowIndex)}`);
      }
      const count = Math.min(remaining, span.rowStart + span.rowCount - rowIndex);
      appendRowIdSpan(
        this.#rowIdSpans,
        outputRow,
        span.rowIdStart + BigInt(rowIndex - span.rowStart),
        count,
      );
      outputRow += count;
      rowIndex += count;
      remaining -= count;
    }
  }
}

/** Appends `rowCount` consecutive row IDs from `rowId`, extending the last span when contiguous. */
function appendRowIdSpan(
  spans: MutableRowIdSpan[],
  rowStart: number,
  rowId: bigint,
  rowCount: number,
): void {
  const previous = spans[spans.length - 1];
  if (
    previous !== undefined &&
    previous.rowStart + previous.rowCount === rowStart &&
    previous.rowIdStart + BigInt(previous.rowCount) === rowId
  ) {
    previous.rowCount += rowCount;
  } else {
    spans.push({ rowStart, rowCount, rowIdStart: rowId });
  }
}

/** Appends `rowCount` output rows read from one source block, extending the last range when contiguous. */
function appendMergeOutputRange(
  ranges: MutableMergeOutputSourceRange[],
  outputRowStart: number,
  sourceBlockId: string,
  sourceRowStart: number,
  rowCount: number,
): void {
  const previous = ranges[ranges.length - 1];
  if (
    previous?.sourceBlockId === sourceBlockId &&
    previous.outputRowStart + previous.rowCount === outputRowStart &&
    previous.sourceRowStart + previous.rowCount === sourceRowStart
  ) {
    previous.rowCount += rowCount;
  } else {
    ranges.push({ outputRowStart, sourceBlockId, sourceRowStart, rowCount });
  }
}

function mergeSourceAt(
  segment: MergeCompactionSourceSegment,
  columnId: string,
  rowIndex: number,
): MergeResolvedSource {
  const column = segment.columns.find((candidate) => candidate.columnId === columnId);
  const block = column === undefined ? undefined : rowRangeAt(column.sourceBlocks, rowIndex);
  if (block === undefined) {
    throw new Error(`Mutation source row is missing: ${segment.segmentId}:${columnId}`);
  }
  return { blockId: block.blockId, sourceRowIndex: rowIndex - block.rowStart };
}

function rowRangeAt<T extends { readonly rowStart: number; readonly rowCount: number }>(
  ranges: readonly T[],
  rowIndex: number,
): T | undefined {
  let low = 0;
  let high = ranges.length - 1;
  while (low <= high) {
    const middle = low + Math.floor((high - low) / 2);
    const range = ranges[middle];
    if (range === undefined) return undefined;
    if (rowIndex < range.rowStart) {
      high = middle - 1;
    } else if (rowIndex >= range.rowStart + range.rowCount) {
      low = middle + 1;
    } else {
      return range;
    }
  }
  return undefined;
}

function rowIdSpanEnvelope(spans: readonly RowIdSpan[]): {
  start: bigint;
  endExclusive: bigint;
} {
  if (spans.length === 0) return { start: 0n, endExclusive: 0n };
  let start = spans[0]?.rowIdStart ?? 0n;
  let endExclusive = start + BigInt(spans[0]?.rowCount ?? 0);
  for (const span of spans.slice(1)) {
    if (span.rowIdStart < start) start = span.rowIdStart;
    const spanEnd = span.rowIdStart + BigInt(span.rowCount);
    if (spanEnd > endExclusive) endExclusive = spanEnd;
  }
  return { start, endExclusive };
}

function validatePhysicalTablePlan(table: TableRecord, plan: PhysicalCompactionRewritePlan): void {
  if (
    table.columns.length !== plan.columns.length ||
    table.columns.some((column, index) => {
      const planned = plan.columns[index];
      return planned?.columnId !== column.id || planned.type !== column.type;
    })
  ) {
    throw new Error(`Compaction table schema changed after planning: ${table.name}`);
  }
  if (plan.kind === "merge-v1" && table.uniqueKeyColumnId !== plan.keyColumnId) {
    throw new Error(`Compaction table key changed after planning: ${table.name}`);
  }
}

function physicalRewriteSourceBlocks(
  plan: PhysicalCompactionRewritePlan,
): Array<RechunkCompactionSourceBlock | MergeCompactionSourceBlock> {
  return plan.kind === "rechunk-v1"
    ? plan.columns.flatMap((column) => [...column.sourceBlocks])
    : plan.sourceSegments.flatMap((segment) =>
        segment.columns.flatMap((column) => [...column.sourceBlocks]),
      );
}

function physicalRewriteSourceStoredBytes(plan: PhysicalCompactionRewritePlan): number {
  return safeWholeNumberSum(
    physicalRewriteSourceBlocks(plan).map((block) => block.storedBytes),
    "Compaction source stored bytes",
  );
}

function physicalRewriteSourceEncodedBytes(plan: PhysicalCompactionRewritePlan): number {
  return safeWholeNumberSum(
    physicalRewriteSourceBlocks(plan).map((block) => block.encodedBytes),
    "Compaction source encoded bytes",
  );
}

function rechunkPhysicalColumns(
  columns: readonly RechunkCompactionSourceColumn[],
): PhysicalCompactionSourceColumn[] {
  return columns.map((column) => ({
    columnId: column.columnId,
    type: column.type,
    sourceRanges: column.sourceBlocks.map((block) => ({
      blockId: block.blockId,
      outputRowStart: block.rowStart,
      sourceRowStart: 0,
      rowCount: block.rowCount,
      sourceBlockRowCount: block.rowCount,
      storedBytes: block.storedBytes,
      encodedBytes: block.encodedBytes,
      checksum: block.checksum,
    })),
  }));
}

function mergePhysicalColumns(
  columns: readonly MergeCompactionOutputColumn[],
  sourceSegments: readonly MergeCompactionSourceSegment[],
): PhysicalCompactionSourceColumn[] {
  const blocks = new Map(
    sourceSegments.flatMap((segment) =>
      segment.columns.flatMap((column) =>
        column.sourceBlocks.map((block) => [block.blockId, block] as const),
      ),
    ),
  );
  return columns.map((column) => ({
    columnId: column.columnId,
    type: column.type,
    sourceRanges: column.sourceRanges.map((range) => {
      const block = blocks.get(range.sourceBlockId);
      if (block === undefined) {
        throw new Error(
          `Mutation compaction source fingerprint is missing: ${range.sourceBlockId}`,
        );
      }
      return {
        blockId: block.blockId,
        outputRowStart: range.outputRowStart,
        sourceRowStart: range.sourceRowStart,
        rowCount: range.rowCount,
        sourceBlockRowCount: block.rowCount,
        storedBytes: block.storedBytes,
        encodedBytes: block.encodedBytes,
        checksum: block.checksum,
      };
    }),
  }));
}

function physicalRewriteLayout(plan: PhysicalCompactionRewritePlan): PhysicalCompactionLayout {
  return {
    targetBlockBytes: plan.targetBlockBytes,
    outputCompression: plan.outputCompression,
    totalRows: plan.totalRows,
    columns:
      plan.kind === "rechunk-v1"
        ? rechunkPhysicalColumns(plan.columns)
        : mergePhysicalColumns(plan.columns, plan.sourceSegments),
    outputs: plan.outputs,
  };
}

function overlappingPhysicalSourceRanges(
  column: PhysicalCompactionSourceColumn,
  output: RechunkCompactionOutputWindow,
): readonly PhysicalCompactionSourceRange[] {
  const outputEnd = safeWholeNumberSum(
    [output.rowStart, output.rowCount],
    "Compaction output row range",
  );
  return column.sourceRanges.filter((block) => {
    const blockEnd = safeWholeNumberSum(
      [block.outputRowStart, block.rowCount],
      "Compaction source row range",
    );
    return block.outputRowStart < outputEnd && blockEnd > output.rowStart;
  });
}

function physicalOutputMemoryBound(
  column: PhysicalCompactionSourceColumn,
  output: RechunkCompactionOutputWindow,
  compression: Compression,
): number {
  const sourceBlocks = overlappingPhysicalSourceRanges(column, output);
  let retainedDecodedBytes = 0;
  let decodePeakBytes = 0;
  for (const block of sourceBlocks) {
    const decodeBytes = safeWholeNumberSum(
      [
        retainedDecodedBytes,
        safeWholeNumberProduct(block.storedBytes, 2, "Compaction decode memory"),
        safeWholeNumberProduct(block.encodedBytes, 2, "Compaction decode memory"),
      ],
      "Compaction decode memory",
    );
    decodePeakBytes = Math.max(decodePeakBytes, decodeBytes);
    retainedDecodedBytes = safeWholeNumberSum(
      [retainedDecodedBytes, block.encodedBytes],
      "Compaction decoded source memory",
    );
  }
  const outputEncodedBytes = retainedDecodedBytes;
  const buildPeakBytes = safeWholeNumberSum(
    [retainedDecodedBytes, outputEncodedBytes],
    "Compaction physical build memory",
  );
  const compressionBound = getCompressionMemoryBound(compression, outputEncodedBytes);
  const maximumBlockBytes = safeWholeNumberSum(
    [MAX_BLOCK_ENVELOPE_BYTES, compressionBound.maximumOutputBytes],
    "Compaction encoded block memory",
  );
  const compressionPeakBytes = safeWholeNumberSum(
    [outputEncodedBytes, compressionBound.scratchBytes, compressionBound.maximumOutputBytes],
    "Compaction compression memory",
  );
  const envelopePeakBytes = safeWholeNumberSum(
    [outputEncodedBytes, compressionBound.maximumOutputBytes, maximumBlockBytes],
    "Compaction block envelope memory",
  );
  const reconciliationPeakBytes = safeWholeNumberSum(
    [
      safeWholeNumberProduct(outputEncodedBytes, 3, "Compaction reconciliation memory"),
      safeWholeNumberProduct(maximumBlockBytes, 2, "Compaction reconciliation memory"),
    ],
    "Compaction reconciliation memory",
  );
  return Math.max(
    1,
    decodePeakBytes,
    buildPeakBytes,
    compressionPeakBytes,
    envelopePeakBytes,
    reconciliationPeakBytes,
  );
}

function compactionMinimumMemoryBytes(plan: PhysicalCompactionRewritePlan): number {
  let minimumBytes = plan.outputs.length === 0 ? 0 : 1;
  const layout = physicalRewriteLayout(plan);
  for (const output of plan.outputs) {
    for (const column of layout.columns) {
      minimumBytes = Math.max(
        minimumBytes,
        physicalOutputMemoryBound(column, output, plan.outputCompression),
      );
    }
  }
  return minimumBytes;
}

function physicalOutputBlockId(jobId: string, outputIndex: number, columnIndex: number): string {
  return [
    jobId,
    "rewrite",
    "window",
    String(outputIndex).padStart(8, "0"),
    "column",
    String(columnIndex).padStart(8, "0"),
  ].join("/");
}

function physicalOutputBlockIds(jobId: string, plan: PhysicalCompactionRewritePlan): string[] {
  return plan.outputs.flatMap((_output, outputIndex) =>
    plan.columns.map((_column, columnIndex) =>
      physicalOutputBlockId(jobId, outputIndex, columnIndex),
    ),
  );
}

function physicalOutputColumns(
  jobId: string,
  plan: PhysicalCompactionRewritePlan,
  window: { readonly rowStart: number; readonly rowCount: number } = {
    rowStart: 0,
    rowCount: plan.totalRows,
  },
): Record<string, string[]> {
  const windowEnd = window.rowStart + window.rowCount;
  return Object.fromEntries(
    plan.columns.map((column, columnIndex) => [
      column.columnId,
      plan.outputs.flatMap((output, outputIndex) =>
        output.rowStart >= window.rowStart && output.rowStart + output.rowCount <= windowEnd
          ? [physicalOutputBlockId(jobId, outputIndex, columnIndex)]
          : [],
      ),
    ]),
  );
}

/** The segment ID partition `index` of a partitioned merge publishes under. */
function partitionOutputSegmentId(outputSegmentId: string, index: number): string {
  return index === 0 ? outputSegmentId : `${outputSegmentId}/${String(index)}`;
}

/** Every segment a job publishes: one per output partition, or the single output segment. */
function compactionOutputSegmentIds(job: CompactionJobRecord): string[] {
  if (job.outputSegmentId === null) return [];
  const plan = job.rewritePlan;
  if ((plan.kind !== "merge-v1" && plan.kind !== "rechunk-v1") || plan.partitions === undefined) {
    return [job.outputSegmentId];
  }
  const outputSegmentId = job.outputSegmentId;
  return plan.partitions.map((_partition, index) =>
    partitionOutputSegmentId(outputSegmentId, index),
  );
}

/**
 * The segments a physical compaction publishes, with the blocks of the windows each covers.
 * A partitioned rewrite publishes one level-one segment per planned partition. A merge carries
 * the slice of its row-ID spans; a rechunk carries the corresponding contiguous interval.
 */
function compactionOutputSegments(
  table: TableRecord,
  job: CompactionJobRecord,
  plan: PhysicalCompactionRewritePlan,
  transactionId: string,
  createdAt: string,
): SegmentRecord[] {
  const outputSegmentId = job.outputSegmentId;
  if (outputSegmentId === null) throw new Error("Compaction output segment ID is missing");
  const keyColumn =
    table.uniqueKeyColumnId === undefined ? {} : { keyColumnId: table.uniqueKeyColumnId };
  const partitionOrdinal =
    job.outputPartitionOrdinal === undefined
      ? {}
      : { partitionOrdinal: job.outputPartitionOrdinal };
  if (plan.partitions !== undefined) {
    return plan.partitions.map((partition, index) => {
      const rowIdSpans =
        plan.kind === "merge-v1"
          ? sliceRowIdSpans(plan.rowIdSpans, partition.rowStart, partition.rowCount)
          : undefined;
      const envelope =
        rowIdSpans === undefined
          ? {
              start: plan.rowIdStart + BigInt(partition.rowStart),
              endExclusive: plan.rowIdStart + BigInt(partition.rowStart + partition.rowCount),
            }
          : rowIdSpanEnvelope(rowIdSpans);
      return {
        id: partitionOutputSegmentId(outputSegmentId, index),
        tableId: table.id,
        transactionId,
        rowCount: partition.rowCount,
        rowIdStart: envelope.start,
        rowIdEndExclusive: envelope.endExclusive,
        columnBlockIds: physicalOutputColumns(job.id, plan, partition),
        kind: plan.kind === "merge-v1" ? "base" : "insert",
        ...keyColumn,
        level: job.targetLevel,
        ...partitionOrdinal,
        logicalOrder: partition.logicalOrder,
        commitOrdinal: index,
        rowIdSpans: rowIdSpans ?? [],
        createdAt,
      };
    });
  }
  return [
    {
      id: outputSegmentId,
      tableId: table.id,
      transactionId,
      rowCount: plan.totalRows,
      rowIdStart: plan.rowIdStart,
      rowIdEndExclusive: plan.rowIdEndExclusive,
      columnBlockIds: physicalOutputColumns(job.id, plan),
      kind: plan.kind === "merge-v1" ? "base" : "insert",
      ...keyColumn,
      level: job.targetLevel,
      ...partitionOrdinal,
      logicalOrder: plan.logicalOrder,
      commitOrdinal: 0,
      rowIdSpans: plan.kind === "merge-v1" ? structuredClone(plan.rowIdSpans) : [],
      createdAt,
    },
  ];
}

/** The spans of output rows `[rowStart, rowStart + rowCount)`, rebased to start at row zero. */
function sliceRowIdSpans(
  spans: readonly RowIdSpan[],
  rowStart: number,
  rowCount: number,
): RowIdSpan[] {
  const sliced: MutableRowIdSpan[] = [];
  const rowEnd = rowStart + rowCount;
  for (const span of spans) {
    const spanEnd = span.rowStart + span.rowCount;
    if (spanEnd <= rowStart || span.rowStart >= rowEnd) continue;
    const start = Math.max(span.rowStart, rowStart);
    const end = Math.min(spanEnd, rowEnd);
    appendRowIdSpan(
      sliced,
      start - rowStart,
      span.rowIdStart + BigInt(start - span.rowStart),
      end - start,
    );
  }
  return sliced;
}

interface CompactionBlockEntry {
  columnId: string;
  sourceBlockId: string;
  outputBlockId: string;
}

function isActiveCompactionState(state: CompactionJobState): boolean {
  return state === "planned" || state === "running" || state === "ready";
}

function uniqueSegmentBlockIds(segments: readonly SegmentRecord[]): string[] {
  return [
    ...new Set(segments.flatMap((segment) => Object.values(segment.columnBlockIds).flat())),
  ].sort();
}

function compactionBlockEntries(
  table: TableRecord,
  segment: SegmentRecord,
  segmentIndex: number,
  jobId: string,
): CompactionBlockEntry[] {
  return table.columns.flatMap((column, columnIndex) =>
    (segment.columnBlockIds[column.id] ?? []).map((sourceBlockId, part) => ({
      columnId: column.id,
      sourceBlockId,
      outputBlockId: [
        jobId,
        "output",
        "segment",
        String(segmentIndex).padStart(6, "0"),
        "column",
        String(columnIndex).padStart(6, "0"),
        "part",
        String(part).padStart(6, "0"),
      ].join("/"),
    })),
  );
}

function compactionOutputColumns(
  table: TableRecord,
  sourceSegments: readonly SegmentRecord[],
  jobId: string,
): Record<string, string[]> {
  return Object.fromEntries(
    table.columns.map((column) => [
      column.id,
      sourceSegments.flatMap((segment, segmentIndex) =>
        compactionBlockEntries(table, segment, segmentIndex, jobId)
          .filter((entry) => entry.columnId === column.id)
          .map((entry) => entry.outputBlockId),
      ),
    ]),
  );
}

function compactionProgress(
  tableName: string,
  job: CompactionJobRecord,
  result: CompactTableResult | null,
): CompactionJobProgress {
  const rewritePlan = job.rewritePlan;
  return {
    jobId: job.id,
    tableName,
    state: job.state,
    processedRows: job.processedRows,
    sourceSegmentCount: job.sourceSegmentIds.length,
    sourceBlockCount: job.sourceBlockIds.length,
    outputBlockCount: job.outputBlockIds.length,
    level0SourceStoredBytes: job.level0SourceStoredBytes,
    anchorSourceStoredBytes: job.anchorSourceStoredBytes,
    ...(job.outputPartitionOrdinal === undefined
      ? {}
      : {
          outputPartitionOrdinal: job.outputPartitionOrdinal,
          maxWriteAmplification: job.maxWriteAmplification ?? 0,
          maximumOutputStoredBytes: job.maximumOutputStoredBytes ?? 0,
          plannedOutputStoredBytesUpperBound: job.plannedOutputStoredBytesUpperBound ?? 0,
          priorAttemptOutputStoredBytes: job.priorAttemptOutputStoredBytes ?? 0,
          lifetimeOutputStoredBytes:
            (job.priorAttemptOutputStoredBytes ?? 0) + job.outputStoredBytes,
        }),
    ...(rewritePlan.kind !== "copy-v1"
      ? {
          memoryBudgetBytes: job.memoryBudgetBytes,
          minimumMemoryBytes: job.minimumMemoryBytes,
          peakWorkingBytes: job.peakWorkingBytes,
        }
      : {}),
    result,
  };
}

function compactionSkippedProgress(result: CompactTableResult): CompactionJobProgress {
  return {
    jobId: null,
    tableName: result.tableName,
    state: "skipped",
    processedRows: 0,
    sourceSegmentCount: result.sourceSegmentCount,
    sourceBlockCount: result.sourceBlockCount,
    outputBlockCount: 0,
    result,
  };
}

function compactionCancellationResult(job: CompactionJobRecord): CancelCompactionJobResult {
  if (job.state !== "cancelled" && job.state !== "published" && job.state !== "aborted") {
    throw new Error(`Compaction cancellation did not reach a terminal state: ${job.id}`);
  }
  return {
    jobId: job.id,
    state: job.state,
    publishedVersion: job.publishedVersion,
  };
}

function garbageCollectionProgress(job: GarbageCollectionJobRecord): GarbageCollectionProgress {
  const result: GarbageCollectionResult | null =
    job.state === "completed"
      ? {
          jobId: job.id,
          prunedManifestCount: job.prunedManifestCount,
          alreadyPrunedManifestCount: job.alreadyPrunedManifestCount,
          retainedManifestCount: job.retainedManifestCount,
          missingManifestCount: job.missingManifestCount,
          reclaimedSegmentCount: job.reclaimedSegmentCount,
          retainedSegmentCount: job.retainedSegmentCount,
          missingSegmentCount: job.missingSegmentCount,
          reclaimedBlockCount: job.reclaimedBlockCount,
          retainedBlockCount: job.retainedBlockCount,
          missingBlockCount: job.missingBlockCount,
          reclaimedTransactionCount: job.reclaimedTransactionCount,
          retainedTransactionCount: job.retainedTransactionCount,
          missingTransactionCount: job.missingTransactionCount,
          physicallyReclaimedBytes: job.reclaimedBlockBytes,
        }
      : null;
  return {
    jobId: job.id,
    state: job.state,
    examinedManifestCount: job.cursor.manifestIndex,
    examinedSegmentCount: job.cursor.segmentIndex,
    examinedBlockCount: job.cursor.blockIndex,
    examinedTransactionCount: job.cursor.transactionIndex,
    result,
  };
}

/** One shared internal reader lease, reused across prepares at the same manifest version. */
interface SharedLeaseEntry {
  lease: LeasedSnapshot;
  version: number | null;
  refCount: number;
}

/** Whether any of the table's triggers for these events fire AFTER the write, staging rows. */
function firesAfterTriggers(
  table: TableRecord,
  ...events: Array<"insert" | "update" | "delete">
): boolean {
  return (table.triggers ?? []).some(
    (trigger) => trigger.timing === "after" && events.includes(trigger.event),
  );
}

/** Collects every real table name referenced by a block, its derived sources, or its subqueries. */
function collectRealTableNames(plan: CompiledQuery): string[] {
  const names = new Set<string>();
  const excluded = new Set<string>();
  const walkExpression = (expression: Expression): void => {
    if (expression.kind === "subquery" || expression.kind === "exists") {
      walk(expression.block);
      return;
    }
    if (expression.kind === "binary" || expression.kind === "condition") {
      walkExpression(expression.left);
      walkExpression(expression.right);
    } else if (expression.kind === "logical") {
      walkExpression(expression.left);
      walkExpression(expression.right);
    } else if (expression.kind === "not") walkExpression(expression.operand);
    else if (expression.kind === "case") {
      for (const branch of expression.branches) {
        walkExpression(branch.when);
        walkExpression(branch.then);
      }
      if (expression.otherwise !== undefined) walkExpression(expression.otherwise);
    } else if (expression.kind === "call") expression.arguments.forEach(walkExpression);
    else if (expression.kind === "list") expression.items.forEach(walkExpression);
  };
  const walk = (block: CompiledQuery): void => {
    for (const source of [block.base, ...block.joins]) {
      if (source.union !== undefined) source.union.blocks.forEach(walk);
      else if (source.windowed !== undefined) walk(source.windowed.block);
      else if (source.recursive !== undefined) {
        // The self-reference is bound per iteration, never loaded from storage.
        excluded.add(source.recursive.reference);
        walk(source.recursive.base);
        walk(source.recursive.step);
      } else if (source.derived === undefined) {
        if (source.table !== DUAL_TABLE) names.add(source.table);
      } else walk(source.derived);
    }
    for (const item of block.select) walkExpression(item.expression);
    block.groupBy.forEach(walkExpression);
    for (const join of block.joins) {
      if (join.on !== undefined) walkExpression(join.on);
    }
    for (const predicate of [...block.predicates, ...block.having]) {
      walkExpression(predicate.left);
      walkExpression(predicate.right);
    }
    for (const order of block.orderBy) walkExpression(order.expression);
  };
  walk(plan);
  for (const name of excluded) names.delete(name);
  return [...names];
}

/** Retained payload of a cached derived columnar table: its vectors plus fixed overhead. */
function derivedTableRetainedBytes(table: ColumnarTable): number {
  let bytes = 128;
  for (const vector of table.columns.values()) bytes += columnVectorRetainedBytes(vector);
  return bytes;
}

/** Retained payload of a column vector: typed arrays plus dictionary characters. */
function columnVectorRetainedBytes(vector: ColumnVector): number {
  const base = vector.validity.byteLength;
  if (vector.kind === "string") {
    let dictionaryBytes = 0;
    for (const value of vector.dictionary) dictionaryBytes += 16 + value.length * 2;
    return base + vector.codes.byteLength + dictionaryBytes;
  }
  return base + vector.values.byteLength;
}

/**
 * Retained bytes for a decoded physical block. A raw column keeps the store-returned backing
 * buffer alive through its zero-copy view, while a compressed column keeps the decompressor's
 * uncompressed backing buffer. Charging the stored byte length undercounts highly compressible
 * blocks by orders of magnitude and lets the cache retain far more memory than its byte budget.
 */
function decodedPhysicalBlockRetainedBytes(block: DecodedPhysicalBlock): number {
  const retainedPayloadBytes = block.column.bytes.buffer.byteLength;
  const metadataBytes = block.description.metadata.zoneMap === undefined ? 0 : 32;
  return retainedPayloadBytes + metadataBytes + 192;
}

/**
 * Memoized retained size of a *block* vector. A block vector is built once per block id and
 * then shared by reference across every query that scans it, so its size never changes —
 * but a streamed scan re-reserves that size on every window install, and for a string column
 * the size walks the whole per-block dictionary. On a point lookup that dictionary walk cost
 * more than the lookup itself. Only pool-owned block vectors go through here: the streamed
 * vector they are installed into is a different object, and it is mutated.
 */
const blockVectorRetainedBytesMemo = new WeakMap<ColumnVector, number>();
function blockVectorRetainedBytes(vector: ColumnVector): number {
  const memoized = blockVectorRetainedBytesMemo.get(vector);
  if (memoized !== undefined) return memoized;
  const bytes = columnVectorRetainedBytes(vector);
  blockVectorRetainedBytesMemo.set(vector, bytes);
  return bytes;
}

function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
  return left.byteLength === right.byteLength && left.every((byte, index) => byte === right[index]);
}

function sameCompactionSegment(left: SegmentRecord, right: SegmentRecord): boolean {
  if (
    left.id !== right.id ||
    left.tableId !== right.tableId ||
    left.rowCount !== right.rowCount ||
    left.rowIdStart !== right.rowIdStart ||
    left.rowIdEndExclusive !== right.rowIdEndExclusive ||
    left.kind !== right.kind ||
    left.keyColumnId !== right.keyColumnId ||
    left.level !== right.level ||
    left.partitionOrdinal !== right.partitionOrdinal ||
    left.logicalOrder !== right.logicalOrder
  ) {
    return false;
  }
  const leftColumnIds = Object.keys(left.columnBlockIds).sort();
  const rightColumnIds = Object.keys(right.columnBlockIds).sort();
  if (
    leftColumnIds.length !== rightColumnIds.length ||
    leftColumnIds.some((id, index) => id !== rightColumnIds[index])
  ) {
    return false;
  }
  return (
    leftColumnIds.every((columnId) => {
      const leftIds = left.columnBlockIds[columnId] ?? [];
      const rightIds = right.columnBlockIds[columnId] ?? [];
      return (
        leftIds.length === rightIds.length && leftIds.every((id, index) => id === rightIds[index])
      );
    }) && sameRowIdSpans(left.rowIdSpans, right.rowIdSpans)
  );
}

function sameRowIdSpans(
  left: readonly RowIdSpan[] | undefined,
  right: readonly RowIdSpan[] | undefined,
): boolean {
  if (left === undefined || right === undefined) return left === right;
  return (
    left.length === right.length &&
    left.every((span, index) => {
      const other = right[index];
      return (
        span.rowStart === other?.rowStart &&
        span.rowCount === other.rowCount &&
        span.rowIdStart === other.rowIdStart
      );
    })
  );
}

function sameMergeSourceSegment(
  actual: SegmentRecord,
  owner: { status: string; committedVersion: number | null } | undefined,
  planned: MergeCompactionSourceSegment,
): boolean {
  if (
    owner?.status !== "committed" ||
    owner.committedVersion !== planned.committedVersion ||
    actual.id !== planned.segmentId ||
    actual.transactionId !== planned.transactionId ||
    actual.kind !== planned.kind ||
    (actual.keyColumnId ?? planned.keyColumnId) !== planned.keyColumnId ||
    actual.level !== planned.level ||
    actual.logicalOrder !== planned.logicalOrder ||
    actual.rowCount !== planned.rowCount ||
    actual.rowIdStart !== planned.rowIdStart ||
    actual.rowIdEndExclusive !== planned.rowIdEndExclusive
  ) {
    return false;
  }
  let spans: RowIdSpan[];
  try {
    spans = mergeSourceRowIdSpans(actual, planned.kind);
  } catch {
    return false;
  }
  if (!sameRowIdSpans(spans, planned.rowIdSpans)) return false;
  const actualColumnIds = new Set(Object.keys(actual.columnBlockIds));
  if (
    actualColumnIds.size !== planned.columns.length ||
    planned.columns.some((column) => !actualColumnIds.has(column.columnId))
  ) {
    return false;
  }
  return planned.columns.every((column) => {
    const actualIds = actual.columnBlockIds[column.columnId] ?? [];
    return (
      actualIds.length === column.sourceBlocks.length &&
      actualIds.every((id, index) => id === column.sourceBlocks[index]?.blockId)
    );
  });
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function hasContiguousRowIds(segments: readonly SegmentRecord[]): boolean {
  return segments.every((segment, index) => {
    if (segment.rowIdEndExclusive - segment.rowIdStart !== BigInt(segment.rowCount)) return false;
    const previous = segments[index - 1];
    return previous === undefined || previous.rowIdEndExclusive === segment.rowIdStart;
  });
}

function validLogicalOrder(value: number | undefined): value is number {
  return value !== undefined && Number.isFinite(value) && value >= 0;
}

interface AppendLevelTwoLayout {
  retainedPrefix: readonly SegmentRecord[];
  levelTwoSegments: readonly SegmentRecord[];
  level0Segments: readonly SegmentRecord[];
}

function appendLevelTwoLayout(segments: readonly SegmentRecord[]): AppendLevelTwoLayout | null {
  const levelOneSegments = levelOnePartitionPrefix(segments);
  if (
    levelOneSegments === null ||
    levelOneSegments.some((segment) => segment.kind !== "insert" || segment.rowIdSpans.length !== 0)
  ) {
    return null;
  }
  let index = levelOneSegments.length;
  const retainedPrefix: SegmentRecord[] = [];
  const levelTwoSegments: SegmentRecord[] = [];
  retainedPrefix.push(...levelOneSegments);
  for (;;) {
    const segment = segments[index];
    if (segment?.level !== 2) break;
    if (
      segment.kind !== "insert" ||
      segment.rowIdSpans.length !== 0 ||
      segment.partitionOrdinal !== levelTwoSegments.length ||
      !validLogicalOrder(segment.logicalOrder) ||
      segment.rowIdEndExclusive - segment.rowIdStart !== BigInt(segment.rowCount)
    ) {
      return null;
    }
    retainedPrefix.push(segment);
    levelTwoSegments.push(segment);
    index += 1;
  }
  const level0Segments = segments.slice(index);
  if (
    level0Segments.some(
      (segment) =>
        segment.level !== 0 ||
        segment.partitionOrdinal !== undefined ||
        segment.kind !== "insert" ||
        segment.rowIdSpans.length !== 0 ||
        !validLogicalOrder(segment.logicalOrder),
    )
  ) {
    return null;
  }
  const rowIdIntervals = segments
    .map((segment) => ({
      start: segment.rowIdStart,
      end: segment.rowIdEndExclusive,
      expectedEnd: segment.rowIdStart + BigInt(segment.rowCount),
    }))
    .sort((left, right) => (left.start < right.start ? -1 : left.start > right.start ? 1 : 0));
  for (const [intervalIndex, interval] of rowIdIntervals.entries()) {
    if (interval.start <= 0n || interval.end !== interval.expectedEnd) return null;
    const previous = rowIdIntervals[intervalIndex - 1];
    if (previous !== undefined && interval.start < previous.end) return null;
  }
  return { retainedPrefix, levelTwoSegments, level0Segments };
}

interface KeyedLevelOneLayout {
  /** The level-one partitions, in visible order: each a merged base or an append-shaped insert. */
  partitions: readonly SegmentRecord[];
  level0Segments: readonly SegmentRecord[];
}

/**
 * Validates a keyed table's visible history for a partitioned level-one fold: a prefix of
 * level-one partitions — merged bases carrying row-ID spans, or append-shaped inserts — each
 * with an explicit logical order, strictly increasing along the prefix; then level-zero
 * segments of any mutation kind. Every row footprint must be pairwise disjoint. Returns null
 * when the shape does not hold so the planner skips explicitly.
 */
function keyedLevelOneLayout(segments: readonly SegmentRecord[]): KeyedLevelOneLayout | null {
  const partitions = levelOnePartitionPrefix(segments);
  if (partitions === null) return null;
  const level0Segments = segments.slice(partitions.length);
  if (
    level0Segments.some((segment) => segment.level !== 0 || segment.partitionOrdinal !== undefined)
  ) {
    return null;
  }
  if (!disjointRowIdFootprints(segments)) return null;
  return { partitions, level0Segments };
}

/** The append-only counterpart: bounded L1 partitions followed by contiguous insert deltas. */
function keylessLevelOneLayout(segments: readonly SegmentRecord[]): KeyedLevelOneLayout | null {
  const partitions = levelOnePartitionPrefix(segments);
  if (partitions === null || partitions.some((segment) => segment.kind !== "insert")) {
    return null;
  }
  const level0Segments = segments.slice(partitions.length);
  if (
    level0Segments.some(
      (segment) =>
        segment.level !== 0 ||
        segment.partitionOrdinal !== undefined ||
        segment.kind !== "insert" ||
        segment.rowIdSpans.length !== 0,
    ) ||
    !hasContiguousRowIds(segments)
  ) {
    return null;
  }
  return { partitions, level0Segments };
}

/**
 * The leading level-one segments, when they form a valid partition prefix: insert or base
 * kinds, no L2 ordinal, and explicit strictly increasing logical orders. Null otherwise.
 */
function levelOnePartitionPrefix(segments: readonly SegmentRecord[]): SegmentRecord[] | null {
  const partitions: SegmentRecord[] = [];
  for (const segment of segments) {
    if (segment.level !== 1) break;
    const kind = segment.kind;
    const previousOrder = partitions[partitions.length - 1]?.logicalOrder ?? -1;
    if (
      (kind !== "insert" && kind !== "base") ||
      segment.partitionOrdinal !== undefined ||
      !validLogicalOrder(segment.logicalOrder) ||
      segment.logicalOrder <= previousOrder
    ) {
      return null;
    }
    partitions.push(segment);
  }
  return partitions;
}

/**
 * Whether the segments' row footprints — spans where present, otherwise the contiguous
 * interval — are positive and pairwise disjoint. Update and delete deltas carry no footprint.
 */
function disjointRowIdFootprints(segments: readonly SegmentRecord[]): boolean {
  const intervals: Array<{ start: bigint; end: bigint }> = [];
  for (const segment of segments) {
    if (segment.rowIdSpans.length !== 0) {
      for (const span of segment.rowIdSpans) {
        intervals.push({ start: span.rowIdStart, end: span.rowIdStart + BigInt(span.rowCount) });
      }
      continue;
    }
    if (segment.rowIdEndExclusive <= segment.rowIdStart) continue;
    if (segment.rowIdEndExclusive - segment.rowIdStart !== BigInt(segment.rowCount)) return false;
    intervals.push({ start: segment.rowIdStart, end: segment.rowIdEndExclusive });
  }
  intervals.sort((left, right) =>
    left.start < right.start ? -1 : left.start > right.start ? 1 : 0,
  );
  for (const [intervalIndex, interval] of intervals.entries()) {
    if (interval.start <= 0n) return false;
    const previous = intervals[intervalIndex - 1];
    if (previous !== undefined && interval.start < previous.end) return false;
  }
  return true;
}

interface KeyedLevelTwoLayout {
  levelTwoSegments: readonly SegmentRecord[];
  /** The level-one partitions a promotion folds along with the level-zero prefix. */
  anchors: readonly SegmentRecord[];
  level0Segments: readonly SegmentRecord[];
}

/**
 * Validates a keyed table's visible history for multi-range L2 promotion: existing partitions
 * (append-shaped inserts or merged bases carrying row-ID spans) with ordinals exactly 0..N-1,
 * then the level-one partitions, then level-zero segments of any mutation kind. Every row
 * footprint — a partition's spans or interval, the anchors', and each level-zero insert/upsert
 * interval — must be pairwise disjoint; update and delete deltas carry no footprint. Returns
 * null when the shape does not hold so the planner skips explicitly.
 */
function keyedLevelTwoLayout(segments: readonly SegmentRecord[]): KeyedLevelTwoLayout | null {
  let index = 0;
  const levelTwoSegments: SegmentRecord[] = [];
  for (;;) {
    const segment = segments[index];
    if (segment?.level !== 2) break;
    const kind = segment.kind;
    if (
      segment.partitionOrdinal !== levelTwoSegments.length ||
      !validLogicalOrder(segment.logicalOrder) ||
      (kind !== "insert" && kind !== "base") ||
      (kind === "insert" && segment.rowIdSpans.length !== 0) ||
      (kind === "base" && segment.rowIdSpans.length === 0)
    ) {
      return null;
    }
    levelTwoSegments.push(segment);
    index += 1;
  }
  const anchors = levelOnePartitionPrefix(segments.slice(index));
  if (anchors === null) return null;
  index += anchors.length;
  const level0Segments = segments.slice(index);
  if (
    level0Segments.some((segment) => segment.level !== 0 || segment.partitionOrdinal !== undefined)
  ) {
    return null;
  }
  if (!disjointRowIdFootprints(segments)) return null;
  return { levelTwoSegments, anchors, level0Segments };
}

function compactionWriteAmplificationSkipped(input: {
  tableName: string;
  sourceSegments: readonly SegmentRecord[];
  sourceBlockIds: readonly string[];
  sourceStoredBytes: number;
  level0SourceStoredBytes: number;
  outputPartitionOrdinal: number;
  maxWriteAmplification: number;
  maximumOutputStoredBytes: number;
  plannedOutputStoredBytesUpperBound: number;
  priorAttemptOutputStoredBytes: number;
  targetBlockBytes: number;
  outputCompression: Compression;
  memoryBudgetBytes: number;
  minimumMemoryBytes: number;
  version: number;
}): CompactTableResult {
  return {
    tableName: input.tableName,
    compacted: false,
    skipReason: "write-amplification-budget",
    sourceSegmentCount: input.sourceSegments.length,
    sourceBlockCount: input.sourceBlockIds.length,
    outputSegmentId: null,
    outputBlockCount: 0,
    rowCount: input.sourceSegments.reduce((total, segment) => total + segment.rowCount, 0),
    sourceStoredBytes: input.sourceStoredBytes,
    outputStoredBytes: 0,
    level0SourceStoredBytes: input.level0SourceStoredBytes,
    anchorSourceStoredBytes: 0,
    outputPartitionOrdinal: input.outputPartitionOrdinal,
    maxWriteAmplification: input.maxWriteAmplification,
    maximumOutputStoredBytes: input.maximumOutputStoredBytes,
    plannedOutputStoredBytesUpperBound: input.plannedOutputStoredBytesUpperBound,
    priorAttemptOutputStoredBytes: input.priorAttemptOutputStoredBytes,
    lifetimeOutputStoredBytes: input.priorAttemptOutputStoredBytes,
    targetBlockBytes: input.targetBlockBytes,
    outputCompression: input.outputCompression,
    memoryBudgetBytes: input.memoryBudgetBytes,
    minimumMemoryBytes: input.minimumMemoryBytes,
    peakWorkingBytes: 0,
    supersededBlockCount: 0,
    physicallyReclaimedBytes: 0,
    version: input.version,
    metrics: null,
  };
}

function compactTableSkipped(
  tableName: string,
  skipReason: CompactionSkipReason,
  sourceSegments: readonly SegmentRecord[],
  sourceBlockIds: readonly string[],
  version: number | null,
): CompactTableResult {
  return {
    tableName,
    compacted: false,
    skipReason,
    sourceSegmentCount: sourceSegments.length,
    sourceBlockCount: sourceBlockIds.length,
    outputSegmentId: null,
    outputBlockCount: 0,
    rowCount: sourceSegments.reduce((total, segment) => total + segment.rowCount, 0),
    sourceStoredBytes: 0,
    outputStoredBytes: 0,
    supersededBlockCount: 0,
    physicallyReclaimedBytes: 0,
    version,
    metrics: null,
  };
}

function writeColumnValues(type: LogicalType, values: readonly BatchValue[]): WriteColumnValues {
  const cached = type === "string" ? validatedStringByteLengths.get(values) : undefined;
  return {
    type,
    values,
    ...(cached?.length === values.length ? { stringByteLengths: cached } : {}),
  };
}

/** Conservative complete stored-byte bound used to flush an accumulator before encoding. */
function maximumWriteBlockStoredBytes(
  column: WriteColumnValues,
  start: number,
  end: number,
  compression: Compression,
): number {
  let stringBytes = 0;
  if (column.type === "string") {
    for (let index = start; index < end; index += 1) {
      const value = column.values[index];
      if (value === null) continue;
      if (typeof value !== "string") throw new TypeError("String column contains a non-string");
      stringBytes += column.stringByteLengths?.[index] ?? wellFormedUtf8ByteLength(value);
    }
  }
  const physicalBytes = physicalColumnByteLength(column.type, end - start, stringBytes);
  const storedPayloadBytes =
    compression === "gzip"
      ? Math.max(physicalBytes, getCompressionMemoryBound("gzip", physicalBytes).maximumOutputBytes)
      : physicalBytes;
  return Math.min(
    MAX_STORED_BLOCK_BYTE_LENGTH,
    BLOCK_HEADER_LENGTH + MAX_BLOCK_METADATA_BYTE_LENGTH + storedPayloadBytes,
  );
}

function cacheableQueryInput(sql: string, params: readonly QueryValue[]): boolean {
  let characters = sql.length;
  if (characters > MAX_CACHEABLE_TEXT_CHARACTERS) return false;
  for (const value of params) {
    if (typeof value !== "string") continue;
    characters += value.length;
    if (characters > MAX_CACHEABLE_TEXT_CHARACTERS) return false;
  }
  return true;
}

async function filterSnapshotSegments(
  snapshot: Snapshot,
  segments: readonly SegmentRecord[],
): Promise<SegmentRecord[]> {
  const blockIds = [
    ...new Set(segments.flatMap((segment) => Object.values(segment.columnBlockIds).flat())),
  ];
  const membership = await snapshot.hasBlocks(blockIds);
  const visibleBlockIds = new Set(blockIds.filter((_blockId, index) => membership[index] === true));
  return segments.filter((segment) =>
    Object.values(segment.columnBlockIds)
      .flat()
      .every((blockId) => visibleBlockIds.has(blockId)),
  );
}

async function firstMissingSnapshotBlock(
  snapshot: Snapshot,
  blockIds: readonly string[],
): Promise<string | undefined> {
  const membership = await snapshot.hasBlocks(blockIds);
  return blockIds.find((_blockId, index) => membership[index] !== true);
}

function createWriteMetrics(input: {
  logicalBytes: number;
  storedBytes: number;
  encodeMs: number;
  stageMs: number;
  commitMs: number;
  totalMs: number;
  retries: number;
  rows: number;
}): WriteMetrics {
  return {
    logicalBytes: input.logicalBytes,
    storedBytes: input.storedBytes,
    writeAmplification: input.logicalBytes === 0 ? 0 : input.storedBytes / input.logicalBytes,
    encodeMs: input.encodeMs,
    stageMs: input.stageMs,
    commitMs: input.commitMs,
    totalMs: input.totalMs,
    retries: input.retries,
    rowsPerSecond: input.rows / Math.max(input.totalMs / 1_000, 0.000_001),
  };
}

function asColumnInput(type: LogicalType, values: readonly BatchValue[]): ColumnInput {
  switch (type) {
    case "boolean":
      return { type, values: values as ReadonlyArray<boolean | null> };
    case "number":
      return { type, values: values as ReadonlyArray<number | null> };
    case "string":
      return { type, values: values as ReadonlyArray<string | null> };
    case "datetime":
      return { type, values: values as ReadonlyArray<Date | null> };
  }
}
